window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["EZR"]={"book":"EZR","editions":{"hbo-source":[[1,1,"וּ⁠בִ⁠שְׁנַ֣ת אַחַ֗ת לְ⁠כ֨וֹרֶשׁ֙ מֶ֣לֶךְ פָּרַ֔ס לִ⁠כְל֥וֹת דְּבַר־יְהוָ֖ה מִ⁠פִּ֣י יִרְמְיָ֑ה הֵעִ֣יר יְהוָ֗ה אֶת־ר֨וּחַ֙ כֹּ֣רֶשׁ מֶֽלֶךְ־פָּרַ֔ס וַ⁠יַּֽעֲבֶר־קוֹל֙ בְּ⁠כָל־מַלְכוּת֔⁠וֹ וְ⁠גַם־בְּ⁠מִכְתָּ֖ב לֵ⁠אמֹֽר׃","ẇ⁠bi⁠şĕ̌na֣ţ ʼaẖa֗ţ lĕ⁠k֨wòreş̌֙ me֣lekĕ pá̇ra֔s li⁠kĕl֥wòţ dĕ̇bar-yĕhwá֖h mi⁠pi֣̇y yirĕmĕyá֑h héʻi֣yr yĕhwá֗h ʼeţ-r֨ẇẖa֙ kò֣̇reş̌ meֽlekĕ-pá̇ra֔s wa⁠yȧֽʻàber-qwòl֙ bĕ̇⁠kál-malĕkẇţ֔⁠wò wĕ⁠gam-bĕ̇⁠mikĕţá֖̇b lé⁠ʼmòֽr׃"],[1,2,"כֹּ֣ה אָמַ֗ר כֹּ֚רֶשׁ מֶ֣לֶךְ פָּרַ֔ס כֹּ֚ל מַמְלְכ֣וֹת הָ⁠אָ֔רֶץ נָ֣תַן לִ֔⁠י יְהוָ֖ה אֱלֹהֵ֣י הַ⁠שָּׁמָ֑יִם וְ⁠הֽוּא־פָקַ֤ד עָלַ⁠י֙ לִ⁠בְנֽוֹת־ל֣⁠וֹ בַ֔יִת בִּ⁠ירוּשָׁלִַ֖ם אֲשֶׁ֥ר בִּֽ⁠יהוּדָֽה׃","kò֣̇h ʼáma֗r kò֚̇reş̌ me֣lekĕ pá̇ra֔s kò֚̇l mamĕlĕk֣wòţ há⁠ʼá֔reẕ ná֣ţan li֔⁠y yĕhwá֖h ʼèlòhé֣y ha⁠şá̇̌má֑yim wĕ⁠hֽẇʼ-páqa֤d ʻála⁠y֙ li⁠bĕnֽwòţ-l֣⁠wò ba֔yiţ bi̇⁠yrẇşá̌lia֖m ʼàşě֥r biֽ̇⁠yhẇdáֽh׃"],[1,3,"מִֽי־בָ⁠כֶ֣ם מִ⁠כָּל־עַמּ֗⁠וֹ יְהִ֤י אֱלֹהָי⁠ו֙ עִמּ֔⁠וֹ וְ⁠יַ֕עַל לִ⁠ירוּשָׁלִַ֖ם אֲשֶׁ֣ר בִּ⁠יהוּדָ֑ה וְ⁠יִ֗בֶן אֶת־בֵּ֤ית יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל ה֥וּא הָ⁠אֱלֹהִ֖ים אֲשֶׁ֥ר בִּ⁠ירוּשָׁלִָֽם׃","miֽy-bá⁠ke֣m mi⁠ká̇l-ʻaṁ֗⁠wò yĕhi֤y ʼèlòháy⁠w֙ ʻiṁ֔⁠wò wĕ⁠ya֕ʻal li⁠yrẇşá̌lia֖m ʼàşě֣r bi̇⁠yhẇdá֑h wĕ⁠yi֗ben ʼeţ-bé֤̇yţ yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l h֥ẇʼ há⁠ʼèlòhi֖ym ʼàşě֥r bi̇⁠yrẇşá̌liáֽm׃"],[1,4,"וְ⁠כָל־הַ⁠נִּשְׁאָ֗ר מִֽ⁠כָּל־הַ⁠מְּקֹמוֹת֮ אֲשֶׁ֣ר ה֣וּא גָֽר־שָׁם֒ יְנַשְּׂא֨וּ⁠הוּ֙ אַנְשֵׁ֣י מְקֹמ֔⁠וֹ בְּ⁠כֶ֥סֶף וּ⁠בְ⁠זָהָ֖ב וּ⁠בִ⁠רְכ֣וּשׁ וּ⁠בִ⁠בְהֵמָ֑ה עִם־הַ֨⁠נְּדָבָ֔ה לְ⁠בֵ֥ית הָ⁠אֱלֹהִ֖ים אֲשֶׁ֥ר בִּ⁠ירוּשָׁלִָֽם׃","wĕ⁠kál-ha⁠ni̇şĕ̌ʼá֗r miֽ⁠ká̇l-ha⁠mĕ̇qòmwòţ֮ ʼàşě֣r h֣ẇʼ gáֽr-şá̌m֒ yĕnaşĕ̇̂ʼ֨ẇ⁠hẇ֙ ʼanĕşé֣̌y mĕqòm֔⁠wò bĕ̇⁠ke֥sep ẇ⁠bĕ⁠záhá֖b ẇ⁠bi⁠rĕk֣ẇş̌ ẇ⁠bi⁠bĕhémá֑h ʻim-ha֨⁠nĕ̇dábá֔h lĕ⁠bé֥yţ há⁠ʼèlòhi֖ym ʼàşě֥r bi̇⁠yrẇşá̌liáֽm׃"],[1,5,"וַ⁠יָּק֜וּמוּ רָאשֵׁ֣י הָ⁠אָב֗וֹת לִֽ⁠יהוּדָה֙ וּ⁠בִנְיָמִ֔ן וְ⁠הַ⁠כֹּהֲנִ֖ים וְ⁠הַ⁠לְוִיִּ֑ם לְ⁠כֹ֨ל הֵעִ֤יר הָ⁠אֱלֹהִים֙ אֶת־רוּח֔⁠וֹ לַ⁠עֲל֣וֹת לִ⁠בְנ֔וֹת אֶת־בֵּ֥ית יְהוָ֖ה אֲשֶׁ֥ר בִּ⁠ירוּשָׁלִָֽם׃","wa⁠yá̇q֜ẇmẇ ráʼşé֣̌y há⁠ʼáb֗wòţ liֽ⁠yhẇdáh֙ ẇ⁠binĕyámi֔n wĕ⁠ha⁠kò̇hàni֖ym wĕ⁠ha⁠lĕwiyi֑̇m lĕ⁠kò֨l héʻi֤yr há⁠ʼèlòhiym֙ ʼeţ-rẇẖ֔⁠wò la⁠ʻàl֣wòţ li⁠bĕn֔wòţ ʼeţ-bé֥̇yţ yĕhwá֖h ʼàşě֥r bi̇⁠yrẇşá̌liáֽm׃"],[1,6,"וְ⁠כָל־סְבִיבֹֽתֵי⁠הֶם֙ חִזְּק֣וּ בִֽ⁠ידֵי⁠הֶ֔ם בִּ⁠כְלֵי־כֶ֧סֶף בַּ⁠זָּהָ֛ב בָּ⁠רְכ֥וּשׁ וּ⁠בַ⁠בְּהֵמָ֖ה וּ⁠בַ⁠מִּגְדָּנ֑וֹת לְ⁠בַ֖ד עַל־כָּל־הִתְנַדֵּֽב׃ס","wĕ⁠kál-sĕbiybòֽţéy⁠hem֙ ẖizĕ̇q֣ẇ biֽ⁠ydéy⁠he֔m bi̇⁠kĕléy-ke֧sep bȧ⁠zá̇há֛b bá̇⁠rĕk֥ẇş̌ ẇ⁠ba⁠bĕ̇hémá֖h ẇ⁠ba⁠mi̇gĕdá̇n֑wòţ lĕ⁠ba֖d ʻal-ká̇l-hiţĕnadéֽ̇b׃s"],[1,7,"וְ⁠הַ⁠מֶּ֣לֶךְ כּ֔וֹרֶשׁ הוֹצִ֖יא אֶת־כְּלֵ֣י בֵית־יְהוָ֑ה אֲשֶׁ֨ר הוֹצִ֤יא נְבֽוּכַדְנֶצַּר֙ מִ⁠יר֣וּשָׁלִַ֔ם וַֽ⁠יִּתְּנֵ֖⁠ם בְּ⁠בֵ֥ית אֱלֹהָֽי⁠ו׃","wĕ⁠ha⁠mė֣lekĕ k̇֔wòreş̌ hwòẕi֖yʼ ʼeţ-kĕ̇lé֣y béyţ-yĕhwá֑h ʼàşě֨r hwòẕi֤yʼ nĕbֽẇkadĕneẕȧr֙ mi⁠yr֣ẇşá̌lia֔m waֽ⁠yi̇ţĕ̇né֖⁠m bĕ̇⁠bé֥yţ ʼèlòháֽy⁠w׃"],[1,8,"וַ⁠יּֽוֹצִיאֵ֗⁠ם כּ֚וֹרֶשׁ מֶ֣לֶךְ פָּרַ֔ס עַל־יַ֖ד מִתְרְדָ֣ת הַ⁠גִּזְבָּ֑ר וַֽ⁠יִּסְפְּרֵ⁠ם֙ לְ⁠שֵׁשְׁבַּצַּ֔ר הַ⁠נָּשִׂ֖יא לִ⁠יהוּדָֽה׃","wa⁠ẏֽwòẕiyʼé֗⁠m k֚̇wòreş̌ me֣lekĕ pá̇ra֔s ʻal-ya֖d miţĕrĕdá֣ţ ha⁠gi̇zĕbá֑̇r waֽ⁠yi̇sĕpĕ̇ré⁠m֙ lĕ⁠şé̌şĕ̌bȧẕȧ֔r ha⁠ná̇şî֖yʼ li⁠yhẇdáֽh׃"],[1,9,"וְ⁠אֵ֖לֶּה מִסְפָּרָ֑⁠ם אֲגַרְטְלֵ֨י זָהָ֜ב שְׁלֹשִׁ֗ים אֲגַרְטְלֵי־כֶ֨סֶף֙ אָ֔לֶף מַחֲלָפִ֖ים תִּשְׁעָ֥ה וְ⁠עֶשְׂרִֽים׃ס","wĕ⁠ʼé֖lėh misĕpá̇rá֑⁠m ʼàgarĕtĕlé֨y záhá֜b şĕ̌lòşǐ֗ym ʼàgarĕtĕléy-ke֨sep֙ ʼá֔lep maẖàlápi֖ym ţi̇şĕ̌ʻá֥h wĕ⁠ʻeşĕ̂riֽym׃s"],[1,10,"כְּפוֹרֵ֤י זָהָב֙ שְׁלֹשִׁ֔ים כְּפ֤וֹרֵי כֶ֨סֶף֙ מִשְׁנִ֔ים אַרְבַּ֥ע מֵא֖וֹת וַ⁠עֲשָׂרָ֑ה כֵּלִ֥ים אֲחֵרִ֖ים אָֽלֶף׃ס","kĕ̇pwòré֤y záháb֙ şĕ̌lòşǐ֔ym kĕ̇p֤wòréy ke֨sep֙ mişĕ̌ni֔ym ʼarĕbȧ֥ʻ méʼ֖wòţ wa⁠ʻàşá̂rá֑h ké̇li֥ym ʼàẖéri֖ym ʼáֽlep׃s"],[1,11,"כָּל־כֵּלִים֙ לַ⁠זָּהָ֣ב וְ⁠לַ⁠כֶּ֔סֶף חֲמֵ֥שֶׁת אֲלָפִ֖ים וְ⁠אַרְבַּ֣ע מֵא֑וֹת הַ⁠כֹּ֞ל הֶעֱלָ֣ה שֵׁשְׁבַּצַּ֗ר עִ֚ם הֵעָל֣וֹת הַ⁠גּוֹלָ֔ה מִ⁠בָּבֶ֖ל לִ⁠ירוּשָׁלִָֽם׃פ","ká̇l-ké̇liym֙ la⁠zá̇há֣b wĕ⁠la⁠kė֔sep ẖàmé֥şěţ ʼàlápi֖ym wĕ⁠ʼarĕbȧ֣ʻ méʼ֑wòţ ha⁠kò̇֞l heʻèlá֣h şé̌şĕ̌bȧẕȧ֗r ʻi֚m héʻál֣wòţ ha⁠ġwòlá֔h mi⁠bá̇be֖l li⁠yrẇşá̌liáֽm׃p"],[2,1,"וְ⁠אֵ֣לֶּה ׀ בְּנֵ֣י הַ⁠מְּדִינָ֗ה הָֽ⁠עֹלִים֙ מִ⁠שְּׁבִ֣י הַ⁠גּוֹלָ֔ה אֲשֶׁ֥ר הֶגְלָ֛ה נבוכדנצור מֶֽלֶךְ־בָּבֶ֖ל לְ⁠בָבֶ֑ל וַ⁠יָּשׁ֛וּבוּ לִ⁠ירוּשָׁלִַ֥ם וִֽ⁠יהוּדָ֖ה אִ֥ישׁ לְ⁠עִירֽ⁠וֹ׃","wĕ⁠ʼé֣lėh ׀ bĕ̇né֣y ha⁠mĕ̇diyná֗h háֽ⁠ʻòliym֙ mi⁠şĕ̇̌bi֣y ha⁠ġwòlá֔h ʼàşě֥r hegĕlá֛h nbwkdnẕwr meֽlekĕ-bá̇be֖l lĕ⁠bábe֑l wa⁠yá̇ş֛̌ẇbẇ li⁠yrẇşá̌lia֥m wiֽ⁠yhẇdá֖h ʼi֥yş̌ lĕ⁠ʻiyrֽ⁠wò׃"],[2,2,"אֲשֶׁר־בָּ֣אוּ עִם־זְרֻבָּבֶ֗ל יֵשׁ֡וּעַ נְ֠חֶמְיָה שְׂרָיָ֨ה רְֽעֵלָיָ֜ה מָרְדֳּכַ֥י בִּלְשָׁ֛ן מִסְפָּ֥ר בִּגְוַ֖י רְח֣וּם בַּעֲנָ֑ה מִסְפַּ֕ר אַנְשֵׁ֖י עַ֥ם יִשְׂרָאֵֽל׃ס","ʼàşěr-bá֣̇ʼẇ ʻim-zĕrubá̇be֗l yéş̌֡ẇʻa nĕ֠ẖemĕyáh şĕ̂ráyá֨h rĕֽʻéláyá֜h márĕdȯka֥y bi̇lĕşá֛̌n misĕpá֥̇r bi̇gĕwa֖y rĕẖ֣ẇm bȧʻàná֑h misĕpȧ֕r ʼanĕşé֖̌y ʻa֥m yişĕ̂ráʼéֽl׃s"],[2,3,"בְּנֵ֣י פַרְעֹ֔שׁ אַלְפַּ֕יִם מֵאָ֖ה שִׁבְעִ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇né֣y parĕʻò֔ş̌ ʼalĕpȧ֕yim méʼá֖h şǐbĕʻi֥ym ẇ⁠şĕ̌náֽyim׃s"],[2,4,"בְּנֵ֣י שְׁפַטְיָ֔ה שְׁלֹ֥שׁ מֵא֖וֹת שִׁבְעִ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇né֣y şĕ̌patĕyá֔h şĕ̌lò֥ş̌ méʼ֖wòţ şǐbĕʻi֥ym ẇ⁠şĕ̌náֽyim׃s"],[2,5,"בְּנֵ֣י אָרַ֔ח שְׁבַ֥ע מֵא֖וֹת חֲמִשָּׁ֥ה וְ⁠שִׁבְעִֽים׃ס","bĕ̇né֣y ʼára֔ẖ şĕ̌ba֥ʻ méʼ֖wòţ ẖàmişá֥̇̌h wĕ⁠şǐbĕʻiֽym׃s"],[2,6,"בְּנֵֽי־פַחַ֥ת מוֹאָ֛ב לִ⁠בְנֵ֥י יֵשׁ֖וּעַ יוֹאָ֑ב אַלְפַּ֕יִם שְׁמֹנֶ֥ה מֵא֖וֹת וּ⁠שְׁנֵ֥ים עָשָֽׂר׃ס","bĕ̇néֽy-paẖa֥ţ mwòʼá֛b li⁠bĕné֥y yéş֖̌ẇʻa ywòʼá֑b ʼalĕpȧ֕yim şĕ̌mòne֥h méʼ֖wòţ ẇ⁠şĕ̌né֥ym ʻáşáֽ̂r׃s"],[2,7,"בְּנֵ֣י עֵילָ֔ם אֶ֕לֶף מָאתַ֖יִם חֲמִשִּׁ֥ים וְ⁠אַרְבָּעָֽה׃ס","bĕ̇né֣y ʻéylá֔m ʼe֕lep máʼţa֖yim ẖàmişi֥̇̌ym wĕ⁠ʼarĕbá̇ʻáֽh׃s"],[2,8,"בְּנֵ֣י זַתּ֔וּא תְּשַׁ֥ע מֵא֖וֹת וְ⁠אַרְבָּעִ֥ים וַ⁠חֲמִשָּֽׁה׃ס","bĕ̇né֣y zaţ̇֔ẇʼ ţĕ̇şǎ֥ʻ méʼ֖wòţ wĕ⁠ʼarĕbá̇ʻi֥ym wa⁠ẖàmişáֽ̇̌h׃s"],[2,9,"בְּנֵ֣י זַכָּ֔י שְׁבַ֥ע מֵא֖וֹת וְ⁠שִׁשִּֽׁים׃ס","bĕ̇né֣y zaká̇֔y şĕ̌ba֥ʻ méʼ֖wòţ wĕ⁠şǐşiֽ̇̌ym׃s"],[2,10,"בְּנֵ֣י בָנִ֔י שֵׁ֥שׁ מֵא֖וֹת אַרְבָּעִ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇né֣y báni֔y şé֥̌ş̌ méʼ֖wòţ ʼarĕbá̇ʻi֥ym ẇ⁠şĕ̌náֽyim׃s"],[2,11,"בְּנֵ֣י בֵבָ֔י שֵׁ֥שׁ מֵא֖וֹת עֶשְׂרִ֥ים וּ⁠שְׁלֹשָֽׁה׃ס","bĕ̇né֣y bébá֔y şé֥̌ş̌ méʼ֖wòţ ʻeşĕ̂ri֥ym ẇ⁠şĕ̌lòşáֽ̌h׃s"],[2,12,"בְּנֵ֣י עַזְגָּ֔ד אֶ֕לֶף מָאתַ֖יִם עֶשְׂרִ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇né֣y ʻazĕgá̇֔d ʼe֕lep máʼţa֖yim ʻeşĕ̂ri֥ym ẇ⁠şĕ̌náֽyim׃s"],[2,13,"בְּנֵי֙ אֲדֹ֣נִיקָ֔ם שֵׁ֥שׁ מֵא֖וֹת שִׁשִּׁ֥ים וְ⁠שִׁשָּֽׁה׃ס","bĕ̇néy֙ ʼàdò֣niyqá֔m şé֥̌ş̌ méʼ֖wòţ şǐşi֥̇̌ym wĕ⁠şǐşáֽ̇̌h׃s"],[2,14,"בְּנֵ֣י בִגְוָ֔י אַלְפַּ֖יִם חֲמִשִּׁ֥ים וְ⁠שִׁשָּֽׁה׃ס","bĕ̇né֣y bigĕwá֔y ʼalĕpȧ֖yim ẖàmişi֥̇̌ym wĕ⁠şǐşáֽ̇̌h׃s"],[2,15,"בְּנֵ֣י עָדִ֔ין אַרְבַּ֥ע מֵא֖וֹת חֲמִשִּׁ֥ים וְ⁠אַרְבָּעָֽה׃ס","bĕ̇né֣y ʻádi֔yn ʼarĕbȧ֥ʻ méʼ֖wòţ ẖàmişi֥̇̌ym wĕ⁠ʼarĕbá̇ʻáֽh׃s"],[2,16,"בְּנֵֽי־אָטֵ֥ר לִֽ⁠יחִזְקִיָּ֖ה תִּשְׁעִ֥ים וּ⁠שְׁמֹנָֽה׃ס","bĕ̇néֽy-ʼáté֥r liֽ⁠yẖizĕqiyá֖̇h ţi̇şĕ̌ʻi֥ym ẇ⁠şĕ̌mònáֽh׃s"],[2,17,"בְּנֵ֣י בֵצָ֔י שְׁלֹ֥שׁ מֵא֖וֹת עֶשְׂרִ֥ים וּ⁠שְׁלֹשָֽׁה׃ס","bĕ̇né֣y béẕá֔y şĕ̌lò֥ş̌ méʼ֖wòţ ʻeşĕ̂ri֥ym ẇ⁠şĕ̌lòşáֽ̌h׃s"],[2,18,"בְּנֵ֣י יוֹרָ֔ה מֵאָ֖ה וּ⁠שְׁנֵ֥ים עָשָֽׂר׃ס","bĕ̇né֣y ywòrá֔h méʼá֖h ẇ⁠şĕ̌né֥ym ʻáşáֽ̂r׃s"],[2,19,"בְּנֵ֣י חָשֻׁ֔ם מָאתַ֖יִם עֶשְׂרִ֥ים וּ⁠שְׁלֹשָֽׁה׃ס","bĕ̇né֣y ẖáşǔ֔m máʼţa֖yim ʻeşĕ̂ri֥ym ẇ⁠şĕ̌lòşáֽ̌h׃s"],[2,20,"בְּנֵ֥י גִבָּ֖ר תִּשְׁעִ֥ים וַ⁠חֲמִשָּֽׁה׃ס","bĕ̇né֥y gibá֖̇r ţi̇şĕ̌ʻi֥ym wa⁠ẖàmişáֽ̇̌h׃s"],[2,21,"בְּנֵ֣י בֵֽית־לָ֔חֶם מֵאָ֖ה עֶשְׂרִ֥ים וּ⁠שְׁלֹשָֽׁה׃ס","bĕ̇né֣y béֽyţ-lá֔ẖem méʼá֖h ʻeşĕ̂ri֥ym ẇ⁠şĕ̌lòşáֽ̌h׃s"],[2,22,"אַנְשֵׁ֥י נְטֹפָ֖ה חֲמִשִּׁ֥ים וְ⁠שִׁשָּֽׁה׃","ʼanĕşé֥̌y nĕtòpá֖h ẖàmişi֥̇̌ym wĕ⁠şǐşáֽ̇̌h׃"],[2,23,"אַנְשֵׁ֣י עֲנָת֔וֹת מֵאָ֖ה עֶשְׂרִ֥ים וּ⁠שְׁמֹנָֽה׃ס","ʼanĕşé֣̌y ʻànáţ֔wòţ méʼá֖h ʻeşĕ̂ri֥ym ẇ⁠şĕ̌mònáֽh׃s"],[2,24,"בְּנֵ֥י עַזְמָ֖וֶת אַרְבָּעִ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇né֥y ʻazĕmá֖weţ ʼarĕbá̇ʻi֥ym ẇ⁠şĕ̌náֽyim׃s"],[2,25,"בְּנֵ֨י קִרְיַ֤ת עָרִים֙ כְּפִירָ֣ה וּ⁠בְאֵר֔וֹת שְׁבַ֥ע מֵא֖וֹת וְ⁠אַרְבָּעִ֥ים וּ⁠שְׁלֹשָֽׁה׃ס","bĕ̇né֨y qirĕya֤ţ ʻáriym֙ kĕ̇piyrá֣h ẇ⁠bĕʼér֔wòţ şĕ̌ba֥ʻ méʼ֖wòţ wĕ⁠ʼarĕbá̇ʻi֥ym ẇ⁠şĕ̌lòşáֽ̌h׃s"],[2,26,"בְּנֵ֤י הָ⁠רָמָה֙ וָ⁠גָ֔בַע שֵׁ֥שׁ מֵא֖וֹת עֶשְׂרִ֥ים וְ⁠אֶחָֽד׃ס","bĕ̇né֤y há⁠rámáh֙ wá⁠gá֔baʻ şé֥̌ş̌ méʼ֖wòţ ʻeşĕ̂ri֥ym wĕ⁠ʼeẖáֽd׃s"],[2,27,"אַנְשֵׁ֣י מִכְמָ֔ס מֵאָ֖ה עֶשְׂרִ֥ים וּ⁠שְׁנָֽיִם׃ס","ʼanĕşé֣̌y mikĕmá֔s méʼá֖h ʻeşĕ̂ri֥ym ẇ⁠şĕ̌náֽyim׃s"],[2,28,"אַנְשֵׁ֤י בֵֽית־אֵל֙ וְ⁠הָ⁠עָ֔י מָאתַ֖יִם עֶשְׂרִ֥ים וּ⁠שְׁלֹשָֽׁה׃ס","ʼanĕşé֤̌y béֽyţ-ʼél֙ wĕ⁠há⁠ʻá֔y máʼţa֖yim ʻeşĕ̂ri֥ym ẇ⁠şĕ̌lòşáֽ̌h׃s"],[2,29,"בְּנֵ֥י נְב֖וֹ חֲמִשִּׁ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇né֥y nĕb֖wò ẖàmişi֥̇̌ym ẇ⁠şĕ̌náֽyim׃s"],[2,30,"בְּנֵ֣י מַגְבִּ֔ישׁ מֵאָ֖ה חֲמִשִּׁ֥ים וְ⁠שִׁשָּֽׁה׃ס","bĕ̇né֣y magĕbi̇֔yş̌ méʼá֖h ẖàmişi֥̇̌ym wĕ⁠şǐşáֽ̇̌h׃s"],[2,31,"בְּנֵי֙ עֵילָ֣ם אַחֵ֔ר אֶ֕לֶף מָאתַ֖יִם חֲמִשִּׁ֥ים וְ⁠אַרְבָּעָֽה׃ס","bĕ̇néy֙ ʻéylá֣m ʼaẖé֔r ʼe֕lep máʼţa֖yim ẖàmişi֥̇̌ym wĕ⁠ʼarĕbá̇ʻáֽh׃s"],[2,32,"בְּנֵ֣י חָרִ֔ם שְׁלֹ֥שׁ מֵא֖וֹת וְ⁠עֶשְׂרִֽים׃ס","bĕ̇né֣y ẖári֔m şĕ̌lò֥ş̌ méʼ֖wòţ wĕ⁠ʻeşĕ̂riֽym׃s"],[2,33,"בְּנֵי־לֹד֙ חָדִ֣יד וְ⁠אוֹנ֔וֹ שְׁבַ֥ע מֵא֖וֹת עֶשְׂרִ֥ים וַ⁠חֲמִשָּֽׁה׃ס","bĕ̇néy-lòd֙ ẖádi֣yd wĕ⁠ʼwòn֔wò şĕ̌ba֥ʻ méʼ֖wòţ ʻeşĕ̂ri֥ym wa⁠ẖàmişáֽ̇̌h׃s"],[2,34,"בְּנֵ֣י יְרֵח֔וֹ שְׁלֹ֥שׁ מֵא֖וֹת אַרְבָּעִ֥ים וַ⁠חֲמִשָּֽׁה׃ס","bĕ̇né֣y yĕréẖ֔wò şĕ̌lò֥ş̌ méʼ֖wòţ ʼarĕbá̇ʻi֥ym wa⁠ẖàmişáֽ̇̌h׃s"],[2,35,"בְּנֵ֣י סְנָאָ֔ה שְׁלֹ֣שֶׁת אֲלָפִ֔ים וְ⁠שֵׁ֥שׁ מֵא֖וֹת וּ⁠שְׁלֹשִֽׁים׃ס","bĕ̇né֣y sĕnáʼá֔h şĕ̌lò֣şěţ ʼàlápi֔ym wĕ⁠şé֥̌ş̌ méʼ֖wòţ ẇ⁠şĕ̌lòşǐֽym׃s"],[2,36,"הַֽ⁠כֹּהֲנִ֑ים בְּנֵ֤י יְדַֽעְיָה֙ לְ⁠בֵ֣ית יֵשׁ֔וּעַ תְּשַׁ֥ע מֵא֖וֹת שִׁבְעִ֥ים וּ⁠שְׁלֹשָֽׁה׃ס","haֽ⁠kò̇hàni֑ym bĕ̇né֤y yĕdaֽʻĕyáh֙ lĕ⁠bé֣yţ yéş̌֔ẇʻa ţĕ̇şǎ֥ʻ méʼ֖wòţ şǐbĕʻi֥ym ẇ⁠şĕ̌lòşáֽ̌h׃s"],[2,37,"בְּנֵ֣י אִמֵּ֔ר אֶ֖לֶף חֲמִשִּׁ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇né֣y ʼimé̇֔r ʼe֖lep ẖàmişi֥̇̌ym ẇ⁠şĕ̌náֽyim׃s"],[2,38,"בְּנֵ֣י פַשְׁח֔וּר אֶ֕לֶף מָאתַ֖יִם אַרְבָּעִ֥ים וְ⁠שִׁבְעָֽה׃ס","bĕ̇né֣y paşĕ̌ẖ֔ẇr ʼe֕lep máʼţa֖yim ʼarĕbá̇ʻi֥ym wĕ⁠şǐbĕʻáֽh׃s"],[2,39,"בְּנֵ֣י חָרִ֔ם אֶ֖לֶף וְ⁠שִׁבְעָ֥ה עָשָֽׂר׃ס","bĕ̇né֣y ẖári֔m ʼe֖lep wĕ⁠şǐbĕʻá֥h ʻáşáֽ̂r׃s"],[2,40,"הַ⁠לְוִיִּ֑ם בְּנֵי־יֵשׁ֧וּעַ וְ⁠קַדְמִיאֵ֛ל לִ⁠בְנֵ֥י הוֹדַוְיָ֖ה שִׁבְעִ֥ים וְ⁠אַרְבָּעָֽה׃ס","ha⁠lĕwiyi֑̇m bĕ̇néy-yéş֧̌ẇʻa wĕ⁠qadĕmiyʼé֛l li⁠bĕné֥y hwòdawĕyá֖h şǐbĕʻi֥ym wĕ⁠ʼarĕbá̇ʻáֽh׃s"],[2,41,"הַֽ⁠מְשֹׁרְרִ֑ים בְּנֵ֣י אָסָ֔ף מֵאָ֖ה עֶשְׂרִ֥ים וּ⁠שְׁמֹנָֽה׃פ","haֽ⁠mĕşò̌rĕri֑ym bĕ̇né֣y ʼásá֔p méʼá֖h ʻeşĕ̂ri֥ym ẇ⁠şĕ̌mònáֽh׃p"],[2,42,"בְּנֵ֣י הַ⁠שֹּֽׁעֲרִ֗ים בְּנֵי־שַׁלּ֤וּם בְּנֵֽי־אָטֵר֙ בְּנֵי־טַלְמ֣וֹן בְּנֵי־עַקּ֔וּב בְּנֵ֥י חֲטִיטָ֖א בְּנֵ֣י שֹׁבָ֑י הַ⁠כֹּ֕ל מֵאָ֖ה שְׁלֹשִׁ֥ים וְ⁠תִשְׁעָֽה׃פ","bĕ̇né֣y ha⁠şòֽ̇̌ʻàri֗ym bĕ̇néy-şǎl֤̇ẇm bĕ̇néֽy-ʼátér֙ bĕ̇néy-talĕm֣wòn bĕ̇néy-ʻaq̇֔ẇb bĕ̇né֥y ẖàtiytá֖ʼ bĕ̇né֣y şò̌bá֑y ha⁠kò̇֕l méʼá֖h şĕ̌lòşǐ֥ym wĕ⁠ţişĕ̌ʻáֽh׃p"],[2,43,"הַ⁠נְּתִינִ֑ים בְּנֵי־צִיחָ֥א בְנֵי־חֲשׂוּפָ֖א בְּנֵ֥י טַבָּעֽוֹת׃","ha⁠nĕ̇ţiyni֑ym bĕ̇néy-ẕiyẖá֥ʼ bĕnéy-ẖàş̂ẇpá֖ʼ bĕ̇né֥y tabá̇ʻֽwòţ׃"],[2,44,"בְּנֵי־קֵרֹ֥ס בְּֽנֵי־סִֽיעֲהָ֖א בְּנֵ֥י פָדֽוֹן׃","bĕ̇néy-qérò֥s bĕֽ̇néy-siֽyʻàhá֖ʼ bĕ̇né֥y pádֽwòn׃"],[2,45,"בְּנֵי־לְבָנָ֥ה בְנֵי־חֲגָבָ֖ה בְּנֵ֥י עַקּֽוּב׃","bĕ̇néy-lĕbáná֥h bĕnéy-ẖàgábá֖h bĕ̇né֥y ʻaqֽ̇ẇb׃"],[2,46,"בְּנֵי־חָגָ֥ב בְּנֵי־שמלי בְּנֵ֥י חָנָֽן׃","bĕ̇néy-ẖágá֥b bĕ̇néy-şmly bĕ̇né֥y ẖánáֽn׃"],[2,47,"בְּנֵי־גִדֵּ֥ל בְּנֵי־גַ֖חַר בְּנֵ֥י רְאָיָֽה׃","bĕ̇néy-gidé֥̇l bĕ̇néy-ga֖ẖar bĕ̇né֥y rĕʼáyáֽh׃"],[2,48,"בְּנֵי־רְצִ֥ין בְּנֵי־נְקוֹדָ֖א בְּנֵ֥י גַזָּֽם׃","bĕ̇néy-rĕẕi֥yn bĕ̇néy-nĕqwòdá֖ʼ bĕ̇né֥y gazáֽ̇m׃"],[2,49,"בְּנֵי־עֻזָּ֥א בְנֵי־פָסֵ֖חַ בְּנֵ֥י בֵסָֽי׃","bĕ̇néy-ʻuzá֥̇ʼ bĕnéy-pásé֖ẖa bĕ̇né֥y bésáֽy׃"],[2,50,"בְּנֵי־אַסְנָ֥ה בְנֵי־מעינים בְּנֵ֥י נפיסים׃","bĕ̇néy-ʼasĕná֥h bĕnéy-mʻynym bĕ̇né֥y npysym׃"],[2,51,"בְּנֵי־בַקְבּ֥וּק בְּנֵי־חֲקוּפָ֖א בְּנֵ֥י חַרְחֽוּר׃","bĕ̇néy-baqĕḃ֥ẇq bĕ̇néy-ẖàqẇpá֖ʼ bĕ̇né֥y ẖarĕẖֽẇr׃"],[2,52,"בְּנֵי־בַצְל֥וּת בְּנֵי־מְחִידָ֖א בְּנֵ֥י חַרְשָֽׁא׃","bĕ̇néy-baẕĕl֥ẇţ bĕ̇néy-mĕẖiydá֖ʼ bĕ̇né֥y ẖarĕşáֽ̌ʼ׃"],[2,53,"בְּנֵי־בַרְק֥וֹס בְּֽנֵי־סִֽיסְרָ֖א בְּנֵי־תָֽמַח׃","bĕ̇néy-barĕq֥wòs bĕֽ̇néy-siֽysĕrá֖ʼ bĕ̇néy-ţáֽmaẖ׃"],[2,54,"בְּנֵ֥י נְצִ֖יחַ בְּנֵ֥י חֲטִיפָֽא׃","bĕ̇né֥y nĕẕi֖yẖa bĕ̇né֥y ẖàtiypáֽʼ׃"],[2,55,"בְּנֵ֖י עַבְדֵ֣י שְׁלֹמֹ֑ה בְּנֵי־סֹטַ֥י בְּנֵי־הַ⁠סֹּפֶ֖רֶת בְּנֵ֥י פְרוּדָֽא׃","bĕ̇né֖y ʻabĕdé֣y şĕ̌lòmò֑h bĕ̇néy-sòta֥y bĕ̇néy-ha⁠sò̇pe֖reţ bĕ̇né֥y pĕrẇdáֽʼ׃"],[2,56,"בְּנֵי־יַעְלָ֥ה בְנֵי־דַרְק֖וֹן בְּנֵ֥י גִדֵּֽל׃","bĕ̇néy-yaʻĕlá֥h bĕnéy-darĕq֖wòn bĕ̇né֥y gidéֽ̇l׃"],[2,57,"בְּנֵ֧י שְׁפַטְיָ֣ה בְנֵֽי־חַטִּ֗יל בְּנֵ֛י פֹּכֶ֥רֶת הַצְּבָיִ֖ים בְּנֵ֥י אָמִֽי׃","bĕ̇né֧y şĕ̌patĕyá֣h bĕnéֽy-ẖati̇֗yl bĕ̇né֛y pò̇ke֥reţ haẕĕ̇báyi֖ym bĕ̇né֥y ʼámiֽy׃"],[2,58,"כָּ֨ל־הַ⁠נְּתִינִ֔ים וּ⁠בְנֵ֖י עַבְדֵ֣י שְׁלֹמֹ֑ה שְׁלֹ֥שׁ מֵא֖וֹת תִּשְׁעִ֥ים וּ⁠שְׁנָֽיִם׃ס","ká̇֨l-ha⁠nĕ̇ţiyni֔ym ẇ⁠bĕné֖y ʻabĕdé֣y şĕ̌lòmò֑h şĕ̌lò֥ş̌ méʼ֖wòţ ţi̇şĕ̌ʻi֥ym ẇ⁠şĕ̌náֽyim׃s"],[2,59,"וְ⁠אֵ֗לֶּה הָֽ⁠עֹלִים֙ מִ⁠תֵּ֥ל מֶ֨לַח֙ תֵּ֣ל חַרְשָׁ֔א כְּר֥וּב אַדָּ֖ן אִמֵּ֑ר וְ⁠לֹ֣א יָֽכְל֗וּ לְ⁠הַגִּ֤יד בֵּית־אֲבוֹתָ⁠ם֙ וְ⁠זַרְעָ֔⁠ם אִ֥ם מִ⁠יִּשְׂרָאֵ֖ל הֵֽם׃","wĕ⁠ʼé֗lėh háֽ⁠ʻòliym֙ mi⁠ţé֥̇l me֨laẖ֙ ţé֣̇l ẖarĕşá̌֔ʼ kĕ̇r֥ẇb ʼadá֖̇n ʼimé֑̇r wĕ⁠lò֣ʼ yáֽkĕl֗ẇ lĕ⁠hagi֤̇yd bé̇yţ-ʼàbwòţá⁠m֙ wĕ⁠zarĕʻá֔⁠m ʼi֥m mi⁠yi̇şĕ̂ráʼé֖l héֽm׃"],[2,60,"בְּנֵי־דְלָיָ֥ה בְנֵי־טוֹבִיָּ֖ה בְּנֵ֣י נְקוֹדָ֑א שֵׁ֥שׁ מֵא֖וֹת חֲמִשִּׁ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇néy-dĕláyá֥h bĕnéy-twòbiyá֖̇h bĕ̇né֣y nĕqwòdá֑ʼ şé֥̌ş̌ méʼ֖wòţ ẖàmişi֥̇̌ym ẇ⁠şĕ̌náֽyim׃s"],[2,61,"וּ⁠מִ⁠בְּנֵי֙ הַ⁠כֹּ֣הֲנִ֔ים בְּנֵ֥י חֳבַיָּ֖ה בְּנֵ֣י הַקּ֑וֹץ בְּנֵ֣י בַרְזִלַּ֗י אֲשֶׁ֣ר לָ֠קַח מִ⁠בְּנ֞וֹת בַּרְזִלַּ֤י הַ⁠גִּלְעָדִי֙ אִשָּׁ֔ה וַ⁠יִּקָּרֵ֖א עַל־שְׁמָֽ⁠ם׃","ẇ⁠mi⁠bĕ̇néy֙ ha⁠kò֣̇hàni֔ym bĕ̇né֥y ẖobayá֖̇h bĕ̇né֣y haq֑̇wòẕ bĕ̇né֣y barĕzilȧ֗y ʼàşě֣r lá֠qaẖ mi⁠bĕ̇n֞wòţ bȧrĕzilȧ֤y ha⁠gi̇lĕʻádiy֙ ʼişá̇̌֔h wa⁠yi̇qá̇ré֖ʼ ʻal-şĕ̌máֽ⁠m׃"],[2,62,"אֵ֗לֶּה בִּקְשׁ֧וּ כְתָבָ֛⁠ם הַ⁠מִּתְיַחְשִׂ֖ים וְ⁠לֹ֣א נִמְצָ֑אוּ וַֽ⁠יְגֹאֲל֖וּ מִן־הַ⁠כְּהֻנָּֽה׃","ʼé֗lėh bi̇qĕş֧̌ẇ kĕţábá֛⁠m ha⁠mi̇ţĕyaẖĕşî֖ym wĕ⁠lò֣ʼ nimĕẕá֑ʼẇ waֽ⁠yĕgòʼàl֖ẇ min-ha⁠kĕ̇hunáֽ̇h׃"],[2,63,"וַ⁠יֹּ֤אמֶר הַ⁠תִּרְשָׁ֨תָא֙ לָ⁠הֶ֔ם אֲשֶׁ֥ר לֹא־יֹאכְל֖וּ מִ⁠קֹּ֣דֶשׁ הַ⁠קֳּדָשִׁ֑ים עַ֛ד עֲמֹ֥ד כֹּהֵ֖ן לְ⁠אוּרִ֥ים וּ⁠לְ⁠תֻמִּֽים׃","wa⁠yò֤̇ʼmer ha⁠ţi̇rĕşá̌֨ţáʼ֙ lá⁠he֔m ʼàşě֥r lòʼ-yòʼkĕl֖ẇ mi⁠qò֣̇deş̌ ha⁠qȯdáşǐ֑ym ʻa֛d ʻàmò֥d kò̇hé֖n lĕ⁠ʼẇri֥ym ẇ⁠lĕ⁠ţumiֽ̇ym׃"],[2,64,"כָּל־הַ⁠קָּהָ֖ל כְּ⁠אֶחָ֑ד אַרְבַּ֣ע רִבּ֔וֹא אַלְפַּ֖יִם שְׁלֹשׁ־מֵא֥וֹת שִׁשִּֽׁים׃","ká̇l-ha⁠qá̇há֖l kĕ̇⁠ʼeẖá֑d ʼarĕbȧ֣ʻ riḃ֔wòʼ ʼalĕpȧ֖yim şĕ̌lòş̌-méʼ֥wòţ şǐşiֽ̇̌ym׃"],[2,65,"מִ֠⁠לְּ⁠בַד עַבְדֵי⁠הֶ֤ם וְ⁠אַמְהֹֽתֵי⁠הֶם֙ אֵ֔לֶּה שִׁבְעַ֣ת אֲלָפִ֔ים שְׁלֹ֥שׁ מֵא֖וֹת שְׁלֹשִׁ֣ים וְ⁠שִׁבְעָ֑ה וְ⁠לָ⁠הֶ֛ם מְשֹׁרְרִ֥ים וּֽ⁠מְשֹׁרְר֖וֹת מָאתָֽיִם׃","mi֠⁠lĕ̇⁠bad ʻabĕdéy⁠he֤m wĕ⁠ʼamĕhòֽţéy⁠hem֙ ʼé֔lėh şǐbĕʻa֣ţ ʼàlápi֔ym şĕ̌lò֥ş̌ méʼ֖wòţ şĕ̌lòşǐ֣ym wĕ⁠şǐbĕʻá֑h wĕ⁠lá⁠he֛m mĕşò̌rĕri֥ym ẇֽ⁠mĕşò̌rĕr֖wòţ máʼţáֽyim׃"],[2,66,"סוּסֵי⁠הֶ֕ם שְׁבַ֥ע מֵא֖וֹת שְׁלֹשִׁ֣ים וְ⁠שִׁשָּׁ֑ה פִּרְדֵי⁠הֶ֕ם מָאתַ֖יִם אַרְבָּעִ֥ים וַ⁠חֲמִשָּֽׁה׃","sẇséy⁠he֕m şĕ̌ba֥ʻ méʼ֖wòţ şĕ̌lòşǐ֣ym wĕ⁠şǐşá֑̇̌h pi̇rĕdéy⁠he֕m máʼţa֖yim ʼarĕbá̇ʻi֥ym wa⁠ẖàmişáֽ̇̌h׃"],[2,67,"גְּמַ֨לֵּי⁠הֶ֔ם אַרְבַּ֥ע מֵא֖וֹת שְׁלֹשִׁ֣ים וַ⁠חֲמִשָּׁ֑ה חֲמֹרִ֕ים שֵׁ֣שֶׁת אֲלָפִ֔ים שְׁבַ֥ע מֵא֖וֹת וְ⁠עֶשְׂרִֽים׃פ","gĕ̇ma֨lé̇y⁠he֔m ʼarĕbȧ֥ʻ méʼ֖wòţ şĕ̌lòşǐ֣ym wa⁠ẖàmişá֑̇̌h ẖàmòri֕ym şé֣̌şěţ ʼàlápi֔ym şĕ̌ba֥ʻ méʼ֖wòţ wĕ⁠ʻeşĕ̂riֽym׃p"],[2,68,"וּ⁠מֵ⁠רָאשֵׁי֙ הָֽ⁠אָב֔וֹת בְּ⁠בוֹאָ֕⁠ם לְ⁠בֵ֥ית יְהוָ֖ה אֲשֶׁ֣ר בִּ⁠ירוּשָׁלִָ֑ם הִֽתְנַדְּבוּ֙ לְ⁠בֵ֣ית הָֽ⁠אֱלֹהִ֔ים לְ⁠הַעֲמִיד֖⁠וֹ עַל־מְכוֹנֽ⁠וֹ׃","ẇ⁠mé⁠ráʼşé̌y֙ háֽ⁠ʼáb֔wòţ bĕ̇⁠bwòʼá֕⁠m lĕ⁠bé֥yţ yĕhwá֖h ʼàşě֣r bi̇⁠yrẇşá̌liá֑m hiֽţĕnadĕ̇bẇ֙ lĕ⁠bé֣yţ háֽ⁠ʼèlòhi֔ym lĕ⁠haʻàmiyd֖⁠wò ʻal-mĕkwònֽ⁠wò׃"],[2,69,"כְּ⁠כֹחָ֗⁠ם נָתְנוּ֮ לְ⁠אוֹצַ֣ר הַ⁠מְּלָאכָה֒ זָהָ֗ב דַּרְכְּמוֹנִים֙ שֵׁשׁ־רִבֹּ֣אות וָ⁠אֶ֔לֶף ס וְ⁠כֶ֕סֶף מָנִ֖ים חֲמֵ֣שֶׁת אֲלָפִ֑ים וְ⁠כָתְנֹ֥ת כֹּהֲנִ֖ים מֵאָֽה׃ס","kĕ̇⁠kòẖá֗⁠m náţĕnẇ֮ lĕ⁠ʼwòẕa֣r ha⁠mĕ̇láʼkáh֒ záhá֗b dȧrĕkĕ̇mwòniym֙ şé̌ş̌-ribò֣̇ʼwţ wá⁠ʼe֔lep s wĕ⁠ke֕sep máni֖ym ẖàmé֣şěţ ʼàlápi֑ym wĕ⁠káţĕnò֥ţ kò̇hàni֖ym méʼáֽh׃s"],[2,70,"וַ⁠יֵּשְׁב֣וּ הַ⁠כֹּהֲנִ֣ים וְ֠⁠הַ⁠לְוִיִּם וּֽ⁠מִן־הָ⁠עָ֞ם וְ⁠הַ⁠מְשֹׁרְרִ֧ים וְ⁠הַ⁠שּׁוֹעֲרִ֛ים וְ⁠הַ⁠נְּתִינִ֖ים בְּ⁠עָרֵי⁠הֶ֑ם וְ⁠כָל־יִשְׂרָאֵ֖ל בְּ⁠עָרֵי⁠הֶֽם׃ס","wa⁠yé̇şĕ̌b֣ẇ ha⁠kò̇hàni֣ym wĕ֠⁠ha⁠lĕwiyi̇m ẇֽ⁠min-há⁠ʻá֞m wĕ⁠ha⁠mĕşò̌rĕri֧ym wĕ⁠ha⁠ş̇̌wòʻàri֛ym wĕ⁠ha⁠nĕ̇ţiyni֖ym bĕ̇⁠ʻáréy⁠he֑m wĕ⁠kál-yişĕ̂ráʼé֖l bĕ̇⁠ʻáréy⁠heֽm׃s"],[3,1,"וַ⁠יִּגַּע֙ הַ⁠חֹ֣דֶשׁ הַ⁠שְּׁבִיעִ֔י וּ⁠בְנֵ֥י יִשְׂרָאֵ֖ל בֶּ⁠עָרִ֑ים ס וַ⁠יֵּאָסְפ֥וּ הָ⁠עָ֛ם כְּ⁠אִ֥ישׁ אֶחָ֖ד אֶל־יְרוּשָׁלִָֽם׃ס","wa⁠yi̇gȧʻ֙ ha⁠ẖò֣deş̌ ha⁠şĕ̇̌biyʻi֔y ẇ⁠bĕné֥y yişĕ̂ráʼé֖l bė⁠ʻári֑ym s wa⁠yé̇ʼásĕp֥ẇ há⁠ʻá֛m kĕ̇⁠ʼi֥yş̌ ʼeẖá֖d ʼel-yĕrẇşá̌liáֽm׃s"],[3,2,"וַ⁠יָּקָם֩ יֵשׁ֨וּעַ בֶּן־יֽוֹצָדָ֜ק וְ⁠אֶחָ֣י⁠ו הַ⁠כֹּהֲנִ֗ים וּ⁠זְרֻבָּבֶ֤ל בֶּן־שְׁאַלְתִּיאֵל֙ וְ⁠אֶחָ֔י⁠ו וַ⁠יִּבְנ֕וּ אֶת־מִזְבַּ֖ח אֱלֹהֵ֣י יִשְׂרָאֵ֑ל לְ⁠הַעֲל֤וֹת עָלָי⁠ו֙ עֹל֔וֹת כַּ⁠כָּת֕וּב בְּ⁠תוֹרַ֖ת מֹשֶׁ֥ה אִישׁ־הָ⁠אֱלֹהִֽים׃","wa⁠yá̇qám֩ yéş̌֨ẇʻa bėn-yֽwòẕádá֜q wĕ⁠ʼeẖá֣y⁠w ha⁠kò̇hàni֗ym ẇ⁠zĕrubá̇be֤l bėn-şĕ̌ʼalĕţi̇yʼél֙ wĕ⁠ʼeẖá֔y⁠w wa⁠yi̇bĕn֕ẇ ʼeţ-mizĕbȧ֖ẖ ʼèlòhé֣y yişĕ̂ráʼé֑l lĕ⁠haʻàl֤wòţ ʻáláy⁠w֙ ʻòl֔wòţ kȧ⁠ká̇ţ֕ẇb bĕ̇⁠ţwòra֖ţ mòşě֥h ʼiyş̌-há⁠ʼèlòhiֽym׃"],[3,3,"וַ⁠יָּכִ֤ינוּ הַ⁠מִּזְבֵּ֨חַ֙ עַל־מְכ֣וֹנֹתָ֔י⁠ו כִּ֚י בְּ⁠אֵימָ֣ה עֲלֵי⁠הֶ֔ם מֵ⁠עַמֵּ֖י הָ⁠אֲרָצ֑וֹת ו⁠יעל עָלָ֤י⁠ו עֹלוֹת֙ לַֽ⁠יהוָ֔ה עֹל֖וֹת לַ⁠בֹּ֥קֶר וְ⁠לָ⁠עָֽרֶב׃","wa⁠yá̇ki֤ynẇ ha⁠mi̇zĕbé̇֨ẖa֙ ʻal-mĕk֣wònòţá֔y⁠w ki֚̇y bĕ̇⁠ʼéymá֣h ʻàléy⁠he֔m mé⁠ʻamé֖̇y há⁠ʼàráẕ֑wòţ w⁠yʻl ʻálá֤y⁠w ʻòlwòţ֙ laֽ⁠yhwá֔h ʻòl֖wòţ la⁠bò֥̇qer wĕ⁠lá⁠ʻáֽreb׃"],[3,4,"וַֽ⁠יַּעֲשׂ֛וּ אֶת־חַ֥ג הַ⁠סֻּכּ֖וֹת כַּ⁠כָּת֑וּב וְ⁠עֹלַ֨ת י֤וֹם בְּ⁠יוֹם֙ בְּ⁠מִסְפָּ֔ר כְּ⁠מִשְׁפַּ֖ט דְּבַר־י֥וֹם בְּ⁠יוֹמֽ⁠וֹ׃","wֽa⁠yȧʻàş֛̂ẇ ʼeţ-ẖa֥g ha⁠su̇k֖̇wòţ kȧ⁠ká̇ţ֑ẇb wĕ⁠ʻòla֨ţ y֤wòm bĕ̇⁠ywòm֙ bĕ̇⁠misĕpá̇֔r kĕ̇⁠mişĕ̌pȧ֖t dĕ̇bar-y֥wòm bĕ̇⁠ywòmֽ⁠wò׃"],[3,5,"וְ⁠אַחֲרֵי כֵ֞ן עֹלַ֤ת תָּמִיד֙ וְ⁠לֶ֣⁠חֳדָשִׁ֔ים וּ⁠לְ⁠כָל־מוֹעֲדֵ֥י יְהוָ֖ה הַ⁠מְקֻדָּשִׁ֑ים וּ⁠לְ⁠כֹ֛ל מִתְנַדֵּ֥ב נְדָבָ֖ה לַ⁠יהוָֽה׃","wĕ⁠ʼaẖàréy ké֞n ʻòla֤ţ ţá̇miyd֙ wĕ⁠le֣⁠ẖodáşǐ֔ym ẇ⁠lĕ⁠kál-mwòʻàdé֥y yĕhwá֖h ha⁠mĕqudá̇şǐ֑ym ẇ⁠lĕ⁠kò֛l miţĕnadé֥̇b nĕdábá֖h la⁠yhwáֽh׃"],[3,6,"מִ⁠יּ֤וֹם אֶחָד֙ לַ⁠חֹ֣דֶשׁ הַ⁠שְּׁבִיעִ֔י הֵחֵ֕לּוּ לְ⁠הַעֲל֥וֹת עֹל֖וֹת לַ⁠יהוָ֑ה וְ⁠הֵיכַ֥ל יְהוָ֖ה לֹ֥א יֻסָּֽד׃","mi⁠ẏ֤wòm ʼeẖád֙ la⁠ẖò֣deş̌ ha⁠şĕ̇̌biyʻi֔y héẖé֕l̇ẇ lĕ⁠haʻàl֥wòţ ʻòl֖wòţ la⁠yhwá֑h wĕ⁠héyka֥l yĕhwá֖h lò֥ʼ yusáֽ̇d׃"],[3,7,"וַ⁠יִּ֨תְּנוּ־כֶ֔סֶף לַ⁠חֹצְבִ֖ים וְ⁠לֶ⁠חָרָשִׁ֑ים וּ⁠מַאֲכָ֨ל וּ⁠מִשְׁתֶּ֜ה וָ⁠שֶׁ֗מֶן לַ⁠צִּֽדֹנִים֙ וְ⁠לַ⁠צֹּרִ֔ים לְ⁠הָבִיא֩ עֲצֵ֨י אֲרָזִ֤ים מִן־הַ⁠לְּבָנוֹן֙ אֶל־יָ֣ם יָפ֔וֹא כְּ⁠רִשְׁי֛וֹן כּ֥וֹרֶשׁ מֶֽלֶךְ־פָּרַ֖ס עֲלֵי⁠הֶֽם׃פ","wa⁠yi̇֨ţĕ̇nẇ-ke֔sep la⁠ẖòẕĕbi֖ym wĕ⁠le⁠ẖáráşǐ֑ym ẇ⁠maʼàká֨l ẇ⁠mişĕ̌ţė֜h wá⁠şě֗men la⁠ẕiֽ̇dòniym֙ wĕ⁠la⁠ẕò̇ri֔ym lĕ⁠hábiyʼ֩ ʻàẕé֨y ʼàrázi֤ym min-ha⁠lĕ̇bánwòn֙ ʼel-yá֣m yáp֔wòʼ kĕ̇⁠rişĕ̌y֛wòn k֥̇wòreş̌ meֽlekĕ-pá̇ra֖s ʻàléy⁠heֽm׃p"],[3,8,"וּ⁠בַ⁠שָּׁנָ֣ה הַ⁠שֵּׁנִ֗ית לְ⁠בוֹאָ֞⁠ם אֶל־בֵּ֤ית הָֽ⁠אֱלֹהִים֙ לִ⁠יר֣וּשָׁלִַ֔ם בַּ⁠חֹ֖דֶשׁ הַ⁠שֵּׁנִ֑י הֵחֵ֡לּוּ זְרֻבָּבֶ֣ל בֶּן־שְׁ֠אַלְתִּיאֵל וְ⁠יֵשׁ֨וּעַ בֶּן־יֽוֹצָדָ֜ק וּ⁠שְׁאָ֥ר אֲחֵי⁠הֶ֣ם ׀ הַ⁠כֹּהֲנִ֣ים וְ⁠הַ⁠לְוִיִּ֗ם וְ⁠כָל־הַ⁠בָּאִים֙ מֵ⁠הַ⁠שְּׁבִ֣י יְרֽוּשָׁלִַ֔ם וַ⁠יַּעֲמִ֣ידוּ אֶת־הַ⁠לְוִיִּ֗ם מִ⁠בֶּ֨ן עֶשְׂרִ֤ים שָׁנָה֙ וָ⁠מַ֔עְלָ⁠ה לְ⁠נַצֵּ֖חַ עַל־מְלֶ֥אכֶת בֵּית־יְהוָֽה׃פ","ẇ⁠ba⁠şá̇̌ná֣h ha⁠şé̇̌ni֗yţ lĕ⁠bwòʼá֞⁠m ʼel-bé֤̇yţ háֽ⁠ʼèlòhiym֙ li⁠yr֣ẇşá̌lia֔m bȧ⁠ẖò֖deş̌ ha⁠şé̇̌ni֑y héẖé֡l̇ẇ zĕrubá̇be֣l bėn-şĕ̌֠ʼalĕţi̇yʼél wĕ⁠yéş̌֨ẇʻa bėn-yֽwòẕádá֜q ẇ⁠şĕ̌ʼá֥r ʼàẖéy⁠he֣m ׀ ha⁠kò̇hàni֣ym wĕ⁠ha⁠lĕwiyi̇֗m wĕ⁠kál-ha⁠bá̇ʼiym֙ mé⁠ha⁠şĕ̇̌bi֣y yĕrֽẇşá̌lia֔m wa⁠yȧʻàmi֣ydẇ ʼeţ-ha⁠lĕwiyi̇֗m mi⁠bė֨n ʻeşĕ̂ri֤ym şá̌náh֙ wá⁠ma֔ʻĕlá⁠h lĕ⁠naẕé֖̇ẖa ʻal-mĕle֥ʼkeţ bé̇yţ-yĕhwáֽh׃p"],[3,9,"וַ⁠יַּעֲמֹ֣ד יֵשׁ֡וּעַ בָּנָ֣י⁠ו וְ֠⁠אֶחָי⁠ו קַדְמִיאֵ֨ל וּ⁠בָנָ֤י⁠ו בְּנֵֽי־יְהוּדָה֙ כְּ⁠אֶחָ֔ד לְ⁠נַצֵּ֛חַ עַל־עֹשֵׂ֥ה הַ⁠מְּלָאכָ֖ה בְּ⁠בֵ֣ית הָ⁠אֱלֹהִ֑ים ס בְּנֵי֙ חֵֽנָדָ֔ד בְּנֵי⁠הֶ֥ם וַ⁠אֲחֵי⁠הֶ֖ם הַ⁠לְוִיִּֽם׃","wa⁠yȧʻàmò֣d yéş̌֡ẇʻa bá̇ná֣y⁠w wĕ֠⁠ʼeẖáy⁠w qadĕmiyʼé֨l ẇ⁠báná֤y⁠w bĕ̇néֽy-yĕhẇdáh֙ kĕ̇⁠ʼeẖá֔d lĕ⁠naẕé֛̇ẖa ʻal-ʻòşé֥̂h ha⁠mĕ̇láʼká֖h bĕ̇⁠bé֣yţ há⁠ʼèlòhi֑ym s bĕ̇néy֙ ẖéֽnádá֔d bĕ̇néy⁠he֥m wa⁠ʼàẖéy⁠he֖m ha⁠lĕwiyiֽ̇m׃"],[3,10,"וְ⁠יִסְּד֥וּ הַ⁠בֹּנִ֖ים אֶת־הֵיכַ֣ל יְהוָ֑ה וַ⁠יַּעֲמִידוּ֩ הַ⁠כֹּהֲנִ֨ים מְלֻבָּשִׁ֜ים בַּ⁠חֲצֹֽצְר֗וֹת וְ⁠הַ⁠לְוִיִּ֤ם בְּנֵֽי־אָסָף֙ בַּֽ⁠מְצִלְתַּ֔יִם לְ⁠הַלֵּל֙ אֶת־יְהוָ֔ה עַל־יְדֵ֖י דָּוִ֥יד מֶֽלֶךְ־יִשְׂרָאֵֽל׃","wĕ⁠yisĕ̇d֥ẇ ha⁠bò̇ni֖ym ʼeţ-héyka֣l yĕhwá֑h wa⁠yȧʻàmiydẇ֩ ha⁠kò̇hàni֨ym mĕlubá̇şǐ֜ym bȧ⁠ẖàẕòֽẕĕr֗wòţ wĕ⁠ha⁠lĕwiyi֤̇m bĕ̇néֽy-ʼásáp֙ bȧֽ⁠mĕẕilĕţȧ֔yim lĕ⁠halé̇l֙ ʼeţ-yĕhwá֔h ʻal-yĕdé֖y dá̇wi֥yd meֽlekĕ-yişĕ̂ráʼéֽl׃"],[3,11,"וַֽ֠⁠יַּעֲנוּ בְּ⁠הַלֵּ֨ל וּ⁠בְ⁠הוֹדֹ֤ת לַֽ⁠יהוָה֙ כִּ֣י ט֔וֹב כִּֽי־לְ⁠עוֹלָ֥ם חַסְדּ֖⁠וֹ עַל־יִשְׂרָאֵ֑ל וְ⁠כָל־הָ⁠עָ֡ם הֵרִיעוּ֩ תְרוּעָ֨ה גְדוֹלָ֤ה בְ⁠הַלֵּל֙ לַֽ⁠יהוָ֔ה עַ֖ל הוּסַ֥ד בֵּית־יְהוָֽה׃ס","wֽa֠⁠yȧʻànẇ bĕ̇⁠halé̇֨l ẇ⁠bĕ⁠hwòdò֤ţ laֽ⁠yhwáh֙ ki֣̇y t֔wòb kiֽ̇y-lĕ⁠ʻwòlá֥m ẖasĕḋ֖⁠wò ʻal-yişĕ̂ráʼé֑l wĕ⁠kál-há⁠ʻá֡m hériyʻẇ֩ ţĕrẇʻá֨h gĕdwòlá֤h bĕ⁠halé̇l֙ laֽ⁠yhwá֔h ʻa֖l hẇsa֥d bé̇yţ-yĕhwáֽh׃s"],[3,12,"וְ⁠רַבִּ֡ים מֵ⁠הַ⁠כֹּהֲנִ֣ים וְ⁠הַ⁠לְוִיִּם֩ וְ⁠רָאשֵׁ֨י הָ⁠אָב֜וֹת הַ⁠זְּקֵנִ֗ים אֲשֶׁ֨ר רָא֜וּ אֶת־הַ⁠בַּ֤יִת הָֽ⁠רִאשׁוֹן֙ בְּ⁠יָסְד֔⁠וֹ זֶ֤ה הַ⁠בַּ֨יִת֙ בְּ⁠עֵ֣ינֵי⁠הֶ֔ם בֹּכִ֖ים בְּ⁠ק֣וֹל גָּד֑וֹל וְ⁠רַבִּ֛ים בִּ⁠תְרוּעָ֥ה בְ⁠שִׂמְחָ֖ה לְ⁠הָרִ֥ים קֽוֹל׃","wĕ⁠rabi̇֡ym mé⁠ha⁠kò̇hàni֣ym wĕ⁠ha⁠lĕwiyi̇m֩ wĕ⁠ráʼşé̌֨y há⁠ʼáb֜wòţ ha⁠zĕ̇qéni֗ym ʼàşě֨r ráʼ֜ẇ ʼeţ-ha⁠bȧ֤yiţ háֽ⁠riʼş̌wòn֙ bĕ̇⁠yásĕd֔⁠wò ze֤h ha⁠bȧ֨yiţ֙ bĕ̇⁠ʻé֣ynéy⁠he֔m bò̇ki֖ym bĕ̇⁠q֣wòl gá̇d֑wòl wĕ⁠rabi֛̇ym bi̇⁠ţĕrẇʻá֥h bĕ⁠şîmĕẖá֖h lĕ⁠hári֥ym qֽwòl׃"],[3,13,"וְ⁠אֵ֣ין הָ⁠עָ֗ם מַכִּירִים֙ ק֚וֹל תְּרוּעַ֣ת הַ⁠שִּׂמְחָ֔ה לְ⁠ק֖וֹל בְּכִ֣י הָ⁠עָ֑ם כִּ֣י הָ⁠עָ֗ם מְרִיעִים֙ תְּרוּעָ֣ה גְדוֹלָ֔ה וְ⁠הַ⁠קּ֥וֹל נִשְׁמַ֖ע עַד־לְ⁠מֵ⁠רָחֽוֹק׃פ","wĕ⁠ʼé֣yn há⁠ʻá֗m maki̇yriym֙ q֚wòl ţĕ̇rẇʻa֣ţ ha⁠şi̇̂mĕẖá֔h lĕ⁠q֖wòl bĕ̇ki֣y há⁠ʻá֑m ki֣̇y há⁠ʻá֗m mĕriyʻiym֙ ţĕ̇rẇʻá֣h gĕdwòlá֔h wĕ⁠ha⁠q֥̇wòl nişĕ̌ma֖ʻ ʻad-lĕ⁠mé⁠ráẖֽwòq׃p"],[4,1,"וַֽ⁠יִּשְׁמְע֔וּ צָרֵ֥י יְהוּדָ֖ה וּ⁠בִנְיָמִ֑ן כִּֽי־בְנֵ֤י הַ⁠גּוֹלָה֙ בּוֹנִ֣ים הֵיכָ֔ל לַ⁠יהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","waֽ⁠yi̇şĕ̌mĕʻ֔ẇ ẕáré֥y yĕhẇdá֖h ẇ⁠binĕyámi֑n kiֽ̇y-bĕné֤y ha⁠ġwòláh֙ ḃwòni֣ym héyká֔l la⁠yhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[4,2,"וַ⁠יִּגְּשׁ֨וּ אֶל־זְרֻבָּבֶ֜ל וְ⁠אֶל־רָאשֵׁ֣י הָֽ⁠אָב֗וֹת וַ⁠יֹּאמְר֤וּ לָ⁠הֶם֙ נִבְנֶ֣ה עִמָּ⁠כֶ֔ם כִּ֣י כָ⁠כֶ֔ם נִדְר֖וֹשׁ לֵֽ⁠אלֹהֵי⁠כֶ֑ם ו⁠לא ׀ אֲנַ֣חְנוּ זֹבְחִ֗ים מִ⁠ימֵי֙ אֵסַ֤ר חַדֹּן֙ מֶ֣לֶךְ אַשּׁ֔וּר הַ⁠מַּעֲלֶ֥ה אֹתָ֖⁠נוּ פֹּֽה׃","wa⁠yi̇gĕ̇ş̌֨ẇ ʼel-zĕrubá̇be֜l wĕ⁠ʼel-ráʼşé֣̌y hֽá⁠ʼáb֗wòţ wa⁠yò̇ʼmĕr֤ẇ lá⁠hem֙ nibĕne֣h ʻimá̇⁠ke֔m ki֣̇y ká⁠ke֔m nidĕr֖wòş̌ lֽé⁠ʼlòhéy⁠ke֑m w⁠lʼ ׀ ʼàna֣ẖĕnẇ zòbĕẖi֗ym mi⁠yméy֙ ʼésa֤r ẖadò̇n֙ me֣lekĕ ʼaş̇̌֔ẇr ha⁠mȧʻàle֥h ʼòţá֖⁠nẇ pòֽ̇h׃"],[4,3,"וַ⁠יֹּאמֶר֩ לָ⁠הֶ֨ם זְרֻבָּבֶ֜ל וְ⁠יֵשׁ֗וּעַ וּ⁠שְׁאָ֨ר רָאשֵׁ֤י הָֽ⁠אָבוֹת֙ לְ⁠יִשְׂרָאֵ֔ל לֹֽא־לָ֣⁠כֶם וָ⁠לָ֔⁠נוּ לִ⁠בְנ֥וֹת בַּ֖יִת לֵ⁠אלֹהֵ֑י⁠נוּ כִּי֩ אֲנַ֨חְנוּ יַ֜חַד נִבְנֶ֗ה לַֽ⁠יהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל כַּ⁠אֲשֶׁ֣ר צִוָּ֔⁠נוּ הַ⁠מֶּ֖לֶךְ כּ֥וֹרֶשׁ מֶֽלֶךְ־פָּרָֽס׃","wa⁠yò̇ʼmer֩ lá⁠he֨m zĕrubá̇be֜l wĕ⁠yéş̌֗ẇʻa ẇ⁠şĕ̌ʼá֨r ráʼşé֤̌y háֽ⁠ʼábwòţ֙ lĕ⁠yişĕ̂ráʼé֔l lòֽʼ-lá֣⁠kem wá⁠lá֔⁠nẇ li⁠bĕn֥wòţ bȧ֖yiţ lé⁠ʼlòhé֑y⁠nẇ ki̇y֩ ʼàna֨ẖĕnẇ ya֜ẖad nibĕne֗h laֽ⁠yhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l kȧ⁠ʼàşě֣r ẕiwá̇֔⁠nẇ ha⁠mė֖lekĕ k֥̇wòreş̌ meֽlekĕ-pá̇ráֽs׃"],[4,4,"וַ⁠יְהִי֙ עַם־הָ⁠אָ֔רֶץ מְרַפִּ֖ים יְדֵ֣י עַם־יְהוּדָ֑ה ו⁠מבלהים אוֹתָ֖⁠ם לִ⁠בְנֽוֹת׃","wa⁠yĕhiy֙ ʻam-há⁠ʼá֔reẕ mĕrapi֖̇ym yĕdé֣y ʻam-yĕhẇdá֑h w⁠mblhym ʼwòţá֖⁠m li⁠bĕnֽwòţ׃"],[4,5,"וְ⁠סֹכְרִ֧ים עֲלֵי⁠הֶ֛ם יוֹעֲצִ֖ים לְ⁠הָפֵ֣ר עֲצָתָ֑⁠ם כָּל־יְמֵ֗י כּ֚וֹרֶשׁ מֶ֣לֶךְ פָּרַ֔ס וְ⁠עַד־מַלְכ֖וּת דָּרְיָ֥וֶשׁ מֶֽלֶךְ־פָּרָֽס׃","wĕ⁠sòkĕri֧ym ʻàléy⁠he֛m ywòʻàẕi֖ym lĕ⁠hápé֣r ʻàẕáţá֑⁠m ká̇l-yĕmé֗y k֚̇wòreş̌ me֣lekĕ pá̇ra֔s wĕ⁠ʻad-malĕk֖ẇţ dá̇rĕyá֥weş̌ meֽlekĕ-pá̇ráֽs׃"],[4,6,"וּ⁠בְ⁠מַלְכוּת֙ אֲחַשְׁוֵר֔וֹשׁ בִּ⁠תְחִלַּ֖ת מַלְכוּת֑⁠וֹ כָּתְב֣וּ שִׂטְנָ֔ה עַל־יֹשְׁבֵ֥י יְהוּדָ֖ה וִ⁠ירוּשָׁלִָֽם׃ס","ẇ⁠bĕ⁠malĕkẇţ֙ ʼàẖaşĕ̌wér֔wòş̌ bi̇⁠ţĕẖilȧ֖ţ malĕkẇţ֑⁠wò ká̇ţĕb֣ẇ şîtĕná֔h ʻal-yòşĕ̌bé֥y yĕhẇdá֖h wi⁠yrẇşá̌liáֽm׃s"],[4,7,"וּ⁠בִ⁠ימֵ֣י אַרְתַּחְשַׁ֗שְׂתָּא כָּתַ֨ב בִּשְׁלָ֜ם מִתְרְדָ֤ת טָֽבְאֵל֙ וּ⁠שְׁאָ֣ר כנותו עַל־ארתחששתא מֶ֣לֶךְ פָּרָ֑ס וּ⁠כְתָב֙ הַֽ⁠נִּשְׁתְּוָ֔ן כָּת֥וּב אֲרָמִ֖ית וּ⁠מְתֻרְגָּ֥ם אֲרָמִֽית׃פ","ẇ⁠bi⁠ymé֣y ʼarĕţȧẖĕşǎ֗şĕ̂ţá̇ʼ ká̇ţa֨b bi̇şĕ̌lá֜m miţĕrĕdá֤ţ táֽbĕʼél֙ ẇ⁠şĕ̌ʼá֣r knwţw ʻal-ʼrţẖşşţʼ me֣lekĕ pá̇rá֑s ẇ⁠kĕţáb֙ haֽ⁠ni̇şĕ̌ţĕ̇wá֔n ká̇ţ֥ẇb ʼàrámi֖yţ ẇ⁠mĕţurĕgá֥̇m ʼàrámiֽyţ׃p"],[4,8,"רְח֣וּם בְּעֵל־טְעֵ֗ם וְ⁠שִׁמְשַׁי֙ סָֽפְרָ֔⁠א כְּתַ֛בוּ אִגְּרָ֥ה חֲדָ֖ה עַל־יְרוּשְׁלֶ֑ם לְ⁠אַרְתַּחְשַׁ֥שְׂתְּא מַלְכָּ֖⁠א כְּנֵֽמָא׃","rĕẖ֣ẇm bĕ̇ʻél-tĕʻé֗m wĕ⁠şǐmĕşǎy֙ sáֽpĕrá֔⁠ʼ kĕ̇ţa֛bẇ ʼigĕ̇rá֥h ẖàdá֖h ʻal-yĕrẇşĕ̌le֑m lĕ⁠ʼarĕţȧẖĕşǎ֥şĕ̂ţĕ̇ʼ malĕká֖̇⁠ʼ kĕ̇néֽmáʼ׃"],[4,9,"אֱדַ֜יִן רְח֣וּם בְּעֵל־טְעֵ֗ם וְ⁠שִׁמְשַׁי֙ סָֽפְרָ֔⁠א וּ⁠שְׁאָ֖ר כְּנָוָתְ⁠ה֑וֹן דִּ֠ינָיֵ⁠א וַ⁠אֲפַרְסַתְכָיֵ֞⁠א טַרְפְּלָיֵ֣⁠א אֲפָֽרְסָיֵ֗⁠א ארכוי בָבְלָיֵ⁠א֙ שֽׁוּשַׁנְכָיֵ֔⁠א ד⁠הוא עֵלְמָיֵֽ⁠א׃","ʼèda֜yin rĕẖ֣ẇm bĕ̇ʻél-tĕʻé֗m wĕ⁠şǐmĕşǎy֙ sáֽpĕrá֔⁠ʼ ẇ⁠şĕ̌ʼá֖r kĕ̇náwáţĕ⁠h֑wòn di̇֠ynáyé⁠ʼ wa⁠ʼàparĕsaţĕkáyé֞⁠ʼ tarĕpĕ̇láyé֣⁠ʼ ʼàpáֽrĕsáyé֗⁠ʼ ʼrkwy bábĕláyé⁠ʼ֙ şֽ̌ẇşǎnĕkáyé֔⁠ʼ d⁠hwʼ ʻélĕmáyéֽ⁠ʼ׃"],[4,10,"וּ⁠שְׁאָ֣ר אֻמַּיָּ֗⁠א דִּ֤י הַגְלִי֙ אָסְנַפַּר֙ רַבָּ֣⁠א וְ⁠יַקִּירָ֔⁠א וְ⁠הוֹתֵ֣ב הִמּ֔וֹ בְּ⁠קִרְיָ֖ה דִּ֣י שָׁמְרָ֑יִן וּ⁠שְׁאָ֥ר עֲבַֽר־נַהֲרָ֖⁠ה וּ⁠כְעֶֽנֶת׃","ẇ⁠şĕ̌ʼá֣r ʼumȧyá̇֗⁠ʼ di֤̇y hagĕliy֙ ʼásĕnapȧr֙ rabá֣̇⁠ʼ wĕ⁠yaqi̇yrá֔⁠ʼ wĕ⁠hwòţé֣b hiṁ֔wò bĕ̇⁠qirĕyá֖h di֣̇y şá̌mĕrá֑yin ẇ⁠şĕ̌ʼá֥r ʻàbaֽr-nahàrá֖⁠h ẇ⁠kĕʻeֽneţ׃"],[4,11,"דְּנָה֙ פַּרְשֶׁ֣גֶן אִגַּרְתָּ֔⁠א דִּ֚י שְׁלַ֣חוּ עֲל֔וֹ⁠הִי עַל־אַרְתַּחְשַׁ֖שְׂתְּא מַלְכָּ֑⁠א עַבְדָ֛י⁠ךְ אֱנָ֥שׁ עֲבַֽר־נַהֲרָ֖⁠ה וּ⁠כְעֶֽנֶת׃פ","dĕ̇náh֙ pȧrĕşě֣gen ʼigȧrĕţá̇֔⁠ʼ di֚̇y şĕ̌la֣ẖẇ ʻàl֔wò⁠hiy ʻal-ʼarĕţȧẖĕşǎ֖şĕ̂ţĕ̇ʼ malĕká֑̇⁠ʼ ʻabĕdá֛y⁠kĕ ʼèná֥ş̌ ʻàbaֽr-nahàrá֖⁠h ẇ⁠kĕʻeֽneţ׃p"],[4,12,"יְדִ֨יעַ֙ לֶהֱוֵ֣א לְ⁠מַלְכָּ֔⁠א דִּ֣י יְהוּדָיֵ֗⁠א דִּ֤י סְלִ֨קוּ֙ מִן־לְוָתָ֔⁠ךְ עֲלֶ֥י⁠נָא אֲת֖וֹ לִ⁠ירוּשְׁלֶ֑ם קִרְיְתָ֨⁠א מָֽרָדְתָּ֤⁠א ו⁠באישת⁠א בָּנַ֔יִן ו⁠שורי אשכללו וְ⁠אֻשַּׁיָּ֖⁠א יַחִֽיטוּ׃","yĕdi֨yʻa֙ lehèwé֣ʼ lĕ⁠malĕká̇֔⁠ʼ di֣̇y yĕhẇdáyé֗⁠ʼ di֤̇y sĕli֨qẇ֙ min-lĕwáţá֔⁠kĕ ʻàle֥y⁠náʼ ʼàţ֖wò li⁠yrẇşĕ̌le֑m qirĕyĕţá֨⁠ʼ máֽrádĕţá֤̇⁠ʼ w⁠bʼyşţ⁠ʼ bá̇na֔yin w⁠şwry ʼşkllw wĕ⁠ʼuşȧ̌yá֖̇⁠ʼ yaẖiֽytẇ׃"],[4,13,"כְּעַ֗ן יְדִ֨יעַ֙ לֶהֱוֵ֣א לְ⁠מַלְכָּ֔⁠א דִּ֠י הֵ֣ן קִרְיְתָ֥⁠א דָךְ֙ תִּתְבְּנֵ֔א וְ⁠שׁוּרַיָּ֖⁠ה יִֽשְׁתַּכְלְל֑וּן מִנְדָּֽה־בְל֤וֹ וַ⁠הֲלָךְ֙ לָ֣א יִנְתְּנ֔וּן וְ⁠אַפְּתֹ֥ם מַלְכִ֖ים תְּהַנְזִֽק׃","kĕ̇ʻa֗n yĕdi֨yʻa֙ lehèwé֣ʼ lĕ⁠malĕká̇֔⁠ʼ di̇֠y hé֣n qirĕyĕţá֥⁠ʼ dákĕ֙ ţi̇ţĕbĕ̇né֔ʼ wĕ⁠ş̌ẇrayá֖̇⁠h yiֽşĕ̌ţȧkĕlĕl֑ẇn minĕdáֽ̇h-bĕl֤wò wa⁠hàlákĕ֙ lá֣ʼ yinĕţĕ̇n֔ẇn wĕ⁠ʼapĕ̇ţò֥m malĕki֖ym ţĕ̇hanĕziֽq׃"],[4,14,"כְּעַ֗ן כָּ⁠ל־קֳבֵל֙ דִּֽי־מְלַ֤ח הֵֽיכְלָ⁠א֙ מְלַ֔חְנָא וְ⁠עַרְוַ֣ת מַלְכָּ֔⁠א לָ֥א אֲֽרִֽיךְ לַ֖⁠נָא לְ⁠מֶֽחֱזֵ֑א עַ֨ל־דְּנָ֔ה שְׁלַ֖חְנָא וְ⁠הוֹדַ֥עְנָא לְ⁠מַלְכָּֽ⁠א׃","kĕ̇ʻa֗n ká̇⁠l-qobél֙ diֽ̇y-mĕla֤ẖ héֽykĕlá⁠ʼ֙ mĕla֔ẖĕnáʼ wĕ⁠ʻarĕwa֣ţ malĕká̇֔⁠ʼ lá֥ʼ ʼàֽriֽykĕ la֖⁠náʼ lĕ⁠meֽẖèzé֑ʼ ʻa֨l-dĕ̇ná֔h şĕ̌la֖ẖĕnáʼ wĕ⁠hwòda֥ʻĕnáʼ lĕ⁠malĕkáֽ̇⁠ʼ׃"],[4,15,"דִּ֡י יְבַקַּר֩ בִּֽ⁠סְפַר־דָּכְרָ֨נַיָּ֜⁠א דִּ֣י אֲבָהָתָ֗⁠ךְ וּ֠⁠תְהַשְׁכַּח בִּ⁠סְפַ֣ר דָּכְרָנַיָּ⁠א֮ וְ⁠תִנְדַּע֒ דִּי֩ קִרְיְתָ֨⁠א דָ֜ךְ קִרְיָ֣א מָֽרָדָ֗א וּֽ⁠מְהַנְזְקַ֤ת מַלְכִין֙ וּ⁠מְדִנָ֔ן וְ⁠אֶשְׁתַּדּוּר֙ עָבְדִ֣ין בְּ⁠גַוַּ֔⁠הּ מִן־יוֹמָ֖ת עָלְמָ֑⁠א עַ֨ל־דְּנָ֔ה קִרְיְתָ֥⁠א דָ֖ךְ הָֽחָרְבַֽת׃","di̇֡y yĕbaqȧr֩ biֽ̇⁠sĕpar-dá̇kĕrá֨nayá̇֜⁠ʼ di֣̇y ʼàbáháţá֗⁠kĕ ẇ֠⁠ţĕhaşĕ̌kȧẖ bi̇⁠sĕpa֣r dá̇kĕránayá̇⁠ʼ֮ wĕ⁠ţinĕdȧʻ֒ di̇y֩ qirĕyĕţá֨⁠ʼ dá֜kĕ qirĕyá֣ʼ máֽrádá֗ʼ ẇֽ⁠mĕhanĕzĕqa֤ţ malĕkiyn֙ ẇ⁠mĕdiná֔n wĕ⁠ʼeşĕ̌ţȧḋẇr֙ ʻábĕdi֣yn bĕ̇⁠gawȧ֔⁠ḣ min-ywòmá֖ţ ʻálĕmá֑⁠ʼ ʻa֨l-dĕ̇ná֔h qirĕyĕţá֥⁠ʼ dá֖kĕ háֽẖárĕbaֽţ׃"],[4,16,"מְהוֹדְעִ֤ין אֲנַ֨חְנָה֙ לְ⁠מַלְכָּ֔⁠א דִּ֠י הֵ֣ן קִרְיְתָ֥⁠א דָךְ֙ תִּתְבְּנֵ֔א וְ⁠שׁוּרַיָּ֖⁠ה יִֽשְׁתַּכְלְל֑וּן לָ⁠קֳבֵ֣ל דְּנָ֔ה חֲלָק֙ בַּ⁠עֲבַ֣ר נַהֲרָ֔⁠א לָ֥א אִיתַ֖י לָֽ⁠ךְ׃פ","mĕhwòdĕʻi֤yn ʼàna֨ẖĕnáh֙ lĕ⁠malĕká̇֔⁠ʼ di̇֠y hé֣n qirĕyĕţá֥⁠ʼ dákĕ֙ ţi̇ţĕbĕ̇né֔ʼ wĕ⁠ş̌ẇrayá֖̇⁠h yiֽşĕ̌ţȧkĕlĕl֑ẇn lá⁠qobé֣l dĕ̇ná֔h ẖàláq֙ bȧ⁠ʻàba֣r nahàrá֔⁠ʼ lá֥ʼ ʼiyţa֖y láֽ⁠kĕ׃p"],[4,17,"פִּתְגָמָ֞⁠א שְׁלַ֣ח מַלְכָּ֗⁠א עַל־רְח֤וּם בְּעֵל־טְעֵם֙ וְ⁠שִׁמְשַׁ֣י סָֽפְרָ֔⁠א וּ⁠שְׁאָר֙ כְּנָוָ֣תְ⁠ה֔וֹן דִּ֥י יָתְבִ֖ין בְּ⁠שָֽׁמְרָ֑יִן וּ⁠שְׁאָ֧ר עֲבַֽר־נַהֲרָ֛⁠ה שְׁלָ֖ם וּ⁠כְעֶֽת׃ס","pi̇ţĕgámá֞⁠ʼ şĕ̌la֣ẖ malĕká̇֗⁠ʼ ʻal-rĕẖ֤ẇm bĕ̇ʻél-tĕʻém֙ wĕ⁠şǐmĕşǎ֣y sáֽpĕrá֔⁠ʼ ẇ⁠şĕ̌ʼár֙ kĕ̇náwá֣ţĕ⁠h֔wòn di֥̇y yáţĕbi֖yn bĕ̇⁠şáֽ̌mĕrá֑yin ẇ⁠şĕ̌ʼá֧r ʻàbaֽr-nahàrá֛⁠h şĕ̌lá֖m ẇ⁠kĕʻeֽţ׃s"],[4,18,"נִשְׁתְּוָנָ֕⁠א דִּ֥י שְׁלַחְתּ֖וּן עֲלֶ֑י⁠נָא מְפָרַ֥שׁ קֱרִ֖י קָדָמָֽ⁠י׃","nişĕ̌ţĕ̇wáná֕⁠ʼ di֥̇y şĕ̌laẖĕţ֖̇ẇn ʻàle֑y⁠náʼ mĕpára֥ş̌ qèri֖y qádámáֽ⁠y׃"],[4,19,"וּ⁠מִנִּ⁠י֮ שִׂ֣ים טְעֵם֒ וּ⁠בַקַּ֣רוּ וְ⁠הַשְׁכַּ֔חוּ דִּ֚י קִרְיְתָ֣⁠א דָ֔ךְ מִן־יוֹמָת֙ עָֽלְמָ֔⁠א עַל־מַלְכִ֖ין מִֽתְנַשְּׂאָ֑ה וּ⁠מְרַ֥ד וְ⁠אֶשְׁתַּדּ֖וּר מִתְעֲבֶד־בַּֽ⁠הּ׃","ẇ⁠mini̇⁠y֮ şî֣ym tĕʻém֒ ẇ⁠baqȧ֣rẇ wĕ⁠haşĕ̌kȧ֔ẖẇ di֚̇y qirĕyĕţá֣⁠ʼ dá֔kĕ min-ywòmáţ֙ ʻֽálĕmá֔⁠ʼ ʻal-malĕki֖yn miֽţĕnaşĕ̇̂ʼá֑h ẇ⁠mĕra֥d wĕ⁠ʼeşĕ̌ţȧḋ֖ẇr miţĕʻàbed-bȧֽ⁠ḣ׃"],[4,20,"וּ⁠מַלְכִ֣ין תַּקִּיפִ֗ין הֲווֹ֙ עַל־יְר֣וּשְׁלֶ֔ם וְ⁠שַׁ֨לִּיטִ֔ין בְּ⁠כֹ֖ל עֲבַ֣ר נַהֲרָ֑⁠ה וּ⁠מִדָּ֥ה בְל֛וֹ וַ⁠הֲלָ֖ךְ מִתְיְהֵ֥ב לְ⁠הֽוֹן׃","ẇ⁠malĕki֣yn ţȧqi̇ypi֗yn hàwwò֙ ʻal-yĕr֣ẇşĕ̌le֔m wĕ⁠şǎ֨li̇yti֔yn bĕ̇⁠kò֖l ʻàba֣r nahàrá֑⁠h ẇ⁠midá֥̇h bĕl֛wò wa⁠hàlá֖kĕ miţĕyĕhé֥b lĕ⁠hֽwòn׃"],[4,21,"כְּעַן֙ שִׂ֣ימוּ טְּעֵ֔ם לְ⁠בַטָּלָ֖א גֻּבְרַיָּ֣⁠א אִלֵּ֑ךְ וְ⁠קִרְיְתָ֥⁠א דָךְ֙ לָ֣א תִתְבְּנֵ֔א עַד־מִנִּ֖⁠י טַעְמָ֥⁠א יִתְּשָֽׂם׃","kĕ̇ʻan֙ şî֣ymẇ tĕ̇ʻé֔m lĕ⁠batá̇lá֖ʼ gu̇bĕrayá֣̇⁠ʼ ʼilé֑̇kĕ wĕ⁠qirĕyĕţá֥⁠ʼ dákĕ֙ lá֣ʼ ţiţĕbĕ̇né֔ʼ ʻad-mini֖̇⁠y taʻĕmá֥⁠ʼ yiţĕ̇şáֽ̂m׃"],[4,22,"וּ⁠זְהִירִ֥ין הֱו֛וֹ שָׁל֖וּ לְ⁠מֶעְבַּ֣ד עַל־דְּנָ֑ה לְ⁠מָה֙ יִשְׂגֵּ֣א חֲבָלָ֔⁠א לְ⁠הַנְזָקַ֖ת מַלְכִֽין׃ס","ẇ⁠zĕhiyri֥yn hèw֛wò şá̌l֖ẇ lĕ⁠meʻĕbȧ֣d ʻal-dĕ̇ná֑h lĕ⁠máh֙ yişĕ̂gé֣̇ʼ ẖàbálá֔⁠ʼ lĕ⁠hanĕzáqa֖ţ malĕkiֽyn׃s"],[4,23,"אֱדַ֗יִן מִן־דִּ֞י פַּרְשֶׁ֤גֶן נִשְׁתְּוָנָ⁠א֙ דִּ֚י ארתחששתא מַלְכָּ֔⁠א קֱרִ֧י קֳדָם־רְח֛וּם וְ⁠שִׁמְשַׁ֥י סָפְרָ֖⁠א וּ⁠כְנָוָתְ⁠ה֑וֹן אֲזַ֨לוּ בִ⁠בְהִיל֤וּ לִ⁠ירֽוּשְׁלֶם֙ עַל־יְה֣וּדָיֵ֔⁠א וּ⁠בַטִּ֥לוּ הִמּ֖וֹ בְּ⁠אֶדְרָ֥ע וְ⁠חָֽיִל׃ס","ʼèda֗yin min-di̇֞y pȧrĕşě֤gen nişĕ̌ţĕ̇wáná⁠ʼ֙ di֚̇y ʼrţẖşşţʼ malĕká̇֔⁠ʼ qèri֧y qodám-rĕẖ֛ẇm wĕ⁠şǐmĕşǎ֥y sápĕrá֖⁠ʼ ẇ⁠kĕnáwáţĕ⁠h֑wòn ʼàza֨lẇ bi⁠bĕhiyl֤ẇ li⁠yrֽẇşĕ̌lem֙ ʻal-yĕh֣ẇdáyé֔⁠ʼ ẇ⁠bati֥̇lẇ hiṁ֖wò bĕ̇⁠ʼedĕrá֥ʻ wĕ⁠ẖáֽyil׃s"],[4,24,"בֵּ⁠אדַ֗יִן בְּטֵלַת֙ עֲבִידַ֣ת בֵּית־אֱלָהָ֔⁠א דִּ֖י בִּ⁠ירוּשְׁלֶ֑ם וַ⁠הֲוָת֙ בָּֽטְלָ֔א עַ֚ד שְׁנַ֣ת תַּרְתֵּ֔ין לְ⁠מַלְכ֖וּת דָּרְיָ֥וֶשׁ מֶֽלֶךְ־פָּרָֽס׃פ","bé̇⁠ʼda֗yin bĕ̇télaţ֙ ʻàbiyda֣ţ bé̇yţ-ʼèláhá֔⁠ʼ di֖̇y bi̇⁠yrẇşĕ̌le֑m wa⁠hàwáţ֙ báֽ̇tĕlá֔ʼ ʻa֚d şĕ̌na֣ţ ţȧrĕţé̇֔yn lĕ⁠malĕk֖ẇţ dá̇rĕyá֥weş̌ meֽlekĕ-pá̇ráֽs׃p"],[5,1,"וְ⁠הִתְנַבִּ֞י חַגַּ֣י נביא⁠ה וּ⁠זְכַרְיָ֤ה בַר־עִדּוֹא֙ נביאי⁠א עַל־יְה֣וּדָיֵ֔⁠א דִּ֥י בִ⁠יה֖וּד וּ⁠בִ⁠ירוּשְׁלֶ֑ם בְּ⁠שֻׁ֛ם אֱלָ֥הּ יִשְׂרָאֵ֖ל עֲלֵי⁠הֽוֹן׃ס","wĕ⁠hiţĕnabi̇֞y ẖagȧ֣y nbyʼ⁠h ẇ⁠zĕkarĕyá֤h bar-ʻiḋwòʼ֙ nbyʼy⁠ʼ ʻal-yĕh֣ẇdáyé֔⁠ʼ di֥̇y bi⁠yh֖ẇd ẇ⁠bi⁠yrẇşĕ̌le֑m bĕ̇⁠şǔ֛m ʼèlá֥ḣ yişĕ̂ráʼé֖l ʻàléy⁠hֽwòn׃s"],[5,2,"בֵּ⁠אדַ֡יִן קָ֠מוּ זְרֻבָּבֶ֤ל בַּר־שְׁאַלְתִּיאֵל֙ וְ⁠יֵשׁ֣וּעַ בַּר־יֽוֹצָדָ֔ק וְ⁠שָׁרִ֣יו לְ⁠מִבְנֵ֔א בֵּ֥ית אֱלָהָ֖⁠א דִּ֣י בִ⁠ירֽוּשְׁלֶ֑ם וְ⁠עִמְּ⁠ה֛וֹן נביאי⁠א דִֽי־אֱלָהָ֖⁠א מְסָעֲדִ֥ין לְ⁠הֽוֹן׃פ","bé̇⁠ʼda֡yin qá֠mẇ zĕrubá̇be֤l bȧr-şĕ̌ʼalĕţi̇yʼél֙ wĕ⁠yéş֣̌ẇʻa bȧr-yֽwòẕádá֔q wĕ⁠şá̌ri֣yw lĕ⁠mibĕné֔ʼ bé֥̇yţ ʼèláhá֖⁠ʼ di֣̇y bi⁠yrֽẇşĕ̌le֑m wĕ⁠ʻimĕ̇⁠h֛wòn nbyʼy⁠ʼ diֽy-ʼèláhá֖⁠ʼ mĕsáʻàdi֥yn lĕ⁠hֽwòn׃p"],[5,3,"בֵּ⁠הּ־זִמְנָ⁠א֩ אֲתָ֨א עֲלֵי⁠ה֜וֹן תַּ֠תְּנַי פַּחַ֧ת עֲבַֽר־נַהֲרָ֛⁠ה וּ⁠שְׁתַ֥ר בּוֹזְנַ֖י וּ⁠כְנָוָתְ⁠ה֑וֹן וְ⁠כֵן֙ אָמְרִ֣ין לְ⁠הֹ֔ם מַן־שָׂ֨ם לְ⁠כֹ֜ם טְעֵ֗ם בַּיְתָ֤⁠א דְנָה֙ לִ⁠בְּנֵ֔א וְ⁠אֻשַּׁרְנָ֥⁠א דְנָ֖ה לְ⁠שַׁכְלָלָֽה׃ס","bé̇⁠ḣ-zimĕná⁠ʼ֩ ʼàţá֨ʼ ʻàléy⁠h֜wòn ţȧ֠ţĕ̇nay pȧẖa֧ţ ʻàbaֽr-nahàrá֛⁠h ẇ⁠şĕ̌ţa֥r ḃwòzĕna֖y ẇ⁠kĕnáwáţĕ⁠h֑wòn wĕ⁠kén֙ ʼámĕri֣yn lĕ⁠hò֔m man-şá̂֨m lĕ⁠kò֜m tĕʻé֗m bȧyĕţá֤⁠ʼ dĕnáh֙ li⁠bĕ̇né֔ʼ wĕ⁠ʼuşȧ̌rĕná֥⁠ʼ dĕná֖h lĕ⁠şǎkĕláláֽh׃s"],[5,4,"אֱדַ֥יִן כְּנֵ֖מָא אֲמַ֣רְנָא לְּ⁠הֹ֑ם מַן־אִנּוּן֙ שְׁמָהָ֣ת גֻּבְרַיָּ֔⁠א דִּֽי־דְנָ֥ה בִנְיָנָ֖⁠א בָּנַֽיִן׃","ʼèda֥yin kĕ̇né֖máʼ ʼàma֣rĕnáʼ lĕ̇⁠hò֑m man-ʼiṅẇn֙ şĕ̌máhá֣ţ gu̇bĕrayá̇֔⁠ʼ diֽ̇y-dĕná֥h binĕyáná֖⁠ʼ bá̇naֽyin׃"],[5,5,"וְ⁠עֵ֣ין אֱלָהֲ⁠הֹ֗ם הֲוָת֙ עַל־שָׂבֵ֣י יְהוּדָיֵ֔⁠א וְ⁠לָא־בַטִּ֣לוּ הִמּ֔וֹ עַד־טַעְמָ֖⁠א לְ⁠דָרְיָ֣וֶשׁ יְהָ֑ךְ וֶ⁠אֱדַ֛יִן יְתִיב֥וּן נִשְׁתְּוָנָ֖⁠א עַל־דְּנָֽה׃פ","wĕ⁠ʻé֣yn ʼèláhà⁠hò֗m hàwáţ֙ ʻal-şá̂bé֣y yĕhẇdáyé֔⁠ʼ wĕ⁠láʼ-bati֣̇lẇ hiṁ֔wò ʻad-taʻĕmá֖⁠ʼ lĕ⁠dárĕyá֣weş̌ yĕhá֑kĕ we⁠ʼèda֛yin yĕţiyb֥ẇn nişĕ̌ţĕ̇wáná֖⁠ʼ ʻal-dĕ̇náֽh׃p"],[5,6,"פַּרְשֶׁ֣גֶן אִ֠גַּרְתָּ⁠א דִּֽי־שְׁלַ֞ח תַּתְּנַ֣י ׀ פַּחַ֣ת עֲבַֽר־נַהֲרָ֗⁠ה וּ⁠שְׁתַ֤ר בּוֹזְנַי֙ וּ⁠כְנָ֣וָתֵ֔⁠הּ אֲפַ֨רְסְכָיֵ֔⁠א דִּ֖י בַּ⁠עֲבַ֣ר נַהֲרָ֑⁠ה עַל־דָּרְיָ֖וֶשׁ מַלְכָּֽ⁠א׃","pȧrĕşě֣gen ʼi֠gȧrĕţá̇⁠ʼ diֽ̇y-şĕ̌la֞ẖ ţȧţĕ̇na֣y ׀ pȧẖa֣ţ ʻàbaֽr-nahàrá֗⁠h ẇ⁠şĕ̌ţa֤r ḃwòzĕnay֙ ẇ⁠kĕná֣wáţé֔⁠ḣ ʼàpa֨rĕsĕkáyé֔⁠ʼ di֖̇y bȧ⁠ʻàba֣r nahàrá֑⁠h ʻal-dá̇rĕyá֖weş̌ malĕkáֽ̇⁠ʼ׃"],[5,7,"פִּתְגָמָ֖⁠א שְׁלַ֣חוּ עֲל֑וֹ⁠הִי וְ⁠כִ⁠דְנָה֙ כְּתִ֣יב בְּ⁠גַוֵּ֔⁠הּ לְ⁠דָרְיָ֥וֶשׁ מַלְכָּ֖⁠א שְׁלָמָ֥⁠א כֹֽלָּ⁠א׃ס","pi̇ţĕgámá֖⁠ʼ şĕ̌la֣ẖẇ ʻàl֑wò⁠hiy wĕ⁠ki⁠dĕnáh֙ kĕ̇ţi֣yb bĕ̇⁠gawé̇֔⁠ḣ lĕ⁠dárĕyá֥weş̌ malĕká֖̇⁠ʼ şĕ̌lámá֥⁠ʼ kòֽlá̇⁠ʼ׃s"],[5,8,"יְדִ֣יעַ ׀ לֶהֱוֵ֣א לְ⁠מַלְכָּ֗⁠א דִּֽי־אֲזַ֜לְנָא לִ⁠יה֤וּד מְדִֽינְתָּ⁠א֙ לְ⁠בֵית֙ אֱלָהָ֣⁠א רַבָּ֔⁠א וְ⁠ה֤וּא מִתְבְּנֵא֙ אֶ֣בֶן גְּלָ֔ל וְ⁠אָ֖ע מִתְּשָׂ֣ם בְּ⁠כֻתְלַיָּ֑⁠א וַ⁠עֲבִ֥ידְתָּ⁠א דָ֛ךְ אָסְפַּ֥רְנָא מִתְעַבְדָ֖א וּ⁠מַצְלַ֥ח בְּ⁠יֶדְ⁠הֹֽם׃ס","yĕdi֣yʻa ׀ lehèwé֣ʼ lĕ⁠malĕká̇֗⁠ʼ diֽ̇y-ʼàza֜lĕnáʼ li⁠yh֤ẇd mĕdiֽynĕţá̇⁠ʼ֙ lĕ⁠béyţ֙ ʼèláhá֣⁠ʼ rabá̇֔⁠ʼ wĕ⁠h֤ẇʼ miţĕbĕ̇néʼ֙ ʼe֣ben gĕ̇lá֔l wĕ⁠ʼá֖ʻ miţĕ̇şá֣̂m bĕ̇⁠kuţĕlayá֑̇⁠ʼ wa⁠ʻàbi֥ydĕţá̇⁠ʼ dá֛kĕ ʼásĕpȧ֥rĕnáʼ miţĕʻabĕdá֖ʼ ẇ⁠maẕĕla֥ẖ bĕ̇⁠yedĕ⁠hòֽm׃s"],[5,9,"אֱדַ֗יִן שְׁאֵ֨לְנָא֙ לְ⁠שָׂבַיָּ֣⁠א אִלֵּ֔ךְ כְּנֵ֖מָא אֲמַ֣רְנָא לְּ⁠הֹ֑ם מַן־שָׂ֨ם לְ⁠כֹ֜ם טְעֵ֗ם בַּיְתָ֤⁠א דְנָה֙ לְ⁠מִבְנְיָ֔ה וְ⁠אֻשַּׁרְנָ֥⁠א דְנָ֖ה לְ⁠שַׁכְלָלָֽה׃","ʼèda֗yin şĕ̌ʼé֨lĕnáʼ֙ lĕ⁠şá̂bayá֣̇⁠ʼ ʼilé̇֔kĕ kĕ̇né֖máʼ ʼàma֣rĕnáʼ lĕ̇⁠hò֑m man-şá̂֨m lĕ⁠kò֜m tĕʻé֗m bȧyĕţá֤⁠ʼ dĕnáh֙ lĕ⁠mibĕnĕyá֔h wĕ⁠ʼuşȧ̌rĕná֥⁠ʼ dĕná֖h lĕ⁠şǎkĕláláֽh׃"],[5,10,"וְ⁠אַ֧ף שְׁמָהָתְ⁠הֹ֛ם שְׁאֵ֥לְנָא לְּ⁠הֹ֖ם לְ⁠הוֹדָעוּתָ֑⁠ךְ דִּ֛י נִכְתֻּ֥ב שֻׁם־גֻּבְרַיָּ֖⁠א דִּ֥י בְ⁠רָאשֵׁי⁠הֹֽם׃ס","wĕ⁠ʼa֧p şĕ̌máháţĕ⁠hò֛m şĕ̌ʼé֥lĕnáʼ lĕ̇⁠hò֖m lĕ⁠hwòdáʻẇţá֑⁠kĕ di֛̇y nikĕţu֥̇b şǔm-gu̇bĕrayá֖̇⁠ʼ di֥̇y bĕ⁠ráʼşé̌y⁠hòֽm׃s"],[5,11,"וּ⁠כְנֵ֥מָא פִתְגָמָ֖⁠א הֲתִיב֣וּ⁠נָא לְ⁠מֵמַ֑ר אֲנַ֣חְנָא הִמּ֡וֹ עַבְדוֹ⁠הִי֩ דִֽי־אֱלָ֨הּ שְׁמַיָּ֜⁠א וְ⁠אַרְעָ֗⁠א וּ⁠בָנַ֤יִן בַּיְתָ⁠א֙ דִּֽי־הֲוָ֨א בְנֵ֜ה מִ⁠קַּדְמַ֤ת דְּנָה֙ שְׁנִ֣ין שַׂגִּיאָ֔ן וּ⁠מֶ֤לֶךְ לְ⁠יִשְׂרָאֵל֙ רַ֔ב בְּנָ֖⁠הִי וְ⁠שַׁכְלְלֵֽ⁠הּ׃","ẇ⁠kĕné֥máʼ piţĕgámá֖⁠ʼ hàţiyb֣ẇ⁠náʼ lĕ⁠méma֑r ʼàna֣ẖĕnáʼ hiṁ֡wò ʻabĕdwò⁠hiy֩ diֽy-ʼèlá֨ḣ şĕ̌mayá̇֜⁠ʼ wĕ⁠ʼarĕʻá֗⁠ʼ ẇ⁠bána֤yin bȧyĕţá⁠ʼ֙ diֽ̇y-hàwá֨ʼ bĕné֜h mi⁠qȧdĕma֤ţ dĕ̇náh֙ şĕ̌ni֣yn şâgi̇yʼá֔n ẇ⁠me֤lekĕ lĕ⁠yişĕ̂ráʼél֙ ra֔b bĕ̇ná֖⁠hiy wĕ⁠şǎkĕlĕléֽ⁠ḣ׃"],[5,12,"לָהֵ֗ן מִן־דִּ֨י הַרְגִּ֤זוּ אֲבָהֳתַ֨⁠נָא֙ לֶ⁠אֱלָ֣הּ שְׁמַיָּ֔⁠א יְהַ֣ב הִמּ֔וֹ בְּ⁠יַ֛ד נְבוּכַדְנֶצַּ֥ר מֶֽלֶךְ־בָּבֶ֖ל כסדי⁠א וּ⁠בַיְתָ֤⁠ה דְנָה֙ סַתְרֵ֔⁠הּ וְ⁠עַמָּ֖⁠ה הַגְלִ֥י לְ⁠בָבֶֽל׃ס","láhé֗n min-di̇֨y harĕgi֤̇zẇ ʼàbáhoţa֨⁠náʼ֙ le⁠ʼèlá֣ḣ şĕ̌mayá̇֔⁠ʼ yĕha֣b hiṁ֔wò bĕ̇⁠ya֛d nĕbẇkadĕneẕȧ֥r meֽlekĕ-bá̇be֖l ksdy⁠ʼ ẇ⁠bayĕţá֤⁠h dĕnáh֙ saţĕré֔⁠ḣ wĕ⁠ʻamá֖̇⁠h hagĕli֥y lĕ⁠bábeֽl׃s"],[5,13,"בְּרַם֙ בִּ⁠שְׁנַ֣ת חֲדָ֔ה לְ⁠כ֥וֹרֶשׁ מַלְכָּ֖⁠א דִּ֣י בָבֶ֑ל כּ֤וֹרֶשׁ מַלְכָּ⁠א֙ שָׂ֣ם טְעֵ֔ם בֵּית־אֱלָהָ֥⁠א דְנָ֖ה לִ⁠בְּנֵֽא׃","bĕ̇ram֙ bi̇⁠şĕ̌na֣ţ ẖàdá֔h lĕ⁠k֥wòreş̌ malĕká֖̇⁠ʼ di֣̇y bábe֑l k֤̇wòreş̌ malĕká̇⁠ʼ֙ şá֣̂m tĕʻé֔m bé̇yţ-ʼèláhá֥⁠ʼ dĕná֖h li⁠bĕ̇néֽʼ׃"],[5,14,"וְ֠⁠אַף מָאנַיָּ֣⁠א דִֽי־בֵית־אֱלָהָ⁠א֮ דִּ֣י דַהֲבָ֣⁠ה וְ⁠כַסְפָּ⁠א֒ דִּ֣י נְבוּכַדְנֶצַּ֗ר הַנְפֵּק֙ מִן־הֵֽיכְלָ⁠א֙ דִּ֣י בִֽ⁠ירוּשְׁלֶ֔ם וְ⁠הֵיבֵ֣ל הִמּ֔וֹ לְ⁠הֵיכְלָ֖⁠א דִּ֣י בָבֶ֑ל הַנְפֵּ֨ק הִמּ֜וֹ כּ֣וֹרֶשׁ מַלְכָּ֗⁠א מִן־הֵֽיכְלָ⁠א֙ דִּ֣י בָבֶ֔ל וִ⁠יהִ֨יבוּ֙ לְ⁠שֵׁשְׁבַּצַּ֣ר שְׁמֵ֔⁠הּ דִּ֥י פֶחָ֖ה שָׂמֵֽ⁠הּ׃","wĕ֠⁠ʼap máʼnayá֣̇⁠ʼ diֽy-béyţ-ʼèláhá⁠ʼ֮ di֣̇y dahàbá֣⁠h wĕ⁠kasĕpá̇⁠ʼ֒ di֣̇y nĕbẇkadĕneẕȧ֗r hanĕpé̇q֙ min-héֽykĕlá⁠ʼ֙ di֣̇y biֽ⁠yrẇşĕ̌le֔m wĕ⁠héybé֣l hiṁ֔wò lĕ⁠héykĕlá֖⁠ʼ di֣̇y bábe֑l hanĕpé̇֨q hiṁ֜wò k֣̇wòreş̌ malĕká̇֗⁠ʼ min-héֽykĕlá⁠ʼ֙ di֣̇y bábe֔l wi⁠yhi֨ybẇ֙ lĕ⁠şé̌şĕ̌bȧẕȧ֣r şĕ̌mé֔⁠ḣ di֥̇y peẖá֖h şá̂méֽ⁠ḣ׃"],[5,15,"וַ⁠אֲמַר־לֵ֓⁠הּ ׀ אלה מָֽאנַיָּ֔⁠א שֵׂ֚א אֵֽזֶל־אֲחֵ֣ת הִמּ֔וֹ בְּ⁠הֵיכְלָ֖⁠א דִּ֣י בִ⁠ירוּשְׁלֶ֑ם וּ⁠בֵ֥ית אֱלָהָ֖⁠א יִתְבְּנֵ֥א עַל־אַתְרֵֽ⁠הּ׃ס","wa⁠ʼàmar-lé֓⁠ḣ ׀ ʼlh máֽʼnayá̇֔⁠ʼ şé֚̂ʼ ʼéֽzel-ʼàẖé֣ţ hiṁ֔wò bĕ̇⁠héykĕlá֖⁠ʼ di֣̇y bi⁠yrẇşĕ̌le֑m ẇ⁠bé֥yţ ʼèláhá֖⁠ʼ yiţĕbĕ̇né֥ʼ ʻal-ʼaţĕréֽ⁠ḣ׃s"],[5,16,"אֱדַ֨יִן֙ שֵׁשְׁבַּצַּ֣ר דֵּ֔ךְ אֲתָ֗א יְהַ֧ב אֻשַּׁיָּ֛⁠א דִּי־בֵ֥ית אֱלָהָ֖⁠א דִּ֣י בִ⁠ירוּשְׁלֶ֑ם וּ⁠מִן־אֱדַ֧יִן וְ⁠עַד־כְּעַ֛ן מִתְבְּנֵ֖א וְ⁠לָ֥א שְׁלִֽם׃","ʼèda֨yin֙ şé̌şĕ̌bȧẕȧ֣r dé̇֔kĕ ʼàţá֗ʼ yĕha֧b ʼuşȧ̌yá֛̇⁠ʼ di̇y-bé֥yţ ʼèláhá֖⁠ʼ di֣̇y bi⁠yrẇşĕ̌le֑m ẇ⁠min-ʼèda֧yin wĕ⁠ʻad-kĕ̇ʻa֛n miţĕbĕ̇né֖ʼ wĕ⁠lá֥ʼ şĕ̌liֽm׃"],[5,17,"וּ⁠כְעַ֞ן הֵ֧ן עַל־מַלְכָּ֣⁠א טָ֗ב יִ֠תְבַּקַּר בְּ⁠בֵ֨ית גִּנְזַיָּ֜⁠א דִּי־מַלְכָּ֣⁠א תַמָּה֮ דִּ֣י בְּ⁠בָבֶל֒ הֵ֣ן אִיתַ֗י דִּֽי־מִן־כּ֤וֹרֶשׁ מַלְכָּ⁠א֙ שִׂ֣ים טְעֵ֔ם לְ⁠מִבְנֵ֛א בֵּית־אֱלָהָ֥⁠א דֵ֖ךְ בִּ⁠ירוּשְׁלֶ֑ם וּ⁠רְע֥וּת מַלְכָּ֛⁠א עַל־דְּנָ֖ה יִשְׁלַ֥ח עֲלֶֽי⁠נָא׃ס","ẇ⁠kĕʻa֞n hé֧n ʻal-malĕká֣̇⁠ʼ tá֗b yi֠ţĕbȧqȧr bĕ̇⁠bé֨yţ gi̇nĕzayá̇֜⁠ʼ di̇y-malĕká֣̇⁠ʼ ţamá̇h֮ di֣̇y bĕ̇⁠bábel֒ hé֣n ʼiyţa֗y diֽ̇y-min-k֤̇wòreş̌ malĕká̇⁠ʼ֙ şî֣ym tĕʻé֔m lĕ⁠mibĕné֛ʼ bé̇yţ-ʼèláhá֥⁠ʼ dé֖kĕ bi̇⁠yrẇşĕ̌le֑m ẇ⁠rĕʻ֥ẇţ malĕká֛̇⁠ʼ ʻal-dĕ̇ná֖h yişĕ̌la֥ẖ ʻàleֽy⁠náʼ׃s"],[6,1,"בֵּ⁠אדַ֛יִן דָּרְיָ֥וֶשׁ מַלְכָּ֖⁠א שָׂ֣ם טְעֵ֑ם וּ⁠בַקַּ֣רוּ ׀ בְּ⁠בֵ֣ית סִפְרַיָּ֗⁠א דִּ֧י גִנְזַיָּ֛⁠א מְהַחֲתִ֥ין תַּמָּ֖ה בְּ⁠בָבֶֽל׃","bé̇⁠ʼda֛yin dá̇rĕyá֥weş̌ malĕká֖̇⁠ʼ şá֣̂m tĕʻé֑m ẇ⁠baqȧ֣rẇ ׀ bĕ̇⁠bé֣yţ sipĕrayá̇֗⁠ʼ di֧̇y ginĕzayá֛̇⁠ʼ mĕhaẖàţi֥yn ţȧmá֖̇h bĕ̇⁠bábeֽl׃"],[6,2,"וְ⁠הִשְׁתְּכַ֣ח בְּ⁠אַחְמְתָ֗א בְּ⁠בִֽירְתָ֛⁠א דִּ֛י בְּ⁠מָדַ֥י מְדִינְתָּ֖⁠ה מְגִלָּ֣ה חֲדָ֑ה וְ⁠כֵן־כְּתִ֥יב בְּ⁠גַוַּ֖⁠הּ דִּכְרוֹנָֽ⁠ה׃פ","wĕ⁠hişĕ̌ţĕ̇ka֣ẖ bĕ̇⁠ʼaẖĕmĕţá֗ʼ bĕ̇⁠biֽyrĕţá֛⁠ʼ di֛̇y bĕ̇⁠máda֥y mĕdiynĕţá֖̇⁠h mĕgilá֣̇h ẖàdá֑h wĕ⁠kén-kĕ̇ţi֥yb bĕ̇⁠gawȧ֖⁠ḣ di̇kĕrwònáֽ⁠h׃p"],[6,3,"בִּ⁠שְׁנַ֨ת חֲדָ֜ה לְ⁠כ֣וֹרֶשׁ מַלְכָּ֗⁠א כּ֣וֹרֶשׁ מַלְכָּ⁠א֮ שָׂ֣ם טְעֵם֒ בֵּית־אֱלָהָ֤⁠א בִֽ⁠ירוּשְׁלֶם֙ בַּיְתָ֣⁠א יִתְבְּנֵ֔א אֲתַר֙ דִּֽי־דָבְחִ֣ין דִּבְחִ֔ין וְ⁠אֻשּׁ֖וֹ⁠הִי מְסֽוֹבְלִ֑ין רוּמֵ⁠הּ֙ אַמִּ֣ין שִׁתִּ֔ין פְּתָיֵ֖⁠הּ אַמִּ֥ין שִׁתִּֽין׃","bi̇⁠şĕ̌na֨ţ ẖàdá֜h lĕ⁠k֣wòreş̌ malĕká̇֗⁠ʼ k֣̇wòreş̌ malĕká̇⁠ʼ֮ şá֣̂m tĕʻém֒ bé̇yţ-ʼèláhá֤⁠ʼ biֽ⁠yrẇşĕ̌lem֙ bȧyĕţá֣⁠ʼ yiţĕbĕ̇né֔ʼ ʼàţar֙ diֽ̇y-dábĕẖi֣yn di̇bĕẖi֔yn wĕ⁠ʼuş֖̇̌wò⁠hiy mĕsֽwòbĕli֑yn rẇmé⁠ḣ֙ ʼami֣̇yn şǐţi̇֔yn pĕ̇ţáyé֖⁠ḣ ʼami֥̇yn şǐţiֽ̇yn׃"],[6,4,"נִדְבָּכִ֞ין דִּי־אֶ֤בֶן גְּלָל֙ תְּלָתָ֔א וְ⁠נִדְבָּ֖ךְ דִּי־אָ֣ע חֲדַ֑ת וְ⁠נִ֨פְקְתָ֔⁠א מִן־בֵּ֥ית מַלְכָּ֖⁠א תִּתְיְהִֽב׃","nidĕbá̇ki֞yn di̇y-ʼe֤ben gĕ̇lál֙ ţĕ̇láţá֔ʼ wĕ⁠nidĕbá֖̇kĕ di̇y-ʼá֣ʻ ẖàda֑ţ wĕ⁠ni֨pĕqĕţá֔⁠ʼ min-bé֥̇yţ malĕká֖̇⁠ʼ ţi̇ţĕyĕhiֽb׃"],[6,5,"וְ֠⁠אַף מָאנֵ֣י בֵית־אֱלָהָ⁠א֮ דִּ֣י דַהֲבָ֣⁠ה וְ⁠כַסְפָּ⁠א֒ דִּ֣י נְבֽוּכַדְנֶצַּ֗ר הַנְפֵּ֛ק מִן־הֵיכְלָ֥⁠א דִי־בִ⁠ירוּשְׁלֶ֖ם וְ⁠הֵיבֵ֣ל לְ⁠בָבֶ֑ל יַהֲתִיב֗וּן וִ֠⁠יהָךְ לְ⁠הֵיכְלָ֤⁠א דִי־בִ⁠ירֽוּשְׁלֶם֙ לְ⁠אַתְרֵ֔⁠הּ וְ⁠תַחֵ֖ת בְּ⁠בֵ֥ית אֱלָהָֽ⁠א׃ס","wĕ֠⁠ʼap máʼné֣y béyţ-ʼèláhá⁠ʼ֮ di֣̇y dahàbá֣⁠h wĕ⁠kasĕpá̇⁠ʼ֒ di֣̇y nĕbֽẇkadĕneẕȧ֗r hanĕpé֛̇q min-héykĕlá֥⁠ʼ diy-bi⁠yrẇşĕ̌le֖m wĕ⁠héybé֣l lĕ⁠bábe֑l yahàţiyb֗ẇn wi֠⁠yhákĕ lĕ⁠héykĕlá֤⁠ʼ diy-bi⁠yrֽẇşĕ̌lem֙ lĕ⁠ʼaţĕré֔⁠ḣ wĕ⁠ţaẖé֖ţ bĕ̇⁠bé֥yţ ʼèláháֽ⁠ʼ׃s"],[6,6,"כְּעַ֡ן תַּ֠תְּנַי פַּחַ֨ת עֲבַֽר־נַהֲרָ֜⁠ה שְׁתַ֤ר בּוֹזְנַי֙ וּ⁠כְנָוָ֣תְ⁠ה֔וֹן אֲפַרְסְכָיֵ֔⁠א דִּ֖י בַּ⁠עֲבַ֣ר נַהֲרָ֑⁠ה רַחִיקִ֥ין הֲו֖וֹ מִן־תַּמָּֽה׃","kĕ̇ʻa֡n ţȧ֠ţĕ̇nay pȧẖa֨ţ ʻàbaֽr-nahàrá֜⁠h şĕ̌ţa֤r ḃwòzĕnay֙ ẇ⁠kĕnáwá֣ţĕ⁠h֔wòn ʼàparĕsĕkáyé֔⁠ʼ di֖̇y bȧ⁠ʻàba֣r nahàrá֑⁠h raẖiyqi֥yn hàw֖wò min-ţȧmáֽ̇h׃"],[6,7,"שְׁבֻ֕קוּ לַ⁠עֲבִידַ֖ת בֵּית־אֱלָהָ֣⁠א דֵ֑ךְ פַּחַ֤ת יְהוּדָיֵ⁠א֙ וּ⁠לְ⁠שָׂבֵ֣י יְהוּדָיֵ֔⁠א בֵּית־אֱלָהָ֥⁠א דֵ֖ךְ יִבְנ֥וֹן עַל־אַתְרֵֽ⁠הּ׃","şĕ̌bu֕qẇ la⁠ʻàbiyda֖ţ bé̇yţ-ʼèláhá֣⁠ʼ dé֑kĕ pȧẖa֤ţ yĕhẇdáyé⁠ʼ֙ ẇ⁠lĕ⁠şá̂bé֣y yĕhẇdáyé֔⁠ʼ bé̇yţ-ʼèláhá֥⁠ʼ dé֖kĕ yibĕn֥wòn ʻal-ʼaţĕréֽ⁠ḣ׃"],[6,8,"וּ⁠מִנִּ⁠י֮ שִׂ֣ים טְעֵם֒ לְ⁠מָ֣א דִֽי־תַֽעַבְד֗וּן עִם־שָׂבֵ֤י יְהוּדָיֵ⁠א֙ אִלֵּ֔ךְ לְ⁠מִבְנֵ֖א בֵּית־אֱלָהָ֣⁠א דֵ֑ךְ וּ⁠מִ⁠נִּכְסֵ֣י מַלְכָּ֗⁠א דִּ֚י מִדַּת֙ עֲבַ֣ר נַהֲרָ֔⁠ה אָסְפַּ֗רְנָא נִפְקְתָ֛⁠א תֶּהֱוֵ֧א מִֽתְיַהֲבָ֛א לְ⁠גֻבְרַיָּ֥⁠א אִלֵּ֖ךְ דִּי־לָ֥א לְ⁠בַטָּלָֽא׃","ẇ⁠mini̇⁠y֮ şî֣ym tĕʻém֒ lĕ⁠má֣ʼ diֽy-ţֽaʻabĕd֗ẇn ʻim-şá̂bé֤y yĕhẇdáyé⁠ʼ֙ ʼilé̇֔kĕ lĕ⁠mibĕné֖ʼ bé̇yţ-ʼèláhá֣⁠ʼ dé֑kĕ ẇ⁠mi⁠ni̇kĕsé֣y malĕká̇֗⁠ʼ di֚̇y midȧţ֙ ʻàba֣r nahàrá֔⁠h ʼásĕpȧ֗rĕnáʼ nipĕqĕţá֛⁠ʼ ţėhèwé֧ʼ miֽţĕyahàbá֛ʼ lĕ⁠gubĕrayá֥̇⁠ʼ ʼilé֖̇kĕ di̇y-lá֥ʼ lĕ⁠batá̇láֽʼ׃"],[6,9,"וּ⁠מָ֣ה חַשְׁחָ֡ן וּ⁠בְנֵ֣י תוֹרִ֣ין וְ⁠דִכְרִ֣ין וְ⁠אִמְּרִ֣ין ׀ לַ⁠עֲלָוָ֣ן ׀ לֶ⁠אֱלָ֪הּ שְׁמַיָּ֟⁠א חִנְטִ֞ין מְלַ֣ח ׀ חֲמַ֣ר וּ⁠מְשַׁ֗ח כְּ⁠מֵאמַ֨ר כָּהֲנַיָּ֤⁠א דִי־בִ⁠ירֽוּשְׁלֶם֙ לֶהֱוֵ֨א מִתְיְהֵ֥ב לְ⁠הֹ֛ם י֥וֹם ׀ בְּ⁠י֖וֹם דִּי־לָ֥א שָׁלֽוּ׃","ẇ⁠má֣h ẖaşĕ̌ẖá֡n ẇ⁠bĕné֣y ţwòri֣yn wĕ⁠dikĕri֣yn wĕ⁠ʼimĕ̇ri֣yn ׀ la⁠ʻàláwá֣n ׀ le⁠ʼèlá֪ḣ şĕ̌mayá̇֟⁠ʼ ẖinĕti֞yn mĕla֣ẖ ׀ ẖàma֣r ẇ⁠mĕşǎ֗ẖ kĕ̇⁠méʼma֨r ká̇hànayá֤̇⁠ʼ diy-bi⁠yrֽẇşĕ̌lem֙ lehèwé֨ʼ miţĕyĕhé֥b lĕ⁠hò֛m y֥wòm ׀ bĕ̇⁠y֖wòm di̇y-lá֥ʼ şá̌lֽẇ׃"],[6,10,"דִּֽי־לֶהֱוֺ֧ן מְהַקְרְבִ֛ין נִיחוֹחִ֖ין לֶ⁠אֱלָ֣הּ שְׁמַיָּ֑⁠א וּ⁠מְצַלַּ֕יִן לְ⁠חַיֵּ֥י מַלְכָּ֖⁠א וּ⁠בְנֽוֹ⁠הִי׃","diֽ̇y-lehèwֺ֧n mĕhaqĕrĕbi֛yn niyẖwòẖi֖yn le⁠ʼèlá֣ḣ şĕ̌mayá֑̇⁠ʼ ẇ⁠mĕẕalȧ֕yin lĕ⁠ẖayé֥̇y malĕká֖̇⁠ʼ ẇ⁠bĕnֽwò⁠hiy׃"],[6,11,"וּ⁠מִנִּ⁠י֮ שִׂ֣ים טְעֵם֒ דִּ֣י כָל־אֱנָ֗שׁ דִּ֤י יְהַשְׁנֵא֙ פִּתְגָמָ֣⁠א דְנָ֔ה יִתְנְסַ֥ח אָע֙ מִן־בַּיְתֵ֔⁠הּ וּ⁠זְקִ֖יף יִתְמְחֵ֣א עֲלֹ֑⁠הִי וּ⁠בַיְתֵ֛⁠הּ נְוָל֥וּ יִתְעֲבֵ֖ד עַל־דְּנָֽה׃","ẇ⁠mini̇⁠y֮ şî֣ym tĕʻém֒ di֣̇y kál-ʼèná֗ş̌ di֤̇y yĕhaşĕ̌néʼ֙ pi̇ţĕgámá֣⁠ʼ dĕná֔h yiţĕnĕsa֥ẖ ʼáʻ֙ min-bȧyĕţé֔⁠ḣ ẇ⁠zĕqi֖yp yiţĕmĕẖé֣ʼ ʻàlò֑⁠hiy ẇ⁠bayĕţé֛⁠ḣ nĕwál֥ẇ yiţĕʻàbé֖d ʻal-dĕ̇náֽh׃"],[6,12,"וֵֽ⁠אלָהָ֞⁠א דִּ֣י שַׁכִּ֧ן שְׁמֵ֣⁠הּ תַּמָּ֗ה יְמַגַּ֞ר כָּל־מֶ֤לֶךְ וְ⁠עַם֙ דִּ֣י ׀ יִשְׁלַ֣ח יְדֵ֗⁠הּ לְ⁠הַשְׁנָיָ֛ה לְ⁠חַבָּלָ֛ה בֵּית־אֱלָהָ֥⁠א דֵ֖ךְ דִּ֣י בִ⁠ירוּשְׁלֶ֑ם אֲנָ֤ה דָרְיָ֨וֶשׁ֙ שָׂ֣מֶת טְעֵ֔ם אָסְפַּ֖רְנָא יִתְעֲבִֽד׃פ","wéֽ⁠ʼláhá֞⁠ʼ di֣̇y şǎki֧̇n şĕ̌mé֣⁠ḣ ţȧmá̇֗h yĕmagȧ֞r ká̇l-me֤lekĕ wĕ⁠ʻam֙ di֣̇y ׀ yişĕ̌la֣ẖ yĕdé֗⁠ḣ lĕ⁠haşĕ̌náyá֛h lĕ⁠ẖabá̇lá֛h bé̇yţ-ʼèláhá֥⁠ʼ dé֖kĕ di֣̇y bi⁠yrẇşĕ̌le֑m ʼàná֤h dárĕyá֨weş̌֙ şá֣̂meţ tĕʻé֔m ʼásĕpȧ֖rĕnáʼ yiţĕʻàbiֽd׃p"],[6,13,"אֱ֠דַיִן תַּתְּנַ֞י פַּחַ֧ת עֲבַֽר־נַהֲרָ֛⁠ה שְׁתַ֥ר בּוֹזְנַ֖י וּ⁠כְנָוָתְ⁠ה֑וֹן לָ⁠קֳבֵ֗ל דִּֽי־שְׁלַ֞ח דָּרְיָ֧וֶשׁ מַלְכָּ֛⁠א כְּנֵ֖מָא אָסְפַּ֥רְנָא עֲבַֽדוּ׃","ʼè֠dayin ţȧţĕ̇na֞y pȧẖa֧ţ ʻàbaֽr-nahàrá֛⁠h şĕ̌ţa֥r ḃwòzĕna֖y ẇ⁠kĕnáwáţĕ⁠h֑wòn lá⁠qobé֗l diֽ̇y-şĕ̌la֞ẖ dá̇rĕyá֧weş̌ malĕká֛̇⁠ʼ kĕ̇né֖máʼ ʼásĕpȧ֥rĕnáʼ ʻàbaֽdẇ׃"],[6,14,"וְ⁠שָׂבֵ֤י יְהוּדָיֵ⁠א֙ בָּנַ֣יִן וּ⁠מַצְלְחִ֔ין בִּ⁠נְבוּאַת֙ חַגַּ֣י נביא⁠ה וּ⁠זְכַרְיָ֖ה בַּר־עִדּ֑וֹא וּ⁠בְנ֣וֹ וְ⁠שַׁכְלִ֗לוּ מִן־טַ֨עַם֙ אֱלָ֣הּ יִשְׂרָאֵ֔ל וּ⁠מִ⁠טְּעֵם֙ כּ֣וֹרֶשׁ וְ⁠דָרְיָ֔וֶשׁ וְ⁠אַרְתַּחְשַׁ֖שְׂתְּא מֶ֥לֶךְ פָּרָֽס׃","wĕ⁠şá̂bé֤y yĕhẇdáyé⁠ʼ֙ bá̇na֣yin ẇ⁠maẕĕlĕẖi֔yn bi̇⁠nĕbẇʼaţ֙ ẖagȧ֣y nbyʼ⁠h ẇ⁠zĕkarĕyá֖h bȧr-ʻiḋ֑wòʼ ẇ⁠bĕn֣wò wĕ⁠şǎkĕli֗lẇ min-ta֨ʻam֙ ʼèlá֣ḣ yişĕ̂ráʼé֔l ẇ⁠mi⁠tĕ̇ʻém֙ k֣̇wòreş̌ wĕ⁠dárĕyá֔weş̌ wĕ⁠ʼarĕţȧẖĕşǎ֖şĕ̂ţĕ̇ʼ me֥lekĕ pá̇ráֽs׃"],[6,15,"וְ⁠שֵׁיצִיא֙ בַּיְתָ֣⁠ה דְנָ֔ה עַ֛ד י֥וֹם תְּלָתָ֖ה לִ⁠ירַ֣ח אֲדָ֑ר דִּי־הִ֣יא שְׁנַת־שֵׁ֔ת לְ⁠מַלְכ֖וּת דָּרְיָ֥וֶשׁ מַלְכָּֽ⁠א׃פ","wĕ⁠şé̌yẕiyʼ֙ bȧyĕţá֣⁠h dĕná֔h ʻa֛d y֥wòm ţĕ̇láţá֖h li⁠yra֣ẖ ʼàdá֑r di̇y-hi֣yʼ şĕ̌naţ-şé̌֔ţ lĕ⁠malĕk֖ẇţ dá̇rĕyá֥weş̌ malĕkáֽ̇⁠ʼ׃p"],[6,16,"וַ⁠עֲבַ֣דוּ בְנֵֽי־יִ֠שְׂרָאֵל כָּהֲנַיָּ֨⁠א וְ⁠לֵוָיֵ֜⁠א וּ⁠שְׁאָ֣ר בְּנֵי־גָלוּתָ֗⁠א חֲנֻכַּ֛ת בֵּית־אֱלָהָ֥⁠א דְנָ֖ה בְּ⁠חֶדְוָֽה׃","wa⁠ʻàba֣dẇ bĕnéֽy-yi֠şĕ̂ráʼél ká̇hànayá̇֨⁠ʼ wĕ⁠léwáyé֜⁠ʼ ẇ⁠şĕ̌ʼá֣r bĕ̇néy-gálẇţá֗⁠ʼ ẖànukȧ֛ţ bé̇yţ-ʼèláhá֥⁠ʼ dĕná֖h bĕ̇⁠ẖedĕwáֽh׃"],[6,17,"וְ⁠הַקְרִ֗בוּ לַ⁠חֲנֻכַּת֮ בֵּית־אֱלָהָ֣⁠א דְנָה֒ תּוֹרִ֣ין מְאָ֔ה דִּכְרִ֣ין מָאתַ֔יִן אִמְּרִ֖ין אַרְבַּ֣ע מְאָ֑ה וּ⁠צְפִירֵ֨י עִזִּ֜ין ל⁠חטיא עַל־כָּל־יִשְׂרָאֵל֙ תְּרֵֽי־עֲשַׂ֔ר לְ⁠מִנְיָ֖ן שִׁבְטֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠haqĕri֗bẇ la⁠ẖànukȧţ֮ bé̇yţ-ʼèláhá֣⁠ʼ dĕnáh֒ ţ̇wòri֣yn mĕʼá֔h di̇kĕri֣yn máʼţa֔yin ʼimĕ̇ri֖yn ʼarĕbȧ֣ʻ mĕʼá֑h ẇ⁠ẕĕpiyré֨y ʻizi̇֜yn l⁠ẖtyʼ ʻal-ká̇l-yişĕ̂ráʼél֙ ţĕ̇réֽy-ʻàşâ֔r lĕ⁠minĕyá֖n şǐbĕté֥y yişĕ̂ráʼéֽl׃"],[6,18,"וַ⁠הֲקִ֨ימוּ כָהֲנַיָּ֜⁠א בִּ⁠פְלֻגָּתְ⁠ה֗וֹן וְ⁠לֵוָיֵ⁠א֙ בְּ⁠מַחְלְקָ֣תְ⁠ה֔וֹן עַל־עֲבִידַ֥ת אֱלָהָ֖⁠א דִּ֣י בִ⁠ירוּשְׁלֶ֑ם כִּ⁠כְתָ֖ב סְפַ֥ר מֹשֶֽׁה׃פ","wa⁠hàqi֨ymẇ káhànayá̇֜⁠ʼ bi̇⁠pĕlugá̇ţĕ⁠h֗wòn wĕ⁠léwáyé⁠ʼ֙ bĕ̇⁠maẖĕlĕqá֣ţĕ⁠h֔wòn ʻal-ʻàbiyda֥ţ ʼèláhá֖⁠ʼ di֣̇y bi⁠yrẇşĕ̌le֑m ki̇⁠kĕţá֖b sĕpa֥r mòşěֽh׃p"],[6,19,"וַ⁠יַּעֲשׂ֥וּ בְנֵי־הַ⁠גּוֹלָ֖ה אֶת־הַ⁠פָּ֑סַח בְּ⁠אַרְבָּעָ֥ה עָשָׂ֖ר לַ⁠חֹ֥דֶשׁ הָ⁠רִאשֽׁוֹן׃","wa⁠yȧʻàş֥̂ẇ bĕnéy-ha⁠ġwòlá֖h ʼeţ-ha⁠pá֑̇saẖ bĕ̇⁠ʼarĕbá̇ʻá֥h ʻáşá֖̂r la⁠ẖò֥deş̌ há⁠riʼşֽ̌wòn׃"],[6,20,"כִּ֣י הִֽטַּהֲר֞וּ הַ⁠כֹּהֲנִ֧ים וְ⁠הַ⁠לְוִיִּ֛ם כְּ⁠אֶחָ֖ד כֻּלָּ֣⁠ם טְהוֹרִ֑ים וַ⁠יִּשְׁחֲט֤וּ הַ⁠פֶּ֨סַח֙ לְ⁠כָל־בְּנֵ֣י הַ⁠גּוֹלָ֔ה וְ⁠לַ⁠אֲחֵי⁠הֶ֥ם הַ⁠כֹּהֲנִ֖ים וְ⁠לָ⁠הֶֽם׃","ki֣̇y hiֽtȧhàr֞ẇ ha⁠kò̇hàni֧ym wĕ⁠ha⁠lĕwiyi֛̇m kĕ̇⁠ʼeẖá֖d ku̇lá֣̇⁠m tĕhwòri֑ym wa⁠yi̇şĕ̌ẖàt֤ẇ ha⁠pė֨saẖ֙ lĕ⁠kál-bĕ̇né֣y ha⁠ġwòlá֔h wĕ⁠la⁠ʼàẖéy⁠he֥m ha⁠kò̇hàni֖ym wĕ⁠lá⁠heֽm׃"],[6,21,"וַ⁠יֹּאכְל֣וּ בְנֵֽי־יִשְׂרָאֵ֗ל הַ⁠שָּׁבִים֙ מֵֽ⁠הַ⁠גּוֹלָ֔ה וְ⁠כֹ֗ל הַ⁠נִּבְדָּ֛ל מִ⁠טֻּמְאַ֥ת גּוֹיֵֽ־הָ⁠אָ֖רֶץ אֲלֵ⁠הֶ֑ם לִ⁠דְרֹ֕שׁ לַֽ⁠יהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","wa⁠yò̇ʼkĕl֣ẇ bĕnéֽy-yişĕ̂ráʼé֗l ha⁠şá̇̌biym֙ méֽ⁠ha⁠ġwòlá֔h wĕ⁠kò֗l ha⁠ni̇bĕdá֛̇l mi⁠tu̇mĕʼa֥ţ ġwòyéֽ-há⁠ʼá֖reẕ ʼàlé⁠he֑m li⁠dĕrò֕ş̌ laֽ⁠yhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[6,22,"וַ⁠יַּֽעֲשׂ֧וּ חַג־מַצּ֛וֹת שִׁבְעַ֥ת יָמִ֖ים בְּ⁠שִׂמְחָ֑ה כִּ֣י ׀ שִׂמְּחָ֣⁠ם יְהוָ֗ה וְֽ⁠הֵסֵ֞ב לֵ֤ב מֶֽלֶךְ־אַשּׁוּר֙ עֲלֵי⁠הֶ֔ם לְ⁠חַזֵּ֣ק יְדֵי⁠הֶ֔ם בִּ⁠מְלֶ֥אכֶת בֵּית־הָ⁠אֱלֹהִ֖ים אֱלֹהֵ֥י יִשְׂרָאֵֽל׃פ","wa⁠yȧֽʻàş֧̂ẇ ẖag-maẕ֛̇wòţ şǐbĕʻa֥ţ yámi֖ym bĕ̇⁠şîmĕẖá֑h ki֣̇y ׀ şîmĕ̇ẖá֣⁠m yĕhwá֗h wĕֽ⁠hésé֞b lé֤b meֽlekĕ-ʼaş̇̌ẇr֙ ʻàléy⁠he֔m lĕ⁠ẖazé֣̇q yĕdéy⁠he֔m bi̇⁠mĕle֥ʼkeţ bé̇yţ-há⁠ʼèlòhi֖ym ʼèlòhé֥y yişĕ̂ráʼéֽl׃p"],[7,1,"וְ⁠אַחַר֙ הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה בְּ⁠מַלְכ֖וּת אַרְתַּחְשַׁ֣סְתְּא מֶֽלֶךְ־פָּרָ֑ס עֶזְרָא֙ בֶּן־שְׂרָיָ֔ה בֶּן־עֲזַרְיָ֖ה בֶּן־חִלְקִיָּֽה׃","wĕ⁠ʼaẖar֙ ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh bĕ̇⁠malĕk֖ẇţ ʼarĕţȧẖĕşǎ֣sĕţĕ̇ʼ meֽlekĕ-pá̇rá֑s ʻezĕráʼ֙ bėn-şĕ̂ráyá֔h bėn-ʻàzarĕyá֖h bėn-ẖilĕqiyáֽ̇h׃"],[7,2,"בֶּן־שַׁלּ֥וּם בֶּן־צָד֖וֹק בֶּן־אֲחִיטֽוּב׃","bėn-şǎl֥̇ẇm bėn-ẕád֖wòq bėn-ʼàẖiytֽẇb׃"],[7,3,"בֶּן־אֲמַרְיָ֥ה בֶן־עֲזַרְיָ֖ה בֶּן־מְרָיֽוֹת׃","bėn-ʼàmarĕyá֥h ben-ʻàzarĕyá֖h bėn-mĕráyֽwòţ׃"],[7,4,"בֶּן־זְרַֽחְיָ֥ה בֶן־עֻזִּ֖י בֶּן־בֻּקִּֽי׃","bėn-zĕraֽẖĕyá֥h ben-ʻuzi֖̇y bėn-bu̇qiֽ̇y׃"],[7,5,"בֶּן־אֲבִישׁ֗וּעַ בֶּן־פִּֽינְחָס֙ בֶּן־אֶלְעָזָ֔ר בֶּן־אַהֲרֹ֥ן הַ⁠כֹּהֵ֖ן הָ⁠רֹֽאשׁ׃","bėn-ʼàbiyş̌֗ẇʻa bėn-piֽ̇ynĕẖás֙ bėn-ʼelĕʻázá֔r bėn-ʼahàrò֥n ha⁠kò̇hé֖n há⁠ròֽʼş̌׃"],[7,6,"ה֤וּא עֶזְרָא֙ עָלָ֣ה מִ⁠בָּבֶ֔ל וְ⁠הֽוּא־סֹפֵ֤ר מָהִיר֙ בְּ⁠תוֹרַ֣ת מֹשֶׁ֔ה אֲשֶׁר־נָתַ֥ן יְהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל וַ⁠יִּתֶּן־ל֣⁠וֹ הַ⁠מֶּ֗לֶךְ כְּ⁠יַד־יְהוָ֤ה אֱלֹהָי⁠ו֙ עָלָ֔י⁠ו כֹּ֖ל בַּקָּשָׁתֽ⁠וֹ׃פ","h֤ẇʼ ʻezĕráʼ֙ ʻálá֣h mi⁠bá̇be֔l wĕ⁠hֽẇʼ-sòpé֤r máhiyr֙ bĕ̇⁠ţwòra֣ţ mòşě֔h ʼàşěr-náţa֥n yĕhwá֖h ʼèlòhé֣y yişĕ̂ráʼé֑l wa⁠yi̇ţėn-l֣⁠wò ha⁠mė֗lekĕ kĕ̇⁠yad-yĕhwá֤h ʼèlòháy⁠w֙ ʻálá֔y⁠w kò֖̇l bȧqá̇şá̌ţֽ⁠wò׃p"],[7,7,"וַ⁠יַּֽעֲל֣וּ מִ⁠בְּנֵֽי־יִ֠שְׂרָאֵל וּ⁠מִן־הַ⁠כֹּהֲנִ֨ים וְ⁠הַ⁠לְוִיִּ֜ם וְ⁠הַ⁠מְשֹׁרְרִ֧ים וְ⁠הַ⁠שֹּׁעֲרִ֛ים וְ⁠הַ⁠נְּתִינִ֖ים אֶל־יְרוּשָׁלִָ֑ם בִּ⁠שְׁנַת־שֶׁ֖בַע לְ⁠אַרְתַּחְשַׁ֥סְתְּא הַ⁠מֶּֽלֶךְ׃","wa⁠yȧֽʻàl֣ẇ mi⁠bĕ̇néֽy-yi֠şĕ̂ráʼél ẇ⁠min-ha⁠kò̇hàni֨ym wĕ⁠ha⁠lĕwiyi̇֜m wĕ⁠ha⁠mĕşò̌rĕri֧ym wĕ⁠ha⁠şò̇̌ʻàri֛ym wĕ⁠ha⁠nĕ̇ţiyni֖ym ʼel-yĕrẇşá̌liá֑m bi̇⁠şĕ̌naţ-şě֖baʻ lĕ⁠ʼarĕţȧẖĕşǎ֥sĕţĕ̇ʼ ha⁠mėֽlekĕ׃"],[7,8,"וַ⁠יָּבֹ֥א יְרוּשָׁלִַ֖ם בַּ⁠חֹ֣דֶשׁ הַ⁠חֲמִישִׁ֑י הִ֛יא שְׁנַ֥ת הַ⁠שְּׁבִיעִ֖ית לַ⁠מֶּֽלֶךְ׃","wa⁠yá̇bò֥ʼ yĕrẇşá̌lia֖m bȧ⁠ẖò֣deş̌ ha⁠ẖàmiyşǐ֑y hi֛yʼ şĕ̌na֥ţ ha⁠şĕ̇̌biyʻi֖yţ la⁠mėֽlekĕ׃"],[7,9,"כִּ֗י בְּ⁠אֶחָד֙ לַ⁠חֹ֣דֶשׁ הָ⁠רִאשׁ֔וֹן ה֣וּא יְסֻ֔ד הַֽ⁠מַּעֲלָ֖ה מִ⁠בָּבֶ֑ל וּ⁠בְ⁠אֶחָ֞ד לַ⁠חֹ֣דֶשׁ הַ⁠חֲמִישִׁ֗י בָּ֚א אֶל־יְר֣וּשָׁלִַ֔ם כְּ⁠יַד־אֱלֹהָ֖י⁠ו הַ⁠טּוֹבָ֥ה עָלָֽי⁠ו׃","ki̇֗y bĕ̇⁠ʼeẖád֙ la⁠ẖò֣deş̌ há⁠riʼş̌֔wòn h֣ẇʼ yĕsu֔d haֽ⁠mȧʻàlá֖h mi⁠bá̇be֑l ẇ⁠bĕ⁠ʼeẖá֞d la⁠ẖò֣deş̌ ha⁠ẖàmiyşǐ֗y bá֚̇ʼ ʼel-yĕr֣ẇşá̌lia֔m kĕ̇⁠yad-ʼèlòhá֖y⁠w ha⁠ṫwòbá֥h ʻáláֽy⁠w׃"],[7,10,"כִּ֤י עֶזְרָא֙ הֵכִ֣ין לְבָב֔⁠וֹ לִ⁠דְר֛וֹשׁ אֶת־תּוֹרַ֥ת יְהוָ֖ה וְ⁠לַ⁠עֲשֹׂ֑ת וּ⁠לְ⁠לַמֵּ֥ד בְּ⁠יִשְׂרָאֵ֖ל חֹ֥ק וּ⁠מִשְׁפָּֽט׃ס","ki֤̇y ʻezĕráʼ֙ héki֣yn lĕbáb֔⁠wò li⁠dĕr֛wòş̌ ʼeţ-ţ̇wòra֥ţ yĕhwá֖h wĕ⁠la⁠ʻàşò֑̂ţ ẇ⁠lĕ⁠lamé֥̇d bĕ̇⁠yişĕ̂ráʼé֖l ẖò֥q ẇ⁠mişĕ̌páֽ̇t׃s"],[7,11,"וְ⁠זֶ֣ה ׀ פַּרְשֶׁ֣גֶן הַֽ⁠נִּשְׁתְּוָ֗ן אֲשֶׁ֤ר נָתַן֙ הַ⁠מֶּ֣לֶךְ אַרְתַּחְשַׁ֔סְתְּא לְ⁠עֶזְרָ֥א הַ⁠כֹּהֵ֖ן הַ⁠סֹּפֵ֑ר סֹפֵ֞ר דִּבְרֵ֧י מִצְוֺת־יְהוָ֛ה וְ⁠חֻקָּ֖י⁠ו עַל־יִשְׂרָאֵֽל׃פ","wĕ⁠ze֣h ׀ pȧrĕşě֣gen haֽ⁠ni̇şĕ̌ţĕ̇wá֗n ʼàşě֤r náţan֙ ha⁠mė֣lekĕ ʼarĕţȧẖĕşǎ֔sĕţĕ̇ʼ lĕ⁠ʻezĕrá֥ʼ ha⁠kò̇hé֖n ha⁠sò̇pé֑r sòpé֞r di̇bĕré֧y miẕĕwֺţ-yĕhwá֛h wĕ⁠ẖuqá֖̇y⁠w ʻal-yişĕ̂ráʼéֽl׃p"],[7,12,"אַ֨רְתַּחְשַׁ֔סְתְּא מֶ֖לֶךְ מַלְכַיָּ֑⁠א לְ⁠עֶזְרָ֣א כָ֠הֲנָ⁠א סָפַ֨ר דָּתָ֜⁠א דִּֽי־אֱלָ֧הּ שְׁמַיָּ֛⁠א גְּמִ֖יר וּ⁠כְעֶֽנֶת׃","ʼa֨rĕţȧẖĕşǎ֔sĕţĕ̇ʼ me֖lekĕ malĕkayá֑̇⁠ʼ lĕ⁠ʻezĕrá֣ʼ ká֠hàná⁠ʼ sápa֨r dá̇ţá֜⁠ʼ diֽ̇y-ʼèlá֧ḣ şĕ̌mayá֛̇⁠ʼ gĕ̇mi֖yr ẇ⁠kĕʻeֽneţ׃"],[7,13,"מִנִּ⁠י֮ שִׂ֣ים טְעֵם֒ דִּ֣י כָל־מִתְנַדַּ֣ב בְּ⁠מַלְכוּתִ⁠י֩ מִן־עַמָּ֨⁠ה יִשְׂרָאֵ֜ל וְ⁠כָהֲנ֣וֹ⁠הִי וְ⁠לֵוָיֵ֗⁠א לִ⁠מְהָ֧ךְ לִֽ⁠ירוּשְׁלֶ֛ם עִמָּ֖⁠ךְ יְהָֽךְ׃","mini̇⁠y֮ şî֣ym tĕʻém֒ di֣̇y kál-miţĕnadȧ֣b bĕ̇⁠malĕkẇţi⁠y֩ min-ʻamá̇֨⁠h yişĕ̂ráʼé֜l wĕ⁠káhàn֣wò⁠hiy wĕ⁠léwáyé֗⁠ʼ li⁠mĕhá֧kĕ liֽ⁠yrẇşĕ̌le֛m ʻimá֖̇⁠kĕ yĕháֽkĕ׃"],[7,14,"כָּ⁠ל־קֳבֵ֗ל דִּי֩ מִן־קֳדָ֨ם מַלְכָּ֜⁠א וְ⁠שִׁבְעַ֤ת יָעֲטֹ֨⁠הִי֙ שְׁלִ֔יחַ לְ⁠בַקָּרָ֥א עַל־יְה֖וּד וְ⁠לִֽ⁠ירוּשְׁלֶ֑ם בְּ⁠דָ֥ת אֱלָהָ֖⁠ךְ דִּ֥י בִ⁠ידָֽ⁠ךְ׃","ká̇⁠l-qobé֗l di̇y֩ min-qodá֨m malĕká̇֜⁠ʼ wĕ⁠şǐbĕʻa֤ţ yáʻàtò֨⁠hiy֙ şĕ̌li֔yẖa lĕ⁠baqá̇rá֥ʼ ʻal-yĕh֖ẇd wĕ⁠liֽ⁠yrẇşĕ̌le֑m bĕ̇⁠dá֥ţ ʼèláhá֖⁠kĕ di֥̇y bi⁠ydáֽ⁠kĕ׃"],[7,15,"וּ⁠לְ⁠הֵיבָלָ֖ה כְּסַ֣ף וּ⁠דְהַ֑ב דִּֽי־מַלְכָּ֣⁠א וְ⁠יָעֲט֗וֹ⁠הִי הִתְנַדַּ֨בוּ֙ לֶ⁠אֱלָ֣הּ יִשְׂרָאֵ֔ל דִּ֥י בִֽ⁠ירוּשְׁלֶ֖ם מִשְׁכְּנֵֽ⁠הּ׃","ẇ⁠lĕ⁠héybálá֖h kĕ̇sa֣p ẇ⁠dĕha֑b diֽ̇y-malĕká֣̇⁠ʼ wĕ⁠yáʻàt֗wò⁠hiy hiţĕnadȧ֨bẇ֙ le⁠ʼèlá֣ḣ yişĕ̂ráʼé֔l di֥̇y biֽ⁠yrẇşĕ̌le֖m mişĕ̌kĕ̇néֽ⁠ḣ׃"],[7,16,"וְ⁠כֹל֙ כְּסַ֣ף וּ⁠דְהַ֔ב דִּ֣י תְהַשְׁכַּ֔ח בְּ⁠כֹ֖ל מְדִינַ֣ת בָּבֶ֑ל עִם֩ הִתְנַדָּב֨וּת עַמָּ֤⁠א וְ⁠כָֽהֲנַיָּ⁠א֙ מִֽתְנַדְּבִ֔ין לְ⁠בֵ֥ית אֱלָהֲ⁠הֹ֖ם דִּ֥י בִ⁠ירוּשְׁלֶֽם׃","wĕ⁠kòl֙ kĕ̇sa֣p ẇ⁠dĕha֔b di֣̇y ţĕhaşĕ̌kȧ֔ẖ bĕ̇⁠kò֖l mĕdiyna֣ţ bá̇be֑l ʻim֩ hiţĕnadá̇b֨ẇţ ʻamá֤̇⁠ʼ wĕ⁠káֽhànayá̇⁠ʼ֙ miֽţĕnadĕ̇bi֔yn lĕ⁠bé֥yţ ʼèláhà⁠hò֖m di֥̇y bi⁠yrẇşĕ̌leֽm׃"],[7,17,"כָּ⁠ל־קֳבֵ֣ל דְּנָה֩ אָסְפַּ֨רְנָא תִקְנֵ֜א בְּ⁠כַסְפָּ֣⁠א דְנָ֗ה תּוֹרִ֤ין ׀ דִּכְרִין֙ אִמְּרִ֔ין וּ⁠מִנְחָתְ⁠ה֖וֹן וְ⁠נִסְכֵּי⁠ה֑וֹן וּ⁠תְקָרֵ֣ב הִמּ֔וֹ עַֽל־מַדְבְּחָ֔⁠ה דִּ֛י בֵּ֥ית אֱלָהֲ⁠כֹ֖ם דִּ֥י בִ⁠ירוּשְׁלֶֽם׃","ká̇⁠l-qobé֣l dĕ̇náh֩ ʼásĕpȧ֨rĕnáʼ ţiqĕné֜ʼ bĕ̇⁠kasĕpá֣̇⁠ʼ dĕná֗h ţ̇wòri֤yn ׀ di̇kĕriyn֙ ʼimĕ̇ri֔yn ẇ⁠minĕẖáţĕ⁠h֖wòn wĕ⁠nisĕké̇y⁠h֑wòn ẇ⁠ţĕqáré֣b hiṁ֔wò ʻaֽl-madĕbĕ̇ẖá֔⁠h di֛̇y bé֥̇yţ ʼèláhà⁠kò֖m di֥̇y bi⁠yrẇşĕ̌leֽm׃"],[7,18,"וּ⁠מָ֣ה דִי֩ עלי⁠ך וְ⁠עַל־אחי⁠ך יֵיטַ֗ב בִּ⁠שְׁאָ֛ר כַּסְפָּ֥⁠א וְ⁠דַהֲבָ֖⁠ה לְ⁠מֶעְבַּ֑ד כִּ⁠רְע֥וּת אֱלָהֲ⁠כֹ֖ם תַּעַבְדֽוּן׃","ẇ⁠má֣h diy֩ ʻly⁠k wĕ⁠ʻal-ʼẖy⁠k yéyta֗b bi̇⁠şĕ̌ʼá֛r kȧsĕpá֥̇⁠ʼ wĕ⁠dahàbá֖⁠h lĕ⁠meʻĕbȧ֑d ki̇⁠rĕʻ֥ẇţ ʼèláhà⁠kò֖m ţȧʻabĕdֽẇn׃"],[7,19,"וּ⁠מָֽאנַיָּ⁠א֙ דִּֽי־מִתְיַהֲבִ֣ין לָ֔⁠ךְ לְ⁠פָלְחָ֖ן בֵּ֣ית אֱלָהָ֑⁠ךְ הַשְׁלֵ֕ם קֳדָ֖ם אֱלָ֥הּ יְרוּשְׁלֶֽם׃","ẇ⁠máֽʼnayá̇⁠ʼ֙ diֽ̇y-miţĕyahàbi֣yn lá֔⁠kĕ lĕ⁠pálĕẖá֖n bé֣̇yţ ʼèláhá֑⁠kĕ haşĕ̌lé֕m qodá֖m ʼèlá֥ḣ yĕrẇşĕ̌leֽm׃"],[7,20,"וּ⁠שְׁאָ֗ר חַשְׁחוּת֙ בֵּ֣ית אֱלָהָ֔⁠ךְ דִּ֥י יִפֶּל־לָ֖⁠ךְ לְ⁠מִנְתַּ֑ן תִּנְתֵּ֕ן מִן־בֵּ֖ית גִּנְזֵ֥י מַלְכָּֽ⁠א׃","ẇ⁠şĕ̌ʼá֗r ẖaşĕ̌ẖẇţ֙ bé֣̇yţ ʼèláhá֔⁠kĕ di֥̇y yipėl-lá֖⁠kĕ lĕ⁠minĕţȧ֑n ţi̇nĕţé̇֕n min-bé֖̇yţ gi̇nĕzé֥y malĕkáֽ̇⁠ʼ׃"],[7,21,"וּ֠⁠מִנִּ⁠י אֲנָ֞ה אַרְתַּחְשַׁ֤סְתְּא מַלְכָּ⁠א֙ שִׂ֣ים טְעֵ֔ם לְ⁠כֹל֙ גִּזַּֽבְרַיָּ֔⁠א דִּ֖י בַּ⁠עֲבַ֣ר נַהֲרָ֑⁠ה דִּ֣י כָל־דִּ֣י יִ֠שְׁאֲלֶנְ⁠כוֹן עֶזְרָ֨א כָהֲנָ֜⁠ה סָפַ֤ר דָּתָ⁠א֙ דִּֽי־אֱלָ֣הּ שְׁמַיָּ֔⁠א אָסְפַּ֖רְנָא יִתְעֲבִֽד׃","ẇ֠⁠mini̇⁠y ʼàná֞h ʼarĕţȧẖĕşǎ֤sĕţĕ̇ʼ malĕká̇⁠ʼ֙ şî֣ym tĕʻé֔m lĕ⁠kòl֙ gi̇zȧֽbĕrayá̇֔⁠ʼ di֖̇y bȧ⁠ʻàba֣r nahàrá֑⁠h di֣̇y kál-di֣̇y yi֠şĕ̌ʼàlenĕ⁠kwòn ʻezĕrá֨ʼ káhàná֜⁠h sápa֤r dá̇ţá⁠ʼ֙ diֽ̇y-ʼèlá֣ḣ şĕ̌mayá̇֔⁠ʼ ʼásĕpȧ֖rĕnáʼ yiţĕʻàbiֽd׃"],[7,22,"עַד־כְּסַף֮ כַּכְּרִ֣ין מְאָה֒ וְ⁠עַד־חִנְטִין֙ כֹּרִ֣ין מְאָ֔ה וְ⁠עַד־חֲמַר֙ בַּתִּ֣ין מְאָ֔ה וְ⁠עַד־בַּתִּ֥ין מְשַׁ֖ח מְאָ֑ה וּ⁠מְלַ֖ח דִּי־לָ֥א כְתָֽב׃","ʻad-kĕ̇sap֮ kȧkĕ̇ri֣yn mĕʼáh֒ wĕ⁠ʻad-ẖinĕtiyn֙ kò̇ri֣yn mĕʼá֔h wĕ⁠ʻad-ẖàmar֙ bȧţi֣̇yn mĕʼá֔h wĕ⁠ʻad-bȧţi֥̇yn mĕşǎ֖ẖ mĕʼá֑h ẇ⁠mĕla֖ẖ di̇y-lá֥ʼ kĕţáֽb׃"],[7,23,"כָּל־דִּ֗י מִן־טַ֨עַם֙ אֱלָ֣הּ שְׁמַיָּ֔⁠א יִתְעֲבֵד֙ אַדְרַזְדָּ֔א לְ⁠בֵ֖ית אֱלָ֣הּ שְׁמַיָּ֑⁠א דִּֽי־לְ⁠מָ֤ה לֶֽהֱוֵא֙ קְצַ֔ף עַל־מַלְכ֥וּת מַלְכָּ֖⁠א וּ⁠בְנֽוֹ⁠הִי׃","ká̇l-di̇֗y min-ta֨ʻam֙ ʼèlá֣ḣ şĕ̌mayá̇֔⁠ʼ yiţĕʻàbéd֙ ʼadĕrazĕdá̇֔ʼ lĕ⁠bé֖yţ ʼèlá֣ḣ şĕ̌mayá֑̇⁠ʼ diֽ̇y-lĕ⁠má֤h leֽhèwéʼ֙ qĕẕa֔p ʻal-malĕk֥ẇţ malĕká֖̇⁠ʼ ẇ⁠bĕnֽwò⁠hiy׃"],[7,24,"וּ⁠לְ⁠כֹ֣ם מְהוֹדְעִ֗ין דִּ֣י כָל־כָּהֲנַיָּ֣⁠א וְ֠⁠לֵוָיֵ⁠א זַמָּ֨רַיָּ֤⁠א תָרָֽעַיָּ⁠א֙ נְתִ֣ינַיָּ֔⁠א וּ⁠פָ֣לְחֵ֔י בֵּ֖ית אֱלָהָ֣⁠א דְנָ֑ה מִנְדָּ֤ה בְלוֹ֙ וַ⁠הֲלָ֔ךְ לָ֥א שַׁלִּ֖יט לְ⁠מִרְמֵ֥א עֲלֵי⁠הֹֽם׃","ẇ⁠lĕ⁠kò֣m mĕhwòdĕʻi֗yn di֣̇y kál-ká̇hànayá֣̇⁠ʼ wĕ֠⁠léwáyé⁠ʼ zamá̇֨rayá֤̇⁠ʼ ţáráֽʻayá̇⁠ʼ֙ nĕţi֣ynayá̇֔⁠ʼ ẇ⁠pá֣lĕẖé֔y bé֖̇yţ ʼèláhá֣⁠ʼ dĕná֑h minĕdá֤̇h bĕlwò֙ wa⁠hàlá֔kĕ lá֥ʼ şǎli֖̇yt lĕ⁠mirĕmé֥ʼ ʻàléy⁠hòֽm׃"],[7,25,"וְ⁠אַ֣נְתְּ עֶזְרָ֗א כְּ⁠חָכְמַ֨ת אֱלָהָ֤⁠ךְ דִּֽי־בִ⁠ידָ⁠ךְ֙ מֶ֣נִּי שָׁפְטִ֞ין וְ⁠דַיָּנִ֗ין דִּי־לֶהֱוֺ֤ן דאנין לְ⁠כָל־עַמָּ⁠ה֙ דִּ֚י בַּ⁠עֲבַ֣ר נַהֲרָ֔⁠ה לְ⁠כָל־יָדְעֵ֖י דָּתֵ֣י אֱלָהָ֑⁠ךְ וְ⁠דִ֧י לָ֦א יָדַ֖ע תְּהוֹדְעֽוּן׃","wĕ⁠ʼa֣nĕţĕ̇ ʻezĕrá֗ʼ kĕ̇⁠ẖákĕma֨ţ ʼèláhá֤⁠kĕ diֽ̇y-bi⁠ydá⁠kĕ֙ me֣ni̇y şá̌pĕti֞yn wĕ⁠dayá̇ni֗yn di̇y-lehèwֺ֤n dʼnyn lĕ⁠kál-ʻamá̇⁠h֙ di֚̇y bȧ⁠ʻàba֣r nahàrá֔⁠h lĕ⁠kál-yádĕʻé֖y dá̇ţé֣y ʼèláhá֑⁠kĕ wĕ⁠di֧y lá֦ʼ yáda֖ʻ ţĕ̇hwòdĕʻֽẇn׃"],[7,26,"וְ⁠כָל־דִּי־לָא֩ לֶהֱוֵ֨א עָבֵ֜ד דָּתָ֣⁠א דִֽי־אֱלָהָ֗⁠ךְ וְ⁠דָתָ⁠א֙ דִּ֣י מַלְכָּ֔⁠א אָסְפַּ֕רְנָא דִּינָ֕⁠ה לֶהֱוֵ֥א מִתְעֲבֵ֖ד מִנֵּ֑⁠הּ הֵ֤ן לְ⁠מוֹת֙ הֵ֣ן ל⁠שרשו הֵן־לַ⁠עֲנָ֥שׁ נִכְסִ֖ין וְ⁠לֶ⁠אֱסוּרִֽין׃פ","wĕ⁠kál-di̇y-láʼ֩ lehèwé֨ʼ ʻábé֜d dá̇ţá֣⁠ʼ diֽy-ʼèláhá֗⁠kĕ wĕ⁠dáţá⁠ʼ֙ di֣̇y malĕká̇֔⁠ʼ ʼásĕpȧ֕rĕnáʼ di̇yná֕⁠h lehèwé֥ʼ miţĕʻàbé֖d miné֑̇⁠ḣ hé֤n lĕ⁠mwòţ֙ hé֣n l⁠şrşw hén-la⁠ʻàná֥ş̌ nikĕsi֖yn wĕ⁠le⁠ʼèsẇriֽyn׃p"],[7,27,"בָּר֥וּךְ יְהוָ֖ה אֱלֹהֵ֣י אֲבוֹתֵ֑י⁠נוּ אֲשֶׁ֨ר נָתַ֤ן כָּ⁠זֹאת֙ בְּ⁠לֵ֣ב הַ⁠מֶּ֔לֶךְ לְ⁠פָאֵ֕ר אֶת־בֵּ֥ית יְהוָ֖ה אֲשֶׁ֥ר בִּ⁠ירוּשָׁלִָֽם׃","bá̇r֥ẇkĕ yĕhwá֖h ʼèlòhé֣y ʼàbwòţé֑y⁠nẇ ʼàşě֨r náţa֤n ká̇⁠zòʼţ֙ bĕ̇⁠lé֣b ha⁠mė֔lekĕ lĕ⁠páʼé֕r ʼeţ-bé֥̇yţ yĕhwá֖h ʼàşě֥r bi̇⁠yrẇşá̌liáֽm׃"],[7,28,"וְ⁠עָלַ֣⁠י הִטָּה־חֶ֗סֶד לִ⁠פְנֵ֤י הַ⁠מֶּ֨לֶךְ֙ וְ⁠יֽוֹעֲצָ֔י⁠ו וּ⁠לְ⁠כָל־שָׂרֵ֥י הַ⁠מֶּ֖לֶךְ הַ⁠גִּבֹּרִ֑ים וַ⁠אֲנִ֣י הִתְחַזַּ֗קְתִּי כְּ⁠יַד־יְהוָ֤ה אֱלֹהַ⁠י֙ עָלַ֔⁠י וָ⁠אֶקְבְּצָ֧⁠ה מִ⁠יִּשְׂרָאֵ֛ל רָאשִׁ֖ים לַ⁠עֲל֥וֹת עִמִּֽ⁠י׃פ","wĕ⁠ʻála֣⁠y hitá̇h-ẖe֗sed li⁠pĕné֤y ha⁠mė֨lekĕ֙ wĕ⁠yֽwòʻàẕá֔y⁠w ẇ⁠lĕ⁠kál-şá̂ré֥y ha⁠mė֖lekĕ ha⁠gi̇bò̇ri֑ym wa⁠ʼàni֣y hiţĕẖazȧ֗qĕţi̇y kĕ̇⁠yad-yĕhwá֤h ʼèlòha⁠y֙ ʻála֔⁠y wá⁠ʼeqĕbĕ̇ẕá֧⁠h mi⁠yi̇şĕ̂ráʼé֛l ráʼşǐ֖ym la⁠ʻàl֥wòţ ʻimiֽ̇⁠y׃p"],[8,1,"וְ⁠אֵ֛לֶּה רָאשֵׁ֥י אֲבֹתֵי⁠הֶ֖ם וְ⁠הִתְיַחְשָׂ֑⁠ם הָ⁠עֹלִ֣ים עִמִּ֗⁠י בְּ⁠מַלְכ֛וּת אַרְתַּחְשַׁ֥סְתְּא הַ⁠מֶּ֖לֶךְ מִ⁠בָּבֶֽל׃ס","wĕ⁠ʼé֛lėh ráʼşé֥̌y ʼàbòţéy⁠he֖m wĕ⁠hiţĕyaẖĕşá֑̂⁠m há⁠ʻòli֣ym ʻimi̇֗⁠y bĕ̇⁠malĕk֛ẇţ ʼarĕţȧẖĕşǎ֥sĕţĕ̇ʼ ha⁠mė֖lekĕ mi⁠bá̇beֽl׃s"],[8,2,"מִ⁠בְּנֵ֤י פִֽינְחָס֙ גֵּֽרְשֹׁ֔ם ס מִ⁠בְּנֵ֥י אִיתָמָ֖ר דָּנִיֵּ֑אל ס מִ⁠בְּנֵ֥י דָוִ֖יד חַטּֽוּשׁ׃ס","mi⁠bĕ̇né֤y piֽynĕẖás֙ géֽ̇rĕşò̌֔m s mi⁠bĕ̇né֥y ʼiyţámá֖r dá̇niyé֑̇ʼl s mi⁠bĕ̇né֥y dáwi֖yd ẖaṫֽẇş̌׃s"],[8,3,"מִ⁠בְּנֵ֣י שְׁכַנְיָ֔ה ס מִ⁠בְּנֵ֥י פַרְעֹ֖שׁ זְכַרְיָ֑ה וְ⁠עִמּ֛⁠וֹ הִתְיַחֵ֥שׂ לִ⁠זְכָרִ֖ים מֵאָ֥ה וַ⁠חֲמִשִּֽׁים׃ס","mi⁠bĕ̇né֣y şĕ̌kanĕyá֔h s mi⁠bĕ̇né֥y parĕʻò֖ş̌ zĕkarĕyá֑h wĕ⁠ʻiṁ֛⁠wò hiţĕyaẖé֥ş̂ li⁠zĕkári֖ym méʼá֥h wa⁠ẖàmişiֽ̇̌ym׃s"],[8,4,"מִ⁠בְּנֵי֙ פַּחַ֣ת מוֹאָ֔ב אֶלְיְהֽוֹעֵינַ֖י בֶּן־זְרַֽחְיָ֑ה וְ⁠עִמּ֖⁠וֹ מָאתַ֥יִם הַ⁠זְּכָרִֽים׃ס","mi⁠bĕ̇néy֙ pȧẖa֣ţ mwòʼá֔b ʼelĕyĕhֽwòʻéyna֖y bėn-zĕraֽẖĕyá֑h wĕ⁠ʻiṁ֖⁠wò máʼţa֥yim ha⁠zĕ̇káriֽym׃s"],[8,5,"מִ⁠בְּנֵ֥י שְׁכַנְיָ֖ה בֶּן־יַחֲזִיאֵ֑ל וְ⁠עִמּ֕⁠וֹ שְׁלֹ֥שׁ מֵא֖וֹת הַ⁠זְּכָרִֽים׃ס","mi⁠bĕ̇né֥y şĕ̌kanĕyá֖h bėn-yaẖàziyʼé֑l wĕ⁠ʻiṁ֕⁠wò şĕ̌lò֥ş̌ méʼ֖wòţ ha⁠zĕ̇káriֽym׃s"],[8,6,"וּ⁠מִ⁠בְּנֵ֣י עָדִ֔ין עֶ֖בֶד בֶּן־יוֹנָתָ֑ן וְ⁠עִמּ֖⁠וֹ חֲמִשִּׁ֥ים הַ⁠זְּכָרִֽים׃ס","ẇ⁠mi⁠bĕ̇né֣y ʻádi֔yn ʻe֖bed bėn-ywònáţá֑n wĕ⁠ʻiṁ֖⁠wò ẖàmişi֥̇̌ym ha⁠zĕ̇káriֽym׃s"],[8,7,"וּ⁠מִ⁠בְּנֵ֣י עֵילָ֔ם יְשַֽׁעְיָ֖ה בֶּן־עֲתַלְיָ֑ה וְ⁠עִמּ֖⁠וֹ שִׁבְעִ֥ים הַ⁠זְּכָרִֽים׃ס","ẇ⁠mi⁠bĕ̇né֣y ʻéylá֔m yĕşǎֽʻĕyá֖h bėn-ʻàţalĕyá֑h wĕ⁠ʻiṁ֖⁠wò şǐbĕʻi֥ym ha⁠zĕ̇káriֽym׃s"],[8,8,"וּ⁠מִ⁠בְּנֵ֣י שְׁפַטְיָ֔ה זְבַדְיָ֖ה בֶּן־מִֽיכָאֵ֑ל וְ⁠עִמּ֖⁠וֹ שְׁמֹנִ֥ים הַ⁠זְּכָרִֽים׃ס","ẇ⁠mi⁠bĕ̇né֣y şĕ̌patĕyá֔h zĕbadĕyá֖h bėn-miֽykáʼé֑l wĕ⁠ʻiṁ֖⁠wò şĕ̌mòni֥ym ha⁠zĕ̇káriֽym׃s"],[8,9,"מִ⁠בְּנֵ֣י יוֹאָ֔ב עֹבַדְיָ֖ה בֶּן־יְחִיאֵ֑ל וְ⁠עִמּ֕⁠וֹ מָאתַ֛יִם וּ⁠שְׁמֹנָ֥ה עָשָׂ֖ר הַ⁠זְּכָרִֽים׃ס","mi⁠bĕ̇né֣y ywòʼá֔b ʻòbadĕyá֖h bėn-yĕẖiyʼé֑l wĕ⁠ʻiṁ֕⁠wò máʼţa֛yim ẇ⁠şĕ̌mòná֥h ʻáşá֖̂r ha⁠zĕ̇káriֽym׃s"],[8,10,"וּ⁠מִ⁠בְּנֵ֥י שְׁלוֹמִ֖ית בֶּן־יוֹסִפְיָ֑ה וְ⁠עִמּ֕⁠וֹ מֵאָ֥ה וְ⁠שִׁשִּׁ֖ים הַ⁠זְּכָרִֽים׃ס","ẇ⁠mi⁠bĕ̇né֥y şĕ̌lwòmi֖yţ bėn-ywòsipĕyá֑h wĕ⁠ʻiṁ֕⁠wò méʼá֥h wĕ⁠şǐşi֖̇̌ym ha⁠zĕ̇káriֽym׃s"],[8,11,"וּ⁠מִ⁠בְּנֵ֣י בֵבַ֔י זְכַרְיָ֖ה בֶּן־בֵּבָ֑י וְ⁠עִמּ֕⁠וֹ עֶשְׂרִ֥ים וּ⁠שְׁמֹנָ֖ה הַ⁠זְּכָרִֽים׃ס","ẇ⁠mi⁠bĕ̇né֣y béba֔y zĕkarĕyá֖h bėn-bé̇bá֑y wĕ⁠ʻiṁ֕⁠wò ʻeşĕ̂ri֥ym ẇ⁠şĕ̌mòná֖h ha⁠zĕ̇káriֽym׃s"],[8,12,"וּ⁠מִ⁠בְּנֵ֣י עַזְגָּ֔ד יוֹחָנָ֖ן בֶּן־הַ⁠קָּטָ֑ן וְ⁠עִמּ֕⁠וֹ מֵאָ֥ה וַ⁠עֲשָׂרָ֖ה הַ⁠זְּכָרִֽים׃ס","ẇ⁠mi⁠bĕ̇né֣y ʻazĕgá̇֔d ywòẖáná֖n bėn-ha⁠qá̇tá֑n wĕ⁠ʻiṁ֕⁠wò méʼá֥h wa⁠ʻàşá̂rá֖h ha⁠zĕ̇káriֽym׃s"],[8,13,"וּ⁠מִ⁠בְּנֵ֣י אֲדֹנִיקָם֮ אַחֲרֹנִים֒ וְ⁠אֵ֣לֶּה שְׁמוֹתָ֔⁠ם אֱלִיפֶ֖לֶט יְעִיאֵ֣ל וּֽ⁠שְׁמַעְיָ֑ה וְ⁠עִמָּ⁠הֶ֖ם שִׁשִּׁ֥ים הַ⁠זְּכָרִֽים׃ס","ẇ⁠mi⁠bĕ̇né֣y ʼàdòniyqám֮ ʼaẖàròniym֒ wĕ⁠ʼé֣lėh şĕ̌mwòţá֔⁠m ʼèliype֖let yĕʻiyʼé֣l ẇֽ⁠şĕ̌maʻĕyá֑h wĕ⁠ʻimá̇⁠he֖m şǐşi֥̇̌ym ha⁠zĕ̇káriֽym׃s"],[8,14,"וּ⁠מִ⁠בְּנֵ֥י בִגְוַ֖י עוּתַ֣י ו⁠זבוד וְ⁠עִמּ֖⁠וֹ שִׁבְעִ֥ים הַ⁠זְּכָרִֽים׃פ","ẇ⁠mi⁠bĕ̇né֥y bigĕwa֖y ʻẇţa֣y w⁠zbwd wĕ⁠ʻiṁ֖⁠wò şǐbĕʻi֥ym ha⁠zĕ̇káriֽym׃p"],[8,15,"וָֽ⁠אֶקְבְּצֵ֗⁠ם אֶל־הַ⁠נָּהָר֙ הַ⁠בָּ֣א אֶֽל־אַהֲוָ֔א וַ⁠נַּחֲנֶ֥ה שָׁ֖ם יָמִ֣ים שְׁלֹשָׁ֑ה וָ⁠אָבִ֤ינָ⁠ה בָ⁠עָם֙ וּ⁠בַ⁠כֹּ֣הֲנִ֔ים וּ⁠מִ⁠בְּנֵ֥י לֵוִ֖י לֹא־מָצָ֥אתִי שָֽׁם׃","wáֽ⁠ʼeqĕbĕ̇ẕé֗⁠m ʼel-ha⁠ná̇hár֙ ha⁠bá֣̇ʼ ʼeֽl-ʼahàwá֔ʼ wa⁠nȧẖàne֥h şá֖̌m yámi֣ym şĕ̌lòşá֑̌h wá⁠ʼábi֤yná⁠h bá⁠ʻám֙ ẇ⁠ba⁠kò֣̇hàni֔ym ẇ⁠mi⁠bĕ̇né֥y léwi֖y lòʼ-máẕá֥ʼţiy şáֽ̌m׃"],[8,16,"וָ⁠אֶשְׁלְחָ֡⁠ה לֶ⁠אֱלִיעֶ֡זֶר לַ⁠אֲרִיאֵ֡ל לִֽ֠⁠שְׁמַעְיָה וּ⁠לְ⁠אֶלְנָתָ֨ן וּ⁠לְ⁠יָרִ֜יב וּ⁠לְ⁠אֶלְנָתָ֧ן וּ⁠לְ⁠נָתָ֛ן וְ⁠לִ⁠זְכַרְיָ֥ה וְ⁠לִ⁠מְשֻׁלָּ֖ם רָאשִׁ֑ים וּ⁠לְ⁠יוֹיָרִ֥יב וּ⁠לְ⁠אֶלְנָתָ֖ן מְבִינִֽים׃","wá⁠ʼeşĕ̌lĕẖá֡⁠h le⁠ʼèliyʻe֡zer la⁠ʼàriyʼé֡l liֽ֠⁠şĕ̌maʻĕyáh ẇ⁠lĕ⁠ʼelĕnáţá֨n ẇ⁠lĕ⁠yári֜yb ẇ⁠lĕ⁠ʼelĕnáţá֧n ẇ⁠lĕ⁠náţá֛n wĕ⁠li⁠zĕkarĕyá֥h wĕ⁠li⁠mĕşǔlá֖̇m ráʼşǐ֑ym ẇ⁠lĕ⁠ywòyári֥yb ẇ⁠lĕ⁠ʼelĕnáţá֖n mĕbiyniֽym׃"],[8,17,"ו⁠אוצא⁠ה אוֹתָ⁠ם֙ עַל־אִדּ֣וֹ הָ⁠רֹ֔אשׁ בְּ⁠כָסִפְיָ֖א הַ⁠מָּק֑וֹם וָ⁠אָשִׂימָ⁠ה֩ בְּ⁠פִי⁠הֶ֨ם דְּבָרִ֜ים לְ֠⁠דַבֵּר אֶל־אִדּ֨וֹ אָחִ֤י⁠ו ה⁠נתונים בְּ⁠כָסִפְיָ֣א הַ⁠מָּק֔וֹם לְ⁠הָֽבִיא־לָ֥⁠נוּ מְשָׁרְתִ֖ים לְ⁠בֵ֥ית אֱלֹהֵֽי⁠נוּ׃","w⁠ʼwẕʼ⁠h ʼwòţá⁠m֙ ʻal-ʼiḋ֣wò há⁠rò֔ʼş̌ bĕ̇⁠kásipĕyá֖ʼ ha⁠má̇q֑wòm wá⁠ʼáşîymá⁠h֩ bĕ̇⁠piy⁠he֨m dĕ̇bári֜ym lĕ֠⁠dabé̇r ʼel-ʼiḋ֨wò ʼáẖi֤y⁠w h⁠nţwnym bĕ̇⁠kásipĕyá֣ʼ ha⁠má̇q֔wòm lĕ⁠háֽbiyʼ-lá֥⁠nẇ mĕşá̌rĕţi֖ym lĕ⁠bé֥yţ ʼèlòhéֽy⁠nẇ׃"],[8,18,"וַ⁠יָּבִ֨יאּוּ לָ֜⁠נוּ כְּ⁠יַד־אֱלֹהֵ֨י⁠נוּ הַ⁠טּוֹבָ֤ה עָלֵ֨י⁠נוּ֙ אִ֣ישׁ שֶׂ֔כֶל מִ⁠בְּנֵ֣י מַחְלִ֔י בֶּן־לֵוִ֖י בֶּן־יִשְׂרָאֵ֑ל וְ⁠שֵׁרֵֽבְיָ֛ה וּ⁠בָנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁמֹנָ֥ה עָשָֽׂר׃","wa⁠yá̇bi֨yʼ̇ẇ lá֜⁠nẇ kĕ̇⁠yad-ʼèlòhé֨y⁠nẇ ha⁠ṫwòbá֤h ʻálé֨y⁠nẇ֙ ʼi֣yş̌ şê֔kel mi⁠bĕ̇né֣y maẖĕli֔y bėn-léwi֖y bėn-yişĕ̂ráʼé֑l wĕ⁠şé̌réֽbĕyá֛h ẇ⁠báná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌mòná֥h ʻáşáֽ̂r׃"],[8,19,"וְ⁠אֶת־חֲשַׁבְיָ֔ה וְ⁠אִתּ֥⁠וֹ יְשַֽׁעְיָ֖ה מִ⁠בְּנֵ֣י מְרָרִ֑י אֶחָ֥י⁠ו וּ⁠בְנֵי⁠הֶ֖ם עֶשְׂרִֽים׃ס","wĕ⁠ʼeţ-ẖàşǎbĕyá֔h wĕ⁠ʼiţ֥̇⁠wò yĕşǎֽʻĕyá֖h mi⁠bĕ̇né֣y mĕrári֑y ʼeẖá֥y⁠w ẇ⁠bĕnéy⁠he֖m ʻeşĕ̂riֽym׃s"],[8,20,"וּ⁠מִן־הַ⁠נְּתִינִ֗ים שֶׁ⁠נָּתַ֨ן דָּוִ֤יד וְ⁠הַ⁠שָּׂרִים֙ לַ⁠עֲבֹדַ֣ת הַ⁠לְוִיִּ֔ם נְתִינִ֖ים מָאתַ֣יִם וְ⁠עֶשְׂרִ֑ים כֻּלָּ֖⁠ם נִקְּב֥וּ בְ⁠שֵׁמֽוֹת׃","ẇ⁠min-ha⁠nĕ̇ţiyni֗ym şě⁠ná̇ţa֨n dá̇wi֤yd wĕ⁠ha⁠şá̇̂riym֙ la⁠ʻàbòda֣ţ ha⁠lĕwiyi̇֔m nĕţiyni֖ym máʼţa֣yim wĕ⁠ʻeşĕ̂ri֑ym ku̇lá֖̇⁠m niqĕ̇b֥ẇ bĕ⁠şé̌mֽwòţ׃"],[8,21,"וָ⁠אֶקְרָ֨א שָׁ֥ם צוֹם֙ עַל־הַ⁠נָּהָ֣ר אַהֲוָ֔א לְ⁠הִתְעַנּ֖וֹת לִ⁠פְנֵ֣י אֱלֹהֵ֑י⁠נוּ לְ⁠בַקֵּ֤שׁ מִמֶּ֨⁠נּוּ֙ דֶּ֣רֶךְ יְשָׁרָ֔ה לָ֥⁠נוּ וּ⁠לְ⁠טַפֵּ֖⁠נוּ וּ⁠לְ⁠כָל־רְכוּשֵֽׁ⁠נוּ׃","wá⁠ʼeqĕrá֨ʼ şá֥̌m ẕwòm֙ ʻal-ha⁠ná̇há֣r ʼahàwá֔ʼ lĕ⁠hiţĕʻaṅ֖wòţ li⁠pĕné֣y ʼèlòhé֑y⁠nẇ lĕ⁠baqé֤̇ş̌ mimė֨⁠ṅẇ֙ dė֣rekĕ yĕşá̌rá֔h lá֥⁠nẇ ẇ⁠lĕ⁠tapé֖̇⁠nẇ ẇ⁠lĕ⁠kál-rĕkẇşéֽ̌⁠nẇ׃"],[8,22,"כִּ֣י בֹ֗שְׁתִּי לִ⁠שְׁא֤וֹל מִן־הַ⁠מֶּ֨לֶךְ֙ חַ֣יִל וּ⁠פָרָשִׁ֔ים לְ⁠עָזְרֵ֥⁠נוּ מֵ⁠אוֹיֵ֖ב בַּ⁠דָּ֑רֶךְ כִּֽי־אָמַ֨רְנוּ לַ⁠מֶּ֜לֶךְ לֵ⁠אמֹ֗ר יַד־אֱלֹהֵ֤י⁠נוּ עַל־כָּל־מְבַקְשָׁי⁠ו֙ לְ⁠טוֹבָ֔ה וְ⁠עֻזּ֣⁠וֹ וְ⁠אַפּ֔⁠וֹ עַ֖ל כָּל־עֹזְבָֽי⁠ו׃","ki֣̇y bò֗şĕ̌ţi̇y li⁠şĕ̌ʼ֤wòl min-ha⁠mė֨lekĕ֙ ẖa֣yil ẇ⁠páráşǐ֔ym lĕ⁠ʻázĕré֥⁠nẇ mé⁠ʼwòyé֖b bȧ⁠dá֑̇rekĕ kiֽ̇y-ʼáma֨rĕnẇ la⁠mė֜lekĕ lé⁠ʼmò֗r yad-ʼèlòhé֤y⁠nẇ ʻal-ká̇l-mĕbaqĕşá̌y⁠w֙ lĕ⁠twòbá֔h wĕ⁠ʻuż֣⁠wò wĕ⁠ʼaṗ֔⁠wò ʻa֖l ká̇l-ʻòzĕbáֽy⁠w׃"],[8,23,"וַ⁠נָּצ֛וּמָ⁠ה וַ⁠נְּבַקְשָׁ֥⁠ה מֵ⁠אֱלֹהֵ֖י⁠נוּ עַל־זֹ֑את וַ⁠יֵּעָתֵ֖ר לָֽ⁠נוּ׃","wa⁠ná̇ẕ֛ẇmá⁠h wa⁠nĕ̇baqĕşá֥̌⁠h mé⁠ʼèlòhé֖y⁠nẇ ʻal-zò֑ʼţ wa⁠yé̇ʻáţé֖r láֽ⁠nẇ׃"],[8,24,"וָ⁠אַבְדִּ֛ילָ⁠ה מִ⁠שָּׂרֵ֥י הַ⁠כֹּהֲנִ֖ים שְׁנֵ֣ים עָשָׂ֑ר לְ⁠שֵׁרֵֽבְיָ֣ה חֲשַׁבְיָ֔ה וְ⁠עִמָּ⁠הֶ֥ם מֵ⁠אֲחֵי⁠הֶ֖ם עֲשָׂרָֽה׃","wá⁠ʼabĕdi֛̇ylá⁠h mi⁠şá̇̂ré֥y ha⁠kò̇hàni֖ym şĕ̌né֣ym ʻáşá֑̂r lĕ⁠şé̌réֽbĕyá֣h ẖàşǎbĕyá֔h wĕ⁠ʻimá̇⁠he֥m mé⁠ʼàẖéy⁠he֖m ʻàşá̂ráֽh׃"],[8,25,"ו⁠אשקול⁠ה לָ⁠הֶ֔ם אֶת־הַ⁠כֶּ֥סֶף וְ⁠אֶת־הַ⁠זָּהָ֖ב וְ⁠אֶת־הַ⁠כֵּלִ֑ים תְּרוּמַ֣ת בֵּית־אֱלֹהֵ֗י⁠נוּ הַ⁠הֵרִ֨ימוּ֙ הַ⁠מֶּ֨לֶךְ֙ וְ⁠יֹעֲצָ֣י⁠ו וְ⁠שָׂרָ֔י⁠ו וְ⁠כָל־יִשְׂרָאֵ֖ל הַ⁠נִּמְצָאִֽים׃","w⁠ʼşqwl⁠h lá⁠he֔m ʼeţ-ha⁠kė֥sep wĕ⁠ʼeţ-ha⁠zá̇há֖b wĕ⁠ʼeţ-ha⁠ké̇li֑ym ţĕ̇rẇma֣ţ bé̇yţ-ʼèlòhé֗y⁠nẇ ha⁠héri֨ymẇ֙ ha⁠mė֨lekĕ֙ wĕ⁠yòʻàẕá֣y⁠w wĕ⁠şá̂rá֔y⁠w wĕ⁠kál-yişĕ̂ráʼé֖l ha⁠ni̇mĕẕáʼiֽym׃"],[8,26,"וָ⁠אֶשְׁקֲלָ֨⁠ה עַל־יָדָ֜⁠ם כֶּ֗סֶף כִּכָּרִים֙ שֵֽׁשׁ־מֵא֣וֹת וַ⁠חֲמִשִּׁ֔ים וּ⁠כְלֵי־כֶ֥סֶף מֵאָ֖ה לְ⁠כִכָּרִ֑ים זָהָ֖ב מֵאָ֥ה כִכָּֽר׃","wá⁠ʼeşĕ̌qàlá֨⁠h ʻal-yádá֜⁠m kė֗sep ki̇ká̇riym֙ şéֽ̌ş̌-méʼ֣wòţ wa⁠ẖàmişi̇̌֔ym ẇ⁠kĕléy-ke֥sep méʼá֖h lĕ⁠kiká̇ri֑ym záhá֖b méʼá֥h kikáֽ̇r׃"],[8,27,"וּ⁠כְפֹרֵ֤י זָהָב֙ עֶשְׂרִ֔ים לַ⁠אֲדַרְכֹנִ֖ים אָ֑לֶף וּ⁠כְלֵ֨י נְחֹ֜שֶׁת מֻצְהָ֤ב טוֹבָה֙ שְׁנַ֔יִם חֲמוּדֹ֖ת כַּ⁠זָּהָֽב׃","ẇ⁠kĕpòré֤y záháb֙ ʻeşĕ̂ri֔ym la⁠ʼàdarĕkòni֖ym ʼá֑lep ẇ⁠kĕlé֨y nĕẖò֜şěţ muẕĕhá֤b twòbáh֙ şĕ̌na֔yim ẖàmẇdò֖ţ kȧ⁠zá̇háֽb׃"],[8,28,"וָ⁠אֹמְרָ֣⁠ה אֲלֵ⁠הֶ֗ם אַתֶּ֥ם קֹ֨דֶשׁ֙ לַ⁠יהוָ֔ה וְ⁠הַ⁠כֵּלִ֖ים קֹ֑דֶשׁ וְ⁠הַ⁠כֶּ֤סֶף וְ⁠הַ⁠זָּהָב֙ נְדָבָ֔ה לַ⁠יהוָ֖ה אֱלֹהֵ֥י אֲבֹתֵי⁠כֶֽם׃","wá⁠ʼòmĕrá֣⁠h ʼàlé⁠he֗m ʼaţė֥m qò֨deş̌֙ la⁠yhwá֔h wĕ⁠ha⁠ké̇li֖ym qò֑deş̌ wĕ⁠ha⁠kė֤sep wĕ⁠ha⁠zá̇háb֙ nĕdábá֔h la⁠yhwá֖h ʼèlòhé֥y ʼàbòţéy⁠keֽm׃"],[8,29,"שִׁקְד֣וּ וְ⁠שִׁמְר֗וּ עַֽד־תִּשְׁקְל֡וּ לִ⁠פְנֵי֩ שָׂרֵ֨י הַ⁠כֹּהֲנִ֧ים וְ⁠הַ⁠לְוִיִּ֛ם וְ⁠שָׂרֵֽי־הָ⁠אָב֥וֹת לְ⁠יִשְׂרָאֵ֖ל בִּ⁠ירוּשָׁלִָ֑ם הַ⁠לִּשְׁכ֖וֹת בֵּ֥ית יְהוָֽה׃","şǐqĕd֣ẇ wĕ⁠şǐmĕr֗ẇ ʻaֽd-ţi̇şĕ̌qĕl֡ẇ li⁠pĕnéy֩ şá̂ré֨y ha⁠kò̇hàni֧ym wĕ⁠ha⁠lĕwiyi֛̇m wĕ⁠şá̂réֽy-há⁠ʼáb֥wòţ lĕ⁠yişĕ̂ráʼé֖l bi̇⁠yrẇşá̌liá֑m ha⁠li̇şĕ̌k֖wòţ bé֥̇yţ yĕhwáֽh׃"],[8,30,"וְ⁠קִבְּלוּ֙ הַ⁠כֹּהֲנִ֣ים וְ⁠הַ⁠לְוִיִּ֔ם מִשְׁקַ֛ל הַ⁠כֶּ֥סֶף וְ⁠הַ⁠זָּהָ֖ב וְ⁠הַ⁠כֵּלִ֑ים לְ⁠הָבִ֥יא לִ⁠ירוּשָׁלִַ֖ם לְ⁠בֵ֥ית אֱלֹהֵֽי⁠נוּ׃פ","wĕ⁠qibĕ̇lẇ֙ ha⁠kò̇hàni֣ym wĕ⁠ha⁠lĕwiyi̇֔m mişĕ̌qa֛l ha⁠kė֥sep wĕ⁠ha⁠zá̇há֖b wĕ⁠ha⁠ké̇li֑ym lĕ⁠hábi֥yʼ li⁠yrẇşá̌lia֖m lĕ⁠bé֥yţ ʼèlòhéֽy⁠nẇ׃p"],[8,31,"וַֽ⁠נִּסְעָ֞⁠ה מִ⁠נְּהַ֣ר אַֽהֲוָ֗א בִּ⁠שְׁנֵ֤ים עָשָׂר֙ לַ⁠חֹ֣דֶשׁ הָ⁠רִאשׁ֔וֹן לָ⁠לֶ֖כֶת יְרוּשָׁלִָ֑ם וְ⁠יַד־אֱלֹהֵ֨י⁠נוּ֙ הָיְתָ֣ה עָלֵ֔י⁠נוּ וַ⁠יַּ֨צִּילֵ֔⁠נוּ מִ⁠כַּ֥ף אוֹיֵ֛ב וְ⁠אוֹרֵ֖ב עַל־הַ⁠דָּֽרֶךְ׃","waֽ⁠ni̇sĕʻá֞⁠h mi⁠nĕ̇ha֣r ʼֽahàwá֗ʼ bi̇⁠şĕ̌né֤ym ʻáşá̂r֙ la⁠ẖò֣deş̌ há⁠riʼş̌֔wòn lá⁠le֖keţ yĕrẇşá̌liá֑m wĕ⁠yad-ʼèlòhé֨y⁠nẇ֙ háyĕţá֣h ʻálé֔y⁠nẇ wa⁠yȧ֨ẕi̇ylé֔⁠nẇ mi⁠kȧ֥p ʼwòyé֛b wĕ⁠ʼwòré֖b ʻal-ha⁠dáֽ̇rekĕ׃"],[8,32,"וַ⁠נָּב֖וֹא יְרוּשָׁלִָ֑ם וַ⁠נֵּ֥שֶׁב שָׁ֖ם יָמִ֥ים שְׁלֹשָֽׁה׃","wa⁠ná̇b֖wòʼ yĕrẇşá̌liá֑m wa⁠né֥̇şěb şá֖̌m yámi֥ym şĕ̌lòşáֽ̌h׃"],[8,33,"וּ⁠בַ⁠יּ֣וֹם הָ⁠רְבִיעִ֡י נִשְׁקַ֣ל הַ⁠כֶּסֶף֩ וְ⁠הַ⁠זָּהָ֨ב וְ⁠הַ⁠כֵּלִ֜ים בְּ⁠בֵ֣ית אֱלֹהֵ֗י⁠נוּ עַ֠ל יַד־מְרֵמ֤וֹת בֶּן־אֽוּרִיָּה֙ הַ⁠כֹּהֵ֔ן וְ⁠עִמּ֖⁠וֹ אֶלְעָזָ֣ר בֶּן־פִּֽינְחָ֑ס וְ⁠עִמָּ⁠הֶ֞ם יוֹזָבָ֧ד בֶּן־יֵשׁ֛וּעַ וְ⁠נֽוֹעַדְיָ֥ה בֶן־בִּנּ֖וּי הַ⁠לְוִיִּֽם׃","ẇ⁠ba⁠ẏ֣wòm há⁠rĕbiyʻi֡y nişĕ̌qa֣l ha⁠kėsep֩ wĕ⁠ha⁠zá̇há֨b wĕ⁠ha⁠ké̇li֜ym bĕ̇⁠bé֣yţ ʼèlòhé֗y⁠nẇ ʻa֠l yad-mĕrém֤wòţ bėn-ʼֽẇriyá̇h֙ ha⁠kò̇hé֔n wĕ⁠ʻiṁ֖⁠wò ʼelĕʻázá֣r bėn-piֽ̇ynĕẖá֑s wĕ⁠ʻimá̇⁠he֞m ywòzábá֧d bėn-yéş֛̌ẇʻa wĕ⁠nֽwòʻadĕyá֥h ben-bi̇ṅ֖ẇy ha⁠lĕwiyiֽ̇m׃"],[8,34,"בְּ⁠מִסְפָּ֥ר בְּ⁠מִשְׁקָ֖ל לַ⁠כֹּ֑ל וַ⁠יִּכָּתֵ֥ב כָּֽל־הַ⁠מִּשְׁקָ֖ל בָּ⁠עֵ֥ת הַ⁠הִֽיא׃פ","bĕ̇⁠misĕpá֥̇r bĕ̇⁠mişĕ̌qá֖l la⁠kò֑̇l wa⁠yi̇ká̇ţé֥b káֽ̇l-ha⁠mi̇şĕ̌qá֖l bá̇⁠ʻé֥ţ ha⁠hiֽyʼ׃p"],[8,35,"הַ֠⁠בָּאִים מֵֽ⁠הַ⁠שְּׁבִ֨י בְנֵֽי־הַ⁠גּוֹלָ֜ה הִקְרִ֥יבוּ עֹל֣וֹת ׀ לֵ⁠אלֹהֵ֣י יִשְׂרָאֵ֗ל פָּרִ֨ים שְׁנֵים־עָשָׂ֤ר עַל־כָּל־יִשְׂרָאֵל֙ אֵילִ֣ים ׀ תִּשְׁעִ֣ים וְ⁠שִׁשָּׁ֗ה כְּבָשִׂים֙ שִׁבְעִ֣ים וְ⁠שִׁבְעָ֔ה צְפִירֵ֥י חַטָּ֖את שְׁנֵ֣ים עָשָׂ֑ר הַ⁠כֹּ֖ל עוֹלָ֥ה לַ⁠יהוָֽה׃פ","ha֠⁠bá̇ʼiym méֽ⁠ha⁠şĕ̇̌bi֨y bĕnéֽy-ha⁠ġwòlá֜h hiqĕri֥ybẇ ʻòl֣wòţ ׀ lé⁠ʼlòhé֣y yişĕ̂ráʼé֗l pá̇ri֨ym şĕ̌néym-ʻáşá֤̂r ʻal-ká̇l-yişĕ̂ráʼél֙ ʼéyli֣ym ׀ ţi̇şĕ̌ʻi֣ym wĕ⁠şǐşá̇̌֗h kĕ̇báşîym֙ şǐbĕʻi֣ym wĕ⁠şǐbĕʻá֔h ẕĕpiyré֥y ẖatá֖̇ʼţ şĕ̌né֣ym ʻáşá֑̂r ha⁠kò֖̇l ʻwòlá֥h la⁠yhwáֽh׃p"],[8,36,"וַֽ⁠יִּתְּנ֣וּ ׀ אֶת־דָּתֵ֣י הַ⁠מֶּ֗לֶךְ לַ⁠אֲחַשְׁדַּרְפְּנֵי֙ הַ⁠מֶּ֔לֶךְ וּ⁠פַחֲו֖וֹת עֵ֣בֶר הַ⁠נָּהָ֑ר וְ⁠נִשְּׂא֥וּ אֶת־הָ⁠עָ֖ם וְ⁠אֶת־בֵּֽית־הָ⁠אֱלֹהִֽים׃ס","waֽ⁠yi̇ţĕ̇n֣ẇ ׀ ʼeţ-dá̇ţé֣y ha⁠mė֗lekĕ la⁠ʼàẖaşĕ̌dȧrĕpĕ̇néy֙ ha⁠mė֔lekĕ ẇ⁠paẖàw֖wòţ ʻé֣ber ha⁠ná̇há֑r wĕ⁠nişĕ̇̂ʼ֥ẇ ʼeţ-há⁠ʻá֖m wĕ⁠ʼeţ-béֽ̇yţ-há⁠ʼèlòhiֽym׃s"],[9,1,"וּ⁠כְ⁠כַלּ֣וֹת אֵ֗לֶּה נִגְּשׁ֨וּ אֵלַ֤⁠י הַ⁠שָּׂרִים֙ לֵ⁠אמֹ֔ר לֹֽא־נִבְדְּל֞וּ הָ⁠עָ֤ם יִשְׂרָאֵל֙ וְ⁠הַ⁠כֹּהֲנִ֣ים וְ⁠הַ⁠לְוִיִּ֔ם מֵ⁠עַמֵּ֖י הָ⁠אֲרָצ֑וֹת כְּ֠⁠תוֹעֲבֹֽתֵי⁠הֶם לַ⁠כְּנַעֲנִ֨י הַ⁠חִתִּ֜י הַ⁠פְּרִזִּ֣י הַ⁠יְבוּסִ֗י הָֽ⁠עַמֹּנִי֙ הַ⁠מֹּ֣אָבִ֔י הַ⁠מִּצְרִ֖י וְ⁠הָ⁠אֱמֹרִֽי׃","ẇ⁠kĕ⁠kal֣̇wòţ ʼé֗lėh nigĕ̇ş̌֨ẇ ʼéla֤⁠y ha⁠şá̇̂riym֙ lé⁠ʼmò֔r lòֽʼ-nibĕdĕ̇l֞ẇ há⁠ʻá֤m yişĕ̂ráʼél֙ wĕ⁠ha⁠kò̇hàni֣ym wĕ⁠ha⁠lĕwiyi̇֔m mé⁠ʻamé֖̇y há⁠ʼàráẕ֑wòţ kĕ̇֠⁠ţwòʻàbòֽţéy⁠hem la⁠kĕ̇naʻàni֨y ha⁠ẖiţi̇֜y ha⁠pĕ̇rizi֣̇y ha⁠yĕbẇsi֗y háֽ⁠ʻamò̇niy֙ ha⁠mò֣̇ʼábi֔y ha⁠mi̇ẕĕri֖y wĕ⁠há⁠ʼèmòriֽy׃"],[9,2,"כִּֽי־נָשְׂא֣וּ מִ⁠בְּנֹֽתֵי⁠הֶ֗ם לָ⁠הֶם֙ וְ⁠לִ⁠בְנֵי⁠הֶ֔ם וְ⁠הִתְעָֽרְבוּ֙ זֶ֣רַע הַ⁠קֹּ֔דֶשׁ בְּ⁠עַמֵּ֖י הָ⁠אֲרָצ֑וֹת וְ⁠יַ֧ד הַ⁠שָּׂרִ֣ים וְ⁠הַ⁠סְּגָנִ֗ים הָֽיְתָ֛ה בַּ⁠מַּ֥עַל הַ⁠זֶּ֖ה רִאשׁוֹנָֽה׃ס","kiֽ̇y-náşĕ̂ʼ֣ẇ mi⁠bĕ̇nòֽţéy⁠he֗m lá⁠hem֙ wĕ⁠li⁠bĕnéy⁠he֔m wĕ⁠hiţĕʻáֽrĕbẇ֙ ze֣raʻ ha⁠qò̇֔deş̌ bĕ̇⁠ʻamé֖̇y há⁠ʼàráẕ֑wòţ wĕ⁠ya֧d ha⁠şá̇̂ri֣ym wĕ⁠ha⁠sĕ̇gáni֗ym háֽyĕţá֛h bȧ⁠mȧ֥ʻal ha⁠zė֖h riʼş̌wònáֽh׃s"],[9,3,"וּ⁠כְ⁠שָׁמְעִ⁠י֙ אֶת־הַ⁠דָּבָ֣ר הַ⁠זֶּ֔ה קָרַ֥עְתִּי אֶת־בִּגְדִ֖⁠י וּ⁠מְעִילִ֑⁠י וָ⁠אֶמְרְטָ֞⁠ה מִ⁠שְּׂעַ֤ר רֹאשִׁ⁠י֙ וּ⁠זְקָנִ֔⁠י וָ⁠אֵשְׁבָ֖⁠ה מְשׁוֹמֵֽם׃","ẇ⁠kĕ⁠şá̌mĕʻi⁠y֙ ʼeţ-ha⁠dá̇bá֣r ha⁠zė֔h qára֥ʻĕţi̇y ʼeţ-bi̇gĕdi֖⁠y ẇ⁠mĕʻiyli֑⁠y wá⁠ʼemĕrĕtá֞⁠h mi⁠şĕ̇̂ʻa֤r ròʼşǐ⁠y֙ ẇ⁠zĕqáni֔⁠y wá⁠ʼéşĕ̌bá֖⁠h mĕş̌wòméֽm׃"],[9,4,"וְ⁠אֵלַ֣⁠י יֵאָסְפ֗וּ כֹּ֤ל חָרֵד֙ בְּ⁠דִבְרֵ֣י אֱלֹהֵֽי־יִשְׂרָאֵ֔ל עַ֖ל מַ֣עַל הַ⁠גּוֹלָ֑ה וַ⁠אֲנִי֙ יֹשֵׁ֣ב מְשׁוֹמֵ֔ם עַ֖ד לְ⁠מִנְחַ֥ת הָ⁠עָֽרֶב׃","wĕ⁠ʼéla֣⁠y yéʼásĕp֗ẇ kò֤̇l ẖáréd֙ bĕ̇⁠dibĕré֣y ʼèlòhéֽy-yişĕ̂ráʼé֔l ʻa֖l ma֣ʻal ha⁠ġwòlá֑h wa⁠ʼàniy֙ yòşé֣̌b mĕş̌wòmé֔m ʻa֖d lĕ⁠minĕẖa֥ţ há⁠ʻáֽreb׃"],[9,5,"וּ⁠בְ⁠מִנְחַ֣ת הָ⁠עֶ֗רֶב קַ֚מְתִּי מִ⁠תַּֽעֲנִיתִ֔⁠י וּ⁠בְ⁠קָרְעִ֥⁠י בִגְדִ֖⁠י וּ⁠מְעִילִ֑⁠י וָֽ⁠אֶכְרְעָ⁠ה֙ עַל־בִּרְכַּ֔⁠י וָ⁠אֶפְרְשָׂ֥⁠ה כַפַּ֖⁠י אֶל־יְהוָ֥ה אֱלֹהָֽ⁠י׃","ẇ⁠bĕ⁠minĕẖa֣ţ há⁠ʻe֗reb qa֚mĕţi̇y mi⁠ţȧֽʻàniyţi֔⁠y ẇ⁠bĕ⁠qárĕʻi֥⁠y bigĕdi֖⁠y ẇ⁠mĕʻiyli֑⁠y wáֽ⁠ʼekĕrĕʻá⁠h֙ ʻal-bi̇rĕkȧ֔⁠y wá⁠ʼepĕrĕşá֥̂⁠h kapȧ֖⁠y ʼel-yĕhwá֥h ʼèlòháֽ⁠y׃"],[9,6,"וָ⁠אֹמְרָ֗⁠ה אֱלֹהַ⁠י֙ בֹּ֣שְׁתִּי וְ⁠נִכְלַ֔מְתִּי לְ⁠הָרִ֧ים אֱלֹהַ֛⁠י פָּנַ֖⁠י אֵלֶ֑י⁠ךָ כִּ֣י עֲוֺנֹתֵ֤י⁠נוּ רָבוּ֙ לְ⁠מַ֣עְלָ⁠ה רֹּ֔אשׁ וְ⁠אַשְׁמָתֵ֥⁠נוּ גָדְלָ֖ה עַ֥ד לַ⁠שָּׁמָֽיִם׃","wá⁠ʼòmĕrá֗⁠h ʼèlòha⁠y֙ bò֣̇şĕ̌ţi̇y wĕ⁠nikĕla֔mĕţi̇y lĕ⁠hári֧ym ʼèlòha֛⁠y pá̇na֖⁠y ʼéle֑y⁠ká ki֣̇y ʻàwֺnòţé֤y⁠nẇ rábẇ֙ lĕ⁠ma֣ʻĕlá⁠h rò̇֔ʼş̌ wĕ⁠ʼaşĕ̌máţé֥⁠nẇ gádĕlá֖h ʻa֥d la⁠şá̇̌máֽyim׃"],[9,7,"מִ⁠ימֵ֣י אֲבֹתֵ֗י⁠נוּ אֲנַ֨חְנוּ֙ בְּ⁠אַשְׁמָ֣ה גְדֹלָ֔ה עַ֖ד הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה וּ⁠בַ⁠עֲוֺנֹתֵ֡י⁠נוּ נִתַּ֡נּוּ אֲנַחְנוּ֩ מְלָכֵ֨י⁠נוּ כֹהֲנֵ֜י⁠נוּ בְּ⁠יַ֣ד ׀ מַלְכֵ֣י הָ⁠אֲרָצ֗וֹת בַּ⁠חֶ֜רֶב בַּ⁠שְּׁבִ֧י וּ⁠בַ⁠בִּזָּ֛ה וּ⁠בְ⁠בֹ֥שֶׁת פָּנִ֖ים כְּ⁠הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","mi⁠ymé֣y ʼàbòţé֗y⁠nẇ ʼàna֨ẖĕnẇ֙ bĕ̇⁠ʼaşĕ̌má֣h gĕdòlá֔h ʻa֖d ha⁠ẏ֣wòm ha⁠zė֑h ẇ⁠ba⁠ʻàwֺnòţé֡y⁠nẇ niţȧ֡ṅẇ ʼànaẖĕnẇ֩ mĕláké֨y⁠nẇ kòhàné֜y⁠nẇ bĕ̇⁠ya֣d ׀ malĕké֣y há⁠ʼàráẕ֗wòţ bȧ⁠ẖe֜reb bȧ⁠şĕ̇̌bi֧y ẇ⁠ba⁠bi̇zá֛̇h ẇ⁠bĕ⁠bò֥şěţ pá̇ni֖ym kĕ̇⁠ha⁠ẏ֥wòm ha⁠zėֽh׃"],[9,8,"וְ⁠עַתָּ֡ה כִּ⁠מְעַט־רֶגַע֩ הָיְתָ֨ה תְחִנָּ֜ה מֵ⁠אֵ֣ת ׀ יְהוָ֣ה אֱלֹהֵ֗י⁠נוּ לְ⁠הַשְׁאִ֥יר לָ֨⁠נוּ֙ פְּלֵיטָ֔ה וְ⁠לָ⁠תֶת־לָ֥⁠נוּ יָתֵ֖ד בִּ⁠מְק֣וֹם קָדְשׁ֑⁠וֹ לְ⁠הָאִ֤יר עֵינֵ֨י⁠נוּ֙ אֱלֹהֵ֔י⁠נוּ וּ⁠לְ⁠תִתֵּ֛⁠נוּ מִֽחְיָ֥ה מְעַ֖ט בְּ⁠עַבְדֻתֵֽ⁠נוּ׃","wĕ⁠ʻaţá̇֡h ki̇⁠mĕʻat-regaʻ֩ háyĕţá֨h ţĕẖiná̇֜h mé⁠ʼé֣ţ ׀ yĕhwá֣h ʼèlòhé֗y⁠nẇ lĕ⁠haşĕ̌ʼi֥yr lá֨⁠nẇ֙ pĕ̇léytá֔h wĕ⁠lá⁠ţeţ-lá֥⁠nẇ yáţé֖d bi̇⁠mĕq֣wòm qádĕş֑̌⁠wò lĕ⁠háʼi֤yr ʻéyné֨y⁠nẇ֙ ʼèlòhé֔y⁠nẇ ẇ⁠lĕ⁠ţiţé֛̇⁠nẇ miֽẖĕyá֥h mĕʻa֖t bĕ̇⁠ʻabĕduţéֽ⁠nẇ׃"],[9,9,"כִּֽי־עֲבָדִ֣ים אֲנַ֔חְנוּ וּ⁠בְ⁠עַבְדֻ֔תֵ⁠נוּ לֹ֥א עֲזָבָ֖⁠נוּ אֱלֹהֵ֑י⁠נוּ וַֽ⁠יַּט־עָלֵ֣י⁠נוּ חֶ֡סֶד לִ⁠פְנֵי֩ מַלְכֵ֨י פָרַ֜ס לָֽ⁠תֶת־לָ֣⁠נוּ מִֽחְיָ֗ה לְ⁠רוֹמֵ֞ם אֶת־בֵּ֤ית אֱלֹהֵ֨י⁠נוּ֙ וּ⁠לְ⁠הַעֲמִ֣יד אֶת־חָרְבֹתָ֔י⁠ו וְ⁠לָֽ⁠תֶת־לָ֣⁠נוּ גָדֵ֔ר בִּֽ⁠יהוּדָ֖ה וּ⁠בִ⁠ירוּשָׁלִָֽם׃ס","kiֽ̇y-ʻàbádi֣ym ʼàna֔ẖĕnẇ ẇ⁠bĕ⁠ʻabĕdu֔ţé⁠nẇ lò֥ʼ ʻàzábá֖⁠nẇ ʼèlòhé֑y⁠nẇ wֽa⁠yȧt-ʻálé֣y⁠nẇ ẖe֡sed li⁠pĕnéy֩ malĕké֨y pára֜s láֽ⁠ţeţ-lá֣⁠nẇ miֽẖĕyá֗h lĕ⁠rwòmé֞m ʼeţ-bé֤̇yţ ʼèlòhé֨y⁠nẇ֙ ẇ⁠lĕ⁠haʻàmi֣yd ʼeţ-ẖárĕbòţá֔y⁠w wĕ⁠láֽ⁠ţeţ-lá֣⁠nẇ gádé֔r biֽ̇⁠yhẇdá֖h ẇ⁠bi⁠yrẇşá̌liáֽm׃s"],[9,10,"וְ⁠עַתָּ֛ה מַה־נֹּאמַ֥ר אֱלֹהֵ֖י⁠נוּ אַֽחֲרֵי־זֹ֑את כִּ֥י עָזַ֖בְנוּ מִצְוֺתֶֽי⁠ךָ׃","wĕ⁠ʻaţá֛̇h mah-nò̇ʼma֥r ʼèlòhé֖y⁠nẇ ʼֽaẖàréy-zò֑ʼţ ki֥̇y ʻáza֖bĕnẇ miẕĕwֺţeֽy⁠ká׃"],[9,11,"אֲשֶׁ֣ר צִוִּ֗יתָ בְּ⁠יַ֨ד עֲבָדֶ֣י⁠ךָ הַ⁠נְּבִיאִים֮ לֵ⁠אמֹר֒ הָ⁠אָ֗רֶץ אֲשֶׁ֨ר אַתֶּ֤ם בָּאִים֙ לְ⁠רִשְׁתָּ֔⁠הּ אֶ֤רֶץ נִדָּה֙ הִ֔יא בְּ⁠נִדַּ֖ת עַמֵּ֣י הָ⁠אֲרָצ֑וֹת בְּ⁠תוֹעֲבֹֽתֵי⁠הֶ֗ם אֲשֶׁ֥ר מִלְא֛וּ⁠הָ מִ⁠פֶּ֥ה אֶל־פֶּ֖ה בְּ⁠טֻמְאָתָֽ⁠ם׃","ʼàşě֣r ẕiwi̇֗yţá bĕ̇⁠ya֨d ʻàbáde֣y⁠ká ha⁠nĕ̇biyʼiym֮ lé⁠ʼmòr֒ há⁠ʼá֗reẕ ʼàşě֨r ʼaţė֤m bá̇ʼiym֙ lĕ⁠rişĕ̌ţá̇֔⁠ḣ ʼe֤reẕ nidá̇h֙ hi֔yʼ bĕ̇⁠nidȧ֖ţ ʻamé֣̇y há⁠ʼàráẕ֑wòţ bĕ̇⁠ţwòʻàbòֽţéy⁠he֗m ʼàşě֥r milĕʼ֛ẇ⁠há mi⁠pė֥h ʼel-pė֖h bĕ̇⁠tumĕʼáţáֽ⁠m׃"],[9,12,"וְ֠⁠עַתָּה בְּֽנוֹתֵי⁠כֶ֞ם אַל־תִּתְּנ֣וּ לִ⁠בְנֵי⁠הֶ֗ם וּ⁠בְנֹֽתֵי⁠הֶם֙ אַל־תִּשְׂא֣וּ לִ⁠בְנֵי⁠כֶ֔ם וְ⁠לֹֽא־תִדְרְשׁ֧וּ שְׁלֹמָ֛⁠ם וְ⁠טוֹבָתָ֖⁠ם עַד־עוֹלָ֑ם לְמַ֣עַן תֶּחֶזְק֗וּ וַ⁠אֲכַלְתֶּם֙ אֶת־ט֣וּב הָ⁠אָ֔רֶץ וְ⁠הוֹרַשְׁתֶּ֥ם לִ⁠בְנֵי⁠כֶ֖ם עַד־עוֹלָֽם׃","wĕ֠⁠ʻaţá̇h bĕֽ̇nwòţéy⁠ke֞m ʼal-ţi̇ţĕ̇n֣ẇ li⁠bĕnéy⁠he֗m ẇ⁠bĕnòֽţéy⁠hem֙ ʼal-ţi̇şĕ̂ʼ֣ẇ li⁠bĕnéy⁠ke֔m wĕ⁠lòֽʼ-ţidĕrĕş֧̌ẇ şĕ̌lòmá֛⁠m wĕ⁠twòbáţá֖⁠m ʻad-ʻwòlá֑m lĕma֣ʻan ţėẖezĕq֗ẇ wa⁠ʼàkalĕţėm֙ ʼeţ-t֣ẇb há⁠ʼá֔reẕ wĕ⁠hwòraşĕ̌ţė֥m li⁠bĕnéy⁠ke֖m ʻad-ʻwòláֽm׃"],[9,13,"וְ⁠אַֽחֲרֵי֙ כָּל־הַ⁠בָּ֣א עָלֵ֔י⁠נוּ בְּ⁠מַעֲשֵׂ֨י⁠נוּ֙ הָ⁠רָעִ֔ים וּ⁠בְ⁠אַשְׁמָתֵ֖⁠נוּ הַ⁠גְּדֹלָ֑ה כִּ֣י ׀ אַתָּ֣ה אֱלֹהֵ֗י⁠נוּ חָשַׂ֤כְתָּֽ לְ⁠מַ֨טָּה֙ מֵֽ⁠עֲוֺנֵ֔⁠נוּ וְ⁠נָתַ֥תָּה לָּ֛⁠נוּ פְּלֵיטָ֖ה כָּ⁠זֹֽאת׃","wĕ⁠ʼaֽẖàréy֙ ká̇l-ha⁠bá֣̇ʼ ʻálé֔y⁠nẇ bĕ̇⁠maʻàşé̂֨y⁠nẇ֙ há⁠ráʻi֔ym ẇ⁠bĕ⁠ʼaşĕ̌máţé֖⁠nẇ ha⁠gĕ̇dòlá֑h ki֣̇y ׀ ʼaţá֣̇h ʼèlòhé֗y⁠nẇ ẖáşâ֤kĕţáֽ̇ lĕ⁠ma֨tá̇h֙ méֽ⁠ʻàwֺné֔⁠nẇ wĕ⁠náţa֥ţá̇h lá֛̇⁠nẇ pĕ̇léytá֖h ká̇⁠zòֽʼţ׃"],[9,14,"הֲ⁠נָשׁוּב֙ לְ⁠הָפֵ֣ר מִצְוֺתֶ֔י⁠ךָ וּ֨⁠לְ⁠הִתְחַתֵּ֔ן בְּ⁠עַמֵּ֥י הַ⁠תֹּעֵב֖וֹת הָ⁠אֵ֑לֶּה הֲ⁠ל֤וֹא תֶֽאֱנַף־בָּ֨⁠נוּ֙ עַד־כַּלֵּ֔ה לְ⁠אֵ֥ין שְׁאֵרִ֖ית וּ⁠פְלֵיטָֽה׃פ","hà⁠náş̌ẇb֙ lĕ⁠hápé֣r miẕĕwֺţe֔y⁠ká ẇ֨⁠lĕ⁠hiţĕẖaţé̇֔n bĕ̇⁠ʻamé֥̇y ha⁠ţò̇ʻéb֖wòţ há⁠ʼé֑lėh hà⁠l֤wòʼ ţeֽʼènap-bá̇֨⁠nẇ֙ ʻad-kȧlé̇֔h lĕ⁠ʼé֥yn şĕ̌ʼéri֖yţ ẇ⁠pĕléytáֽh׃p"],[9,15,"יְהוָ֞ה אֱלֹהֵ֤י יִשְׂרָאֵל֙ צַדִּ֣יק אַ֔תָּה כִּֽי־נִשְׁאַ֥רְנוּ פְלֵיטָ֖ה כְּ⁠הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה הִנְ⁠נ֤וּ לְ⁠פָנֶ֨י⁠ךָ֙ בְּ⁠אַשְׁמָתֵ֔י⁠נוּ כִּ֣י אֵ֥ין לַ⁠עֲמ֛וֹד לְ⁠פָנֶ֖י⁠ךָ עַל־זֹֽאת׃פ","yĕhwá֞h ʼèlòhé֤y yişĕ̂ráʼél֙ ẕadi֣̇yq ʼa֔ţá̇h kiֽ̇y-nişĕ̌ʼa֥rĕnẇ pĕléytá֖h kĕ̇⁠ha⁠ẏ֣wòm ha⁠zė֑h hinĕ⁠n֤ẇ lĕ⁠páne֨y⁠ká֙ bĕ̇⁠ʼaşĕ̌máţé֔y⁠nẇ ki֣̇y ʼé֥yn la⁠ʻàm֛wòd lĕ⁠páne֖y⁠ká ʻal-zòֽʼţ׃p"],[10,1,"וּ⁠כְ⁠הִתְפַּלֵּ֤ל עֶזְרָא֙ וּ⁠כְ֨⁠הִתְוַדֹּת֔⁠וֹ בֹּכֶה֙ וּ⁠מִתְנַפֵּ֔ל לִ⁠פְנֵ֖י בֵּ֣ית הָ⁠אֱלֹהִ֑ים נִקְבְּצוּ֩ אֵלָ֨י⁠ו מִ⁠יִּשְׂרָאֵ֜ל קָהָ֣ל רַב־מְאֹ֗ד אֲנָשִׁ֤ים וְ⁠נָשִׁים֙ וִֽ⁠ילָדִ֔ים כִּֽי־בָכ֥וּ הָ⁠עָ֖ם הַרְבֵּה־בֶֽכֶה׃ס","ẇ⁠kĕ⁠hiţĕpȧlé֤̇l ʻezĕráʼ֙ ẇ⁠kĕ֨⁠hiţĕwadò̇ţ֔⁠wò bò̇keh֙ ẇ⁠miţĕnapé̇֔l li⁠pĕné֖y bé֣̇yţ há⁠ʼèlòhi֑ym niqĕbĕ̇ẕẇ֩ ʼélá֨y⁠w mi⁠yi̇şĕ̂ráʼé֜l qáhá֣l rab-mĕʼò֗d ʼànáşǐ֤ym wĕ⁠náşǐym֙ wiֽ⁠yládi֔ym kiֽ̇y-bák֥ẇ há⁠ʻá֖m harĕbé̇h-beֽkeh׃s"],[10,2,"וַ⁠יַּעַן֩ שְׁכַנְיָ֨ה בֶן־יְחִיאֵ֜ל מִ⁠בְּנֵ֤י עולם וַ⁠יֹּ֣אמֶר לְ⁠עֶזְרָ֔א אֲנַ֨חְנוּ֙ מָעַ֣לְנוּ בֵ⁠אלֹהֵ֔י⁠נוּ וַ⁠נֹּ֛שֶׁב נָשִׁ֥ים נָכְרִיּ֖וֹת מֵ⁠עַמֵּ֣י הָ⁠אָ֑רֶץ וְ⁠עַתָּ֛ה יֵשׁ־מִקְוֶ֥ה לְ⁠יִשְׂרָאֵ֖ל עַל־זֹֽאת׃","wa⁠yȧʻan֩ şĕ̌kanĕyá֨h ben-yĕẖiyʼé֜l mi⁠bĕ̇né֤y ʻwlm wa⁠yò֣̇ʼmer lĕ⁠ʻezĕrá֔ʼ ʼàna֨ẖĕnẇ֙ máʻa֣lĕnẇ bé⁠ʼlòhé֔y⁠nẇ wa⁠nò֛̇şěb náşǐ֥ym nákĕriẏ֖wòţ mé⁠ʻamé֣̇y há⁠ʼá֑reẕ wĕ⁠ʻaţá֛̇h yéş̌-miqĕwe֥h lĕ⁠yişĕ̂ráʼé֖l ʻal-zòֽʼţ׃"],[10,3,"וְ⁠עַתָּ֣ה נִֽכְרָת־בְּרִ֣ית לֵ֠⁠אלֹהֵי⁠נוּ לְ⁠הוֹצִ֨יא כָל־נָשִׁ֜ים וְ⁠הַ⁠נּוֹלָ֤ד מֵ⁠הֶם֙ בַּ⁠עֲצַ֣ת אֲדֹנָ֔⁠י וְ⁠הַ⁠חֲרֵדִ֖ים בְּ⁠מִצְוַ֣ת אֱלֹהֵ֑י⁠נוּ וְ⁠כַ⁠תּוֹרָ֖ה יֵעָשֶֽׂה׃","wĕ⁠ʻaţá֣̇h niֽkĕráţ-bĕ̇ri֣yţ lé֠⁠ʼlòhéy⁠nẇ lĕ⁠hwòẕi֨yʼ kál-náşǐ֜ym wĕ⁠ha⁠ṅwòlá֤d mé⁠hem֙ bȧ⁠ʻàẕa֣ţ ʼàdòná֔⁠y wĕ⁠ha⁠ẖàrédi֖ym bĕ̇⁠miẕĕwa֣ţ ʼèlòhé֑y⁠nẇ wĕ⁠ka⁠ţ̇wòrá֖h yéʻáşêֽh׃"],[10,4,"ק֛וּם כִּֽי־עָלֶ֥י⁠ךָ הַ⁠דָּבָ֖ר וַ⁠אֲנַ֣חְנוּ עִמָּ֑⁠ךְ חֲזַ֖ק וַ⁠עֲשֵֽׂה׃פ","q֛ẇm kiֽ̇y-ʻále֥y⁠ká ha⁠dá̇bá֖r wa⁠ʼàna֣ẖĕnẇ ʻimá֑̇⁠kĕ ẖàza֖q wa⁠ʻàşéֽ̂h׃p"],[10,5,"וַ⁠יָּ֣קָם עֶזְרָ֡א וַ⁠יַּשְׁבַּ֣ע אֶת־שָׂרֵי֩ הַ⁠כֹּהֲנִ֨ים הַ⁠לְוִיִּ֜ם וְ⁠כָל־יִשְׂרָאֵ֗ל לַ⁠עֲשׂ֛וֹת כַּ⁠דָּבָ֥ר הַ⁠זֶּ֖ה וַ⁠יִּשָּׁבֵֽעוּ׃","wa⁠yá֣̇qám ʻezĕrá֡ʼ wa⁠yȧşĕ̌bȧ֣ʻ ʼeţ-şá̂réy֩ ha⁠kò̇hàni֨ym ha⁠lĕwiyi̇֜m wĕ⁠kál-yişĕ̂ráʼé֗l la⁠ʻàş֛̂wòţ kȧ⁠dá̇bá֥r ha⁠zė֖h wa⁠yi̇şá̇̌béֽʻẇ׃"],[10,6,"וַ⁠יָּ֣קָם עֶזְרָ֗א מִ⁠לִּ⁠פְנֵי֙ בֵּ֣ית הָֽ⁠אֱלֹהִ֔ים וַ⁠יֵּ֕לֶךְ אֶל־לִשְׁכַּ֖ת יְהוֹחָנָ֣ן בֶּן־אֶלְיָשִׁ֑יב וַ⁠יֵּ֣לֶךְ שָׁ֗ם לֶ֤חֶם לֹֽא־אָכַל֙ וּ⁠מַ֣יִם לֹֽא־שָׁתָ֔ה כִּ֥י מִתְאַבֵּ֖ל עַל־מַ֥עַל הַ⁠גּוֹלָֽה׃ס","wa⁠yá֣̇qám ʻezĕrá֗ʼ mi⁠li̇⁠pĕnéy֙ bé֣̇yţ háֽ⁠ʼèlòhi֔ym wa⁠yé̇֕lekĕ ʼel-lişĕ̌kȧ֖ţ yĕhwòẖáná֣n bėn-ʼelĕyáşǐ֑yb wa⁠yé֣̇lekĕ şá̌֗m le֤ẖem lòֽʼ-ʼákal֙ ẇ⁠ma֣yim lòֽʼ-şá̌ţá֔h ki֥̇y miţĕʼabé֖̇l ʻal-ma֥ʻal ha⁠ġwòláֽh׃s"],[10,7,"וַ⁠יַּעֲבִ֨ירוּ ק֜וֹל בִּ⁠יהוּדָ֣ה וִ⁠ירֽוּשָׁלִַ֗ם לְ⁠כֹל֙ בְּנֵ֣י הַ⁠גּוֹלָ֔ה לְ⁠הִקָּבֵ֖ץ יְרוּשָׁלִָֽם׃","wa⁠yȧʻàbi֨yrẇ q֜wòl bi̇⁠yhẇdá֣h wi⁠yrֽẇşá̌lia֗m lĕ⁠kòl֙ bĕ̇né֣y ha⁠ġwòlá֔h lĕ⁠hiqá̇bé֖ẕ yĕrẇşá̌liáֽm׃"],[10,8,"וְ⁠כֹל֩ אֲשֶׁ֨ר לֹֽא־יָב֜וֹא לִ⁠שְׁלֹ֣שֶׁת הַ⁠יָּמִ֗ים כַּ⁠עֲצַ֤ת הַ⁠שָּׂרִים֙ וְ⁠הַ⁠זְּקֵנִ֔ים יָחֳרַ֖ם כָּל־רְכוּשׁ֑⁠וֹ וְ⁠ה֥וּא יִבָּדֵ֖ל מִ⁠קְּהַ֥ל הַ⁠גּוֹלָֽה׃ס","wĕ⁠kòl֩ ʼàşě֨r lòֽʼ-yáb֜wòʼ li⁠şĕ̌lò֣şěţ ha⁠yá̇mi֗ym kȧ⁠ʻàẕa֤ţ ha⁠şá̇̂riym֙ wĕ⁠ha⁠zĕ̇qéni֔ym yáẖora֖m ká̇l-rĕkẇş֑̌⁠wò wĕ⁠h֥ẇʼ yibá̇dé֖l mi⁠qĕ̇ha֥l ha⁠ġwòláֽh׃s"],[10,9,"וַ⁠יִּקָּבְצ֣וּ כָל־אַנְשֵֽׁי־יְהוּדָה֩ וּ⁠בִנְיָמִ֨ן ׀ יְרוּשָׁלִַ֜ם לִ⁠שְׁלֹ֣שֶׁת הַ⁠יָּמִ֗ים ה֛וּא חֹ֥דֶשׁ הַ⁠תְּשִׁיעִ֖י בְּ⁠עֶשְׂרִ֣ים בַּ⁠חֹ֑דֶשׁ וַ⁠יֵּשְׁב֣וּ כָל־הָ⁠עָ֗ם בִּ⁠רְחוֹב֙ בֵּ֣ית הָ⁠אֱלֹהִ֔ים מַרְעִידִ֥ים עַל־הַ⁠דָּבָ֖ר וּ⁠מֵ⁠הַ⁠גְּשָׁמִֽים׃פ","wa⁠yi̇qá̇bĕẕ֣ẇ kál-ʼanĕşéֽ̌y-yĕhẇdáh֩ ẇ⁠binĕyámi֨n ׀ yĕrẇşá̌lia֜m li⁠şĕ̌lò֣şěţ ha⁠yá̇mi֗ym h֛ẇʼ ẖò֥deş̌ ha⁠ţĕ̇şǐyʻi֖y bĕ̇⁠ʻeşĕ̂ri֣ym bȧ⁠ẖò֑deş̌ wa⁠yé̇şĕ̌b֣ẇ kál-há⁠ʻá֗m bi̇⁠rĕẖwòb֙ bé֣̇yţ há⁠ʼèlòhi֔ym marĕʻiydi֥ym ʻal-ha⁠dá̇bá֖r ẇ⁠mé⁠ha⁠gĕ̇şá̌miֽym׃p"],[10,10,"וַ⁠יָּ֨קָם עֶזְרָ֤א הַ⁠כֹּהֵן֙ וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֔ם אַתֶּ֣ם מְעַלְתֶּ֔ם וַ⁠תֹּשִׁ֖יבוּ נָשִׁ֣ים נָכְרִיּ֑וֹת לְ⁠הוֹסִ֖יף עַל־אַשְׁמַ֥ת יִשְׂרָאֵֽל׃","wa⁠yá̇֨qám ʻezĕrá֤ʼ ha⁠kò̇hén֙ wa⁠yò֣̇ʼmer ʼàlé⁠he֔m ʼaţė֣m mĕʻalĕţė֔m wa⁠ţò̇şǐ֖ybẇ náşǐ֣ym nákĕriẏ֑wòţ lĕ⁠hwòsi֖yp ʻal-ʼaşĕ̌ma֥ţ yişĕ̂ráʼéֽl׃"],[10,11,"וְ⁠עַתָּ֗ה תְּנ֥וּ תוֹדָ֛ה לַ⁠יהוָ֥ה אֱלֹהֵֽי־אֲבֹתֵי⁠כֶ֖ם וַ⁠עֲשׂ֣וּ רְצוֹנ֑⁠וֹ וְ⁠הִבָּֽדְלוּ֙ מֵ⁠עַמֵּ֣י הָ⁠אָ֔רֶץ וּ⁠מִן־הַ⁠נָּשִׁ֖ים הַ⁠נָּכְרִיּֽוֹת׃","wĕ⁠ʻaţá̇֗h ţĕ̇n֥ẇ ţwòdá֛h la⁠yhwá֥h ʼèlòhéֽy-ʼàbòţéy⁠ke֖m wa⁠ʻàş֣̂ẇ rĕẕwòn֑⁠wò wĕ⁠hibáֽ̇dĕlẇ֙ mé⁠ʻamé֣̇y há⁠ʼá֔reẕ ẇ⁠min-ha⁠ná̇şǐ֖ym ha⁠ná̇kĕriẏֽwòţ׃"],[10,12,"וַ⁠יַּֽעְנ֧וּ כָֽל־הַ⁠קָּהָ֛ל וַ⁠יֹּאמְר֖וּ ק֣וֹל גָּד֑וֹל כֵּ֛ן כ⁠דברי⁠ך עָלֵ֖י⁠נוּ לַ⁠עֲשֽׂוֹת׃","wa⁠yȧֽʻĕn֧ẇ káֽl-ha⁠qá̇há֛l wa⁠yò̇ʼmĕr֖ẇ q֣wòl gá̇d֑wòl ké֛̇n k⁠dbry⁠k ʻálé֖y⁠nẇ la⁠ʻàşֽ̂wòţ׃"],[10,13,"אֲבָ֞ל הָ⁠עָ֥ם רָב֙ וְ⁠הָ⁠עֵ֣ת גְּשָׁמִ֔ים וְ⁠אֵ֥ין כֹּ֖חַ לַ⁠עֲמ֣וֹד בַּ⁠ח֑וּץ וְ⁠הַ⁠מְּלָאכָ֗ה לֹֽא־לְ⁠י֤וֹם אֶחָד֙ וְ⁠לֹ֣א לִ⁠שְׁנַ֔יִם כִּֽי־הִרְבִּ֥ינוּ לִ⁠פְשֹׁ֖עַ בַּ⁠דָּבָ֥ר הַ⁠זֶּֽה׃","ʼàbá֞l há⁠ʻá֥m ráb֙ wĕ⁠há⁠ʻé֣ţ gĕ̇şá̌mi֔ym wĕ⁠ʼé֥yn kò֖̇ẖa la⁠ʻàm֣wòd bȧ⁠ẖ֑ẇẕ wĕ⁠ha⁠mĕ̇láʼká֗h lòֽʼ-lĕ⁠y֤wòm ʼeẖád֙ wĕ⁠lò֣ʼ li⁠şĕ̌na֔yim kiֽ̇y-hirĕbi֥̇ynẇ li⁠pĕşò֖̌ʻa bȧ⁠dá̇bá֥r ha⁠zėֽh׃"],[10,14,"יַֽעֲמְדוּ־נָ֣א שָׂ֠רֵי⁠נוּ לְֽ⁠כָל־הַ⁠קָּהָ֞ל וְ⁠כֹ֣ל ׀ אֲשֶׁ֣ר בֶּ⁠עָרֵ֗י⁠נוּ הַ⁠הֹשִׁ֞יב נָשִׁ֤ים נָכְרִיּוֹת֙ יָבֹא֙ לְ⁠עִתִּ֣ים מְזֻמָּנִ֔ים וְ⁠עִמָּ⁠הֶ֛ם זִקְנֵי־עִ֥יר וָ⁠עִ֖יר וְ⁠שֹׁפְטֶ֑י⁠הָ עַ֠ד לְ⁠הָשִׁ֞יב חֲר֤וֹן אַף־אֱלֹהֵ֨י⁠נוּ֙ מִמֶּ֔⁠נּוּ עַ֖ד לַ⁠דָּבָ֥ר הַ⁠זֶּֽה׃פ","yaֽʻàmĕdẇ-ná֣ʼ şá̂֠réy⁠nẇ lĕֽ⁠kál-ha⁠qá̇há֞l wĕ⁠kò֣l ׀ ʼàşě֣r bė⁠ʻáré֗y⁠nẇ ha⁠hòşǐ֞yb náşǐ֤ym nákĕriẏwòţ֙ yábòʼ֙ lĕ⁠ʻiţi֣̇ym mĕzumá̇ni֔ym wĕ⁠ʻimá̇⁠he֛m ziqĕnéy-ʻi֥yr wá⁠ʻi֖yr wĕ⁠şò̌pĕte֑y⁠há ʻa֠d lĕ⁠háşǐ֞yb ẖàr֤wòn ʼap-ʼèlòhé֨y⁠nẇ֙ mimė֔⁠ṅẇ ʻa֖d la⁠dá̇bá֥r ha⁠zėֽh׃p"],[10,15,"אַ֣ךְ יוֹנָתָ֧ן בֶּן־עֲשָׂהאֵ֛ל וְ⁠יַחְזְיָ֥ה בֶן־תִּקְוָ֖ה עָמְד֣וּ עַל־זֹ֑את וּ⁠מְשֻׁלָּ֛ם וְ⁠שַׁבְּתַ֥י הַ⁠לֵּוִ֖י עֲזָרֻֽ⁠ם׃","ʼa֣kĕ ywònáţá֧n bėn-ʻàşá̂hʼé֛l wĕ⁠yaẖĕzĕyá֥h ben-ţi̇qĕwá֖h ʻámĕd֣ẇ ʻal-zò֑ʼţ ẇ⁠mĕşǔlá֛̇m wĕ⁠şǎbĕ̇ţa֥y ha⁠lé̇wi֖y ʻàzáruֽ⁠m׃"],[10,16,"וַ⁠יַּֽעֲשׂוּ־כֵן֮ בְּנֵ֣י הַ⁠גּוֹלָה֒ וַ⁠יִּבָּדְלוּ֩ עֶזְרָ֨א הַ⁠כֹּהֵ֜ן אֲנָשִׁ֨ים רָאשֵׁ֧י הָ⁠אָב֛וֹת לְ⁠בֵ֥ית אֲבֹתָ֖⁠ם וְ⁠כֻלָּ֣⁠ם בְּ⁠שֵׁמ֑וֹת וַ⁠יֵּשְׁב֗וּ בְּ⁠י֤וֹם אֶחָד֙ לַ⁠חֹ֣דֶשׁ הָ⁠עֲשִׂירִ֔י לְ⁠דַרְי֖וֹשׁ הַ⁠דָּבָֽר׃","wa⁠ẏֽaʻàş̂ẇ-kén֮ bĕ̇né֣y ha⁠ġwòláh֒ wa⁠yi̇bá̇dĕlẇ֩ ʻezĕrá֨ʼ ha⁠kò̇hé֜n ʼànáşǐ֨ym ráʼşé֧̌y há⁠ʼáb֛wòţ lĕ⁠bé֥yţ ʼàbòţá֖⁠m wĕ⁠kulá֣̇⁠m bĕ̇⁠şé̌m֑wòţ wa⁠yé̇şĕ̌b֗ẇ bĕ̇⁠y֤wòm ʼeẖád֙ la⁠ẖò֣deş̌ há⁠ʻàşîyri֔y lĕ⁠darĕy֖wòş̌ ha⁠dá̇báֽr׃"],[10,17,"וַ⁠יְכַלּ֣וּ בַ⁠כֹּ֔ל אֲנָשִׁ֕ים הַ⁠הֹשִׁ֖יבוּ נָשִׁ֣ים נָכְרִיּ֑וֹת עַ֛ד י֥וֹם אֶחָ֖ד לַ⁠חֹ֥דֶשׁ הָ⁠רִאשֽׁוֹן׃פ","wa⁠yĕkal֣̇ẇ ba⁠kò̇֔l ʼànáşǐ֕ym ha⁠hòşǐ֖ybẇ náşǐ֣ym nákĕriẏ֑wòţ ʻa֛d y֥wòm ʼeẖá֖d la⁠ẖò֥deş̌ há⁠riʼşֽ̌wòn׃p"],[10,18,"וַ⁠יִּמָּצֵא֙ מִ⁠בְּנֵ֣י הַ⁠כֹּהֲנִ֔ים אֲשֶׁ֥ר הֹשִׁ֖יבוּ נָשִׁ֣ים נָכְרִיּ֑וֹת מִ⁠בְּנֵ֨י יֵשׁ֤וּעַ בֶּן־יֽוֹצָדָק֙ וְ⁠אֶחָ֔י⁠ו מַֽעֲשֵׂיָה֙ וֶֽ⁠אֱלִיעֶ֔זֶר וְ⁠יָרִ֖יב וּ⁠גְדַלְיָֽה׃","wa⁠yi̇má̇ẕéʼ֙ mi⁠bĕ̇né֣y ha⁠kò̇hàni֔ym ʼàşě֥r hòşǐ֖ybẇ náşǐ֣ym nákĕriẏ֑wòţ mi⁠bĕ̇né֨y yéş֤̌ẇʻa bėn-yֽwòẕádáq֙ wĕ⁠ʼeẖá֔y⁠w maֽʻàşé̂yáh֙ wֽe⁠ʼèliyʻe֔zer wĕ⁠yári֖yb ẇ⁠gĕdalĕyáֽh׃"],[10,19,"וַ⁠יִּתְּנ֥וּ יָדָ֖⁠ם לְ⁠הוֹצִ֣יא נְשֵׁי⁠הֶ֑ם וַ⁠אֲשֵׁמִ֥ים אֵֽיל־צֹ֖אן עַל־אַשְׁמָתָֽ⁠ם׃ס","wa⁠yi̇ţĕ̇n֥ẇ yádá֖⁠m lĕ⁠hwòẕi֣yʼ nĕşé̌y⁠he֑m wa⁠ʼàşé̌mi֥ym ʼéֽyl-ẕò֖ʼn ʻal-ʼaşĕ̌máţáֽ⁠m׃s"],[10,20,"וּ⁠מִ⁠בְּנֵ֣י אִמֵּ֔ר חֲנָ֖נִי וּ⁠זְבַדְיָֽה׃ס","ẇ⁠mi⁠bĕ̇né֣y ʼimé̇֔r ẖàná֖niy ẇ⁠zĕbadĕyáֽh׃s"],[10,21,"וּ⁠מִ⁠בְּנֵ֖י חָרִ֑ם מַעֲשֵׂיָ֤ה וְ⁠אֵֽלִיָּה֙ וּֽ⁠שְׁמַֽעְיָ֔ה וִ⁠יחִיאֵ֖ל וְ⁠עֻזִיָּֽה׃","ẇ⁠mi⁠bĕ̇né֖y ẖári֑m maʻàşé̂yá֤h wĕ⁠ʼéֽliyá̇h֙ ẇֽ⁠şĕ̌maֽʻĕyá֔h wi⁠yẖiyʼé֖l wĕ⁠ʻuziyáֽ̇h׃"],[10,22,"וּ⁠מִ⁠בְּנֵ֖י פַּשְׁח֑וּר אֶלְיוֹעֵינַ֤י מַֽעֲשֵׂיָה֙ יִשְׁמָעֵ֣אל נְתַנְאֵ֔ל יוֹזָבָ֖ד וְ⁠אֶלְעָשָֽׂה׃ס","ẇ⁠mi⁠bĕ̇né֖y pȧşĕ̌ẖ֑ẇr ʼelĕywòʻéyna֤y maֽʻàşé̂yáh֙ yişĕ̌máʻé֣ʼl nĕţanĕʼé֔l ywòzábá֖d wĕ⁠ʼelĕʻáşáֽ̂h׃s"],[10,23,"וּ⁠מִֽן־הַ⁠לְוִיִּ֑ם יוֹזָבָ֣ד וְ⁠שִׁמְעִ֗י וְ⁠קֵֽלָיָה֙ ה֣וּא קְלִיטָ֔א פְּתַֽחְיָ֥ה יְהוּדָ֖ה וֶ⁠אֱלִיעֶֽזֶר׃ס","ẇ⁠miֽn-ha⁠lĕwiyi֑̇m ywòzábá֣d wĕ⁠şǐmĕʻi֗y wĕ⁠qéֽláyáh֙ h֣ẇʼ qĕliytá֔ʼ pĕ̇ţaֽẖĕyá֥h yĕhẇdá֖h we⁠ʼèliyʻeֽzer׃s"],[10,24,"וּ⁠מִן־הַ⁠מְשֹׁרְרִ֖ים אֶלְיָשִׁ֑יב וּ⁠מִן־הַ⁠שֹּׁ֣עֲרִ֔ים שַׁלֻּ֥ם וָ⁠טֶ֖לֶם וְ⁠אוּרִֽי׃ס","ẇ⁠min-ha⁠mĕşò̌rĕri֖ym ʼelĕyáşǐ֑yb ẇ⁠min-ha⁠şò֣̇̌ʻàri֔ym şǎlu֥̇m wá⁠te֖lem wĕ⁠ʼẇriֽy׃s"],[10,25,"וּ⁠מִֽ⁠יִּשְׂרָאֵ֑ל מִ⁠בְּנֵ֣י פַרְעֹ֡שׁ רַ֠מְיָה וְ⁠יִזִּיָּ֤ה וּ⁠מַלְכִּיָּה֙ וּ⁠מִיָּמִ֣ן וְ⁠אֶלְעָזָ֔ר וּ⁠מַלְכִּיָּ֖ה וּ⁠בְנָיָֽה׃ס","ẇ⁠miֽ⁠yi̇şĕ̂ráʼé֑l mi⁠bĕ̇né֣y parĕʻò֡ş̌ ra֠mĕyáh wĕ⁠yizi̇yá֤̇h ẇ⁠malĕki̇yá̇h֙ ẇ⁠miyá̇mi֣n wĕ⁠ʼelĕʻázá֔r ẇ⁠malĕki̇yá֖̇h ẇ⁠bĕnáyáֽh׃s"],[10,26,"וּ⁠מִ⁠בְּנֵ֖י עֵילָ֑ם מַתַּנְיָ֤ה זְכַרְיָה֙ וִ⁠יחִיאֵ֣ל וְ⁠עַבְדִּ֔י וִ⁠ירֵמ֖וֹת וְ⁠אֵלִיָּֽה׃ס","ẇ⁠mi⁠bĕ̇né֖y ʻéylá֑m maţȧnĕyá֤h zĕkarĕyáh֙ wi⁠yẖiyʼé֣l wĕ⁠ʻabĕdi̇֔y wi⁠yrém֖wòţ wĕ⁠ʼéliyáֽ̇h׃s"],[10,27,"וּ⁠מִ⁠בְּנֵ֖י זַתּ֑וּא אֶלְיוֹעֵנַ֤י אֶלְיָשִׁיב֙ מַתַּנְיָ֣ה וִֽ⁠ירֵמ֔וֹת וְ⁠זָבָ֖ד וַ⁠עֲזִיזָֽא׃ס","ẇ⁠mi⁠bĕ̇né֖y zaţ֑̇ẇʼ ʼelĕywòʻéna֤y ʼelĕyáşǐyb֙ maţȧnĕyá֣h wiֽ⁠yrém֔wòţ wĕ⁠zábá֖d wa⁠ʻàziyzáֽʼ׃s"],[10,28,"וּ⁠מִ⁠בְּנֵ֖י בֵּבָ֑י יְהוֹחָנָ֥ן חֲנַנְיָ֖ה זַבַּ֥י עַתְלָֽי׃ס","ẇ⁠mi⁠bĕ̇né֖y bé̇bá֑y yĕhwòẖáná֥n ẖànanĕyá֖h zabȧ֥y ʻaţĕláֽy׃s"],[10,29,"וּ⁠מִ⁠בְּנֵ֖י בָּנִ֑י מְשֻׁלָּ֤ם מַלּוּךְ֙ וַ⁠עֲדָיָ֔ה יָשׁ֖וּב וּ⁠שְׁאָ֥ל ירמות׃ס","ẇ⁠mi⁠bĕ̇né֖y bá̇ni֑y mĕşǔlá֤̇m mal̇ẇkĕ֙ wa⁠ʻàdáyá֔h yáş֖̌ẇb ẇ⁠şĕ̌ʼá֥l yrmwţ׃s"],[10,30,"וּ⁠מִ⁠בְּנֵ֛י פַּחַ֥ת מוֹאָ֖ב עַדְנָ֣א וּ⁠כְלָ֑ל בְּנָיָ֤ה מַעֲשֵׂיָה֙ מַתַּנְיָ֣ה בְצַלְאֵ֔ל וּ⁠בִנּ֖וּי וּ⁠מְנַשֶּֽׁה׃ס","ẇ⁠mi⁠bĕ̇né֛y pȧẖa֥ţ mwòʼá֖b ʻadĕná֣ʼ ẇ⁠kĕlá֑l bĕ̇náyá֤h maʻàşé̂yáh֙ maţȧnĕyá֣h bĕẕalĕʼé֔l ẇ⁠biṅ֖ẇy ẇ⁠mĕnaşėֽ̌h׃s"],[10,31,"וּ⁠בְנֵ֖י חָרִ֑ם אֱלִיעֶ֧זֶר יִשִּׁיָּ֛ה מַלְכִּיָּ֖ה שְׁמַֽעְיָ֥ה שִׁמְעֽוֹן׃","ẇ⁠bĕné֖y ẖári֑m ʼèliyʻe֧zer yişi̇̌yá֛̇h malĕki̇yá֖̇h şĕ̌maֽʻĕyá֥h şǐmĕʻֽwòn׃"],[10,32,"בְּנְיָמִ֥ן מַלּ֖וּךְ שְׁמַרְיָֽה׃ס","bĕ̇nĕyámi֥n mal֖̇ẇkĕ şĕ̌marĕyáֽh׃s"],[10,33,"מִ⁠בְּנֵ֖י חָשֻׁ֑ם מַתְּנַ֤י מַתַּתָּה֙ זָבָ֣ד אֱלִיפֶ֔לֶט יְרֵמַ֥י מְנַשֶּׁ֖ה שִׁמְעִֽי׃ס","mi⁠bĕ̇né֖y ẖáşǔ֑m maţĕ̇na֤y maţȧţá̇h֙ zábá֣d ʼèliype֔let yĕréma֥y mĕnaşė֖̌h şǐmĕʻiֽy׃s"],[10,34,"מִ⁠בְּנֵ֣י בָנִ֔י מַעֲדַ֥י עַמְרָ֖ם וְ⁠אוּאֵֽל׃ס","mi⁠bĕ̇né֣y báni֔y maʻàda֥y ʻamĕrá֖m wĕ⁠ʼẇʼéֽl׃s"],[10,35,"בְּנָיָ֥ה בֵדְיָ֖ה כלהי׃","bĕ̇náyá֥h bédĕyá֖h klhy׃"],[10,36,"וַנְיָ֥ה מְרֵמ֖וֹת אֶלְיָשִֽׁיב׃","wanĕyá֥h mĕrém֖wòţ ʼelĕyáşǐֽyb׃"],[10,37,"מַתַּנְיָ֥ה מַתְּנַ֖י ו⁠יעשו׃","maţȧnĕyá֥h maţĕ̇na֖y w⁠yʻşw׃"],[10,38,"וּ⁠בָנִ֥י וּ⁠בִנּ֖וּי שִׁמְעִֽי׃","ẇ⁠báni֥y ẇ⁠biṅ֖ẇy şǐmĕʻiֽy׃"],[10,39,"וְ⁠שֶֽׁלֶמְיָ֥ה וְ⁠נָתָ֖ן וַ⁠עֲדָיָֽה׃","wĕ⁠şěֽlemĕyá֥h wĕ⁠náţá֖n wa⁠ʻàdáyáֽh׃"],[10,40,"מַכְנַדְבַ֥י שָׁשַׁ֖י שָׁרָֽי׃","makĕnadĕba֥y şá̌şǎ֖y şá̌ráֽy׃"],[10,41,"עֲזַרְאֵ֥ל וְ⁠שֶׁלֶמְיָ֖הוּ שְׁמַרְיָֽה׃","ʻàzarĕʼé֥l wĕ⁠şělemĕyá֖hẇ şĕ̌marĕyáֽh׃"],[10,42,"שַׁלּ֥וּם אֲמַרְיָ֖ה יוֹסֵֽף׃ס","şǎl֥̇ẇm ʼàmarĕyá֖h ywòséֽp׃s"],[10,43,"מִ⁠בְּנֵ֖י נְב֑וֹ יְעִיאֵ֤ל מַתִּתְיָה֙ זָבָ֣ד זְבִינָ֔א ידו וְ⁠יוֹאֵ֖ל בְּנָיָֽה׃","mi⁠bĕ̇né֖y nĕb֑wò yĕʻiyʼé֤l maţi̇ţĕyáh֙ zábá֣d zĕbiyná֔ʼ ydw wĕ⁠ywòʼé֖l bĕ̇náyáֽh׃"],[10,44,"כָּל־אֵ֕לֶּה נשא⁠י נָשִׁ֣ים נָכְרִיּ֑וֹת וְ⁠יֵ֣שׁ מֵ⁠הֶ֣ם נָשִׁ֔ים וַ⁠יָּשִׂ֖ימוּ בָּנִֽים׃פ","ká̇l-ʼé֕lėh nşʼ⁠y náşǐ֣ym nákĕriẏ֑wòţ wĕ⁠yé֣ş̌ mé⁠he֣m náşǐ֔ym wa⁠yá̇şî֖ymẇ bá̇niֽym׃p"]],"fra-lsg1910":[[1,1,"La première année de Cyrus, roi de Perse, afin que s'accomplît la parole de l'Éternel prononcée par la bouche de Jérémie, l'Éternel réveilla l'esprit de Cyrus, roi de Perse, qui fit faire de vive voix et par écrit cette publication dans tout son royaume:","La première année de Cyrus, roi de Perse, afin que s'accomplît la parole de l'Éternel prononcée par la bouche de Jérémie, l'Éternel réveilla l'esprit de Cyrus, roi de Perse, qui fit faire de vive voix et par écrit cette publication dans tout son royaume:"],[1,2,"Ainsi parle Cyrus, roi des Perses: L'Éternel, le Dieu des cieux, m'a donné tous les royaumes de la terre, et il m'a commandé de lui bâtir une maison à Jérusalem en Juda.","Ainsi parle Cyrus, roi des Perses: L'Éternel, le Dieu des cieux, m'a donné tous les royaumes de la terre, et il m'a commandé de lui bâtir une maison à Jérusalem en Juda."],[1,3,"Qui d'entre vous est de son peuple? Que son Dieu soit avec lui, et qu'il monte à Jérusalem en Juda et bâtisse la maison de l'Éternel, le Dieu d'Israël! C'est le Dieu qui est à Jérusalem.","Qui d'entre vous est de son peuple? Que son Dieu soit avec lui, et qu'il monte à Jérusalem en Juda et bâtisse la maison de l'Éternel, le Dieu d'Israël! C'est le Dieu qui est à Jérusalem."],[1,4,"Dans tout lieu où séjournent des restes du peuple de l'Éternel, les gens du lieu leur donneront de l'argent, de l'or, des effets, et du bétail, avec des offrandes volontaires pour la maison de Dieu qui est à Jérusalem.","Dans tout lieu où séjournent des restes du peuple de l'Éternel, les gens du lieu leur donneront de l'argent, de l'or, des effets, et du bétail, avec des offrandes volontaires pour la maison de Dieu qui est à Jérusalem."],[1,5,"Les chefs de famille de Juda et de Benjamin, les sacrificateurs et les Lévites, tous ceux dont Dieu réveilla l'esprit, se levèrent pour aller bâtir la maison de l'Éternel à Jérusalem.","Les chefs de famille de Juda et de Benjamin, les sacrificateurs et les Lévites, tous ceux dont Dieu réveilla l'esprit, se levèrent pour aller bâtir la maison de l'Éternel à Jérusalem."],[1,6,"Tous leurs alentours leur donnèrent des objets d'argent, de l'or, des effets, du bétail, et des choses précieuses, outre toutes les offrandes volontaires.","Tous leurs alentours leur donnèrent des objets d'argent, de l'or, des effets, du bétail, et des choses précieuses, outre toutes les offrandes volontaires."],[1,7,"Le roi Cyrus rendit les ustensiles de la maison de l'Éternel, que Nebucadnetsar avait emportés de Jérusalem et placés dans la maison de son dieu.","Le roi Cyrus rendit les ustensiles de la maison de l'Éternel, que Nebucadnetsar avait emportés de Jérusalem et placés dans la maison de son dieu."],[1,8,"Cyrus, roi de Perse, les fit sortir par Mithredath, le trésorier, qui les remit à Scheschbatsar, prince de Juda.","Cyrus, roi de Perse, les fit sortir par Mithredath, le trésorier, qui les remit à Scheschbatsar, prince de Juda."],[1,9,"En voici le nombre: trente bassins d'or, mille bassins d'argent, vingt-neuf couteaux,","En voici le nombre: trente bassins d'or, mille bassins d'argent, vingt-neuf couteaux,"],[1,10,"trente coupes d'or, quatre cent dix coupes d'argent de second ordre, mille autres ustensiles.","trente coupes d'or, quatre cent dix coupes d'argent de second ordre, mille autres ustensiles."],[1,11,"Tous les objets d'or et d'argent étaient au nombre de cinq mille quatre cents. Scheschbatsar emporta le tout de Babylone à Jérusalem, au retour de la captivité.","Tous les objets d'or et d'argent étaient au nombre de cinq mille quatre cents. Scheschbatsar emporta le tout de Babylone à Jérusalem, au retour de la captivité."],[2,1,"Voici ceux de la province qui revinrent de l'exil, ceux que Nebucadnetsar, roi de Babylone, avait emmenés captifs à Babylone, et qui retournèrent à Jérusalem et en Juda, chacun dans sa ville.","Voici ceux de la province qui revinrent de l'exil, ceux que Nebucadnetsar, roi de Babylone, avait emmenés captifs à Babylone, et qui retournèrent à Jérusalem et en Juda, chacun dans sa ville."],[2,2,"Ils partirent avec Zorobabel, Josué, Néhémie, Seraja, Reélaja, Mardochée, Bilschan, Mispar, Bigvaï, Rehum, Baana. Nombre des hommes du peuple d'Israël:","Ils partirent avec Zorobabel, Josué, Néhémie, Seraja, Reélaja, Mardochée, Bilschan, Mispar, Bigvaï, Rehum, Baana. Nombre des hommes du peuple d'Israël:"],[2,3,"les fils de Pareosch, deux mille cent soixante-douze;","les fils de Pareosch, deux mille cent soixante-douze;"],[2,4,"les fils de Schephathia, trois cent soixante-douze;","les fils de Schephathia, trois cent soixante-douze;"],[2,5,"les fils d'Arach, sept cent soixante-quinze;","les fils d'Arach, sept cent soixante-quinze;"],[2,6,"les fils de Pachath-Moab, des fils de Josué et de Joab, deux mille huit cent douze;","les fils de Pachath-Moab, des fils de Josué et de Joab, deux mille huit cent douze;"],[2,7,"les fils d'Élam, mille deux cent cinquante-quatre;","les fils d'Élam, mille deux cent cinquante-quatre;"],[2,8,"les fils de Zatthu, neuf cent quarante-cinq;","les fils de Zatthu, neuf cent quarante-cinq;"],[2,9,"les fils de Zaccaï, sept cent soixante;","les fils de Zaccaï, sept cent soixante;"],[2,10,"les fils de Bani, six cent quarante-deux;","les fils de Bani, six cent quarante-deux;"],[2,11,"les fils de Bébaï, six cent vingt-trois;","les fils de Bébaï, six cent vingt-trois;"],[2,12,"les fils d'Azgad, mille deux cent vingt-deux;","les fils d'Azgad, mille deux cent vingt-deux;"],[2,13,"les fils d'Adonikam, six cent soixante-six;","les fils d'Adonikam, six cent soixante-six;"],[2,14,"les fils de Bigvaï, deux mille cinquante-six;","les fils de Bigvaï, deux mille cinquante-six;"],[2,15,"les fils d'Adin, quatre cent cinquante-quatre;","les fils d'Adin, quatre cent cinquante-quatre;"],[2,16,"les fils d'Ather, de la famille d'Ézéchias, quatre-vingt-dix-huit;","les fils d'Ather, de la famille d'Ézéchias, quatre-vingt-dix-huit;"],[2,17,"les fils de Betsaï, trois cent vingt-trois;","les fils de Betsaï, trois cent vingt-trois;"],[2,18,"les fils de Jora, cent douze;","les fils de Jora, cent douze;"],[2,19,"les fils de Haschum, deux cent vingt-trois;","les fils de Haschum, deux cent vingt-trois;"],[2,20,"les fils de Guibbar, quatre-vingt-quinze;","les fils de Guibbar, quatre-vingt-quinze;"],[2,21,"les fils de Bethléhem, cent vingt-trois;","les fils de Bethléhem, cent vingt-trois;"],[2,22,"les gens de Nethopha, cinquante-six;","les gens de Nethopha, cinquante-six;"],[2,23,"les gens d'Anathoth, cent vingt-huit;","les gens d'Anathoth, cent vingt-huit;"],[2,24,"les fils d'Azmaveth, quarante-deux;","les fils d'Azmaveth, quarante-deux;"],[2,25,"les fils de Kirjath-Arim, de Kephira et de Beéroth, sept cent quarante trois;","les fils de Kirjath-Arim, de Kephira et de Beéroth, sept cent quarante trois;"],[2,26,"les fils de Rama et de Guéba, six cent vingt et un;","les fils de Rama et de Guéba, six cent vingt et un;"],[2,27,"les gens de Micmas, cent vingt-deux;","les gens de Micmas, cent vingt-deux;"],[2,28,"les gens de Béthel et d'Aï, deux cent vingt-trois;","les gens de Béthel et d'Aï, deux cent vingt-trois;"],[2,29,"les fils de Nebo, cinquante-deux;","les fils de Nebo, cinquante-deux;"],[2,30,"les fils de Magbisch, cent cinquante-six;","les fils de Magbisch, cent cinquante-six;"],[2,31,"les fils de l'autre Élam, mille deux cent cinquante-quatre;","les fils de l'autre Élam, mille deux cent cinquante-quatre;"],[2,32,"les fils de Harim, trois cent vingt;","les fils de Harim, trois cent vingt;"],[2,33,"les fils de Lod, de Hadid et d'Ono, sept cent vingt-cinq;","les fils de Lod, de Hadid et d'Ono, sept cent vingt-cinq;"],[2,34,"les fils de Jéricho, trois cent quarante-cinq;","les fils de Jéricho, trois cent quarante-cinq;"],[2,35,"les fils de Senaa, trois mille six cent trente.","les fils de Senaa, trois mille six cent trente."],[2,36,"Sacrificateurs: les fils de Jedaeja, de la maison de Josué, neuf cent soixante-treize;","Sacrificateurs: les fils de Jedaeja, de la maison de Josué, neuf cent soixante-treize;"],[2,37,"les fils d'Immer, mille cinquante-deux;","les fils d'Immer, mille cinquante-deux;"],[2,38,"les fils de Paschhur, mille deux cent quarante-sept;","les fils de Paschhur, mille deux cent quarante-sept;"],[2,39,"les fils de Harim, mille dix-sept.","les fils de Harim, mille dix-sept."],[2,40,"Lévites: les fils de Josué et de Kadmiel, des fils d'Hodavia, soixante quatorze.","Lévites: les fils de Josué et de Kadmiel, des fils d'Hodavia, soixante quatorze."],[2,41,"Chantres: les fils d'Asaph, cent vingt-huit.","Chantres: les fils d'Asaph, cent vingt-huit."],[2,42,"Fils des portiers: les fils de Schallum, les fils d'Ather, les fils de Thalmon, les fils d'Akkub, les fils de Hathitha, les fils de Schobaï, en tout cent trente-neuf.","Fils des portiers: les fils de Schallum, les fils d'Ather, les fils de Thalmon, les fils d'Akkub, les fils de Hathitha, les fils de Schobaï, en tout cent trente-neuf."],[2,43,"Néthiniens: les fils de Tsicha, les fils de Hasupha, les fils de Thabbaoth,","Néthiniens: les fils de Tsicha, les fils de Hasupha, les fils de Thabbaoth,"],[2,44,"les fils de Kéros, les fils de Siaha, les fils de Padon,","les fils de Kéros, les fils de Siaha, les fils de Padon,"],[2,45,"les fils de Lebana, les fils de Hagaba, les fils d'Akkub,","les fils de Lebana, les fils de Hagaba, les fils d'Akkub,"],[2,46,"les fils de Hagab, les fils de Schamlaï, les fils de Hanan,","les fils de Hagab, les fils de Schamlaï, les fils de Hanan,"],[2,47,"les fils de Guiddel, les fils de Gachar, les fils de Reaja,","les fils de Guiddel, les fils de Gachar, les fils de Reaja,"],[2,48,"les fils de Retsin, les fils de Nekoda, les fils de Gazzam,","les fils de Retsin, les fils de Nekoda, les fils de Gazzam,"],[2,49,"les fils d'Uzza, les fils de Paséach, les fils de Bésaï,","les fils d'Uzza, les fils de Paséach, les fils de Bésaï,"],[2,50,"les fils d'Asna, les fils de Mehunim, les fils de Nephusim,","les fils d'Asna, les fils de Mehunim, les fils de Nephusim,"],[2,51,"les fils de Bakbuk, les fils de Hakupha, les fils de Harhur,","les fils de Bakbuk, les fils de Hakupha, les fils de Harhur,"],[2,52,"les fils de Batsluth, les fils de Mehida, les fils de Harscha,","les fils de Batsluth, les fils de Mehida, les fils de Harscha,"],[2,53,"les fils de Barkos, les fils de Sisera, les fils de Thamach,","les fils de Barkos, les fils de Sisera, les fils de Thamach,"],[2,54,"les fils de Netsiach, les fils de Hathipha.","les fils de Netsiach, les fils de Hathipha."],[2,55,"Fils des serviteurs de Salomon: les fils de Sothaï, les fils de Sophéreth, les fils de Peruda,","Fils des serviteurs de Salomon: les fils de Sothaï, les fils de Sophéreth, les fils de Peruda,"],[2,56,"les fils de Jaala, les fils de Darkon, les fils de Guiddel,","les fils de Jaala, les fils de Darkon, les fils de Guiddel,"],[2,57,"les fils de Schephathia, les fils de Hatthil, les fils de Pokéreth-Hatsebaïm, les fils d'Ami.","les fils de Schephathia, les fils de Hatthil, les fils de Pokéreth-Hatsebaïm, les fils d'Ami."],[2,58,"Total des Néthiniens et des fils des serviteurs de Salomon: trois cent quatre-vingt-douze.","Total des Néthiniens et des fils des serviteurs de Salomon: trois cent quatre-vingt-douze."],[2,59,"Voici ceux qui partirent de Thel-Mélach, de Thel-Harscha, de Kerub-Addan, et qui ne purent pas faire connaître leur maison paternelle et leur race, pour prouver qu'ils étaient d'Israël.","Voici ceux qui partirent de Thel-Mélach, de Thel-Harscha, de Kerub-Addan, et qui ne purent pas faire connaître leur maison paternelle et leur race, pour prouver qu'ils étaient d'Israël."],[2,60,"Les fils de Delaja, les fils de Tobija, les fils de Nekoda, six cent cinquante-deux.","Les fils de Delaja, les fils de Tobija, les fils de Nekoda, six cent cinquante-deux."],[2,61,"Et parmi les fils des sacrificateurs: les fils de Habaja, les fils d'Hakkots, les fils de Barzillaï, qui avait pris pour femme une des filles de Barzillaï, le Galaadite, et fut appelé de leur nom.","Et parmi les fils des sacrificateurs: les fils de Habaja, les fils d'Hakkots, les fils de Barzillaï, qui avait pris pour femme une des filles de Barzillaï, le Galaadite, et fut appelé de leur nom."],[2,62,"Ils cherchèrent leurs titres généalogiques, mais ils ne les trouvèrent point. On les exclut du sacerdoce,","Ils cherchèrent leurs titres généalogiques, mais ils ne les trouvèrent point. On les exclut du sacerdoce,"],[2,63,"et le gouverneur leur dit de ne pas manger des choses très saintes jusqu'à ce qu'un sacrificateur ait consulté l'urim et le thummim.","et le gouverneur leur dit de ne pas manger des choses très saintes jusqu'à ce qu'un sacrificateur ait consulté l'urim et le thummim."],[2,64,"L'assemblée tout entière était de quarante-deux mille trois cent soixante personnes,","L'assemblée tout entière était de quarante-deux mille trois cent soixante personnes,"],[2,65,"sans compter leurs serviteurs et leurs servantes, au nombre de sept mille trois cent trente-sept. Parmi eux se trouvaient deux cents chantres et chanteuses.","sans compter leurs serviteurs et leurs servantes, au nombre de sept mille trois cent trente-sept. Parmi eux se trouvaient deux cents chantres et chanteuses."],[2,66,"Ils avaient sept cent trente-six chevaux, deux cent quarante-cinq mulets,","Ils avaient sept cent trente-six chevaux, deux cent quarante-cinq mulets,"],[2,67,"quatre cent trente-cinq chameaux, et six mille sept cent vingt ânes.","quatre cent trente-cinq chameaux, et six mille sept cent vingt ânes."],[2,68,"Plusieurs des chefs de famille, à leur arrivée vers la maison de l'Éternel à Jérusalem, firent des offrandes volontaires pour la maison de Dieu, afin qu'on la rétablît sur le lieu où elle avait été.","Plusieurs des chefs de famille, à leur arrivée vers la maison de l'Éternel à Jérusalem, firent des offrandes volontaires pour la maison de Dieu, afin qu'on la rétablît sur le lieu où elle avait été."],[2,69,"Ils donnèrent au trésor de l'oeuvre, selon leurs moyens, soixante et un mille dariques d'or, cinq mille mines d'argent, et cent tuniques sacerdotales.","Ils donnèrent au trésor de l'oeuvre, selon leurs moyens, soixante et un mille dariques d'or, cinq mille mines d'argent, et cent tuniques sacerdotales."],[2,70,"Les sacrificateurs et les Lévites, les gens du peuple, les chantres, les portiers et les Néthiniens s'établirent dans leurs villes. Tout Israël habita dans ses villes.","Les sacrificateurs et les Lévites, les gens du peuple, les chantres, les portiers et les Néthiniens s'établirent dans leurs villes. Tout Israël habita dans ses villes."],[3,1,"Le septième mois arriva, et les enfants d'Israël étaient dans leurs villes. Alors le peuple s'assembla comme un seul homme à Jérusalem.","Le septième mois arriva, et les enfants d'Israël étaient dans leurs villes. Alors le peuple s'assembla comme un seul homme à Jérusalem."],[3,2,"Josué, fils de Jotsadak, avec ses frères les sacrificateurs, et Zorobabel, fils de Schealthiel, avec ses frères, se levèrent et bâtirent l'autel du Dieu d'Israël, pour y offrir des holocaustes, selon ce qui est écrit dans la loi de Moïse, homme de Dieu.","Josué, fils de Jotsadak, avec ses frères les sacrificateurs, et Zorobabel, fils de Schealthiel, avec ses frères, se levèrent et bâtirent l'autel du Dieu d'Israël, pour y offrir des holocaustes, selon ce qui est écrit dans la loi de Moïse, homme de Dieu."],[3,3,"Ils rétablirent l'autel sur ses fondements, quoiqu'ils eussent à craindre les peuples du pays, et ils y offrirent des holocaustes à l'Éternel, les holocaustes du matin et du soir.","Ils rétablirent l'autel sur ses fondements, quoiqu'ils eussent à craindre les peuples du pays, et ils y offrirent des holocaustes à l'Éternel, les holocaustes du matin et du soir."],[3,4,"Ils célébrèrent la fête des tabernacles, comme il est écrit, et ils offrirent jour par jour des holocaustes, selon le nombre ordonné pour chaque jour.","Ils célébrèrent la fête des tabernacles, comme il est écrit, et ils offrirent jour par jour des holocaustes, selon le nombre ordonné pour chaque jour."],[3,5,"Après cela, ils offrirent l'holocauste perpétuel, les holocaustes des nouvelles lunes et de toutes les solennités consacrées à l'Éternel, et ceux de quiconque faisait des offrandes volontaires à l'Éternel.","Après cela, ils offrirent l'holocauste perpétuel, les holocaustes des nouvelles lunes et de toutes les solennités consacrées à l'Éternel, et ceux de quiconque faisait des offrandes volontaires à l'Éternel."],[3,6,"Dès le premier jour du septième mois, ils commencèrent à offrir à l'Éternel des holocaustes. Cependant les fondements du temple de l'Éternel n'étaient pas encore posés.","Dès le premier jour du septième mois, ils commencèrent à offrir à l'Éternel des holocaustes. Cependant les fondements du temple de l'Éternel n'étaient pas encore posés."],[3,7,"On donna de l'argent aux tailleurs de pierres et aux charpentiers, et des vivres, des boissons et de l'huile aux Sidoniens et aux Tyriens, pour qu'ils amenassent par mer jusqu'à Japho des bois de cèdre du Liban, suivant l'autorisation qu'on avait eue de Cyrus, roi de Perse.","On donna de l'argent aux tailleurs de pierres et aux charpentiers, et des vivres, des boissons et de l'huile aux Sidoniens et aux Tyriens, pour qu'ils amenassent par mer jusqu'à Japho des bois de cèdre du Liban, suivant l'autorisation qu'on avait eue de Cyrus, roi de Perse."],[3,8,"La seconde année depuis leur arrivée à la maison de Dieu à Jérusalem, au second mois, Zorobabel, fils de Schealthiel, Josué, fils de Jotsadak, avec le reste de leurs frères les sacrificateurs et les Lévites, et tous ceux qui étaient revenus de la captivité à Jérusalem, se mirent à l'oeuvre et chargèrent les Lévites de vingt ans et au-dessus de surveiller les travaux de la maison de l'Éternel.","La seconde année depuis leur arrivée à la maison de Dieu à Jérusalem, au second mois, Zorobabel, fils de Schealthiel, Josué, fils de Jotsadak, avec le reste de leurs frères les sacrificateurs et les Lévites, et tous ceux qui étaient revenus de la captivité à Jérusalem, se mirent à l'oeuvre et chargèrent les Lévites de vingt ans et au-dessus de surveiller les travaux de la maison de l'Éternel."],[3,9,"Et Josué, avec ses fils et ses frères, Kadmiel, avec ses fils, fils de Juda, les fils de Hénadad, avec leurs fils et leurs frères les Lévites, se préparèrent tous ensemble à surveiller ceux qui travaillaient à la maison de Dieu.","Et Josué, avec ses fils et ses frères, Kadmiel, avec ses fils, fils de Juda, les fils de Hénadad, avec leurs fils et leurs frères les Lévites, se préparèrent tous ensemble à surveiller ceux qui travaillaient à la maison de Dieu."],[3,10,"Lorsque les ouvriers posèrent les fondements du temple de l'Éternel, on fit assister les sacrificateurs en costume, avec les trompettes, et les Lévites, fils d'Asaph, avec les cymbales, afin qu'ils célébrassent l'Éternel, d'après les ordonnances de David, roi d'Israël.","Lorsque les ouvriers posèrent les fondements du temple de l'Éternel, on fit assister les sacrificateurs en costume, avec les trompettes, et les Lévites, fils d'Asaph, avec les cymbales, afin qu'ils célébrassent l'Éternel, d'après les ordonnances de David, roi d'Israël."],[3,11,"Ils chantaient, célébrant et louant l'Éternel par ces paroles: Car il est bon, car sa miséricorde pour Israël dure à toujours! Et tout le peuple poussait de grands cris de joie en célébrant l'Éternel, parce qu'on posait les fondements de la maison de l'Éternel.","Ils chantaient, célébrant et louant l'Éternel par ces paroles: Car il est bon, car sa miséricorde pour Israël dure à toujours! Et tout le peuple poussait de grands cris de joie en célébrant l'Éternel, parce qu'on posait les fondements de la maison de l'Éternel."],[3,12,"Mais plusieurs des sacrificateurs et des Lévites, et des chefs de famille âgés, qui avaient vu la première maison, pleuraient à grand bruit pendant qu'on posait sous leurs yeux les fondements de cette maison. Beaucoup d'autres faisaient éclater leur joie par des cris,","Mais plusieurs des sacrificateurs et des Lévites, et des chefs de famille âgés, qui avaient vu la première maison, pleuraient à grand bruit pendant qu'on posait sous leurs yeux les fondements de cette maison. Beaucoup d'autres faisaient éclater leur joie par des cris,"],[3,13,"en sorte qu'on ne pouvait distinguer le bruit des cris de joie d'avec le bruit des pleurs parmi le peuple, car le peuple poussait de grands cris dont le son s'entendait au loin.","en sorte qu'on ne pouvait distinguer le bruit des cris de joie d'avec le bruit des pleurs parmi le peuple, car le peuple poussait de grands cris dont le son s'entendait au loin."],[4,1,"Les ennemis de Juda et de Benjamin apprirent que les fils de la captivité bâtissaient un temple à l'Éternel, le Dieu d'Israël.","Les ennemis de Juda et de Benjamin apprirent que les fils de la captivité bâtissaient un temple à l'Éternel, le Dieu d'Israël."],[4,2,"Ils vinrent auprès de Zorobabel et des chefs de familles, et leur dirent: Nous bâtirons avec vous; car, comme vous, nous invoquons votre Dieu, et nous lui offrons des sacrifices depuis le temps d'Ésar-Haddon, roi d'Assyrie, qui nous a fait monter ici.","Ils vinrent auprès de Zorobabel et des chefs de familles, et leur dirent: Nous bâtirons avec vous; car, comme vous, nous invoquons votre Dieu, et nous lui offrons des sacrifices depuis le temps d'Ésar-Haddon, roi d'Assyrie, qui nous a fait monter ici."],[4,3,"Mais Zorobabel, Josué, et les autres chefs des familles d'Israël, leur répondirent: Ce n'est pas à vous et à nous de bâtir la maison de notre Dieu; nous la bâtirons nous seuls à l'Éternel, le Dieu d'Israël, comme nous l'a ordonné le roi Cyrus, roi de Perse.","Mais Zorobabel, Josué, et les autres chefs des familles d'Israël, leur répondirent: Ce n'est pas à vous et à nous de bâtir la maison de notre Dieu; nous la bâtirons nous seuls à l'Éternel, le Dieu d'Israël, comme nous l'a ordonné le roi Cyrus, roi de Perse."],[4,4,"Alors les gens du pays découragèrent le peuple de Juda; ils l'intimidèrent pour l'empêcher de bâtir,","Alors les gens du pays découragèrent le peuple de Juda; ils l'intimidèrent pour l'empêcher de bâtir,"],[4,5,"et ils gagnèrent à prix d'argent des conseillers pour faire échouer son entreprise. Il en fut ainsi pendant toute la vie de Cyrus, roi de Perse, et jusqu'au règne de Darius, roi de Perse.","et ils gagnèrent à prix d'argent des conseillers pour faire échouer son entreprise. Il en fut ainsi pendant toute la vie de Cyrus, roi de Perse, et jusqu'au règne de Darius, roi de Perse."],[4,6,"Sous le règne d'Assuérus, au commencement de son règne, ils écrivirent une accusation contre les habitants de Juda et de Jérusalem.","Sous le règne d'Assuérus, au commencement de son règne, ils écrivirent une accusation contre les habitants de Juda et de Jérusalem."],[4,7,"Et du temps d'Artaxerxès, Bischlam, Mithredath, Thabeel, et le reste de leurs collègues, écrivirent à Artaxerxès, roi de Perse. La lettre fut transcrite en caractères araméens et traduite en araméen.","Et du temps d'Artaxerxès, Bischlam, Mithredath, Thabeel, et le reste de leurs collègues, écrivirent à Artaxerxès, roi de Perse. La lettre fut transcrite en caractères araméens et traduite en araméen."],[4,8,"Rehum, gouverneur, et Schimschaï, secrétaire écrivirent au roi Artaxerxès la lettre suivante concernant Jérusalem:","Rehum, gouverneur, et Schimschaï, secrétaire écrivirent au roi Artaxerxès la lettre suivante concernant Jérusalem:"],[4,9,"Rehum, gouverneur, Schimschaï, secrétaire, et le reste de leurs collègues, ceux de Din, d'Arpharsathac, de Tharpel, d'Apharas, d'Érec, de Babylone, de Suse, de Déha, d'Élam,","Rehum, gouverneur, Schimschaï, secrétaire, et le reste de leurs collègues, ceux de Din, d'Arpharsathac, de Tharpel, d'Apharas, d'Érec, de Babylone, de Suse, de Déha, d'Élam,"],[4,10,"et les autres peuples que le grand et illustre Osnappar a transportés et établis dans la ville de Samarie et autres lieux de ce côté du fleuve, etc.","et les autres peuples que le grand et illustre Osnappar a transportés et établis dans la ville de Samarie et autres lieux de ce côté du fleuve, etc."],[4,11,"C'est ici la copie de la lettre qu'ils envoyèrent au roi Artaxerxès: Tes serviteurs, les gens de ce côté du fleuve, etc.","C'est ici la copie de la lettre qu'ils envoyèrent au roi Artaxerxès: Tes serviteurs, les gens de ce côté du fleuve, etc."],[4,12,"Que le roi sache que les Juifs partis de chez toi et arrivés parmi nous à Jérusalem rebâtissent la ville rebelle et méchante, en relèvent les murs et en restaurent les fondements.","Que le roi sache que les Juifs partis de chez toi et arrivés parmi nous à Jérusalem rebâtissent la ville rebelle et méchante, en relèvent les murs et en restaurent les fondements."],[4,13,"Que le roi sache donc que, si cette ville est rebâtie et si ses murs sont relevés, ils ne paieront ni tribut, ni impôt, ni droit de passage, et que le trésor royal en souffrira.","Que le roi sache donc que, si cette ville est rebâtie et si ses murs sont relevés, ils ne paieront ni tribut, ni impôt, ni droit de passage, et que le trésor royal en souffrira."],[4,14,"Or, comme nous mangeons le sel du palais et qu'il ne nous paraît pas convenable de voir mépriser le roi, nous envoyons au roi ces informations.","Or, comme nous mangeons le sel du palais et qu'il ne nous paraît pas convenable de voir mépriser le roi, nous envoyons au roi ces informations."],[4,15,"Qu'on fasse des recherches dans le livre des mémoires de tes pères; et tu trouveras et verras dans le livre des mémoires que cette ville est une ville rebelle, funeste aux rois et aux provinces, et qu'on s'y est livré à la révolte dès les temps anciens. C'est pourquoi cette ville a été détruite.","Qu'on fasse des recherches dans le livre des mémoires de tes pères; et tu trouveras et verras dans le livre des mémoires que cette ville est une ville rebelle, funeste aux rois et aux provinces, et qu'on s'y est livré à la révolte dès les temps anciens. C'est pourquoi cette ville a été détruite."],[4,16,"Nous faisons savoir au roi que, si cette ville est rebâtie et si ses murs sont relevés, par cela même tu n'auras plus de possession de ce côté du fleuve.","Nous faisons savoir au roi que, si cette ville est rebâtie et si ses murs sont relevés, par cela même tu n'auras plus de possession de ce côté du fleuve."],[4,17,"Réponse envoyée par le roi à Rehum, gouverneur, à Schimschaï, secrétaire, et au reste de leurs collègues, demeurant à Samarie et autres lieux de l'autre côté du fleuve: Salut, etc.","Réponse envoyée par le roi à Rehum, gouverneur, à Schimschaï, secrétaire, et au reste de leurs collègues, demeurant à Samarie et autres lieux de l'autre côté du fleuve: Salut, etc."],[4,18,"La lettre que vous nous avez envoyée a été lue exactement devant moi.","La lettre que vous nous avez envoyée a été lue exactement devant moi."],[4,19,"J'ai donné ordre de faire des recherches; et l'on a trouvé que dès les temps anciens cette ville s'est soulevée contre les rois, et qu'on s'y est livré à la sédition et à la révolte.","J'ai donné ordre de faire des recherches; et l'on a trouvé que dès les temps anciens cette ville s'est soulevée contre les rois, et qu'on s'y est livré à la sédition et à la révolte."],[4,20,"Il y eut à Jérusalem des rois puissants, maîtres de tout le pays de l'autre côté du fleuve, et auxquels on payait tribut, impôt, et droit de passage.","Il y eut à Jérusalem des rois puissants, maîtres de tout le pays de l'autre côté du fleuve, et auxquels on payait tribut, impôt, et droit de passage."],[4,21,"En conséquence, ordonnez de faire cesser les travaux de ces gens, afin que cette ville ne se rebâtisse point avant une autorisation de ma part.","En conséquence, ordonnez de faire cesser les travaux de ces gens, afin que cette ville ne se rebâtisse point avant une autorisation de ma part."],[4,22,"Gardez-vous de mettre en cela de la négligence, de peur que le mal n'augmente au préjudice des rois.","Gardez-vous de mettre en cela de la négligence, de peur que le mal n'augmente au préjudice des rois."],[4,23,"Aussitôt que la copie de la lettre du roi Artaxerxès eut été lue devant Rehum, Schimschaï, le secrétaire, et leurs collègues, ils allèrent en hâte à Jérusalem vers les Juifs, et firent cesser leurs travaux par violence et par force.","Aussitôt que la copie de la lettre du roi Artaxerxès eut été lue devant Rehum, Schimschaï, le secrétaire, et leurs collègues, ils allèrent en hâte à Jérusalem vers les Juifs, et firent cesser leurs travaux par violence et par force."],[4,24,"Alors s'arrêta l'ouvrage de la maison de Dieu à Jérusalem, et il fut interrompu jusqu'à la seconde année du règne de Darius, roi de Perse.","Alors s'arrêta l'ouvrage de la maison de Dieu à Jérusalem, et il fut interrompu jusqu'à la seconde année du règne de Darius, roi de Perse."],[5,1,"Aggée, le prophète, et Zacharie, fils d'Iddo, le prophète, prophétisèrent aux Juifs qui étaient en Juda et à Jérusalem, au nom du Dieu d'Israël.","Aggée, le prophète, et Zacharie, fils d'Iddo, le prophète, prophétisèrent aux Juifs qui étaient en Juda et à Jérusalem, au nom du Dieu d'Israël."],[5,2,"Alors Zorobabel, fils de Schealthiel, et Josué, fils de Jotsadak, se levèrent et commencèrent à bâtir la maison de Dieu à Jérusalem. Et avec eux étaient les prophètes de Dieu, qui les assistaient.","Alors Zorobabel, fils de Schealthiel, et Josué, fils de Jotsadak, se levèrent et commencèrent à bâtir la maison de Dieu à Jérusalem. Et avec eux étaient les prophètes de Dieu, qui les assistaient."],[5,3,"Dans ce même temps, Thathnaï, gouverneur de ce côté du fleuve, Schethar-Boznaï, et leurs collègues, vinrent auprès d'eux et leur parlèrent ainsi: Qui vous a donné l'autorisation de bâtir cette maison et de relever ces murs?","Dans ce même temps, Thathnaï, gouverneur de ce côté du fleuve, Schethar-Boznaï, et leurs collègues, vinrent auprès d'eux et leur parlèrent ainsi: Qui vous a donné l'autorisation de bâtir cette maison et de relever ces murs?"],[5,4,"Ils leur dirent encore: Quels sont les noms des hommes qui construisent cet édifice?","Ils leur dirent encore: Quels sont les noms des hommes qui construisent cet édifice?"],[5,5,"Mais l'oeil de Dieu veillait sur les anciens des Juifs. Et on laissa continuer les travaux pendant l'envoi d'un rapport à Darius et jusqu'à la réception d'une lettre sur cet objet.","Mais l'oeil de Dieu veillait sur les anciens des Juifs. Et on laissa continuer les travaux pendant l'envoi d'un rapport à Darius et jusqu'à la réception d'une lettre sur cet objet."],[5,6,"Copie de la lettre envoyée au roi Darius par Thathnaï, gouverneur de ce côté du fleuve. Schethar-Boznaï, et leurs collègues d'Apharsac, demeurant de ce côté du fleuve.","Copie de la lettre envoyée au roi Darius par Thathnaï, gouverneur de ce côté du fleuve. Schethar-Boznaï, et leurs collègues d'Apharsac, demeurant de ce côté du fleuve."],[5,7,"Ils lui adressèrent un rapport ainsi conçu: Au roi Darius, salut!","Ils lui adressèrent un rapport ainsi conçu: Au roi Darius, salut!"],[5,8,"Que le roi sache que nous sommes allés dans la province de Juda, à la maison du grand Dieu. Elle se construit en pierres de taille, et le bois se pose dans les murs; le travail marche rapidement et réussit entre leurs mains.","Que le roi sache que nous sommes allés dans la province de Juda, à la maison du grand Dieu. Elle se construit en pierres de taille, et le bois se pose dans les murs; le travail marche rapidement et réussit entre leurs mains."],[5,9,"Nous avons interrogé les anciens, et nous leur avons ainsi parlé: Qui vous a donné l'autorisation de bâtir cette maison et de relever ces murs?","Nous avons interrogé les anciens, et nous leur avons ainsi parlé: Qui vous a donné l'autorisation de bâtir cette maison et de relever ces murs?"],[5,10,"Nous leur avons aussi demandé leurs noms pour te les faire connaître, et nous avons mis par écrit les noms des hommes qui sont à leur tête.","Nous leur avons aussi demandé leurs noms pour te les faire connaître, et nous avons mis par écrit les noms des hommes qui sont à leur tête."],[5,11,"Voici la réponse qu'ils nous ont faite: Nous sommes les serviteurs du Dieu des cieux et de la terre, et nous rebâtissons la maison qui avait été construite il y a bien des années; un grand roi d'Israël l'avait bâtie et achevée.","Voici la réponse qu'ils nous ont faite: Nous sommes les serviteurs du Dieu des cieux et de la terre, et nous rebâtissons la maison qui avait été construite il y a bien des années; un grand roi d'Israël l'avait bâtie et achevée."],[5,12,"Mais après que nos pères eurent irrité le Dieu des cieux, il les livra entre les mains de Nebucadnetsar, roi de Babylone, le Chaldéen, qui détruisit cette maison et emmena le peuple captif à Babylone.","Mais après que nos pères eurent irrité le Dieu des cieux, il les livra entre les mains de Nebucadnetsar, roi de Babylone, le Chaldéen, qui détruisit cette maison et emmena le peuple captif à Babylone."],[5,13,"Toutefois, la première année de Cyrus, roi de Babylone, le roi Cyrus donna l'ordre de rebâtir cette maison de Dieu.","Toutefois, la première année de Cyrus, roi de Babylone, le roi Cyrus donna l'ordre de rebâtir cette maison de Dieu."],[5,14,"Et même le roi Cyrus ôta du temple de Babylone les ustensiles d'or et d'argent de la maison de Dieu, que Nebucadnetsar avait enlevés du temple de Jérusalem et transportés dans le temple de Babylone, il les fit remettre au nommé Scheschbatsar, qu'il établit gouverneur,","Et même le roi Cyrus ôta du temple de Babylone les ustensiles d'or et d'argent de la maison de Dieu, que Nebucadnetsar avait enlevés du temple de Jérusalem et transportés dans le temple de Babylone, il les fit remettre au nommé Scheschbatsar, qu'il établit gouverneur,"],[5,15,"et il lui dit: Prends ces ustensiles, va les déposer dans le temple de Jérusalem, et que la maison de Dieu soit rebâtie sur le lieu où elle était.","et il lui dit: Prends ces ustensiles, va les déposer dans le temple de Jérusalem, et que la maison de Dieu soit rebâtie sur le lieu où elle était."],[5,16,"Ce Scheschbatsar est donc venu, et il a posé les fondements de la maison de Dieu à Jérusalem; depuis lors jusqu'à présent elle se construit, et elle n'est pas achevée.","Ce Scheschbatsar est donc venu, et il a posé les fondements de la maison de Dieu à Jérusalem; depuis lors jusqu'à présent elle se construit, et elle n'est pas achevée."],[5,17,"Maintenant, si le roi le trouve bon, que l'on fasse des recherches dans la maison des trésors du roi à Babylone, pour voir s'il y a eu de la part du roi Cyrus un ordre donné pour la construction de cette maison de Dieu à Jérusalem. Puis, que le roi nous transmette sa volonté sur cet objet.","Maintenant, si le roi le trouve bon, que l'on fasse des recherches dans la maison des trésors du roi à Babylone, pour voir s'il y a eu de la part du roi Cyrus un ordre donné pour la construction de cette maison de Dieu à Jérusalem. Puis, que le roi nous transmette sa volonté sur cet objet."],[6,1,"Alors le roi Darius donna ordre de faire des recherches dans la maison des archives où l'on déposait les trésors à Babylone.","Alors le roi Darius donna ordre de faire des recherches dans la maison des archives où l'on déposait les trésors à Babylone."],[6,2,"Et l'on trouva à Achmetha, capitale de la province de Médie, un rouleau sur lequel était écrit le mémoire suivant:","Et l'on trouva à Achmetha, capitale de la province de Médie, un rouleau sur lequel était écrit le mémoire suivant:"],[6,3,"La première année du roi Cyrus, le roi Cyrus a donné cet ordre au sujet de la maison de Dieu à Jérusalem: Que la maison soit rebâtie, pour être un lieu où l'on offre des sacrifices, et qu'elle ait des solides fondements. Elle aura soixante coudées de hauteur, soixante coudées de largeur,","La première année du roi Cyrus, le roi Cyrus a donné cet ordre au sujet de la maison de Dieu à Jérusalem: Que la maison soit rebâtie, pour être un lieu où l'on offre des sacrifices, et qu'elle ait des solides fondements. Elle aura soixante coudées de hauteur, soixante coudées de largeur,"],[6,4,"trois rangées de pierres de taille et une rangée de bois neuf. Les frais seront payés par la maison du roi.","trois rangées de pierres de taille et une rangée de bois neuf. Les frais seront payés par la maison du roi."],[6,5,"De plus, les ustensiles d'or et d'argent de la maison de Dieu, que Nebucadnetsar avait enlevés du temple de Jérusalem et transportés à Babylone, seront rendus, transportés au temple de Jérusalem à la place où ils étaient, et déposés dans la maison de Dieu.","De plus, les ustensiles d'or et d'argent de la maison de Dieu, que Nebucadnetsar avait enlevés du temple de Jérusalem et transportés à Babylone, seront rendus, transportés au temple de Jérusalem à la place où ils étaient, et déposés dans la maison de Dieu."],[6,6,"Maintenant, Thathnaï, gouverneur de l'autre côté du fleuve, Schethar-Boznaï, et vos collègues d'Apharsac, qui demeurez de l'autre côté du fleuve, tenez-vous loin de ce lieu.","Maintenant, Thathnaï, gouverneur de l'autre côté du fleuve, Schethar-Boznaï, et vos collègues d'Apharsac, qui demeurez de l'autre côté du fleuve, tenez-vous loin de ce lieu."],[6,7,"Laissez continuer les travaux de cette maison de Dieu; que le gouverneur des Juifs et les anciens des Juifs la rebâtissent sur l'emplacement qu'elle occupait.","Laissez continuer les travaux de cette maison de Dieu; que le gouverneur des Juifs et les anciens des Juifs la rebâtissent sur l'emplacement qu'elle occupait."],[6,8,"Voici l'ordre que je donne touchant ce que vous aurez à faire à l'égard de ces anciens des Juifs pour la construction de cette maison de Dieu: les frais, pris sur les biens du roi provenant des tributs de l'autre côté du fleuve, seront exactement payés à ces hommes, afin qu'il n'y ait pas d'interruption.","Voici l'ordre que je donne touchant ce que vous aurez à faire à l'égard de ces anciens des Juifs pour la construction de cette maison de Dieu: les frais, pris sur les biens du roi provenant des tributs de l'autre côté du fleuve, seront exactement payés à ces hommes, afin qu'il n'y ait pas d'interruption."],[6,9,"Les choses nécessaires pour les holocaustes du Dieu des cieux, jeunes taureaux, béliers et agneaux, froment, sel, vin et huile, seront livrées, sur leur demande, aux sacrificateurs de Jérusalem, jour par jour et sans manquer,","Les choses nécessaires pour les holocaustes du Dieu des cieux, jeunes taureaux, béliers et agneaux, froment, sel, vin et huile, seront livrées, sur leur demande, aux sacrificateurs de Jérusalem, jour par jour et sans manquer,"],[6,10,"afin qu'ils offrent des sacrifices de bonne odeur au Dieu des cieux et qu'ils prient pour la vie du roi et de ses fils.","afin qu'ils offrent des sacrifices de bonne odeur au Dieu des cieux et qu'ils prient pour la vie du roi et de ses fils."],[6,11,"Et voici l'ordre que je donne touchant quiconque transgressera cette parole: on arrachera de sa maison une pièce de bois, on la dressera pour qu'il y soit attaché, et l'on fera de sa maison un tas d'immondices.","Et voici l'ordre que je donne touchant quiconque transgressera cette parole: on arrachera de sa maison une pièce de bois, on la dressera pour qu'il y soit attaché, et l'on fera de sa maison un tas d'immondices."],[6,12,"Que le Dieu qui fait résider en ce lieu son nom renverse tout roi et tout peuple qui étendraient la main pour transgresser ma parole, pour détruire cette maison de Dieu à Jérusalem! Moi, Darius, j'ai donné cet ordre. Qu'il soit ponctuellement exécuté.","Que le Dieu qui fait résider en ce lieu son nom renverse tout roi et tout peuple qui étendraient la main pour transgresser ma parole, pour détruire cette maison de Dieu à Jérusalem! Moi, Darius, j'ai donné cet ordre. Qu'il soit ponctuellement exécuté."],[6,13,"Thathnaï, gouverneur de ce côté du fleuve, Schethar-Boznaï, et leurs collègues, se conformèrent ponctuellement à cet ordre que leur envoya le roi Darius.","Thathnaï, gouverneur de ce côté du fleuve, Schethar-Boznaï, et leurs collègues, se conformèrent ponctuellement à cet ordre que leur envoya le roi Darius."],[6,14,"Et les anciens des Juifs bâtirent avec succès, selon les prophéties d'Aggée, le prophète, et de Zacharie, fils d'Iddo; ils bâtirent et achevèrent, d'après l'ordre du Dieu d'Israël, et d'après l'ordre de Cyrus, de Darius, et d'Artaxerxès, roi de Perse.","Et les anciens des Juifs bâtirent avec succès, selon les prophéties d'Aggée, le prophète, et de Zacharie, fils d'Iddo; ils bâtirent et achevèrent, d'après l'ordre du Dieu d'Israël, et d'après l'ordre de Cyrus, de Darius, et d'Artaxerxès, roi de Perse."],[6,15,"La maison fut achevée le troisième jour du mois d'Adar, dans la sixième année du règne du roi Darius.","La maison fut achevée le troisième jour du mois d'Adar, dans la sixième année du règne du roi Darius."],[6,16,"Les enfants d'Israël, les sacrificateurs et les Lévites, et le reste des fils de la captivité, firent avec joie la dédicace de cette maison de Dieu.","Les enfants d'Israël, les sacrificateurs et les Lévites, et le reste des fils de la captivité, firent avec joie la dédicace de cette maison de Dieu."],[6,17,"Ils offrirent, pour la dédicace de cette maison de Dieu, cent taureaux, deux cents béliers, quatre cents agneaux, et, comme victimes expiatoires pour tout Israël, douze boucs, d'après le nombre des tribus d'Israël.","Ils offrirent, pour la dédicace de cette maison de Dieu, cent taureaux, deux cents béliers, quatre cents agneaux, et, comme victimes expiatoires pour tout Israël, douze boucs, d'après le nombre des tribus d'Israël."],[6,18,"Ils établirent les sacrificateurs selon leurs classes et les Lévites selon leurs divisions pour le service de Dieu à Jérusalem, comme il est écrit dans le livre de Moïse.","Ils établirent les sacrificateurs selon leurs classes et les Lévites selon leurs divisions pour le service de Dieu à Jérusalem, comme il est écrit dans le livre de Moïse."],[6,19,"Les fils de la captivité célébrèrent la Pâque le quatorzième jour du premier mois.","Les fils de la captivité célébrèrent la Pâque le quatorzième jour du premier mois."],[6,20,"Les sacrificateurs et les Lévites s'étaient purifiés de concert, tous étaient purs; ils immolèrent la Pâque pour tous les fils de la captivité, pour leurs frères les sacrificateurs, et pour eux-mêmes.","Les sacrificateurs et les Lévites s'étaient purifiés de concert, tous étaient purs; ils immolèrent la Pâque pour tous les fils de la captivité, pour leurs frères les sacrificateurs, et pour eux-mêmes."],[6,21,"Les enfants d'Israël revenus de la captivité mangèrent la Pâque, avec tous ceux qui s'étaient éloignés de l'impureté des nations du pays et qui se joignirent à eux pour chercher l'Éternel, le Dieu d'Israël.","Les enfants d'Israël revenus de la captivité mangèrent la Pâque, avec tous ceux qui s'étaient éloignés de l'impureté des nations du pays et qui se joignirent à eux pour chercher l'Éternel, le Dieu d'Israël."],[6,22,"Ils célébrèrent avec joie pendant sept jours la fête des pains sans levain, car l'Éternel les avait réjouis en disposant le roi d'Assyrie à les soutenir dans l'oeuvre de la maison de Dieu, du Dieu d'Israël.","Ils célébrèrent avec joie pendant sept jours la fête des pains sans levain, car l'Éternel les avait réjouis en disposant le roi d'Assyrie à les soutenir dans l'oeuvre de la maison de Dieu, du Dieu d'Israël."],[7,1,"Après ces choses, sous le règne d'Artaxerxès, roi de Perse, vint Esdras, fils de Seraja, fils d'Azaria, fils de Hilkija,","Après ces choses, sous le règne d'Artaxerxès, roi de Perse, vint Esdras, fils de Seraja, fils d'Azaria, fils de Hilkija,"],[7,2,"fils de Schallum, fils de Tsadok, fils d'Achithub,","fils de Schallum, fils de Tsadok, fils d'Achithub,"],[7,3,"fils d'Amaria, fils d'Azaria, fils de Merajoth,","fils d'Amaria, fils d'Azaria, fils de Merajoth,"],[7,4,"fils de Zerachja, fils d'Uzzi, fils de Bukki,","fils de Zerachja, fils d'Uzzi, fils de Bukki,"],[7,5,"fils d'Abischua, fils de Phinées, fils d'Éléazar, fils d'Aaron, le souverain sacrificateur.","fils d'Abischua, fils de Phinées, fils d'Éléazar, fils d'Aaron, le souverain sacrificateur."],[7,6,"Cet Esdras vint de Babylone: c'était un scribe versé dans la loi de Moïse, donnée par l'Éternel, le Dieu d'Israël. Et comme la main de l'Éternel, son Dieu, était sur lui, le roi lui accorda tout ce qu'il avait demandé.","Cet Esdras vint de Babylone: c'était un scribe versé dans la loi de Moïse, donnée par l'Éternel, le Dieu d'Israël. Et comme la main de l'Éternel, son Dieu, était sur lui, le roi lui accorda tout ce qu'il avait demandé."],[7,7,"Plusieurs des enfants d'Israël, des sacrificateurs et des Lévites, des chantres, des portiers, et des Néthiniens, vinrent aussi à Jérusalem, la septième année du roi Artaxerxès.","Plusieurs des enfants d'Israël, des sacrificateurs et des Lévites, des chantres, des portiers, et des Néthiniens, vinrent aussi à Jérusalem, la septième année du roi Artaxerxès."],[7,8,"Esdras arriva à Jérusalem au cinquième mois de la septième année du roi;","Esdras arriva à Jérusalem au cinquième mois de la septième année du roi;"],[7,9,"il était parti de Babylone le premier jour du premier mois, et il arriva à Jérusalem le premier jour du cinquième mois, la bonne main de son Dieu étant sur lui.","il était parti de Babylone le premier jour du premier mois, et il arriva à Jérusalem le premier jour du cinquième mois, la bonne main de son Dieu étant sur lui."],[7,10,"Car Esdras avait appliqué son coeur à étudier et à mettre en pratique la loi de l'Éternel, et à enseigner au milieu d'Israël les lois et les ordonnances.","Car Esdras avait appliqué son coeur à étudier et à mettre en pratique la loi de l'Éternel, et à enseigner au milieu d'Israël les lois et les ordonnances."],[7,11,"Voici la copie de la lettre donnée par le roi Artaxerxès à Esdras, sacrificateur et scribe, enseignant les commandements et les lois de l'Éternel concernant Israël:","Voici la copie de la lettre donnée par le roi Artaxerxès à Esdras, sacrificateur et scribe, enseignant les commandements et les lois de l'Éternel concernant Israël:"],[7,12,"Artaxerxès, roi des rois, à Esdras, sacrificateur et scribe, versé dans la loi du Dieu des cieux, etc.","Artaxerxès, roi des rois, à Esdras, sacrificateur et scribe, versé dans la loi du Dieu des cieux, etc."],[7,13,"J'ai donné ordre de laisser aller tous ceux du peuple d'Israël, de ses sacrificateurs et de ses Lévites, qui se trouvent dans mon royaume, et qui sont disposés à partir avec toi pour Jérusalem.","J'ai donné ordre de laisser aller tous ceux du peuple d'Israël, de ses sacrificateurs et de ses Lévites, qui se trouvent dans mon royaume, et qui sont disposés à partir avec toi pour Jérusalem."],[7,14,"Tu es envoyé par le roi et ses sept conseillers pour inspecter Juda et Jérusalem d'après la loi de ton Dieu, laquelle est entre tes mains,","Tu es envoyé par le roi et ses sept conseillers pour inspecter Juda et Jérusalem d'après la loi de ton Dieu, laquelle est entre tes mains,"],[7,15,"et pour porter l'argent et l'or que le roi et ses conseillers ont généreusement offerts au Dieu d'Israël, dont la demeure est à Jérusalem,","et pour porter l'argent et l'or que le roi et ses conseillers ont généreusement offerts au Dieu d'Israël, dont la demeure est à Jérusalem,"],[7,16,"tout l'argent et l'or que tu trouveras dans toute la province de Babylone, et les dons volontaires faits par le peuple et les sacrificateurs pour la maison de leur Dieu à Jérusalem.","tout l'argent et l'or que tu trouveras dans toute la province de Babylone, et les dons volontaires faits par le peuple et les sacrificateurs pour la maison de leur Dieu à Jérusalem."],[7,17,"En conséquence, tu auras soin d'acheter avec cet argent des taureaux, des béliers, des agneaux, et ce qui est nécessaire pour les offrandes et les libations, et tu les offriras sur l'autel de la maison de votre Dieu à Jérusalem.","En conséquence, tu auras soin d'acheter avec cet argent des taureaux, des béliers, des agneaux, et ce qui est nécessaire pour les offrandes et les libations, et tu les offriras sur l'autel de la maison de votre Dieu à Jérusalem."],[7,18,"Vous ferez avec le reste de l'argent et de l'or ce que vous jugerez bon de faire, toi et tes frères, en vous conformant à la volonté de votre Dieu.","Vous ferez avec le reste de l'argent et de l'or ce que vous jugerez bon de faire, toi et tes frères, en vous conformant à la volonté de votre Dieu."],[7,19,"Dépose devant le Dieu de Jérusalem les ustensiles qui te sont remis pour le service de la maison de ton Dieu.","Dépose devant le Dieu de Jérusalem les ustensiles qui te sont remis pour le service de la maison de ton Dieu."],[7,20,"Tu tireras de la maison des trésors du roi ce qu'il faudra pour les autres dépenses que tu auras à faire concernant la maison de ton Dieu.","Tu tireras de la maison des trésors du roi ce qu'il faudra pour les autres dépenses que tu auras à faire concernant la maison de ton Dieu."],[7,21,"Moi, le roi Artaxerxès, je donne l'ordre à tous les trésoriers de l'autre côté du fleuve de livrer exactement à Esdras, sacrificateur et scribe, versé dans la loi du Dieu des cieux, tout ce qu'il vous demandera,","Moi, le roi Artaxerxès, je donne l'ordre à tous les trésoriers de l'autre côté du fleuve de livrer exactement à Esdras, sacrificateur et scribe, versé dans la loi du Dieu des cieux, tout ce qu'il vous demandera,"],[7,22,"jusqu'à cent talents d'argent, cent cors de froment, cent baths de vin, cent baths d'huile, et du sel à discrétion.","jusqu'à cent talents d'argent, cent cors de froment, cent baths de vin, cent baths d'huile, et du sel à discrétion."],[7,23,"Que tout ce qui est ordonné par le Dieu des cieux se fasse ponctuellement pour la maison du Dieu des cieux, afin que sa colère ne soit pas sur le royaume, sur le roi et sur ses fils.","Que tout ce qui est ordonné par le Dieu des cieux se fasse ponctuellement pour la maison du Dieu des cieux, afin que sa colère ne soit pas sur le royaume, sur le roi et sur ses fils."],[7,24,"Nous vous faisons savoir qu'il ne peut être levé ni tribut, ni impôt, ni droit de passage, sur aucun des sacrificateurs, des Lévites, des chantres, des portiers, des Néthiniens, et des serviteurs de cette maison de Dieu.","Nous vous faisons savoir qu'il ne peut être levé ni tribut, ni impôt, ni droit de passage, sur aucun des sacrificateurs, des Lévites, des chantres, des portiers, des Néthiniens, et des serviteurs de cette maison de Dieu."],[7,25,"Et toi, Esdras, selon la sagesse de Dieu que tu possèdes, établis des juges et des magistrats qui rendent la justice à tout le peuple de l'autre côté du fleuve, à tous ceux qui connaissent les lois de ton Dieu; et fais-les connaître à ceux qui ne les connaissent pas.","Et toi, Esdras, selon la sagesse de Dieu que tu possèdes, établis des juges et des magistrats qui rendent la justice à tout le peuple de l'autre côté du fleuve, à tous ceux qui connaissent les lois de ton Dieu; et fais-les connaître à ceux qui ne les connaissent pas."],[7,26,"Quiconque n'observera pas ponctuellement la loi de ton Dieu et la loi du roi sera condamné à la mort, au bannissement, à une amende, ou à la prison.","Quiconque n'observera pas ponctuellement la loi de ton Dieu et la loi du roi sera condamné à la mort, au bannissement, à une amende, ou à la prison."],[7,27,"Béni soit l'Éternel, le Dieu de nos pères, qui a disposé le coeur du roi à glorifier ainsi la maison de l'Éternel à Jérusalem,","Béni soit l'Éternel, le Dieu de nos pères, qui a disposé le coeur du roi à glorifier ainsi la maison de l'Éternel à Jérusalem,"],[7,28,"et qui m'a rendu l'objet de la bienveillance du roi, de ses conseillers, et de tous ses puissants chefs! Fortifié par la main de l'Éternel, mon Dieu, qui était sur moi, j'ai rassemblé les chefs d'Israël, afin qu'ils partissent avec moi.","et qui m'a rendu l'objet de la bienveillance du roi, de ses conseillers, et de tous ses puissants chefs! Fortifié par la main de l'Éternel, mon Dieu, qui était sur moi, j'ai rassemblé les chefs d'Israël, afin qu'ils partissent avec moi."],[8,1,"Voici les chefs de familles et les généalogies de ceux qui montèrent avec moi de Babylone, sous le règne du roi Artaxerxès.","Voici les chefs de familles et les généalogies de ceux qui montèrent avec moi de Babylone, sous le règne du roi Artaxerxès."],[8,2,"Des fils de Phinées, Guerschom; des fils d'Ithamar, Daniel; des fils de David, Hatthusch,","Des fils de Phinées, Guerschom; des fils d'Ithamar, Daniel; des fils de David, Hatthusch,"],[8,3,"des fils de Schecania; des fils de Pareosch, Zacharie, et avec lui cent cinquante mâles enregistrés;","des fils de Schecania; des fils de Pareosch, Zacharie, et avec lui cent cinquante mâles enregistrés;"],[8,4,"des fils de Pachat Moab, Eljoénaï, fils de Zerachja, et avec lui deux cents mâles;","des fils de Pachat Moab, Eljoénaï, fils de Zerachja, et avec lui deux cents mâles;"],[8,5,"des fils de Schecania, le fils de Jachaziel, et avec lui trois cents mâles;","des fils de Schecania, le fils de Jachaziel, et avec lui trois cents mâles;"],[8,6,"des fils d'Adin, Ébed, fils de Jonathan, et avec lui cinquante mâles;","des fils d'Adin, Ébed, fils de Jonathan, et avec lui cinquante mâles;"],[8,7,"des fils d'Élam, Ésaïe, fils d'Athalia, et avec lui soixante-dix mâles;","des fils d'Élam, Ésaïe, fils d'Athalia, et avec lui soixante-dix mâles;"],[8,8,"des fils de Schephathia, Zebadia, fils de Micaël, et avec lui quatre-vingts mâles;","des fils de Schephathia, Zebadia, fils de Micaël, et avec lui quatre-vingts mâles;"],[8,9,"des fils de Joab, Abdias, fils de Jehiel, et avec lui deux cent dix-huit mâles;","des fils de Joab, Abdias, fils de Jehiel, et avec lui deux cent dix-huit mâles;"],[8,10,"des fils de Schelomith, le fils de Josiphia, et avec lui cent soixante mâles;","des fils de Schelomith, le fils de Josiphia, et avec lui cent soixante mâles;"],[8,11,"des fils de Bébaï, Zacharie, fils de Bébaï, et avec lui vingt-huit mâles;","des fils de Bébaï, Zacharie, fils de Bébaï, et avec lui vingt-huit mâles;"],[8,12,"des fils d'Azgad, Jochanan, fils d'Hakkathan, et avec lui cent dix mâles;","des fils d'Azgad, Jochanan, fils d'Hakkathan, et avec lui cent dix mâles;"],[8,13,"des fils d'Adonikam, les derniers, dont voici les noms: Éliphéleth, Jeïel et Schemaeja, et avec eux soixante mâles;","des fils d'Adonikam, les derniers, dont voici les noms: Éliphéleth, Jeïel et Schemaeja, et avec eux soixante mâles;"],[8,14,"des fils de Bigvaï, Uthaï et Zabbud, et avec eux soixante-dix mâles.","des fils de Bigvaï, Uthaï et Zabbud, et avec eux soixante-dix mâles."],[8,15,"Je les rassemblai près du fleuve qui coule vers Ahava, et nous campâmes là trois jours. Je dirigeai mon attention sur le peuple et sur les sacrificateurs, et je ne trouvai là aucun des fils de Lévi.","Je les rassemblai près du fleuve qui coule vers Ahava, et nous campâmes là trois jours. Je dirigeai mon attention sur le peuple et sur les sacrificateurs, et je ne trouvai là aucun des fils de Lévi."],[8,16,"Alors je fis appeler les chefs Éliézer, Ariel, Schemaeja, Elnathan, Jarib, Elnathan, Nathan, Zacharie et Meschullam, et les docteurs Jojarib et Elnathan.","Alors je fis appeler les chefs Éliézer, Ariel, Schemaeja, Elnathan, Jarib, Elnathan, Nathan, Zacharie et Meschullam, et les docteurs Jojarib et Elnathan."],[8,17,"Je les envoyai vers le chef Iddo, demeurant à Casiphia, et je mis dans leur bouche ce qu'ils devaient dire à Iddo et à ses frères les Néthiniens qui étaient à Casiphia, afin qu'ils nous amenassent des serviteurs pour la maison de notre Dieu.","Je les envoyai vers le chef Iddo, demeurant à Casiphia, et je mis dans leur bouche ce qu'ils devaient dire à Iddo et à ses frères les Néthiniens qui étaient à Casiphia, afin qu'ils nous amenassent des serviteurs pour la maison de notre Dieu."],[8,18,"Et, comme la bonne main de notre Dieu était sur nous, ils nous amenèrent Schérébia, homme de sens, d'entre les fils de Machli, fils de Lévi, fils d'Israël, et avec lui ses fils et ses frères, au nombre de dix-huit;","Et, comme la bonne main de notre Dieu était sur nous, ils nous amenèrent Schérébia, homme de sens, d'entre les fils de Machli, fils de Lévi, fils d'Israël, et avec lui ses fils et ses frères, au nombre de dix-huit;"],[8,19,"Haschabia, et avec lui Ésaïe, d'entre les fils de Merari, ses frères et leurs fils, au nombre de vingt;","Haschabia, et avec lui Ésaïe, d'entre les fils de Merari, ses frères et leurs fils, au nombre de vingt;"],[8,20,"et d'entre les Néthiniens, que David et les chefs avaient mis au service des Lévites, deux cent vingt Néthiniens, tous désignés par leurs noms.","et d'entre les Néthiniens, que David et les chefs avaient mis au service des Lévites, deux cent vingt Néthiniens, tous désignés par leurs noms."],[8,21,"Là, près du fleuve d'Ahava, je publiai un jeûne d'humiliation devant notre Dieu, afin d'implorer de lui un heureux voyage pour nous, pour nos enfants, et pour tout ce qui nous appartenait.","Là, près du fleuve d'Ahava, je publiai un jeûne d'humiliation devant notre Dieu, afin d'implorer de lui un heureux voyage pour nous, pour nos enfants, et pour tout ce qui nous appartenait."],[8,22,"J'aurais eu honte de demander au roi une escorte et des cavaliers pour nous protéger contre l'ennemi pendant la route, car nous avions dit au roi: La main de notre Dieu est pour leur bien sur tous ceux qui le cherchent, mais sa force et sa colère sont sur tous ceux qui l'abandonnent.","J'aurais eu honte de demander au roi une escorte et des cavaliers pour nous protéger contre l'ennemi pendant la route, car nous avions dit au roi: La main de notre Dieu est pour leur bien sur tous ceux qui le cherchent, mais sa force et sa colère sont sur tous ceux qui l'abandonnent."],[8,23,"C'est à cause de cela que nous jeûnâmes et que nous invoquâmes notre Dieu. Et il nous exauça.","C'est à cause de cela que nous jeûnâmes et que nous invoquâmes notre Dieu. Et il nous exauça."],[8,24,"Je choisis douze chefs des sacrificateurs, Schérébia, Haschabia, et dix de leurs frères.","Je choisis douze chefs des sacrificateurs, Schérébia, Haschabia, et dix de leurs frères."],[8,25,"Je pesai devant eux l'argent, l'or, et les ustensiles, donnés en offrande pour la maison de notre Dieu par le roi, ses conseillers et ses chefs, et par tous ceux d'Israël qu'on avait trouvés.","Je pesai devant eux l'argent, l'or, et les ustensiles, donnés en offrande pour la maison de notre Dieu par le roi, ses conseillers et ses chefs, et par tous ceux d'Israël qu'on avait trouvés."],[8,26,"Je remis entre leurs mains six cent cinquante talents d'argent, des ustensiles d'argent pour cent talents, cent talents d'or,","Je remis entre leurs mains six cent cinquante talents d'argent, des ustensiles d'argent pour cent talents, cent talents d'or,"],[8,27,"vingt coupes d'or valant mille dariques, et deux vases d'un bel airain poli, aussi précieux que l'or.","vingt coupes d'or valant mille dariques, et deux vases d'un bel airain poli, aussi précieux que l'or."],[8,28,"Puis je leur dis: Vous êtes consacrés à l'Éternel; ces ustensiles sont des choses saintes, et cet argent et cet or sont une offrande volontaire à l'Éternel, le Dieu de vos pères.","Puis je leur dis: Vous êtes consacrés à l'Éternel; ces ustensiles sont des choses saintes, et cet argent et cet or sont une offrande volontaire à l'Éternel, le Dieu de vos pères."],[8,29,"Soyez vigilants, et prenez cela sous votre garde, jusqu'à ce que vous le pesiez devant les chefs des sacrificateurs et les Lévites, et devant les chefs de familles d'Israël, à Jérusalem, dans les chambres de la maison de l'Éternel.","Soyez vigilants, et prenez cela sous votre garde, jusqu'à ce que vous le pesiez devant les chefs des sacrificateurs et les Lévites, et devant les chefs de familles d'Israël, à Jérusalem, dans les chambres de la maison de l'Éternel."],[8,30,"Et les sacrificateurs et les Lévites reçurent au poids l'argent, l'or et les ustensiles, pour les porter à Jérusalem, dans la maison de notre Dieu.","Et les sacrificateurs et les Lévites reçurent au poids l'argent, l'or et les ustensiles, pour les porter à Jérusalem, dans la maison de notre Dieu."],[8,31,"Nous partîmes du fleuve d'Ahava pour nous rendre à Jérusalem, le douzième jour du premier mois. La main de notre Dieu fut sur nous et nous préserva des attaques de l'ennemi et de toute embûche pendant la route.","Nous partîmes du fleuve d'Ahava pour nous rendre à Jérusalem, le douzième jour du premier mois. La main de notre Dieu fut sur nous et nous préserva des attaques de l'ennemi et de toute embûche pendant la route."],[8,32,"Nous arrivâmes à Jérusalem, et nous nous y reposâmes trois jours.","Nous arrivâmes à Jérusalem, et nous nous y reposâmes trois jours."],[8,33,"Le quatrième jour, nous pesâmes dans la maison de notre Dieu l'argent, l'or, et les ustensiles, que nous remîmes à Merémoth, fils d'Urie, le sacrificateur; il y avait avec lui Éléazar, fils de Phinées, et avec eux les Lévites Jozabad, fils de Josué, et Noadia, fils de Binnuï.","Le quatrième jour, nous pesâmes dans la maison de notre Dieu l'argent, l'or, et les ustensiles, que nous remîmes à Merémoth, fils d'Urie, le sacrificateur; il y avait avec lui Éléazar, fils de Phinées, et avec eux les Lévites Jozabad, fils de Josué, et Noadia, fils de Binnuï."],[8,34,"Le tout ayant été vérifié, soit pour le nombre, soit pour le poids, on mit alors par écrit le poids du tout.","Le tout ayant été vérifié, soit pour le nombre, soit pour le poids, on mit alors par écrit le poids du tout."],[8,35,"Les fils de la captivité revenus de l'exil offrirent en holocauste au Dieu d'Israël douze taureaux pour tout Israël, quatre-vingt-seize béliers, soixante-dix-sept agneaux, et douze boucs comme victimes expiatoires, le tout en holocauste à l'Éternel.","Les fils de la captivité revenus de l'exil offrirent en holocauste au Dieu d'Israël douze taureaux pour tout Israël, quatre-vingt-seize béliers, soixante-dix-sept agneaux, et douze boucs comme victimes expiatoires, le tout en holocauste à l'Éternel."],[8,36,"Ils transmirent les ordres du roi aux satrapes du roi et aux gouverneurs de ce côté du fleuve, lesquels honorèrent le peuple et la maison de Dieu.","Ils transmirent les ordres du roi aux satrapes du roi et aux gouverneurs de ce côté du fleuve, lesquels honorèrent le peuple et la maison de Dieu."],[9,1,"Après que cela fut terminé, les chefs s'approchèrent de moi, en disant: Le peuple d'Israël, les sacrificateurs et les Lévites ne se sont point séparés des peuples de ces pays, et ils imitent leurs abominations, celles des Cananéens, des Héthiens, des Phéréziens, des Jébusiens, des Ammonites, des Moabites, des Égyptiens et des Amoréens.","Après que cela fut terminé, les chefs s'approchèrent de moi, en disant: Le peuple d'Israël, les sacrificateurs et les Lévites ne se sont point séparés des peuples de ces pays, et ils imitent leurs abominations, celles des Cananéens, des Héthiens, des Phéréziens, des Jébusiens, des Ammonites, des Moabites, des Égyptiens et des Amoréens."],[9,2,"Car ils ont pris de leurs filles pour eux et pour leurs fils, et ont mêlé la race sainte avec les peuples de ces pays; et les chefs et les magistrats ont été les premiers à commettre ce péché.","Car ils ont pris de leurs filles pour eux et pour leurs fils, et ont mêlé la race sainte avec les peuples de ces pays; et les chefs et les magistrats ont été les premiers à commettre ce péché."],[9,3,"Lorsque j'entendis cela, je déchirai mes vêtements et mon manteau, je m'arrachai les cheveux de la tête et les poils de la barbe, et je m'assis désolé.","Lorsque j'entendis cela, je déchirai mes vêtements et mon manteau, je m'arrachai les cheveux de la tête et les poils de la barbe, et je m'assis désolé."],[9,4,"Auprès de moi s'assemblèrent tous ceux que faisaient trembler les paroles du Dieu d'Israël, à cause du péché des fils de la captivité; et moi, je restai assis et désolé, jusqu'à l'offrande du soir.","Auprès de moi s'assemblèrent tous ceux que faisaient trembler les paroles du Dieu d'Israël, à cause du péché des fils de la captivité; et moi, je restai assis et désolé, jusqu'à l'offrande du soir."],[9,5,"Puis, au moment de l'offrande du soir, je me levai du sein de mon humiliation, avec mes vêtements et mon manteau déchirés, je tombai à genoux, j'étendis les mains vers l'Éternel, mon Dieu,","Puis, au moment de l'offrande du soir, je me levai du sein de mon humiliation, avec mes vêtements et mon manteau déchirés, je tombai à genoux, j'étendis les mains vers l'Éternel, mon Dieu,"],[9,6,"et je dis: Mon Dieu, je suis dans la confusion, et j'ai honte, ô mon Dieu, de lever ma face vers toi; car nos iniquités se sont multipliées par-dessus nos têtes, et nos fautes ont atteint jusqu'aux cieux.","et je dis: Mon Dieu, je suis dans la confusion, et j'ai honte, ô mon Dieu, de lever ma face vers toi; car nos iniquités se sont multipliées par-dessus nos têtes, et nos fautes ont atteint jusqu'aux cieux."],[9,7,"Depuis les jours de nos pères nous avons été grandement coupables jusqu'à ce jour, et c'est à cause de nos iniquités que nous avons été livrés, nous, nos rois et nos sacrificateurs, aux mains des rois étrangers, à l'épée, à la captivité, au pillage, et à la honte qui couvre aujourd'hui notre visage.","Depuis les jours de nos pères nous avons été grandement coupables jusqu'à ce jour, et c'est à cause de nos iniquités que nous avons été livrés, nous, nos rois et nos sacrificateurs, aux mains des rois étrangers, à l'épée, à la captivité, au pillage, et à la honte qui couvre aujourd'hui notre visage."],[9,8,"Et cependant l'Éternel, notre Dieu, vient de nous faire grâce en nous laissant quelques réchappés et en nous accordant un abri dans son saint lieu, afin d'éclaircir nos yeux et de nous donner un peu de vie au milieu de notre servitude.","Et cependant l'Éternel, notre Dieu, vient de nous faire grâce en nous laissant quelques réchappés et en nous accordant un abri dans son saint lieu, afin d'éclaircir nos yeux et de nous donner un peu de vie au milieu de notre servitude."],[9,9,"Car nous sommes esclaves, mais Dieu ne nous a pas abandonnés dans notre servitude. Il nous a rendus les objets de la bienveillance des rois de Perse, pour nous conserver la vie afin que nous puissions bâtir la maison de notre Dieu et en relever les ruines, et pour nous donner une retraite en Juda et à Jérusalem.","Car nous sommes esclaves, mais Dieu ne nous a pas abandonnés dans notre servitude. Il nous a rendus les objets de la bienveillance des rois de Perse, pour nous conserver la vie afin que nous puissions bâtir la maison de notre Dieu et en relever les ruines, et pour nous donner une retraite en Juda et à Jérusalem."],[9,10,"Maintenant, que dirons-nous après cela, ô notre Dieu? Car nous avons abandonné tes commandements,","Maintenant, que dirons-nous après cela, ô notre Dieu? Car nous avons abandonné tes commandements,"],[9,11,"que tu nous avais prescrits par tes serviteurs les prophètes, en disant: Le pays dans lequel vous entrez pour le posséder est un pays souillé par les impuretés des peuples de ces contrées, par les abominations dont ils l'ont rempli d'un bout à l'autre avec leurs impuretés;","que tu nous avais prescrits par tes serviteurs les prophètes, en disant: Le pays dans lequel vous entrez pour le posséder est un pays souillé par les impuretés des peuples de ces contrées, par les abominations dont ils l'ont rempli d'un bout à l'autre avec leurs impuretés;"],[9,12,"ne donnez donc point vos filles à leurs fils et ne prenez point leurs filles pour vos fils, et n'ayez jamais souci ni de leur prospérité ni de leur bien-être, et ainsi vous deviendrez forts, vous mangerez les meilleures productions du pays, et vous le laisserez pour toujours en héritage à vos fils.","ne donnez donc point vos filles à leurs fils et ne prenez point leurs filles pour vos fils, et n'ayez jamais souci ni de leur prospérité ni de leur bien-être, et ainsi vous deviendrez forts, vous mangerez les meilleures productions du pays, et vous le laisserez pour toujours en héritage à vos fils."],[9,13,"Après tout ce qui nous est arrivé à cause des mauvaises actions et des grandes fautes que nous avons commises, quoique tu ne nous aies pas, ô notre Dieu, punis en proportion de nos iniquités, et maintenant que tu nous as conservé ces réchappés,","Après tout ce qui nous est arrivé à cause des mauvaises actions et des grandes fautes que nous avons commises, quoique tu ne nous aies pas, ô notre Dieu, punis en proportion de nos iniquités, et maintenant que tu nous as conservé ces réchappés,"],[9,14,"recommencerions-nous à violer tes commandements et à nous allier avec ces peuples abominables? Ta colère n'éclaterait-elle pas encore contre nous jusqu'à nous détruire, sans laisser ni reste ni réchappés?","recommencerions-nous à violer tes commandements et à nous allier avec ces peuples abominables? Ta colère n'éclaterait-elle pas encore contre nous jusqu'à nous détruire, sans laisser ni reste ni réchappés?"],[9,15,"Éternel, Dieu d'Israël, tu es juste, car nous sommes aujourd'hui un reste de réchappés. Nous voici devant toi comme des coupables, et nous ne saurions ainsi subsister devant ta face.","Éternel, Dieu d'Israël, tu es juste, car nous sommes aujourd'hui un reste de réchappés. Nous voici devant toi comme des coupables, et nous ne saurions ainsi subsister devant ta face."],[10,1,"Pendant qu'Esdras, pleurant et prosterné devant la maison de Dieu, faisait cette prière et cette confession, il s'était rassemblé auprès de lui une foule très nombreuse de gens d'Israël, hommes, femmes et enfants, et le peuple répandait d'abondantes larmes.","Pendant qu'Esdras, pleurant et prosterné devant la maison de Dieu, faisait cette prière et cette confession, il s'était rassemblé auprès de lui une foule très nombreuse de gens d'Israël, hommes, femmes et enfants, et le peuple répandait d'abondantes larmes."],[10,2,"Alors Schecania, fils de Jehiel, d'entre les fils d'Élam, prit la parole et dit à Esdras: Nous avons péché contre notre Dieu, en nous alliant à des femmes étrangères qui appartiennent aux peuples du pays. Mais Israël ne reste pas pour cela sans espérance.","Alors Schecania, fils de Jehiel, d'entre les fils d'Élam, prit la parole et dit à Esdras: Nous avons péché contre notre Dieu, en nous alliant à des femmes étrangères qui appartiennent aux peuples du pays. Mais Israël ne reste pas pour cela sans espérance."],[10,3,"Faisons maintenant une alliance avec notre Dieu pour le renvoi de toutes ces femmes et de leurs enfants, selon l'avis de mon seigneur et de ceux qui tremblent devant les commandements de notre Dieu. Et que l'on agisse d'après la loi.","Faisons maintenant une alliance avec notre Dieu pour le renvoi de toutes ces femmes et de leurs enfants, selon l'avis de mon seigneur et de ceux qui tremblent devant les commandements de notre Dieu. Et que l'on agisse d'après la loi."],[10,4,"Lève-toi, car cette affaire te regarde. Nous serons avec toi. Prends courage et agis.","Lève-toi, car cette affaire te regarde. Nous serons avec toi. Prends courage et agis."],[10,5,"Esdras se leva, et il fit jurer aux chefs des sacrificateurs, des Lévites, et de tout Israël, de faire ce qui venait d'être dit. Et ils le jurèrent.","Esdras se leva, et il fit jurer aux chefs des sacrificateurs, des Lévites, et de tout Israël, de faire ce qui venait d'être dit. Et ils le jurèrent."],[10,6,"Puis Esdras se retira de devant la maison de Dieu, et il alla dans la chambre de Jochanan, fils d'Éliaschib; quand il y fut entré, il ne mangea point de pain et il ne but point d'eau, parce qu'il était dans la désolation à cause du péché des fils de la captivité.","Puis Esdras se retira de devant la maison de Dieu, et il alla dans la chambre de Jochanan, fils d'Éliaschib; quand il y fut entré, il ne mangea point de pain et il ne but point d'eau, parce qu'il était dans la désolation à cause du péché des fils de la captivité."],[10,7,"On publia dans Juda et à Jérusalem que tous les fils de la captivité eussent à se réunir à Jérusalem,","On publia dans Juda et à Jérusalem que tous les fils de la captivité eussent à se réunir à Jérusalem,"],[10,8,"et que, d'après l'avis des chefs et des anciens, quiconque ne s'y serait pas rendu dans trois jours aurait tous ses biens confisqués et serait lui-même exclu de l'assemblée des fils de la captivité.","et que, d'après l'avis des chefs et des anciens, quiconque ne s'y serait pas rendu dans trois jours aurait tous ses biens confisqués et serait lui-même exclu de l'assemblée des fils de la captivité."],[10,9,"Tous les hommes de Juda et de Benjamin se rassemblèrent à Jérusalem dans les trois jours. C'était le vingtième jour du neuvième mois. Tout le peuple se tenait sur la place de la maison de Dieu, tremblant à cause de la circonstance et par suite de la pluie.","Tous les hommes de Juda et de Benjamin se rassemblèrent à Jérusalem dans les trois jours. C'était le vingtième jour du neuvième mois. Tout le peuple se tenait sur la place de la maison de Dieu, tremblant à cause de la circonstance et par suite de la pluie."],[10,10,"Esdras, le sacrificateur, se leva et leur dit: Vous avez péché en vous alliant à des femmes étrangères, et vous avez rendu Israël encore plus coupable.","Esdras, le sacrificateur, se leva et leur dit: Vous avez péché en vous alliant à des femmes étrangères, et vous avez rendu Israël encore plus coupable."],[10,11,"Confessez maintenant votre faute à l'Éternel, le Dieu de vos pères, et faites sa volonté! Séparez-vous des peuples du pays et des femmes étrangères.","Confessez maintenant votre faute à l'Éternel, le Dieu de vos pères, et faites sa volonté! Séparez-vous des peuples du pays et des femmes étrangères."],[10,12,"Toute l'assemblée répondit d'une voix haute: À nous de faire comme tu l'as dit!","Toute l'assemblée répondit d'une voix haute: À nous de faire comme tu l'as dit!"],[10,13,"Mais le peuple est nombreux, le temps est à la pluie, et il n'est pas possible de rester dehors; d'ailleurs, ce n'est pas l'oeuvre d'un jour ou deux, car il y en a beaucoup parmi nous qui ont péché dans cette affaire.","Mais le peuple est nombreux, le temps est à la pluie, et il n'est pas possible de rester dehors; d'ailleurs, ce n'est pas l'oeuvre d'un jour ou deux, car il y en a beaucoup parmi nous qui ont péché dans cette affaire."],[10,14,"Que nos chefs restent donc pour toute l'assemblée; et tous ceux qui dans nos villes se sont alliés à des femmes étrangères viendront à des époques fixes, avec les anciens et les juges de chaque ville, jusqu'à ce que l'ardente colère de notre Dieu se soit détournée de nous au sujet de cette affaire.","Que nos chefs restent donc pour toute l'assemblée; et tous ceux qui dans nos villes se sont alliés à des femmes étrangères viendront à des époques fixes, avec les anciens et les juges de chaque ville, jusqu'à ce que l'ardente colère de notre Dieu se soit détournée de nous au sujet de cette affaire."],[10,15,"Jonathan, fils d'Asaël, et Jachzia, fils de Thikva, appuyés par Meschullam et par le Lévite Schabthaï, furent les seuls à combattre cet avis,","Jonathan, fils d'Asaël, et Jachzia, fils de Thikva, appuyés par Meschullam et par le Lévite Schabthaï, furent les seuls à combattre cet avis,"],[10,16,"auquel se conformèrent les fils de la captivité. On choisit Esdras, le sacrificateur, et des chefs de famille selon leurs maisons paternelles, tous désignés par leurs noms; et ils siégèrent le premier jour du dixième mois pour s'occuper de la chose.","auquel se conformèrent les fils de la captivité. On choisit Esdras, le sacrificateur, et des chefs de famille selon leurs maisons paternelles, tous désignés par leurs noms; et ils siégèrent le premier jour du dixième mois pour s'occuper de la chose."],[10,17,"Le premier jour du premier mois, ils en finirent avec tous les hommes qui s'étaient alliés à des femmes étrangères.","Le premier jour du premier mois, ils en finirent avec tous les hommes qui s'étaient alliés à des femmes étrangères."],[10,18,"Parmi les fils de sacrificateurs, il s'en trouva qui s'étaient alliés à des femmes étrangères: des fils de Josué, fils de Jotsadak, et de ses frères, Maaséja, Éliézer, Jarib et Guedalia,","Parmi les fils de sacrificateurs, il s'en trouva qui s'étaient alliés à des femmes étrangères: des fils de Josué, fils de Jotsadak, et de ses frères, Maaséja, Éliézer, Jarib et Guedalia,"],[10,19,"qui s'engagèrent, en donnant la main, à renvoyer leurs femmes et à offrir un bélier en sacrifice de culpabilité;","qui s'engagèrent, en donnant la main, à renvoyer leurs femmes et à offrir un bélier en sacrifice de culpabilité;"],[10,20,"des fils d'Immer, Hanani et Zebadia;","des fils d'Immer, Hanani et Zebadia;"],[10,21,"des fils de Harim, Maaséja, Élie, Schemaeja, Jehiel et Ozias;","des fils de Harim, Maaséja, Élie, Schemaeja, Jehiel et Ozias;"],[10,22,"des fils de Paschhur, Eljoénaï, Maaséja, Ismaël, Nethaneel, Jozabad et Éleasa.","des fils de Paschhur, Eljoénaï, Maaséja, Ismaël, Nethaneel, Jozabad et Éleasa."],[10,23,"Parmi les Lévites: Jozabad, Schimeï, Kélaja ou Kelitha, Pethachja, Juda et Éliézer.","Parmi les Lévites: Jozabad, Schimeï, Kélaja ou Kelitha, Pethachja, Juda et Éliézer."],[10,24,"Parmi les chantres: Éliaschib. Parmi les portiers: Schallum, Thélem et Uri.","Parmi les chantres: Éliaschib. Parmi les portiers: Schallum, Thélem et Uri."],[10,25,"Parmi ceux d'Israël: des fils de Pareosch, Ramia, Jizzija, Malkija, Mijamin, Éléazar, Malkija et Benaja;","Parmi ceux d'Israël: des fils de Pareosch, Ramia, Jizzija, Malkija, Mijamin, Éléazar, Malkija et Benaja;"],[10,26,"des fils d'Élam, Matthania, Zacharie, Jehiel, Abdi, Jerémoth et Élie;","des fils d'Élam, Matthania, Zacharie, Jehiel, Abdi, Jerémoth et Élie;"],[10,27,"des fils de Zatthu, Eljoénaï, Éliaschib, Matthania, Jerémoth, Zabad et Aziza;","des fils de Zatthu, Eljoénaï, Éliaschib, Matthania, Jerémoth, Zabad et Aziza;"],[10,28,"des fils de Bébaï, Jochanan, Hanania, Zabbaï et Athlaï;","des fils de Bébaï, Jochanan, Hanania, Zabbaï et Athlaï;"],[10,29,"des fils de Bani, Meschullam, Malluc, Adaja, Jaschub, Scheal et Ramoth;","des fils de Bani, Meschullam, Malluc, Adaja, Jaschub, Scheal et Ramoth;"],[10,30,"des fils de Pachath-Moab, Adna, Kelal, Benaja, Maaséja, Matthania, Betsaleel, Binnuï et Manassé;","des fils de Pachath-Moab, Adna, Kelal, Benaja, Maaséja, Matthania, Betsaleel, Binnuï et Manassé;"],[10,31,"des fils de Harim, Éliézer, Jischija, Malkija, Schemaeja, Siméon,","des fils de Harim, Éliézer, Jischija, Malkija, Schemaeja, Siméon,"],[10,32,"Benjamin, Malluc et Schemaria;","Benjamin, Malluc et Schemaria;"],[10,33,"des fils de Haschum, Matthnaï, Matthattha, Zabad, Éliphéleth, Jerémaï, Manassé et Schimeï;","des fils de Haschum, Matthnaï, Matthattha, Zabad, Éliphéleth, Jerémaï, Manassé et Schimeï;"],[10,34,"des fils de Bani, Maadaï, Amram, Uel,","des fils de Bani, Maadaï, Amram, Uel,"],[10,35,"Benaja, Bédia, Keluhu,","Benaja, Bédia, Keluhu,"],[10,36,"Vania, Merémoth, Éliaschib,","Vania, Merémoth, Éliaschib,"],[10,37,"Matthania, Matthnaï, Jaasaï,","Matthania, Matthnaï, Jaasaï,"],[10,38,"Bani, Binnuï, Schimeï,","Bani, Binnuï, Schimeï,"],[10,39,"Schélémia, Nathan, Adaja,","Schélémia, Nathan, Adaja,"],[10,40,"Macnadbaï, Schaschaï, Scharaï,","Macnadbaï, Schaschaï, Scharaï,"],[10,41,"Azareel, Schélémia, Schemaria,","Azareel, Schélémia, Schemaria,"],[10,42,"Schallum, Amaria et Joseph;","Schallum, Amaria et Joseph;"],[10,43,"des fils de Nebo, Jeïel, Matthithia, Zabad, Zebina, Jaddaï, Joël et Benaja.","des fils de Nebo, Jeïel, Matthithia, Zabad, Zebina, Jaddaï, Joël et Benaja."],[10,44,"Tous ceux-là avaient pris des femmes étrangères, et plusieurs en avaient eu des enfants.","Tous ceux-là avaient pris des femmes étrangères, et plusieurs en avaient eu des enfants."]],"spa-rv1909":[[1,1,"Y EN el primerañode Ciroreyde Persia, para que se cumpliesela palabrade Jehovápor bocade Jeremías, excitó Jehováel espíritude Ciroreyde Persia, el cual hizo pasar pregón por todosu reino, y tambiénpor escrito, diciendo:","Y EN el primerañode Ciroreyde Persia, para que se cumpliesela palabrade Jehovápor bocade Jeremías, excitó Jehováel espíritude Ciroreyde Persia, el cual hizo pasar pregón por todosu reino, y tambiénpor escrito, diciendo:"],[1,2,"Asíha dichoCiroreyde Persia: JehováDiosde los cielosme ha dadotodoslos reinosde la tierra, y meha mandadoque le edifiquecasaen Jerusalem, queestá en Judá.","Asíha dichoCiroreyde Persia: JehováDiosde los cielosme ha dadotodoslos reinosde la tierra, y meha mandadoque le edifiquecasaen Jerusalem, queestá en Judá."],[1,3,"¿Quién hay entre vosotros de todo supueblo? SeaDiosconél, y subaá Jerusalemqueestá en Judá, y edifiquela casaá JehováDiosde Israel, (éles el Dios,) la cualestá en Jerusalem.","¿Quién hay entre vosotros de todo supueblo? SeaDiosconél, y subaá Jerusalemqueestá en Judá, y edifiquela casaá JehováDiosde Israel, (éles el Dios,) la cualestá en Jerusalem."],[1,4,"Y á cualquieraque hubiere quedadode todoslos lugaresdondeperegrinare, los hombresde sulugarle ayudencon plata, y oro, y hacienda, y con bestias; con dones voluntariospara la casade Dios, la cualestá en Jerusalem.","Y á cualquieraque hubiere quedadode todoslos lugaresdondeperegrinare, los hombresde sulugarle ayudencon plata, y oro, y hacienda, y con bestias; con dones voluntariospara la casade Dios, la cualestá en Jerusalem."],[1,5,"Entonces se levantaronlos cabezasde las familias de Judáy de Benjamín, y los sacerdotesy Levitas, todosaquellos cuyo espíritudespertóDiospara subirá edificarla casade Jehová, la cualestá en Jerusalem.","Entonces se levantaronlos cabezasde las familias de Judáy de Benjamín, y los sacerdotesy Levitas, todosaquellos cuyo espíritudespertóDiospara subirá edificarla casade Jehová, la cualestá en Jerusalem."],[1,6,"Y todoslos que estaban en sus alrededoresconfortaronlas manosde ellos con vasos de platay de oro, con hacienday bestias, y con cosas preciosas, á másde lo que se ofrecióvoluntariamente.","Y todoslos que estaban en sus alrededoresconfortaronlas manosde ellos con vasos de platay de oro, con hacienday bestias, y con cosas preciosas, á másde lo que se ofrecióvoluntariamente."],[1,7,"Y el reyCirosacólos vasosde la casade Jehová, queNabucodonosorhabía traspasadode Jerusalem, y puestoen la casade sus dioses.","Y el reyCirosacólos vasosde la casade Jehová, queNabucodonosorhabía traspasadode Jerusalem, y puestoen la casade sus dioses."],[1,8,"Sacólospues Ciroreyde Persia, pormanode Mitrídatestesorero, el cual los dió por cuentaá Sesbassarpríncipede Judá.","Sacólospues Ciroreyde Persia, pormanode Mitrídatestesorero, el cual los dió por cuentaá Sesbassarpríncipede Judá."],[1,9,"Y estaes la cuentade ellos: treintatazonesde oro, miltazonesde plata, veintey nuevecuchillos,","Y estaes la cuentade ellos: treintatazonesde oro, miltazonesde plata, veintey nuevecuchillos,"],[1,10,"Treintatazasde oro, cuatrocientasy diezotrastazasde plata, y milotrosvasos.","Treintatazasde oro, cuatrocientasy diezotrastazasde plata, y milotrosvasos."],[1,11,"Todoslos vasosde oroy de plata, cincomily cuatrocientos. Todoslos hizo llevarSesbassarconlos que subierondel cautiveriode Babiloniaá Jerusalem.","Todoslos vasosde oroy de plata, cincomily cuatrocientos. Todoslos hizo llevarSesbassarconlos que subierondel cautiveriode Babiloniaá Jerusalem."],[2,1,"Y ESTOSson los hijosde la provinciaque subieronde la cautividad, de la transmigraciónqueNabucodonosorreyde Babiloniahizo traspasar á Babilonia, y quevolvieroná Jerusalemy á Judá, cada unoá su ciudad:","Y ESTOSson los hijosde la provinciaque subieronde la cautividad, de la transmigraciónqueNabucodonosorreyde Babiloniahizo traspasar á Babilonia, y quevolvieroná Jerusalemy á Judá, cada unoá su ciudad:"],[2,2,"Los cuales vinieronconZorobabel, Jesuá, Nehemías, Seraías, Reelaías, Mardochêo, Bilsán, Mispar, Bigvai, RehumyBaana. La cuentade los varonesdel pueblode Israel:","Los cuales vinieronconZorobabel, Jesuá, Nehemías, Seraías, Reelaías, Mardochêo, Bilsán, Mispar, Bigvai, RehumyBaana. La cuentade los varonesdel pueblode Israel:"],[2,3,"Los hijosde Paros, dos milcientosetentay dos;","Los hijosde Paros, dos milcientosetentay dos;"],[2,4,"Los hijosde Sephatías, trescientossetentay dos;","Los hijosde Sephatías, trescientossetentay dos;"],[2,5,"Los hijosde Ara, setecientossetentay cinco;","Los hijosde Ara, setecientossetentay cinco;"],[2,6,"Los hijosde Pahath-moab, de los hijosde Josué yde Joab, dos milochocientosy doce;","Los hijosde Pahath-moab, de los hijosde Josué yde Joab, dos milochocientosy doce;"],[2,7,"Los hijosde Elam, mildoscientoscincuentay cuatro;","Los hijosde Elam, mildoscientoscincuentay cuatro;"],[2,8,"Los hijosde Zattu, novecientoscuarentay cinco;","Los hijosde Zattu, novecientoscuarentay cinco;"],[2,9,"Los hijosde Zachâi, setecientosy sesenta;","Los hijosde Zachâi, setecientosy sesenta;"],[2,10,"Los hijosde Bani, seiscientoscuarentay dos;","Los hijosde Bani, seiscientoscuarentay dos;"],[2,11,"Los hijosde Bebai, seiscientosveintey tres;","Los hijosde Bebai, seiscientosveintey tres;"],[2,12,"Los hijosde Azgad, mildoscientosveintey dos;","Los hijosde Azgad, mildoscientosveintey dos;"],[2,13,"Los hijosde Adonicam, seiscientossesentay seis;","Los hijosde Adonicam, seiscientossesentay seis;"],[2,14,"Los hijosde Bigvai, dos milcincuentay seis;","Los hijosde Bigvai, dos milcincuentay seis;"],[2,15,"Los hijosde Adin, cuatrocientoscincuentay cuatro;","Los hijosde Adin, cuatrocientoscincuentay cuatro;"],[2,16,"Los hijosde Ater, de Ezechîas, noventay ocho;","Los hijosde Ater, de Ezechîas, noventay ocho;"],[2,17,"Los hijosde Besai, trescientosveintey tres;","Los hijosde Besai, trescientosveintey tres;"],[2,18,"Los hijosde Jora, cientoy doce;","Los hijosde Jora, cientoy doce;"],[2,19,"Los hijosde Hasum, doscientosveintey tres;","Los hijosde Hasum, doscientosveintey tres;"],[2,20,"Los hijosde Gibbar, noventay cinco;","Los hijosde Gibbar, noventay cinco;"],[2,21,"Los hijosde Beth-lehem, cientoveintey tres;","Los hijosde Beth-lehem, cientoveintey tres;"],[2,22,"Los varonesde Nethopha, cincuentay seis;","Los varonesde Nethopha, cincuentay seis;"],[2,23,"Los varonesde Anathoth, cientoveintey ocho;","Los varonesde Anathoth, cientoveintey ocho;"],[2,24,"Los hijosde Asmaveth, cuarentay dos;","Los hijosde Asmaveth, cuarentay dos;"],[2,25,"Los hijosde Chîriath-jearim, Cephira, y Beeroth, setecientoscuarentay tres;","Los hijosde Chîriath-jearim, Cephira, y Beeroth, setecientoscuarentay tres;"],[2,26,"Los hijosde Ramay Gabaa, seiscientosveintey uno;","Los hijosde Ramay Gabaa, seiscientosveintey uno;"],[2,27,"Los varonesde Michmas, cientoveintey dos;","Los varonesde Michmas, cientoveintey dos;"],[2,28,"Los varonesde Beth-ely Hai, doscientosveintey tres;","Los varonesde Beth-ely Hai, doscientosveintey tres;"],[2,29,"Los hijosde Nebo, cincuentay dos;","Los hijosde Nebo, cincuentay dos;"],[2,30,"Los hijosde Magbis, cientocincuentay seis;","Los hijosde Magbis, cientocincuentay seis;"],[2,31,"Los hijosdel otroElam, mildoscientoscincuentay cuatro;","Los hijosdel otroElam, mildoscientoscincuentay cuatro;"],[2,32,"Los hijosde Harim, trescientosy veinte;","Los hijosde Harim, trescientosy veinte;"],[2,33,"Los hijosde Lod, Hadid, y Ono, setecientosveintey cinco;","Los hijosde Lod, Hadid, y Ono, setecientosveintey cinco;"],[2,34,"Los hijosde Jericó, trescientoscuarentay cinco;","Los hijosde Jericó, trescientoscuarentay cinco;"],[2,35,"Los hijosde Senaa, tresmilseiscientosy treinta;","Los hijosde Senaa, tresmilseiscientosy treinta;"],[2,36,"Los sacerdotes: los hijosde Jedaía, de la casade Jesuá, novecientossetentay tres;","Los sacerdotes: los hijosde Jedaía, de la casade Jesuá, novecientossetentay tres;"],[2,37,"Los hijosde Immer, milcincuentay dos;","Los hijosde Immer, milcincuentay dos;"],[2,38,"Los hijosde Pashur, mildoscientoscuarentay siete;","Los hijosde Pashur, mildoscientoscuarentay siete;"],[2,39,"Los hijosde Harim, mildiezy siete.","Los hijosde Harim, mildiezy siete."],[2,40,"Los Levitas: los hijosde Jesuáy de Cadmiel, de los hijosde Odovías, setentay cuatro.","Los Levitas: los hijosde Jesuáy de Cadmiel, de los hijosde Odovías, setentay cuatro."],[2,41,"Los cantores: los hijosde Asaph, cientoveintey ocho.","Los cantores: los hijosde Asaph, cientoveintey ocho."],[2,42,"Los hijosde los porteros: los hijosde Sallum, los hijosde Ater, los hijosde Talmón, los hijosde Accub, los hijosde Hatita, los hijosde Sobai; entodos, cientotreintay nueve.","Los hijosde los porteros: los hijosde Sallum, los hijosde Ater, los hijosde Talmón, los hijosde Accub, los hijosde Hatita, los hijosde Sobai; entodos, cientotreintay nueve."],[2,43,"Los Nethineos: los hijosde Siha, los hijosde Hasupha, los hijosde Thabaoth,","Los Nethineos: los hijosde Siha, los hijosde Hasupha, los hijosde Thabaoth,"],[2,44,"Los hijosde Chêros, los hijosde Siaa, los hijosde Phadón;","Los hijosde Chêros, los hijosde Siaa, los hijosde Phadón;"],[2,45,"Los hijosde Lebana, los hijosde Hagaba, los hijosde Accub;","Los hijosde Lebana, los hijosde Hagaba, los hijosde Accub;"],[2,46,"Los hijosde Hagab, los hijosde Samlai, los hijosde Hanán;","Los hijosde Hagab, los hijosde Samlai, los hijosde Hanán;"],[2,47,"Los hijosde Giddel, los hijosde Gaher, los hijosde Reaía;","Los hijosde Giddel, los hijosde Gaher, los hijosde Reaía;"],[2,48,"Los hijosde Resin, los hijosde Necoda, los hijosde Gazam;","Los hijosde Resin, los hijosde Necoda, los hijosde Gazam;"],[2,49,"Los hijosde Uzza, los hijosde Phasea, los hijosde Besai;","Los hijosde Uzza, los hijosde Phasea, los hijosde Besai;"],[2,50,"Los hijosde Asena, los hijosde Meunim, los hijosde Nephusim;","Los hijosde Asena, los hijosde Meunim, los hijosde Nephusim;"],[2,51,"Los hijosde Bacbuc, los hijosde Hacusa, los hijosde Harhur;","Los hijosde Bacbuc, los hijosde Hacusa, los hijosde Harhur;"],[2,52,"Los hijosde Basluth, los hijosde Mehida, los hijosde Harsa;","Los hijosde Basluth, los hijosde Mehida, los hijosde Harsa;"],[2,53,"Los hijosde Barcos, los hijosde Sisera, los hijosde Thema;","Los hijosde Barcos, los hijosde Sisera, los hijosde Thema;"],[2,54,"Los hijosde Nesía, los hijosde Hatipha.","Los hijosde Nesía, los hijosde Hatipha."],[2,55,"Los hijosde los siervosde Salomón: los hijosde Sotai, los hijosde Sophereth, los hijosde Peruda;","Los hijosde los siervosde Salomón: los hijosde Sotai, los hijosde Sophereth, los hijosde Peruda;"],[2,56,"Los hijosde Jaala, los hijosde Darcón, los hijosde Giddel;","Los hijosde Jaala, los hijosde Darcón, los hijosde Giddel;"],[2,57,"Los hijosde Sephatías, los hijosde Hatil, los hijosde Phochêreth-hassebaim, los hijosde Ami.","Los hijosde Sephatías, los hijosde Hatil, los hijosde Phochêreth-hassebaim, los hijosde Ami."],[2,58,"Todoslos Nethineos, é hijosde los siervosde Salomón, trescientosnoventay dos.","Todoslos Nethineos, é hijosde los siervosde Salomón, trescientosnoventay dos."],[2,59,"Y estosfueron los que subieronde Tel-mela, Tel-harsa, Chêrub, Addan, é Immer, los cuales nopudieronmostrar la casade suspadres, ni sulinaje, sieran de Israel:","Y estosfueron los que subieronde Tel-mela, Tel-harsa, Chêrub, Addan, é Immer, los cuales nopudieronmostrar la casade suspadres, ni sulinaje, sieran de Israel:"],[2,60,"Los hijosde Delaía, los hijosde Tobías, los hijosde Necoda, seiscientoscincuentay dos.","Los hijosde Delaía, los hijosde Tobías, los hijosde Necoda, seiscientoscincuentay dos."],[2,61,"Y de los hijosde los sacerdotes: los hijosde Abaía, los hijosde Cos, los hijosde Barzillai, el cualtomómujerde las hijasde BarzillaiGalaadita, y fué llamadodel nombrede ellas.","Y de los hijosde los sacerdotes: los hijosde Abaía, los hijosde Cos, los hijosde Barzillai, el cualtomómujerde las hijasde BarzillaiGalaadita, y fué llamadodel nombrede ellas."],[2,62,"Estosbuscaronsu registrode genealogías, y nofué hallado; y fueron echadosdelsacerdocio.","Estosbuscaronsu registrode genealogías, y nofué hallado; y fueron echadosdelsacerdocio."],[2,63,"Y el Tirsathales dijoquenocomiesende las cosas más santas, hastaquehubiesesacerdotecon Urimy Thummim.","Y el Tirsathales dijoquenocomiesende las cosas más santas, hastaquehubiesesacerdotecon Urimy Thummim."],[2,64,"Todala congregación, unidacomo un solo hombre, era de cuarentay dos miltrescientosy sesenta,","Todala congregación, unidacomo un solo hombre, era de cuarentay dos miltrescientosy sesenta,"],[2,65,"Sinsus siervosy siervas, los cualeseran sietemiltrescientostreintay siete: y tenían doscientoscantoresy cantoras.","Sinsus siervosy siervas, los cualeseran sietemiltrescientostreintay siete: y tenían doscientoscantoresy cantoras."],[2,66,"Sus caballoseran setecientostreintay seis; sus mulos, doscientoscuarentay cinco;","Sus caballoseran setecientostreintay seis; sus mulos, doscientoscuarentay cinco;"],[2,67,"Sus camellos, cuatrocientostreintay cinco; asnos, seismilsetecientosy veinte.","Sus camellos, cuatrocientostreintay cinco; asnos, seismilsetecientosy veinte."],[2,68,"Y algunos de los cabezasde los padres, cuando vinieroná la casade Jehovála cual estaba en Jerusalem, ofrecieron voluntariamentepara la casade Dios, para levantarlaensu asiento.","Y algunos de los cabezasde los padres, cuando vinieroná la casade Jehovála cual estaba en Jerusalem, ofrecieron voluntariamentepara la casade Dios, para levantarlaensu asiento."],[2,69,"Según sus fuerzasdieronal tesorerode la obrasesentay un mildracmas de oro, y cincomillibrasde plata, y cientúnicassacerdotales.","Según sus fuerzasdieronal tesorerode la obrasesentay un mildracmas de oro, y cincomillibrasde plata, y cientúnicassacerdotales."],[2,70,"Y habitaronlos sacerdotes, y los Levitas, y losdelpueblo, y los cantores, y los porterosy los Nethineos, en sus ciudades; y todoIsraelen sus ciudades.","Y habitaronlos sacerdotes, y los Levitas, y losdelpueblo, y los cantores, y los porterosy los Nethineos, en sus ciudades; y todoIsraelen sus ciudades."],[3,1,"Y LLEGADO el messéptimo, y yalos hijosde Israelen las ciudades, juntóseel pueblocomo unsolo hombreenJerusalem.","Y LLEGADO el messéptimo, y yalos hijosde Israelen las ciudades, juntóseel pueblocomo unsolo hombreenJerusalem."],[3,2,"Entonces se levantó Jesuáhijode Josadec, y sus hermanoslos sacerdotes, y Zorobabelhijode Sealthiel, y sus hermanos, y edificaronel altardel Diosde Israel, para ofrecersobreél holocaustos, como está escritoen la leyde Moisésvarónde Dios.","Entonces se levantó Jesuáhijode Josadec, y sus hermanoslos sacerdotes, y Zorobabelhijode Sealthiel, y sus hermanos, y edificaronel altardel Diosde Israel, para ofrecersobreél holocaustos, como está escritoen la leyde Moisésvarónde Dios."],[3,3,"Y asentaronel altarsobresus basas, bien que teníanmiedode los pueblosde las tierras, y ofrecieronsobreél holocaustosá Jehová, holocaustosá la mañanay á la tarde.","Y asentaronel altarsobresus basas, bien que teníanmiedode los pueblosde las tierras, y ofrecieronsobreél holocaustosá Jehová, holocaustosá la mañanay á la tarde."],[3,4,"Hicieronasimismo la solemnidadde las cabañas, como está escrito, y holocaustoscada díapor cuenta, conforme al rito, cadacosa en su día;","Hicieronasimismo la solemnidadde las cabañas, como está escrito, y holocaustoscada díapor cuenta, conforme al rito, cadacosa en su día;"],[3,5,"Y á más de esto, el holocaustocontinuo, y las nuevaslunas, y todaslas fiestassantificadas de Jehová, y todosacrificioespontáneo, todaofrenda voluntariaá Jehová.","Y á más de esto, el holocaustocontinuo, y las nuevaslunas, y todaslas fiestassantificadas de Jehová, y todosacrificioespontáneo, todaofrenda voluntariaá Jehová."],[3,6,"Desde el primerdíadel messéptimocomenzaroná ofrecerholocaustosá Jehová; mas el templode Jehovánoestaba aún fundado.","Desde el primerdíadel messéptimocomenzaroná ofrecerholocaustosá Jehová; mas el templode Jehovánoestaba aún fundado."],[3,7,"Y dierondineroá los carpinterosy oficiales; asimismo comiday bebiday aceiteá los Sidoniosy Tirios, para que trajesenmaderade cedrodel Líbanoá la marde Joppe, conforme á la voluntadde Ciroreyde Persiaacerca deesto.","Y dierondineroá los carpinterosy oficiales; asimismo comiday bebiday aceiteá los Sidoniosy Tirios, para que trajesenmaderade cedrodel Líbanoá la marde Joppe, conforme á la voluntadde Ciroreyde Persiaacerca deesto."],[3,8,"Y en el añosegundode su venidaála casade Diosen Jerusalem, en el messegundo, comenzaronZorobabelhijode Sealthiel, y Jesuáhijode Josadec, y los otrossus hermanos, los sacerdotesy los Levitas, y todoslos que habían venidode la cautividadá Jerusalem; y pusieroná los Levitasde veinteañosarribapara que tuviesen cargode la obrade la casade Jehová.","Y en el añosegundode su venidaála casade Diosen Jerusalem, en el messegundo, comenzaronZorobabelhijode Sealthiel, y Jesuáhijode Josadec, y los otrossus hermanos, los sacerdotesy los Levitas, y todoslos que habían venidode la cautividadá Jerusalem; y pusieroná los Levitasde veinteañosarribapara que tuviesen cargode la obrade la casade Jehová."],[3,9,"Jesuá también, sus hijosy sus hermanos, Cadmiely sus hijos, hijosde Judá, como unsolo hombreasistíanpara dar priesaálos que hacíanla obraen la casade Dios: los hijosde Henadad, sus hijosy sus hermanos, Levitas.","Jesuá también, sus hijosy sus hermanos, Cadmiely sus hijos, hijosde Judá, como unsolo hombreasistíanpara dar priesaálos que hacíanla obraen la casade Dios: los hijosde Henadad, sus hijosy sus hermanos, Levitas."],[3,10,"Y cuando los albañilesdel templode Jehováechaban los cimientos, pusieroná los sacerdotesvestidosde sus ropas, con trompetas, y á Levitashijosde Asaphcon címbalos, para que alabasená Jehová, segúnordenanzade Davidreyde Israel.","Y cuando los albañilesdel templode Jehováechaban los cimientos, pusieroná los sacerdotesvestidosde sus ropas, con trompetas, y á Levitashijosde Asaphcon címbalos, para que alabasená Jehová, segúnordenanzade Davidreyde Israel."],[3,11,"Y cantaban, alabandoy confesandoá Jehová, y decían: Porquees bueno, porquepara siemprees su misericordiasobreIsrael. Y todoel puebloaclamabacon grandejúbilo, alabandoá Jehová, porqueá la casade Jehováse echaba el cimiento.","Y cantaban, alabandoy confesandoá Jehová, y decían: Porquees bueno, porquepara siemprees su misericordiasobreIsrael. Y todoel puebloaclamabacon grandejúbilo, alabandoá Jehová, porqueá la casade Jehováse echaba el cimiento."],[3,12,"Y muchosde los sacerdotesy de los Levitasy de los cabezasde los padres, ancianosquehabían vistola casaprimera, viendo fundaresta casa, llorabanen altavoz, mientras muchosotrosdaban grandesgritosde alegría.","Y muchosde los sacerdotesy de los Levitasy de los cabezasde los padres, ancianosquehabían vistola casaprimera, viendo fundaresta casa, llorabanen altavoz, mientras muchosotrosdaban grandesgritosde alegría."],[3,13,"Y nopodía discernir el puebloel clamorde los gritosde alegría, de la vozdel llorodel pueblo: porqueclamaba el pueblocon grandejúbilo, y oíaseel ruidohastade lejos.","Y nopodía discernir el puebloel clamorde los gritosde alegría, de la vozdel llorodel pueblo: porqueclamaba el pueblocon grandejúbilo, y oíaseel ruidohastade lejos."],[4,1,"Y OYENDOlos enemigosde Judáy de Benjamín, quelos venidosde la cautividadedificabanel templode JehováDiosde Israel,","Y OYENDOlos enemigosde Judáy de Benjamín, quelos venidosde la cautividadedificabanel templode JehováDiosde Israel,"],[4,2,"Llegáronseá Zorobabel, y á los cabezasde los padres, y dijéronles: Edificaremosconvosotros, porquecomo vosotros buscaremos á vuestro Dios, y á él sacrificamos desde los díasde Esar-haddónreyde Asiria, que nos hizo subiraquí.","Llegáronseá Zorobabel, y á los cabezasde los padres, y dijéronles: Edificaremosconvosotros, porquecomo vosotros buscaremos á vuestro Dios, y á él sacrificamos desde los díasde Esar-haddónreyde Asiria, que nos hizo subiraquí."],[4,3,"Y díjolesZorobabel, y Jesuá, y los demáscabezasde los padresde Israel: Nonos conviene edificar con vosotros casaá nuestroDios, sinoque nosotrossoloslaedificaremosá JehováDiosde Israel, como nosmandóel reyCiro, reyde Persia.","Y díjolesZorobabel, y Jesuá, y los demáscabezasde los padresde Israel: Nonos conviene edificar con vosotros casaá nuestroDios, sinoque nosotrossoloslaedificaremosá JehováDiosde Israel, como nosmandóel reyCiro, reyde Persia."],[4,4,"Mas el pueblode la tierradebilitaba las manos del pueblode Judá, y los arredraban de edificar.","Mas el pueblode la tierradebilitaba las manos del pueblode Judá, y los arredraban de edificar."],[4,5,"Cohecharon además contraellos consejerospara disipar su consejo, todoel tiempode Ciroreyde Persia, y hastael reinadode Daríoreyde Persia.","Cohecharon además contraellos consejerospara disipar su consejo, todoel tiempode Ciroreyde Persia, y hastael reinadode Daríoreyde Persia."],[4,6,"Y en el reinadode Assuero, en el principiode su reinado, escribieronacusacionescontralos moradoresde Judáy de Jerusalem.","Y en el reinadode Assuero, en el principiode su reinado, escribieronacusacionescontralos moradoresde Judáy de Jerusalem."],[4,7,"Y en díasde Artajerjes, Bislam, Mitrídates, Tabeel, y los demássus compañeros, escribieronáArtajerjesreyde Persia; y la escriturade la cartaestaba hechaen siriaco, y declaradaen siriaco.","Y en díasde Artajerjes, Bislam, Mitrídates, Tabeel, y los demássus compañeros, escribieronáArtajerjesreyde Persia; y la escriturade la cartaestaba hechaen siriaco, y declaradaen siriaco."],[4,8,"Rehumcanciller, y Simsaisecretario, escribieronuna cartacontraJerusalemal reyArtajerjes, como se sigue.","Rehumcanciller, y Simsaisecretario, escribieronuna cartacontraJerusalemal reyArtajerjes, como se sigue."],[4,9,"Entonces Rehumcanciller, y Simsaisecretario, y los demássus compañeros, los Dineos, y los Apharsathachêos, Thepharleos, Apharseos, los Erchûeos, los Babilonios, Susanchêos, Dieveos, y Elamitas;","Entonces Rehumcanciller, y Simsaisecretario, y los demássus compañeros, los Dineos, y los Apharsathachêos, Thepharleos, Apharseos, los Erchûeos, los Babilonios, Susanchêos, Dieveos, y Elamitas;"],[4,10,"Y los demáspueblosqueel grandey gloriosoAsnappartrasportó, é hizo habitaren las ciudadesde Samaria, y los demásde la otra parte del río, etcétera, escribieron.","Y los demáspueblosqueel grandey gloriosoAsnappartrasportó, é hizo habitaren las ciudadesde Samaria, y los demásde la otra parte del río, etcétera, escribieron."],[4,11,"Este es el trasladode la cartaqueenviaron: Alrey Artajerjes: Tus siervosde la otra partedel río, etcétera.","Este es el trasladode la cartaqueenviaron: Alrey Artajerjes: Tus siervosde la otra partedel río, etcétera."],[4,12,"Sea notorioal rey, quelos Judíos quesubierondetiá nosotros, vinieroná Jerusalem; y edificanla ciudadrebeldey mala, y han erigido los muros; y compuesto los fundamentos.","Sea notorioal rey, quelos Judíos quesubierondetiá nosotros, vinieroná Jerusalem; y edificanla ciudadrebeldey mala, y han erigido los muros; y compuesto los fundamentos."],[4,13,"Ahora, notoriosea al rey, quesiaquellaciudadfuere reedificada, y los murosfueren establecidos, el tributo, pecho, y rentasnodarán, y el catastrode lo reyesserá menoscabado.","Ahora, notoriosea al rey, quesiaquellaciudadfuere reedificada, y los murosfueren establecidos, el tributo, pecho, y rentasnodarán, y el catastrode lo reyesserá menoscabado."],[4,14,"Ya pues queestamos mantenidos de palacio, nonos es justover el menospreciodel rey: hemos enviadoportanto, y hécholosaberal rey,","Ya pues queestamos mantenidos de palacio, nonos es justover el menospreciodel rey: hemos enviadoportanto, y hécholosaberal rey,"],[4,15,"Para que busqueen el librode las historias de nuestros padres; y hallarásen el librode las historias, y sabrásque estaciudades ciudadrebelde, y perjudicialá los reyesy á las provincias, y que detiempoantiguo formanen medio deella rebeliones; porlo queestaciudadfué destruída.","Para que busqueen el librode las historias de nuestros padres; y hallarásen el librode las historias, y sabrásque estaciudades ciudadrebelde, y perjudicialá los reyesy á las provincias, y que detiempoantiguo formanen medio deella rebeliones; porlo queestaciudadfué destruída."],[4,16,"Hacemos saberal rey, que siestaciudadfuereedificada, y erigidos sus muros, la parte alládel ríonoserá tuya.","Hacemos saberal rey, que siestaciudadfuereedificada, y erigidos sus muros, la parte alládel ríonoserá tuya."],[4,17,"El reyenvióestarespuestaá Rehumcanciller, y á Simsaisecretario, y á los demássus compañerosque habitanen Samaria, y á los demásde la parteallá del río: Paz, etc.","El reyenvióestarespuestaá Rehumcanciller, y á Simsaisecretario, y á los demássus compañerosque habitanen Samaria, y á los demásde la parteallá del río: Paz, etc."],[4,18,"La cartaque nosenviasteisclaramentefué leídadelantede mí.","La cartaque nosenviasteisclaramentefué leídadelantede mí."],[4,19,"Y pormí fué dadomandamiento, y buscaron, y hallaronqueaquellaciudaddetiempoantiguose levantacontralos reyes, y se rebela, y se formaen ella sedición:","Y pormí fué dadomandamiento, y buscaron, y hallaronqueaquellaciudaddetiempoantiguose levantacontralos reyes, y se rebela, y se formaen ella sedición:"],[4,20,"Y que reyesfuerteshuboenJerusalem, quienes señorearon entodolo que estáá la parte alládel río; y que tributo, y pecho, y rentasse les daba.","Y que reyesfuerteshuboenJerusalem, quienes señorearon entodolo que estáá la parte alládel río; y que tributo, y pecho, y rentasse les daba."],[4,21,"Ahorapuesdadordenque cesenaquelloshombres, y nosea esaciudadedificada, hastaque pormí sea dadomandamiento.","Ahorapuesdadordenque cesenaquelloshombres, y nosea esaciudadedificada, hastaque pormí sea dadomandamiento."],[4,22,"Y miradbien que no hagáis errorenesto: ¿por quéhabrá de crecerel dañopara perjuiciode los reyes?","Y miradbien que no hagáis errorenesto: ¿por quéhabrá de crecerel dañopara perjuiciode los reyes?"],[4,23,"Entonces, cuandoel trasladode la cartadel reyArtajerjesfué leídodelantede Rehum, y de Simsaisecretario, y sus compañeros, fueronprestamenteá Jerusalemálos Judíos, é hiciéronles cesarcon podery fuerza.","Entonces, cuandoel trasladode la cartadel reyArtajerjesfué leídodelantede Rehum, y de Simsaisecretario, y sus compañeros, fueronprestamenteá Jerusalemálos Judíos, é hiciéronles cesarcon podery fuerza."],[4,24,"Cesóentoncesla obrade la casade Dios, la cual estaba en Jerusalem: y cesóhastael añosegundodel reinadode Daríoreyde Persia.","Cesóentoncesla obrade la casade Dios, la cual estaba en Jerusalem: y cesóhastael añosegundodel reinadode Daríoreyde Persia."],[5,1,"Y PROFETIZARONHaggeoprofeta, y Zacaríashijode Iddo, profetas, á los Judíosqueestaban en Judáy en Jerusalemyendoen nombredel Diosde Israelá ellos.","Y PROFETIZARONHaggeoprofeta, y Zacaríashijode Iddo, profetas, á los Judíosqueestaban en Judáy en Jerusalemyendoen nombredel Diosde Israelá ellos."],[5,2,"Entoncesse levantaronZorobabelhijode Sealthiel, y Jesuáhijode Josadec; y comenzaroná edificar la casade Diosqueestaba en Jerusalem; y con elloslos profetasde Diosqueles ayudaban.","Entoncesse levantaronZorobabelhijode Sealthiel, y Jesuáhijode Josadec; y comenzaroná edificar la casade Diosqueestaba en Jerusalem; y con elloslos profetasde Diosqueles ayudaban."],[5,3,"En aquel tiempovinoáellos Tatnai, capitánde la parte alládel río, y Sethar-boznaiy sus compañeros, y dijéronlesasí: ¿Quién os dió mandamientopara edificarestacasa, y restablecer estosmuros?","En aquel tiempovinoáellos Tatnai, capitánde la parte alládel río, y Sethar-boznaiy sus compañeros, y dijéronlesasí: ¿Quién os dió mandamientopara edificarestacasa, y restablecer estosmuros?"],[5,4,"Entonces lesdijimosen orden á esto cuáleseranlos nombresde los varonesqueedificabanesteedificio.","Entonces lesdijimosen orden á esto cuáleseranlos nombresde los varonesqueedificabanesteedificio."],[5,5,"Mas los ojosde su Diosfueronsobrelos ancianosde los Judíos, y noles hicieron cesarhastaque el negociovinieseá Darío: y entoncesrespondieronpor cartasobreesto.","Mas los ojosde su Diosfueronsobrelos ancianosde los Judíos, y noles hicieron cesarhastaque el negociovinieseá Darío: y entoncesrespondieronpor cartasobreesto."],[5,6,"Traslado de la cartaqueTatnai, capitánde la parte alládel río, y Sethar-boznai, y sus compañeroslos Apharsachêos, queestaban á la parte allá del río, enviaronal reyDarío.","Traslado de la cartaqueTatnai, capitánde la parte alládel río, y Sethar-boznai, y sus compañeroslos Apharsachêos, queestaban á la parte allá del río, enviaronal reyDarío."],[5,7,"Enviáronlecarta, y de esta manera estaba escritoen ella. Al reyDaríotodapaz.","Enviáronlecarta, y de esta manera estaba escritoen ella. Al reyDaríotodapaz."],[5,8,"Seanotorioal rey, quefuimosá la provinciade Judea, á la casadel granDios, la cualse edificade piedrade mármol; y los maderosson puestosen las paredes, y la obrase haceapriesa, y prosperaen sus manos.","Seanotorioal rey, quefuimosá la provinciade Judea, á la casadel granDios, la cualse edificade piedrade mármol; y los maderosson puestosen las paredes, y la obrase haceapriesa, y prosperaen sus manos."],[5,9,"Entoncespreguntamosá los ancianos, diciéndolesasí: ¿Quiénos diómandamientopara edificarestacasa, y para restablecer estosmuros?","Entoncespreguntamosá los ancianos, diciéndolesasí: ¿Quiénos diómandamientopara edificarestacasa, y para restablecer estosmuros?"],[5,10,"Y tambiénles preguntamossus nombrespara hacértelo saber, para escribirtelos nombresde los varones queestaban por cabezas de ellos.","Y tambiénles preguntamossus nombrespara hacértelo saber, para escribirtelos nombresde los varones queestaban por cabezas de ellos."],[5,11,"Y respondiéronnos, diciendoasí: Nosotrossomos siervosdel Diosdel cieloy de la tierra, y reedificamosla casaqueya muchosañosantes había sido edificada, la cualedificóy fundóel granreyde Israel.","Y respondiéronnos, diciendoasí: Nosotrossomos siervosdel Diosdel cieloy de la tierra, y reedificamosla casaqueya muchosañosantes había sido edificada, la cualedificóy fundóel granreyde Israel."],[5,12,"Masdespuésquenuestrospadresensañaron al Diosde los cielos, él losentregóen manode Nabucodonosorreyde Babilonia, Caldeo, el cual destruyóestacasa, é hizo trasportarel puebloá Babilonia.","Masdespuésquenuestrospadresensañaron al Diosde los cielos, él losentregóen manode Nabucodonosorreyde Babilonia, Caldeo, el cual destruyóestacasa, é hizo trasportarel puebloá Babilonia."],[5,13,"Empero el primer añode Ciroreyde Babilonia, el mismoreyCirodiómandamientopara que estacasade Diosfuese edificada.","Empero el primer añode Ciroreyde Babilonia, el mismoreyCirodiómandamientopara que estacasade Diosfuese edificada."],[5,14,"Y tambiénlos vasosdeoroy deplatadela casadeDios, que Nabucodonosorhabía sacadodeltemploque estaba en Jerusalem, y loshabía metidoen el templodeBabilonia, el reyCirolossacódeltemplodeBabilonia, y fueron entregadosá Sesbassar, al cual había puestopor gobernador;","Y tambiénlos vasosdeoroy deplatadela casadeDios, que Nabucodonosorhabía sacadodeltemploque estaba en Jerusalem, y loshabía metidoen el templodeBabilonia, el reyCirolossacódeltemplodeBabilonia, y fueron entregadosá Sesbassar, al cual había puestopor gobernador;"],[5,15,"Y le dijo: Tomaestosvasos, vey ponlosen el temploqueestá en Jerusalem; y la casade Diossea edificada ensu lugar.","Y le dijo: Tomaestosvasos, vey ponlosen el temploqueestá en Jerusalem; y la casade Diossea edificada ensu lugar."],[5,16,"EntoncesesteSesbassarvino, y pusolos fundamentosde la casade Diosqueestaba en Jerusalem, y desdeentonceshastaahorase edifica, y aun noestá acabada.","EntoncesesteSesbassarvino, y pusolos fundamentosde la casade Diosqueestaba en Jerusalem, y desdeentonceshastaahorase edifica, y aun noestá acabada."],[5,17,"Y ahora, sialreyparece bien, búsqueseen la casade los tesorosdel reyqueestá allíen Babilonia, siesasí queporel reyCirohabía sido dadomandamientopara edificar estacasade Diosen Jerusalem, y envíenos á decirla voluntaddel reysobreesto.","Y ahora, sialreyparece bien, búsqueseen la casade los tesorosdel reyqueestá allíen Babilonia, siesasí queporel reyCirohabía sido dadomandamientopara edificar estacasade Diosen Jerusalem, y envíenos á decirla voluntaddel reysobreesto."],[6,1,"ENTONCESel reyDaríodiómandamiento, y buscaron en la casade los libros, dondeguardabanlos tesorosallíen Babilonia.","ENTONCESel reyDaríodiómandamiento, y buscaron en la casade los libros, dondeguardabanlos tesorosallíen Babilonia."],[6,2,"Y fué halladoen Achmetta, en el palacioqueestá en la provinciade Media, un libro, dentro del cualestaba escritoasí: Memoria:","Y fué halladoen Achmetta, en el palacioqueestá en la provinciade Media, un libro, dentro del cualestaba escritoasí: Memoria:"],[6,3,"En el añoprimerodel reyCiro, el mismoreyCirodiómandamientoacerca de la casade Diosque estaba en Jerusalem, que fuese la casaedificadapara lugaren que sacrifiquensacrificios, y que sus paredesfuesen cubiertas; su alturade sesentacodos, y de sesentacodossu anchura;","En el añoprimerodel reyCiro, el mismoreyCirodiómandamientoacerca de la casade Diosque estaba en Jerusalem, que fuese la casaedificadapara lugaren que sacrifiquensacrificios, y que sus paredesfuesen cubiertas; su alturade sesentacodos, y de sesentacodossu anchura;"],[6,4,"Los órdenes, tresde piedrade mármol, y un ordende maderanueva: y que el gastosea dadode la casa del rey.","Los órdenes, tresde piedrade mármol, y un ordende maderanueva: y que el gastosea dadode la casa del rey."],[6,5,"Y tambiénlos vasosde oroy de platade la casade Dios, queNabucodonosorsacódeltemploqueestaba en Jerusalemy los pasóá Babilonia, sean devueltosy vayanal temploqueestá en Jerusalem, á su lugar, y sean puestosen la casade Dios.","Y tambiénlos vasosde oroy de platade la casade Dios, queNabucodonosorsacódeltemploqueestaba en Jerusalemy los pasóá Babilonia, sean devueltosy vayanal temploqueestá en Jerusalem, á su lugar, y sean puestosen la casade Dios."],[6,6,"Ahorapues, Tatnai, jefedel lado alládel río, Sethar-boznai, y sus compañeroslos Apharsachêosqueestáis á la otraparte del río, apartaosdeahí.","Ahorapues, Tatnai, jefedel lado alládel río, Sethar-boznai, y sus compañeroslos Apharsachêosqueestáis á la otraparte del río, apartaosdeahí."],[6,7,"Dejadla obrade la casade este Diosal principal de los Judíos, y á sus ancianos, para que edifiquen la casade este Diosensu lugar.","Dejadla obrade la casade este Diosal principal de los Judíos, y á sus ancianos, para que edifiquen la casade este Diosensu lugar."],[6,8,"Y pormí es dadomandamientode lo quehabéis de hacerconlos ancianosde estos Judíos, para edificar la casade este Dios: quedela haciendadel rey, quetienedel tributode la parte alládel río, los gastossean dadosluego á aquellos varones, para quenocesen.","Y pormí es dadomandamientode lo quehabéis de hacerconlos ancianosde estos Judíos, para edificar la casade este Dios: quedela haciendadel rey, quetienedel tributode la parte alládel río, los gastossean dadosluego á aquellos varones, para quenocesen."],[6,9,"Y lo quefuere necesario, becerrosy carnerosy corderos, para holocaustosal Diosdel cielo, trigo, sal, vinoy aceite, conforme á lo quedijerenlos sacerdotesqueestán en Jerusalem, déseles cada un díasinobstáculoalguno;","Y lo quefuere necesario, becerrosy carnerosy corderos, para holocaustosal Diosdel cielo, trigo, sal, vinoy aceite, conforme á lo quedijerenlos sacerdotesqueestán en Jerusalem, déseles cada un díasinobstáculoalguno;"],[6,10,"Para que ofrezcanolores de holganzaal Diosdel cielo, y orenpor la vidadel reyy por sushijos.","Para que ofrezcanolores de holganzaal Diosdel cielo, y orenpor la vidadel reyy por sushijos."],[6,11,"También es dadopormí mandamiento, quecualquieraquemudareestedecreto, sea derribadoun maderodesu casa, y enhiesto, sea colgadoenél: y su casasea hechamuladarporesto.","También es dadopormí mandamiento, quecualquieraquemudareestedecreto, sea derribadoun maderodesu casa, y enhiesto, sea colgadoenél: y su casasea hechamuladarporesto."],[6,12,"Y el Diosquehizo habitarallísu nombre, destruyatodoreyy puebloquepusieresu manopara mudaró destruir estacasade Dios, la cualestá en Jerusalem. Yo Daríopuse el decreto: sea hechoprestamente.","Y el Diosquehizo habitarallísu nombre, destruyatodoreyy puebloquepusieresu manopara mudaró destruir estacasade Dios, la cualestá en Jerusalem. Yo Daríopuse el decreto: sea hechoprestamente."],[6,13,"EntoncesTatnai, gobernadordel otrolado del río, y Sethar-boznai, y sus compañeros, hicieronprestamente segúnel reyDaríohabía enviado.","EntoncesTatnai, gobernadordel otrolado del río, y Sethar-boznai, y sus compañeros, hicieronprestamente segúnel reyDaríohabía enviado."],[6,14,"Y los ancianosde los Judíosedificabany prosperaban, conforme á la profecíade Haggeoprofeta, y de Zacaríashijode Iddo. Edificaronpues, y acabaron, porel mandamientodel Diosde Israel, y porel mandamientode Ciro, y de Darío, y de Artajerjesreyde Persia.","Y los ancianosde los Judíosedificabany prosperaban, conforme á la profecíade Haggeoprofeta, y de Zacaríashijode Iddo. Edificaronpues, y acabaron, porel mandamientodel Diosde Israel, y porel mandamientode Ciro, y de Darío, y de Artajerjesreyde Persia."],[6,15,"Y estacasafué acabada al tercerdíadel mesde Adar, queerael sextoañodel reinadodel reyDarío.","Y estacasafué acabada al tercerdíadel mesde Adar, queerael sextoañodel reinadodel reyDarío."],[6,16,"Y los hijosde Israel, los sacerdotesy los Levitas, y los demásque habían venidode la trasportación, hicieronla dedicaciónde estacasade Dioscon gozo.","Y los hijosde Israel, los sacerdotesy los Levitas, y los demásque habían venidode la trasportación, hicieronla dedicaciónde estacasade Dioscon gozo."],[6,17,"Y ofrecieronen la dedicaciónde estacasade Dioscienbecerros, doscientoscarneros, cuatrocientoscorderos; y machosde cabríoen expiaciónportodoIsrael, doce, conforme al númerode las tribusde Israel.","Y ofrecieronen la dedicaciónde estacasade Dioscienbecerros, doscientoscarneros, cuatrocientoscorderos; y machosde cabríoen expiaciónportodoIsrael, doce, conforme al númerode las tribusde Israel."],[6,18,"Y pusieroná los sacerdotesen sus clases, y á los Levitasen sus divisiones, sobre la obrade Diosque está en Jerusalem, conforme á lo escritoen el librode Moisés.","Y pusieroná los sacerdotesen sus clases, y á los Levitasen sus divisiones, sobre la obrade Diosque está en Jerusalem, conforme á lo escritoen el librode Moisés."],[6,19,"Y losde la transmigraciónhicieronla pascuaá los catorcedel mesprimero.","Y losde la transmigraciónhicieronla pascuaá los catorcedel mesprimero."],[6,20,"Porquelos sacerdotesy los Levitasse habían purificadoá una; todosfueron limpios: y sacrificaronla pascuapor todoslos de la transmigración, y por sushermanoslos sacerdotes, y por símismos.","Porquelos sacerdotesy los Levitasse habían purificadoá una; todosfueron limpios: y sacrificaronla pascuapor todoslos de la transmigración, y por sushermanoslos sacerdotes, y por símismos."],[6,21,"Y comieronlos hijosde Israelque habían vueltode la transmigración, y todoslos que se habían apartadoá ellos de la inmundicia de las gentesde la tierra, para buscará JehováDiosde Israel.","Y comieronlos hijosde Israelque habían vueltode la transmigración, y todoslos que se habían apartadoá ellos de la inmundicia de las gentesde la tierra, para buscará JehováDiosde Israel."],[6,22,"Y celebraronla solemnidadde los panes ázimossietedíascon regocijo, por cuantoJehoválos había alegrado, y convertidoel corazóndel reyde Asiriaá ellos, para esforzarsus manosen la obrade la casade Dios, del Diosde Israel.","Y celebraronla solemnidadde los panes ázimossietedíascon regocijo, por cuantoJehoválos había alegrado, y convertidoel corazóndel reyde Asiriaá ellos, para esforzarsus manosen la obrade la casade Dios, del Diosde Israel."],[7,1,"PASADASestas cosas, en el reinadode Artajerjesreyde Persia, Esdras, hijode Seraías, hijode Azarías, hijode Hilcías,","PASADASestas cosas, en el reinadode Artajerjesreyde Persia, Esdras, hijode Seraías, hijode Azarías, hijode Hilcías,"],[7,2,"Hijode Sallum, hijode Sadoc, hijode Achîtob,","Hijode Sallum, hijode Sadoc, hijode Achîtob,"],[7,3,"Hijode Amarías, hijode Azarías, hijode Meraioth,","Hijode Amarías, hijode Azarías, hijode Meraioth,"],[7,4,"Hijode Zeraías, hijode Uzzi, hijode Bucci,","Hijode Zeraías, hijode Uzzi, hijode Bucci,"],[7,5,"Hijode Abisue, hijode Phinees, hijode Eleazar, hijode Aarón, primersacerdote:","Hijode Abisue, hijode Phinees, hijode Eleazar, hijode Aarón, primersacerdote:"],[7,6,"EsteEsdrassubióde Babilonia, el cual era escribadiligenteen la leyde Moisés, queJehováDiosde Israelhabía dado; y concedióleel rey, según la manode JehovásuDiossobreél, todolo quepidió.","EsteEsdrassubióde Babilonia, el cual era escribadiligenteen la leyde Moisés, queJehováDiosde Israelhabía dado; y concedióleel rey, según la manode JehovásuDiossobreél, todolo quepidió."],[7,7,"Y subieroncon éláJerusalemdelos hijosdeIsrael, y delos sacerdotes, y Levitas, y cantores, y porteros, y Nethineos, en el séptimoañodel reyArtajerjes.","Y subieroncon éláJerusalemdelos hijosdeIsrael, y delos sacerdotes, y Levitas, y cantores, y porteros, y Nethineos, en el séptimoañodel reyArtajerjes."],[7,8,"Y llegóá Jerusalemen el mesquinto, el añoséptimodel rey.","Y llegóá Jerusalemen el mesquinto, el añoséptimodel rey."],[7,9,"Porqueel díaprimerodel primermesfué el principiode la partida de Babilonia, y al primerodel mesquintollegóáJerusalem, según la buenamanode su Diossobre él.","Porqueel díaprimerodel primermesfué el principiode la partida de Babilonia, y al primerodel mesquintollegóáJerusalem, según la buenamanode su Diossobre él."],[7,10,"PorqueEsdrashabía preparadosu corazónpara inquirirla leyde Jehová, y para hacer y enseñará Israelmandamientosy juicios.","PorqueEsdrashabía preparadosu corazónpara inquirirla leyde Jehová, y para hacer y enseñará Israelmandamientosy juicios."],[7,11,"Y este es el traslado de la cartaquedióel reyArtajerjesá Esdras, sacerdoteescriba, escribade las palabras mandadasde Jehová, y de sus estatutosá Israel:","Y este es el traslado de la cartaquedióel reyArtajerjesá Esdras, sacerdoteescriba, escribade las palabras mandadasde Jehová, y de sus estatutosá Israel:"],[7,12,"Artajerjes, reyde los reyes, á Esdrassacerdote, escribaperfecto de la leydel Diosdel cielo: Salud, etc.","Artajerjes, reyde los reyes, á Esdrassacerdote, escribaperfecto de la leydel Diosdel cielo: Salud, etc."],[7,13,"Pormí es dadomandamiento, quecualquieraquequisiere en mi reino, delpueblode Israely de sus sacerdotesy Levitas, ircontigoá Jerusalem, vaya.","Pormí es dadomandamiento, quecualquieraquequisiere en mi reino, delpueblode Israely de sus sacerdotesy Levitas, ircontigoá Jerusalem, vaya."],[7,14,"Porquedepartedel reyy desus sieteconsultoreseres enviadoá visitará Judeay á Jerusalem, conforme á la leydetu Diosqueestá en tu mano;","Porquedepartedel reyy desus sieteconsultoreseres enviadoá visitará Judeay á Jerusalem, conforme á la leydetu Diosqueestá en tu mano;"],[7,15,"Y á llevarla platay el oroque el reyy sus consultores voluntariamente ofrecenal Diosde Israel, cuyamoradaestá en Jerusalem;","Y á llevarla platay el oroque el reyy sus consultores voluntariamente ofrecenal Diosde Israel, cuyamoradaestá en Jerusalem;"],[7,16,"Y todala platay el oroquehallaresen todala provinciade Babilonia, conlas ofrendasvoluntarias del puebloy de los sacerdotes, que de su voluntad ofrecierenpara la casade su Diosqueestá en Jerusalem.","Y todala platay el oroquehallaresen todala provinciade Babilonia, conlas ofrendasvoluntarias del puebloy de los sacerdotes, que de su voluntad ofrecierenpara la casade su Diosqueestá en Jerusalem."],[7,17,"Compraráspuesprestamente con esta plata becerros, carneros, corderos, con sus presentesy sus libaciones, y los ofrecerássobreel altarde la casade vuestro Diosque está en Jerusalem.","Compraráspuesprestamente con esta plata becerros, carneros, corderos, con sus presentesy sus libaciones, y los ofrecerássobreel altarde la casade vuestro Diosque está en Jerusalem."],[7,18,"Y loqueá ti y á tus hermanospluguiere hacerde la otraplatay oro, hacedloconforme á la voluntadde vuestro Dios.","Y loqueá ti y á tus hermanospluguiere hacerde la otraplatay oro, hacedloconforme á la voluntadde vuestro Dios."],[7,19,"Y los vasosquete son entregadospara el serviciode la casade tu Dios, los restituirásdelantede Diosen Jerusalem.","Y los vasosquete son entregadospara el serviciode la casade tu Dios, los restituirásdelantede Diosen Jerusalem."],[7,20,"Y lo demás necesariopara la casade tu Diosque te fuere menesterdar, daráslo dela casadelos tesorosdel rey.","Y lo demás necesariopara la casade tu Diosque te fuere menesterdar, daráslo dela casadelos tesorosdel rey."],[7,21,"Y pormí el reyArtajerjeses dadomandamientoá todoslos tesorerosqueestán al otrolado del río, quetodolo queos demandare Esdrassacerdote, escribade la leydel Diosdel cielo, concédaseleluego,","Y pormí el reyArtajerjeses dadomandamientoá todoslos tesorerosqueestán al otrolado del río, quetodolo queos demandare Esdrassacerdote, escribade la leydel Diosdel cielo, concédaseleluego,"],[7,22,"Hastacientalentosde plata, y hastaciencorosde trigo, y hastacienbatosde vino, y hastacienbatosde aceite; y salsintasa.","Hastacientalentosde plata, y hastaciencorosde trigo, y hastacienbatosde vino, y hastacienbatosde aceite; y salsintasa."],[7,23,"Todolo que es mandadoporel Diosdel cielo, sea hechoprestamente para la casadel Diosdel cielo: pues, ¿porquéhabría de ser su iracontrael reinodel reyy de sushijos?","Todolo que es mandadoporel Diosdel cielo, sea hechoprestamente para la casadel Diosdel cielo: pues, ¿porquéhabría de ser su iracontrael reinodel reyy de sushijos?"],[7,24,"Y á vosotros os hacemos saber, queá todoslos sacerdotesy Levitas, cantores, porteros, Nethineosy ministrosde la casade Dios, ningunopueda imponerlestributo, ó pecho, ó renta.","Y á vosotros os hacemos saber, queá todoslos sacerdotesy Levitas, cantores, porteros, Nethineosy ministrosde la casade Dios, ningunopueda imponerlestributo, ó pecho, ó renta."],[7,25,"Y tú, Esdras, conforme á la sabiduríade tu Diosquetienes, ponjuecesy gobernadores, quegobiernená todoel puebloqueestá del otrolado del río, á todoslos quetienen noticia de las leyesde tu Dios; y al quenola tuviere, le enseñaréis.","Y tú, Esdras, conforme á la sabiduríade tu Diosquetienes, ponjuecesy gobernadores, quegobiernená todoel puebloqueestá del otrolado del río, á todoslos quetienen noticia de las leyesde tu Dios; y al quenola tuviere, le enseñaréis."],[7,26,"Y cualquieraquenohicierela leyde tu Dios, y la leydel rey, prestamente sea juzgado, ó á muerte, ó á desarraigo, ó á penade la hacienda, ó á prisión.","Y cualquieraquenohicierela leyde tu Dios, y la leydel rey, prestamente sea juzgado, ó á muerte, ó á desarraigo, ó á penade la hacienda, ó á prisión."],[7,27,"BenditoJehová, Diosde nuestrospadres, quepusotal cosaen el corazóndel rey, para honrarla casade Jehováqueestá en Jerusalem.","BenditoJehová, Diosde nuestrospadres, quepusotal cosaen el corazóndel rey, para honrarla casade Jehováqueestá en Jerusalem."],[7,28,"E inclinóhaciamísumisericordiadelantedel reyy de sus consultores, y de todoslos príncipespoderosos del rey. Y yo, confortadosegún la manode miDiossobremí, junté los principalesde Israelpara que subiesenconmigo.","E inclinóhaciamísumisericordiadelantedel reyy de sus consultores, y de todoslos príncipespoderosos del rey. Y yo, confortadosegún la manode miDiossobremí, junté los principalesde Israelpara que subiesenconmigo."],[8,1,"Y ESTOSson los cabezasde sus familias, y genealogíade aquellos que subieronconmigode Babilonia, reinandoel reyArtajerjes:","Y ESTOSson los cabezasde sus familias, y genealogíade aquellos que subieronconmigode Babilonia, reinandoel reyArtajerjes:"],[8,2,"De los hijosde Phinees, Gersón; de los hijosde Ithamar, Daniel; de los hijosde David, Hattus;","De los hijosde Phinees, Gersón; de los hijosde Ithamar, Daniel; de los hijosde David, Hattus;"],[8,3,"De los hijosde Sechâníasy de los hijosde Pharos, Zacarías, y conél, en la líneade varones, cientoy cincuenta;","De los hijosde Sechâníasy de los hijosde Pharos, Zacarías, y conél, en la líneade varones, cientoy cincuenta;"],[8,4,"De los hijosde Pahath-moab, Elioenai, hijode Zarahi, y conél doscientosvarones;","De los hijosde Pahath-moab, Elioenai, hijode Zarahi, y conél doscientosvarones;"],[8,5,"De los hijosde Sechânías, el hijode Jahaziel, y conél trescientosvarones;","De los hijosde Sechânías, el hijode Jahaziel, y conél trescientosvarones;"],[8,6,"De los hijosde Adín, Ebed, hijode Jonathán, y conél cincuentavarones;","De los hijosde Adín, Ebed, hijode Jonathán, y conél cincuentavarones;"],[8,7,"De los hijosde Elam, Isaía, hijode Athalías, y conél setentavarones;","De los hijosde Elam, Isaía, hijode Athalías, y conél setentavarones;"],[8,8,"Y de los hijosde Sephatías, Zebadías, hijode Michâel, y conél ochentavarones;","Y de los hijosde Sephatías, Zebadías, hijode Michâel, y conél ochentavarones;"],[8,9,"De los hijosde Joab, Obadías, hijode Jehiel, y conél doscientosdiez y ochovarones;","De los hijosde Joab, Obadías, hijode Jehiel, y conél doscientosdiez y ochovarones;"],[8,10,"Y de los hijosde Solomith, el hijode Josiphías, y conél cientoy sesentavarones;","Y de los hijosde Solomith, el hijode Josiphías, y conél cientoy sesentavarones;"],[8,11,"Y de los hijosde Bebai, Zacarías, hijode Bebai, y conél veintiochovarones;","Y de los hijosde Bebai, Zacarías, hijode Bebai, y conél veintiochovarones;"],[8,12,"Y de los hijosde Azgad, Johanán, hijode Catán, y conél cientoy diezvarones;","Y de los hijosde Azgad, Johanán, hijode Catán, y conél cientoy diezvarones;"],[8,13,"Y de los hijosde Adonicam, los postreros, cuyos nombresson estos, Eliphelet, Jeiel, y Semaías, y conellos sesentavarones;","Y de los hijosde Adonicam, los postreros, cuyos nombresson estos, Eliphelet, Jeiel, y Semaías, y conellos sesentavarones;"],[8,14,"Y de los hijosde Bigvai, Utaiy Zabud, y conellos sesentavarones.","Y de los hijosde Bigvai, Utaiy Zabud, y conellos sesentavarones."],[8,15,"Y juntélosjuntoal ríoque vieneáAhava, y reposamosallítresdías: y habiendo buscadoentre el puebloy entre los sacerdotes, nohalléallíde los hijosde Leví.","Y juntélosjuntoal ríoque vieneáAhava, y reposamosallítresdías: y habiendo buscadoentre el puebloy entre los sacerdotes, nohalléallíde los hijosde Leví."],[8,16,"Entonces despachéá Eliezer, y á Ariel, y á Semaías, y á Elnathán, y á Jarib, y á Elnathán, y á Nathán, y á Zacarías, y á Mesullam, principales; asimismo á Joiariby á Elnathán, hombres doctos;","Entonces despachéá Eliezer, y á Ariel, y á Semaías, y á Elnathán, y á Jarib, y á Elnathán, y á Nathán, y á Zacarías, y á Mesullam, principales; asimismo á Joiariby á Elnathán, hombres doctos;"],[8,17,"Y enviélosá Iddo, jefeen el lugarde Casipia, y puseen bocade ellos las palabrasque habían de hablará Iddo, y á sus hermanoslos Nethineosen el lugarde Casipia, para que nos trajesenministrospara la casade nuestroDios.","Y enviélosá Iddo, jefeen el lugarde Casipia, y puseen bocade ellos las palabrasque habían de hablará Iddo, y á sus hermanoslos Nethineosen el lugarde Casipia, para que nos trajesenministrospara la casade nuestroDios."],[8,18,"Y trajéronnos, según la buenamanode nuestroDiossobrenosotros, un varónentendidode los hijosde Mahalí, hijode Leví, hijode Israel; y á Serabíascon sus hijosy sus hermanos, dieciocho;","Y trajéronnos, según la buenamanode nuestroDiossobrenosotros, un varónentendidode los hijosde Mahalí, hijode Leví, hijode Israel; y á Serabíascon sus hijosy sus hermanos, dieciocho;"],[8,19,"Y á Hasabías, y conél á Isaíade los hijosde Merari, á sus hermanosy á sus hijos, veinte;","Y á Hasabías, y conél á Isaíade los hijosde Merari, á sus hermanosy á sus hijos, veinte;"],[8,20,"Y delos Nethineos, á quienes Davidcon los príncipespusopara el ministeriodelos Levitas, doscientosy veinteNethineos: todoslos cuales fueron declaradospor sus nombres.","Y delos Nethineos, á quienes Davidcon los príncipespusopara el ministeriodelos Levitas, doscientosy veinteNethineos: todoslos cuales fueron declaradospor sus nombres."],[8,21,"Y publiquéayunoallíjuntoal ríode Ahava, para afligirnosdelantede nuestroDios, para solicitardeél caminoderechopara nosotros, y para nuestrosniños, y para todanuestrahacienda.","Y publiquéayunoallíjuntoal ríode Ahava, para afligirnosdelantede nuestroDios, para solicitardeél caminoderechopara nosotros, y para nuestrosniños, y para todanuestrahacienda."],[8,22,"Porquetuve vergüenzade pediral reytropay gente de á caballo quenosdefendiesendelenemigoen el camino: porquehabíamos habladoal rey, diciendo: La manode nuestroDioses para biensobretodoslos quele buscan; massu fortalezay su furorsobretodoslos quele dejan.","Porquetuve vergüenzade pediral reytropay gente de á caballo quenosdefendiesendelenemigoen el camino: porquehabíamos habladoal rey, diciendo: La manode nuestroDioses para biensobretodoslos quele buscan; massu fortalezay su furorsobretodoslos quele dejan."],[8,23,"Ayunamospues, y pedimosá nuestroDiossobreesto, y él nos fué propicio.","Ayunamospues, y pedimosá nuestroDiossobreesto, y él nos fué propicio."],[8,24,"Apartéluego docede los principalesde los sacerdotes, á Serebíasy á Hasabías, y conellos diezde sus hermanos;","Apartéluego docede los principalesde los sacerdotes, á Serebíasy á Hasabías, y conellos diezde sus hermanos;"],[8,25,"Y pesélesla plata, y el oro, y los vasos, la ofrendaque para la casade nuestroDioshabían ofrecidoel rey, y sus consultores, y sus príncipes, y todos los que se hallaron en Israel.","Y pesélesla plata, y el oro, y los vasos, la ofrendaque para la casade nuestroDioshabían ofrecidoel rey, y sus consultores, y sus príncipes, y todos los que se hallaron en Israel."],[8,26,"Pesépues enmanosde ellos seiscientosy cincuentatalentosde plata, y vasosde platapor cientalentos, y cientalentosde oro;","Pesépues enmanosde ellos seiscientosy cincuentatalentosde plata, y vasosde platapor cientalentos, y cientalentosde oro;"],[8,27,"Además veintetazonesde oro, de mildracmas; y dosvasosde metallimpiomuy bueno, preciados como el oro.","Además veintetazonesde oro, de mildracmas; y dosvasosde metallimpiomuy bueno, preciados como el oro."],[8,28,"Y díjeles: Vosotrossois consagradosá Jehová, y santoslos vasos; y la platay el oroofrenda voluntariaá Jehová, Diosde nuestros padres.","Y díjeles: Vosotrossois consagradosá Jehová, y santoslos vasos; y la platay el oroofrenda voluntariaá Jehová, Diosde nuestros padres."],[8,29,"Velad, y guardadlos, hastaque los peséisdelantede los príncipesde los sacerdotesy Levitas, y de los jefesde los padresde Israelen Jerusalem, en las cámarasde la casade Jehová.","Velad, y guardadlos, hastaque los peséisdelantede los príncipesde los sacerdotesy Levitas, y de los jefesde los padresde Israelen Jerusalem, en las cámarasde la casade Jehová."],[8,30,"Los sacerdotespues y Levitasrecibieronel pesode la platay del oroy de los vasos, para traerloá Jerusalemá la casade nuestroDios.","Los sacerdotespues y Levitasrecibieronel pesode la platay del oroy de los vasos, para traerloá Jerusalemá la casade nuestroDios."],[8,31,"Y partimosdel ríode Ahavael docedel mesprimero, para irá Jerusalem: y la manode nuestroDiosfué sobrenosotros, el cual noslibróde manode enemigoy de asechadorenel camino.","Y partimosdel ríode Ahavael docedel mesprimero, para irá Jerusalem: y la manode nuestroDiosfué sobrenosotros, el cual noslibróde manode enemigoy de asechadorenel camino."],[8,32,"Y llegamosá Jerusalem, y reposamosallítresdías.","Y llegamosá Jerusalem, y reposamosallítresdías."],[8,33,"Al cuartodíafué luego pesadala plata, y el oro, y los vasos, en la casade nuestroDios, pormanode Meremothhijode Uríassacerdote, y conél Eleazarhijode Phinees; y conellos Jozabadhijode Jesuá, y Noadíashijode Binnui, Levitas;","Al cuartodíafué luego pesadala plata, y el oro, y los vasos, en la casade nuestroDios, pormanode Meremothhijode Uríassacerdote, y conél Eleazarhijode Phinees; y conellos Jozabadhijode Jesuá, y Noadíashijode Binnui, Levitas;"],[8,34,"Por cuentay por pesotodo: y se apuntótodoaquel pesoen aquel tiempo.","Por cuentay por pesotodo: y se apuntótodoaquel pesoen aquel tiempo."],[8,35,"Los que habían venidode la cautividad, los hijosde la transmigración, ofrecieron holocaustosalDiosde Israel, docebecerrosportodoIsrael, noventay seiscarneros, setentay sietecorderos, docemachos cabríosporexpiación: todoen holocaustoá Jehová.","Los que habían venidode la cautividad, los hijosde la transmigración, ofrecieron holocaustosalDiosde Israel, docebecerrosportodoIsrael, noventay seiscarneros, setentay sietecorderos, docemachos cabríosporexpiación: todoen holocaustoá Jehová."],[8,36,"Y dieronlos despachosdel reyá sus gobernadoresy capitanesdel otro ladodel río, los cuales favorecieronal puebloy á la casade Dios.","Y dieronlos despachosdel reyá sus gobernadoresy capitanesdel otro ladodel río, los cuales favorecieronal puebloy á la casade Dios."],[9,1,"Y ACABADASestascosas, los príncipesse llegaronámí, diciendo: El pueblode Israel, y los sacerdotesy Levitas, nose han apartado de los pueblosde las tierras, de los Cananeos, Hetheos, Pherezeos, Jebuseos, Ammonitas, y Moabitas, Egipcios, y Amorrheos, haciendoconforme á sus abominaciones.","Y ACABADASestascosas, los príncipesse llegaronámí, diciendo: El pueblode Israel, y los sacerdotesy Levitas, nose han apartado de los pueblosde las tierras, de los Cananeos, Hetheos, Pherezeos, Jebuseos, Ammonitas, y Moabitas, Egipcios, y Amorrheos, haciendoconforme á sus abominaciones."],[9,2,"Porquehan tomadode sushijaspara síy para sushijos, y la simientesantaha sido mezcladacon los pueblosde las tierras; y la manode los príncipesy de los gobernadoresha sidola primeraen esta prevaricación.","Porquehan tomadode sushijaspara síy para sushijos, y la simientesantaha sido mezcladacon los pueblosde las tierras; y la manode los príncipesy de los gobernadoresha sidola primeraen esta prevaricación."],[9,3,"Lo cual oyendo yo, rasguémi vestidoy mi manto, y arranquéde los cabellosde mi cabezay de mi barba, y sentémeatónito.","Lo cual oyendo yo, rasguémi vestidoy mi manto, y arranquéde los cabellosde mi cabezay de mi barba, y sentémeatónito."],[9,4,"Y juntáronseá mí todoslos temerosos de las palabrasdel Diosde Israel, á causa dela prevaricaciónde los de la transmigración; mas yoestuvesentado atónitohastael sacrificiode la tarde.","Y juntáronseá mí todoslos temerosos de las palabrasdel Diosde Israel, á causa dela prevaricaciónde los de la transmigración; mas yoestuvesentado atónitohastael sacrificiode la tarde."],[9,5,"Y al sacrificiode la tardelevantémede mi aflicción; y habiendo rasgado mi vestidoy mi manto, postrémede rodillas, y extendímis palmasáJehovámi Dios;","Y al sacrificiode la tardelevantémede mi aflicción; y habiendo rasgado mi vestidoy mi manto, postrémede rodillas, y extendímis palmasáJehovámi Dios;"],[9,6,"Y dije: Diosmío, confusoy avergonzadoestoy para levantar, oh Diosmío, mi rostroáti: porquenuestrasiniquidadesse han multiplicadosobre nuestra cabeza, y nuestrosdelitoshan crecidohastael cielo.","Y dije: Diosmío, confusoy avergonzadoestoy para levantar, oh Diosmío, mi rostroáti: porquenuestrasiniquidadesse han multiplicadosobre nuestra cabeza, y nuestrosdelitoshan crecidohastael cielo."],[9,7,"Desde los díasde nuestrospadreshastaeste díaestamos en grandeculpa; y por nuestrasiniquidadesnosotros, nuestrosreyes, y nuestrossacerdotes, hemos sido entregadosen manosde los reyesde las tierras, á cuchillo, á cautiverio, y á robo, y á confusión de rostro, como hoy día.","Desde los díasde nuestrospadreshastaeste díaestamos en grandeculpa; y por nuestrasiniquidadesnosotros, nuestrosreyes, y nuestrossacerdotes, hemos sido entregadosen manosde los reyesde las tierras, á cuchillo, á cautiverio, y á robo, y á confusión de rostro, como hoy día."],[9,8,"Y ahoracomo por un brevemomentofuéla misericordiade JehovánuestroDios, para hacer que nos quedase un restolibre, y para darnosestaca en el lugarde su santuario, á fin de alumbrarnuestrosojosnuestroDios, y darnosuna poca de vidaen nuestraservidumbre.","Y ahoracomo por un brevemomentofuéla misericordiade JehovánuestroDios, para hacer que nos quedase un restolibre, y para darnosestaca en el lugarde su santuario, á fin de alumbrarnuestrosojosnuestroDios, y darnosuna poca de vidaen nuestraservidumbre."],[9,9,"Porquesiervoséramos: mas en nuestraservidumbrenonosdesamparó nuestroDios, antes inclinósobrenosotrosmisericordiadelantede los reyesde Persia, para que senosdiesevidapara alzar la casade nuestroDios, y para hacer restaurarsus asolamientos, y para darnosvalladoen Judáy en Jerusalem.","Porquesiervoséramos: mas en nuestraservidumbrenonosdesamparó nuestroDios, antes inclinósobrenosotrosmisericordiadelantede los reyesde Persia, para que senosdiesevidapara alzar la casade nuestroDios, y para hacer restaurarsus asolamientos, y para darnosvalladoen Judáy en Jerusalem."],[9,10,"Mas ahora, ¿quédiremos, oh Diosnuestro, despuésde esto? porquenosotros hemos dejadotus mandamientos,","Mas ahora, ¿quédiremos, oh Diosnuestro, despuésde esto? porquenosotros hemos dejadotus mandamientos,"],[9,11,"Los cuales prescribistepor manode tussiervoslos profetas, diciendo: La tierraá la cualentráispara poseerla, tierrainmundaes á causa de la inmundiciade los pueblosde aquellas regiones, por las abominacionesde quelahan henchidode unoá otro extremocon su inmundicia.","Los cuales prescribistepor manode tussiervoslos profetas, diciendo: La tierraá la cualentráispara poseerla, tierrainmundaes á causa de la inmundiciade los pueblosde aquellas regiones, por las abominacionesde quelahan henchidode unoá otro extremocon su inmundicia."],[9,12,"Ahorapues, nodaréisvuestras hijasá los hijosde ellos, nisus hijastomaréispara vuestros hijos, niprocuraréissu paznisu bienpara siempre; para que seáis corroborados, y comáisel biende la tierra, y la dejéispor heredadá vuestros hijosparasiempre.","Ahorapues, nodaréisvuestras hijasá los hijosde ellos, nisus hijastomaréispara vuestros hijos, niprocuraréissu paznisu bienpara siempre; para que seáis corroborados, y comáisel biende la tierra, y la dejéispor heredadá vuestros hijosparasiempre."],[9,13,"Mas despuésde todolo que nosha sobrevenidoá causa de nuestrasmalasobras, y á causa de nuestrograndedelito; ya quetú, Diosnuestro, estorbasteque fuésemos oprimidos bajo de nuestrasiniquidades, y nos disteestetal efugio;","Mas despuésde todolo que nosha sobrevenidoá causa de nuestrasmalasobras, y á causa de nuestrograndedelito; ya quetú, Diosnuestro, estorbasteque fuésemos oprimidos bajo de nuestrasiniquidades, y nos disteestetal efugio;"],[9,14,"¿Hemos de volverá infringir tus mandamientos, y á emparentarcon los pueblosde estas abominaciones? ¿Note ensañarías contra nosotroshastaconsumirnos, sinque quedara resto ni escapatoria?","¿Hemos de volverá infringir tus mandamientos, y á emparentarcon los pueblosde estas abominaciones? ¿Note ensañarías contra nosotroshastaconsumirnos, sinque quedara resto ni escapatoria?"],[9,15,"Jehová, Diosde Israel, tú eresjusto: pues quehemos quedadoalgunos salvos, como este día, henos aquí delantede tien nuestrosdelitos; porquenoes posible subsistir en tu presenciaá causade esto.","Jehová, Diosde Israel, tú eresjusto: pues quehemos quedadoalgunos salvos, como este día, henos aquí delantede tien nuestrosdelitos; porquenoes posible subsistir en tu presenciaá causade esto."],[10,1,"Y ORANDO Esdrasy confesando, llorandoy postrándosedelantede la casade Dios, juntóseáél una muygrandemultitudde Israel, hombresy mujeresy niños; yllorabael pueblocon granllanto.","Y ORANDO Esdrasy confesando, llorandoy postrándosedelantede la casade Dios, juntóseáél una muygrandemultitudde Israel, hombresy mujeresy niños; yllorabael pueblocon granllanto."],[10,2,"Entonces respondióSechânías hijode Jehiel, de los hijosde Elam, y dijoá Esdras: Nosotroshemos prevaricado contra nuestroDios, pues tomamosmujeresextranjerasde los pueblosde la tierra: mas hayaúnesperanzapara Israelsobre esto.","Entonces respondióSechânías hijode Jehiel, de los hijosde Elam, y dijoá Esdras: Nosotroshemos prevaricado contra nuestroDios, pues tomamosmujeresextranjerasde los pueblosde la tierra: mas hayaúnesperanzapara Israelsobre esto."],[10,3,"Ahorapues hagamospactocon nuestroDios, que echaremos todaslas mujeresy los nacidosde ellas, según el consejodel Señor, y de los que temenel mandamientode nuestroDios: y hágaseconforme á la ley.","Ahorapues hagamospactocon nuestroDios, que echaremos todaslas mujeresy los nacidosde ellas, según el consejodel Señor, y de los que temenel mandamientode nuestroDios: y hágaseconforme á la ley."],[10,4,"Levántate, porqueá ti toca el negocio, y nosotrosseremos contigo; esfuérzate, y ponlo por obra.","Levántate, porqueá ti toca el negocio, y nosotrosseremos contigo; esfuérzate, y ponlo por obra."],[10,5,"Entonces se levantóEsdras, y juramentóá los príncipesde los sacerdotesy de los Levitas, y á todoIsrael, que haríanconforme á esto; y ellos juraron.","Entonces se levantóEsdras, y juramentóá los príncipesde los sacerdotesy de los Levitas, y á todoIsrael, que haríanconforme á esto; y ellos juraron."],[10,6,"Levantóseluego Esdrasde delantela casade Dios, y fuéseála cámarade Johanánhijode Eliasib: é idoallá, nocomiópannibebióagua, porquese entristeciósobre la prevaricaciónde los de la transmigración.","Levantóseluego Esdrasde delantela casade Dios, y fuéseála cámarade Johanánhijode Eliasib: é idoallá, nocomiópannibebióagua, porquese entristeciósobre la prevaricaciónde los de la transmigración."],[10,7,"E hicieron pasar pregónpor Judáy por Jerusalemá todoslos hijosde la transmigración, que se juntasenen Jerusalem:","E hicieron pasar pregónpor Judáy por Jerusalemá todoslos hijosde la transmigración, que se juntasenen Jerusalem:"],[10,8,"Y que el quenovinieradentro de tresdías, conforme al acuerdode los príncipesy de los ancianos, perdiesetodasuhacienda, y él fuese apartadode la compañíade los de la transmigración.","Y que el quenovinieradentro de tresdías, conforme al acuerdode los príncipesy de los ancianos, perdiesetodasuhacienda, y él fuese apartadode la compañíade los de la transmigración."],[10,9,"Así todoslos hombresde Judáy de Benjamínse reunieronen Jerusalemdentro de tresdías, á los veintedel mes, el cual era el mesnoveno; y sentósetodoel puebloen la plazade la casade Dios, temblandocon motivo deaquel negocio, y á causa delas lluvias.","Así todoslos hombresde Judáy de Benjamínse reunieronen Jerusalemdentro de tresdías, á los veintedel mes, el cual era el mesnoveno; y sentósetodoel puebloen la plazade la casade Dios, temblandocon motivo deaquel negocio, y á causa delas lluvias."],[10,10,"Y levantóseEsdrasel sacerdote, y díjoles: Vosotroshabéis prevaricado, por cuanto tomasteismujeresextrañas, añadiendoasísobreel pecadode Israel.","Y levantóseEsdrasel sacerdote, y díjoles: Vosotroshabéis prevaricado, por cuanto tomasteismujeresextrañas, añadiendoasísobreel pecadode Israel."],[10,11,"Ahorapues, dadgloriaá JehováDiosde vuestros padres, y hacedsu voluntad, y apartaosdelos pueblosdelas tierras, y delas mujeresextranjeras.","Ahorapues, dadgloriaá JehováDiosde vuestros padres, y hacedsu voluntad, y apartaosdelos pueblosdelas tierras, y delas mujeresextranjeras."],[10,12,"Y respondiótodoaquel concurso, y dijeronen altavoz: Asíse hagaconforme á tu palabra.","Y respondiótodoaquel concurso, y dijeronen altavoz: Asíse hagaconforme á tu palabra."],[10,13,"Mas el puebloes mucho, y el tiempolluvioso, y nohay fuerza para estar en la calle: nila obraes de undíanide dos, porquesomos muchoslos que hemos prevaricadoen este negocio.","Mas el puebloes mucho, y el tiempolluvioso, y nohay fuerza para estar en la calle: nila obraes de undíanide dos, porquesomos muchoslos que hemos prevaricadoen este negocio."],[10,14,"Estén ahora nuestrospríncipes, los de todala congregación; y todosaquellosque en nuestrasciudadeshubieren tomadomujeresextranjeras, venganá tiemposaplazados, y conellos los ancianosde cada ciudad, y los juecesde ellas, hastaque apartemosdenosotros el furordela iradenuestroDiossobre esto.","Estén ahora nuestrospríncipes, los de todala congregación; y todosaquellosque en nuestrasciudadeshubieren tomadomujeresextranjeras, venganá tiemposaplazados, y conellos los ancianosde cada ciudad, y los juecesde ellas, hastaque apartemosdenosotros el furordela iradenuestroDiossobre esto."],[10,15,"Fueron pues puestossobre este negocioJonathánhijode Asael, y Jaazías hijode Tikvah; y Mesullamy Sabethai, Levitas, les ayudaron.","Fueron pues puestossobre este negocioJonathánhijode Asael, y Jaazías hijode Tikvah; y Mesullamy Sabethai, Levitas, les ayudaron."],[10,16,"E hicieronasílos hijosde la transmigración. Y apartadosque fueron luego Esdrassacerdote, y los varonescabezasde familiasen la casa de sus padres, todosellos por sus nombres, sentáronseel primerdíadel mesdécimopara inquirirel negocio.","E hicieronasílos hijosde la transmigración. Y apartadosque fueron luego Esdrassacerdote, y los varonescabezasde familiasen la casa de sus padres, todosellos por sus nombres, sentáronseel primerdíadel mesdécimopara inquirirel negocio."],[10,17,"Y concluyeron, con todosaquellosque habían tomadomujeresextranjeras, al primerdíadel mesprimero.","Y concluyeron, con todosaquellosque habían tomadomujeresextranjeras, al primerdíadel mesprimero."],[10,18,"Y de los hijosde los sacerdotesquehabían tomadomujeresextranjeras, fueron halladosestos: De los hijosde Jesuáhijode Josadec, y de sus hermanos: Maasías, y Eliezer, y Jarib, y Gedalías;","Y de los hijosde los sacerdotesquehabían tomadomujeresextranjeras, fueron halladosestos: De los hijosde Jesuáhijode Josadec, y de sus hermanos: Maasías, y Eliezer, y Jarib, y Gedalías;"],[10,19,"Y dieronsu manoen promesade echar sus mujeres, y ofrecieroncomo culpados un carnerode los rebañospor su delito.","Y dieronsu manoen promesade echar sus mujeres, y ofrecieroncomo culpados un carnerode los rebañospor su delito."],[10,20,"Y de los hijosde Immer: Hananiy Zebadías.","Y de los hijosde Immer: Hananiy Zebadías."],[10,21,"Y de los hijosde Harím: Maasías, y Elías, y Semeías, y Jehiel, y Uzzías.","Y de los hijosde Harím: Maasías, y Elías, y Semeías, y Jehiel, y Uzzías."],[10,22,"Y de los hijosde Phasur: Elioenai, Maasías, Ismael, Nathanael, Jozabad, y Elasa.","Y de los hijosde Phasur: Elioenai, Maasías, Ismael, Nathanael, Jozabad, y Elasa."],[10,23,"Y delos hijos delos Levitas: Jozabad, y Simi, Kelaía(este es Kelita), Pethaía, Judáy Eliezer.","Y delos hijos delos Levitas: Jozabad, y Simi, Kelaía(este es Kelita), Pethaía, Judáy Eliezer."],[10,24,"Y delos cantores, Eliasib; y delos porteros: Sellum, y Telem, y Uri.","Y delos cantores, Eliasib; y delos porteros: Sellum, y Telem, y Uri."],[10,25,"Asimismo de Israel: De los hijosde Pharos: Ramíaé Izzías, y Malchías, y Miamim, y Eleazar, y Malchías, y Benaías.","Asimismo de Israel: De los hijosde Pharos: Ramíaé Izzías, y Malchías, y Miamim, y Eleazar, y Malchías, y Benaías."],[10,26,"Y de los hijosde Elam: Mathanías, Zachârías, y Jehiel, y Abdi, y Jeremoth, y Elía.","Y de los hijosde Elam: Mathanías, Zachârías, y Jehiel, y Abdi, y Jeremoth, y Elía."],[10,27,"Y de los hijosde Zattu: Elioenai, Eliasib, Mathanías, y Jeremoth, y Zabad, y Aziza.","Y de los hijosde Zattu: Elioenai, Eliasib, Mathanías, y Jeremoth, y Zabad, y Aziza."],[10,28,"Y de los hijosde Bebai: Johanán, Hananías, Zabbai, Atlai.","Y de los hijosde Bebai: Johanán, Hananías, Zabbai, Atlai."],[10,29,"Y de los hijosde Bani: Mesullam, Malluch, y Adaías, Jasub, y Seal, y Ramoth.","Y de los hijosde Bani: Mesullam, Malluch, y Adaías, Jasub, y Seal, y Ramoth."],[10,30,"Y de los hijosde Pahath-moab: Adna, y Chêleal, Benaías, Maasías, Mathanías, Besaleel, Binnuiy Manasés.","Y de los hijosde Pahath-moab: Adna, y Chêleal, Benaías, Maasías, Mathanías, Besaleel, Binnuiy Manasés."],[10,31,"Y de los hijosde Harim: Eliezer, Issia, Malchîas, Semeía, Simeón,","Y de los hijosde Harim: Eliezer, Issia, Malchîas, Semeía, Simeón,"],[10,32,"Benjamín, Malluch, Semarías.","Benjamín, Malluch, Semarías."],[10,33,"De los hijosde Hasum: Mathenai, Mathatha, Zabad, Eliphelet, Jeremai, Manasés, Sami.","De los hijosde Hasum: Mathenai, Mathatha, Zabad, Eliphelet, Jeremai, Manasés, Sami."],[10,34,"De los hijosde Bani: Maadi, Amramy Uel,","De los hijosde Bani: Maadi, Amramy Uel,"],[10,35,"Benaías, Bedías, Chêluhi,","Benaías, Bedías, Chêluhi,"],[10,36,"Vanías, Meremoth, Eliasib,","Vanías, Meremoth, Eliasib,"],[10,37,"Mathanías, Mathenai, y Jaasai,","Mathanías, Mathenai, y Jaasai,"],[10,38,"Y Bani, y Binnui, Simi,","Y Bani, y Binnui, Simi,"],[10,39,"Y Selemíasy Nathány Adaías,","Y Selemíasy Nathány Adaías,"],[10,40,"Machnadbai, Sasai, Sarai,","Machnadbai, Sasai, Sarai,"],[10,41,"Azareel, y Selamías, Semarías,","Azareel, y Selamías, Semarías,"],[10,42,"Sallum, Amarías, Joseph.","Sallum, Amarías, Joseph."],[10,43,"Y de los hijosde Nebo: Jehiel, Matithías, Zabad, Zebina, Jadau, y Joel, Benaías.","Y de los hijosde Nebo: Jehiel, Matithías, Zabad, Zebina, Jadau, y Joel, Benaías."],[10,44,"Todosestoshabían tomadomujeresextranjeras; y habíamujeresde ellosque habían paridohijos.","Todosestoshabían tomadomujeresextranjeras; y habíamujeresde ellosque habían paridohijos."]],"rus-synodal":[[1,1,"В первый год Кира, царя Персидского, во исполнение слова Господня из уст Иеремии, возбудил Господь дух Кира, царя Персидского, и он повелел объявить по всему царству своему, словесно и письменно:","V pervyj god Kira, carâ Persidskogo, vo ispolnenie slova Gospodnâ iz ust Ieremii, vozbudil Gospodʹ duh Kira, carâ Persidskogo, i on povelel obʺâvitʹ po vsemu carstvu svoemu, slovesno i pisʹmenno:"],[1,2,"«Так говорит Кир, царь Персидский: все царства земли дал мне Господь, Бог небесный, и Он повелел мне построить Ему дом в Иерусалиме, что в Иудее.","«Tak govorit Kir, carʹ Persidskij: vse carstva zemli dal mne Gospodʹ, Bog nebesnyj, i On povelel mne postroitʹ Emu dom v Ierusalime, čto v Iudee."],[1,3,"Кто есть из вас, из всего народа Его, – да будет Бог его с ним, – и пусть он идет в Иерусалим, что в Иудее, и строит дом Господа, Бога Израилева, Того Бога, Который в Иерусалиме.","Kto estʹ iz vas, iz vsego naroda Ego, – da budet Bog ego s nim, – i pustʹ on idet v Ierusalim, čto v Iudee, i stroit dom Gospoda, Boga Izraileva, Togo Boga, Kotoryj v Ierusalime."],[1,4,"А все оставшиеся во всех местах, где бы тот ни жил, пусть помогут ему жители места того серебром и золотом и иным имуществом, и скотом, с доброхотным даянием для дома Божия, что в Иерусалиме».","A vse ostavšiesâ vo vseh mestah, gde by tot ni žil, pustʹ pomogut emu žiteli mesta togo serebrom i zolotom i inym imuŝestvom, i skotom, s dobrohotnym daâniem dlâ doma Božiâ, čto v Ierusalime»."],[1,5,"И поднялись главы поколений Иудиных и Вениаминовых, и священники и левиты, всякий, в ком возбудил Бог дух его, чтобы пойти строить дом Господень, который в Иерусалиме.","I podnâlisʹ glavy pokolenij Iudinyh i Veniaminovyh, i svâŝenniki i levity, vsâkij, v kom vozbudil Bog duh ego, čtoby pojti stroitʹ dom Gospodenʹ, kotoryj v Ierusalime."],[1,6,"И все соседи их вспомоществовали им серебряными сосудами, золотом, иным имуществом, и скотом, и дорогими вещами, сверх всякого доброхотного даяния для храма.","I vse sosedi ih vspomoŝestvovali im serebrânymi sosudami, zolotom, inym imuŝestvom, i skotom, i dorogimi veŝami, sverh vsâkogo dobrohotnogo daâniâ dlâ hrama."],[1,7,"И царь Кир вынес сосуды дома Господня, которые Навуходоносор взял из Иерусалима и положил в доме бога своего, –","I carʹ Kir vynes sosudy doma Gospodnâ, kotorye Navuhodonosor vzâl iz Ierusalima i položil v dome boga svoego, –"],[1,8,"и вынес их Кир, царь Персидский, рукою Мифредата сокровищехранителя, а он счетом сдал их Шешбацару, князю Иудину.","i vynes ih Kir, carʹ Persidskij, rukoû Mifredata sokroviŝehranitelâ, a on sčetom sdal ih Šešbacaru, knâzû Iudinu."],[1,9,"И вот число их: блюд золотых тридцать, блюд серебряных тысяча, ножей двадцать девять,","I vot čislo ih: blûd zolotyh tridcatʹ, blûd serebrânyh tysâča, nožej dvadcatʹ devâtʹ,"],[1,10,"чаш золотых тридцать, чаш серебряных двойных четыреста десять, других сосудов тысяча:","čaš zolotyh tridcatʹ, čaš serebrânyh dvojnyh četyresta desâtʹ, drugih sosudov tysâča:"],[1,11,"всех сосудов, золотых и серебряных, пять тысяч четыреста. Все это взял с собою Шешбацар, при отправлении переселенцев из Вавилона в Иерусалим.","vseh sosudov, zolotyh i serebrânyh, pâtʹ tysâč četyresta. Vse éto vzâl s soboû Šešbacar, pri otpravlenii pereselencev iz Vavilona v Ierusalim."],[2,1,"Вот сыны страны из пленников переселения, которых Навуходоносор, царь Вавилонский, отвел в Вавилон, возвратившиеся в Иерусалим и Иудею, каждый в свой город, –","Vot syny strany iz plennikov pereseleniâ, kotoryh Navuhodonosor, carʹ Vavilonskij, otvel v Vavilon, vozvrativšiesâ v Ierusalim i Iudeû, každyj v svoj gorod, –"],[2,2,"пришедшие с Зоровавелем, Иисусом, Неемиею, Сараием, Реелаем, Мардохеем, Билшаном, Мисфаром, Бигваем, Рехумом, Вааном. Число людей народа Израилева:","prišedšie s Zorovavelem, Iisusom, Neemieû, Saraiem, Reelaem, Mardoheem, Bilšanom, Misfarom, Bigvaem, Rehumom, Vaanom. Čislo lûdej naroda Izraileva:"],[2,3,"Сыновей Пароша две тысячи сто семьдесят два;","Synovej Paroša dve tysâči sto semʹdesât dva;"],[2,4,"сыновей Сафатии триста семьдесят два;","synovej Safatii trista semʹdesât dva;"],[2,5,"сыновей Араха семьсот семьдесят пять;","synovej Araha semʹsot semʹdesât pâtʹ;"],[2,6,"сыновей Пахаф-Моава, из сыновей Иисуса [и] Иоава, две тысячи восемьсот двенадцать;","synovej Pahaf-Moava, iz synovej Iisusa [i] Ioava, dve tysâči vosemʹsot dvenadcatʹ;"],[2,7,"сыновей Елама тысяча двести пятьдесят четыре;","synovej Elama tysâča dvesti pâtʹdesât četyre;"],[2,8,"сыновей Заттуя девятьсот сорок пять;","synovej Zattuâ devâtʹsot sorok pâtʹ;"],[2,9,"сыновей Закхая семьсот шестьдесят;","synovej Zakhaâ semʹsot šestʹdesât;"],[2,10,"сыновей Вания шестьсот сорок два;","synovej Vaniâ šestʹsot sorok dva;"],[2,11,"сыновей Бебая шестьсот двадцать три;","synovej Bebaâ šestʹsot dvadcatʹ tri;"],[2,12,"сыновей Азгада тысяча двести двадцать два;","synovej Azgada tysâča dvesti dvadcatʹ dva;"],[2,13,"сыновей Адоникама шестьсот шестьдесят шесть;","synovej Adonikama šestʹsot šestʹdesât šestʹ;"],[2,14,"сыновей Бигвая две тысячи пятьдесят шесть;","synovej Bigvaâ dve tysâči pâtʹdesât šestʹ;"],[2,15,"сыновей Адина четыреста пятьдесят четыре;","synovej Adina četyresta pâtʹdesât četyre;"],[2,16,"сыновей Атера, из дома Езекии, девяносто восемь;","synovej Atera, iz doma Ezekii, devânosto vosemʹ;"],[2,17,"сыновей Бецая триста двадцать три;","synovej Becaâ trista dvadcatʹ tri;"],[2,18,"сыновей Иоры сто двенадцать;","synovej Iory sto dvenadcatʹ;"],[2,19,"сыновей Хашума двести двадцать три;","synovej Hašuma dvesti dvadcatʹ tri;"],[2,20,"сыновей Гиббара девяносто пять;","synovej Gibbara devânosto pâtʹ;"],[2,21,"Уроженцев Вифлеема сто двадцать три;","Urožencev Vifleema sto dvadcatʹ tri;"],[2,22,"жителей Нетофы пятьдесят шесть;","žitelej Netofy pâtʹdesât šestʹ;"],[2,23,"жителей Анафофа сто двадцать восемь;","žitelej Anafofa sto dvadcatʹ vosemʹ;"],[2,24,"уроженцев Азмавефа сорок два;","urožencev Azmavefa sorok dva;"],[2,25,"уроженцев Кириаф-Иарима, Кефиры и Беерофа семьсот сорок три;","urožencev Kiriaf-Iarima, Kefiry i Beerofa semʹsot sorok tri;"],[2,26,"уроженцев Рамы и Гевы шестьсот двадцать один;","urožencev Ramy i Gevy šestʹsot dvadcatʹ odin;"],[2,27,"жителей Михмаса сто двадцать два;","žitelej Mihmasa sto dvadcatʹ dva;"],[2,28,"жителей Вефиля и Гая двести двадцать три;","žitelej Vefilâ i Gaâ dvesti dvadcatʹ tri;"],[2,29,"уроженцев Нево пятьдесят два;","urožencev Nevo pâtʹdesât dva;"],[2,30,"уроженцев Магбиша сто пятьдесят шесть;","urožencev Magbiša sto pâtʹdesât šestʹ;"],[2,31,"сыновей другого Елама тысяча двести пятьдесят четыре;","synovej drugogo Elama tysâča dvesti pâtʹdesât četyre;"],[2,32,"сыновей Харима триста двадцать;","synovej Harima trista dvadcatʹ;"],[2,33,"уроженцев Лидды, Хадида и Оно семьсот двадцать пять;","urožencev Liddy, Hadida i Ono semʹsot dvadcatʹ pâtʹ;"],[2,34,"уроженцев Иерихона триста сорок пять;","urožencev Ierihona trista sorok pâtʹ;"],[2,35,"уроженцев Сенаи три тысячи шестьсот тридцать.","urožencev Senai tri tysâči šestʹsot tridcatʹ."],[2,36,"Священников: сыновей Иедаии, из дома Иисусова, девятьсот семьдесят три;","Svâŝennikov: synovej Iedaii, iz doma Iisusova, devâtʹsot semʹdesât tri;"],[2,37,"сыновей Иммера тысяча пятьдесят два;","synovej Immera tysâča pâtʹdesât dva;"],[2,38,"сыновей Пашхура тысяча двести сорок семь;","synovej Pašhura tysâča dvesti sorok semʹ;"],[2,39,"сыновей Харима тысяча семнадцать.","synovej Harima tysâča semnadcatʹ."],[2,40,"Левитов: сыновей Иисуса и Кадмиила, из сыновей Годавии, семьдесят четыре;","Levitov: synovej Iisusa i Kadmiila, iz synovej Godavii, semʹdesât četyre;"],[2,41,"певцов: сыновей Асафа сто двадцать восемь;","pevcov: synovej Asafa sto dvadcatʹ vosemʹ;"],[2,42,"сыновей привратников: сыновья Шаллума, сыновья Атера, сыновья Талмона, сыновья Аккува, сыновья Хатиты, сыновья Шовая, – всего сто тридцать девять.","synovej privratnikov: synovʹâ Šalluma, synovʹâ Atera, synovʹâ Talmona, synovʹâ Akkuva, synovʹâ Hatity, synovʹâ Šovaâ, – vsego sto tridcatʹ devâtʹ."],[2,43,"Нефинеев: сыновья Цихи, сыновья Хасуфы, сыновья Таббаофа,","Nefineev: synovʹâ Cihi, synovʹâ Hasufy, synovʹâ Tabbaofa,"],[2,44,"сыновья Кероса, сыновья Сиаги, сыновья Фадона,","synovʹâ Kerosa, synovʹâ Siagi, synovʹâ Fadona,"],[2,45,"сыновья Лебаны, сыновья Хагабы, сыновья Аккува,","synovʹâ Lebany, synovʹâ Hagaby, synovʹâ Akkuva,"],[2,46,"сыновья Хагава, сыновья Шамлая, сыновья Ханана,","synovʹâ Hagava, synovʹâ Šamlaâ, synovʹâ Hanana,"],[2,47,"сыновья Гиддела, сыновья Гахара, сыновья Реаии,","synovʹâ Giddela, synovʹâ Gahara, synovʹâ Reaii,"],[2,48,"сыновья Рецина, сыновья Некоды, сыновья Газзама,","synovʹâ Recina, synovʹâ Nekody, synovʹâ Gazzama,"],[2,49,"сыновья Уззы, сыновья Пасеаха, сыновья Бесая,","synovʹâ Uzzy, synovʹâ Paseaha, synovʹâ Besaâ,"],[2,50,"сыновья Асны, сыновья Меунима, сыновья Нефисима,","synovʹâ Asny, synovʹâ Meunima, synovʹâ Nefisima,"],[2,51,"сыновья Бакбука, сыновья Хакуфы, сыновья Хархура,","synovʹâ Bakbuka, synovʹâ Hakufy, synovʹâ Harhura,"],[2,52,"сыновья Бацлуфа, сыновья Мехиды, сыновья Харши,","synovʹâ Baclufa, synovʹâ Mehidy, synovʹâ Harši,"],[2,53,"сыновья Баркоса, сыновья Сисры, сыновья Фамаха,","synovʹâ Barkosa, synovʹâ Sisry, synovʹâ Famaha,"],[2,54,"сыновья Нециаха, сыновья Хатифы;","synovʹâ Neciaha, synovʹâ Hatify;"],[2,55,"сыновья рабов Соломоновых: сыновья Сотая, сыновья Гассоферефа, сыновья Феруды,","synovʹâ rabov Solomonovyh: synovʹâ Sotaâ, synovʹâ Gassoferefa, synovʹâ Ferudy,"],[2,56,"сыновья Иаалы, сыновья Даркона, сыновья Гиддела,","synovʹâ Iaaly, synovʹâ Darkona, synovʹâ Giddela,"],[2,57,"сыновья Сефатии, сыновья Хаттила, сыновья Похереф-Гаццебайима, сыновья Амия, –","synovʹâ Sefatii, synovʹâ Hattila, synovʹâ Poheref-Gaccebajima, synovʹâ Amiâ, –"],[2,58,"всего – нефинеев и сыновей рабов Соломоновых триста девяносто два.","vsego – nefineev i synovej rabov Solomonovyh trista devânosto dva."],[2,59,"И вот вышедшие из Тел-Мелаха, Тел-Харши, Херуб-Аддан-Иммера, которые не могли показать о поколении своем и о племени своем – от Израиля ли они:","I vot vyšedšie iz Tel-Melaha, Tel-Harši, Herub-Addan-Immera, kotorye ne mogli pokazatʹ o pokolenii svoem i o plemeni svoem – ot Izrailâ li oni:"],[2,60,"сыновья Делайи, сыновья Товии, сыновья Некоды, шестьсот пятьдесят два.","synovʹâ Delaji, synovʹâ Tovii, synovʹâ Nekody, šestʹsot pâtʹdesât dva."],[2,61,"И из сыновей священнических: сыновья Хабайи, сыновья Гаккоца, сыновья Верзеллия, который взял жену из дочерей Верзеллия Галаадитянина и стал называться именем их.","I iz synovej svâŝenničeskih: synovʹâ Habaji, synovʹâ Gakkoca, synovʹâ Verzelliâ, kotoryj vzâl ženu iz dočerej Verzelliâ Galaaditânina i stal nazyvatʹsâ imenem ih."],[2,62,"Они искали своей записи родословной, и не нашлось ее, а потому исключены из священства.","Oni iskali svoej zapisi rodoslovnoj, i ne našlosʹ ee, a potomu isklûčeny iz svâŝenstva."],[2,63,"И Тиршафа сказал им, чтоб они не ели великой святыни, доколе не восстанет священник с уримом и туммимом.","I Tiršafa skazal im, čtob oni ne eli velikoj svâtyni, dokole ne vosstanet svâŝennik s urimom i tummimom."],[2,64,"Все общество вместе состояло из сорока двух тысяч трехсот шестидесяти человек,","Vse obŝestvo vmeste sostoâlo iz soroka dvuh tysâč trehsot šestidesâti čelovek,"],[2,65,"кроме рабов их и рабынь их, которых было семь тысяч триста тридцать семь; и при них певцов и певиц двести.","krome rabov ih i rabynʹ ih, kotoryh bylo semʹ tysâč trista tridcatʹ semʹ; i pri nih pevcov i pevic dvesti."],[2,66,"Коней у них семьсот тридцать шесть, лошаков у них двести сорок пять;","Konej u nih semʹsot tridcatʹ šestʹ, lošakov u nih dvesti sorok pâtʹ;"],[2,67,"верблюдов у них четыреста тридцать пять, ослов шесть тысяч семьсот двадцать.","verblûdov u nih četyresta tridcatʹ pâtʹ, oslov šestʹ tysâč semʹsot dvadcatʹ."],[2,68,"Из глав поколений некоторые, придя к дому Господню, что в Иерусалиме, доброхотно жертвовали на дом Божий, чтобы восстановить его на основании его.","Iz glav pokolenij nekotorye, pridâ k domu Gospodnû, čto v Ierusalime, dobrohotno žertvovali na dom Božij, čtoby vosstanovitʹ ego na osnovanii ego."],[2,69,"По достатку своему, они дали в сокровищницу на производство работ шестьдесят одну тысячу драхм золота и пять тысяч мин серебра и сто священнических одежд.","Po dostatku svoemu, oni dali v sokroviŝnicu na proizvodstvo rabot šestʹdesât odnu tysâču drahm zolota i pâtʹ tysâč min serebra i sto svâŝenničeskih odežd."],[2,70,"И стали жить священники и левиты, и народ и певцы, и привратники и нефинеи в городах своих, и весь Израиль в городах своих.","I stali žitʹ svâŝenniki i levity, i narod i pevcy, i privratniki i nefinei v gorodah svoih, i vesʹ Izrailʹ v gorodah svoih."],[3,1,"Когда наступил седьмой месяц, и сыны Израилевы уже были в городах, тогда собрался народ, как один человек, в Иерусалиме.","Kogda nastupil sedʹmoj mesâc, i syny Izrailevy uže byli v gorodah, togda sobralsâ narod, kak odin čelovek, v Ierusalime."],[3,2,"И встал Иисус, сын Иоседеков, и братья его священники, и Зоровавель, сын Салафиилов, и братья его, и соорудили они жертвенник Богу Израилеву, чтобы возносить на нем всесожжения, как написано в законе Моисея, человека Божия.","I vstal Iisus, syn Iosedekov, i bratʹâ ego svâŝenniki, i Zorovavelʹ, syn Salafiilov, i bratʹâ ego, i soorudili oni žertvennik Bogu Izrailevu, čtoby voznositʹ na nem vsesožženiâ, kak napisano v zakone Moiseâ, čeloveka Božiâ."],[3,3,"И поставили жертвенник на основании его, так как они были в страхе от иноземных народов; и стали возносить на нем всесожжения Господу, всесожжения утренние и вечерние.","I postavili žertvennik na osnovanii ego, tak kak oni byli v strahe ot inozemnyh narodov; i stali voznositʹ na nem vsesožženiâ Gospodu, vsesožženiâ utrennie i večernie."],[3,4,"И совершили праздник кущей, как предписано, с ежедневным всесожжением в определенном числе, по уставу каждого дня.","I soveršili prazdnik kuŝej, kak predpisano, s ežednevnym vsesožženiem v opredelennom čisle, po ustavu každogo dnâ."],[3,5,"И после того совершали всесожжение постоянное, и в новомесячия, и во все праздники, посвященные Господу, и добровольное приношение Господу от всякого усердствующего.","I posle togo soveršali vsesožženie postoânnoe, i v novomesâčiâ, i vo vse prazdniki, posvâŝennye Gospodu, i dobrovolʹnoe prinošenie Gospodu ot vsâkogo userdstvuûŝego."],[3,6,"С первого же дня седьмого месяца начали возносить всесожжения Господу. А храму Господню еще не было положено основание.","S pervogo že dnâ sedʹmogo mesâca načali voznositʹ vsesožženiâ Gospodu. A hramu Gospodnû eŝe ne bylo položeno osnovanie."],[3,7,"И стали выдавать серебро каменотесам и плотникам, и пищу и питье и масло Сидонянам и Тирянам, чтоб они доставляли кедровый лес с Ливана по морю в Яфу, с дозволения им Кира, царя Персидского.","I stali vydavatʹ serebro kamenotesam i plotnikam, i piŝu i pitʹe i maslo Sidonânam i Tirânam, čtob oni dostavlâli kedrovyj les s Livana po morû v Âfu, s dozvoleniâ im Kira, carâ Persidskogo."],[3,8,"Во второй год по приходе своем к дому Божию в Иерусалим, во второй месяц, Зоровавель, сын Салафиилов, и Иисус, сын Иоседеков, и прочие братья их, священники и левиты, и все пришедшие из плена в Иерусалим положили начало и поставили левитов от двадцати лет и выше для надзора за работами дома Господня.","Vo vtoroj god po prihode svoem k domu Božiû v Ierusalim, vo vtoroj mesâc, Zorovavelʹ, syn Salafiilov, i Iisus, syn Iosedekov, i pročie bratʹâ ih, svâŝenniki i levity, i vse prišedšie iz plena v Ierusalim položili načalo i postavili levitov ot dvadcati let i vyše dlâ nadzora za rabotami doma Gospodnâ."],[3,9,"И стали Иисус, сыновья его и братья его, Кадмиил и сыновья его, сыновья Иуды, как один человек, для надзора за производителями работ в доме Божием, а также и сыновья Хенадада, сыновья их и братья их левиты.","I stali Iisus, synovʹâ ego i bratʹâ ego, Kadmiil i synovʹâ ego, synovʹâ Iudy, kak odin čelovek, dlâ nadzora za proizvoditelâmi rabot v dome Božiem, a takže i synovʹâ Henadada, synovʹâ ih i bratʹâ ih levity."],[3,10,"Когда строители положили основание храму Господню, тогда поставили священников в облачении их с трубами и левитов, сыновей Асафовых, с кимвалами, чтобы славить Господа по уставу Давида, царя Израилева.","Kogda stroiteli položili osnovanie hramu Gospodnû, togda postavili svâŝennikov v oblačenii ih s trubami i levitov, synovej Asafovyh, s kimvalami, čtoby slavitʹ Gospoda po ustavu Davida, carâ Izraileva."],[3,11,"И начали они попеременно петь: «хвалите» и: «славьте Господа», «ибо – благ, ибо вовек милость Его к Израилю». И весь народ восклицал громогласно, славя Господа за то, что положено основание дома Господня.","I načali oni poperemenno petʹ: «hvalite» i: «slavʹte Gospoda», «ibo – blag, ibo vovek milostʹ Ego k Izrailû». I vesʹ narod vosklical gromoglasno, slavâ Gospoda za to, čto položeno osnovanie doma Gospodnâ."],[3,12,"Впрочем, многие из священников и левитов и глав поколений, старики, которые видели прежний храм, при основании этого храма пред глазами их, плакали громко, но многие и восклицали от радости громогласно.","Vpročem, mnogie iz svâŝennikov i levitov i glav pokolenij, stariki, kotorye videli prežnij hram, pri osnovanii étogo hrama pred glazami ih, plakali gromko, no mnogie i vosklicali ot radosti gromoglasno."],[3,13,"И не мог народ распознать восклицаний радости от воплей плача народного, потому что народ восклицал громко, и голос слышен был далеко.","I ne mog narod raspoznatʹ vosklicanij radosti ot voplej plača narodnogo, potomu čto narod vosklical gromko, i golos slyšen byl daleko."],[4,1,"И услышали враги Иуды и Вениамина, что возвратившиеся из плена строят храм Господу, Богу Израилеву;","I uslyšali vragi Iudy i Veniamina, čto vozvrativšiesâ iz plena stroât hram Gospodu, Bogu Izrailevu;"],[4,2,"и пришли они к Зоровавелю и к главам поколений, и сказали им: будем и мы строить с вами, потому что мы, как и вы, прибегаем к Богу вашему, и Ему приносим жертвы от дней Асардана, царя Сирийского, который перевел нас сюда.","i prišli oni k Zorovavelû i k glavam pokolenij, i skazali im: budem i my stroitʹ s vami, potomu čto my, kak i vy, pribegaem k Bogu vašemu, i Emu prinosim žertvy ot dnej Asardana, carâ Sirijskogo, kotoryj perevel nas sûda."],[4,3,"И сказал им Зоровавель и Иисус и прочие главы поколений Израильских: не строить вам вместе с нами дом нашему Богу; мы одни будем строить дом Господу, Богу Израилеву, как повелел нам царь Кир, царь Персидский.","I skazal im Zorovavelʹ i Iisus i pročie glavy pokolenij Izrailʹskih: ne stroitʹ vam vmeste s nami dom našemu Bogu; my odni budem stroitʹ dom Gospodu, Bogu Izrailevu, kak povelel nam carʹ Kir, carʹ Persidskij."],[4,4,"И стал народ земли той ослаблять руки народа Иудейского и препятствовать ему в строении;","I stal narod zemli toj oslablâtʹ ruki naroda Iudejskogo i prepâtstvovatʹ emu v stroenii;"],[4,5,"и подкупали против них советников, чтобы разрушить предприятие их, во все дни Кира, царя Персидского, и до царствования Дария, царя Персидского.","i podkupali protiv nih sovetnikov, čtoby razrušitʹ predpriâtie ih, vo vse dni Kira, carâ Persidskogo, i do carstvovaniâ Dariâ, carâ Persidskogo."],[4,6,"А в царствование Ахашвероша, в начале царствования его, написали обвинение на жителей Иудеи и Иерусалима.","A v carstvovanie Ahašveroša, v načale carstvovaniâ ego, napisali obvinenie na žitelej Iudei i Ierusalima."],[4,7,"И во дни Артаксеркса писали Бишлам, Мифредат, Табеел и прочие товарищи их к Артаксерксу, царю Персидскому. Письмо же написано было буквами Сирийскими и на Сирийском языке.","I vo dni Artakserksa pisali Bišlam, Mifredat, Tabeel i pročie tovariŝi ih k Artakserksu, carû Persidskomu. Pisʹmo že napisano bylo bukvami Sirijskimi i na Sirijskom âzyke."],[4,8,"Рехум советник и Шимшай писец писали одно письмо против Иерусалима к царю Артаксерксу такое:","Rehum sovetnik i Šimšaj pisec pisali odno pisʹmo protiv Ierusalima k carû Artakserksu takoe:"],[4,9,"«Тогда-то. Рехум советник и Шимшай писец и прочие товарищи их, – Динеи и Афарсафхеи, Тарпелеи, Апарсы, Арехьяне, Вавилоняне, Сусанцы, Даги, Еламитяне,","«Togda-to. Rehum sovetnik i Šimšaj pisec i pročie tovariŝi ih, – Dinei i Afarsafhei, Tarpelei, Aparsy, Arehʹâne, Vavilonâne, Susancy, Dagi, Elamitâne,"],[4,10,"и прочие народы, которых переселил Аснафар [Сеннахирим] великий и славный и поселил в городах Самарийских и в прочих городах за рекою», и прочее.","i pročie narody, kotoryh pereselil Asnafar [Sennahirim] velikij i slavnyj i poselil v gorodah Samarijskih i v pročih gorodah za rekoû», i pročee."],[4,11,"И вот список с письма, которое послали к нему: «Царю Артаксерксу – рабы твои, люди, живущие за рекою», и прочее.","I vot spisok s pisʹma, kotoroe poslali k nemu: «Carû Artakserksu – raby tvoi, lûdi, živuŝie za rekoû», i pročee."],[4,12,"«Да будет известно царю, что Иудеи, которые вышли от тебя, пришли к нам в Иерусалим, строят этот мятежный и негодный город, и стены делают, и основания их уже исправили.","«Da budet izvestno carû, čto Iudei, kotorye vyšli ot tebâ, prišli k nam v Ierusalim, stroât étot mâtežnyj i negodnyj gorod, i steny delaût, i osnovaniâ ih uže ispravili."],[4,13,"Да будет же известно царю, что если этот город будет построен и стены восстановлены, то ни подати, ни налога, ни пошлины не будут давать, и царской казне сделан будет ущерб.","Da budet že izvestno carû, čto esli étot gorod budet postroen i steny vosstanovleny, to ni podati, ni naloga, ni pošliny ne budut davatʹ, i carskoj kazne sdelan budet uŝerb."],[4,14,"Так как мы едим соль от дворца царского, и ущерб для царя не можем видеть, поэтому мы посылаем донесение к царю:","Tak kak my edim solʹ ot dvorca carskogo, i uŝerb dlâ carâ ne možem videtʹ, poétomu my posylaem donesenie k carû:"],[4,15,"пусть поищут в памятной книге отцов твоих, – и найдешь в книге памятной, и узнаешь, что город сей – город мятежный и вредный для царей и областей, и что отпадения бывали в нем издавна, за что город сей и опустошен.","pustʹ poiŝut v pamâtnoj knige otcov tvoih, – i najdešʹ v knige pamâtnoj, i uznaešʹ, čto gorod sej – gorod mâtežnyj i vrednyj dlâ carej i oblastej, i čto otpadeniâ byvali v nem izdavna, za čto gorod sej i opustošen."],[4,16,"Посему мы уведомляем царя, что если город сей будет достроен и стены его доделаны, то после этого не будет у тебя владения за рекою».","Posemu my uvedomlâem carâ, čto esli gorod sej budet dostroen i steny ego dodelany, to posle étogo ne budet u tebâ vladeniâ za rekoû»."],[4,17,"Царь послал ответ Рехуму советнику и Шимшаю писцу и прочим товарищам их, которые живут в Самарии и в прочих городах заречных: «Мир...» и прочее.","Carʹ poslal otvet Rehumu sovetniku i Šimšaû piscu i pročim tovariŝam ih, kotorye živut v Samarii i v pročih gorodah zarečnyh: «Mir...» i pročee."],[4,18,"«Письмо, которое вы прислали нам, внятно прочитано предо мною;","«Pisʹmo, kotoroe vy prislali nam, vnâtno pročitano predo mnoû;"],[4,19,"и от меня дано повеление, – и разыскивали, и нашли, что город этот издавна восставал против царей, и производились в нем мятежи и волнения,","i ot menâ dano povelenie, – i razyskivali, i našli, čto gorod étot izdavna vosstaval protiv carej, i proizvodilisʹ v nem mâteži i volneniâ,"],[4,20,"и что были в Иерусалиме цари могущественные и владевшие всем заречьем, и им давали подать, налоги и пошлины.","i čto byli v Ierusalime cari moguŝestvennye i vladevšie vsem zarečʹem, i im davali podatʹ, nalogi i pošliny."],[4,21,"Итак, дайте приказание, чтобы люди сии перестали работать, и чтобы город сей не строился, доколе от меня не будет дано повеление.","Itak, dajte prikazanie, čtoby lûdi sii perestali rabotatʹ, i čtoby gorod sej ne stroilsâ, dokole ot menâ ne budet dano povelenie."],[4,22,"И будьте осторожны, чтобы не сделать в этом недосмотра. К чему допускать размножение вредного в ущерб царям?»","I budʹte ostorožny, čtoby ne sdelatʹ v étom nedosmotra. K čemu dopuskatʹ razmnoženie vrednogo v uŝerb carâm?»"],[4,23,"Как скоро это письмо царя Артаксеркса было прочитано пред Рехумом и Шимшаем писцом и товарищами их, они немедленно пошли в Иерусалим к Иудеям, и сильною вооруженною рукою остановили работу их.","Kak skoro éto pisʹmo carâ Artakserksa bylo pročitano pred Rehumom i Šimšaem piscom i tovariŝami ih, oni nemedlenno pošli v Ierusalim k Iudeâm, i silʹnoû vooružennoû rukoû ostanovili rabotu ih."],[4,24,"Тогда остановилась работа при доме Божием, который в Иерусалиме, и остановка сия продолжалась до второго года царствования Дария, царя Персидского.","Togda ostanovilasʹ rabota pri dome Božiem, kotoryj v Ierusalime, i ostanovka siâ prodolžalasʹ do vtorogo goda carstvovaniâ Dariâ, carâ Persidskogo."],[5,1,"Но пророк Аггей и пророк Захария, сын Адды, говорили Иудеям, которые в Иудее и Иерусалиме, пророческие речи во имя Бога Израилева.","No prorok Aggej i prorok Zahariâ, syn Addy, govorili Iudeâm, kotorye v Iudee i Ierusalime, proročeskie reči vo imâ Boga Izraileva."],[5,2,"Тогда встали Зоровавель, сын Салафиилов, и Иисус, сын Иоседеков, и начали строить дом Божий в Иерусалиме, и с ними пророки Божии, подкреплявшие их.","Togda vstali Zorovavelʹ, syn Salafiilov, i Iisus, syn Iosedekov, i načali stroitʹ dom Božij v Ierusalime, i s nimi proroki Božii, podkreplâvšie ih."],[5,3,"В то время пришел к ним Фафнай, заречный областеначальник, и Шефар-Бознай и товарищи их, и так сказали им: кто дал вам разрешение строить дом сей и доделывать стены сии?","V to vremâ prišel k nim Fafnaj, zarečnyj oblastenačalʹnik, i Šefar-Boznaj i tovariŝi ih, i tak skazali im: kto dal vam razrešenie stroitʹ dom sej i dodelyvatʹ steny sii?"],[5,4,"Тогда мы сказали им имена тех людей, которые строят это здание.","Togda my skazali im imena teh lûdej, kotorye stroât éto zdanie."],[5,5,"Но око Бога их было над старейшинами Иудейскими, и те не возбраняли им, доколе дело не отправили к Дарию, и доколе не пришло решение по этому делу.","No oko Boga ih bylo nad starejšinami Iudejskimi, i te ne vozbranâli im, dokole delo ne otpravili k Dariû, i dokole ne prišlo rešenie po étomu delu."],[5,6,"Вот содержание письма, которое послал Фафнай, заречный областеначальник, и Шефар-Бознай с товарищами своими Афарсахеями, которые за рекою, к царю Дарию.","Vot soderžanie pisʹma, kotoroe poslal Fafnaj, zarečnyj oblastenačalʹnik, i Šefar-Boznaj s tovariŝami svoimi Afarsaheâmi, kotorye za rekoû, k carû Dariû."],[5,7,"В донесении, которое они послали к нему, вот что написано: «Дарию царю – всякий мир!","V donesenii, kotoroe oni poslali k nemu, vot čto napisano: «Dariû carû – vsâkij mir!"],[5,8,"Да будет известно царю, что мы ходили в Иудейскую область, к дому Бога великого; и строится он из больших камней, и дерево вкладывается в стены; и работа сия производится быстро и с успехом идет в руках их.","Da budet izvestno carû, čto my hodili v Iudejskuû oblastʹ, k domu Boga velikogo; i stroitsâ on iz bolʹših kamnej, i derevo vkladyvaetsâ v steny; i rabota siâ proizvoditsâ bystro i s uspehom idet v rukah ih."],[5,9,"Тогда мы спросили у старейшин тех и так сказали им: кто дал вам разрешение строить дом сей и стены сии доделывать?","Togda my sprosili u starejšin teh i tak skazali im: kto dal vam razrešenie stroitʹ dom sej i steny sii dodelyvatʹ?"],[5,10,"И сверх того об именах их мы спросили их, чтобы дать знать тебе и написать имена тех людей, которые главными у них.","I sverh togo ob imenah ih my sprosili ih, čtoby datʹ znatʹ tebe i napisatʹ imena teh lûdej, kotorye glavnymi u nih."],[5,11,"И они ответили нам такими словами: мы рабы Бога неба и земли и строим дом, который был построен за много лет прежде сего, – и великий царь у Израиля строил его и довершил его.","I oni otvetili nam takimi slovami: my raby Boga neba i zemli i stroim dom, kotoryj byl postroen za mnogo let prežde sego, – i velikij carʹ u Izrailâ stroil ego i doveršil ego."],[5,12,"Когда же отцы наши прогневали Бога небесного, Он предал их в руку Навуходоносора, царя Вавилонского, Халдеянина; и дом сей он разрушил, и народ переселил в Вавилон.","Kogda že otcy naši prognevali Boga nebesnogo, On predal ih v ruku Navuhodonosora, carâ Vavilonskogo, Haldeânina; i dom sej on razrušil, i narod pereselil v Vavilon."],[5,13,"Но в первый год Кира, царя Вавилонского, царь Кир дал разрешение построить сей дом Божий;","No v pervyj god Kira, carâ Vavilonskogo, carʹ Kir dal razrešenie postroitʹ sej dom Božij;"],[5,14,"да и сосуды дома Божия, золотые и серебряные, которые Навуходоносор вынес из храма Иерусалимского и отнес в храм Вавилонский, – вынес Кир царь из храма Вавилонского; и отдали их по имени Шешбацару, которого он назначил областеначальником,","da i sosudy doma Božiâ, zolotye i serebrânye, kotorye Navuhodonosor vynes iz hrama Ierusalimskogo i otnes v hram Vavilonskij, – vynes Kir carʹ iz hrama Vavilonskogo; i otdali ih po imeni Šešbacaru, kotorogo on naznačil oblastenačalʹnikom,"],[5,15,"и сказал ему: возьми сии сосуды, пойди и отнеси их в храм Иерусалимский, и пусть дом Божий строится на своем месте.","i skazal emu: vozʹmi sii sosudy, pojdi i otnesi ih v hram Ierusalimskij, i pustʹ dom Božij stroitsâ na svoem meste."],[5,16,"Тогда Шешбацар тот пришел, положил основания дома Божия в Иерусалиме; и с тех пор доселе он строится, и еще не кончен.","Togda Šešbacar tot prišel, položil osnovaniâ doma Božiâ v Ierusalime; i s teh por dosele on stroitsâ, i eŝe ne končen."],[5,17,"Итак, если царю благоугодно, пусть поищут в доме царских сокровищ, там, в Вавилоне, точно ли царем Киром дано разрешение строить сей дом Божий в Иерусалиме, и царскую волю о сем пусть пришлют к нам».","Itak, esli carû blagougodno, pustʹ poiŝut v dome carskih sokroviŝ, tam, v Vavilone, točno li carem Kirom dano razrešenie stroitʹ sej dom Božij v Ierusalime, i carskuû volû o sem pustʹ prišlût k nam»."],[6,1,"Тогда царь Дарий дал повеление, и разыскивали в Вавилоне в книгохранилище, куда полагали сокровища.","Togda carʹ Darij dal povelenie, i razyskivali v Vavilone v knigohraniliŝe, kuda polagali sokroviŝa."],[6,2,"И найден в Екбатане во дворце, который в области Мидии, один свиток, и в нем написано так: «Для памяти:","I najden v Ekbatane vo dvorce, kotoryj v oblasti Midii, odin svitok, i v nem napisano tak: «Dlâ pamâti:"],[6,3,"в первый год царя Кира царь Кир дал повеление о доме Божием в Иерусалиме: пусть строится дом на том месте, где приносят жертвы, и пусть будут положены прочные основания для него; вышина его в шестьдесят локтей, ширина его в шестьдесят локтей;","v pervyj god carâ Kira carʹ Kir dal povelenie o dome Božiem v Ierusalime: pustʹ stroitsâ dom na tom meste, gde prinosât žertvy, i pustʹ budut položeny pročnye osnovaniâ dlâ nego; vyšina ego v šestʹdesât loktej, širina ego v šestʹdesât loktej;"],[6,4,"рядов из камней больших три, и ряд из дерева один; издержки же пусть выдаются из царского дома.","râdov iz kamnej bolʹših tri, i râd iz dereva odin; izderžki že pustʹ vydaûtsâ iz carskogo doma."],[6,5,"Да и сосуды дома Божия, золотые и серебряные, которые Навуходоносор вынес из храма Иерусалимского и отнес в Вавилон, пусть возвратятся и пойдут в храм Иерусалимский, каждый на место свое, и помещены будут в доме Божием.","Da i sosudy doma Božiâ, zolotye i serebrânye, kotorye Navuhodonosor vynes iz hrama Ierusalimskogo i otnes v Vavilon, pustʹ vozvratâtsâ i pojdut v hram Ierusalimskij, každyj na mesto svoe, i pomeŝeny budut v dome Božiem."],[6,6,"Итак, Фафнай, заречный областеначальник, и Шефар-Бознай, с товарищами вашими Афарсахеями, которые за рекою, – удалитесь оттуда.","Itak, Fafnaj, zarečnyj oblastenačalʹnik, i Šefar-Boznaj, s tovariŝami vašimi Afarsaheâmi, kotorye za rekoû, – udalitesʹ ottuda."],[6,7,"Не останавливайте работы при сем доме Божием; пусть Иудейский областеначальник и Иудейские старейшины строят сей дом Божий на месте его.","Ne ostanavlivajte raboty pri sem dome Božiem; pustʹ Iudejskij oblastenačalʹnik i Iudejskie starejšiny stroât sej dom Božij na meste ego."],[6,8,"И от меня дается повеление о том, чем вы должны содействовать старейшинам тем Иудейским в построении того дома Божия, и именно: из имущества царского – из заречной подати – немедленно берите и давайте тем людям, чтобы работа не останавливалась;","I ot menâ daetsâ povelenie o tom, čem vy dolžny sodejstvovatʹ starejšinam tem Iudejskim v postroenii togo doma Božiâ, i imenno: iz imuŝestva carskogo – iz zarečnoj podati – nemedlenno berite i davajte tem lûdâm, čtoby rabota ne ostanavlivalasʹ;"],[6,9,"и сколько нужно – тельцов ли, или овнов и агнцев, на всесожжения Богу небесному, также пшеницы, соли, вина и масла, как скажут священники Иерусалимские, пусть будет выдаваемо им изо дня в день без задержки,","i skolʹko nužno – telʹcov li, ili ovnov i agncev, na vsesožženiâ Bogu nebesnomu, takže pšenicy, soli, vina i masla, kak skažut svâŝenniki Ierusalimskie, pustʹ budet vydavaemo im izo dnâ v denʹ bez zaderžki,"],[6,10,"чтоб они приносили жертву, приятную Богу небесному, и молились о жизни царя и сыновей его.","čtob oni prinosili žertvu, priâtnuû Bogu nebesnomu, i molilisʹ o žizni carâ i synovej ego."],[6,11,"Мною же дается повеление, что если какой человек изменит это определение, то будет вынуто бревно из дома его, и будет поднят он и пригвожден к нему, а дом его за то будет обращен в развалины.","Mnoû že daetsâ povelenie, čto esli kakoj čelovek izmenit éto opredelenie, to budet vynuto brevno iz doma ego, i budet podnât on i prigvožden k nemu, a dom ego za to budet obraŝen v razvaliny."],[6,12,"И Бог, Которого имя там обитает, да низложит всякого царя и народ, который простер бы руку свою, чтобы изменить сие ко вреду этого дома Божия в Иерусалиме. Я, Дарий, дал это повеление; да будет оно в точности исполняемо».","I Bog, Kotorogo imâ tam obitaet, da nizložit vsâkogo carâ i narod, kotoryj proster by ruku svoû, čtoby izmenitʹ sie ko vredu étogo doma Božiâ v Ierusalime. Â, Darij, dal éto povelenie; da budet ono v točnosti ispolnâemo»."],[6,13,"Тогда Фафнай, заречный областеначальник, Шефар-Бознай и товарищи их, – как повелел царь Дарий, так в точности и делали.","Togda Fafnaj, zarečnyj oblastenačalʹnik, Šefar-Boznaj i tovariŝi ih, – kak povelel carʹ Darij, tak v točnosti i delali."],[6,14,"И старейшины Иудейские строили и преуспевали, по пророчеству Аггея пророка и Захарии, сына Адды. И построили и окончили, по воле Бога Израилева и по воле Кира и Дария и Артаксеркса, царей Персидских.","I starejšiny Iudejskie stroili i preuspevali, po proročestvu Aggeâ proroka i Zaharii, syna Addy. I postroili i okončili, po vole Boga Izraileva i po vole Kira i Dariâ i Artakserksa, carej Persidskih."],[6,15,"И окончен дом сей к третьему дню месяца Адара, в шестой год царствования царя Дария.","I okončen dom sej k tretʹemu dnû mesâca Adara, v šestoj god carstvovaniâ carâ Dariâ."],[6,16,"И совершили сыны Израилевы, священники и левиты и прочие, возвратившиеся из плена, освящение сего дома Божия с радостью.","I soveršili syny Izrailevy, svâŝenniki i levity i pročie, vozvrativšiesâ iz plena, osvâŝenie sego doma Božiâ s radostʹû."],[6,17,"И принесли при освящении сего дома Божия: сто волов, двести овнов, четыреста агнцев и двенадцать козлов в жертву за грех за всего Израиля, по числу колен Израилевых.","I prinesli pri osvâŝenii sego doma Božiâ: sto volov, dvesti ovnov, četyresta agncev i dvenadcatʹ kozlov v žertvu za greh za vsego Izrailâ, po čislu kolen Izrailevyh."],[6,18,"И поставили священников по отделениям их, и левитов по чередам их на службу Божию в Иерусалиме, как предписано в книге Моисея.","I postavili svâŝennikov po otdeleniâm ih, i levitov po čeredam ih na službu Božiû v Ierusalime, kak predpisano v knige Moiseâ."],[6,19,"И совершили возвратившиеся из плена пасху в четырнадцатый день первого месяца,","I soveršili vozvrativšiesâ iz plena pashu v četyrnadcatyj denʹ pervogo mesâca,"],[6,20,"потому что очистились священники и левиты, – все они, как один, были чисты; и закололи агнцев пасхальных для всех, возвратившихся из плена, для братьев своих священников и для себя.","potomu čto očistilisʹ svâŝenniki i levity, – vse oni, kak odin, byli čisty; i zakololi agncev pashalʹnyh dlâ vseh, vozvrativšihsâ iz plena, dlâ bratʹev svoih svâŝennikov i dlâ sebâ."],[6,21,"И ели сыны Израилевы, возвратившиеся из переселения, и все отделившиеся к ним от нечистоты народов земли, чтобы прибегать к Господу, Богу Израилеву.","I eli syny Izrailevy, vozvrativšiesâ iz pereseleniâ, i vse otdelivšiesâ k nim ot nečistoty narodov zemli, čtoby pribegatʹ k Gospodu, Bogu Izrailevu."],[6,22,"И праздновали праздник опресноков семь дней в радости, потому что обрадовал их Господь и обратил к ним сердце царя Ассирийского, чтобы подкреплять руки их при строении дома Господа, Бога Израилева.","I prazdnovali prazdnik opresnokov semʹ dnej v radosti, potomu čto obradoval ih Gospodʹ i obratil k nim serdce carâ Assirijskogo, čtoby podkreplâtʹ ruki ih pri stroenii doma Gospoda, Boga Izraileva."],[7,1,"После сих происшествий, в царствование Артаксеркса, царя Персидского, Ездра, сын Сераии, сын Азарии, сын Хелкии,","Posle sih proisšestvij, v carstvovanie Artakserksa, carâ Persidskogo, Ezdra, syn Seraii, syn Azarii, syn Helkii,"],[7,2,"сын Шаллума, сын Садока, сын Ахитува,","syn Šalluma, syn Sadoka, syn Ahituva,"],[7,3,"сын Амарии, сын Азарии, сын Марайофа,","syn Amarii, syn Azarii, syn Marajofa,"],[7,4,"сын Захарии, сын Уззия, сын Буккия,","syn Zaharii, syn Uzziâ, syn Bukkiâ,"],[7,5,"сын Авишуя, сын Финееса, сын Елеазара, сын Аарона первосвященника, –","syn Avišuâ, syn Fineesa, syn Eleazara, syn Aarona pervosvâŝennika, –"],[7,6,"Сей Ездра вышел из Вавилона. Он был книжник, сведущий в законе Моисеевом, который дал Господь, Бог Израилев. И дал ему царь все по желанию его, так как рука Господа Бога его была над ним.","Sej Ezdra vyšel iz Vavilona. On byl knižnik, sveduŝij v zakone Moiseevom, kotoryj dal Gospodʹ, Bog Izrailev. I dal emu carʹ vse po želaniû ego, tak kak ruka Gospoda Boga ego byla nad nim."],[7,7,"С ним пошли в Иерусалим и некоторые из сынов Израилевых, и из священников и левитов, и певцов и привратников и нефинеев в седьмой год царя Артаксеркса.","S nim pošli v Ierusalim i nekotorye iz synov Izrailevyh, i iz svâŝennikov i levitov, i pevcov i privratnikov i nefineev v sedʹmoj god carâ Artakserksa."],[7,8,"И пришел он в Иерусалим в пятый месяц, – в седьмой же год царя.","I prišel on v Ierusalim v pâtyj mesâc, – v sedʹmoj že god carâ."],[7,9,"Ибо в первый день первого месяца было начало выхода из Вавилона, и в первый день пятого месяца он пришел в Иерусалим, так как благодеющая рука Бога его была над ним,","Ibo v pervyj denʹ pervogo mesâca bylo načalo vyhoda iz Vavilona, i v pervyj denʹ pâtogo mesâca on prišel v Ierusalim, tak kak blagodeûŝaâ ruka Boga ego byla nad nim,"],[7,10,"потому что Ездра расположил сердце свое к тому, чтобы изучать закон Господень и исполнять его, и учить в Израиле закону и правде.","potomu čto Ezdra raspoložil serdce svoe k tomu, čtoby izučatʹ zakon Gospodenʹ i ispolnâtʹ ego, i učitʹ v Izraile zakonu i pravde."],[7,11,"И вот содержание письма, которое дал царь Артаксеркс Ездре священнику, книжнику, учившему словам заповедей Господа и законов Его в Израиле:","I vot soderžanie pisʹma, kotoroe dal carʹ Artakserks Ezdre svâŝenniku, knižniku, učivšemu slovam zapovedej Gospoda i zakonov Ego v Izraile:"],[7,12,"«Артаксеркс, царь царей, Ездре священнику, учителю закона Бога небесного совершенному», и прочее.","«Artakserks, carʹ carej, Ezdre svâŝenniku, učitelû zakona Boga nebesnogo soveršennomu», i pročee."],[7,13,"«От меня дано повеление, чтобы в царстве моем всякий из народа Израилева и из священников его и левитов, желающий идти в Иерусалим, шел с тобою.","«Ot menâ dano povelenie, čtoby v carstve moem vsâkij iz naroda Izraileva i iz svâŝennikov ego i levitov, želaûŝij idti v Ierusalim, šel s toboû."],[7,14,"Так как ты посылаешься от царя и семи советников его, чтобы обозреть Иудею и Иерусалим по закону Бога твоего, находящемуся в руке твоей,","Tak kak ty posylaešʹsâ ot carâ i semi sovetnikov ego, čtoby obozretʹ Iudeû i Ierusalim po zakonu Boga tvoego, nahodâŝemusâ v ruke tvoej,"],[7,15,"и чтобы доставить серебро и золото, которое царь и советники его пожертвовали Богу Израилеву, Которого жилище в Иерусалиме,","i čtoby dostavitʹ serebro i zoloto, kotoroe carʹ i sovetniki ego požertvovali Bogu Izrailevu, Kotorogo žiliŝe v Ierusalime,"],[7,16,"и все серебро и золото, которое ты соберешь во всей области Вавилонской, вместе с доброхотными даяниями от народа и священников, которые пожертвуют они для дома Бога своего, что в Иерусалиме;","i vse serebro i zoloto, kotoroe ty soberešʹ vo vsej oblasti Vavilonskoj, vmeste s dobrohotnymi daâniâmi ot naroda i svâŝennikov, kotorye požertvuût oni dlâ doma Boga svoego, čto v Ierusalime;"],[7,17,"поэтому немедленно купи на эти деньги волов, овнов, агнцев и хлебных приношений к ним и возлияний для них, и принеси их на жертвенник дома Бога вашего в Иерусалиме.","poétomu nemedlenno kupi na éti denʹgi volov, ovnov, agncev i hlebnyh prinošenij k nim i vozliânij dlâ nih, i prinesi ih na žertvennik doma Boga vašego v Ierusalime."],[7,18,"И что тебе и братьям твоим заблагорассудится сделать из остального серебра и золота, то по воле Бога вашего делайте.","I čto tebe i bratʹâm tvoim zablagorassuditsâ sdelatʹ iz ostalʹnogo serebra i zolota, to po vole Boga vašego delajte."],[7,19,"И сосуды, которые даны тебе для служб в доме Бога твоего, поставь пред Богом Иерусалимским.","I sosudy, kotorye dany tebe dlâ služb v dome Boga tvoego, postavʹ pred Bogom Ierusalimskim."],[7,20,"И прочее потребное для дома Бога твоего, что ты признаешь нужным, давай из дома царских сокровищ.","I pročee potrebnoe dlâ doma Boga tvoego, čto ty priznaešʹ nužnym, davaj iz doma carskih sokroviŝ."],[7,21,"И от меня, царя Артаксеркса, дается повеление всем сокровищехранителям, которые за рекою: все, чего потребует у вас Ездра священник, учитель закона Бога небесного, немедленно давайте:","I ot menâ, carâ Artakserksa, daetsâ povelenie vsem sokroviŝehranitelâm, kotorye za rekoû: vse, čego potrebuet u vas Ezdra svâŝennik, učitelʹ zakona Boga nebesnogo, nemedlenno davajte:"],[7,22,"серебра до ста талантов, и пшеницы до ста коров, и вина до ста батов, и до ста же батов масла, а соли без обозначения количества.","serebra do sta talantov, i pšenicy do sta korov, i vina do sta batov, i do sta že batov masla, a soli bez oboznačeniâ količestva."],[7,23,"Все, что повелено Богом небесным, должно делаться со тщанием для дома Бога небесного; [смотрите, чтобы кто не простер руки на дом Бога небесного,] дабы не было гнева Его на царство, царя и сыновей его.","Vse, čto poveleno Bogom nebesnym, dolžno delatʹsâ so tŝaniem dlâ doma Boga nebesnogo; [smotrite, čtoby kto ne proster ruki na dom Boga nebesnogo,] daby ne bylo gneva Ego na carstvo, carâ i synovej ego."],[7,24,"И даем вам знать, чтобы ни на кого из священников или левитов, певцов, привратников, нефинеев и служащих при этом доме Божием, не налагать ни подати, ни налога, ни пошлины.","I daem vam znatʹ, čtoby ni na kogo iz svâŝennikov ili levitov, pevcov, privratnikov, nefineev i služaŝih pri étom dome Božiem, ne nalagatʹ ni podati, ni naloga, ni pošliny."],[7,25,"Ты же, Ездра, по премудрости Бога твоего, которая в руке твоей, поставь правителей и судей, чтоб они судили весь народ за рекою – всех знающих законы Бога твоего, а кто не знает, тех учите.","Ty že, Ezdra, po premudrosti Boga tvoego, kotoraâ v ruke tvoej, postavʹ pravitelej i sudej, čtob oni sudili vesʹ narod za rekoû – vseh znaûŝih zakony Boga tvoego, a kto ne znaet, teh učite."],[7,26,"Кто же не будет исполнять закон Бога твоего и закон царя, над тем немедленно пусть производят суд, на смерть ли, или на изгнание, или на денежную пеню, или на заключение в темницу».","Kto že ne budet ispolnâtʹ zakon Boga tvoego i zakon carâ, nad tem nemedlenno pustʹ proizvodât sud, na smertʹ li, ili na izgnanie, ili na denežnuû penû, ili na zaklûčenie v temnicu»."],[7,27,"Благословен Господь, Бог отцов наших, вложивший в сердце царя – украсить дом Господень, который в Иерусалиме,","Blagosloven Gospodʹ, Bog otcov naših, vloživšij v serdce carâ – ukrasitʹ dom Gospodenʹ, kotoryj v Ierusalime,"],[7,28,"и склонивший на меня милость царя и советников его, и всех могущественных князей царя! И я ободрился, ибо рука Господа, Бога моего, была надо мною, и собрал я глав Израиля, чтоб они пошли со мною.","i sklonivšij na menâ milostʹ carâ i sovetnikov ego, i vseh moguŝestvennyh knâzej carâ! I â obodrilsâ, ibo ruka Gospoda, Boga moego, byla nado mnoû, i sobral â glav Izrailâ, čtob oni pošli so mnoû."],[8,1,"И вот главы поколений и родословие тех, которые вышли со мною из Вавилона, в царствование царя Артаксеркса:","I vot glavy pokolenij i rodoslovie teh, kotorye vyšli so mnoû iz Vavilona, v carstvovanie carâ Artakserksa:"],[8,2,"из сыновей Финееса Гирсон; из сыновей Ифамара Даниил; из сыновей Давида Хаттуш;","iz synovej Fineesa Girson; iz synovej Ifamara Daniil; iz synovej Davida Hattuš;"],[8,3,"из сыновей Шехании, из сыновей Пароша Захария, и с ним по списку родословному сто пятьдесят человек мужеского пола;","iz synovej Šehanii, iz synovej Paroša Zahariâ, i s nim po spisku rodoslovnomu sto pâtʹdesât čelovek mužeskogo pola;"],[8,4,"из сыновей Пахаф-Моава Эльегоенай, сын Зерахии, и с ним двести человек мужеского пола;","iz synovej Pahaf-Moava Élʹegoenaj, syn Zerahii, i s nim dvesti čelovek mužeskogo pola;"],[8,5,"из сыновей [Зафоя] Шехания, сын Яхазиила, и с ним триста человек мужеского пола;","iz synovej [Zafoâ] Šehaniâ, syn Âhaziila, i s nim trista čelovek mužeskogo pola;"],[8,6,"из сыновей Адина Евед, сын Ионафана, и с ним пятьдесят человек мужеского пола;","iz synovej Adina Eved, syn Ionafana, i s nim pâtʹdesât čelovek mužeskogo pola;"],[8,7,"из сыновей Елама Иешаия, сын Афалии, и с ним семьдесят человек мужеского пола;","iz synovej Elama Iešaiâ, syn Afalii, i s nim semʹdesât čelovek mužeskogo pola;"],[8,8,"из сыновей Сафатии Зевадия, сын Михаилов, и с ним восемьдесят человек мужеского пола;","iz synovej Safatii Zevadiâ, syn Mihailov, i s nim vosemʹdesât čelovek mužeskogo pola;"],[8,9,"из сыновей Иоава Овадия, сын Иехиелов, и с ним двести восемнадцать человек мужеского пола;","iz synovej Ioava Ovadiâ, syn Iehielov, i s nim dvesti vosemnadcatʹ čelovek mužeskogo pola;"],[8,10,"из сыновей [Ваания] Шеломиф, сын Иосифии, и с ним сто шестьдесят человек мужеского пола;","iz synovej [Vaaniâ] Šelomif, syn Iosifii, i s nim sto šestʹdesât čelovek mužeskogo pola;"],[8,11,"из сыновей Бевая Захария, сын Бевая, и с ним двадцать восемь человек мужеского пола;","iz synovej Bevaâ Zahariâ, syn Bevaâ, i s nim dvadcatʹ vosemʹ čelovek mužeskogo pola;"],[8,12,"из сыновей Азгада Иоханан, сын Гаккатана, и с ним сто десять человек мужеского пола;","iz synovej Azgada Iohanan, syn Gakkatana, i s nim sto desâtʹ čelovek mužeskogo pola;"],[8,13,"из сыновей Адоникама последние, и вот имена их: Елифелет, Иеиел и Шемаия, и с ними шестьдесят человек мужеского пола;","iz synovej Adonikama poslednie, i vot imena ih: Elifelet, Ieiel i Šemaiâ, i s nimi šestʹdesât čelovek mužeskogo pola;"],[8,14,"из сыновей Бигвая, Уфай и Заббуд, и с ними семьдесят человек мужеского пола.","iz synovej Bigvaâ, Ufaj i Zabbud, i s nimi semʹdesât čelovek mužeskogo pola."],[8,15,"Я собрал их у реки, втекающей в Агаву, и мы простояли там три дня, и когда я осмотрел народ и священников, то из сынов Левия никого там не нашел.","Â sobral ih u reki, vtekaûŝej v Agavu, i my prostoâli tam tri dnâ, i kogda â osmotrel narod i svâŝennikov, to iz synov Leviâ nikogo tam ne našel."],[8,16,"И послал я позвать Елиезера, Ариэла, Шемаию, и Элнафана, и Иарива, и Элнафана, и Нафана, и Захарию, и Мешуллама – главных, и Иоярива и Элнафана – ученых;","I poslal â pozvatʹ Eliezera, Ariéla, Šemaiû, i Élnafana, i Iariva, i Élnafana, i Nafana, i Zahariû, i Mešullama – glavnyh, i Ioâriva i Élnafana – učenyh;"],[8,17,"и дал им поручение к Иддо, главному в местности Касифье, и вложил им в уста, что говорить к Иддо и братьям его, нефинеям в местности Касифье, чтобы они привели к нам служителей для дома Бога нашего.","i dal im poručenie k Iddo, glavnomu v mestnosti Kasifʹe, i vložil im v usta, čto govoritʹ k Iddo i bratʹâm ego, nefineâm v mestnosti Kasifʹe, čtoby oni priveli k nam služitelej dlâ doma Boga našego."],[8,18,"И привели они к нам, так как благодеющая рука Бога нашего была над нами, человека умного из сыновей Махлия, сына Левиина, сына Израилева, именно Шеревию, и сыновей его и братьев его, восемнадцать человек;","I priveli oni k nam, tak kak blagodeûŝaâ ruka Boga našego byla nad nami, čeloveka umnogo iz synovej Mahliâ, syna Leviina, syna Izraileva, imenno Šereviû, i synovej ego i bratʹev ego, vosemnadcatʹ čelovek;"],[8,19,"и Хашавию и с ним Иешаию из сыновей Мерариных, братьев его и сыновей их двадцать;","i Hašaviû i s nim Iešaiû iz synovej Merarinyh, bratʹev ego i synovej ih dvadcatʹ;"],[8,20,"и из нефинеев, которых дал Давид и князья его на прислугу левитам, двести двадцать нефинеев; все они названы поименно.","i iz nefineev, kotoryh dal David i knâzʹâ ego na prislugu levitam, dvesti dvadcatʹ nefineev; vse oni nazvany poimenno."],[8,21,"И провозгласил я там пост у реки Агавы, чтобы смириться нам пред лицом Бога нашего, просить у Него благополучного пути для себя и для детей наших и для всего имущества нашего,","I provozglasil â tam post u reki Agavy, čtoby smiritʹsâ nam pred licom Boga našego, prositʹ u Nego blagopolučnogo puti dlâ sebâ i dlâ detej naših i dlâ vsego imuŝestva našego,"],[8,22,"так как мне стыдно было просить у царя войска и всадников для охранения нашего от врага на пути, ибо мы, говоря с царем, сказали: «рука Бога нашего для всех, прибегающих к Нему, есть благодеющая, а на всех, оставляющих Его, – могущество Его и гнев Его!»","tak kak mne stydno bylo prositʹ u carâ vojska i vsadnikov dlâ ohraneniâ našego ot vraga na puti, ibo my, govorâ s carem, skazali: «ruka Boga našego dlâ vseh, pribegaûŝih k Nemu, estʹ blagodeûŝaâ, a na vseh, ostavlâûŝih Ego, – moguŝestvo Ego i gnev Ego!»"],[8,23,"Итак, мы постились и просили Бога нашего о сем, и Он услышал нас.","Itak, my postilisʹ i prosili Boga našego o sem, i On uslyšal nas."],[8,24,"И я отделил из начальствующих над священниками двенадцать человек: Шеревию, Хашавию и с ними десять из братьев их;","I â otdelil iz načalʹstvuûŝih nad svâŝennikami dvenadcatʹ čelovek: Šereviû, Hašaviû i s nimi desâtʹ iz bratʹev ih;"],[8,25,"и отдал им весом серебро, и золото, и сосуды, – все, пожертвованное для дома Бога нашего, что пожертвовали царь, и советники его, и князья его, и все Израильтяне, там находившиеся.","i otdal im vesom serebro, i zoloto, i sosudy, – vse, požertvovannoe dlâ doma Boga našego, čto požertvovali carʹ, i sovetniki ego, i knâzʹâ ego, i vse Izrailʹtâne, tam nahodivšiesâ."],[8,26,"И отдал на руки им весом: серебра – шестьсот пятьдесят талантов, и серебряных сосудов на сто талантов, золота – сто талантов;","I otdal na ruki im vesom: serebra – šestʹsot pâtʹdesât talantov, i serebrânyh sosudov na sto talantov, zolota – sto talantov;"],[8,27,"и чаш золотых – двадцать, в тысячу драхм, и два сосуда из лучшей блестящей меди, ценимой как золото.","i čaš zolotyh – dvadcatʹ, v tysâču drahm, i dva sosuda iz lučšej blestâŝej medi, cenimoj kak zoloto."],[8,28,"И сказал я им: вы – святыня Господу, и сосуды – святыня, и серебро и золото – доброхотное даяние Господу, Богу отцов ваших.","I skazal â im: vy – svâtynâ Gospodu, i sosudy – svâtynâ, i serebro i zoloto – dobrohotnoe daânie Gospodu, Bogu otcov vaših."],[8,29,"Будьте же бдительны и сберегите это, доколе весом не сдадите начальствующим над священниками и левитами и главам поколений Израилевых в Иерусалиме, в хранилище при доме Господнем.","Budʹte že bditelʹny i sberegite éto, dokole vesom ne sdadite načalʹstvuûŝim nad svâŝennikami i levitami i glavam pokolenij Izrailevyh v Ierusalime, v hraniliŝe pri dome Gospodnem."],[8,30,"И приняли священники и левиты взвешенное серебро, и золото, и сосуды, чтоб отнести в Иерусалим в дом Бога нашего.","I prinâli svâŝenniki i levity vzvešennoe serebro, i zoloto, i sosudy, čtob otnesti v Ierusalim v dom Boga našego."],[8,31,"И отправились мы от реки Агавы в двенадцатый день первого месяца, чтобы идти в Иерусалим; и рука Бога нашего была над нами, и спасала нас от руки врага и от подстерегающих нас на пути.","I otpravilisʹ my ot reki Agavy v dvenadcatyj denʹ pervogo mesâca, čtoby idti v Ierusalim; i ruka Boga našego byla nad nami, i spasala nas ot ruki vraga i ot podsteregaûŝih nas na puti."],[8,32,"И пришли мы в Иерусалим, и пробыли там три дня.","I prišli my v Ierusalim, i probyli tam tri dnâ."],[8,33,"В четвертый день мы сдали весом серебро, и золото, и сосуды в дом Бога нашего, на руки Меремофу, сыну Урии, священнику, и с ним Елеазару, сыну Финеесову, и с ними Иозаваду, сыну Иисусову, и Ноадии, сыну Виннуя, левитам,","V četvertyj denʹ my sdali vesom serebro, i zoloto, i sosudy v dom Boga našego, na ruki Meremofu, synu Urii, svâŝenniku, i s nim Eleazaru, synu Fineesovu, i s nimi Iozavadu, synu Iisusovu, i Noadii, synu Vinnuâ, levitam,"],[8,34,"все счетом и весом. И все взвешенное записано в то же время.","vse sčetom i vesom. I vse vzvešennoe zapisano v to že vremâ."],[8,35,"Пришедшие из плена переселенцы принесли во всесожжение Богу Израилеву двенадцать тельцов за всего Израиля, девяносто шесть овнов, семьдесят семь агнцев и двенадцать козлов в жертву за грех: все это во всесожжение Господу.","Prišedšie iz plena pereselency prinesli vo vsesožženie Bogu Izrailevu dvenadcatʹ telʹcov za vsego Izrailâ, devânosto šestʹ ovnov, semʹdesât semʹ agncev i dvenadcatʹ kozlov v žertvu za greh: vse éto vo vsesožženie Gospodu."],[8,36,"И отдали царские повеления царским сатрапам и заречным областеначальникам, и они почтили народ и дом Божий.","I otdali carskie poveleniâ carskim satrapam i zarečnym oblastenačalʹnikam, i oni počtili narod i dom Božij."],[9,1,"По окончании сего подошли ко мне начальствующие и сказали: народ Израилев и священники и левиты не отделились от народов иноплеменных с мерзостями их, от Хананеев, Хеттеев, Ферезеев, Иевусеев, Аммонитян, Моавитян, Египтян и Аморреев,","Po okončanii sego podošli ko mne načalʹstvuûŝie i skazali: narod Izrailev i svâŝenniki i levity ne otdelilisʹ ot narodov inoplemennyh s merzostâmi ih, ot Hananeev, Hetteev, Ferezeev, Ievuseev, Ammonitân, Moavitân, Egiptân i Amorreev,"],[9,2,"потому что взяли дочерей их за себя и за сыновей своих, и смешалось семя святое с народами иноплеменными, и притом рука знатнейших и главнейших была в сем беззаконии первою.","potomu čto vzâli dočerej ih za sebâ i za synovej svoih, i smešalosʹ semâ svâtoe s narodami inoplemennymi, i pritom ruka znatnejših i glavnejših byla v sem bezzakonii pervoû."],[9,3,"Услышав это слово, я разодрал нижнюю и верхнюю одежду мою и рвал волосы на голове моей и на бороде моей, и сидел печальный.","Uslyšav éto slovo, â razodral nižnûû i verhnûû odeždu moû i rval volosy na golove moej i na borode moej, i sidel pečalʹnyj."],[9,4,"Тогда собрались ко мне все, убоявшиеся слов Бога Израилева по причине преступления переселенцев, и я сидел в печали до вечерней жертвы.","Togda sobralisʹ ko mne vse, uboâvšiesâ slov Boga Izraileva po pričine prestupleniâ pereselencev, i â sidel v pečali do večernej žertvy."],[9,5,"А во время вечерней жертвы я встал с места сетования моего, и в разодранной нижней и верхней одежде пал на колени мои и простер руки мои к Господу, Богу моему,","A vo vremâ večernej žertvy â vstal s mesta setovaniâ moego, i v razodrannoj nižnej i verhnej odežde pal na koleni moi i proster ruki moi k Gospodu, Bogu moemu,"],[9,6,"и сказал: Боже мой! стыжусь и боюсь поднять лицо мое к Тебе, Боже мой, потому что беззакония наши стали выше головы, и вина наша возросла до небес.","i skazal: Bože moj! styžusʹ i boûsʹ podnâtʹ lico moe k Tebe, Bože moj, potomu čto bezzakoniâ naši stali vyše golovy, i vina naša vozrosla do nebes."],[9,7,"Со дней отцов наших мы в великой вине до сего дня, и за беззакония наши преданы были мы, цари наши, священники наши, в руки царей иноземных, под меч, в плен и на разграбление и на посрамление, как это и ныне.","So dnej otcov naših my v velikoj vine do sego dnâ, i za bezzakoniâ naši predany byli my, cari naši, svâŝenniki naši, v ruki carej inozemnyh, pod meč, v plen i na razgrablenie i na posramlenie, kak éto i nyne."],[9,8,"И вот, по малом времени, даровано нам помилование от Господа, Бога нашего, и Он оставил у нас несколько уцелевших и дал нам утвердиться на месте святыни Его, и просветил глаза наши Бог наш, и дал нам ожить немного в рабстве нашем.","I vot, po malom vremeni, darovano nam pomilovanie ot Gospoda, Boga našego, i On ostavil u nas neskolʹko ucelevših i dal nam utverditʹsâ na meste svâtyni Ego, i prosvetil glaza naši Bog naš, i dal nam ožitʹ nemnogo v rabstve našem."],[9,9,"Мы – рабы, но и в рабстве нашем не оставил нас Бог наш. И склонил Он к нам милость царей Персидских, чтоб они дали нам ожить, воздвигнуть дом Бога нашего и восстановить его из развалин его, и дали нам ограждение в Иудее и в Иерусалиме.","My – raby, no i v rabstve našem ne ostavil nas Bog naš. I sklonil On k nam milostʹ carej Persidskih, čtob oni dali nam ožitʹ, vozdvignutʹ dom Boga našego i vosstanovitʹ ego iz razvalin ego, i dali nam ograždenie v Iudee i v Ierusalime."],[9,10,"И ныне, что скажем мы, Боже наш, после этого? Ибо мы отступили от заповедей Твоих,","I nyne, čto skažem my, Bože naš, posle étogo? Ibo my otstupili ot zapovedej Tvoih,"],[9,11,"которые заповедал Ты чрез рабов Твоих пророков, говоря: «земля, в которую идете вы, чтоб овладеть ею, земля нечистая, она осквернена нечистотою иноплеменных народов, их мерзостями, которыми они наполнили ее от края до края в осквернениях своих.","kotorye zapovedal Ty črez rabov Tvoih prorokov, govorâ: «zemlâ, v kotoruû idete vy, čtob ovladetʹ eû, zemlâ nečistaâ, ona oskvernena nečistotoû inoplemennyh narodov, ih merzostâmi, kotorymi oni napolnili ee ot kraâ do kraâ v oskverneniâh svoih."],[9,12,"Итак, дочерей ваших не выдавайте за сыновей их, и дочерей их не берите за сыновей ваших, и не ищите мира их и блага их вовеки, чтобы укрепиться вам и питаться благами земли той и передать ее в наследие сыновьям вашим навеки».","Itak, dočerej vaših ne vydavajte za synovej ih, i dočerej ih ne berite za synovej vaših, i ne iŝite mira ih i blaga ih voveki, čtoby ukrepitʹsâ vam i pitatʹsâ blagami zemli toj i peredatʹ ee v nasledie synovʹâm vašim naveki»."],[9,13,"И после всего, постигшего нас за худые дела наши и за великую вину нашу, – ибо Ты, Боже наш, пощадил нас не по мере беззакония нашего и дал нам такое избавление, –","I posle vsego, postigšego nas za hudye dela naši i za velikuû vinu našu, – ibo Ty, Bože naš, poŝadil nas ne po mere bezzakoniâ našego i dal nam takoe izbavlenie, –"],[9,14,"неужели мы опять будем нарушать заповеди Твои и вступать в родство с этими отвратительными народами? Не прогневаешься ли Ты на нас даже до истребления нас, так что не будет уцелевших и не будет спасения?","neuželi my opâtʹ budem narušatʹ zapovedi Tvoi i vstupatʹ v rodstvo s étimi otvratitelʹnymi narodami? Ne prognevaešʹsâ li Ty na nas daže do istrebleniâ nas, tak čto ne budet ucelevših i ne budet spaseniâ?"],[9,15,"Господи Боже Израилев! праведен Ты. Ибо мы остались уцелевшими до сего дня; и вот мы в беззакониях наших пред лицом Твоим, хотя после этого не надлежало бы нам стоять пред лицом Твоим.","Gospodi Bože Izrailev! praveden Ty. Ibo my ostalisʹ ucelevšimi do sego dnâ; i vot my v bezzakoniâh naših pred licom Tvoim, hotâ posle étogo ne nadležalo by nam stoâtʹ pred licom Tvoim."],[10,1,"Когда так молился Ездра и исповедовался, плача и повергаясь пред домом Божиим, стеклось к нему весьма большое собрание Израильтян, мужчин и женщин и детей, потому что и народ много плакал.","Kogda tak molilsâ Ezdra i ispovedovalsâ, plača i povergaâsʹ pred domom Božiim, steklosʹ k nemu vesʹma bolʹšoe sobranie Izrailʹtân, mužčin i ženŝin i detej, potomu čto i narod mnogo plakal."],[10,2,"И отвечал Шехания, сын Иехиила из сыновей Еламовых, и сказал Ездре: мы сделали преступление пред Богом нашим, что взяли себе жен иноплеменных из народов земли, но есть еще надежда для Израиля в этом деле;","I otvečal Šehaniâ, syn Iehiila iz synovej Elamovyh, i skazal Ezdre: my sdelali prestuplenie pred Bogom našim, čto vzâli sebe žen inoplemennyh iz narodov zemli, no estʹ eŝe nadežda dlâ Izrailâ v étom dele;"],[10,3,"заключим теперь завет с Богом нашим, что, по совету господина моего и благоговеющих пред заповедями Бога нашего, мы отпустим от себя всех жен и детей, рожденных ими, – и да будет по закону!","zaklûčim teperʹ zavet s Bogom našim, čto, po sovetu gospodina moego i blagogoveûŝih pred zapovedâmi Boga našego, my otpustim ot sebâ vseh žen i detej, roždennyh imi, – i da budet po zakonu!"],[10,4,"Встань, потому что это твое дело, и мы с тобою: ободрись и действуй!","Vstanʹ, potomu čto éto tvoe delo, i my s toboû: obodrisʹ i dejstvuj!"],[10,5,"И встал Ездра, и велел начальствующим над священниками, левитами и всем Израилем дать клятву, что они сделают так. И они дали клятву.","I vstal Ezdra, i velel načalʹstvuûŝim nad svâŝennikami, levitami i vsem Izrailem datʹ klâtvu, čto oni sdelaût tak. I oni dali klâtvu."],[10,6,"И встал Ездра и пошел от дома Божия в жилище Иоханана, сына Елияшивова, и пришел туда. Хлеба он не ел и воды не пил, потому что плакал о преступлении переселенцев.","I vstal Ezdra i pošel ot doma Božiâ v žiliŝe Iohanana, syna Eliâšivova, i prišel tuda. Hleba on ne el i vody ne pil, potomu čto plakal o prestuplenii pereselencev."],[10,7,"И объявили в Иудее и в Иерусалиме всем бывшим в плену, чтоб они собрались в Иерусалим;","I obʺâvili v Iudee i v Ierusalime vsem byvšim v plenu, čtob oni sobralisʹ v Ierusalim;"],[10,8,"а кто не придет чрез три дня, на все имение того, по определению начальствующих и старейшин, будет положено заклятие, и сам он будет отлучен от общества переселенцев.","a kto ne pridet črez tri dnâ, na vse imenie togo, po opredeleniû načalʹstvuûŝih i starejšin, budet položeno zaklâtie, i sam on budet otlučen ot obŝestva pereselencev."],[10,9,"И собрались все жители Иудеи и земли Вениаминовой в Иерусалим в три дня. Это было в девятом месяце, в двадцатый день месяца. И сидел весь народ на площади у дома Божия, дрожа как по этому делу, так и от дождей.","I sobralisʹ vse žiteli Iudei i zemli Veniaminovoj v Ierusalim v tri dnâ. Éto bylo v devâtom mesâce, v dvadcatyj denʹ mesâca. I sidel vesʹ narod na ploŝadi u doma Božiâ, droža kak po étomu delu, tak i ot doždej."],[10,10,"И встал Ездра священник и сказал им: вы сделали преступление, взяв себе жен иноплеменных, и тем увеличили вину Израиля.","I vstal Ezdra svâŝennik i skazal im: vy sdelali prestuplenie, vzâv sebe žen inoplemennyh, i tem uveličili vinu Izrailâ."],[10,11,"Итак, покайтесь в сем пред Господом, Богом отцов ваших, и исполните волю Его, и отлучите себя от народов земли и от жен иноплеменных.","Itak, pokajtesʹ v sem pred Gospodom, Bogom otcov vaših, i ispolnite volû Ego, i otlučite sebâ ot narodov zemli i ot žen inoplemennyh."],[10,12,"И отвечало все собрание, и сказало громким голосом: как ты сказал, так и сделаем.","I otvečalo vse sobranie, i skazalo gromkim golosom: kak ty skazal, tak i sdelaem."],[10,13,"Однако же народ многочислен и время теперь дождливое, и нет возможности стоять на улице. Да и это дело не одного дня и не двух, потому что мы много в этом деле погрешили.","Odnako že narod mnogočislen i vremâ teperʹ doždlivoe, i net vozmožnosti stoâtʹ na ulice. Da i éto delo ne odnogo dnâ i ne dvuh, potomu čto my mnogo v étom dele pogrešili."],[10,14,"Пусть наши начальствующие заступят место всего общества, и все в городах наших, которые взяли жен иноплеменных, пусть приходят сюда в назначенные времена и с ними старейшины каждого города и судьи его, доколе не отвратится от нас пылающий гнев Бога нашего за это дело.","Pustʹ naši načalʹstvuûŝie zastupât mesto vsego obŝestva, i vse v gorodah naših, kotorye vzâli žen inoplemennyh, pustʹ prihodât sûda v naznačennye vremena i s nimi starejšiny každogo goroda i sudʹi ego, dokole ne otvratitsâ ot nas pylaûŝij gnev Boga našego za éto delo."],[10,15,"Тогда Ионафан, сын Асаила, и Яхзеия, сын Фиквы, стали над этим делом, и Мешуллам и Шавфай левит были помощниками им.","Togda Ionafan, syn Asaila, i Âhzeiâ, syn Fikvy, stali nad étim delom, i Mešullam i Šavfaj levit byli pomoŝnikami im."],[10,16,"И сделали так вышедшие из плена. И отделены на это Ездра священник, главы поколений, от каждого поколения их, и все они названы поименно. И сделали они заседание в первый день десятого месяца, для исследования сего дела;","I sdelali tak vyšedšie iz plena. I otdeleny na éto Ezdra svâŝennik, glavy pokolenij, ot každogo pokoleniâ ih, i vse oni nazvany poimenno. I sdelali oni zasedanie v pervyj denʹ desâtogo mesâca, dlâ issledovaniâ sego dela;"],[10,17,"и окончили исследование о всех, которые взяли жен иноплеменных, к первому дню первого месяца.","i okončili issledovanie o vseh, kotorye vzâli žen inoplemennyh, k pervomu dnû pervogo mesâca."],[10,18,"И нашлись из сыновей священнических, которые взяли жен иноплеменных, – из сыновей Иисуса, сына Иоседекова, и братьев его: Маасея, Елиезер, Иарив и Гедалия;","I našlisʹ iz synovej svâŝenničeskih, kotorye vzâli žen inoplemennyh, – iz synovej Iisusa, syna Iosedekova, i bratʹev ego: Maaseâ, Eliezer, Iariv i Gedaliâ;"],[10,19,"и они дали руки свои во уверение, что отпустят жен своих, и что они повинны принести в жертву овна за свою вину;","i oni dali ruki svoi vo uverenie, čto otpustât žen svoih, i čto oni povinny prinesti v žertvu ovna za svoû vinu;"],[10,20,"и из сыновей Иммера: Хананий и Зевадия;","i iz synovej Immera: Hananij i Zevadiâ;"],[10,21,"и из сыновей Харима: Маасея, Елия, Шемаия, Иехиил и Уззия;","i iz synovej Harima: Maaseâ, Eliâ, Šemaiâ, Iehiil i Uzziâ;"],[10,22,"и из сыновей Пашхура: Елиоенай, Маасея, Исмаил, Нафанаил, Иозавад и Эласа;","i iz synovej Pašhura: Elioenaj, Maaseâ, Ismail, Nafanail, Iozavad i Élasa;"],[10,23,"И из левитов: Иозавад, Шимей и Келаия, он же Клита, Пафахия, Иуда и Елиезер;","I iz levitov: Iozavad, Šimej i Kelaiâ, on že Klita, Pafahiâ, Iuda i Eliezer;"],[10,24,"И из певцов: Елияшив; и из привратников: Шаллум, Телем и Урий;","I iz pevcov: Eliâšiv; i iz privratnikov: Šallum, Telem i Urij;"],[10,25,"А из Израильтян, – из сыновей Пароша: Рамаия, Иззия, Малхия, Миямин, Елеазар, Малхия и Венаия;","A iz Izrailʹtân, – iz synovej Paroša: Ramaiâ, Izziâ, Malhiâ, Miâmin, Eleazar, Malhiâ i Venaiâ;"],[10,26,"и из сыновей Елама: Матфания, Захария, Иехиел, Авдий, Иремоф и Елия;","i iz synovej Elama: Matfaniâ, Zahariâ, Iehiel, Avdij, Iremof i Eliâ;"],[10,27,"и из сыновей Заффу: Елиоенай, Елияшив, Матфания, Иремоф, Завад и Азиса;","i iz synovej Zaffu: Elioenaj, Eliâšiv, Matfaniâ, Iremof, Zavad i Azisa;"],[10,28,"и из сыновей Бевая: Иоханан, Ханания, Забвай и Афлай;","i iz synovej Bevaâ: Iohanan, Hananiâ, Zabvaj i Aflaj;"],[10,29,"и из сыновей Вания: Мешуллам, Маллух, Адая, Иашув, Шеал и Иерамоф;","i iz synovej Vaniâ: Mešullam, Malluh, Adaâ, Iašuv, Šeal i Ieramof;"],[10,30,"и из сыновей Пахаф-Моава: Адна, Хелал, Венаия, Маасея, Матфания, Веселеил, Биннуй и Манассия;","i iz synovej Pahaf-Moava: Adna, Helal, Venaiâ, Maaseâ, Matfaniâ, Veseleil, Binnuj i Manassiâ;"],[10,31,"и из сыновей Харима: Елиезер, Ишшия, Малхия, Шемаия, Симеон,","i iz synovej Harima: Eliezer, Iššiâ, Malhiâ, Šemaiâ, Simeon,"],[10,32,"Вениамин, Маллух, Шемария;","Veniamin, Malluh, Šemariâ;"],[10,33,"и из сыновей Хашума: Мафнай, Мафафа, Завад, Елифелет, Иеремай, Манассия и Шимей;","i iz synovej Hašuma: Mafnaj, Mafafa, Zavad, Elifelet, Ieremaj, Manassiâ i Šimej;"],[10,34,"и из сыновей Вания: Маадай, Амрам и Уел,","i iz synovej Vaniâ: Maadaj, Amram i Uel,"],[10,35,"Бенаия, Бидья, Келуги,","Benaiâ, Bidʹâ, Kelugi,"],[10,36,"Ванея, Меремоф, Елиашив,","Vaneâ, Meremof, Eliašiv,"],[10,37,"Матфания, Мафнай, Иаасай,","Matfaniâ, Mafnaj, Iaasaj,"],[10,38,"Ваний, Биннуй, Шимей,","Vanij, Binnuj, Šimej,"],[10,39,"Шелемия, Нафан, Адаия,","Šelemiâ, Nafan, Adaiâ,"],[10,40,"Махнадбай, Шашай, Шарай,","Mahnadbaj, Šašaj, Šaraj,"],[10,41,"Азариел, Шелемиягу, Шемария,","Azariel, Šelemiâgu, Šemariâ,"],[10,42,"Шаллум, Амария и Иосиф;","Šallum, Amariâ i Iosif;"],[10,43,"и из сыновей Нево: Иеиел, Матфифия, Завад, Зевина, Иаддай, Иоель и Бенаия.","i iz synovej Nevo: Ieiel, Matfifiâ, Zavad, Zevina, Iaddaj, Ioelʹ i Benaiâ."],[10,44,"Все сии взяли за себя жен иноплеменных, и некоторые из сих жен родили им детей.","Vse sii vzâli za sebâ žen inoplemennyh, i nekotorye iz sih žen rodili im detej."]],"cmn-cuv-hant":[[1,1,"波斯王 塞魯士元年，耶和華為要應驗藉 耶利米口所說的話，就激動 波斯王 塞魯士的心，使他下詔通告全國說：","bō sī wáng sāi lǔ shì yuán nián， yé hé huá wèi yào yīng yàn jí yé lì mǐ kǒu suǒ shuō de huà， jiù jī dòng bō sī wáng sāi lǔ shì de xīn， shǐ tā xià zhào tōng gào quán guó shuō："],[1,2,"「 波斯王 塞魯士如此說：『耶和華天上的神已將天下萬國賜給我，又囑咐我在 猶大的 耶路撒冷為他建造殿宇。","‘ bō sī wáng sāi lǔ shì rú cǐ shuō：“yé hé huá tiān shàng de shén yǐ jiāng tiān xià wàn guó cì gěi wǒ， yòu zhǔ fù wǒ zài yóu dà de yé lù sā lěng wèi tā jiàn zào diàn yǔ."],[1,3,"在你們中間凡作他子民的，可以上 猶大的 耶路撒冷，在 耶路撒冷重建耶和華－ 以色列神的殿（只有他是神）。願神與這人同在。","zài nǐ men zhōng jiān fán zuò tā zǐ mín de， kě yǐ shàng yóu dà de yé lù sā lěng， zài yé lù sā lěng zhòng jiàn yé hé huá－ yǐ sè liè shén de diàn （zhǐ yǒu tā shì shén）. yuàn shén yǔ zhè rén tóng zài."],[1,4,"凡剩下的人，無論寄居何處，那地的人要用金銀、財物、牲畜幫助他，另外也要為 耶路撒冷神的殿甘心獻上禮物。』」","fán shèng xià de rén， wú lùn jì jū hé chù， nà de de rén yào yòng jīn yín, cái wù, shēng chù bāng zhù tā， lìng wài yě yào wèi yé lù sā lěng shén de diàn gān xīn xiàn shàng lǐ wù.”’"],[1,5,"於是， 猶大和 便雅憫的族長、祭司、 利未人，就是一切被神激動他心的人，都起來要上 耶路撒冷去建造耶和華的殿。","yú shì， yóu dà hé biàn yǎ mǐn de zú zhǎng, jì sī, lì wèi rén， jiù shì yī qiè bèi shén jī dòng tā xīn de rén， dōu qǐ lái yào shàng yé lù sā lěng qù jiàn zào yé hé huá de diàn."],[1,6,"他們四圍的人就拿銀器、金子、財物、牲畜、珍寶幫助他們，另外還有甘心獻的禮物。","tā men sì wéi de rén jiù ná yín qì, jīn zǐ, cái wù, shēng chù, zhēn bǎo bāng zhù tā men， lìng wài hái yǒu gān xīn xiàn de lǐ wù."],[1,7,"塞魯士王也將耶和華殿的器皿拿出來，這器皿是 尼布甲尼撒從 耶路撒冷掠來、放在自己神之廟中的。","sāi lǔ shì wáng yě jiāng yé hé huá diàn de qì mǐn ná chū lái， zhè qì mǐn shì ní bù jiǎ ní sā cóng yé lù sā lěng lüè lái, fàng zài zì jǐ shén zhī miào zhōng de."],[1,8,"波斯王 塞魯士派庫官 米提利達將這器皿拿出來，按數交給 猶大的首領 設巴薩。","bō sī wáng sāi lǔ shì pài kù guān mǐ tí lì dá jiāng zhè qì mǐn ná chū lái， àn shù jiāo gěi yóu dà de shǒu lǐng shè bā sà."],[1,9,"器皿的數目記在下面：金盤三十個，銀盤一千個，刀二十九把，","qì mǐn de shù mù jì zài xià miàn： jīn pán sān shí gè， yín pán yī qiān gè， dāo èr shí jiǔ bǎ，"],[1,10,"金碗三十個，銀碗之次的四百一十個，別樣的器皿一千件。","jīn wǎn sān shí gè， yín wǎn zhī cì de sì bǎi yī shí gè， bié yàng de qì mǐn yī qiān jiàn."],[1,11,"金銀器皿共有五千四百件。被擄的人從 巴比倫上 耶路撒冷的時候， 設巴薩將這一切都帶上來。","jīn yín qì mǐn gòng yǒu wǔ qiān sì bǎi jiàn. bèi lǔ de rén cóng bā bǐ lún shàng yé lù sā lěng de shí hòu， shè bā sà jiāng zhè yī qiè dōu dài shàng lái."],[2,1,"巴比倫王 尼布甲尼撒從前擄到 巴比倫之 猶大省的人，現在他們的子孫從被擄到之地回 耶路撒冷和 猶大，各歸本城。","bā bǐ lún wáng ní bù jiǎ ní sā cóng qián lǔ dào bā bǐ lún zhī yóu dà shěng de rén， xiàn zài tā men de zǐ sūn cóng bèi lǔ dào zhī de huí yé lù sā lěng hé yóu dà， gè guī běn chéng."],[2,2,"他們是同着 所羅巴伯、 耶書亞、 尼希米、 西萊雅、 利來雅、 末底改、 必珊、 米斯拔、 比革瓦伊、 利宏、 巴拿回來的。","tā men shì tóng zhe suǒ luó bā bó, yé shū yà, ní xī mǐ, xī lái yǎ, lì lái yǎ, mò dǐ gǎi, bì shān, mǐ sī bá, bǐ gé wǎ yī, lì hóng, bā ná huí lái de."],[2,3,"以色列人民的數目記在下面： 巴錄的子孫二千一百七十二名；","yǐ sè liè rén mín de shù mù jì zài xià miàn： bā lù de zǐ sūn èr qiān yī bǎi qī shí èr míng；"],[2,4,"示法提雅的子孫三百七十二名；","shì fǎ tí yǎ de zǐ sūn sān bǎi qī shí èr míng；"],[2,5,"亞拉的子孫七百七十五名；","yà lā de zǐ sūn qī bǎi qī shí wǔ míng；"],[2,6,"巴哈‧摩押的後裔，就是 耶書亞和 約押的子孫二千八百一十二名；","bā hā‧mó yā de hòu yì， jiù shì yé shū yà hé yuē yā de zǐ sūn èr qiān bā bǎi yī shí èr míng；"],[2,7,"以攔的子孫一千二百五十四名；","yǐ lán de zǐ sūn yī qiān èr bǎi wǔ shí sì míng；"],[2,8,"薩土的子孫九百四十五名；","sà tǔ de zǐ sūn jiǔ bǎi sì shí wǔ míng；"],[2,9,"薩改的子孫七百六十名；","sà gǎi de zǐ sūn qī bǎi liù shí míng；"],[2,10,"巴尼的子孫六百四十二名；","bā ní de zǐ sūn liù bǎi sì shí èr míng；"],[2,11,"比拜的子孫六百二十三名；","bǐ bài de zǐ sūn liù bǎi èr shí sān míng；"],[2,12,"押甲的子孫一千二百二十二名；","yā jiǎ de zǐ sūn yī qiān èr bǎi èr shí èr míng；"],[2,13,"亞多尼干的子孫六百六十六名；","yà duō ní gàn de zǐ sūn liù bǎi liù shí liù míng；"],[2,14,"比革瓦伊的子孫二千零五十六名；","bǐ gé wǎ yī de zǐ sūn èr qiān líng wǔ shí liù míng；"],[2,15,"亞丁的子孫四百五十四名；","yà dīng de zǐ sūn sì bǎi wǔ shí sì míng；"],[2,16,"亞特的後裔，就是 希西家的子孫九十八名；","yà tè de hòu yì， jiù shì xī xī jiā de zǐ sūn jiǔ shí bā míng；"],[2,17,"比賽的子孫三百二十三名；","bǐ sài de zǐ sūn sān bǎi èr shí sān míng；"],[2,18,"約拉的子孫一百一十二名；","yuē lā de zǐ sūn yī bǎi yī shí èr míng；"],[2,19,"哈順的子孫二百二十三名；","hā shùn de zǐ sūn èr bǎi èr shí sān míng；"],[2,20,"吉罷珥人九十五名；","jí bà ěr rén jiǔ shí wǔ míng；"],[2,21,"伯利恆人一百二十三名；","bó lì héng rén yī bǎi èr shí sān míng；"],[2,22,"尼陀法人五十六名；","ní tuó fǎ rén wǔ shí liù míng；"],[2,23,"亞拿突人一百二十八名；","yà ná tū rén yī bǎi èr shí bā míng；"],[2,24,"亞斯瑪弗人四十二名；","yà sī mǎ fú rén sì shí èr míng；"],[2,25,"基列‧耶琳人、 基非拉人、 比錄人共七百四十三名；","jī liè‧yé lín rén, jī fēi lā rén, bǐ lù rén gòng qī bǎi sì shí sān míng；"],[2,26,"拉瑪人、 迦巴人共六百二十一名；","lā mǎ rén, jiā bā rén gòng liù bǎi èr shí yī míng；"],[2,27,"默瑪人一百二十二名；","mò mǎ rén yī bǎi èr shí èr míng；"],[2,28,"伯特利人、 艾人共二百二十三名；","bó tè lì rén, ài rén gòng èr bǎi èr shí sān míng；"],[2,29,"尼波人五十二名；","ní bō rén wǔ shí èr míng；"],[2,30,"末必人一百五十六名；","mò bì rén yī bǎi wǔ shí liù míng；"],[2,31,"別的 以攔子孫一千二百五十四名；","bié de yǐ lán zǐ sūn yī qiān èr bǎi wǔ shí sì míng；"],[2,32,"哈琳的子孫三百二十名；","hā lín de zǐ sūn sān bǎi èr shí míng；"],[2,33,"羅德人、 哈第人、 阿挪人共七百二十五名；","luó dé rén, hā dì rén, ā nuó rén gòng qī bǎi èr shí wǔ míng；"],[2,34,"耶利哥人三百四十五名；","yé lì gē rén sān bǎi sì shí wǔ míng；"],[2,35,"西拿人三千六百三十名。","xī ná rén sān qiān liù bǎi sān shí míng."],[2,36,"祭司： 耶書亞家 耶大雅的子孫九百七十三名；","jì sī： yé shū yà jiā yé dà yǎ de zǐ sūn jiǔ bǎi qī shí sān míng；"],[2,37,"音麥的子孫一千零五十二名；","yīn mài de zǐ sūn yī qiān líng wǔ shí èr míng；"],[2,38,"巴施戶珥的子孫一千二百四十七名；","bā shī hù ěr de zǐ sūn yī qiān èr bǎi sì shí qī míng；"],[2,39,"哈琳的子孫一千零一十七名。","hā lín de zǐ sūn yī qiān líng yī shí qī míng."],[2,40,"利未人： 何達威雅的後裔，就是 耶書亞和 甲篾的子孫七十四名。","lì wèi rén： hé dá wēi yǎ de hòu yì， jiù shì yé shū yà hé jiǎ miè de zǐ sūn qī shí sì míng."],[2,41,"歌唱的： 亞薩的子孫一百二十八名。","gē chàng de： yà sà de zǐ sūn yī bǎi èr shí bā míng."],[2,42,"守門的： 沙龍的子孫、 亞特的子孫、 達們的子孫、 亞谷的子孫、 哈底大的子孫、 朔拜的子孫，共一百三十九名。","shǒu mén de： shā lóng de zǐ sūn, yà tè de zǐ sūn, dá men de zǐ sūn, yà gǔ de zǐ sūn, hā dǐ dà de zǐ sūn, shuò bài de zǐ sūn， gòng yī bǎi sān shí jiǔ míng."],[2,43,"尼提寧： 西哈的子孫、 哈蘇巴的子孫、 答巴俄的子孫、","ní tí níng： xī hā de zǐ sūn, hā sū bā de zǐ sūn, dá bā é de zǐ sūn,"],[2,44,"基綠的子孫、 西亞的子孫、 巴頓的子孫、","jī lǜ de zǐ sūn, xī yà de zǐ sūn, bā dùn de zǐ sūn,"],[2,45,"利巴拿的子孫、 哈迦巴的子孫、 亞谷的子孫、","lì bā ná de zǐ sūn, hā jiā bā de zǐ sūn, yà gǔ de zǐ sūn,"],[2,46,"哈甲的子孫、 薩買的子孫、 哈難的子孫、","hā jiǎ de zǐ sūn, sà mǎi de zǐ sūn, hā nán de zǐ sūn,"],[2,47,"吉德的子孫、 迦哈的子孫、 利亞雅的子孫、","jí dé de zǐ sūn, jiā hā de zǐ sūn, lì yà yǎ de zǐ sūn,"],[2,48,"利汛的子孫、 尼哥大的子孫、 迦散的子孫、","lì xùn de zǐ sūn, ní gē dà de zǐ sūn, jiā sàn de zǐ sūn,"],[2,49,"烏撒的子孫、 巴西亞的子孫、 比賽的子孫、","wū sā de zǐ sūn, bā xī yà de zǐ sūn, bǐ sài de zǐ sūn,"],[2,50,"押拿的子孫、 米烏寧的子孫、 尼普心的子孫、","yā ná de zǐ sūn, mǐ wū níng de zǐ sūn, ní pǔ xīn de zǐ sūn,"],[2,51,"巴卜的子孫、 哈古巴的子孫、 哈忽的子孫、","bā bo de zǐ sūn, hā gǔ bā de zǐ sūn, hā hū de zǐ sūn,"],[2,52,"巴洗律的子孫、 米希大的子孫、 哈沙的子孫、","bā xǐ lǜ de zǐ sūn, mǐ xī dà de zǐ sūn, hā shā de zǐ sūn,"],[2,53,"巴柯的子孫、 西西拉的子孫、 答瑪的子孫、","bā kē de zǐ sūn, xī xī lā de zǐ sūn, dá mǎ de zǐ sūn,"],[2,54,"尼細亞的子孫、 哈提法的子孫。","ní xì yà de zǐ sūn, hā tí fǎ de zǐ sūn."],[2,55,"所羅門僕人的後裔，就是 瑣太的子孫、 瑣斐列的子孫、 比路大的子孫、","suǒ luó mén pú rén de hòu yì， jiù shì suǒ tài de zǐ sūn, suǒ fěi liè de zǐ sūn, bǐ lù dà de zǐ sūn,"],[2,56,"雅拉的子孫、 達昆的子孫、 吉德的子孫、","yǎ lā de zǐ sūn, dá kūn de zǐ sūn, jí dé de zǐ sūn,"],[2,57,"示法提雅的子孫、 哈替的子孫、 玻黑列‧哈斯巴音的子孫、 亞米的子孫。","shì fǎ tí yǎ de zǐ sūn, hā tì de zǐ sūn, bō hēi liè‧hā sī bā yīn de zǐ sūn, yà mǐ de zǐ sūn."],[2,58,"尼提寧和 所羅門僕人的後裔共三百九十二名。","ní tí níng hé suǒ luó mén pú rén de hòu yì gòng sān bǎi jiǔ shí èr míng."],[2,59,"從 特‧米拉、 特‧哈薩、 基綠、 押但、 音麥上來的，不能指明他們的宗族譜系是 以色列人不是；","cóng tè‧mǐ lā, tè‧hā sà, jī lǜ, yā dàn, yīn mài shàng lái de， bù néng zhǐ míng tā men de zōng zú pǔ xì shì yǐ sè liè rén bù shì；"],[2,60,"他們是 第來雅的子孫、 多比雅的子孫、 尼哥大的子孫，共六百五十二名。","tā men shì dì lái yǎ de zǐ sūn, duō bǐ yǎ de zǐ sūn, ní gē dà de zǐ sūn， gòng liù bǎi wǔ shí èr míng."],[2,61,"祭司中， 哈巴雅的子孫、 哈哥斯的子孫、 巴西萊的子孫；因為他們的先祖娶了 基列人 巴西萊的女兒為妻，所以起名叫 巴西萊。","jì sī zhōng， hā bā yǎ de zǐ sūn, hā gē sī de zǐ sūn, bā xī lái de zǐ sūn； yīn wèi tā men de xiān zǔ qǔ le jī liè rén bā xī lái de nǚ ér wèi qī， suǒ yǐ qǐ míng jiào bā xī lái."],[2,62,"這三家的人在族譜之中尋查自己的譜系，卻尋不着，因此算為不潔，不准供祭司的職任。","zhè sān jiā de rén zài zú pǔ zhī zhōng xún chá zì jǐ de pǔ xì， què xún bù zhe， yīn cǐ suàn wèi bù jié， bù zhǔn gōng jì sī de zhí rèn."],[2,63,"省長對他們說：「不可吃至聖的物，直到有用烏陵和土明決疑的祭司興起來。」","shěng zhǎng duì tā men shuō：‘bù kě chī zhì shèng de wù， zhí dào yǒu yòng wū líng hé tǔ míng jué yí de jì sī xìng qǐ lái.’"],[2,64,"會眾共有四萬二千三百六十名。","huì zhòng gòng yǒu sì wàn èr qiān sān bǎi liù shí míng."],[2,65,"此外，還有他們的僕婢七千三百三十七名，又有歌唱的男女二百名。","cǐ wài， hái yǒu tā men de pú bì qī qiān sān bǎi sān shí qī míng， yòu yǒu gē chàng de nán nǚ èr bǎi míng."],[2,66,"他們有馬七百三十六匹，騾子二百四十五匹，","tā men yǒu mǎ qī bǎi sān shí liù pǐ， luó zǐ èr bǎi sì shí wǔ pǐ，"],[2,67,"駱駝四百三十五隻，驢六千七百二十匹。","luò tuó sì bǎi sān shí wǔ zhī， lǘ liù qiān qī bǎi èr shí pǐ."],[2,68,"有些族長到了 耶路撒冷耶和華殿的地方，便為神的殿甘心獻上禮物，要重新建造。","yǒu xiē zú zhǎng dào le yé lù sā lěng yé hé huá diàn de de fāng， biàn wèi shén de diàn gān xīn xiàn shàng lǐ wù， yào zhòng xīn jiàn zào."],[2,69,"他們量力捐入工程庫的金子六萬一千達利克，銀子五千彌拿，並祭司的禮服一百件。","tā men liàng lì juān rù gōng chéng kù de jīn zǐ liù wàn yī qiān dá lì kè， yín zǐ wǔ qiān mí ná， bìng jì sī de lǐ fú yī bǎi jiàn."],[2,70,"於是祭司、 利未人、民中的一些人、歌唱的、守門的、尼提寧，並 以色列眾人，各住在自己的城裏。","yú shì jì sī, lì wèi rén, mín zhōng de yī xiē rén, gē chàng de, shǒu mén de, ní tí níng， bìng yǐ sè liè zhòng rén， gè zhù zài zì jǐ de chéng lǐ."],[3,1,"到了七月， 以色列人住在各城；那時他們如同一人，聚集在 耶路撒冷。","dào le qī yuè， yǐ sè liè rén zhù zài gè chéng； nà shí tā men rú tóng yī rén， jù jí zài yé lù sā lěng."],[3,2,"約薩達兒子 耶書亞和他的弟兄眾祭司，並 撒拉鐵的兒子 所羅巴伯與他的弟兄，都起來建築 以色列神的壇，要照神人 摩西律法書上所寫的，在壇上獻燔祭。","yuē sà dá ér zǐ yé shū yà hé tā de dì xiōng zhòng jì sī， bìng sā lā tiě de ér zǐ suǒ luó bā bó yǔ tā de dì xiōng， dōu qǐ lái jiàn zhú yǐ sè liè shén de tán， yào zhào shén rén mó xī lǜ fǎ shū shàng suǒ xiě de， zài tán shàng xiàn fán jì."],[3,3,"他們在原有的根基上築壇，因懼怕鄰國的民，又在其上向耶和華早晚獻燔祭，","tā men zài yuán yǒu de gēn jī shàng zhú tán， yīn jù pà lín guó de mín， yòu zài qí shàng xiàng yé hé huá zǎo wǎn xiàn fán jì，"],[3,4,"又照律法書上所寫的守住棚節，按數照例 獻每日所當獻的燔祭；","yòu zhào lǜ fǎ shū shàng suǒ xiě de shǒu zhù péng jié， àn shù zhào lì xiàn měi rì suǒ dāng xiàn de fán jì；"],[3,5,"其後獻常獻的燔祭，並在月朔與耶和華的一切聖節獻祭，又向耶和華獻各人的甘心祭。","qí hòu xiàn cháng xiàn de fán jì， bìng zài yuè shuò yǔ yé hé huá de yī qiè shèng jié xiàn jì， yòu xiàng yé hé huá xiàn gè rén de gān xīn jì."],[3,6,"從七月初一日起，他們就向耶和華獻燔祭。但耶和華殿的根基尚未立定。","cóng qī yuè chū yī rì qǐ， tā men jiù xiàng yé hé huá xiàn fán jì. dàn yé hé huá diàn de gēn jī shàng wèi lì dìng."],[3,7,"他們又將銀子給石匠、木匠，把糧食、酒、油給 西頓人、 泰爾人，使他們將香柏樹從 黎巴嫩運到海裏，浮海運到 約帕，是照 波斯王 塞魯士所允准的。","tā men yòu jiāng yín zǐ gěi shí jiàng, mù jiàng， bǎ liáng shí, jiǔ, yóu gěi xī dùn rén, tài ěr rén， shǐ tā men jiāng xiāng bǎi shù cóng lí bā nèn yùn dào hǎi lǐ， fú hǎi yùn dào yuē pà， shì zhào bō sī wáng sāi lǔ shì suǒ yǔn zhǔn de."],[3,8,"百姓到了 耶路撒冷神殿的地方。第二年二月， 撒拉鐵的兒子 所羅巴伯， 約薩達的兒子 耶書亞和其餘的弟兄，就是祭司、 利未人，並一切被擄歸回 耶路撒冷的人，都興工建造；又派 利未人，從二十歲以外的，督理建造耶和華殿的工作。","bǎi xìng dào le yé lù sā lěng shén diàn de de fāng. dì èr nián èr yuè， sā lā tiě de ér zǐ suǒ luó bā bó， yuē sà dá de ér zǐ yé shū yà hé qí yú de dì xiōng， jiù shì jì sī, lì wèi rén， bìng yī qiè bèi lǔ guī huí yé lù sā lěng de rén， dōu xìng gōng jiàn zào； yòu pài lì wèi rén， cóng èr shí suì yǐ wài de， dū lǐ jiàn zào yé hé huá diàn de gōng zuò."],[3,9,"於是 猶大的後裔，就是 耶書亞和他的子孫與弟兄， 甲篾和他的子孫， 利未人 希拿達的子孫與弟兄，都一同起來，督理那在神殿做工的人。","yú shì yóu dà de hòu yì， jiù shì yé shū yà hé tā de zǐ sūn yǔ dì xiōng， jiǎ miè hé tā de zǐ sūn， lì wèi rén xī ná dá de zǐ sūn yǔ dì xiōng， dōu yī tóng qǐ lái， dū lǐ nà zài shén diàn zuò gōng de rén."],[3,10,"匠人立耶和華殿根基的時候，祭司皆穿禮服吹號， 亞薩的子孫 利未人敲鈸，照 以色列王 大衛所定的例，都站着讚美耶和華。","jiàng rén lì yé hé huá diàn gēn jī de shí hòu， jì sī jiē chuān lǐ fú chuī hào， yà sà de zǐ sūn lì wèi rén qiāo bó， zhào yǐ sè liè wáng dà wèi suǒ dìng de lì， dōu zhàn zhe zàn měi yé hé huá."],[3,11,"他們彼此唱和，讚美稱謝耶和華 說： 他本為善， 他向 以色列人永發慈愛。 他們讚美耶和華的時候，眾民大聲呼喊，因耶和華殿的根基已經立定。","tā men bǐ cǐ chàng hé， zàn měi chēng xiè yé hé huá shuō： tā běn wèi shàn， tā xiàng yǐ sè liè rén yǒng fā cí ài. tā men zàn měi yé hé huá de shí hòu， zhòng mín dà shēng hū hǎn， yīn yé hé huá diàn de gēn jī yǐ jīng lì dìng."],[3,12,"然而有許多祭司、 利未人、族長，就是見過舊殿的老年人，現在親眼看見立這殿的根基，便大聲哭號，也有許多人大聲歡呼，","rán ér yǒu xǔ duō jì sī, lì wèi rén, zú zhǎng， jiù shì jiàn guò jiù diàn de lǎo nián rén， xiàn zài qīn yǎn kàn jiàn lì zhè diàn de gēn jī， biàn dà shēng kū hào， yě yǒu xǔ duō rén dà shēng huān hū，"],[3,13,"甚至百姓不能分辨歡呼的聲音和哭號的聲音；因為眾人大聲呼喊，聲音聽到遠處。","shèn zhì bǎi xìng bù néng fēn biàn huān hū de shēng yīn hé kū hào de shēng yīn； yīn wèi zhòng rén dà shēng hū hǎn， shēng yīn tīng dào yuǎn chù."],[4,1,"猶大和 便雅憫的敵人聽說被擄歸回的人為耶和華－ 以色列的神建造殿宇，","yóu dà hé biàn yǎ mǐn de dí rén tīng shuō bèi lǔ guī huí de rén wèi yé hé huá－ yǐ sè liè de shén jiàn zào diàn yǔ，"],[4,2,"就去見 所羅巴伯和 以色列的族長，對他們說：「請容我們與你們一同建造；因為我們尋求你們的神，與你們一樣。自從 亞述王 以撒哈頓帶我們上這地以來，我們常祭祀神。」","jiù qù jiàn suǒ luó bā bó hé yǐ sè liè de zú zhǎng， duì tā men shuō：‘qǐng róng wǒ men yǔ nǐ men yī tóng jiàn zào； yīn wèi wǒ men xún qiú nǐ men de shén， yǔ nǐ men yī yàng. zì cóng yà shù wáng yǐ sā hā dùn dài wǒ men shàng zhè de yǐ lái， wǒ men cháng jì sì shén.’"],[4,3,"但 所羅巴伯、 耶書亞，和其餘 以色列的族長對他們說：「我們建造神的殿與你們無干，我們自己為耶和華－ 以色列的神協力建造，是照 波斯王 塞魯士所吩咐的。」","dàn suǒ luó bā bó, yé shū yà， hé qí yú yǐ sè liè de zú zhǎng duì tā men shuō：‘wǒ men jiàn zào shén de diàn yǔ nǐ men wú gàn， wǒ men zì jǐ wèi yé hé huá－ yǐ sè liè de shén xié lì jiàn zào， shì zhào bō sī wáng sāi lǔ shì suǒ fēn fù de.’"],[4,4,"那地的民，就在 猶大人建造的時候，使他們的手發軟，擾亂他們；","nà de de mín， jiù zài yóu dà rén jiàn zào de shí hòu， shǐ tā men de shǒu fā ruǎn， rǎo luàn tā men；"],[4,5,"從 波斯王 塞魯士年間，直到 波斯王 大流士登基的時候，賄買謀士，要敗壞他們的謀算。","cóng bō sī wáng sāi lǔ shì nián jiān， zhí dào bō sī wáng dà liú shì dēng jī de shí hòu， huì mǎi móu shì， yào bài huài tā men de móu suàn."],[4,6,"在 亞哈隨魯才登基的時候，上本控告 猶大和 耶路撒冷的居民。","zài yà hā suí lǔ cái dēng jī de shí hòu， shàng běn kòng gào yóu dà hé yé lù sā lěng de jū mín."],[4,7,"亞達薛西年間， 比施蘭、 米特利達、 他別，和他們的同黨上本奏告 波斯王 亞達薛西。本章是用 亞蘭 文字， 亞蘭 方言。","yà dá xuē xī nián jiān， bǐ shī lán, mǐ tè lì dá, tā bié， hé tā men de tóng dǎng shàng běn zòu gào bō sī wáng yà dá xuē xī. běn zhāng shì yòng yà lán wén zì， yà lán fāng yán."],[4,8,"省長 利宏、書記 伸帥要控告 耶路撒冷人，也上本奏告 亞達薛西王。","shěng zhǎng lì hóng, shū jì shēn shuài yào kòng gào yé lù sā lěng rén， yě shàng běn zòu gào yà dá xuē xī wáng."],[4,9,"省長 利宏、書記 伸帥，和同黨的 底拿人、 亞法薩提迦人、 他毗拉人、 亞法撒人、 亞基衛人、 巴比倫人、 書珊迦人、 底亥人、 以攔人，","shěng zhǎng lì hóng, shū jì shēn shuài， hé tóng dǎng de dǐ ná rén, yà fǎ sà tí jiā rén, tā pí lā rén, yà fǎ sā rén, yà jī wèi rén, bā bǐ lún rén, shū shān jiā rén, dǐ hài rén, yǐ lán rén，"],[4,10,"和尊大的 亞斯那巴所遷移、安置在 撒馬利亞城，並大 河西一帶地方的人等，","hé zūn dà de yà sī nà bā suǒ qiān yí, ān zhì zài sā mǎ lì yà chéng， bìng dà hé xī yī dài de fāng de rén děng，"],[4,11,"上奏 亞達薛西王說：「 河西的臣民云云：","shàng zòu yà dá xuē xī wáng shuō：‘ hé xī de chén mín yún yún："],[4,12,"王該知道，從王那裏上到我們這裏的 猶大人，已經到 耶路撒冷重建這反叛惡劣的城，築立根基，建造城牆。","wáng gāi zhī dào， cóng wáng nà lǐ shàng dào wǒ men zhè lǐ de yóu dà rén， yǐ jīng dào yé lù sā lěng zhòng jiàn zhè fǎn pàn è liè de chéng， zhú lì gēn jī， jiàn zào chéng qiáng."],[4,13,"如今王該知道，他們若建造這城，城牆完畢就不再與王進貢，交課，納稅，終久王必受虧損。","rú jīn wáng gāi zhī dào， tā men ruò jiàn zào zhè chéng， chéng qiáng wán bì jiù bù zài yǔ wáng jìn gòng， jiāo kè， nà shuì， zhōng jiǔ wáng bì shòu kuī sǔn."],[4,14,"我們既食御鹽，不忍見王吃虧，因此奏告於王。","wǒ men jì shí yù yán， bù rěn jiàn wáng chī kuī， yīn cǐ zòu gào yú wáng."],[4,15,"請王考察先王的實錄，必在其上查知這城是反叛的城，與列王和各省有害；自古以來，其中常有悖逆的事，因此這城曾被拆毀。","qǐng wáng kǎo chá xiān wáng de shí lù， bì zài qí shàng chá zhī zhè chéng shì fǎn pàn de chéng， yǔ liè wáng hé gè shěng yǒu hài； zì gǔ yǐ lái， qí zhōng cháng yǒu bèi nì de shì， yīn cǐ zhè chéng céng bèi chāi huǐ."],[4,16,"我們謹奏王知，這城若再建造，城牆完畢， 河西之地王就無分了。」","wǒ men jǐn zòu wáng zhī， zhè chéng ruò zài jiàn zào， chéng qiáng wán bì， hé xī zhī de wáng jiù wú fēn le.’"],[4,17,"那時王諭覆省長 利宏、書記 伸帥，和他們的同黨，就是住 撒馬利亞並 河西一帶地方的人，說：「願你們平安云云。","nà shí wáng yù fù shěng zhǎng lì hóng, shū jì shēn shuài， hé tā men de tóng dǎng， jiù shì zhù sā mǎ lì yà bìng hé xī yī dài de fāng de rén， shuō：‘yuàn nǐ men píng ān yún yún."],[4,18,"你們所上的本，已經明讀在我面前。","nǐ men suǒ shàng de běn， yǐ jīng míng dú zài wǒ miàn qián."],[4,19,"我已命人考查，得知此城古來果然背叛列王，其中常有反叛悖逆的事。","wǒ yǐ mìng rén kǎo chá， dé zhī cǐ chéng gǔ lái guǒ rán bèi pàn liè wáng， qí zhōng cháng yǒu fǎn pàn bèi nì de shì."],[4,20,"從前 耶路撒冷也有大君王統管 河西全 地，人就給他們進貢，交課，納稅。","cóng qián yé lù sā lěng yě yǒu dà jūn wáng tǒng guǎn hé xī quán de， rén jiù gěi tā men jìn gòng， jiāo kè， nà shuì."],[4,21,"現在你們要出告示命這些人停工，使這城不得建造，等我降旨。","xiàn zài nǐ men yào chū gào shì mìng zhè xiē rén tíng gōng， shǐ zhè chéng bù dé jiàn zào， děng wǒ jiàng zhǐ."],[4,22,"你們當謹慎，不可遲延，為何容害加重，使王受虧損呢？」","nǐ men dāng jǐn shèn， bù kě chí yán， wèi hé róng hài jiā zhòng， shǐ wáng shòu kuī sǔn ne？’"],[4,23,"亞達薛西王的上諭讀在 利宏和書記 伸帥，並他們的同黨面前，他們就急忙往 耶路撒冷去見 猶大人，用勢力強迫他們停工。","yà dá xuē xī wáng de shàng yù dú zài lì hóng hé shū jì shēn shuài， bìng tā men de tóng dǎng miàn qián， tā men jiù jí máng wǎng yé lù sā lěng qù jiàn yóu dà rén， yòng shì lì qiáng pò tā men tíng gōng."],[4,24,"於是，在 耶路撒冷神殿的工程就停止了，直停到 波斯王 大流士第二年。","yú shì， zài yé lù sā lěng shén diàn de gōng chéng jiù tíng zhǐ le， zhí tíng dào bō sī wáng dà liú shì dì èr nián."],[5,1,"那時，先知 哈該和 易多的孫子 撒迦利亞奉 以色列神的名向 猶大和 耶路撒冷的 猶大人說勸勉的話。","nà shí， xiān zhī hā gāi hé yì duō de sūn zǐ sā jiā lì yà fèng yǐ sè liè shén de míng xiàng yóu dà hé yé lù sā lěng de yóu dà rén shuō quàn miǎn de huà."],[5,2,"於是 撒拉鐵的兒子 所羅巴伯和 約薩達的兒子 耶書亞都起來動手建造 耶路撒冷神的殿，有神的先知在那裏幫助他們。","yú shì sā lā tiě de ér zǐ suǒ luó bā bó hé yuē sà dá de ér zǐ yé shū yà dōu qǐ lái dòng shǒu jiàn zào yé lù sā lěng shén de diàn， yǒu shén de xiān zhī zài nà lǐ bāng zhù tā men."],[5,3,"當時 河西的總督 達乃和 示他‧波斯乃，並他們的同黨來問說：「誰降旨讓你們建造這殿，修成這牆呢？」","dāng shí hé xī de zǒng dū dá nǎi hé shì tā‧bō sī nǎi， bìng tā men de tóng dǎng lái wèn shuō：‘shuí jiàng zhǐ ràng nǐ men jiàn zào zhè diàn， xiū chéng zhè qiáng ne？’"],[5,4,"我們便告訴他們建造這殿的人叫甚麼名字。","wǒ men biàn gào sù tā men jiàn zào zhè diàn de rén jiào shèn me míng zì."],[5,5,"神的眼目看顧 猶大的長老，以致總督等沒有叫他們停工，直到這事奏告 大流士，得着他的回諭。","shén de yǎn mù kàn gù yóu dà de zhǎng lǎo， yǐ zhì zǒng dū děng méi yǒu jiào tā men tíng gōng， zhí dào zhè shì zòu gào dà liú shì， dé zhe tā de huí yù."],[5,6,"河西的總督 達乃和 示他‧波斯乃，並他們的同黨，就是住 河西的 亞法薩迦人，上本奏告 大流士王。","hé xī de zǒng dū dá nǎi hé shì tā‧bō sī nǎi， bìng tā men de tóng dǎng， jiù shì zhù hé xī de yà fǎ sà jiā rén， shàng běn zòu gào dà liú shì wáng."],[5,7,"本上寫着說：「願 大流士王諸事平安。","běn shàng xiě zhe shuō：‘yuàn dà liú shì wáng zhū shì píng ān."],[5,8,"王該知道，我們往 猶大省去，到了至大神的殿，這殿是用大石建造的。樑木插入牆內，工作甚速，他們手下亨通。","wáng gāi zhī dào， wǒ men wǎng yóu dà shěng qù， dào le zhì dà shén de diàn， zhè diàn shì yòng dà shí jiàn zào de. liáng mù chā rù qiáng nèi， gōng zuò shèn sù， tā men shǒu xià hēng tōng."],[5,9,"我們就問那些長老說：『誰降旨讓你們建造這殿，修成這牆呢？』","wǒ men jiù wèn nà xiē zhǎng lǎo shuō：“shuí jiàng zhǐ ràng nǐ men jiàn zào zhè diàn， xiū chéng zhè qiáng ne？”"],[5,10,"又問他們的名字，要記錄他們首領的名字，奏告於王。","yòu wèn tā men de míng zì， yào jì lù tā men shǒu lǐng de míng zì， zòu gào yú wáng."],[5,11,"他們回答說：『我們是天地之神的僕人，重建前多年所建造的殿，就是 以色列的一位大君王建造修成的。","tā men huí dá shuō：“wǒ men shì tiān de zhī shén de pú rén， zhòng jiàn qián duō nián suǒ jiàn zào de diàn， jiù shì yǐ sè liè de yī wèi dà jūn wáng jiàn zào xiū chéng de."],[5,12,"只因我們列祖惹天上的神發怒，神把他們交在 迦勒底人 巴比倫王 尼布甲尼撒的手中，他就拆毀這殿，又將百姓擄到 巴比倫。","zhǐ yīn wǒ men liè zǔ rě tiān shàng de shén fā nù， shén bǎ tā men jiāo zài jiā lēi dǐ rén bā bǐ lún wáng ní bù jiǎ ní sā de shǒu zhōng， tā jiù chāi huǐ zhè diàn， yòu jiāng bǎi xìng lǔ dào bā bǐ lún."],[5,13,"然而 巴比倫王 塞魯士元年，他降旨允准建造神的這殿。","rán ér bā bǐ lún wáng sāi lǔ shì yuán nián， tā jiàng zhǐ yǔn zhǔn jiàn zào shén de zhè diàn."],[5,14,"神殿中的金、銀器皿，就是 尼布甲尼撒從 耶路撒冷的殿中掠去帶到 巴比倫廟裏的， 塞魯士王從 巴比倫廟裏取出來，交給派為省長的，名叫 設巴薩，","shén diàn zhōng de jīn, yín qì mǐn， jiù shì ní bù jiǎ ní sā cóng yé lù sā lěng de diàn zhōng lüè qù dài dào bā bǐ lún miào lǐ de， sāi lǔ shì wáng cóng bā bǐ lún miào lǐ qǔ chū lái， jiāo gěi pài wèi shěng zhǎng de， míng jiào shè bā sà，"],[5,15,"對他說可以將這些器皿帶去，放在 耶路撒冷的殿中，在原處建造神的殿。","duì tā shuō kě yǐ jiāng zhè xiē qì mǐn dài qù， fàng zài yé lù sā lěng de diàn zhōng， zài yuán chù jiàn zào shén de diàn."],[5,16,"於是這 設巴薩來建立 耶路撒冷神殿的根基。這殿從那時直到如今尚未造成。』","yú shì zhè shè bā sà lái jiàn lì yé lù sā lěng shén diàn de gēn jī. zhè diàn cóng nà shí zhí dào rú jīn shàng wèi zào chéng.”"],[5,17,"現在王若以為美，請察 巴比倫王的府庫，看 塞魯士王降旨允准在 耶路撒冷建造神的殿沒有，王的心意如何？請降旨曉諭我們。」","xiàn zài wáng ruò yǐ wèi měi， qǐng chá bā bǐ lún wáng de fǔ kù， kàn sāi lǔ shì wáng jiàng zhǐ yǔn zhǔn zài yé lù sā lěng jiàn zào shén de diàn méi yǒu， wáng de xīn yì rú hé？ qǐng jiàng zhǐ xiǎo yù wǒ men.’"],[6,1,"於是 大流士王降旨，要尋察典籍庫內，就是在 巴比倫藏寶物之處；","yú shì dà liú shì wáng jiàng zhǐ， yào xún chá diǎn jí kù nèi， jiù shì zài bā bǐ lún cáng bǎo wù zhī chù；"],[6,2,"在 米底亞省 亞馬他城的宮內尋得一卷，其中記着說：","zài mǐ dǐ yà shěng yà mǎ tā chéng de gōng nèi xún dé yī juǎn， qí zhōng jì zhe shuō："],[6,3,"「 塞魯士王元年，他降旨論到 耶路撒冷神的殿，要建造這殿為獻祭之處，堅立殿的根基。殿高六十肘，寬六十肘，","‘ sāi lǔ shì wáng yuán nián， tā jiàng zhǐ lùn dào yé lù sā lěng shén de diàn， yào jiàn zào zhè diàn wèi xiàn jì zhī chù， jiān lì diàn de gēn jī. diàn gāo liù shí zhǒu， kuān liù shí zhǒu，"],[6,4,"用三層大石頭，一層新木頭，經費要出於王庫；","yòng sān céng dà shí tóu， yī céng xīn mù tóu， jīng fèi yào chū yú wáng kù；"],[6,5,"並且神殿的金銀器皿，就是 尼布甲尼撒從 耶路撒冷的殿中掠到 巴比倫的，要歸還帶到 耶路撒冷的殿中，各按原處放在神的殿裏。」","bìng qiě shén diàn de jīn yín qì mǐn， jiù shì ní bù jiǎ ní sā cóng yé lù sā lěng de diàn zhōng lüè dào bā bǐ lún de， yào guī hái dài dào yé lù sā lěng de diàn zhōng， gè àn yuán chù fàng zài shén de diàn lǐ.’"],[6,6,"「現在 河西的總督 達乃和 示他‧波斯乃，並你們的同黨，就是住 河西的 亞法薩迦人，你們當遠離他們。","‘xiàn zài hé xī de zǒng dū dá nǎi hé shì tā‧bō sī nǎi， bìng nǐ men de tóng dǎng， jiù shì zhù hé xī de yà fǎ sà jiā rén， nǐ men dāng yuǎn lí tā men."],[6,7,"不要攔阻神殿的工作，任憑 猶大人的省長和 猶大人的長老在原處建造神的這殿。","bù yào lán zǔ shén diàn de gōng zuò， rèn píng yóu dà rén de shěng zhǎng hé yóu dà rén de zhǎng lǎo zài yuán chù jiàn zào shén de zhè diàn."],[6,8,"我又降旨，吩咐你們向 猶大人的長老為建造神的殿當怎樣行，就是從 河西的款項中，急速撥取貢銀作他們的經費，免得耽誤工作。","wǒ yòu jiàng zhǐ， fēn fù nǐ men xiàng yóu dà rén de zhǎng lǎo wèi jiàn zào shén de diàn dāng zěn yàng xíng， jiù shì cóng hé xī de kuǎn xiàng zhōng， jí sù bō qǔ gòng yín zuò tā men de jīng fèi， miǎn dé dān wù gōng zuò."],[6,9,"他們與天上的神獻燔祭所需用的公牛犢、公綿羊、綿羊羔，並所用的麥子、鹽、酒、油，都要照 耶路撒冷祭司的話，每日供給他們，不得有誤；","tā men yǔ tiān shàng de shén xiàn fán jì suǒ xū yòng de gōng niú dú, gōng mián yáng, mián yáng gāo， bìng suǒ yòng de mài zǐ, yán, jiǔ, yóu， dōu yào zhào yé lù sā lěng jì sī de huà， měi rì gōng gěi tā men， bù dé yǒu wù；"],[6,10,"好叫他們獻馨香的祭給天上的神，又為王和王眾子的壽命祈禱。","hǎo jiào tā men xiàn xīn xiāng de jì gěi tiān shàng de shén， yòu wèi wáng hé wáng zhòng zǐ de shòu mìng qí dǎo."],[6,11,"我再降旨，無論誰更改這命令，必從他房屋中拆出一根樑來，把他舉起，懸在其上，又使他的房屋成為糞堆。","wǒ zài jiàng zhǐ， wú lùn shuí gèng gǎi zhè mìng lìng， bì cóng tā fáng wū zhōng chāi chū yī gēn liáng lái， bǎ tā jǔ qǐ， xuán zài qí shàng， yòu shǐ tā de fáng wū chéng wèi fèn duī."],[6,12,"若有王和民伸手更改這 命令，拆毀這殿，願那使 耶路撒冷的殿作為他名居所的神將他們滅絕。我－ 大流士降這旨意，當速速遵行。」","ruò yǒu wáng hé mín shēn shǒu gèng gǎi zhè mìng lìng， chāi huǐ zhè diàn， yuàn nà shǐ yé lù sā lěng de diàn zuò wèi tā míng jū suǒ de shén jiāng tā men miè jué. wǒ－ dà liú shì jiàng zhè zhǐ yì， dāng sù sù zūn xíng.’"],[6,13,"於是， 河西總督 達乃和 示他‧波斯乃，並他們的同黨，因 大流士王所發的命令，就急速遵行。","yú shì， hé xī zǒng dū dá nǎi hé shì tā‧bō sī nǎi， bìng tā men de tóng dǎng， yīn dà liú shì wáng suǒ fā de mìng lìng， jiù jí sù zūn xíng."],[6,14,"猶大長老因先知 哈該和 易多的孫子 撒迦利亞所說勸勉的話就建造這殿，凡事亨通。他們遵着 以色列神的命令和 波斯王 塞魯士、 大流士、 亞達薛西的旨意，建造完畢。","yóu dà zhǎng lǎo yīn xiān zhī hā gāi hé yì duō de sūn zǐ sā jiā lì yà suǒ shuō quàn miǎn de huà jiù jiàn zào zhè diàn， fán shì hēng tōng. tā men zūn zhe yǐ sè liè shén de mìng lìng hé bō sī wáng sāi lǔ shì, dà liú shì, yà dá xuē xī de zhǐ yì， jiàn zào wán bì."],[6,15,"大流士王第六年，亞達月初三日，這殿修成了。","dà liú shì wáng dì liù nián， yà dá yuè chū sān rì， zhè diàn xiū chéng le."],[6,16,"以色列的祭司和 利未人，並其餘被擄歸回的人都歡歡喜喜地行奉獻神殿的禮。","yǐ sè liè de jì sī hé lì wèi rén， bìng qí yú bèi lǔ guī huí de rén dōu huān huān xǐ xǐ de xíng fèng xiàn shén diàn de lǐ."],[6,17,"行奉獻神殿的禮就獻公牛一百隻，公綿羊二百隻，綿羊羔四百隻，又照 以色列支派的數目獻公山羊十二隻，為 以色列眾人作贖罪祭；","xíng fèng xiàn shén diàn de lǐ jiù xiàn gōng niú yī bǎi zhī， gōng mián yáng èr bǎi zhī， mián yáng gāo sì bǎi zhī， yòu zhào yǐ sè liè zhī pài de shù mù xiàn gōng shān yáng shí èr zhī， wèi yǐ sè liè zhòng rén zuò shú zuì jì；"],[6,18,"且派祭司和 利未人按着班次在 耶路撒冷事奉神，是照 摩西 律法書上所寫的。","qiě pài jì sī hé lì wèi rén àn zhe bān cì zài yé lù sā lěng shì fèng shén， shì zhào mó xī lǜ fǎ shū shàng suǒ xiě de."],[6,19,"正月十四日，被擄歸回的人守逾越節。","zhèng yuè shí sì rì， bèi lǔ guī huí de rén shǒu yú yuè jié."],[6,20,"原來，祭司和 利未人一同自潔，無一人不潔淨。 利未人為被擄歸回的眾人和他們的弟兄眾祭司，並為自己宰逾越節 的羊羔。","yuán lái， jì sī hé lì wèi rén yī tóng zì jié， wú yī rén bù jié jìng. lì wèi rén wèi bèi lǔ guī huí de zhòng rén hé tā men de dì xiōng zhòng jì sī， bìng wèi zì jǐ zǎi yú yuè jié de yáng gāo."],[6,21,"從擄到之地歸回的 以色列人和一切除掉所染外邦人污穢、歸附他們、要尋求耶和華－ 以色列神的人都吃 這羊羔，","cóng lǔ dào zhī de guī huí de yǐ sè liè rén hé yī qiè chú diào suǒ rǎn wài bāng rén wū huì, guī fù tā men, yào xún qiú yé hé huá－ yǐ sè liè shén de rén dōu chī zhè yáng gāo，"],[6,22,"歡歡喜喜地守除酵節七日；因為耶和華使他們歡喜，又使 亞述王的心轉向他們，堅固他們的手，作 以色列神殿的工程。","huān huān xǐ xǐ de shǒu chú jiào jié qī rì； yīn wèi yé hé huá shǐ tā men huān xǐ， yòu shǐ yà shù wáng de xīn zhuǎn xiàng tā men， jiān gù tā men de shǒu， zuò yǐ sè liè shén diàn de gōng chéng."],[7,1,"這事以後， 波斯王 亞達薛西年間，有個 以斯拉，他是 西萊雅的兒子， 西萊雅是 亞撒利雅的兒子， 亞撒利雅是 希勒家的兒子，","zhè shì yǐ hòu， bō sī wáng yà dá xuē xī nián jiān， yǒu gè yǐ sī lā， tā shì xī lái yǎ de ér zǐ， xī lái yǎ shì yà sā lì yǎ de ér zǐ， yà sā lì yǎ shì xī lēi jiā de ér zǐ，"],[7,2,"希勒家是 沙龍的兒子， 沙龍是 撒督的兒子， 撒督是 亞希突的兒子，","xī lēi jiā shì shā lóng de ér zǐ， shā lóng shì sā dū de ér zǐ， sā dū shì yà xī tū de ér zǐ，"],[7,3,"亞希突是 亞瑪利雅的兒子， 亞瑪利雅是 亞撒利雅的兒子， 亞撒利雅是 米拉約的兒子，","yà xī tū shì yà mǎ lì yǎ de ér zǐ， yà mǎ lì yǎ shì yà sā lì yǎ de ér zǐ， yà sā lì yǎ shì mǐ lā yuē de ér zǐ，"],[7,4,"米拉約是 西拉希雅的兒子， 西拉希雅是 烏西的兒子， 烏西是 布基的兒子，","mǐ lā yuē shì xī lā xī yǎ de ér zǐ， xī lā xī yǎ shì wū xī de ér zǐ， wū xī shì bù jī de ér zǐ，"],[7,5,"布基是 亞比書的兒子， 亞比書是 非尼哈的兒子， 非尼哈是 以利亞撒的兒子， 以利亞撒是大祭司 亞倫的兒子。","bù jī shì yà bǐ shū de ér zǐ， yà bǐ shū shì fēi ní hā de ér zǐ， fēi ní hā shì yǐ lì yà sā de ér zǐ， yǐ lì yà sā shì dà jì sī yà lún de ér zǐ."],[7,6,"這 以斯拉從 巴比倫上來，他是敏捷的文士，通達耶和華－ 以色列神所賜 摩西的律法書。王允准他一切所求的，是因耶和華－他神的手幫助他。","zhè yǐ sī lā cóng bā bǐ lún shàng lái， tā shì mǐn jié de wén shì， tōng dá yé hé huá－ yǐ sè liè shén suǒ cì mó xī de lǜ fǎ shū. wáng yǔn zhǔn tā yī qiè suǒ qiú de， shì yīn yé hé huá－tā shén de shǒu bāng zhù tā."],[7,7,"亞達薛西王第七年， 以色列人、祭司、 利未人、歌唱的、守門的、尼提寧，有上 耶路撒冷的。","yà dá xuē xī wáng dì qī nián， yǐ sè liè rén, jì sī, lì wèi rén, gē chàng de, shǒu mén de, ní tí níng， yǒu shàng yé lù sā lěng de."],[7,8,"王第七年五月， 以斯拉到了 耶路撒冷。","wáng dì qī nián wǔ yuè， yǐ sī lā dào le yé lù sā lěng."],[7,9,"正月初一日，他從 巴比倫起程；因他神施恩的手幫助他，五月初一日就到了 耶路撒冷。","zhèng yuè chū yī rì， tā cóng bā bǐ lún qǐ chéng； yīn tā shén shī ēn de shǒu bāng zhù tā， wǔ yuè chū yī rì jiù dào le yé lù sā lěng."],[7,10,"以斯拉定志考究遵行耶和華的律法，又將律例典章教訓 以色列人。","yǐ sī lā dìng zhì kǎo jiū zūn xíng yé hé huá de lǜ fǎ， yòu jiāng lǜ lì diǎn zhāng jiào xùn yǐ sè liè rén."],[7,11,"祭司 以斯拉是通達耶和華誡命和賜 以色列之律例的文士。 亞達薛西王賜給他們諭旨，上面寫着說：","jì sī yǐ sī lā shì tōng dá yé hé huá jiè mìng hé cì yǐ sè liè zhī lǜ lì de wén shì. yà dá xuē xī wáng cì gěi tā men yù zhǐ， shàng miàn xiě zhe shuō："],[7,12,"「諸王之王 亞達薛西，達於祭司 以斯拉通達天上神律法大德的文士，云云。","‘zhū wáng zhī wáng yà dá xuē xī， dá yú jì sī yǐ sī lā tōng dá tiān shàng shén lǜ fǎ dà dé de wén shì， yún yún."],[7,13,"住在我國中的 以色列人、祭司、 利未人，凡甘心上 耶路撒冷去的，我降旨准他們與你同去。","zhù zài wǒ guó zhōng de yǐ sè liè rén, jì sī, lì wèi rén， fán gān xīn shàng yé lù sā lěng qù de， wǒ jiàng zhǐ zhǔn tā men yǔ nǐ tóng qù."],[7,14,"王與七個謀士既然差你去，照你手中神的律法書察問 猶大和 耶路撒冷的景況；","wáng yǔ qī gè móu shì jì rán chà nǐ qù， zhào nǐ shǒu zhōng shén de lǜ fǎ shū chá wèn yóu dà hé yé lù sā lěng de jǐng kuàng；"],[7,15,"又帶金銀，就是王和謀士甘心獻給住 耶路撒冷、 以色列神的，","yòu dài jīn yín， jiù shì wáng hé móu shì gān xīn xiàn gěi zhù yé lù sā lěng, yǐ sè liè shén de，"],[7,16,"並帶你在 巴比倫全省所得的金銀，和百姓、祭司樂意獻給 耶路撒冷－他們神殿的禮物。","bìng dài nǐ zài bā bǐ lún quán shěng suǒ dé de jīn yín， hé bǎi xìng, jì sī lè yì xiàn gěi yé lù sā lěng－tā men shén diàn de lǐ wù."],[7,17,"所以你當用這金銀，急速買公牛、公綿羊、綿羊羔，和同獻的素祭奠祭之物，獻在 耶路撒冷－你們神殿的壇上。","suǒ yǐ nǐ dāng yòng zhè jīn yín， jí sù mǎi gōng niú, gōng mián yáng, mián yáng gāo， hé tóng xiàn de sù jì diàn jì zhī wù， xiàn zài yé lù sā lěng－nǐ men shén diàn de tán shàng."],[7,18,"剩下的金銀，你和你的弟兄看着怎樣好，就怎樣用，總要遵着你們神的旨意。","shèng xià de jīn yín， nǐ hé nǐ de dì xiōng kàn zhe zěn yàng hǎo， jiù zěn yàng yòng， zǒng yào zūn zhe nǐ men shén de zhǐ yì."],[7,19,"所交給你神殿中使用的器皿，你要交在 耶路撒冷神面前。","suǒ jiāo gěi nǐ shén diàn zhōng shǐ yòng de qì mǐn， nǐ yào jiāo zài yé lù sā lěng shén miàn qián."],[7,20,"你神殿裏若再有需用的經費，你可以從王的府庫裏支取。","nǐ shén diàn lǐ ruò zài yǒu xū yòng de jīng fèi， nǐ kě yǐ cóng wáng de fǔ kù lǐ zhī qǔ."],[7,21,"「我－ 亞達薛西王又降旨與 河西的一切庫官，說：『通達天上神律法的文士祭司 以斯拉，無論向你們要甚麼，你們要速速地備辦，","‘wǒ－ yà dá xuē xī wáng yòu jiàng zhǐ yǔ hé xī de yī qiè kù guān， shuō：“tōng dá tiān shàng shén lǜ fǎ de wén shì jì sī yǐ sī lā， wú lùn xiàng nǐ men yào shèn me， nǐ men yào sù sù de bèi bàn，"],[7,22,"就是銀子直到一百他連得，麥子一百柯珥，酒一百罷特，油一百罷特，鹽不計其數，也要給他。","jiù shì yín zǐ zhí dào yī bǎi tā lián dé， mài zǐ yī bǎi kē ěr， jiǔ yī bǎi bà tè， yóu yī bǎi bà tè， yán bù jì qí shù， yě yào gěi tā."],[7,23,"凡天上之神所吩咐的，當為天上神的殿詳細辦理。為何使忿怒臨到王和王眾子的國呢？","fán tiān shàng zhī shén suǒ fēn fù de， dāng wèi tiān shàng shén de diàn xiáng xì bàn lǐ. wèi hé shǐ fèn nù lín dào wáng hé wáng zhòng zǐ de guó ne？"],[7,24,"我又曉諭你們，至於祭司、 利未人、歌唱的、守門的，和尼提寧，並在神殿當差的人，不可叫他們進貢，交課，納稅。』","wǒ yòu xiǎo yù nǐ men， zhì yú jì sī, lì wèi rén, gē chàng de, shǒu mén de， hé ní tí níng， bìng zài shén diàn dāng chà de rén， bù kě jiào tā men jìn gòng， jiāo kè， nà shuì.”"],[7,25,"「 以斯拉啊，要照着你神賜你的智慧，將所有明白你神律法的人立為士師、審判官，治理 河西的百姓，使他們教訓一切不明白 神律法的人。","‘ yǐ sī lā a， yào zhào zhe nǐ shén cì nǐ de zhì huì， jiāng suǒ yǒu míng bái nǐ shén lǜ fǎ de rén lì wèi shì shī, shěn pàn guān， zhì lǐ hé xī de bǎi xìng， shǐ tā men jiào xùn yī qiè bù míng bái shén lǜ fǎ de rén."],[7,26,"凡不遵行你神律法和王命令的人就當速速定他的罪，或治死，或充軍，或抄家，或囚禁。」","fán bù zūn xíng nǐ shén lǜ fǎ hé wáng mìng lìng de rén jiù dāng sù sù dìng tā de zuì， huò zhì sǐ， huò chōng jūn， huò chāo jiā， huò qiú jìn.’"],[7,27,"以斯拉說：「耶和華－我們列祖的神是應當稱頌的！因他使王起這心意修飾 耶路撒冷耶和華的殿，","yǐ sī lā shuō：‘yé hé huá－wǒ men liè zǔ de shén shì yīng dāng chēng sòng de！ yīn tā shǐ wáng qǐ zhè xīn yì xiū shì yé lù sā lěng yé hé huá de diàn，"],[7,28,"又在王和謀士，並大能的軍長面前施恩於我。因耶和華－我神的手幫助我，我就得以堅強，從 以色列中招聚首領，與我一同上來。」","yòu zài wáng hé móu shì， bìng dà néng de jūn zhǎng miàn qián shī ēn yú wǒ. yīn yé hé huá－wǒ shén de shǒu bāng zhù wǒ， wǒ jiù dé yǐ jiān qiáng， cóng yǐ sè liè zhōng zhāo jù shǒu lǐng， yǔ wǒ yī tóng shàng lái.’"],[8,1,"當 亞達薛西王年間，同我從 巴比倫上來的人，他們的族長和他們的家譜記在下面：","dāng yà dá xuē xī wáng nián jiān， tóng wǒ cóng bā bǐ lún shàng lái de rén， tā men de zú zhǎng hé tā men de jiā pǔ jì zài xià miàn："],[8,2,"屬 非尼哈的子孫有 革順；屬 以他瑪的子孫有 但以理；屬 大衛的子孫有 哈突；","shǔ fēi ní hā de zǐ sūn yǒu gé shùn； shǔ yǐ tā mǎ de zǐ sūn yǒu dàn yǐ lǐ； shǔ dà wèi de zǐ sūn yǒu hā tū；"],[8,3,"屬 巴錄的後裔，就是 示迦尼的子孫有 撒迦利亞，同着他，按家譜計算，男丁一百五十人；","shǔ bā lù de hòu yì， jiù shì shì jiā ní de zǐ sūn yǒu sā jiā lì yà， tóng zhe tā， àn jiā pǔ jì suàn， nán dīng yī bǎi wǔ shí rén；"],[8,4,"屬 巴哈‧摩押的子孫有 西拉希雅的兒子 以利約乃，同着他有男丁二百；","shǔ bā hā‧mó yā de zǐ sūn yǒu xī lā xī yǎ de ér zǐ yǐ lì yuē nǎi， tóng zhe tā yǒu nán dīng èr bǎi；"],[8,5,"屬 示迦尼的子孫有 雅哈悉的兒子，同着他有男丁三百；","shǔ shì jiā ní de zǐ sūn yǒu yǎ hā xī de ér zǐ， tóng zhe tā yǒu nán dīng sān bǎi；"],[8,6,"屬 亞丁的子孫有 約拿單的兒子 以別，同着他有男丁五十；","shǔ yà dīng de zǐ sūn yǒu yuē ná dān de ér zǐ yǐ bié， tóng zhe tā yǒu nán dīng wǔ shí；"],[8,7,"屬 以攔的子孫有 亞他利雅的兒子 耶篩亞，同着他有男丁七十；","shǔ yǐ lán de zǐ sūn yǒu yà tā lì yǎ de ér zǐ yé shāi yà， tóng zhe tā yǒu nán dīng qī shí；"],[8,8,"屬 示法提雅的子孫有 米迦勒的兒子 西巴第雅，同着他有男丁八十；","shǔ shì fǎ tí yǎ de zǐ sūn yǒu mǐ jiā lēi de ér zǐ xī bā dì yǎ， tóng zhe tā yǒu nán dīng bā shí；"],[8,9,"屬 約押的子孫有 耶歇的兒子 俄巴底亞，同着他有男丁二百一十八；","shǔ yuē yā de zǐ sūn yǒu yé xiē de ér zǐ é bā dǐ yà， tóng zhe tā yǒu nán dīng èr bǎi yī shí bā；"],[8,10,"屬 示羅密的子孫有 約細斐的兒子，同着他有男丁一百六十；","shǔ shì luó mì de zǐ sūn yǒu yuē xì fěi de ér zǐ， tóng zhe tā yǒu nán dīng yī bǎi liù shí；"],[8,11,"屬 比拜的子孫有 比拜的兒子 撒迦利亞，同着他有男丁二十八；","shǔ bǐ bài de zǐ sūn yǒu bǐ bài de ér zǐ sā jiā lì yà， tóng zhe tā yǒu nán dīng èr shí bā；"],[8,12,"屬 押甲的子孫有 哈加坦的兒子 約哈難，同着他有男丁一百一十；","shǔ yā jiǎ de zǐ sūn yǒu hā jiā tǎn de ér zǐ yuē hā nán， tóng zhe tā yǒu nán dīng yī bǎi yī shí；"],[8,13,"屬 亞多尼干的子孫，就是末尾的，他們的名字是 以利法列、 耶利、 示瑪雅，同着他們有男丁六十；","shǔ yà duō ní gàn de zǐ sūn， jiù shì mò wěi de， tā men de míng zì shì yǐ lì fǎ liè, yé lì, shì mǎ yǎ， tóng zhe tā men yǒu nán dīng liù shí；"],[8,14,"屬 比革瓦伊的子孫有 烏太和 撒布，同着他們有男丁七十。","shǔ bǐ gé wǎ yī de zǐ sūn yǒu wū tài hé sā bù， tóng zhe tā men yǒu nán dīng qī shí."],[8,15,"我招聚這些人在流入 亞哈瓦的河邊，我們在那裏住了三日。我查看百姓和祭司，見沒有 利未人在那裏，","wǒ zhāo jù zhè xiē rén zài liú rù yà hā wǎ de hé biān， wǒ men zài nà lǐ zhù le sān rì. wǒ chá kàn bǎi xìng hé jì sī， jiàn méi yǒu lì wèi rén zài nà lǐ，"],[8,16,"就召首領 以利以謝、 亞列、 示瑪雅、 以利拿單、 雅立、 以利拿單、 拿單、 撒迦利亞、 米書蘭，又召教習 約雅立和 以利拿單。","jiù zhào shǒu lǐng yǐ lì yǐ xiè, yà liè, shì mǎ yǎ, yǐ lì ná dān, yǎ lì, yǐ lì ná dān, ná dān, sā jiā lì yà, mǐ shū lán， yòu zhào jiào xí yuē yǎ lì hé yǐ lì ná dān."],[8,17,"我打發他們往 迦西斐雅地方去見那裏的首領 易多，又告訴他們當向 易多和他的弟兄尼提寧說甚麼話，叫他們為我們神的殿帶使用的人來。","wǒ dǎ fā tā men wǎng jiā xī fěi yǎ de fāng qù jiàn nà lǐ de shǒu lǐng yì duō， yòu gào sù tā men dāng xiàng yì duō hé tā de dì xiōng ní tí níng shuō shèn me huà， jiào tā men wèi wǒ men shén de diàn dài shǐ yòng de rén lái."],[8,18,"蒙我們神施恩的手幫助我們，他們在 以色列的曾孫、 利未的孫子、 抹利的後裔中帶一個通達人來；還有 示利比和他的眾子與弟兄共一十八人。","méng wǒ men shén shī ēn de shǒu bāng zhù wǒ men， tā men zài yǐ sè liè de céng sūn, lì wèi de sūn zǐ, mǒ lì de hòu yì zhōng dài yī gè tōng dá rén lái； hái yǒu shì lì bǐ hé tā de zhòng zǐ yǔ dì xiōng gòng yī shí bā rén."],[8,19,"又有 哈沙比雅，同着他有 米拉利的子孫 耶篩亞，並他的眾子和弟兄共二十人。","yòu yǒu hā shā bǐ yǎ， tóng zhe tā yǒu mǐ lā lì de zǐ sūn yé shāi yà， bìng tā de zhòng zǐ hé dì xiōng gòng èr shí rén."],[8,20,"從前 大衛和眾首領派尼提寧服事 利未人，現在從這尼提寧中也帶了二百二十人來，都是按名指定的。","cóng qián dà wèi hé zhòng shǒu lǐng pài ní tí níng fú shì lì wèi rén， xiàn zài cóng zhè ní tí níng zhōng yě dài le èr bǎi èr shí rén lái， dōu shì àn míng zhǐ dìng de."],[8,21,"那時，我在 亞哈瓦河邊宣告禁食，為要在我們神面前克苦己心，求他使我們和 婦人孩子，並一切所有的，都得平坦的道路。","nà shí， wǒ zài yà hā wǎ hé biān xuān gào jìn shí， wèi yào zài wǒ men shén miàn qián kè kǔ jǐ xīn， qiú tā shǐ wǒ men hé fù rén hái zǐ， bìng yī qiè suǒ yǒu de， dōu dé píng tǎn de dào lù."],[8,22,"我求王撥步兵馬兵幫助我們抵擋路上的仇敵，本以為羞恥；因我曾對王說：「我們神施恩的手必幫助一切尋求他的；但他的能力和忿怒必攻擊一切離棄他的。」","wǒ qiú wáng bō bù bīng mǎ bīng bāng zhù wǒ men dǐ dǎng lù shàng de chóu dí， běn yǐ wèi xiū chǐ； yīn wǒ céng duì wáng shuō：‘wǒ men shén shī ēn de shǒu bì bāng zhù yī qiè xún qiú tā de； dàn tā de néng lì hé fèn nù bì gōng jī yī qiè lí qì tā de.’"],[8,23,"所以我們禁食祈求我們的神，他就應允了我們。","suǒ yǐ wǒ men jìn shí qí qiú wǒ men de shén， tā jiù yīng yǔn le wǒ men."],[8,24,"我分派祭司長十二人，就是 示利比、 哈沙比雅，和他們的弟兄十人，","wǒ fēn pài jì sī zhǎng shí èr rén， jiù shì shì lì bǐ, hā shā bǐ yǎ， hé tā men de dì xiōng shí rén，"],[8,25,"將王和謀士、軍長，並在那裏的 以色列眾人為我們神殿所獻的金銀和器皿，都秤了交給他們。","jiāng wáng hé móu shì, jūn zhǎng， bìng zài nà lǐ de yǐ sè liè zhòng rén wèi wǒ men shén diàn suǒ xiàn de jīn yín hé qì mǐn， dōu chèng le jiāo gěi tā men."],[8,26,"我秤了交在他們手中的銀子有六百五十他連得；銀器重一百他連得；金子一百他連得；","wǒ chèng le jiāo zài tā men shǒu zhōng de yín zǐ yǒu liù bǎi wǔ shí tā lián dé； yín qì zhòng yī bǎi tā lián dé； jīn zǐ yī bǎi tā lián dé；"],[8,27,"金碗二十個，重一千達利克；上等光銅的器皿兩個，寶貴如金。","jīn wǎn èr shí gè， zhòng yī qiān dá lì kè； shàng děng guāng tóng de qì mǐn liǎng gè， bǎo guì rú jīn."],[8,28,"我對他們說：「你們歸耶和華為聖，器皿也為聖；金銀是甘心獻給耶和華－你們列祖之神的。","wǒ duì tā men shuō：‘nǐ men guī yé hé huá wèi shèng， qì mǐn yě wèi shèng； jīn yín shì gān xīn xiàn gěi yé hé huá－nǐ men liè zǔ zhī shén de."],[8,29,"你們當警醒看守，直到你們在 耶路撒冷耶和華殿的庫內，在祭司長和 利未族長，並 以色列的各族長面前過了秤。」","nǐ men dāng jǐng xǐng kàn shǒu， zhí dào nǐ men zài yé lù sā lěng yé hé huá diàn de kù nèi， zài jì sī zhǎng hé lì wèi zú zhǎng， bìng yǐ sè liè de gè zú zhǎng miàn qián guò le chèng.’"],[8,30,"於是，祭司、 利未人按着分量接受金銀和器皿，要帶到 耶路撒冷我們神的殿裏。","yú shì， jì sī, lì wèi rén àn zhe fēn liàng jiē shòu jīn yín hé qì mǐn， yào dài dào yé lù sā lěng wǒ men shén de diàn lǐ."],[8,31,"正月十二日，我們從 亞哈瓦河邊起行，要往 耶路撒冷去。我們神的手保佑我們，救我們脫離仇敵和路上埋伏之人的手。","zhèng yuè shí èr rì， wǒ men cóng yà hā wǎ hé biān qǐ xíng， yào wǎng yé lù sā lěng qù. wǒ men shén de shǒu bǎo yòu wǒ men， jiù wǒ men tuō lí chóu dí hé lù shàng mái fú zhī rén de shǒu."],[8,32,"我們到了 耶路撒冷，在那裏住了三日。","wǒ men dào le yé lù sā lěng， zài nà lǐ zhù le sān rì."],[8,33,"第四日，在我們神的殿裏把金銀和器皿都秤了，交在祭司 烏利亞的兒子 米利末的手中。同着他有 非尼哈的兒子 以利亞撒，還有 利未人 耶書亞的兒子 約撒拔和 賓內的兒子 挪亞底。","dì sì rì， zài wǒ men shén de diàn lǐ bǎ jīn yín hé qì mǐn dōu chèng le， jiāo zài jì sī wū lì yà de ér zǐ mǐ lì mò de shǒu zhōng. tóng zhe tā yǒu fēi ní hā de ér zǐ yǐ lì yà sā， hái yǒu lì wèi rén yé shū yà de ér zǐ yuē sā bá hé bīn nèi de ér zǐ nuó yà dǐ."],[8,34,"當時都點了數目，按着分量寫在冊上。","dāng shí dōu diǎn le shù mù， àn zhe fēn liàng xiě zài cè shàng."],[8,35,"從擄到之地歸回的人向 以色列的神獻燔祭，就是為 以色列眾人獻公牛十二隻，公綿羊九十六隻，綿羊羔七十七隻，又獻公山羊十二隻作贖罪祭，這都是向耶和華焚獻的。","cóng lǔ dào zhī de guī huí de rén xiàng yǐ sè liè de shén xiàn fán jì， jiù shì wèi yǐ sè liè zhòng rén xiàn gōng niú shí èr zhī， gōng mián yáng jiǔ shí liù zhī， mián yáng gāo qī shí qī zhī， yòu xiàn gōng shān yáng shí èr zhī zuò shú zuì jì， zhè dōu shì xiàng yé hé huá fén xiàn de."],[8,36,"他們將王的諭旨交給王所派的總督與 河西的省長，他們就幫助百姓，又供給神殿裏所需用的。","tā men jiāng wáng de yù zhǐ jiāo gěi wáng suǒ pài de zǒng dū yǔ hé xī de shěng zhǎng， tā men jiù bāng zhù bǎi xìng， yòu gōng gěi shén diàn lǐ suǒ xū yòng de."],[9,1,"這事做完了，眾首領來見我，說：「 以色列民和祭司並 利未人，沒有離絕 迦南人、 赫人、 比利洗人、 耶布斯人、 亞捫人、 摩押人、 埃及人、 亞摩利人，仍效法這些國的民，行可憎的事。","zhè shì zuò wán le， zhòng shǒu lǐng lái jiàn wǒ， shuō：‘ yǐ sè liè mín hé jì sī bìng lì wèi rén， méi yǒu lí jué jiā nán rén, hè rén, bǐ lì xǐ rén, yé bù sī rén, yà mén rén, mó yā rén, āi jí rén, yà mó lì rén， réng xiào fǎ zhè xiē guó de mín， xíng kě zēng de shì."],[9,2,"因他們為自己和兒子娶了這些外邦女子為妻，以致聖潔的種類和這些國的民混雜；而且首領和官長在這事上為罪魁。」","yīn tā men wèi zì jǐ hé ér zǐ qǔ le zhè xiē wài bāng nǚ zǐ wèi qī， yǐ zhì shèng jié de zhǒng lèi hé zhè xiē guó de mín hùn zá； ér qiě shǒu lǐng hé guān zhǎng zài zhè shì shàng wèi zuì kuí.’"],[9,3,"我一聽見這事，就撕裂衣服和外袍，拔了頭髮和鬍鬚，驚懼憂悶而坐。","wǒ yī tīng jiàn zhè shì， jiù sī liè yī fú hé wài páo， bá le tóu fà hé hú xū， jīng jù yōu mèn ér zuò."],[9,4,"凡為 以色列神言語戰兢的，都因這被擄歸回之人所犯的罪聚集到我這裏來。我就驚懼憂悶而坐，直到獻晚祭的時候。","fán wèi yǐ sè liè shén yán yǔ zhàn jīng de， dōu yīn zhè bèi lǔ guī huí zhī rén suǒ fàn de zuì jù jí dào wǒ zhè lǐ lái. wǒ jiù jīng jù yōu mèn ér zuò， zhí dào xiàn wǎn jì de shí hòu."],[9,5,"獻晚祭的時候我起來，心中愁苦，穿着撕裂的衣袍，雙膝跪下向耶和華－我的神舉手，","xiàn wǎn jì de shí hòu wǒ qǐ lái， xīn zhōng chóu kǔ， chuān zhe sī liè de yī páo， shuāng xī guì xià xiàng yé hé huá－wǒ de shén jǔ shǒu，"],[9,6,"說：「我的神啊，我抱愧蒙羞，不敢向我神仰面；因為我們的罪孽滅頂，我們的罪惡滔天。","shuō：‘wǒ de shén a， wǒ bào kuì méng xiū， bù gǎn xiàng wǒ shén yǎng miàn； yīn wèi wǒ men de zuì niè miè dǐng， wǒ men de zuì è tāo tiān."],[9,7,"從我們列祖直到今日，我們的罪惡甚重；因我們的罪孽，我們和君王、祭司都交在外邦列王的手中，殺害、擄掠、搶奪、臉上蒙羞正如今日的光景。","cóng wǒ men liè zǔ zhí dào jīn rì， wǒ men de zuì è shèn zhòng； yīn wǒ men de zuì niè， wǒ men hé jūn wáng, jì sī dōu jiāo zài wài bāng liè wáng de shǒu zhōng， shā hài, lǔ lüè, qiǎng duó, liǎn shàng méng xiū zhèng rú jīn rì de guāng jǐng."],[9,8,"現在耶和華－我們的神暫且施恩與我們，給我們留些逃脫的人，使我們 安穩如釘子釘在他的聖所，我們的神好光照我們的眼目，使我們在受轄制之中稍微復興。","xiàn zài yé hé huá－wǒ men de shén zàn qiě shī ēn yǔ wǒ men， gěi wǒ men liú xiē táo tuō de rén， shǐ wǒ men ān wěn rú dīng zǐ dīng zài tā de shèng suǒ， wǒ men de shén hǎo guāng zhào wǒ men de yǎn mù， shǐ wǒ men zài shòu xiá zhì zhī zhōng shāo wēi fù xìng."],[9,9,"我們是奴僕，然而在受轄制之中，我們的神仍沒有丟棄我們，在 波斯王眼前向我們施恩，叫我們復興，能重建我們神的殿，修其毀壞之處，使我們在 猶大和 耶路撒冷有牆垣。","wǒ men shì nú pú， rán ér zài shòu xiá zhì zhī zhōng， wǒ men de shén réng méi yǒu diū qì wǒ men， zài bō sī wáng yǎn qián xiàng wǒ men shī ēn， jiào wǒ men fù xìng， néng zhòng jiàn wǒ men shén de diàn， xiū qí huǐ huài zhī chù， shǐ wǒ men zài yóu dà hé yé lù sā lěng yǒu qiáng yuán."],[9,10,"「我們的神啊，既是如此，我們還有甚麼話可說呢？因為我們已經離棄你的命令，","‘wǒ men de shén a， jì shì rú cǐ， wǒ men hái yǒu shèn me huà kě shuō ne？ yīn wèi wǒ men yǐ jīng lí qì nǐ de mìng lìng，"],[9,11,"就是你藉你僕人眾先知所吩咐的說：『你們要去得為業之地是污穢之地；因列國之民的污穢和可憎的事，叫全地從這邊直到那邊滿了污穢。","jiù shì nǐ jí nǐ pú rén zhòng xiān zhī suǒ fēn fù de shuō：“nǐ men yào qù dé wèi yè zhī de shì wū huì zhī de； yīn liè guó zhī mín de wū huì hé kě zēng de shì， jiào quán de cóng zhè biān zhí dào nà biān mǎn le wū huì."],[9,12,"所以不可將你們的女兒嫁他們的兒子，也不可為你們的兒子娶他們的女兒，永不可求他們的平安和他們的利益，這樣你們就可以強盛，吃這地的美物，並遺留這地給你們的子孫永遠為業。』","suǒ yǐ bù kě jiāng nǐ men de nǚ ér jià tā men de ér zǐ， yě bù kě wèi nǐ men de ér zǐ qǔ tā men de nǚ ér， yǒng bù kě qiú tā men de píng ān hé tā men de lì yì， zhè yàng nǐ men jiù kě yǐ qiáng shèng， chī zhè de de měi wù， bìng yí liú zhè de gěi nǐ men de zǐ sūn yǒng yuǎn wèi yè.”"],[9,13,"神啊，我們因自己的惡行和大罪，遭遇了這一切的事，並且你刑罰我們輕於我們罪所當得的，又給我們留下這些人。","shén a， wǒ men yīn zì jǐ de è xíng hé dà zuì， zāo yù le zhè yī qiè de shì， bìng qiě nǐ xíng fá wǒ men qīng yú wǒ men zuì suǒ dāng dé de， yòu gěi wǒ men liú xià zhè xiē rén."],[9,14,"我們豈可再違背你的命令，與這行可憎之事的民結親呢？ 若這樣行，你豈不向我們發怒，將我們滅絕，以致沒有一個剩下逃脫的人嗎？","wǒ men qǐ kě zài wéi bèi nǐ de mìng lìng， yǔ zhè xíng kě zēng zhī shì de mín jié qīn ne？ ruò zhè yàng xíng， nǐ qǐ bù xiàng wǒ men fā nù， jiāng wǒ men miè jué， yǐ zhì méi yǒu yī gè shèng xià táo tuō de rén ma？"],[9,15,"耶和華－ 以色列的神啊，因你是公義的，我們這剩下的人才得逃脫，正如今日的光景。看哪，我們在你面前有罪惡，因此無人在你面前站立得住。」","yé hé huá－ yǐ sè liè de shén a， yīn nǐ shì gōng yì de， wǒ men zhè shèng xià de rén cái dé táo tuō， zhèng rú jīn rì de guāng jǐng. kàn nǎ， wǒ men zài nǐ miàn qián yǒu zuì è， yīn cǐ wú rén zài nǐ miàn qián zhàn lì dé zhù.’"],[10,1,"以斯拉禱告，認罪，哭泣，俯伏在神殿前的時候，有 以色列中的男女孩童聚集到 以斯拉那裏，成了大會，眾民無不痛哭。","yǐ sī lā dǎo gào， rèn zuì， kū qì， fǔ fú zài shén diàn qián de shí hòu， yǒu yǐ sè liè zhōng de nán nǚ hái tóng jù jí dào yǐ sī lā nà lǐ， chéng le dà huì， zhòng mín wú bù tòng kū."],[10,2,"屬 以攔的子孫、 耶歇的兒子 示迦尼對 以斯拉說：「我們在此地娶了外邦女子為妻，干犯了我們的神，然而 以色列人還有指望。","shǔ yǐ lán de zǐ sūn, yé xiē de ér zǐ shì jiā ní duì yǐ sī lā shuō：‘wǒ men zài cǐ de qǔ le wài bāng nǚ zǐ wèi qī， gàn fàn le wǒ men de shén， rán ér yǐ sè liè rén hái yǒu zhǐ wàng."],[10,3,"現在當與我們的神立約，休這一切的妻，離絕她們所生的，照着我主和那因神命令戰兢之人所議定的，按律法而行。","xiàn zài dāng yǔ wǒ men de shén lì yuē， xiū zhè yī qiè de qī， lí jué tā men suǒ shēng de， zhào zhe wǒ zhǔ hé nà yīn shén mìng lìng zhàn jīng zhī rén suǒ yì dìng de， àn lǜ fǎ ér xíng."],[10,4,"你起來，這是你當辦的事，我們必幫助你，你當奮勉而行。」","nǐ qǐ lái， zhè shì nǐ dāng bàn de shì， wǒ men bì bāng zhù nǐ， nǐ dāng fèn miǎn ér xíng.’"],[10,5,"以斯拉便起來，使祭司長和 利未人，並 以色列眾人起誓說，必照這話去行；他們就起了誓。","yǐ sī lā biàn qǐ lái， shǐ jì sī zhǎng hé lì wèi rén， bìng yǐ sè liè zhòng rén qǐ shì shuō， bì zhào zhè huà qù xíng； tā men jiù qǐ le shì."],[10,6,"以斯拉從神殿前起來，進入 以利亞實的兒子 約哈難的屋裏，到了那裏不吃飯，也不喝水；因為被擄歸回之人所犯的罪，心裏悲傷。","yǐ sī lā cóng shén diàn qián qǐ lái， jìn rù yǐ lì yà shí de ér zǐ yuē hā nán de wū lǐ， dào le nà lǐ bù chī fàn， yě bù hē shuǐ； yīn wèi bèi lǔ guī huí zhī rén suǒ fàn de zuì， xīn lǐ bēi shāng."],[10,7,"他們通告 猶大和 耶路撒冷被擄歸回的人，叫他們在 耶路撒冷聚集。","tā men tōng gào yóu dà hé yé lù sā lěng bèi lǔ guī huí de rén， jiào tā men zài yé lù sā lěng jù jí."],[10,8,"凡不遵首領和長老所議定、三日之內不來的，就必抄他的家，使他離開被擄歸回之人的會。","fán bù zūn shǒu lǐng hé zhǎng lǎo suǒ yì dìng, sān rì zhī nèi bù lái de， jiù bì chāo tā de jiā， shǐ tā lí kāi bèi lǔ guī huí zhī rén de huì."],[10,9,"於是， 猶大和 便雅憫眾人，三日之內都聚集在 耶路撒冷。那日正是九月二十日，眾人都坐在神殿前的寬闊處；因這事，又因下大雨，就都戰兢。","yú shì， yóu dà hé biàn yǎ mǐn zhòng rén， sān rì zhī nèi dōu jù jí zài yé lù sā lěng. nà rì zhèng shì jiǔ yuè èr shí rì， zhòng rén dōu zuò zài shén diàn qián de kuān kuò chù； yīn zhè shì， yòu yīn xià dà yǔ， jiù dōu zhàn jīng."],[10,10,"祭司 以斯拉站起來，對他們說：「你們有罪了；因你們娶了外邦的女子為妻，增添 以色列人的罪惡。","jì sī yǐ sī lā zhàn qǐ lái， duì tā men shuō：‘nǐ men yǒu zuì le； yīn nǐ men qǔ le wài bāng de nǚ zǐ wèi qī， zēng tiān yǐ sè liè rén de zuì è."],[10,11,"現在當向耶和華－你們列祖的神認罪，遵行他的旨意，離絕這些國的民和外邦的女子。」","xiàn zài dāng xiàng yé hé huá－nǐ men liè zǔ de shén rèn zuì， zūn xíng tā de zhǐ yì， lí jué zhè xiē guó de mín hé wài bāng de nǚ zǐ.’"],[10,12,"會眾都大聲回答說：「我們必照着你的話行，","huì zhòng dōu dà shēng huí dá shuō：‘wǒ men bì zhào zhe nǐ de huà xíng，"],[10,13,"只是百姓眾多，又逢大雨的時令，我們不能站在外頭，這也不是一兩天辦完的事，因我們在這事上犯了大罪；","zhǐ shì bǎi xìng zhòng duō， yòu féng dà yǔ de shí lìng， wǒ men bù néng zhàn zài wài tóu， zhè yě bù shì yī liǎng tiān bàn wán de shì， yīn wǒ men zài zhè shì shàng fàn le dà zuì；"],[10,14,"不如為全會眾派首領辦理。凡我們城邑中娶外邦女子為妻的，當按所定的日期，同着本城的長老和士師而來，直到辦完這事，神的烈怒就轉離我們了。」","bù rú wèi quán huì zhòng pài shǒu lǐng bàn lǐ. fán wǒ men chéng yì zhōng qǔ wài bāng nǚ zǐ wèi qī de， dāng àn suǒ dìng de rì qī， tóng zhe běn chéng de zhǎng lǎo hé shì shī ér lái， zhí dào bàn wán zhè shì， shén de liè nù jiù zhuǎn lí wǒ men le.’"],[10,15,"惟有 亞撒黑的兒子 約拿單， 特瓦的兒子 雅哈謝阻擋這事，並有 米書蘭和 利未人 沙比太幫助他們。","wéi yǒu yà sā hēi de ér zǐ yuē ná dān， tè wǎ de ér zǐ yǎ hā xiè zǔ dǎng zhè shì， bìng yǒu mǐ shū lán hé lì wèi rén shā bǐ tài bāng zhù tā men."],[10,16,"被擄歸回的人如此而行。祭司 以斯拉和些族長按着宗族都指名見派；在十月初一日，一同在座查辦這事，","bèi lǔ guī huí de rén rú cǐ ér xíng. jì sī yǐ sī lā hé xiē zú zhǎng àn zhe zōng zú dōu zhǐ míng jiàn pài； zài shí yuè chū yī rì， yī tóng zài zuò chá bàn zhè shì，"],[10,17,"到正月初一日，才查清娶外邦女子的人數。","dào zhèng yuè chū yī rì， cái chá qīng qǔ wài bāng nǚ zǐ de rén shù."],[10,18,"在祭司中查出娶外邦女子為妻的，就是 耶書亞的子孫 約薩達的兒子，和他弟兄 瑪西雅、 以利以謝、 雅立、 基大利；","zài jì sī zhōng chá chū qǔ wài bāng nǚ zǐ wèi qī de， jiù shì yé shū yà de zǐ sūn yuē sà dá de ér zǐ， hé tā dì xiōng mǎ xī yǎ, yǐ lì yǐ xiè, yǎ lì, jī dà lì；"],[10,19,"他們便應許必休他們的妻。他們因有罪，就 獻群中的一隻公綿羊贖罪。","tā men biàn yīng xǔ bì xiū tā men de qī. tā men yīn yǒu zuì， jiù xiàn qún zhōng de yī zhī gōng mián yáng shú zuì."],[10,20,"音麥的子孫中，有 哈拿尼、 西巴第雅。","yīn mài de zǐ sūn zhōng， yǒu hā ná ní, xī bā dì yǎ."],[10,21,"哈琳的子孫中，有 瑪西雅、 以利雅、 示瑪雅、 耶歇、 烏西雅。","hā lín de zǐ sūn zhōng， yǒu mǎ xī yǎ, yǐ lì yǎ, shì mǎ yǎ, yé xiē, wū xī yǎ."],[10,22,"巴施戶珥的子孫中，有 以利約乃、 瑪西雅、 以實瑪利、 拿坦業、 約撒拔、 以利亞撒。","bā shī hù ěr de zǐ sūn zhōng， yǒu yǐ lì yuē nǎi, mǎ xī yǎ, yǐ shí mǎ lì, ná tǎn yè, yuē sā bá, yǐ lì yà sā."],[10,23,"利未人中，有 約撒拔、 示每、 基拉雅（ 基拉雅就是 基利他），還有 毗他希雅、 猶大、 以利以謝。","lì wèi rén zhōng， yǒu yuē sā bá, shì měi, jī lā yǎ （ jī lā yǎ jiù shì jī lì tā）， hái yǒu pí tā xī yǎ, yóu dà, yǐ lì yǐ xiè."],[10,24,"歌唱的人中有 以利亞實。守門的人中，有 沙龍、 提聯、 烏利。","gē chàng de rén zhōng yǒu yǐ lì yà shí. shǒu mén de rén zhōng， yǒu shā lóng, tí lián, wū lì."],[10,25,"以色列人 巴錄的子孫中，有 拉米、 耶西雅、 瑪基雅、 米雅民、 以利亞撒、 瑪基雅、 比拿雅。","yǐ sè liè rén bā lù de zǐ sūn zhōng， yǒu lā mǐ, yé xī yǎ, mǎ jī yǎ, mǐ yǎ mín, yǐ lì yà sā, mǎ jī yǎ, bǐ ná yǎ."],[10,26,"以攔的子孫中，有 瑪他尼、 撒迦利亞、 耶歇、 押底、 耶利末、 以利雅。","yǐ lán de zǐ sūn zhōng， yǒu mǎ tā ní, sā jiā lì yà, yé xiē, yā dǐ, yé lì mò, yǐ lì yǎ."],[10,27,"薩土的子孫中，有 以利約乃、 以利亞實、 瑪他尼、 耶利末、 撒拔、 亞西撒。","sà tǔ de zǐ sūn zhōng， yǒu yǐ lì yuē nǎi, yǐ lì yà shí, mǎ tā ní, yé lì mò, sā bá, yà xī sā."],[10,28,"比拜的子孫中，有 約哈難、 哈拿尼雅、 薩拜、 亞勒。","bǐ bài de zǐ sūn zhōng， yǒu yuē hā nán, hā ná ní yǎ, sà bài, yà lēi."],[10,29,"巴尼的子孫中，有 米書蘭、 瑪鹿、 亞大雅、 雅述、 示押、 耶利末。","bā ní de zǐ sūn zhōng， yǒu mǐ shū lán, mǎ lù, yà dà yǎ, yǎ shù, shì yā, yé lì mò."],[10,30,"巴哈‧摩押的子孫中，有 阿底拿、 基拉、 比拿雅、 瑪西雅、 瑪他尼、 比撒列、 賓內、 瑪拿西。","bā hā‧mó yā de zǐ sūn zhōng， yǒu ā dǐ ná, jī lā, bǐ ná yǎ, mǎ xī yǎ, mǎ tā ní, bǐ sā liè, bīn nèi, mǎ ná xī."],[10,31,"哈琳的子孫中，有 以利以謝、 伊示雅、 瑪基雅、 示瑪雅、 西緬、","hā lín de zǐ sūn zhōng， yǒu yǐ lì yǐ xiè, yī shì yǎ, mǎ jī yǎ, shì mǎ yǎ, xī miǎn,"],[10,32,"便雅憫、 瑪鹿、 示瑪利雅。","biàn yǎ mǐn, mǎ lù, shì mǎ lì yǎ."],[10,33,"哈順的子孫中，有 瑪特乃、 瑪達他、 撒拔、 以利法列、 耶利買、 瑪拿西、 示每。","hā shùn de zǐ sūn zhōng， yǒu mǎ tè nǎi, mǎ dá tā, sā bá, yǐ lì fǎ liè, yé lì mǎi, mǎ ná xī, shì měi."],[10,34,"巴尼的子孫中，有 瑪玳、 暗蘭、 烏益、","bā ní de zǐ sūn zhōng， yǒu mǎ dài, àn lán, wū yì,"],[10,35,"比拿雅、 比底雅、 基祿、","bǐ ná yǎ, bǐ dǐ yǎ, jī lù,"],[10,36,"瓦尼雅、 米利末、 以利亞實、","wǎ ní yǎ, mǐ lì mò, yǐ lì yà shí,"],[10,37,"瑪他尼、 瑪特乃、 雅掃、","mǎ tā ní, mǎ tè nǎi, yǎ sǎo,"],[10,38,"巴尼、 賓內、 示每、","bā ní, bīn nèi, shì měi,"],[10,39,"示利米雅、 拿單、 亞大雅、","shì lì mǐ yǎ, ná dān, yà dà yǎ,"],[10,40,"瑪拿底拜、 沙賽、 沙賴、","mǎ ná dǐ bài, shā sài, shā lài,"],[10,41,"亞薩利、 示利米雅、 示瑪利雅、","yà sà lì, shì lì mǐ yǎ, shì mǎ lì yǎ,"],[10,42,"沙龍、 亞瑪利雅、 約瑟。","shā lóng, yà mǎ lì yǎ, yuē sè."],[10,43,"尼波的子孫中，有 耶利、 瑪他提雅、 撒拔、 西比拿、 雅玳、 約珥、 比拿雅。","ní bō de zǐ sūn zhōng， yǒu yé lì, mǎ tā tí yǎ, sā bá, xī bǐ ná, yǎ dài, yuē ěr, bǐ ná yǎ."],[10,44,"這些人都娶了外邦女子為妻，其中也有生了兒女的。","zhè xiē rén dōu qǔ le wài bāng nǚ zǐ wèi qī， qí zhōng yě yǒu shēng le ér nǚ de."]],"arb-vandyck":[[1,1,"وَفِي ٱلسَّنَةِ ٱلْأُولَى لِكُورَشَ مَلِكِ فَارِسَ عِنْدَ تَمَامِ كَلَامِ ٱلرَّبِّ بِفَمِ إِرْمِيَا، نَبَّهَ ٱلرَّبُّ رُوحَ كُورَشَ مَلِكِ فَارِسَ فَأَطْلَقَ نِدَاءً فِي كُلِّ مَمْلَكَتِهِ وَبِالْكِتَابَةِ أَيْضًا قَائِلًا:","wafī ٱlsãnaẗi ٱl̊ạủwlay̱ likūrasẖa maliki fārisa ʿin̊da tamāmi kalāmi ٱlrãbĩ bifami ại̹r̊mīā, nabãha ٱlrãbũ rūḥa kūrasẖa maliki fārisa fāảṭ̊laqa nidāʾaⁿ fī kulĩ mam̊lakatihi wabiạl̊kitābaẗi ạảẙḍaⁿạ qāyỉlaⁿạ:"],[1,2,"«هَكَذَا قَالَ كُورَشُ مَلِكُ فَارِسَ: جَمِيعُ مَمَالِكِ ٱلْأَرْضِ دَفَعَهَا لِي ٱلرَّبُّ إِلَهُ ٱلسَّمَاءِ، وَهُوَ أَوْصَانِي أَنْ أَبْنِيَ لَهُ بَيْتًا فِي أُورُشَلِيمَ ٱلَّتِي فِي يَهُوذَا.","«hakadẖā qāla kūrasẖu maliku fārisa: jamīʿu mamāliki ٱl̊ạảr̊ḍi dafaʿahā lī ٱlrãbũ ại̹lahu ٱlsãmāʾi, wahūa ạảẘṣānī ạản̊ ạảb̊nīa lahu baẙtaⁿạ fī ạủwrusẖalīma ٱlãtī fī yahūdẖā."],[1,3,"مَنْ مِنْكُمْ مِنْ كُلِّ شَعْبِهِ، لِيَكُنْ إِلَهُهُ مَعَهُ، وَيَصْعَدْ إِلَى أُورُشَلِيمَ ٱلَّتِي فِي يَهُوذَا فَيَبْنِيَ بَيْتَ ٱلرَّبِّ إِلَهِ إِسْرَائِيلَ. هُوَ ٱلْإِلَهُ ٱلَّذِي فِي أُورُشَلِيمَ.","man̊ min̊kum̊ min̊ kulĩ sẖaʿ̊bihi, līakun̊ ại̹lahuhu maʿahu, wayaṣ̊ʿad̊ ại̹lay̱ ạủwrusẖalīma ٱlãtī fī yahūdẖā fayab̊nīa baẙta ٱlrãbĩ ại̹lahi ại̹s̊rāyỉyla. hūa ٱl̊ại̹lahu ٱlãdẖī fī ạủwrusẖalīma."],[1,4,"وَكُلُّ مَنْ بَقِيَ فِي أَحَدِ ٱلْأَمَاكِنِ حَيْثُ هُوَ مُتَغَرِّبٌ فَلْيُنْجِدْهُ أَهْلُ مَكَانِهِ بِفِضَّةٍ وَبِذَهَبٍ وَبِأَمْتِعَةٍ وَبِبَهَائِمَ مَعَ ٱلتَّبَرُّعِ لِبَيْتِ ٱلرَّبِّ ٱلَّذِي فِي أُورُشَلِيمَ».","wakulũ man̊ baqīa fī ạảḥadi ٱl̊ạảmākini ḥaẙtẖu hūa mutagẖarĩbuⁿ fal̊yun̊jid̊hu ạảh̊lu makānihi bifiḍãẗiⁿ wabidẖahabiⁿ wabiạảm̊tiʿaẗiⁿ wabibahāyỉma maʿa ٱltãbarũʿi libaẙti ٱlrãbĩ ٱlãdẖī fī ạủwrusẖalīma»."],[1,5,"فَقَامَ رُؤُوسُ آبَاءِ يَهُوذَا وَبَنْيَامِينَ، وَٱلْكَهَنَةُ وَٱللَّاوِيُّونَ، مَعَ كُلِّ مَنْ نَبَّهَ ٱللهُ رُوحَهُ، لِيَصْعَدُوا لِيَبْنُوا بَيْتَ ٱلرَّبِّ ٱلَّذِي فِي أُورُشَلِيمَ.","faqāma rūủwsu ậbāʾi yahūdẖā waban̊yāmīna, waٱl̊kahanaẗu waٱllãạwīũwna, maʿa kulĩ man̊ nabãha ٱllhu rūḥahu, līaṣ̊ʿadūạ līab̊nūạ baẙta ٱlrãbĩ ٱlãdẖī fī ạủwrusẖalīma."],[1,6,"وَكُلُّ ٱلَّذِينَ حَوْلَهُمْ أَعَانُوهُمْ بِآنِيَةِ فِضَّةٍ وَبِذَهَبٍ وَبِأَمْتِعَةٍ وَبِبَهَائِمَ وَبِتُحَفٍ، فَضْلًا عَنْ كُلِّ مَا تُبُرِّعَ بِهِ.","wakulũ ٱlãdẖīna ḥaẘlahum̊ ạảʿānūhum̊ biậnīaẗi fiḍãẗiⁿ wabidẖahabiⁿ wabiạảm̊tiʿaẗiⁿ wabibahāyỉma wabituḥafiⁿ, faḍ̊laⁿạ ʿan̊ kulĩ mā tuburĩʿa bihi."],[1,7,"وَٱلْمَلِكُ كُورَشُ أَخْرَجَ آنِيَةَ بَيْتِ ٱلرَّبِّ ٱلَّتِي أَخْرَجَهَا نَبُوخَذْنَاصَّرُ مِنْ أُورُشَلِيمَ وَجَعَلَهَا فِي بَيْتِ آلِهَتِهِ.","waٱl̊maliku kūrasẖu ạảkẖ̊raja ậnīaẗa baẙti ٱlrãbĩ ٱlãtī ạảkẖ̊rajahā nabūkẖadẖ̊nāṣãru min̊ ạủwrusẖalīma wajaʿalahā fī baẙti ậlihatihi."],[1,8,"أَخْرَجَهَا كُورَشُ مَلِكُ فَارِسَ عَنْ يَدِ مِثْرَدَاثَ ٱلْخَازِنِ، وَعَدَّهَا لِشِيشْبَصَّرَ رَئِيسِ يَهُوذَا.","ạảkẖ̊rajahā kūrasẖu maliku fārisa ʿan̊ yadi mitẖ̊radātẖa ٱl̊kẖāzini, waʿadãhā lisẖīsẖ̊baṣãra rayỉysi yahūdẖā."],[1,9,"وَهَذَا عَدَدُهَا: ثَلَاثُونَ طَسْتًا مِنْ ذَهَبٍ، وَأَلْفُ طَسْتٍ مِنْ فِضَّةٍ، وَتِسْعَةٌ وَعِشْرُونَ سِكِّينًا،","wahadẖā ʿadaduhā: tẖalātẖūna ṭas̊taⁿạ min̊ dẖahabiⁿ, wāảl̊fu ṭas̊tiⁿ min̊ fiḍãẗiⁿ, watis̊ʿaẗuⁿ waʿisẖ̊rūna sikĩynaⁿạ,"],[1,10,"وَثَلَاثُونَ قَدَحًا مِنْ ذَهَبٍ، وَأَقْدَاحُ فِضَّةٍ مِنَ ٱلرُّتْبَةِ ٱلثَّانِيَةِ أَرْبَعُ مِئَةٍ وَعَشَرَةٌ، وَأَلْفٌ مِنْ آنِيَةٍ أُخْرَى.","watẖalātẖūna qadaḥaⁿạ min̊ dẖahabiⁿ, wāảq̊dāḥu fiḍãẗiⁿ mina ٱlrũt̊baẗi ٱltẖãạnīaẗi ạảr̊baʿu mīảẗiⁿ waʿasẖaraẗuⁿ, wāảl̊fuⁿ min̊ ậnīaẗiⁿ ạủkẖ̊ray̱."],[1,11,"جَمِيعُ ٱلْآنِيَةِ مِنَ ٱلذَّهَبِ وَٱلْفِضَّةِ خَمْسَةُ آلَافٍ وَأَرْبَعُ مِئَةٍ. ٱلْكُلُّ أَصْعَدَهُ شِيشْبَصَّرُ عِنْدَ إِصْعَادِ ٱلسَّبْيِ مِنْ بَابِلَ إِلَى أُورُشَلِيمَ.","jamīʿu ٱl̊ậnīaẗi mina ٱldẖãhabi waٱl̊fiḍãẗi kẖam̊saẗu ậlāfiⁿ wāảr̊baʿu mīảẗiⁿ. ٱl̊kulũ ạảṣ̊ʿadahu sẖīsẖ̊baṣãru ʿin̊da ại̹ṣ̊ʿādi ٱlsãb̊yi min̊ bābila ại̹lay̱ ạủwrusẖalīma."],[2,1,"وَهَؤُلَاءِ هُمْ بَنُو ٱلْكُورَةِ ٱلصَّاعِدُونَ مِنْ سَبْيِ ٱلْمَسْبِيِّينَ، ٱلَّذِينَ سَبَاهُمْ نَبُوخَذْنَاصَّرُ مَلِكُ بَابِلَ إِلَى بَابِلَ، وَرَجَعُوا إِلَى أُورُشَلِيمَ وَيَهُوذَا، كُلُّ وَاحِدٍ إِلَى مَدِينَتِهِ.","wahawủlāʾi hum̊ banū ٱl̊kūraẗi ٱlṣãạʿidūna min̊ sab̊yi ٱl̊mas̊bīĩyna, ٱlãdẖīna sabāhum̊ nabūkẖadẖ̊nāṣãru maliku bābila ại̹lay̱ bābila, warajaʿūạ ại̹lay̱ ạủwrusẖalīma wayahūdẖā, kulũ wāḥidiⁿ ại̹lay̱ madīnatihi."],[2,2,"ٱلَّذِينَ جَاءُوا مَعَ زَرُبَّابِلَ، يَشُوعُ، نَحَمْيَا، سَرَايَا، رَعْلَايَا، مُرْدَخَايُ، بِلْشَانُ، مِسْفَارُ، بِغْوَايُ، رَحُومُ، بَعْنَةَ. عَدَدُ رِجَالِ شَعْبِ إِسْرَائِيلَ:","ٱlãdẖīna jāʾūạ maʿa zarubãạbila, yasẖūʿu, naḥam̊yā, sarāyā, raʿ̊lāyā, mur̊dakẖāyu, bil̊sẖānu, mis̊fāru, bigẖ̊wāyu, raḥūmu, baʿ̊naẗa. ʿadadu rijāli sẖaʿ̊bi ại̹s̊rāyỉyla:"],[2,3,"بَنُو فَرْعُوشَ أَلْفَانِ وَمِئَةٌ وَٱثْنَانِ وَسَبْعُونَ.","banū far̊ʿūsẖa ạảl̊fāni wamīảẗuⁿ waٱtẖ̊nāni wasab̊ʿūna."],[2,4,"بَنُو شَفَطْيَا ثَلَاثُ مِئَةٍ وَٱثْنَانِ وَسَبْعُونَ.","banū sẖafaṭ̊yā tẖalātẖu mīảẗiⁿ waٱtẖ̊nāni wasab̊ʿūna."],[2,5,"بَنُو آرَحَ سَبْعُ مِئَةٍ وَخَمْسَةٌ وَسَبْعُونَ.","banū ậraḥa sab̊ʿu mīảẗiⁿ wakẖam̊saẗuⁿ wasab̊ʿūna."],[2,6,"بَنُو فَحَثَ مُوآبَ مِنْ بَنِي يَشُوعَ وَيُوآبَ أَلْفَانِ وَثَمَانُ مِئَةٍ وَٱثْنَا عَشَرَ.","banū faḥatẖa mūậba min̊ banī yasẖūʿa wayūậba ạảl̊fāni watẖamānu mīảẗiⁿ waٱtẖ̊nā ʿasẖara."],[2,7,"بَنُو عِيلَامَ أَلْفٌ وَمِئَتَانِ وَأَرْبَعَةٌ وَخَمْسُونَ.","banū ʿīlāma ạảl̊fuⁿ wamīảtāni wāảr̊baʿaẗuⁿ wakẖam̊sūna."],[2,8,"بَنُو زَتُّو تِسْعُ مِئَةٍ وَخَمْسَةٌ وَأَرْبَعُونَ.","banū zatũw tis̊ʿu mīảẗiⁿ wakẖam̊saẗuⁿ wāảr̊baʿūna."],[2,9,"بَنُو زَكَّايَ سَبْعُ مِئَةٍ وَسِتُّونَ.","banū zakãạya sab̊ʿu mīảẗiⁿ wasitũwna."],[2,10,"بَنُو بَانِي سِتُّ مِئَةٍ وَٱثْنَانِ وَأَرْبَعُونَ.","banū bānī sitũ mīảẗiⁿ waٱtẖ̊nāni wāảr̊baʿūna."],[2,11,"بَنُو بَابَايَ سِتُّ مِئَةٍ وَثَلَاثَةٌ وَعِشْرُونَ.","banū bābāya sitũ mīảẗiⁿ watẖalātẖaẗuⁿ waʿisẖ̊rūna."],[2,12,"بَنُو عَرْجَدَ أَلْفٌ وَمِئَتَانِ وَٱثْنَانِ وَعِشْرُونَ.","banū ʿar̊jada ạảl̊fuⁿ wamīảtāni waٱtẖ̊nāni waʿisẖ̊rūna."],[2,13,"بَنُو أَدُونِيقَامَ سِتُّ مِئَةٍ وَسِتَّةٌ وَسِتُّونَ.","banū ạảdūnīqāma sitũ mīảẗiⁿ wasitãẗuⁿ wasitũwna."],[2,14,"بَنُو بِغْوَايَ أَلْفَانِ وَسِتَّةٌ وَخَمْسُونَ.","banū bigẖ̊wāya ạảl̊fāni wasitãẗuⁿ wakẖam̊sūna."],[2,15,"بَنُو عَادِينَ أَرْبَعُ مِئَةٍ وَأَرْبَعَةٌ وَخَمْسُونَ.","banū ʿādīna ạảr̊baʿu mīảẗiⁿ wāảr̊baʿaẗuⁿ wakẖam̊sūna."],[2,16,"بَنُو آطِيرَ مِنْ يَحَزَقِيَّا ثَمَانِيَةٌ وَتِسْعُونَ.","banū ậṭīra min̊ yaḥazaqīãạ tẖamānīaẗuⁿ watis̊ʿūna."],[2,17,"بَنُو بِيصَايَ ثَلَاثُ مِئَةٍ وَثَلَاثَةٌ وَعِشْرُونَ.","banū bīṣāya tẖalātẖu mīảẗiⁿ watẖalātẖaẗuⁿ waʿisẖ̊rūna."],[2,18,"بَنُو يُورَةَ مِئَةٌ وَٱثْنَا عَشَرَ.","banū yūraẗa mīảẗuⁿ waٱtẖ̊nā ʿasẖara."],[2,19,"بَنُو حَشُومَ مِئَتَانِ وَثَلَاثَةٌ وَعِشْرُونَ.","banū ḥasẖūma mīảtāni watẖalātẖaẗuⁿ waʿisẖ̊rūna."],[2,20,"بَنُو جِبَّارَ خَمْسَةٌ وَتِسْعُونَ.","banū jibãạra kẖam̊saẗuⁿ watis̊ʿūna."],[2,21,"بَنُو بَيْتِ لَحْمٍ مِئَةٌ وَثَلَاثَةٌ وَعِشْرُونَ.","banū baẙti laḥ̊miⁿ mīảẗuⁿ watẖalātẖaẗuⁿ waʿisẖ̊rūna."],[2,22,"رِجَالُ نَطُوفَةَ سِتَّةٌ وَخَمْسُونَ.","rijālu naṭūfaẗa sitãẗuⁿ wakẖam̊sūna."],[2,23,"رِجَالُ عَنَاثُوثَ مِئَةٌ وَثَمَانِيَةٌ وَعِشْرُونَ.","rijālu ʿanātẖūtẖa mīảẗuⁿ watẖamānīaẗuⁿ waʿisẖ̊rūna."],[2,24,"بَنُو عَزْمُوتَ ٱثْنَانِ وَأَرْبَعُونَ.","banū ʿaz̊mūta ٱtẖ̊nāni wāảr̊baʿūna."],[2,25,"بَنُو قَرْيَةِ عَارِيمَ كَفِيرَةَ وَبَئِيرُوتَ سَبْعُ مِئَةٍ وَثَلَاثَةٌ وَأَرْبَعُونَ.","banū qar̊yaẗi ʿārīma kafīraẗa wabayỉyrūta sab̊ʿu mīảẗiⁿ watẖalātẖaẗuⁿ wāảr̊baʿūna."],[2,26,"بَنُو ٱلرَّامَةِ وَجَبَعَ سِتُّ مِئَةٍ وَوَاحِدٌ وَعِشْرُونَ.","banū ٱlrãạmaẗi wajabaʿa sitũ mīảẗiⁿ wawāḥiduⁿ waʿisẖ̊rūna."],[2,27,"رِجَالُ مِخْمَاسَ مِئَةٌ وَٱثْنَانِ وَعِشْرُونَ.","rijālu mikẖ̊māsa mīảẗuⁿ waٱtẖ̊nāni waʿisẖ̊rūna."],[2,28,"رِجَالُ بَيْتِ إِيلَ وَعَايَ مِئَتَانِ وَثَلَاثَةٌ وَعِشْرُونَ.","rijālu baẙti ại̹yla waʿāya mīảtāni watẖalātẖaẗuⁿ waʿisẖ̊rūna."],[2,29,"بَنُو نَبُو ٱثْنَانِ وَخَمْسُونَ.","banū nabū ٱtẖ̊nāni wakẖam̊sūna."],[2,30,"بَنُو مَغْبِيشَ مِئَةٌ وَسِتَّةٌ وَخَمْسُونَ.","banū magẖ̊bīsẖa mīảẗuⁿ wasitãẗuⁿ wakẖam̊sūna."],[2,31,"بَنُو عِيلَامَ ٱلْآخَرِ أَلْفٌ وَمِئَتَانِ وَأَرْبَعَةٌ وَخَمْسُونَ.","banū ʿīlāma ٱl̊ậkẖari ạảl̊fuⁿ wamīảtāni wāảr̊baʿaẗuⁿ wakẖam̊sūna."],[2,32,"بَنُو حَارِيمَ ثَلَاثُ مِئَةٍ وَعِشْرُونَ.","banū ḥārīma tẖalātẖu mīảẗiⁿ waʿisẖ̊rūna."],[2,33,"بَنُو لُودَ بَنُو حَادِيدَ وَأُونُو سَبْعُ مِئَةٍ وَخَمْسَةٌ وَعِشْرُونَ.","banū lūda banū ḥādīda wāủwnū sab̊ʿu mīảẗiⁿ wakẖam̊saẗuⁿ waʿisẖ̊rūna."],[2,34,"بَنُو أَرِيحَا ثَلَاثُ مِئَةٍ وَخَمْسَةٌ وَأَرْبَعُونَ.","banū ạảrīḥā tẖalātẖu mīảẗiⁿ wakẖam̊saẗuⁿ wāảr̊baʿūna."],[2,35,"بَنُو سَنَاءَةَ ثَلَاثَةُ آلَافٍ وَسِتُّ مِئَةٍ وَثَلَاثُونَ.","banū sanāʾaẗa tẖalātẖaẗu ậlāfiⁿ wasitũ mīảẗiⁿ watẖalātẖūna."],[2,36,"أَمَّا ٱلْكَهَنَةُ: فَبَنُو يَدْعِيَا مِنْ بَيْتِ يَشُوعَ تِسْعُ مِئَةٍ وَثَلَاثَةٌ وَسَبْعُونَ.","ạảmãạ ٱl̊kahanaẗu: fabanū yad̊ʿīā min̊ baẙti yasẖūʿa tis̊ʿu mīảẗiⁿ watẖalātẖaẗuⁿ wasab̊ʿūna."],[2,37,"بَنُو إِمِّيرَ أَلْفٌ وَٱثْنَانِ وَخَمْسُونَ.","banū ại̹mĩyra ạảl̊fuⁿ waٱtẖ̊nāni wakẖam̊sūna."],[2,38,"بَنُو فَشْحُورَ أَلْفٌ وَمِئَتَانِ وَسَبْعَةٌ وَأَرْبَعُونَ.","banū fasẖ̊ḥūra ạảl̊fuⁿ wamīảtāni wasab̊ʿaẗuⁿ wāảr̊baʿūna."],[2,39,"بَنُو حَارِيمَ أَلْفٌ وَسَبْعَةَ عَشَرَ.","banū ḥārīma ạảl̊fuⁿ wasab̊ʿaẗa ʿasẖara."],[2,40,"أَمَّا ٱللَّاوِيُّونَ: فَبَنُو يَشُوعَ وَقَدْمِيئِيلَ مِنْ بَنِي هُودُويَا أَرْبَعَةٌ وَسَبْعُونَ.","ạảmãạ ٱllãạwīũwna: fabanū yasẖūʿa waqad̊mīyỉyla min̊ banī hūdūyā ạảr̊baʿaẗuⁿ wasab̊ʿūna."],[2,41,"ٱلْمُغَنُّونَ بَنُو آسَافَ مِئَةٌ وَثَمَانِيَةٌ وَعِشْرُونَ.","ٱl̊mugẖanũwna banū ậsāfa mīảẗuⁿ watẖamānīaẗuⁿ waʿisẖ̊rūna."],[2,42,"بَنُو ٱلْبَوَّابِينَ: بَنُو شَلُّومَ، بَنُو آطِيرَ، بَنُو طَلْمُونَ، بَنُو عَقُّوبَ، بَنُو حَطِيطَا، بَنُو شُوبَايَ، ٱلْجَمِيعُ مِئَةٌ وَتِسْعَةٌ وَثَلَاثُونَ.","banū ٱl̊bawãạbīna: banū sẖalũwma, banū ậṭīra, banū ṭal̊mūna, banū ʿaqũwba, banū ḥaṭīṭā, banū sẖūbāya, ٱl̊jamīʿu mīảẗuⁿ watis̊ʿaẗuⁿ watẖalātẖūna."],[2,43,"ٱلنَّثِينِيمُ: بَنُو صِيحَا، بَنُو حَسُوفَا، بَنُو طَبَاعُوتَ،","ٱlnãtẖīnīmu: banū ṣīḥā, banū ḥasūfā, banū ṭabāʿūta,"],[2,44,"بَنُو قِيرُوسَ، بَنُو سِيعَهَا، بَنُو فَادُونَ،","banū qīrūsa, banū sīʿahā, banū fādūna,"],[2,45,"بَنُو لَبَانَةَ، بَنُو حَجَابَةَ، بَنُو عَقُّوبَ،","banū labānaẗa, banū ḥajābaẗa, banū ʿaqũwba,"],[2,46,"بَنُو حَاجَابَ، بَنُو شَمُلَايَ، بَنُو حَانَانَ،","banū ḥājāba, banū sẖamulāya, banū ḥānāna,"],[2,47,"بَنُو جَدِيلَ، بَنُو حَجَرَ، بَنُو رَآيَا،","banū jadīla, banū ḥajara, banū rā̂yā,"],[2,48,"بَنُو رَصِينَ، بَنُو نَقُودَا، بَنُو جَزَّامَ،","banū raṣīna, banū naqūdā, banū jazãạma,"],[2,49,"بَنُو عُزَّا، بَنُو فَاسِيحَ، بَنُو بِيسَايَ،","banū ʿuzãạ, banū fāsīḥa, banū bīsāya,"],[2,50,"بَنُو أَسْنَةَ، بَنُو مَعُونِيمَ، بَنُو نَفُوسِيمَ،","banū ạảs̊naẗa, banū maʿūnīma, banū nafūsīma,"],[2,51,"بَنُو بَقْبُوقَ، بَنُو حَقُوفَا، بَنُو حَرْحُورَ،","banū baq̊būqa, banū ḥaqūfā, banū ḥar̊ḥūra,"],[2,52,"بَنُو بَصْلُوتَ، بَنُو مَحِيدَا، بَنُو حَرْشَا،","banū baṣ̊lūta, banū maḥīdā, banū ḥar̊sẖā,"],[2,53,"بَنُو بَرْقُوسَ، بَنُو سِيسَرَا، بَنُو ثَامَحَ،","banū bar̊qūsa, banū sīsarā, banū tẖāmaḥa,"],[2,54,"بَنُو نَصِيحَ، بَنُو حَطِيفَا.","banū naṣīḥa, banū ḥaṭīfā."],[2,55,"بَنُو عَبِيدِ سُلَيْمَانَ: بَنُو سَوْطَايَ، بَنُو هَسُّوفَرَثَ، بَنُو فَرُودَا،","banū ʿabīdi sulaẙmāna: banū saẘṭāya, banū hasũwfaratẖa, banū farūdā,"],[2,56,"بَنُو يَعْلَةَ، بَنُو دَرْقُونَ، بَنُو جَدِّيلَ،","banū yaʿ̊laẗa, banū dar̊qūna, banū jadĩyla,"],[2,57,"بَنُو شَفَطْيَا، بَنُو حَطِّيلَ، بَنُو فُوخَرَةِ ٱلظِّبَاءِ، بَنُو آمِي.","banū sẖafaṭ̊yā, banū ḥaṭĩyla, banū fūkẖaraẗi ٱlẓĩbāʾi, banū ậmī."],[2,58,"جَمِيعُ ٱلنَّثِينِيمِ وَبَنِي عَبِيدِ سُلَيْمَانَ ثَلَاثُ مِئَةٍ وَٱثْنَانِ وَتِسْعُونَ.","jamīʿu ٱlnãtẖīnīmi wabanī ʿabīdi sulaẙmāna tẖalātẖu mīảẗiⁿ waٱtẖ̊nāni watis̊ʿūna."],[2,59,"وَهَؤُلَاءِ هُمُ ٱلَّذِينَ صَعِدُوا مِنْ تَلِّ مِلْحٍ وَتَلِّ حَرْشَا، كَرُوبُ، أَدَّانُ، إِمِّيرُ، وَلَمْ يَسْتَطِيعُوا أَنْ يُبَيِّنُوا بُيُوتَ آبَائِهِمْ وَنَسْلَهُمْ هَلْ هُمْ مِنْ إِسْرَائِيلَ:","wahawủlāʾi humu ٱlãdẖīna ṣaʿidūạ min̊ talĩ mil̊ḥiⁿ watalĩ ḥar̊sẖā, karūbu, ạảdãạnu, ại̹mĩyru, walam̊ yas̊taṭīʿūạ ạản̊ yubayĩnūạ buyūta ậbāyỉhim̊ wanas̊lahum̊ hal̊ hum̊ min̊ ại̹s̊rāyỉyla:"],[2,60,"بَنُو دَلَايَا، بَنُو طُوبِيَّا، بَنُو نَقُودَا، سِتُّ مِئَةٍ وَٱثْنَانِ وَخَمْسُونَ.","banū dalāyā, banū ṭūbīãạ, banū naqūdā, sitũ mīảẗiⁿ waٱtẖ̊nāni wakẖam̊sūna."],[2,61,"وَمِنْ بَنِي ٱلْكَهَنَةِ: بَنُو حَبَايَا، بَنُو هَقُّوصَ، بَنُو بَرْزِلَّايَ ٱلَّذِي أَخْذَ ٱمْرَأَةً مِنْ بَنَاتِ بَرْزِلَّايَ ٱلْجِلْعَادِيِّ وَتَسَمَّى بِٱسْمِهِمْ.","wamin̊ banī ٱl̊kahanaẗi: banū ḥabāyā, banū haqũwṣa, banū bar̊zilãạya ٱlãdẖī ạảkẖ̊dẖa ٱm̊rāảẗaⁿ min̊ banāti bar̊zilãạya ٱl̊jil̊ʿādīĩ watasamãy̱ biٱs̊mihim̊."],[2,62,"هَؤُلَاءِ فَتَّشُوا عَلَى كِتَابَةِ أَنْسَابِهِمْ فَلَمْ تُوجَدْ، فَرُذِلُوا مِنَ ٱلْكَهَنُوتِ.","hawủlāʾi fatãsẖūạ ʿalay̱ kitābaẗi ạản̊sābihim̊ falam̊ tūjad̊, farudẖilūạ mina ٱl̊kahanūti."],[2,63,"وَقَالَ لَهُمُ ٱلتِّرْشَاثَا أَنْ لَا يَأْكُلُوا مِنْ قُدْسِ ٱلْأَقْدَاسِ حَتَّى يَقُومَ كَاهِنٌ لِلْأُورِيمِ وَٱلتُّمِّيمِ.","waqāla lahumu ٱltĩr̊sẖātẖā ạản̊ lā yā̊̉kulūạ min̊ qud̊si ٱl̊ạảq̊dāsi ḥatãy̱ yaqūma kāhinuⁿ lil̊ạủwrīmi waٱltũmĩymi."],[2,64,"كُلُّ ٱلْجُمْهُورِ مَعًا ٱثْنَانِ وَأَرْبَعُونَ أَلْفًا وَثَلَاثُ مِئَةٍ وَسِتُّونَ،","kulũ ٱl̊jum̊hūri maʿaⁿạ ٱtẖ̊nāni wāảr̊baʿūna ạảl̊faⁿạ watẖalātẖu mīảẗiⁿ wasitũwna,"],[2,65,"فَضْلًا عَنْ عَبِيدِهِمْ وَإِمَائِهِمْ فَهَؤُلَاءِ كَانُوا سَبْعَةَ آلَافٍ وَثَلَاثَ مِئَةٍ وَسَبْعَةً وَثَلَاثِينَ، وَلَهُمْ مِنَ ٱلْمُغَنِّينَ وَٱلْمُغَنِّيَاتِ مِئَتَانِ.","faḍ̊laⁿạ ʿan̊ ʿabīdihim̊ wāi̹māyỉhim̊ fahawủlāʾi kānūạ sab̊ʿaẗa ậlāfiⁿ watẖalātẖa mīảẗiⁿ wasab̊ʿaẗaⁿ watẖalātẖīna, walahum̊ mina ٱl̊mugẖanĩyna waٱl̊mugẖanĩyāti mīảtāni."],[2,66,"خَيْلُهُمْ سَبْعُ مِئَةٍ وَسِتَّةٌ وَثَلَاثُونَ. بِغَالُهُمْ مِئَتَانِ وَخَمْسَةٌ وَأَرْبَعُونَ.","kẖaẙluhum̊ sab̊ʿu mīảẗiⁿ wasitãẗuⁿ watẖalātẖūna. bigẖāluhum̊ mīảtāni wakẖam̊saẗuⁿ wāảr̊baʿūna."],[2,67,"جِمَالُهُمْ أَرْبَعُ مِئَةٍ وَخَمْسَةٌ وَثَلَاثُونَ. حَمِيرُهُمْ سِتَّةُ آلَافٍ وَسَبْعُ مِئَةٍ وَعِشْرُونَ.","jimāluhum̊ ạảr̊baʿu mīảẗiⁿ wakẖam̊saẗuⁿ watẖalātẖūna. ḥamīruhum̊ sitãẗu ậlāfiⁿ wasab̊ʿu mīảẗiⁿ waʿisẖ̊rūna."],[2,68,"وَٱلْبَعْضُ مِنْ رُؤُوسِ ٱلْآبَاءِ عِنْدَ مَجِيئِهِمْ إِلَى بَيْتِ ٱلرَّبِّ ٱلَّذِي فِي أُورُشَلِيمَ تَبَرَّعُوا لِبَيْتِ ٱلرَّبِّ لِإِقَامَتِهِ فِي مَكَانِهِ.","waٱl̊baʿ̊ḍu min̊ rūủwsi ٱl̊ậbāʾi ʿin̊da majīyỉhim̊ ại̹lay̱ baẙti ٱlrãbĩ ٱlãdẖī fī ạủwrusẖalīma tabarãʿūạ libaẙti ٱlrãbĩ liại̹qāmatihi fī makānihi."],[2,69,"أَعْطَوْا حَسَبَ طَاقَتِهِمْ لِخِزَانَةِ ٱلْعَمَلِ وَاحِدًا وَسِتِّينَ أَلْفَ دِرْهَمٍ مِنَ ٱلذَّهَبِ، وَخَمْسَةَ آلَافِ مَنًا مِنَ ٱلْفِضَّةِ، وَمِئَةَ قَمِيصٍ لِلْكَهَنَةِ.","ạảʿ̊ṭaẘạ ḥasaba ṭāqatihim̊ likẖizānaẗi ٱl̊ʿamali wāḥidaⁿạ wasitĩyna ạảl̊fa dir̊hamiⁿ mina ٱldẖãhabi, wakẖam̊saẗa ậlāfi manaⁿạ mina ٱl̊fiḍãẗi, wamīảẗa qamīṣiⁿ lil̊kahanaẗi."],[2,70,"فَأَقَامَ ٱلْكَهَنَةُ وَٱللَّاوِيُّونَ وَبَعْضُ ٱلشَّعْبِ وَٱلْمُغَنُّونَ وَٱلْبَوَّابُونَ وَٱلنَّثِينِيمُ فِي مُدُنِهِمْ وَكُلُّ إِسْرَائِيلَ فِي مُدُنِهِمْ.","fāảqāma ٱl̊kahanaẗu waٱllãạwīũwna wabaʿ̊ḍu ٱlsẖãʿ̊bi waٱl̊mugẖanũwna waٱl̊bawãạbūna waٱlnãtẖīnīmu fī mudunihim̊ wakulũ ại̹s̊rāyỉyla fī mudunihim̊."],[3,1,"وَلَمَّا ٱسْتُهِلَّ ٱلشَّهْرُ ٱلسَّابِعُ وَبَنُو إِسْرَائِيلَ فِي مُدُنِهِمُ، ٱجْتَمَعَ ٱلشَّعْبُ كَرَجُلٍ وَاحِدٍ إِلَى أُورُشَلِيمَ.","walamãạ ٱs̊tuhilã ٱlsẖãh̊ru ٱlsãạbiʿu wabanū ại̹s̊rāyỉyla fī mudunihimu, ٱj̊tamaʿa ٱlsẖãʿ̊bu karajuliⁿ wāḥidiⁿ ại̹lay̱ ạủwrusẖalīma."],[3,2,"وَقَامَ يَشُوعُ بْنُ يُوصَادَاقَ وَإِخْوَتُهُ ٱلْكَهَنَةُ، وَزَرُبَّابِلُ بْنُ شَأَلْتِئِيلَ وَإِخْوَتُهُ، وَبَنَوْا مَذْبَحَ إِلَهِ إِسْرَائِيلَ لِيُصْعِدُوا عَلَيْهِ مُحْرَقَاتٍ كَمَا هُوَ مَكْتُوبٌ فِي شَرِيعَةِ مُوسَى رَجُلِ ٱللهِ.","waqāma yasẖūʿu b̊nu yūṣādāqa wāi̹kẖ̊watuhu ٱl̊kahanaẗu, wazarubãạbilu b̊nu sẖāảl̊tīỉyla wāi̹kẖ̊watuhu, wabanaẘạ madẖ̊baḥa ại̹lahi ại̹s̊rāyỉyla līuṣ̊ʿidūạ ʿalaẙhi muḥ̊raqātiⁿ kamā hūa mak̊tūbuⁿ fī sẖarīʿaẗi mūsay̱ rajuli ٱllhi."],[3,3,"وَأَقَامُوا ٱلْمَذْبَحَ فِي مَكَانِهِ، لِأَنَّهُ كَانَ عَلَيْهِمْ رُعْبٌ مِنْ شُعُوبِ ٱلْأَرَاضِي، وَأَصْعَدُوا عَلَيْهِ مُحْرَقَاتٍ لِلرَّبِّ، مُحْرَقَاتِ ٱلصَّبَاحِ وَٱلْمَسَاءِ.","wāảqāmūạ ٱl̊madẖ̊baḥa fī makānihi, liạảnãhu kāna ʿalaẙhim̊ ruʿ̊buⁿ min̊ sẖuʿūbi ٱl̊ạảrāḍī, wāảṣ̊ʿadūạ ʿalaẙhi muḥ̊raqātiⁿ lilrãbĩ, muḥ̊raqāti ٱlṣãbāḥi waٱl̊masāʾi."],[3,4,"وَحَفِظُوا عِيدَ ٱلْمَظَالِّ كَمَا هُوَ مَكْتُوبٌ، وَمُحْرَقَةَ يَوْمٍ فَيَوْمٍ بِٱلْعَدَدِ كَٱلْمَرْسُومِ، أَمْرَ ٱلْيَوْمِ بِيَوْمِهِ.","waḥafiẓūạ ʿīda ٱl̊maẓālĩ kamā hūa mak̊tūbuⁿ, wamuḥ̊raqaẗa yaẘmiⁿ fayaẘmiⁿ biٱl̊ʿadadi kaٱl̊mar̊sūmi, ạảm̊ra ٱl̊yaẘmi bīaẘmihi."],[3,5,"وَبَعْدَ ذَلِكَ ٱلْمُحْرَقَةُ ٱلدَّائِمَةُ، وَلِلْأَهِلَّةِ وَلِجَمِيعِ مَوَاسِمِ ٱلرّبِّ ٱلْمُقَدَّسَةِ، وَلِكُلِّ مَن تبرَّعَ بِمُتَبَرَّعٍ لِلرَّبِّ.","wabaʿ̊da dẖalika ٱl̊muḥ̊raqaẗu ٱldãạyỉmaẗu, walil̊ạảhilãẗi walijamīʿi mawāsimi ٱlr̃bĩ ٱl̊muqadãsaẗi, walikulĩ man tbrãʿa bimutabarãʿiⁿ lilrãbĩ."],[3,6,"ٱبْتَدَأُوا مِنَ ٱلْيَوْمِ ٱلْأَوَّلِ مِنَ ٱلشَّهْرِ ٱلسَّابِعِ يُصْعِدُونَ مُحْرَقَاتٍ لِلرَّبِّ، وَهَيْكَلُ ٱلرَّبِّ لَمْ يَكُنْ قَدْ تَأَسَّسَ.","ٱb̊tadāủwạ mina ٱl̊yaẘmi ٱl̊ạảwãli mina ٱlsẖãh̊ri ٱlsãạbiʿi yuṣ̊ʿidūna muḥ̊raqātiⁿ lilrãbĩ, wahaẙkalu ٱlrãbĩ lam̊ yakun̊ qad̊ tāảsãsa."],[3,7,"وَأَعْطَوْا فِضَّةً لِلنَّحَّاتِينَ وَٱلنَّجَّارِينَ، وَمَأْكَلًا وَمَشْرَبًا وَزَيْتًا لِلصِّيدُونِيِّينَ وَٱلصُّورِيِّينَ لِيَأْتُوا بِخَشَبِ أَرْزٍ مِنْ لُبْنَانَ إِلَى بَحْرِ يَافَا، حَسَبَ إِذْنِ كُورَشَ مَلِكِ فَارِسَ لَهُمْ.","wāảʿ̊ṭaẘạ fiḍãẗaⁿ lilnãḥãạtīna waٱlnãjãạrīna, wamā̊̉kalaⁿạ wamasẖ̊rabaⁿạ wazaẙtaⁿạ lilṣĩydūnīĩyna waٱlṣũwrīĩyna līā̊̉tūạ bikẖasẖabi ạảr̊ziⁿ min̊ lub̊nāna ại̹lay̱ baḥ̊ri yāfā, ḥasaba ại̹dẖ̊ni kūrasẖa maliki fārisa lahum̊."],[3,8,"وَفِي ٱلسَّنَةِ ٱلثَّانِيَةِ مِنْ مَجِيئِهِمْ إِلَى بَيْتِ ٱللهِ إِلَى أُورُشَلِيمَ، فِي ٱلشَّهْرِ ٱلثَّانِي، شَرَعَ زَرُبَّابِلُ بْنُ شَأَلْتِئِيلَ وَيَشُوعُ بْنُ يُوصَادَاقَ وَبَقِيَّةُ إِخْوَتِهِمِ ٱلْكَهَنَةِ وَٱللَّاوِيِّينَ وَجَمِيعُ ٱلْقَادِمِينَ مِنَ ٱلسَّبْيِ إِلَى أُورُشَلِيمَ، وَأَقَامُوا ٱللَّاوِيِّينَ مِنِ ٱبْنِ عِشْرِينَ سَنَةً فَمَا فَوْقُ لِلْمُنَاظَرَةِ عَلَى عَمَلِ بَيْتِ ٱلرَّبِّ.","wafī ٱlsãnaẗi ٱltẖãạnīaẗi min̊ majīyỉhim̊ ại̹lay̱ baẙti ٱllhi ại̹lay̱ ạủwrusẖalīma, fī ٱlsẖãh̊ri ٱltẖãạnī, sẖaraʿa zarubãạbilu b̊nu sẖāảl̊tīỉyla wayasẖūʿu b̊nu yūṣādāqa wabaqīãẗu ại̹kẖ̊watihimi ٱl̊kahanaẗi waٱllãạwīĩyna wajamīʿu ٱl̊qādimīna mina ٱlsãb̊yi ại̹lay̱ ạủwrusẖalīma, wāảqāmūạ ٱllãạwīĩyna mini ٱb̊ni ʿisẖ̊rīna sanaẗaⁿ famā faẘqu lil̊munāẓaraẗi ʿalay̱ ʿamali baẙti ٱlrãbĩ."],[3,9,"وَوَقَفَ يَشُوعُ مَعَ بَنِيهِ وَإِخْوَتِهِ، قَدْمِيئِيلَ وَبَنِيهِ بَنِي يَهُوذَا مَعًا لِلْمُنَاظَرَةِ عَلَى عَامِلِي ٱلشُّغْلِ فِي بَيْتِ ٱللهِ، وَبَنِي حِينَادَادَ مَعَ بَنِيهِمْ وَإِخْوَتِهِمِ ٱللَّاوِيِّينَ.","wawaqafa yasẖūʿu maʿa banīhi wāi̹kẖ̊watihi, qad̊mīyỉyla wabanīhi banī yahūdẖā maʿaⁿạ lil̊munāẓaraẗi ʿalay̱ ʿāmilī ٱlsẖũgẖ̊li fī baẙti ٱllhi, wabanī ḥīnādāda maʿa banīhim̊ wāi̹kẖ̊watihimi ٱllãạwīĩyna."],[3,10,"وَلَمَّا أَسَّسَ ٱلْبَانُونَ هَيْكَلَ ٱلرَّبِّ، أَقَامُوا ٱلْكَهَنَةَ بِمَلَابِسِهِمْ بِأَبْوَاقٍ، وَٱللَّاوِيِّينَ بَنِي آسَافَ بِٱلصُّنُوجِ، لِتَسْبِيحِ ٱلرَّبِّ عَلَى تَرْتِيبِ دَاوُدَ مَلِكِ إِسْرَائِيلَ.","walamãạ ạảsãsa ٱl̊bānūna haẙkala ٱlrãbĩ, ạảqāmūạ ٱl̊kahanaẗa bimalābisihim̊ biạảb̊wāqiⁿ, waٱllãạwīĩyna banī ậsāfa biٱlṣũnūji, litas̊bīḥi ٱlrãbĩ ʿalay̱ tar̊tībi dāwuda maliki ại̹s̊rāyỉyla."],[3,11,"وَغَنَّوْا بِٱلتَّسْبِيحِ وَٱلْحَمْدِ لِلرَّبِّ، لِأَنَّهُ صَالِحٌ لِأَنَّ إِلَى ٱلْأَبَدِ رَحْمَتَهُ عَلَى إِسْرَائِيلَ. وَكُلُّ ٱلشَّعْبِ هَتَفُوا هُتَافًا عَظِيمًا بِٱلتَّسْبِيحِ لِلرَّبِّ لِأَجْلِ تَأْسِيسِ بَيْتِ ٱلرَّبِّ.","wagẖanãẘạ biٱltãs̊bīḥi waٱl̊ḥam̊di lilrãbĩ, liạảnãhu ṣāliḥuⁿ liạảnã ại̹lay̱ ٱl̊ạảbadi raḥ̊matahu ʿalay̱ ại̹s̊rāyỉyla. wakulũ ٱlsẖãʿ̊bi hatafūạ hutāfaⁿạ ʿaẓīmaⁿạ biٱltãs̊bīḥi lilrãbĩ liạảj̊li tā̊̉sīsi baẙti ٱlrãbĩ."],[3,12,"وَكَثِيرُونَ مِنَ ٱلْكَهَنَةِ وَٱللَّاوِيِّينَ وَرُؤُوسِ ٱلْآبَاءِ ٱلشُّيُوخِ، ٱلَّذِينَ رَأَوْا ٱلْبَيْتَ ٱلْأَوَّلَ، بَكَوْا بِصَوْتٍ عَظِيمٍ عِنْدَ تَأْسِيسِ هَذَا ٱلْبَيْتِ أَمَامَ أَعْيُنِهِمْ. وَكَثِيرُونَ كَانُوا يَرْفَعُونَ أَصْوَاتَهُمْ بِٱلْهُتَافِ بِفَرَحٍ.","wakatẖīrūna mina ٱl̊kahanaẗi waٱllãạwīĩyna warūủwsi ٱl̊ậbāʾi ٱlsẖũyūkẖi, ٱlãdẖīna rāảẘạ ٱl̊baẙta ٱl̊ạảwãla, bakaẘạ biṣaẘtiⁿ ʿaẓīmiⁿ ʿin̊da tā̊̉sīsi hadẖā ٱl̊baẙti ạảmāma ạảʿ̊yunihim̊. wakatẖīrūna kānūạ yar̊faʿūna ạảṣ̊wātahum̊ biٱl̊hutāfi bifaraḥiⁿ."],[3,13,"وَلَمْ يَكُنِ ٱلشَّعْبُ يُمَيِّزُ هُتَافَ ٱلْفَرَحِ مِنْ صَوْتِ بُكَاءِ ٱلشَّعْبِ، لِأَنَّ ٱلشَّعْبَ كَانَ يَهْتِفُ هُتَافًا عَظِيمًا حَتَّى أَنَّ ٱلصَّوْتَ سُمِعَ مِنْ بُعْدٍ.","walam̊ yakuni ٱlsẖãʿ̊bu yumayĩzu hutāfa ٱl̊faraḥi min̊ ṣaẘti bukāʾi ٱlsẖãʿ̊bi, liạảnã ٱlsẖãʿ̊ba kāna yah̊tifu hutāfaⁿạ ʿaẓīmaⁿạ ḥatãy̱ ạảnã ٱlṣãẘta sumiʿa min̊ buʿ̊diⁿ."],[4,1,"وَلَمَّا سَمِعَ أَعْدَاءُ يَهُوذَا وَبَنْيَامِينَ أَنَّ بَنِي ٱلسَّبْيِ يَبْنُونَ هَيْكَلًا لِلرَّبِّ إِلَهِ إِسْرَائِيلَ،","walamãạ samiʿa ạảʿ̊dāʾu yahūdẖā waban̊yāmīna ạảnã banī ٱlsãb̊yi yab̊nūna haẙkalaⁿạ lilrãbĩ ại̹lahi ại̹s̊rāyỉyla,"],[4,2,"تَقَدَّمُوا إِلَى زَرُبَّابِلَ وَرُؤُوسِ ٱلْآبَاءِ وَقَالُوا لَهُمْ: «نَبْنِي مَعَكُمْ لِأَنَّنَا نَظِيرَكُمْ نَطْلُبُ إِلَهَكُمْ، وَلَهُ قَدْ ذَبَحْنَا مِنْ أَيَّامِ أَسَرْحَدُّونَ مَلِكِ أَشُّورَ ٱلَّذِي أَصْعَدَنَا إِلَى هُنَا».","taqadãmūạ ại̹lay̱ zarubãạbila warūủwsi ٱl̊ậbāʾi waqālūạ lahum̊: «nab̊nī maʿakum̊ liạảnãnā naẓīrakum̊ naṭ̊lubu ại̹lahakum̊, walahu qad̊ dẖabaḥ̊nā min̊ ạảyãạmi ạảsar̊ḥadũwna maliki ạảsẖũwra ٱlãdẖī ạảṣ̊ʿadanā ại̹lay̱ hunā»."],[4,3,"فَقَالَ لَهُمْ زَرُبَّابِلُ وَيَشُوعُ وَبَقِيَّةُ رُؤُوسِ آبَاءِ إِسْرَائِيلَ: «لَيْسَ لَكُمْ وَلَنَا أَنْ نَبْنِيَ بَيْتًا لِإِلَهِنَا، وَلَكِنَّنَا نَحْنُ وَحْدَنَا نَبْنِي لِلرَّبِّ إِلَهِ إِسْرَائِيلَ كَمَا أَمَرَنَا ٱلْمَلِكُ كُورَشُ مَلِكُ فَارِسَ».","faqāla lahum̊ zarubãạbilu wayasẖūʿu wabaqīãẗu rūủwsi ậbāʾi ại̹s̊rāyỉyla: «laẙsa lakum̊ walanā ạản̊ nab̊nīa baẙtaⁿạ liại̹lahinā, walakinãnā naḥ̊nu waḥ̊danā nab̊nī lilrãbĩ ại̹lahi ại̹s̊rāyỉyla kamā ạảmaranā ٱl̊maliku kūrasẖu maliku fārisa»."],[4,4,"وَكَانَ شَعْبُ ٱلْأَرْضِ يُرْخُونَ أَيْدِيَ شَعْبِ يَهُوذَا وَيُذْعِرُونَهُمْ عَنِ ٱلْبِنَاءِ.","wakāna sẖaʿ̊bu ٱl̊ạảr̊ḍi yur̊kẖūna ạảẙdīa sẖaʿ̊bi yahūdẖā wayudẖ̊ʿirūnahum̊ ʿani ٱl̊bināʾi."],[4,5,"وَٱسْتَأْجَرُوا ضِدَّهُمْ مُشِيرِينَ لِيُبْطِلُوا مَشُورَتَهُمْ كُلَّ أَيَّامِ كُورَشَ مَلِكِ فَارِسَ وَحَتَّى مُلْكِ دَارِيُوسَ مَلِكِ فَارِسَ.","waٱs̊tā̊̉jarūạ ḍidãhum̊ musẖīrīna līub̊ṭilūạ masẖūratahum̊ kulã ạảyãạmi kūrasẖa maliki fārisa waḥatãy̱ mul̊ki dārīūsa maliki fārisa."],[4,6,"وَفِي مُلْكِ أَحَشْوِيرُوشَ، فِي ٱبْتِدَاءِ مُلْكِهِ، كَتَبُوا شَكْوَى عَلَى سُكَّانِ يَهُوذَا وَأُورُشَلِيمَ.","wafī mul̊ki ạảḥasẖ̊wīrūsẖa, fī ٱb̊tidāʾi mul̊kihi, katabūạ sẖak̊way̱ ʿalay̱ sukãạni yahūdẖā wāủwrusẖalīma."],[4,7,"وَفِي أَيَّامِ أَرْتَحْشَشْتَا كَتَبَ بِشْلَامُ وَمِثْرَدَاثُ وَطَبْئِيلُ وَسَائِرُ رُفَقَائِهِمْ إِلَى أَرْتَحْشَشْتَا مَلِكِ فَارِسَ. وَكِتَابَةُ ٱلرِّسَالَةِ مَكْتُوبَةٌ بِٱلْأَرَامِيَّةِ وَمُتَرْجَمَةٌ بِٱلْأَرَامِيَّةِ.","wafī ạảyãạmi ạảr̊taḥ̊sẖasẖ̊tā kataba bisẖ̊lāmu wamitẖ̊radātẖu waṭab̊yỉylu wasāyỉru rufaqāyỉhim̊ ại̹lay̱ ạảr̊taḥ̊sẖasẖ̊tā maliki fārisa. wakitābaẗu ٱlrĩsālaẗi mak̊tūbaẗuⁿ biٱl̊ạảrāmīãẗi wamutar̊jamaẗuⁿ biٱl̊ạảrāmīãẗi."],[4,8,"رَحُومُ صَاحِبُ ٱلْقَضَاءِ وَشِمْشَايُ ٱلْكَاتِبُ كَتَبَا رِسَالَةً ضِدَّ أُورُشَلِيمَ إِلَى أَرْتَحْشَشْتَا ٱلْمَلِكِ هَكَذَا:","raḥūmu ṣāḥibu ٱl̊qaḍāʾi wasẖim̊sẖāyu ٱl̊kātibu katabā risālaẗaⁿ ḍidã ạủwrusẖalīma ại̹lay̱ ạảr̊taḥ̊sẖasẖ̊tā ٱl̊maliki hakadẖā:"],[4,9,"كَتَبَ حِينَئِذٍ رَحُومُ صَاحِبُ ٱلْقَضَاءِ وَشِمْشَايُ ٱلْكَاتِبُ وَسَائِرُ رُفَقَائِهِمَا ٱلدِّينِيِّينَ وَٱلْأَفَرَسْتِكِيِّينَ وَٱلطَّرْفِلِيِّينَ وَٱلْأَفْرَسِيِّينَ وَٱلْأَرَكْوِيِّينَ وَٱلْبَابِلِيِّينَ وَٱلشُّوشَنِيِّينَ وَٱلدَّهْوِيِّينَ وَٱلْعِيلَامِيِّينَ،","kataba ḥīnayỉdẖiⁿ raḥūmu ṣāḥibu ٱl̊qaḍāʾi wasẖim̊sẖāyu ٱl̊kātibu wasāyỉru rufaqāyỉhimā ٱldĩynīĩyna waٱl̊ạảfaras̊tikīĩyna waٱlṭãr̊filīĩyna waٱl̊ạảf̊rasīĩyna waٱl̊ạảrak̊wīĩyna waٱl̊bābilīĩyna waٱlsẖũwsẖanīĩyna waٱldãh̊wīĩyna waٱl̊ʿīlāmīĩyna,"],[4,10,"وَسَائِرِ ٱلْأُمَمِ ٱلَّذِينَ سَبَاهُمْ أُسْنَفَّرُ ٱلْعَظِيمُ ٱلشَّرِيفُ وَأَسْكَنَهُمْ مُدُنَ ٱلسَّامِرَةِ، وَسَائِرِ ٱلَّذِينَ فِي عَبْرِ ٱلنَّهْرِ وَإِلَى آخِرِهِ.","wasāyỉri ٱl̊ạủmami ٱlãdẖīna sabāhum̊ ạủs̊nafãru ٱl̊ʿaẓīmu ٱlsẖãrīfu wāảs̊kanahum̊ muduna ٱlsãạmiraẗi, wasāyỉri ٱlãdẖīna fī ʿab̊ri ٱlnãh̊ri wāi̹lay̱ ậkẖirihi."],[4,11,"هَذِهِ صُورَةُ ٱلرِّسَالَةِ ٱلَّتِي أَرْسَلُوهَا إِلَيْهِ، إِلَى أَرْتَحْشَشْتَا ٱلْمَلِكِ: «عَبِيدُكَ ٱلْقَوْمُ ٱلَّذِينَ فِي عَبْرِ ٱلنَّهْرِ إِلَى آخِرِهِ.","hadẖihi ṣūraẗu ٱlrĩsālaẗi ٱlãtī ạảr̊salūhā ại̹laẙhi, ại̹lay̱ ạảr̊taḥ̊sẖasẖ̊tā ٱl̊maliki: «ʿabīduka ٱl̊qaẘmu ٱlãdẖīna fī ʿab̊ri ٱlnãh̊ri ại̹lay̱ ậkẖirihi."],[4,12,"لِيُعْلَمِ ٱلْمَلِكُ أَنَّ ٱلْيَهُودَ ٱلَّذِينَ صَعِدُوا مِنْ عِنْدِكَ إِلَيْنَا قَدْ أَتَوْا إِلَى أُورُشَلِيمَ وَيَبْنُونَ ٱلْمَدِينَةَ ٱلْعَاصِيَةَ ٱلرَّدِيَّةَ، وَقَدْ أَكْمَلُوا أَسْوَارَهَا وَرَمَّمُوا أُسُسَهَا.","līuʿ̊lami ٱl̊maliku ạảnã ٱl̊yahūda ٱlãdẖīna ṣaʿidūạ min̊ ʿin̊dika ại̹laẙnā qad̊ ạảtaẘạ ại̹lay̱ ạủwrusẖalīma wayab̊nūna ٱl̊madīnaẗa ٱl̊ʿāṣīaẗa ٱlrãdīãẗa, waqad̊ ạảk̊malūạ ạảs̊wārahā waramãmūạ ạủsusahā."],[4,13,"لِيَكُنِ ٱلْآنَ مَعْلُومًا لَدَى ٱلْمَلِكِ أَنَّهُ إِذَا بُنِيَتْ هَذِهِ ٱلْمَدِينَةُ وَأُكْمِلَتْ أَسْوَارُهَا لَا يُؤَدُّونَ جِزْيَةً وَلَا خَرَاجًا وَلَا خِفَارَةً، فَأَخِيرًا تَضُرُّ ٱلْمُلُوكَ.","līakuni ٱl̊ậna maʿ̊lūmaⁿạ laday̱ ٱl̊maliki ạảnãhu ại̹dẖā bunīat̊ hadẖihi ٱl̊madīnaẗu wāủk̊milat̊ ạảs̊wāruhā lā yūảdũwna jiz̊yaẗaⁿ walā kẖarājaⁿạ walā kẖifāraẗaⁿ, fāảkẖīraⁿạ taḍurũ ٱl̊mulūka."],[4,14,"وَٱلْآنَ بِمَا إِنَّنَا نَأْكُلُ مِلْحَ دَارِ ٱلْمَلِكِ، وَلَا يَلِيقُ بِنَا أَنْ نَرَى ضَرَرَ ٱلْمَلِكِ، لِذَلِكَ أَرْسَلْنَا فَأَعْلَمْنَا ٱلْمَلِكَ،","waٱl̊ậna bimā ại̹nãnā nā̊̉kulu mil̊ḥa dāri ٱl̊maliki, walā yalīqu binā ạản̊ naray̱ ḍarara ٱl̊maliki, lidẖalika ạảr̊sal̊nā fāảʿ̊lam̊nā ٱl̊malika,"],[4,15,"لِكَيْ يُفَتَّشَ فِي سِفْرِ أَخْبَارِ آبَائِكَ، فَتَجِدَ فِي سِفْرِ ٱلْأَخْبَارِ وَتَعْلَمَ أَنَّ هَذِهِ ٱلْمَدِينَةَ مَدِينَةٌ عَاصِيَةٌ وَمُضِرَّةٌ لِلْمُلُوكِ وَٱلْبِلَادِ، وَقَدْ عَمِلُوا عِصْيَانًا فِي وَسَطِهَا مُنْذُ ٱلْأَيَّامِ ٱلْقَدِيمَةِ، لِذَلِكَ أُخْرِبَتْ هَذِهِ ٱلْمَدِينَةُ.","likaẙ yufatãsẖa fī sif̊ri ạảkẖ̊bāri ậbāyỉka, fatajida fī sif̊ri ٱl̊ạảkẖ̊bāri wataʿ̊lama ạảnã hadẖihi ٱl̊madīnaẗa madīnaẗuⁿ ʿāṣīaẗuⁿ wamuḍirãẗuⁿ lil̊mulūki waٱl̊bilādi, waqad̊ ʿamilūạ ʿiṣ̊yānaⁿạ fī wasaṭihā mun̊dẖu ٱl̊ạảyãạmi ٱl̊qadīmaẗi, lidẖalika ạủkẖ̊ribat̊ hadẖihi ٱl̊madīnaẗu."],[4,16,"وَنَحْنُ نُعْلِمُ ٱلْمَلِكَ أَنَّهُ إِذَا بُنِيَتْ هَذِهِ ٱلْمَدِينَةُ وَأُكْمِلَتْ أَسْوَارُهَا لَا يَكُونُ لَكَ عِنْدَ ذَلِكَ نَصِيبٌ فِي عَبْرِ ٱلنَّهْرِ».","wanaḥ̊nu nuʿ̊limu ٱl̊malika ạảnãhu ại̹dẖā bunīat̊ hadẖihi ٱl̊madīnaẗu wāủk̊milat̊ ạảs̊wāruhā lā yakūnu laka ʿin̊da dẖalika naṣībuⁿ fī ʿab̊ri ٱlnãh̊ri»."],[4,17,"فَأَرْسَلَ ٱلْمَلِكُ جَوَابًا: «إِلَى رَحُومَ صَاحِبِ ٱلْقَضَاءِ وَشَمْشَايَ ٱلْكَاتِبِ وَسَائِرِ رُفَقَائِهِمَا ٱلسَّاكِنِينَ فِي ٱلسَّامِرَةِ وَبَاقِي ٱلَّذِينَ فِي عَبْرِ ٱلنَّهْرِ. سَلَامٌ إِلَى آخِرِهِ.","fāảr̊sala ٱl̊maliku jawābaⁿạ: «ại̹lay̱ raḥūma ṣāḥibi ٱl̊qaḍāʾi wasẖam̊sẖāya ٱl̊kātibi wasāyỉri rufaqāyỉhimā ٱlsãạkinīna fī ٱlsãạmiraẗi wabāqī ٱlãdẖīna fī ʿab̊ri ٱlnãh̊ri. salāmuⁿ ại̹lay̱ ậkẖirihi."],[4,18,"ٱلرِّسَالَةُ ٱلَّتِي أَرْسَلْتُمُوهَا إِلَيْنَا قَدْ قُرِئَتْ بِوُضُوحٍ أَمَامِي.","ٱlrĩsālaẗu ٱlãtī ạảr̊sal̊tumūhā ại̹laẙnā qad̊ qurīảt̊ biwuḍūḥiⁿ ạảmāmī."],[4,19,"وَقَدْ خَرَجَ مِنْ عِنْدِي أَمْرٌ فَفَتَّشُوا وَوُجِدَ أَنَّ هَذِهِ ٱلْمَدِينَةَ مُنْذُ ٱلْأَيَّامِ ٱلْقَدِيمَةِ تَقُومُ عَلَى ٱلْمُلُوكِ، وَقَدْ جَرَى فِيهَا تَمَرُّدٌ وَعِصْيَانٌ.","waqad̊ kẖaraja min̊ ʿin̊dī ạảm̊ruⁿ fafatãsẖūạ wawujida ạảnã hadẖihi ٱl̊madīnaẗa mun̊dẖu ٱl̊ạảyãạmi ٱl̊qadīmaẗi taqūmu ʿalay̱ ٱl̊mulūki, waqad̊ jaray̱ fīhā tamarũduⁿ waʿiṣ̊yānuⁿ."],[4,20,"وَقَدْ كَانَ مُلُوكٌ مُقْتَدِرُونَ عَلَى أُورُشَلِيمَ وَتَسَلَّطُوا عَلَى جَمِيعِ عَبْرِ ٱلنَّهْرِ، وَقَدْ أُعْطُوا جِزْيَةً وَخَرَاجًا وَخِفَارَةً.","waqad̊ kāna mulūkuⁿ muq̊tadirūna ʿalay̱ ạủwrusẖalīma watasalãṭūạ ʿalay̱ jamīʿi ʿab̊ri ٱlnãh̊ri, waqad̊ ạủʿ̊ṭūạ jiz̊yaẗaⁿ wakẖarājaⁿạ wakẖifāraẗaⁿ."],[4,21,"فَٱلْآنَ أَخْرِجُوا أَمْرًا بِتَوْقِيفِ أُولَئِكَ ٱلرِّجَالِ فَلَا تُبْنَى هَذِهِ ٱلْمَدِينَةُ حَتَّى يَصْدُرَ مِنِّي أَمْرٌ.","faٱl̊ậna ạảkẖ̊rijūạ ạảm̊raⁿạ bitaẘqīfi ạủwlayỉka ٱlrĩjāli falā tub̊nay̱ hadẖihi ٱl̊madīnaẗu ḥatãy̱ yaṣ̊dura minĩy ạảm̊ruⁿ."],[4,22,"فَٱحْذَرُوا مِنْ أَنْ تَقْصُرُوا عَنْ عَمَلِ ذَلِكَ. لِمَاذَا يَكْثُرُ ٱلضَّرَرُ لِخَسَارَةِ ٱلْمُلُوكِ؟».","faٱḥ̊dẖarūạ min̊ ạản̊ taq̊ṣurūạ ʿan̊ ʿamali dẖalika. limādẖā yak̊tẖuru ٱlḍãraru likẖasāraẗi ٱl̊mulūki?»."],[4,23,"حِينَئِذٍ لَمَّا قُرِئَتْ رِسَالَةُ أَرْتَحْشَشْتَا ٱلْمَلِكِ أَمَامَ رَحُومَ وَشِمْشَايَ ٱلْكَاتِبِ وَرُفَقَائِهِمَا ذَهَبُوا بِسُرْعَةٍ إِلَى أُورُشَلِيمَ، إِلَى ٱلْيَهُودِ، وَأَوْقَفُوهُمْ بِذِرَاعٍ وَقُوَّةٍ.","ḥīnayỉdẖiⁿ lamãạ qurīảt̊ risālaẗu ạảr̊taḥ̊sẖasẖ̊tā ٱl̊maliki ạảmāma raḥūma wasẖim̊sẖāya ٱl̊kātibi warufaqāyỉhimā dẖahabūạ bisur̊ʿaẗiⁿ ại̹lay̱ ạủwrusẖalīma, ại̹lay̱ ٱl̊yahūdi, wāảẘqafūhum̊ bidẖirāʿiⁿ waqūãẗiⁿ."],[4,24,"حِينَئِذٍ تَوَقَّفَ عَمَلُ بَيْتِ ٱللهِ ٱلَّذِي فِي أُورُشَلِيمَ، وَكَانَ مُتَوَقِّفًا إِلَى ٱلسَّنَةِ ٱلثَّانِيَةِ مِنْ مُلْكِ دَارِيُوسَ مَلِكِ فَارِسَ.","ḥīnayỉdẖiⁿ tawaqãfa ʿamalu baẙti ٱllhi ٱlãdẖī fī ạủwrusẖalīma, wakāna mutawaqĩfaⁿạ ại̹lay̱ ٱlsãnaẗi ٱltẖãạnīaẗi min̊ mul̊ki dārīūsa maliki fārisa."],[5,1,"فَتَنَبَّأَ ٱلنَّبِيَّانِ حَجَّيِ ٱلنَّبِيُّ وَزَكَرِيَّا بْنُ عِدُّوَ لِلْيَهُودِ ٱلَّذِينَ فِي يَهُوذَا وَأُورُشَلِيمَ بِٱسْمِ إِلَهِ إِسْرَائِيلَ عَلَيْهِمْ.","fatanabãạả ٱlnãbīãạni ḥajãyi ٱlnãbīũ wazakarīãạ b̊nu ʿidũwa lil̊yahūdi ٱlãdẖīna fī yahūdẖā wāủwrusẖalīma biٱs̊mi ại̹lahi ại̹s̊rāyỉyla ʿalaẙhim̊."],[5,2,"حِينَئِذٍ قَامَ زَرُبَّابِلُ بْنُ شَأَلْتِئِيلَ وَيَشُوعُ بْنُ يُوصَادَاقَ، وَشَرَعَا بِبُنْيَانِ بَيْتِ ٱللهِ ٱلَّذِي فِي أُورُشَلِيمَ، وَمَعَهُمَا أَنْبِيَاءُ ٱللهِ يُسَاعِدُونَهُمَا.","ḥīnayỉdẖiⁿ qāma zarubãạbilu b̊nu sẖāảl̊tīỉyla wayasẖūʿu b̊nu yūṣādāqa, wasẖaraʿā bibun̊yāni baẙti ٱllhi ٱlãdẖī fī ạủwrusẖalīma, wamaʿahumā ạản̊bīāʾu ٱllhi yusāʿidūnahumā."],[5,3,"فِي ذَلِكَ ٱلزَّمَانِ جَاءَ إِلَيْهِمْ تَتْنَايُ وَالِي عَبْرِ ٱلنَّهْرِ وَشَتَرْبُوزْنَايُ وَرُفَقَاؤُهُمَا وَقَالُوا لَهُمْ هَكَذَا: «مَنْ أَمَرَكُمْ أَنْ تَبْنُوا هَذَا ٱلْبَيْتَ وَتُكَمِّلُوا هَذَا ٱلسُّورَ؟».","fī dẖalika ٱlzãmāni jāʾa ại̹laẙhim̊ tat̊nāyu wālī ʿab̊ri ٱlnãh̊ri wasẖatar̊būz̊nāyu warufaqāwủhumā waqālūạ lahum̊ hakadẖā: «man̊ ạảmarakum̊ ạản̊ tab̊nūạ hadẖā ٱl̊baẙta watukamĩlūạ hadẖā ٱlsũwra?»."],[5,4,"حِينَئِذٍ أَخْبَرْنَاهُمْ عَلَى هَذَا ٱلْمَنْوَالِ مَا هِيَ أَسْمَاءُ ٱلرِّجَالِ ٱلَّذِينَ يَبْنُونَ هَذَا ٱلْبِنَاءَ.","ḥīnayỉdẖiⁿ ạảkẖ̊bar̊nāhum̊ ʿalay̱ hadẖā ٱl̊man̊wāli mā hīa ạảs̊māʾu ٱlrĩjāli ٱlãdẖīna yab̊nūna hadẖā ٱl̊bināʾa."],[5,5,"وَكَانَتْ عَلَى شُيُوخِ ٱلْيَهُودِ عَيْنُ إِلَهِهِمْ فَلَمْ يُوقِفُوهُمْ حَتَّى وَصَلَ ٱلْأَمْرُ إِلَى دَارِيُوسَ، وَحِينَئِذٍ جَاوَبُوا بِرِسَالَةٍ عَنْ هَذَا.","wakānat̊ ʿalay̱ sẖuyūkẖi ٱl̊yahūdi ʿaẙnu ại̹lahihim̊ falam̊ yūqifūhum̊ ḥatãy̱ waṣala ٱl̊ạảm̊ru ại̹lay̱ dārīūsa, waḥīnayỉdẖiⁿ jāwabūạ birisālaẗiⁿ ʿan̊ hadẖā."],[5,6,"صُورَةُ ٱلرِّسَالَةِ ٱلَّتِي أَرْسَلَهَا تَتْنَايُ وَالِي عَبْرِ ٱلنَّهْرِ وَشَتَرْبُوزْنَايُ وَرُفَقَاؤُهُمَا ٱلْأَفَرْسَكِيِّينَ ٱلَّذِينَ فِي عَبْرِ ٱلنَّهْرِ إِلَى دَارِيُوسَ ٱلْمَلِكِ.","ṣūraẗu ٱlrĩsālaẗi ٱlãtī ạảr̊salahā tat̊nāyu wālī ʿab̊ri ٱlnãh̊ri wasẖatar̊būz̊nāyu warufaqāwủhumā ٱl̊ạảfar̊sakīĩyna ٱlãdẖīna fī ʿab̊ri ٱlnãh̊ri ại̹lay̱ dārīūsa ٱl̊maliki."],[5,7,"أَرْسَلُوا إِلَيْهِ رِسَالَةً وَكَانَ مَكْتُوبًا فِيهَا هَكَذَا: «لِدَارِيُوسَ ٱلْمَلِكِ كُلُّ سَلَامٍ.","ạảr̊salūạ ại̹laẙhi risālaẗaⁿ wakāna mak̊tūbaⁿạ fīhā hakadẖā: «lidārīūsa ٱl̊maliki kulũ salāmiⁿ."],[5,8,"لِيَكُنْ مَعْلُومًا لَدَى ٱلْمَلِكِ أَنَّنَا ذَهَبْنَا إِلَى بِلَادِ يَهُوذَا، إِلَى بَيْتِ ٱلْإِلَهِ ٱلْعَظِيمِ، وَإِذَا بِهِ يُبْنَى بِحِجَارَةٍ عَظِيمَةٍ، وَيُوضَعُ خَشَبٌ فِي ٱلْحِيطَانِ. وَهَذَا ٱلْعَمَلُ يُعْمَلُ بِسُرْعَةٍ وَيَنْجَحُ فِي أَيْدِيهِمْ.","līakun̊ maʿ̊lūmaⁿạ laday̱ ٱl̊maliki ạảnãnā dẖahab̊nā ại̹lay̱ bilādi yahūdẖā, ại̹lay̱ baẙti ٱl̊ại̹lahi ٱl̊ʿaẓīmi, wāi̹dẖā bihi yub̊nay̱ biḥijāraẗiⁿ ʿaẓīmaẗiⁿ, wayūḍaʿu kẖasẖabuⁿ fī ٱl̊ḥīṭāni. wahadẖā ٱl̊ʿamalu yuʿ̊malu bisur̊ʿaẗiⁿ wayan̊jaḥu fī ạảẙdīhim̊."],[5,9,"حِينَئِذٍ سَأَلْنَا أُولَئِكَ ٱلشُّيُوخَ وَقُلْنَا لَهُمْ هَكَذَا: مَنْ أَمَرَكُمْ بِبِنَاءِ هَذَا ٱلْبَيْتِ وَتَكْمِيلِ هَذِهِ ٱلْأَسْوَارِ؟","ḥīnayỉdẖiⁿ sāảl̊nā ạủwlayỉka ٱlsẖũyūkẖa waqul̊nā lahum̊ hakadẖā: man̊ ạảmarakum̊ bibināʾi hadẖā ٱl̊baẙti watak̊mīli hadẖihi ٱl̊ạảs̊wāri?"],[5,10,"وَسَأَلْنَاهُمْ أَيْضًا عَنْ أَسْمَائِهِمْ لِنُعْلِمَكَ، وَكَتَبْنَا أَسْمَاءَ ٱلرِّجَالِ رُؤُوسِهِمْ.","wasāảl̊nāhum̊ ạảẙḍaⁿạ ʿan̊ ạảs̊māyỉhim̊ linuʿ̊limaka, wakatab̊nā ạảs̊māʾa ٱlrĩjāli rūủwsihim̊."],[5,11,"وَبِمِثْلِ هَذَا ٱلْجَوَابِ جَاوَبُوا قَائِلِينَ: نَحْنُ عَبِيدُ إِلَهِ ٱلسَّمَاءِ وَٱلْأَرْضِ، وَنَبْنِي هَذَا ٱلْبَيْتَ ٱلَّذِي بُنِيَ قَبْلَ هَذِهِ ٱلسِّنِينَ ٱلْكَثِيرَةِ، وَقَدْ بَنَاهُ مَلِكٌ عَظِيمٌ لِإِسْرَائِيلَ وَأَكْمَلَهُ.","wabimitẖ̊li hadẖā ٱl̊jawābi jāwabūạ qāyỉlīna: naḥ̊nu ʿabīdu ại̹lahi ٱlsãmāʾi waٱl̊ạảr̊ḍi, wanab̊nī hadẖā ٱl̊baẙta ٱlãdẖī bunīa qab̊la hadẖihi ٱlsĩnīna ٱl̊katẖīraẗi, waqad̊ banāhu malikuⁿ ʿaẓīmuⁿ liại̹s̊rāyỉyla wāảk̊malahu."],[5,12,"وَلَكِنْ بَعْدَ أَنْ أَسْخَطَ آبَاؤُنَا إِلَهَ ٱلسَّمَاءِ دَفَعَهُمْ لِيَدِ نَبُوخَذْنَصَّرَ مَلِكِ بَابِلَ ٱلْكَلْدَانِيِّ، ٱلَّذِي هَدَمَ هَذَا ٱلْبَيْتَ وَسَبَى ٱلشَّعْبَ إِلَى بَابِلَ.","walakin̊ baʿ̊da ạản̊ ạảs̊kẖaṭa ậbāwủnā ại̹laha ٱlsãmāʾi dafaʿahum̊ līadi nabūkẖadẖ̊naṣãra maliki bābila ٱl̊kal̊dānīĩ, ٱlãdẖī hadama hadẖā ٱl̊baẙta wasabay̱ ٱlsẖãʿ̊ba ại̹lay̱ bābila."],[5,13,"عَلَى أَنَّهُ فِي ٱلسَّنَةِ ٱلْأُولَى لِكُورَشَ مَلِكَ بَابِلَ، أَصْدَرَ كُورَشُ ٱلْمَلِكُ أَمْرًا بِبِنَاءِ بَيْتِ ٱللهِ هَذَا.","ʿalay̱ ạảnãhu fī ٱlsãnaẗi ٱl̊ạủwlay̱ likūrasẖa malika bābila, ạảṣ̊dara kūrasẖu ٱl̊maliku ạảm̊raⁿạ bibināʾi baẙti ٱllhi hadẖā."],[5,14,"حَتَّى إِنَّ آنِيَةَ بَيْتِ ٱللهِ هَذَا، ٱلَّتِي مِنْ ذَهَبٍ وَفِضَّةٍ، ٱلَّتِي أَخْرَجَهَا نَبُوخَذْنَصَّرُ مِنَ ٱلْهَيْكَلِ ٱلَّذِي فِي أُورُشَلِيمَ وَأَتَى بِهَا إِلَى ٱلْهَيْكَلِ ٱلَّذِي فِي بَابِلَ، أَخْرَجَهَا كُورَشُ ٱلْمَلِكُ مِنَ ٱلْهَيْكَلِ ٱلَّذِي فِي بَابِلَ وَأُعْطِيَتْ لِوَاحِدٍ ٱسْمُهُ شِيشْبَصَّرُ ٱلَّذِي جَعَلَهُ وَالِيًا.","ḥatãy̱ ại̹nã ậnīaẗa baẙti ٱllhi hadẖā, ٱlãtī min̊ dẖahabiⁿ wafiḍãẗiⁿ, ٱlãtī ạảkẖ̊rajahā nabūkẖadẖ̊naṣãru mina ٱl̊haẙkali ٱlãdẖī fī ạủwrusẖalīma wāảtay̱ bihā ại̹lay̱ ٱl̊haẙkali ٱlãdẖī fī bābila, ạảkẖ̊rajahā kūrasẖu ٱl̊maliku mina ٱl̊haẙkali ٱlãdẖī fī bābila wāủʿ̊ṭīat̊ liwāḥidiⁿ ٱs̊muhu sẖīsẖ̊baṣãru ٱlãdẖī jaʿalahu wālīaⁿạ."],[5,15,"وَقَالَ لَهُ: خُذْ هَذِهِ ٱلْآنِيَةَ وَٱذْهَبْ وَٱحْمِلْهَا إِلَى ٱلْهَيْكَلِ ٱلَّذِي فِي أُورُشَلِيمَ، وَلْيُبْنَ بَيْتُ ٱللهِ فِي مَكَانِهِ.","waqāla lahu: kẖudẖ̊ hadẖihi ٱl̊ậnīaẗa waٱdẖ̊hab̊ waٱḥ̊mil̊hā ại̹lay̱ ٱl̊haẙkali ٱlãdẖī fī ạủwrusẖalīma, wal̊yub̊na baẙtu ٱllhi fī makānihi."],[5,16,"حِينَئِذٍ جَاءَ شِيشْبَصَّرُ هَذَا وَوَضَعَ أَسَاسَ بَيْتِ ٱللهِ ٱلَّذِي فِي أُورُشَلِيمَ، وَمِنْ ذَلِكَ ٱلْوَقْتِ إِلَى ٱلْآنَ يُبْنَى وَلَمْ يُكْمَلْ.","ḥīnayỉdẖiⁿ jāʾa sẖīsẖ̊baṣãru hadẖā wawaḍaʿa ạảsāsa baẙti ٱllhi ٱlãdẖī fī ạủwrusẖalīma, wamin̊ dẖalika ٱl̊waq̊ti ại̹lay̱ ٱl̊ậna yub̊nay̱ walam̊ yuk̊mal̊."],[5,17,"وَٱلْآنَ إِذَا حَسُنَ عِنْدَ ٱلْمَلِكِ فَلْيُفَتَّشْ فِي بَيْتِ خَزَائِنِ ٱلْمَلِكِ ٱلَّذِي هُوَ هُنَاكَ فِي بَابِلَ: هَلْ كَانَ قَدْ صَدَرَ أَمْرٌ مِنْ كُورَشَ ٱلْمَلِكِ بِبِنَاءِ بَيْتِ ٱللهِ هَذَا فِي أُورُشَلِيمَ؟ وَلْيُرْسِلِ ٱلْمَلِكُ إِلَيْنَا مُرَادَهُ فِي ذَلِكَ».","waٱl̊ậna ại̹dẖā ḥasuna ʿin̊da ٱl̊maliki fal̊yufatãsẖ̊ fī baẙti kẖazāyỉni ٱl̊maliki ٱlãdẖī hūa hunāka fī bābila: hal̊ kāna qad̊ ṣadara ạảm̊ruⁿ min̊ kūrasẖa ٱl̊maliki bibināʾi baẙti ٱllhi hadẖā fī ạủwrusẖalīma? wal̊yur̊sili ٱl̊maliku ại̹laẙnā murādahu fī dẖalika»."],[6,1,"حِينَئِذٍ أَمَرَ دَارِيُوسُ ٱلْمَلِكُ فَفَتَّشُوا فِي بَيْتِ ٱلْأَسْفَارِ حَيْثُ كَانَتِ ٱلْخَزَائِنُ مَوْضُوعَةً فِي بَابِلَ،","ḥīnayỉdẖiⁿ ạảmara dārīūsu ٱl̊maliku fafatãsẖūạ fī baẙti ٱl̊ạảs̊fāri ḥaẙtẖu kānati ٱl̊kẖazāyỉnu maẘḍūʿaẗaⁿ fī bābila,"],[6,2,"فَوُجِدَ فِي أَحْمَثَا، فِي ٱلْقَصْرِ ٱلَّذِي فِي بِلَادِ مَادِي، دَرْجٌ مَكْتُوبٌ فِيهِ هَكَذَا: «تَذْكَارٌ.","fawujida fī ạảḥ̊matẖā, fī ٱl̊qaṣ̊ri ٱlãdẖī fī bilādi mādī, dar̊juⁿ mak̊tūbuⁿ fīhi hakadẖā: «tadẖ̊kāruⁿ."],[6,3,"فِي ٱلسَّنَةِ ٱلْأُولَى لِكُورَشَ ٱلْمَلِكِ، أَمَرَ كُورَشُ ٱلْمَلِكُ مِنْ جِهَةِ بَيْتِ ٱللهِ فِي أُورُشَلِيمَ: لِيُبْنَ ٱلْبَيْتُ، ٱلْمَكَانُ ٱلَّذِي يَذْبَحُونَ فِيهِ ذَبَائِحَ، وَلْتُوضَعْ أُسُسُهُ، ٱرْتِفَاعُهُ سِتُّونَ ذِرَاعًا وَعَرْضُهُ سِتُّونَ ذِرَاعًا.","fī ٱlsãnaẗi ٱl̊ạủwlay̱ likūrasẖa ٱl̊maliki, ạảmara kūrasẖu ٱl̊maliku min̊ jihaẗi baẙti ٱllhi fī ạủwrusẖalīma: līub̊na ٱl̊baẙtu, ٱl̊makānu ٱlãdẖī yadẖ̊baḥūna fīhi dẖabāyỉḥa, wal̊tūḍaʿ̊ ạủsusuhu, ٱr̊tifāʿuhu sitũwna dẖirāʿaⁿạ waʿar̊ḍuhu sitũwna dẖirāʿaⁿạ."],[6,4,"بِثَلَاثَةِ صُفُوفٍ مِنْ حِجَارَةٍ عَظِيمَةٍ، وَصَفٍّ مِنْ خَشَبٍ جَدِيدٍ. وَلْتُعْطَ ٱلنَّفَقَةُ مِنْ بَيْتِ ٱلْمَلِكِ.","bitẖalātẖaẗi ṣufūfiⁿ min̊ ḥijāraẗiⁿ ʿaẓīmaẗiⁿ, waṣafiⁿ̃ min̊ kẖasẖabiⁿ jadīdiⁿ. wal̊tuʿ̊ṭa ٱlnãfaqaẗu min̊ baẙti ٱl̊maliki."],[6,5,"وَأَيْضًا آنِيَةُ بَيْتِ ٱللهِ، ٱلَّتِي مِنْ ذَهَبٍ وَفِضَّةٍ، ٱلَّتِي أَخْرَجَهَا نَبُوخَذْنَصَّرُ مِنَ ٱلْهَيْكَلِ ٱلَّذِي فِي أُورُشَلِيمَ وَأَتَى بِهَا إِلَى بَابِلَ، فَلْتُرَدَّ وَتُرْجَعْ إِلَى ٱلْهَيْكَلِ ٱلَّذِي فِي أُورُشَلِيمَ إِلَى مَكَانِهَا، وَتُوضَعْ فِي بَيْتِ ٱللهِ».","wāảẙḍaⁿạ ậnīaẗu baẙti ٱllhi, ٱlãtī min̊ dẖahabiⁿ wafiḍãẗiⁿ, ٱlãtī ạảkẖ̊rajahā nabūkẖadẖ̊naṣãru mina ٱl̊haẙkali ٱlãdẖī fī ạủwrusẖalīma wāảtay̱ bihā ại̹lay̱ bābila, fal̊turadã watur̊jaʿ̊ ại̹lay̱ ٱl̊haẙkali ٱlãdẖī fī ạủwrusẖalīma ại̹lay̱ makānihā, watūḍaʿ̊ fī baẙti ٱllhi»."],[6,6,"«وَٱلْآنَ يَا تَتْنَايُ وَالِي عَبْرِ ٱلنَّهْرِ وَشَتَرْبُوزْنَايُ وَرُفَقَاءَكُمَا ٱلْأَفَرْسَكِيِّينَ ٱلَّذِينَ فِي عَبْرِ ٱلنَّهْرِ، ٱبْتَعِدُوا مِنْ هُنَاكَ.","«waٱl̊ậna yā tat̊nāyu wālī ʿab̊ri ٱlnãh̊ri wasẖatar̊būz̊nāyu warufaqāʾakumā ٱl̊ạảfar̊sakīĩyna ٱlãdẖīna fī ʿab̊ri ٱlnãh̊ri, ٱb̊taʿidūạ min̊ hunāka."],[6,7,"ٱتْرُكُوا عَمَلَ بَيْتِ ٱللهِ هَذَا. أَمَّا وَالِي ٱلْيَهُودِ وَشُيُوخُ ٱلْيَهُودِ فَلْيَبْنُوا بَيْتَ ٱللهِ هَذَا فِي مَكَانِهِ.","ٱt̊rukūạ ʿamala baẙti ٱllhi hadẖā. ạảmãạ wālī ٱl̊yahūdi wasẖuyūkẖu ٱl̊yahūdi fal̊yab̊nūạ baẙta ٱllhi hadẖā fī makānihi."],[6,8,"وَقَدْ صَدَرَ مِنِّي أَمْرٌ بِمَا تَعْمَلُونَ مَعَ شُيُوخِ ٱلْيَهُودِ هَؤُلَاءِ فِي بِنَاءِ بَيْتِ ٱللهِ هَذَا. فَمِنْ مَالِ ٱلْمَلِكِ، مِنْ جِزْيَةِ عَبْرِ ٱلنَّهْرِ، تُعْطَ ٱلنَّفَقَةُ عَاجِلًا لِهَؤُلَاءِ ٱلرِّجَالِ حَتَّى لَا يَبْطُلُوا.","waqad̊ ṣadara minĩy ạảm̊ruⁿ bimā taʿ̊malūna maʿa sẖuyūkẖi ٱl̊yahūdi hawủlāʾi fī bināʾi baẙti ٱllhi hadẖā. famin̊ māli ٱl̊maliki, min̊ jiz̊yaẗi ʿab̊ri ٱlnãh̊ri, tuʿ̊ṭa ٱlnãfaqaẗu ʿājilaⁿạ lihawủlāʾi ٱlrĩjāli ḥatãy̱ lā yab̊ṭulūạ."],[6,9,"وَمَا يَحْتَاجُونَ إِلَيْهِ مِنَ ٱلثِّيرَانِ وَٱلْكِبَاشِ وَٱلْخِرَافِ مُحْرَقَةً لِإِلَهِ ٱلسَّمَاءِ، وَحِنْطَةٍ وَمِلْحٍ وَخَمْرٍ وَزَيْتٍ حَسَبَ قَوْلِ ٱلْكَهَنَةِ ٱلَّذِينَ فِي أُورُشَلِيمَ، لِتُعْطَ لَهُمْ يَوْمًا فَيَوْمًا حَتَّى لَا يَهْدَأُوا","wamā yaḥ̊tājūna ại̹laẙhi mina ٱltẖĩyrāni waٱl̊kibāsẖi waٱl̊kẖirāfi muḥ̊raqaẗaⁿ liại̹lahi ٱlsãmāʾi, waḥin̊ṭaẗiⁿ wamil̊ḥiⁿ wakẖam̊riⁿ wazaẙtiⁿ ḥasaba qaẘli ٱl̊kahanaẗi ٱlãdẖīna fī ạủwrusẖalīma, lituʿ̊ṭa lahum̊ yaẘmaⁿạ fayaẘmaⁿạ ḥatãy̱ lā yah̊dāủwạ"],[6,10,"عَنْ تَقْرِيبِ رَوَائِحِ سُرُورٍ لِإِلَهِ ٱلسَّمَاءِ، وَٱلصَّلَاةِ لِأَجْلِ حَيَاةِ ٱلْمَلِكِ وَبَنِيهِ.","ʿan̊ taq̊rībi rawāyỉḥi surūriⁿ liại̹lahi ٱlsãmāʾi, waٱlṣãlāẗi liạảj̊li ḥayāẗi ٱl̊maliki wabanīhi."],[6,11,"وَقَدْ صَدَرَ مِنِّي أَمْرٌ أَنَّ كُلَّ إِنْسَانٍ يُغَيِّرُ هَذَا ٱلْكَلَامَ تُسْحَبُ خَشَبَةٌ مِنْ بَيْتِهِ وَيُعَلَّقُ مَصْلُوبًا عَلَيْهَا، وَيُجْعَلُ بَيْتُهُ مَزْبَلَةً مِنْ أَجْلِ هَذَا.","waqad̊ ṣadara minĩy ạảm̊ruⁿ ạảnã kulã ại̹n̊sāniⁿ yugẖayĩru hadẖā ٱl̊kalāma tus̊ḥabu kẖasẖabaẗuⁿ min̊ baẙtihi wayuʿalãqu maṣ̊lūbaⁿạ ʿalaẙhā, wayuj̊ʿalu baẙtuhu maz̊balaẗaⁿ min̊ ạảj̊li hadẖā."],[6,12,"وَٱللهُ ٱلَّذِي أَسْكَنَ ٱسْمَهُ هُنَاكَ يُهْلِكُ كُلَّ مَلِكٍ وَشَعْبٍ يَمُدُّ يَدَهُ لِتَغْيِيرِ أَوْ لِهَدْمِ بَيْتِ ٱللهِ هَذَا ٱلَّذِي فِي أُورُشَلِيمَ. أَنَا دَارِيُوسُ قَدْ أَمَرْتُ فَلْيُفْعَلْ عَاجِلًا».","waٱllhu ٱlãdẖī ạảs̊kana ٱs̊mahu hunāka yuh̊liku kulã malikiⁿ wasẖaʿ̊biⁿ yamudũ yadahu litagẖ̊yīri ạảẘ lihad̊mi baẙti ٱllhi hadẖā ٱlãdẖī fī ạủwrusẖalīma. ạảnā dārīūsu qad̊ ạảmar̊tu fal̊yuf̊ʿal̊ ʿājilaⁿạ»."],[6,13,"حِينَئِذٍ تَتْنَايُ وَالِي عَبْرِ ٱلنَّهْرِ وَشَتَرْبُوزْنَايُ وَرُفَقَاؤُهُمَا عَمِلُوا عَاجِلًا حَسْبَمَا أَرْسَلَ دَارِيُوسُ ٱلْمَلِكُ.","ḥīnayỉdẖiⁿ tat̊nāyu wālī ʿab̊ri ٱlnãh̊ri wasẖatar̊būz̊nāyu warufaqāwủhumā ʿamilūạ ʿājilaⁿạ ḥas̊bamā ạảr̊sala dārīūsu ٱl̊maliku."],[6,14,"وَكَانَ شُيُوخُ ٱلْيَهُودِ يَبْنُونَ وَيَنْجَحُونَ حَسَبَ نُبُوَّةِ حَجَّيِ ٱلنَّبِيِّ وَزَكَرِيَّا بْنِ عِدُّو. فَبَنَوْا وَأَكْمَلُوا حَسَبَ أَمْرِ إِلَهِ إِسْرَائِيلَ وَأَمْرِ كُورَشَ وَدَارِيُوسَ وَأَرْتَحْشَشْتَا مَلِكِ فَارِسَ.","wakāna sẖuyūkẖu ٱl̊yahūdi yab̊nūna wayan̊jaḥūna ḥasaba nubūãẗi ḥajãyi ٱlnãbīĩ wazakarīãạ b̊ni ʿidũw. fabanaẘạ wāảk̊malūạ ḥasaba ạảm̊ri ại̹lahi ại̹s̊rāyỉyla wāảm̊ri kūrasẖa wadārīūsa wāảr̊taḥ̊sẖasẖ̊tā maliki fārisa."],[6,15,"وَكَمِلَ هَذَا ٱلْبَيْتُ فِي ٱلْيَوْمِ ٱلثَّالِثِ مِنْ شَهْرِ أَذَارَ فِي ٱلسَّنَةِ ٱلسَّادِسَةِ مِنْ مُلْكِ دَارِيُوسَ ٱلْمَلِكِ.","wakamila hadẖā ٱl̊baẙtu fī ٱl̊yaẘmi ٱltẖãạlitẖi min̊ sẖah̊ri ạảdẖāra fī ٱlsãnaẗi ٱlsãạdisaẗi min̊ mul̊ki dārīūsa ٱl̊maliki."],[6,16,"وَبَنُو إِسْرَائِيلَ ٱلْكَهَنَةُ وَٱللَّاوِيُّونَ وَبَاقِي بَنِي ٱلسَّبْيِ دَشَّنُوا بَيْتَ ٱللهِ هَذَا بِفَرَحٍ.","wabanū ại̹s̊rāyỉyla ٱl̊kahanaẗu waٱllãạwīũwna wabāqī banī ٱlsãb̊yi dasẖãnūạ baẙta ٱllhi hadẖā bifaraḥiⁿ."],[6,17,"وَقَرَّبُوا تَدْشِينًا لِبَيْتِ ٱللهِ هَذَا: مِئَةَ ثَوْرٍ وَمِئَتَيْ كَبْشٍ وَأَرْبَعَ مِئَةِ خَرُوفٍ وَٱثْنَيْ عَشَرَ تَيْسَ مِعْزًى، ذَبِيحَةَ خَطِيَّةٍ عَنْ جَمِيعِ إِسْرَائِيلَ، حَسَبَ عَدَدِ أَسْبَاطِ إِسْرَائِيلَ.","waqarãbūạ tad̊sẖīnaⁿạ libaẙti ٱllhi hadẖā: mīảẗa tẖaẘriⁿ wamīảtaẙ kab̊sẖiⁿ wāảr̊baʿa mīảẗi kẖarūfiⁿ waٱtẖ̊naẙ ʿasẖara taẙsa miʿ̊zaⁿy̱, dẖabīḥaẗa kẖaṭīãẗiⁿ ʿan̊ jamīʿi ại̹s̊rāyỉyla, ḥasaba ʿadadi ạảs̊bāṭi ại̹s̊rāyỉyla."],[6,18,"وَأَقَامُوا ٱلْكَهَنَةَ فِي فِرَقِهِمْ وَٱللَّاوِيِّينَ فِي أَقْسَامِهِمْ عَلَى خِدْمَةِ ٱللهِ ٱلَّتِي فِي أُورُشَلِيمَ، كَمَا هُوَ مَكْتُوبٌ فِي سِفْرِ مُوسَى.","wāảqāmūạ ٱl̊kahanaẗa fī firaqihim̊ waٱllãạwīĩyna fī ạảq̊sāmihim̊ ʿalay̱ kẖid̊maẗi ٱllhi ٱlãtī fī ạủwrusẖalīma, kamā hūa mak̊tūbuⁿ fī sif̊ri mūsay̱."],[6,19,"وَعَمِلَ بَنُو ٱلسَّبْيِ ٱلْفِصْحَ فِي ٱلرَّابِعَ عَشَرَ مِنَ ٱلشَّهْرِ ٱلْأَوَّلِ.","waʿamila banū ٱlsãb̊yi ٱl̊fiṣ̊ḥa fī ٱlrãạbiʿa ʿasẖara mina ٱlsẖãh̊ri ٱl̊ạảwãli."],[6,20,"لِأَنَّ ٱلْكَهَنَةَ وَٱللَّاوِيِّينَ تَطَهَّرُوا جَمِيعًا. كَانُوا كُلُّهُمْ طَاهِرِينَ، وَذَبَحُوا ٱلْفِصْحَ لِجَمِيعِ بَنِي ٱلسَّبْيِ وَلِإِخْوَتِهِمِ ٱلْكَهَنَةِ وَلِأَنْفُسِهِمْ.","liạảnã ٱl̊kahanaẗa waٱllãạwīĩyna taṭahãrūạ jamīʿaⁿạ. kānūạ kulũhum̊ ṭāhirīna, wadẖabaḥūạ ٱl̊fiṣ̊ḥa lijamīʿi banī ٱlsãb̊yi waliại̹kẖ̊watihimi ٱl̊kahanaẗi waliạản̊fusihim̊."],[6,21,"وَأَكَلَهُ بَنُو إِسْرَائِيلَ ٱلرَّاجِعُونَ مِنَ ٱلسَّبْيِ مَعَ جَمِيعِ ٱلَّذِينَ ٱنْفَصَلُوا إِلَيْهِمْ مِنْ رَجَاسَةِ أُمَمِ ٱلْأَرْضِ، لِيَطْلُبُوا ٱلرَّبَّ إِلَهَ إِسْرَائِيلَ.","wāảkalahu banū ại̹s̊rāyỉyla ٱlrãạjiʿūna mina ٱlsãb̊yi maʿa jamīʿi ٱlãdẖīna ٱn̊faṣalūạ ại̹laẙhim̊ min̊ rajāsaẗi ạủmami ٱl̊ạảr̊ḍi, līaṭ̊lubūạ ٱlrãbã ại̹laha ại̹s̊rāyỉyla."],[6,22,"وَعَمِلُوا عِيدَ ٱلْفَطِيرِ سَبْعَةَ أَيَّامٍ بِفَرَحٍ، لِأَنَّ ٱلرَّبَّ فَرَّحَهُمْ وَحَوَّلَ قَلْبَ مَلِكِ أَشُّورَ نَحْوَهُمْ لِتَقْوِيَةِ أَيْدِيهِمْ فِي عَمَلِ بَيْتِ ٱللهِ إِلَهِ إِسْرَائِيلَ.","waʿamilūạ ʿīda ٱl̊faṭīri sab̊ʿaẗa ạảyãạmiⁿ bifaraḥiⁿ, liạảnã ٱlrãbã farãḥahum̊ waḥawãla qal̊ba maliki ạảsẖũwra naḥ̊wahum̊ litaq̊wīaẗi ạảẙdīhim̊ fī ʿamali baẙti ٱllhi ại̹lahi ại̹s̊rāyỉyla."],[7,1,"وَبَعْدَ هَذِهِ ٱلْأُمُورِ فِي مُلْكِ أَرْتَحْشَشْتَا مَلِكِ فَارِسَ، عَزْرَا بْنُ سَرَايَا بْنِ عَزَرْيَا بْنِ حِلْقِيَّا","wabaʿ̊da hadẖihi ٱl̊ạủmūri fī mul̊ki ạảr̊taḥ̊sẖasẖ̊tā maliki fārisa, ʿaz̊rā b̊nu sarāyā b̊ni ʿazar̊yā b̊ni ḥil̊qīãạ"],[7,2,"بْنِ شَلُّومَ بْنِ صَادُوقَ بْنِ أَخِيطُوبَ","b̊ni sẖalũwma b̊ni ṣādūqa b̊ni ạảkẖīṭūba"],[7,3,"بْنِ أَمَرْيَا بْنِ عَزَرْيَا بْنِ مَرَايُوثَ","b̊ni ạảmar̊yā b̊ni ʿazar̊yā b̊ni marāyūtẖa"],[7,4,"بْنِ زَرَحْيَا بْنِ عُزِّي بْنِ بُقِّي","b̊ni zaraḥ̊yā b̊ni ʿuzĩy b̊ni buqĩy"],[7,5,"بْنِ أَبِيشُوعَ بْنِ فِينَحَاسَ بْنِ أَلِعَازَارَ بْنِ هَارُونَ ٱلْكَاهِنِ ٱلرَّأْسِ.","b̊ni ạảbīsẖūʿa b̊ni fīnaḥāsa b̊ni ạảliʿāzāra b̊ni hārūna ٱl̊kāhini ٱlrãạ̊̉si."],[7,6,"عَزْرَا هَذَا صَعِدَ مِنْ بَابِلَ، وَهُوَ كَاتِبٌ مَاهِرٌ فِي شَرِيعَةِ مُوسَى ٱلَّتِي أَعْطَاهَا ٱلرَّبُّ إِلَهُ إِسْرَائِيلَ. وَأَعْطَاهُ ٱلْمَلِكُ حَسَبَ يَدِ ٱلرَّبِّ إِلَهِهِ عَلَيْهِ، كُلَّ سُؤْلهِ.","ʿaz̊rā hadẖā ṣaʿida min̊ bābila, wahūa kātibuⁿ māhiruⁿ fī sẖarīʿaẗi mūsay̱ ٱlãtī ạảʿ̊ṭāhā ٱlrãbũ ại̹lahu ại̹s̊rāyỉyla. wāảʿ̊ṭāhu ٱl̊maliku ḥasaba yadi ٱlrãbĩ ại̹lahihi ʿalaẙhi, kulã sū̊̉lhi."],[7,7,"وَصَعِدَ مَعَهُ مِنْ بَنِي إِسْرَائِيلَ وَٱلْكَهَنَةِ وَٱللَّاوِيِّينَ وَٱلْمُغَنِّينَ وَٱلْبَوَّابِينَ وَٱلنَّثِينِيمِ إِلَى أُورُشَلِيمَ فِي ٱلسَّنَةِ ٱلسَّابِعَةِ لِأَرْتَحْشَشْتَا ٱلْمَلِكِ.","waṣaʿida maʿahu min̊ banī ại̹s̊rāyỉyla waٱl̊kahanaẗi waٱllãạwīĩyna waٱl̊mugẖanĩyna waٱl̊bawãạbīna waٱlnãtẖīnīmi ại̹lay̱ ạủwrusẖalīma fī ٱlsãnaẗi ٱlsãạbiʿaẗi liạảr̊taḥ̊sẖasẖ̊tā ٱl̊maliki."],[7,8,"وَجَاءَ إِلَى أُورُشَلِيمَ فِي ٱلشَّهْرِ ٱلْخَامِسِ فِي ٱلسَّنَةِ ٱلسَّابِعَةِ لِلْمَلِكِ.","wajāʾa ại̹lay̱ ạủwrusẖalīma fī ٱlsẖãh̊ri ٱl̊kẖāmisi fī ٱlsãnaẗi ٱlsãạbiʿaẗi lil̊maliki."],[7,9,"لِأَنَّهُ فِي ٱلشَّهْرِ ٱلْأَوَّلِ ٱبْتَدَأَ يَصْعَدُ مِنْ بَابِلَ، وَفِي أَوَّلِ ٱلشَّهْرِ ٱلْخَامِسِ جَاءَ إِلَى أُورُشَلِيمَ حَسَبَ يَدِ ٱللهِ ٱلصَّالِحَةِ عَلَيْهِ.","liạảnãhu fī ٱlsẖãh̊ri ٱl̊ạảwãli ٱb̊tadāả yaṣ̊ʿadu min̊ bābila, wafī ạảwãli ٱlsẖãh̊ri ٱl̊kẖāmisi jāʾa ại̹lay̱ ạủwrusẖalīma ḥasaba yadi ٱllhi ٱlṣãạliḥaẗi ʿalaẙhi."],[7,10,"لِأَنَّ عَزْرَا هَيَّأَ قَلْبَهُ لِطَلَبِ شَرِيعَةِ ٱلرَّبِّ وَٱلْعَمَلِ بِهَا، وَلِيُعَلِّمَ إِسْرَائِيلَ فَرِيضَةً وَقَضَاءً.","liạảnã ʿaz̊rā hayãạả qal̊bahu liṭalabi sẖarīʿaẗi ٱlrãbĩ waٱl̊ʿamali bihā, walīuʿalĩma ại̹s̊rāyỉyla farīḍaẗaⁿ waqaḍāʾaⁿ."],[7,11,"وَهَذِهِ صُورَةُ ٱلرِّسَالَةِ ٱلَّتِي أَعْطَاهَا ٱلْمَلِكُ أَرْتَحْشَشْتَا لِعَزْرَا ٱلْكَاهِنِ ٱلْكَاتِبِ، كَاتِبِ كَلَامِ وَصَايَا ٱلرَّبِّ وَفَرَائِضِهِ عَلَى إِسْرَائِيلَ:","wahadẖihi ṣūraẗu ٱlrĩsālaẗi ٱlãtī ạảʿ̊ṭāhā ٱl̊maliku ạảr̊taḥ̊sẖasẖ̊tā liʿaz̊rā ٱl̊kāhini ٱl̊kātibi, kātibi kalāmi waṣāyā ٱlrãbĩ wafarāyỉḍihi ʿalay̱ ại̹s̊rāyỉyla:"],[7,12,"«مِنْ أَرْتَحْشَشْتَا مَلِكِ ٱلْمُلُوكِ، إِلَى عَزْرَا ٱلْكَاهِنِ كَاتِبِ شَرِيعَةِ إِلَهِ ٱلسَّمَاءِ ٱلْكَامِلِ، إِلَى آخِرِهِ.","«min̊ ạảr̊taḥ̊sẖasẖ̊tā maliki ٱl̊mulūki, ại̹lay̱ ʿaz̊rā ٱl̊kāhini kātibi sẖarīʿaẗi ại̹lahi ٱlsãmāʾi ٱl̊kāmili, ại̹lay̱ ậkẖirihi."],[7,13,"قَدْ صَدَرَ مِنِّي أَمْرٌ أَنَّ كُلَّ مَنْ أَرَادَ فِي مُلْكِي مِنْ شَعْبِ إِسْرَائِيلَ وَكَهَنَتِهِ وَٱللَّاوِيِّينَ أَنْ يَرْجِعَ إِلَى أُورُشَلِيمَ مَعَكَ فَلْيَرْجِعْ.","qad̊ ṣadara minĩy ạảm̊ruⁿ ạảnã kulã man̊ ạảrāda fī mul̊kī min̊ sẖaʿ̊bi ại̹s̊rāyỉyla wakahanatihi waٱllãạwīĩyna ạản̊ yar̊jiʿa ại̹lay̱ ạủwrusẖalīma maʿaka fal̊yar̊jiʿ̊."],[7,14,"مِنْ أَجْلِ أَنَّكَ مُرْسَلٌ مِنْ قِبَلِ ٱلْمَلِكِ وَمُشِيرِيهِ ٱلسَّبْعَةِ لِأَجْلِ ٱلسُّؤَالِ عَنْ يَهُوذَا وَأُورُشَلِيمَ حَسَبَ شَرِيعَةِ إِلَهِكَ ٱلَّتِي بِيَدِكَ،","min̊ ạảj̊li ạảnãka mur̊saluⁿ min̊ qibali ٱl̊maliki wamusẖīrīhi ٱlsãb̊ʿaẗi liạảj̊li ٱlsũwảạli ʿan̊ yahūdẖā wāủwrusẖalīma ḥasaba sẖarīʿaẗi ại̹lahika ٱlãtī bīadika,"],[7,15,"وَلِحَمْلِ فِضَّةٍ وَذَهَبٍ تَبَرَّعَ بِهِ ٱلْمَلِكُ وَمُشِيرُوهُ لِإِلَهِ إِسْرَائِيلَ ٱلَّذِي فِي أُورُشَلِيمَ مَسْكَنُهُ.","waliḥam̊li fiḍãẗiⁿ wadẖahabiⁿ tabarãʿa bihi ٱl̊maliku wamusẖīrūhu liại̹lahi ại̹s̊rāyỉyla ٱlãdẖī fī ạủwrusẖalīma mas̊kanuhu."],[7,16,"وَكُلُّ ٱلْفِضَّةِ وَٱلذَّهَبِ ٱلَّتِي تَجِدُ فِي كُلِّ بِلَادِ بَابِلَ مَعَ تَبَرُّعَاتِ ٱلشَّعْبِ وَٱلْكَهَنَةِ ٱلْمُتَبَرِّعِينَ لِبَيْتِ إِلَهِهِمِ ٱلَّذِي فِي أُورُشَلِيمَ،","wakulũ ٱl̊fiḍãẗi waٱldẖãhabi ٱlãtī tajidu fī kulĩ bilādi bābila maʿa tabarũʿāti ٱlsẖãʿ̊bi waٱl̊kahanaẗi ٱl̊mutabarĩʿīna libaẙti ại̹lahihimi ٱlãdẖī fī ạủwrusẖalīma,"],[7,17,"لِكَيْ تَشْتَرِيَ عَاجِلًا بِهَذِهِ ٱلْفِضَّةِ ثِيرَانًا وَكِبَاشًا وَخِرَافًا وَتَقْدِمَاتِهَا وَسَكَائِبَهَا، وَتُقَرِّبَهَا عَلَى ٱلْمَذْبَحِ ٱلَّذِي فِي بَيْتِ إِلَهِكُمُ ٱلَّذِي فِي أُورُشَلِيمَ.","likaẙ tasẖ̊tarīa ʿājilaⁿạ bihadẖihi ٱl̊fiḍãẗi tẖīrānaⁿạ wakibāsẖaⁿạ wakẖirāfaⁿạ wataq̊dimātihā wasakāyỉbahā, watuqarĩbahā ʿalay̱ ٱl̊madẖ̊baḥi ٱlãdẖī fī baẙti ại̹lahikumu ٱlãdẖī fī ạủwrusẖalīma."],[7,18,"وَمَهْمَا حَسُنَ عِنْدَكَ وَعِنْدَ إِخْوَتِكَ أَنْ تَعْمَلُوهُ بِبَاقِي ٱلْفِضَّةِ وَٱلذَّهَبِ، فَحَسَبَ إِرَادَةِ إِلَهِكُمْ تَعْمَلُونَهُ.","wamah̊mā ḥasuna ʿin̊daka waʿin̊da ại̹kẖ̊watika ạản̊ taʿ̊malūhu bibāqī ٱl̊fiḍãẗi waٱldẖãhabi, faḥasaba ại̹rādaẗi ại̹lahikum̊ taʿ̊malūnahu."],[7,19,"وَٱلْآنِيَةُ ٱلَّتِي تُعْطَى لَكَ لِأَجْلِ خِدْمَةِ بَيْتِ إِلَهِكَ فَسَلِّمْهَا أَمَامَ إِلَهِ أُورُشَلِيمَ.","waٱl̊ậnīaẗu ٱlãtī tuʿ̊ṭay̱ laka liạảj̊li kẖid̊maẗi baẙti ại̹lahika fasalĩm̊hā ạảmāma ại̹lahi ạủwrusẖalīma."],[7,20,"وَبَاقِي ٱحْتِيَاجِ بَيْتِ إِلَهِكَ ٱلَّذِي يَتَّفِقُ لَكَ أَنْ تُعْطِيَهُ، فَأَعْطِهِ مِنْ بَيْتِ خَزَائِنِ ٱلْمَلِكِ.","wabāqī ٱḥ̊tīāji baẙti ại̹lahika ٱlãdẖī yatãfiqu laka ạản̊ tuʿ̊ṭīahu, fāảʿ̊ṭihi min̊ baẙti kẖazāyỉni ٱl̊maliki."],[7,21,"وَمِنِّي أَنَا أَرْتَحْشَشْتَا ٱلْمَلِكِ صَدَرَ أَمْرٌ إِلَى كُلِّ ٱلْخَزَنَةِ ٱلَّذِينَ فِي عَبْرِ ٱلنَّهْرِ أَنَّ كُلَّ مَا يَطْلُبُهُ مِنْكُمْ عَزْرَا ٱلْكَاهِنُ كَاتِبُ شَرِيعَةِ إِلَهِ ٱلسَّمَاءِ فَلْيُعْمَلْ بِسُرْعَةٍ،","waminĩy ạảnā ạảr̊taḥ̊sẖasẖ̊tā ٱl̊maliki ṣadara ạảm̊ruⁿ ại̹lay̱ kulĩ ٱl̊kẖazanaẗi ٱlãdẖīna fī ʿab̊ri ٱlnãh̊ri ạảnã kulã mā yaṭ̊lubuhu min̊kum̊ ʿaz̊rā ٱl̊kāhinu kātibu sẖarīʿaẗi ại̹lahi ٱlsãmāʾi fal̊yuʿ̊mal̊ bisur̊ʿaẗiⁿ,"],[7,22,"إِلَى مِئَةِ وَزْنَةٍ مِنَ ٱلْفِضَّةِ وَمِئَةِ كُرٍّ مِنَ ٱلْحِنْطَةِ وَمِئَةِ بَثٍّ مِنَ ٱلْخَمْرِ وَمِئَةِ بَثٍّ مِنَ ٱلزَّيْتِ، وَٱلْمِلْحِ مِنْ دُونِ تَقْيِيدٍ.","ại̹lay̱ mīảẗi waz̊naẗiⁿ mina ٱl̊fiḍãẗi wamīảẗi kuriⁿ̃ mina ٱl̊ḥin̊ṭaẗi wamīảẗi batẖiⁿ̃ mina ٱl̊kẖam̊ri wamīảẗi batẖiⁿ̃ mina ٱlzãẙti, waٱl̊mil̊ḥi min̊ dūni taq̊yīdiⁿ."],[7,23,"كُلُّ مَا أَمَرَ بِهِ إِلَهُ ٱلسَّمَاءِ فَلْيُعْمَلْ بِٱجْتِهَادٍ لِبَيْتِ إِلَهِ ٱلسَّمَاءِ، لِأَنَّهُ لِمَاذَا يَكُونُ غَضَبٌ عَلَى مُلْكِ ٱلْمَلِكِ وَبَنِيهِ؟","kulũ mā ạảmara bihi ại̹lahu ٱlsãmāʾi fal̊yuʿ̊mal̊ biٱj̊tihādiⁿ libaẙti ại̹lahi ٱlsãmāʾi, liạảnãhu limādẖā yakūnu gẖaḍabuⁿ ʿalay̱ mul̊ki ٱl̊maliki wabanīhi?"],[7,24,"وَنُعْلِمُكُمْ أَنَّ جَمِيعَ ٱلْكَهَنَةِ وَٱللَّاوِيِّينَ وَٱلْمُغَنِّينَ وَٱلْبَوَّابِينَ وَٱلنَّثِينِيمِ وَخُدَّامِ بَيْتِ ٱللهِ هَذَا، لَا يُؤْذَنُ أَنْ يُلْقَى عَلَيْهِمْ جِزْيَةٌ أَوْ خَرَاجٌ أَوْ خِفَارَةٌ.","wanuʿ̊limukum̊ ạảnã jamīʿa ٱl̊kahanaẗi waٱllãạwīĩyna waٱl̊mugẖanĩyna waٱl̊bawãạbīna waٱlnãtẖīnīmi wakẖudãạmi baẙti ٱllhi hadẖā, lā yū̊̉dẖanu ạản̊ yul̊qay̱ ʿalaẙhim̊ jiz̊yaẗuⁿ ạảẘ kẖarājuⁿ ạảẘ kẖifāraẗuⁿ."],[7,25,"أَمَّا أَنْتَ يَا عَزْرَا، فَحَسَبَ حِكْمَةِ إِلَهِكَ ٱلَّتِي بِيَدِكَ ضَعْ حُكَّامًا وَقُضَاةً يَقْضُونَ لِجَمِيعِ ٱلشَّعْبِ ٱلَّذِي فِي عَبْرِ ٱلنَّهْرِ مِنْ جَمِيعِ مَنْ يَعْرِفُ شَرَائِعَ إِلَهِكَ. وَٱلَّذِينَ لَا يَعْرِفُونَ فَعَلِّمُوهُمْ.","ạảmãạ ạản̊ta yā ʿaz̊rā, faḥasaba ḥik̊maẗi ại̹lahika ٱlãtī bīadika ḍaʿ̊ ḥukãạmaⁿạ waquḍāẗaⁿ yaq̊ḍūna lijamīʿi ٱlsẖãʿ̊bi ٱlãdẖī fī ʿab̊ri ٱlnãh̊ri min̊ jamīʿi man̊ yaʿ̊rifu sẖarāyỉʿa ại̹lahika. waٱlãdẖīna lā yaʿ̊rifūna faʿalĩmūhum̊."],[7,26,"وَكُلُّ مَنْ لَا يَعْمَلُ شَرِيعَةَ إِلَهِكَ وَشَرِيعَةَ ٱلْمَلِكِ، فَلْيُقْضَ عَلَيْهِ عَاجِلًا إِمَّا بِٱلْمَوْتِ أَوْ بِٱلنَّفْيِ أَوْ بِغَرَامَةِ ٱلْمَالِ أَوْ بِٱلْحَبْسِ».","wakulũ man̊ lā yaʿ̊malu sẖarīʿaẗa ại̹lahika wasẖarīʿaẗa ٱl̊maliki, fal̊yuq̊ḍa ʿalaẙhi ʿājilaⁿạ ại̹mãạ biٱl̊maẘti ạảẘ biٱlnãf̊yi ạảẘ bigẖarāmaẗi ٱl̊māli ạảẘ biٱl̊ḥab̊si»."],[7,27,"مُبَارَكٌ ٱلرَّبُّ إِلَهُ آبَائِنَا ٱلَّذِي جَعَلَ مِثْلَ هَذَا فِي قَلْبِ ٱلْمَلِكِ لِأَجْلِ تَزْيِينِ بَيْتِ ٱلرَّبِّ ٱلَّذِي فِي أُورُشَلِيمَ.","mubārakuⁿ ٱlrãbũ ại̹lahu ậbāyỉnā ٱlãdẖī jaʿala mitẖ̊la hadẖā fī qal̊bi ٱl̊maliki liạảj̊li taz̊yīni baẙti ٱlrãbĩ ٱlãdẖī fī ạủwrusẖalīma."],[7,28,"وَقَدْ بَسَطَ عَلَيَّ رَحْمَةً أَمَامَ ٱلْمَلِكِ وَمُشِيرِيهِ وَأَمَامَ جَمِيعِ رُؤَسَاءِ ٱلْمَلِكِ ٱلْمُقْتَدِرِينَ. وَأَمَّا أَنَا فَقَدْ تَشَدَّدْتُ حَسَبَ يَدِ ٱلرَّبِّ إِلَهِي عَلَيَّ، وَجَمَعْتُ مِنْ إِسْرَائِيلَ رُؤَسَاءَ لِيَصْعَدُوا مَعِي.","waqad̊ basaṭa ʿalayã raḥ̊maẗaⁿ ạảmāma ٱl̊maliki wamusẖīrīhi wāảmāma jamīʿi rūảsāʾi ٱl̊maliki ٱl̊muq̊tadirīna. wāảmãạ ạảnā faqad̊ tasẖadãd̊tu ḥasaba yadi ٱlrãbĩ ại̹lahī ʿalayã, wajamaʿ̊tu min̊ ại̹s̊rāyỉyla rūảsāʾa līaṣ̊ʿadūạ maʿī."],[8,1,"وَهَؤُلَاءِ هُمْ رُؤُوسُ آبَائِهِمْ وَنِسْبَةُ ٱلَّذِينَ صَعِدُوا مَعِي فِي مُلْكِ أَرْتَحْشَشْتَا ٱلْمَلِكِ مِنْ بَابِلَ:","wahawủlāʾi hum̊ rūủwsu ậbāyỉhim̊ wanis̊baẗu ٱlãdẖīna ṣaʿidūạ maʿī fī mul̊ki ạảr̊taḥ̊sẖasẖ̊tā ٱl̊maliki min̊ bābila:"],[8,2,"مِنْ بَنِي فِينَحَاسَ: جِرْشُومُ. مِنْ بَنِي إِيثَامَارَ: دَانِيَالُ. مِنْ بَنِي دَاوُدَ: حَطُّوشُ.","min̊ banī fīnaḥāsa: jir̊sẖūmu. min̊ banī ại̹ytẖāmāra: dānīālu. min̊ banī dāwuda: ḥaṭũwsẖu."],[8,3,"مِنْ بَنِي شَكَنْيَا مِنْ بَنِي فَرْعُوشَ: زَكَرِيَّا، وَٱنْتَسَبَ مَعَهُ مِنَ ٱلذُّكُورِ مِئَةٌ وَخَمْسُونَ.","min̊ banī sẖakan̊yā min̊ banī far̊ʿūsẖa: zakarīãạ, waٱn̊tasaba maʿahu mina ٱldẖũkūri mīảẗuⁿ wakẖam̊sūna."],[8,4,"مِنْ بَنِي فَحَثَ مُوآبَ: أَلِيهُوعِينَايُ بْنُ زَرَحْيَا، وَمَعَهُ مِئَتَانِ مِنَ ٱلذُّكُورِ.","min̊ banī faḥatẖa mūậba: ạảlīhūʿīnāyu b̊nu zaraḥ̊yā, wamaʿahu mīảtāni mina ٱldẖũkūri."],[8,5,"مِنْ بَنِي شَكَنْيَا: ٱبْنُ يَحْزِيئِيلَ، وَمَعَهُ ثَلَاثُ مِئَةٍ مِنَ ٱلذُّكُورِ.","min̊ banī sẖakan̊yā: ٱb̊nu yaḥ̊zīyỉyla, wamaʿahu tẖalātẖu mīảẗiⁿ mina ٱldẖũkūri."],[8,6,"مِنْ بَنِي عَادِينَ: عَابِدُ بْنُ يُونَاثَانَ، وَمَعَهُ خَمْسُونَ مِنَ ٱلذُّكُورِ.","min̊ banī ʿādīna: ʿābidu b̊nu yūnātẖāna, wamaʿahu kẖam̊sūna mina ٱldẖũkūri."],[8,7,"مِنْ بَنِي عِيلَامَ: يَشْعِيَا بْنُ عَثَلِيَا، وَمَعَهُ سَبْعُونَ مِنَ ٱلذُّكُورِ.","min̊ banī ʿīlāma: yasẖ̊ʿīā b̊nu ʿatẖalīā, wamaʿahu sab̊ʿūna mina ٱldẖũkūri."],[8,8,"وَمِنْ بَنِي شَفَطْيَا: زَبَدْيَا بْنُ مِيخَائِيلَ، وَمَعَهُ ثَمَانُونَ مِنَ ٱلذُّكُورِ.","wamin̊ banī sẖafaṭ̊yā: zabad̊yā b̊nu mīkẖāyỉyla, wamaʿahu tẖamānūna mina ٱldẖũkūri."],[8,9,"مِنْ بَنِي يُوآبَ: عُوبَدْيَا بْنُ يَحِيئِيلَ، وَمَعَهُ مِئَتَانِ وَثَمَانِيَةَ عَشَرَ مِنَ ٱلذُّكُورِ.","min̊ banī yūậba: ʿūbad̊yā b̊nu yaḥīyỉyla, wamaʿahu mīảtāni watẖamānīaẗa ʿasẖara mina ٱldẖũkūri."],[8,10,"وَمِنْ بَنِي شَلُومِيثَ: ٱبْنُ يُوشَفْيَا، وَمَعَهُ مِئَةٌ وَسِتُّونَ مِنَ ٱلذُّكُورِ.","wamin̊ banī sẖalūmītẖa: ٱb̊nu yūsẖaf̊yā, wamaʿahu mīảẗuⁿ wasitũwna mina ٱldẖũkūri."],[8,11,"وَمِنْ بَنِي بَابَايَ: زَكَرِيَّا بْنُ بَابَايَ، وَمَعَهُ ثَمَانِيَةٌ وَعِشْرُونَ مِنَ ٱلذُّكُورِ.","wamin̊ banī bābāya: zakarīãạ b̊nu bābāya, wamaʿahu tẖamānīaẗuⁿ waʿisẖ̊rūna mina ٱldẖũkūri."],[8,12,"وَمِنْ بَنِي عَزْجَدَ: يُوحَانَانُ بْنُ هِقَّاطَانَ، وَمَعَهُ مِئَةٌ وَعَشْرَةٌ مِنَ ٱلذُّكُورِ.","wamin̊ banī ʿaz̊jada: yūḥānānu b̊nu hiqãạṭāna, wamaʿahu mīảẗuⁿ waʿasẖ̊raẗuⁿ mina ٱldẖũkūri."],[8,13,"وَمِنْ بَنِي أَدُونِيقَامَ ٱلْآخَرِينَ وَهَذِهِ أَسْمَاؤُهُمْ: أَلِيفَلَطُ وَيَعِيئِيلُ وَشَمْعِيَا، وَمَعَهُمْ سِتُّونَ مِنَ ٱلذُّكُورِ.","wamin̊ banī ạảdūnīqāma ٱl̊ậkẖarīna wahadẖihi ạảs̊māwủhum̊: ạảlīfalaṭu wayaʿīyỉylu wasẖam̊ʿīā, wamaʿahum̊ sitũwna mina ٱldẖũkūri."],[8,14,"وَمِنْ بَنِي بَغْوَايَ: عُوتَايُ وَزَبُّودُ، وَمَعَهُمَا سَبْعُونَ مِنَ ٱلذُّكُورِ.","wamin̊ banī bagẖ̊wāya: ʿūtāyu wazabũwdu, wamaʿahumā sab̊ʿūna mina ٱldẖũkūri."],[8,15,"فَجَمَعْتُهُمْ إِلَى ٱلنَّهْرِ ٱلْجَارِي إِلَى أَهْوَا وَنَزَلْنَا هُنَاكَ ثَلَاثَةَ أَيَّامٍ. وَتَأَمَّلْتُ ٱلشَّعْبَ وَٱلْكَهَنَةَ، وَلَكِنَّنِي لَمْ أَجِدْ أَحَدًا مِنَ ٱللَّاوِيِّينَ هُنَاكَ.","fajamaʿ̊tuhum̊ ại̹lay̱ ٱlnãh̊ri ٱl̊jārī ại̹lay̱ ạảh̊wā wanazal̊nā hunāka tẖalātẖaẗa ạảyãạmiⁿ. watāảmãl̊tu ٱlsẖãʿ̊ba waٱl̊kahanaẗa, walakinãnī lam̊ ạảjid̊ ạảḥadaⁿạ mina ٱllãạwīĩyna hunāka."],[8,16,"فَأَرْسَلْتُ إِلَى: أَلِيعَزَرَ وَأَرِيئِيلَ وَشَمْعِيَا وَأَلْنَاثَانَ وَيَارِيبَ وَأَلْنَاثَانَ وَنَاثَانَ وَزَكَرِيَّا وَمَشُلَّامَ ٱلرُّؤُوسِ، وَإِلَى يُويَارِيبَ وَأَلْنَاثَانَ ٱلْفَهِيمَيْنِ،","fāảr̊sal̊tu ại̹lay̱: ạảlīʿazara wāảrīyỉyla wasẖam̊ʿīā wāảl̊nātẖāna wayārība wāảl̊nātẖāna wanātẖāna wazakarīãạ wamasẖulãạma ٱlrũwủwsi, wāi̹lay̱ yūyārība wāảl̊nātẖāna ٱl̊fahīmaẙni,"],[8,17,"وَأَرْسَلْتُهُمْ إِلَى إِدُّو ٱلرَّأْسِ فِي ٱلْمَكَانِ ٱلْمُسَمَّى كَسِفْيَا، وَجَعَلْتُ فِي أَفْوَاهِهِمْ كَلَامًا يُكَلِّمُونَ بِهِ إِدُّوَ وَإِخْوَتَهُ ٱلنَّثِينِيمَ فِي ٱلْمَكَانِ كَسِفْيَا لِيَأْتُوا إِلَيْنَا بِخُدَّامٍ لِبَيْتِ إِلَهِنَا.","wāảr̊sal̊tuhum̊ ại̹lay̱ ại̹dũw ٱlrãạ̊̉si fī ٱl̊makāni ٱl̊musamãy̱ kasif̊yā, wajaʿal̊tu fī ạảf̊wāhihim̊ kalāmaⁿạ yukalĩmūna bihi ại̹dũwa wāi̹kẖ̊watahu ٱlnãtẖīnīma fī ٱl̊makāni kasif̊yā līā̊̉tūạ ại̹laẙnā bikẖudãạmiⁿ libaẙti ại̹lahinā."],[8,18,"فَأَتَوْا إِلَيْنَا حَسَبَ يَدِ ٱللهِ ٱلصَّالِحَةِ عَلَيْنَا بِرَجُلٍ فَطِنٍ مِنْ بَنِي مَحْلِي بْنِ لَاوِي بْنِ إِسْرَائِيلَ وَشَرَبْيَا وَبَنِيهِ وَإِخْوَتِهِ ثَمَانِيَةَ عَشَرَ،","fāảtaẘạ ại̹laẙnā ḥasaba yadi ٱllhi ٱlṣãạliḥaẗi ʿalaẙnā birajuliⁿ faṭiniⁿ min̊ banī maḥ̊lī b̊ni lāwī b̊ni ại̹s̊rāyỉyla wasẖarab̊yā wabanīhi wāi̹kẖ̊watihi tẖamānīaẗa ʿasẖara,"],[8,19,"وَحَشَبْيَا وَمَعْهُ يَشَعْيَا مِنْ بَنِي مَرَارِي وَإِخْوَتُهُ وَبَنُوهُمْ عِشْرُونَ.","waḥasẖab̊yā wamaʿ̊hu yasẖaʿ̊yā min̊ banī marārī wāi̹kẖ̊watuhu wabanūhum̊ ʿisẖ̊rūna."],[8,20,"وَمِنَ ٱلنَّثِينِيمِ ٱلَّذِينَ جَعَلَهُمْ دَاوُدُ مَعَ ٱلرُّؤَسَاءِ لِخِدْمَةِ ٱللَّاوِيِّينَ مِنَ ٱلنَّثِينِيمِ مِئَتَيْنِ وَعِشْرِينَ. ٱلْجَمِيعُ تَعَيَّنُوا بِأَسْمَائِهِمْ.","wamina ٱlnãtẖīnīmi ٱlãdẖīna jaʿalahum̊ dāwudu maʿa ٱlrũwảsāʾi likẖid̊maẗi ٱllãạwīĩyna mina ٱlnãtẖīnīmi mīảtaẙni waʿisẖ̊rīna. ٱl̊jamīʿu taʿayãnūạ biạảs̊māyỉhim̊."],[8,21,"وَنَادَيْتُ هُنَاكَ بِصَوْمٍ عَلَى نَهْرِ أَهْوَا لِكَيْ نَتَذَلَّلَ أَمَامَ إِلَهِنَا لِنَطْلُبَ مِنْهُ طَرِيقًا مُسْتَقِيمَةً لَنَا وَلِأَطْفَالِنَا وَلِكُلِّ مَالِنَا.","wanādaẙtu hunāka biṣaẘmiⁿ ʿalay̱ nah̊ri ạảh̊wā likaẙ natadẖalãla ạảmāma ại̹lahinā linaṭ̊luba min̊hu ṭarīqaⁿạ mus̊taqīmaẗaⁿ lanā waliạảṭ̊fālinā walikulĩ mālinā."],[8,22,"لِأَنِّي خَجِلْتُ مِنْ أَنْ أَطْلُبَ مِنَ ٱلْمَلِكِ جَيْشًا وَفُرْسَانًا لِيُنْجِدُونَا عَلَى ٱلْعَدُوِّ فِي ٱلطَّرِيقِ، لِأَنَّنَا كَلَّمْنَا ٱلْمَلِكَ قَائِلِينَ: «إِنَّ يَدَ إِلَهِنَا عَلَى كُلِّ طَالِبِيهِ لِلْخَيْرِ، وَصَوْلَتَهُ وَغَضَبَهُ عَلَى كُلِّ مَنْ يَتْرُكُهُ».","liạảnĩy kẖajil̊tu min̊ ạản̊ ạảṭ̊luba mina ٱl̊maliki jaẙsẖaⁿạ wafur̊sānaⁿạ līun̊jidūnā ʿalay̱ ٱl̊ʿadūĩ fī ٱlṭãrīqi, liạảnãnā kalãm̊nā ٱl̊malika qāyỉlīna: «ại̹nã yada ại̹lahinā ʿalay̱ kulĩ ṭālibīhi lil̊kẖaẙri, waṣaẘlatahu wagẖaḍabahu ʿalay̱ kulĩ man̊ yat̊rukuhu»."],[8,23,"فَصُمْنَا وَطَلَبْنَا ذَلِكَ مِنْ إِلَهِنَا فَٱسْتَجَابَ لَنَا.","faṣum̊nā waṭalab̊nā dẖalika min̊ ại̹lahinā faٱs̊tajāba lanā."],[8,24,"وَأَفْرَزْتُ مِنْ رُؤَسَاءِ ٱلْكَهَنَةِ ٱثْنَيْ عَشَرَ: شَرَبْيَا وَحَشَبْيَا، وَمَعْهُمَا مِنْ إِخْوَتِهِمَا عَشَرَةٌ.","wāảf̊raz̊tu min̊ rūảsāʾi ٱl̊kahanaẗi ٱtẖ̊naẙ ʿasẖara: sẖarab̊yā waḥasẖab̊yā, wamaʿ̊humā min̊ ại̹kẖ̊watihimā ʿasẖaraẗuⁿ."],[8,25,"وَوَزَنْتُ لَهُمُ ٱلْفِضَّةَ وَٱلذَّهَبَ وَٱلْآنِيَةَ، تَقْدِمَةَ بَيْتِ إِلَهِنَا ٱلَّتِي قَدَّمَهَا ٱلْمَلِكُ وَمُشِيرُوهُ وَرُؤَسَاؤُهُ وَجَمِيعُ إِسْرَائِيلَ ٱلْمَوْجُودِينَ،","wawazan̊tu lahumu ٱl̊fiḍãẗa waٱldẖãhaba waٱl̊ậnīaẗa, taq̊dimaẗa baẙti ại̹lahinā ٱlãtī qadãmahā ٱl̊maliku wamusẖīrūhu warūảsāwủhu wajamīʿu ại̹s̊rāyỉyla ٱl̊maẘjūdīna,"],[8,26,"وَزَنْتُ لِيَدِهِمْ سِتَّ مِئَةٍ وَخَمْسِينَ وَزْنَةً مِنَ ٱلْفِضَّةِ، وَمِئَةَ وَزْنَةٍ مِنْ آنِيَةِ ٱلْفِضَّةِ، وَمِئَةَ وَزْنَةٍ مِنَ ٱلذَّهَبِ،","wazan̊tu līadihim̊ sitã mīảẗiⁿ wakẖam̊sīna waz̊naẗaⁿ mina ٱl̊fiḍãẗi, wamīảẗa waz̊naẗiⁿ min̊ ậnīaẗi ٱl̊fiḍãẗi, wamīảẗa waz̊naẗiⁿ mina ٱldẖãhabi,"],[8,27,"وَعِشْرِينَ قَدَحًا مِنَ ٱلذَّهَبِ أَلْفَ دِرْهَمٍ، وَآنِيَةً مِنْ نُحَاسٍ صَقِيلٍ جَيِّدٍ ثَمِينٍ كَٱلذَّهَبِ.","waʿisẖ̊rīna qadaḥaⁿạ mina ٱldẖãhabi ạảl̊fa dir̊hamiⁿ, wā̂nīaẗaⁿ min̊ nuḥāsiⁿ ṣaqīliⁿ jayĩdiⁿ tẖamīniⁿ kaٱldẖãhabi."],[8,28,"وَقُلْتُ لَهُمْ: «أَنْتُمْ مُقَدَّسُونَ لِلرَّبِّ، وَٱلْآنِيَةُ مُقَدَّسَةٌ، وَٱلْفِضَّةُ وَٱلذَّهَبُ تَبَرُّعٌ لِلرَّبِّ إِلَهِ آبَائِكُمْ.","waqul̊tu lahum̊: «ạản̊tum̊ muqadãsūna lilrãbĩ, waٱl̊ậnīaẗu muqadãsaẗuⁿ, waٱl̊fiḍãẗu waٱldẖãhabu tabarũʿuⁿ lilrãbĩ ại̹lahi ậbāyỉkum̊."],[8,29,"فَٱسْهَرُوا وَٱحْفَظُوهَا حَتَّى تَزِنُوهَا أَمَامَ رُؤَسَاءِ ٱلْكَهَنَةِ وَٱللَّاوِيِّينَ وَرُؤَسَاءِ آبَاءِ إِسْرَائِيلَ فِي أُورُشَلِيمَ، فِي مَخَادِعِ بَيْتِ ٱلرَّبِّ».","faٱs̊harūạ waٱḥ̊faẓūhā ḥatãy̱ tazinūhā ạảmāma rūảsāʾi ٱl̊kahanaẗi waٱllãạwīĩyna warūảsāʾi ậbāʾi ại̹s̊rāyỉyla fī ạủwrusẖalīma, fī makẖādiʿi baẙti ٱlrãbĩ»."],[8,30,"فَأَخَذَ ٱلْكَهَنَةُ وَٱللَّاوِيُّونَ وَزْنَ ٱلْفِضَّةِ وَٱلذَّهَبِ وَٱلْآنِيَةِ لِيَأْتُوا بِهَا إِلَى أُورُشَلِيمَ، إِلَى بَيْتِ إِلَهِنَا.","fāảkẖadẖa ٱl̊kahanaẗu waٱllãạwīũwna waz̊na ٱl̊fiḍãẗi waٱldẖãhabi waٱl̊ậnīaẗi līā̊̉tūạ bihā ại̹lay̱ ạủwrusẖalīma, ại̹lay̱ baẙti ại̹lahinā."],[8,31,"ثُمَّ رَحَلْنَا مِنْ نَهْرِ أَهْوَا فِي ٱلثَّانِي عَشَرَ مِنَ ٱلشَّهْرِ ٱلْأَوَّلِ لِنَذْهَبَ إِلَى أُورُشَلِيمَ، وَكَانَتْ يَدُ إِلَهِنَا عَلَيْنَا، فَأَنْقَذَنَا مِنْ يَدِ ٱلْعَدُوِّ وَٱلْكَامِنِ عَلَى ٱلطَّرِيقِ.","tẖumã raḥal̊nā min̊ nah̊ri ạảh̊wā fī ٱltẖãạnī ʿasẖara mina ٱlsẖãh̊ri ٱl̊ạảwãli linadẖ̊haba ại̹lay̱ ạủwrusẖalīma, wakānat̊ yadu ại̹lahinā ʿalaẙnā, fāản̊qadẖanā min̊ yadi ٱl̊ʿadūĩ waٱl̊kāmini ʿalay̱ ٱlṭãrīqi."],[8,32,"فَأَتَيْنَا إِلَى أُورُشَلِيمَ وَأَقَمْنَا هُنَاكَ ثَلَاثَةَ أَيَّامٍ.","fāảtaẙnā ại̹lay̱ ạủwrusẖalīma wāảqam̊nā hunāka tẖalātẖaẗa ạảyãạmiⁿ."],[8,33,"وَفِي ٱلْيَوْمِ ٱلرَّابِع وُزِنَتِ ٱلْفِضَّةُ وَٱلذَّهَبُ وَٱلْآنِيَةُ فِي بَيْتِ إِلَهِنَا عَلَى يَدِ مَرِيمُوثَ بْنِ أُورِيَّا ٱلْكَاهِنِ، وَمَعَهُ أَلِعَازَارُ بْنُ فِينَحَاسَ، وَمَعَهُمَا يُوزَابَادُ بْنُ يَشُوعَ وَنُوعَدْيَا بْنُ بَنُّويَ ٱللَّاوِيَّانِ.","wafī ٱl̊yaẘmi ٱlrãạbiʿ wuzinati ٱl̊fiḍãẗu waٱldẖãhabu waٱl̊ậnīaẗu fī baẙti ại̹lahinā ʿalay̱ yadi marīmūtẖa b̊ni ạủwrīãạ ٱl̊kāhini, wamaʿahu ạảliʿāzāru b̊nu fīnaḥāsa, wamaʿahumā yūzābādu b̊nu yasẖūʿa wanūʿad̊yā b̊nu banũwya ٱllãạwīãạni."],[8,34,"بِٱلْعَدَدِ وَٱلْوَزْنِ لِلْكُلِّ، وَكُتِبَ كُلُّ ٱلْوَزْنِ فِي ذَلِكَ ٱلْوَقْتِ.","biٱl̊ʿadadi waٱl̊waz̊ni lil̊kulĩ, wakutiba kulũ ٱl̊waz̊ni fī dẖalika ٱl̊waq̊ti."],[8,35,"وَبَنُو ٱلسَّبْيِ ٱلْقَادِمُونَ مِنَ ٱلسَّبْيِ قَرَّبُوا مُحْرَقَاتٍ لِإِلَهِ إِسْرَائِيلَ، ٱثْنَيْ عَشَرَ ثَوْرًا عَنْ كُلِّ إِسْرَائِيلَ، وَسِتَّةً وَتِسْعِينَ كَبْشًا وَسَبْعَةً وَسَبْعِينَ خَرُوفًا وَٱثْنَيْ عَشَرَ تَيْسًا، ذَبِيحَةَ خَطِيَّةٍ ٱلْجَمِيعُ مُحْرَقَةٌ لِلرَّبِّ.","wabanū ٱlsãb̊yi ٱl̊qādimūna mina ٱlsãb̊yi qarãbūạ muḥ̊raqātiⁿ liại̹lahi ại̹s̊rāyỉyla, ٱtẖ̊naẙ ʿasẖara tẖaẘraⁿạ ʿan̊ kulĩ ại̹s̊rāyỉyla, wasitãẗaⁿ watis̊ʿīna kab̊sẖaⁿạ wasab̊ʿaẗaⁿ wasab̊ʿīna kẖarūfaⁿạ waٱtẖ̊naẙ ʿasẖara taẙsaⁿạ, dẖabīḥaẗa kẖaṭīãẗiⁿ ٱl̊jamīʿu muḥ̊raqaẗuⁿ lilrãbĩ."],[8,36,"وَأَعْطَوْا أَوَامِرَ ٱلْمَلِكِ لِمَرَازِبَةِ ٱلْمَلِكِ وَوُلَاةِ عَبْرِ ٱلنَّهْرِ، فَأَعَانُوا ٱلشَّعْبَ وَبَيْتَ ٱللهِ.","wāảʿ̊ṭaẘạ ạảwāmira ٱl̊maliki limarāzibaẗi ٱl̊maliki wawulāẗi ʿab̊ri ٱlnãh̊ri, fāảʿānūạ ٱlsẖãʿ̊ba wabaẙta ٱllhi."],[9,1,"وَلَمَّا كَمَلَتْ هَذِهِ تَقَدَّمَ إِلَيَّ ٱلرُّؤَسَاءُ قَائِلِينَ: «لَمْ يَنْفَصِلْ شَعْبُ إِسْرَائِيلَ وَٱلْكَهَنَةُ وَٱللَّاوِيُّونَ مِنْ شُعُوبِ ٱلْأَرَاضِي حَسَبَ رَجَاسَاتِهِمْ، مِنَ ٱلْكَنْعَانِيِّينَ وَٱلْحِثِّيِّينَ وَٱلْفِرِزِّيِّينَ وَٱلْيَبُوسِيِّينَ وَٱلْعَمُّونِيِّينَ وَٱلْمُوآبِيِّينَ وَٱلْمِصْرِيِّينَ وَٱلْأَمُورِيِّينَ.","walamãạ kamalat̊ hadẖihi taqadãma ại̹layã ٱlrũwảsāʾu qāyỉlīna: «lam̊ yan̊faṣil̊ sẖaʿ̊bu ại̹s̊rāyỉyla waٱl̊kahanaẗu waٱllãạwīũwna min̊ sẖuʿūbi ٱl̊ạảrāḍī ḥasaba rajāsātihim̊, mina ٱl̊kan̊ʿānīĩyna waٱl̊ḥitẖĩyĩyna waٱl̊firizĩyĩyna waٱl̊yabūsīĩyna waٱl̊ʿamũwnīĩyna waٱl̊mūậbīĩyna waٱl̊miṣ̊rīĩyna waٱl̊ạảmūrīĩyna."],[9,2,"لِأَنَّهُمُ ٱتَّخَذُوا مِنْ بَنَاتِهِمْ لِأَنْفُسِهِمْ وَلِبَنِيهِمْ، وَٱخْتَلَطَ ٱلزَّرْعُ ٱلْمُقَدَّسُ بِشُعُوبِ ٱلْأَرَاضِي. وَكَانَتْ يَدُ ٱلرُّؤَسَاءِ وَٱلْوُلَاةِ فِي هَذِهِ ٱلْخِيَانَةِ أَوَّلًا».","liạảnãhumu ٱtãkẖadẖūạ min̊ banātihim̊ liạản̊fusihim̊ walibanīhim̊, waٱkẖ̊talaṭa ٱlzãr̊ʿu ٱl̊muqadãsu bisẖuʿūbi ٱl̊ạảrāḍī. wakānat̊ yadu ٱlrũwảsāʾi waٱl̊wulāẗi fī hadẖihi ٱl̊kẖīānaẗi ạảwãlaⁿạ»."],[9,3,"فَلَمَّا سَمِعْتُ بِهَذَا ٱلْأَمْرِ مَزَّقْتُ ثِيَابِي وَرِدَائِي وَنَتَّفْتُ شَعْرَ رَأْسِي وَذَقْنِي وَجَلَسْتُ مُتَحَيِّرًا.","falamãạ samiʿ̊tu bihadẖā ٱl̊ạảm̊ri mazãq̊tu tẖīābī waridāyỉy wanatãf̊tu sẖaʿ̊ra rā̊̉sī wadẖaq̊nī wajalas̊tu mutaḥayĩraⁿạ."],[9,4,"فَٱجْتَمَعَ إِلَيَّ كُلُّ مَنِ ٱرْتَعَدَ مِنْ كَلَامِ إِلَهِ إِسْرَائِيلَ مِنْ أَجْلِ خِيَانَةِ ٱلْمَسْبِيِّينَ، وَأَنَا جَلَسْتُ مُتَحَيِّرًا إِلَى تَقْدِمَةِ ٱلْمَسَاءِ.","faٱj̊tamaʿa ại̹layã kulũ mani ٱr̊taʿada min̊ kalāmi ại̹lahi ại̹s̊rāyỉyla min̊ ạảj̊li kẖīānaẗi ٱl̊mas̊bīĩyna, wāảnā jalas̊tu mutaḥayĩraⁿạ ại̹lay̱ taq̊dimaẗi ٱl̊masāʾi."],[9,5,"وَعِنْدَ تَقْدِمَةِ ٱلْمَسَاءِ قُمْتُ مِنْ تَذَلُّلِي، وَفِي ثِيَابِي وَرِدَائِي ٱلْمُمَزَّقَةِ جَثَوْتُ عَلَى رُكْبَتَيَّ وَبَسَطْتُ يَدَيَّ إِلَى ٱلرَّبِّ إِلَهِي،","waʿin̊da taq̊dimaẗi ٱl̊masāʾi qum̊tu min̊ tadẖalũlī, wafī tẖīābī waridāyỉy ٱl̊mumazãqaẗi jatẖaẘtu ʿalay̱ ruk̊batayã wabasaṭ̊tu yadayã ại̹lay̱ ٱlrãbĩ ại̹lahī,"],[9,6,"وَقُلْتُ: «ٱللَّهُمَّ، إِنِّي أَخْجَلُ وَأَخْزَى مِنْ أَنْ أَرْفَعَ يَا إِلَهِي وَجْهِي نَحْوَكَ، لِأَنَّ ذُنُوبَنَا قَدْ كَثُرَتْ فَوْقَ رُؤُوسِنَا، وَآثَامَنَا تَعَاظَمَتْ إِلَى ٱلسَّمَاءِ.","waqul̊tu: «ٱllãhumã, ại̹nĩy ạảkẖ̊jalu wāảkẖ̊zay̱ min̊ ạản̊ ạảr̊faʿa yā ại̹lahī waj̊hī naḥ̊waka, liạảnã dẖunūbanā qad̊ katẖurat̊ faẘqa rūủwsinā, wā̂tẖāmanā taʿāẓamat̊ ại̹lay̱ ٱlsãmāʾi."],[9,7,"مُنْذُ أَيَّامِ آبَائِنَا نَحْنُ فِي إِثْمٍ عَظِيمٍ إِلَى هَذَا ٱلْيَوْمِ. وَلِأَجْلِ ذُنُوبِنَا قَدْ دُفِعْنَا نَحْنُ وَمُلُوكُنَا وَكَهَنَتُنَا لِيَدِ مُلُوكِ ٱلْأَرَاضِي لِلسَّيْفِ وَٱلسَّبْيِ وَٱلنَّهْبِ وَخِزْيِ ٱلْوُجُوهِ كَهَذَا ٱلْيَوْمِ.","mun̊dẖu ạảyãạmi ậbāyỉnā naḥ̊nu fī ại̹tẖ̊miⁿ ʿaẓīmiⁿ ại̹lay̱ hadẖā ٱl̊yaẘmi. waliạảj̊li dẖunūbinā qad̊ dufiʿ̊nā naḥ̊nu wamulūkunā wakahanatunā līadi mulūki ٱl̊ạảrāḍī lilsãẙfi waٱlsãb̊yi waٱlnãh̊bi wakẖiz̊yi ٱl̊wujūhi kahadẖā ٱl̊yaẘmi."],[9,8,"وَٱلْآنَ كَلُحَيْظَةٍ كَانَتْ رَأْفَةٌ مِنْ لَدُنِ ٱلرَّبِّ إِلَهِنَا لِيُبْقِيَ لَنَا نَجَاةً وَيُعْطِيَنَا وَتَدًا فِي مَكَانِ قُدْسِهِ، لِيُنِيرَ إِلَهُنَا أَعْيُنَنَا وَيُعْطِيَنَا حَيَاةً قَلِيلَةً فِي عُبُودِيَّتِنَا.","waٱl̊ậna kaluḥaẙẓaẗiⁿ kānat̊ rā̊̉faẗuⁿ min̊ laduni ٱlrãbĩ ại̹lahinā līub̊qīa lanā najāẗaⁿ wayuʿ̊ṭīanā watadaⁿạ fī makāni qud̊sihi, līunīra ại̹lahunā ạảʿ̊yunanā wayuʿ̊ṭīanā ḥayāẗaⁿ qalīlaẗaⁿ fī ʿubūdīãtinā."],[9,9,"لِأَنَّنَا عَبِيدٌ نَحْنُ، وَفِي عُبُودِيَّتِنَا لَمْ يَتْرُكْنَا إِلَهُنَا بَلْ بَسَطَ عَلَيْنَا رَحْمَةً أَمَامَ مُلُوكِ فَارِسَ، لِيُعْطِيَنَا حَيَاةً لِنَرْفَعَ بَيْتَ إِلَهِنَا وَنُقِيمَ خَرَائِبَهُ، وَلْيُعْطِيَنَا حَائِطًا فِي يَهُوذَا وَفِي أُورُشَلِيمَ.","liạảnãnā ʿabīduⁿ naḥ̊nu, wafī ʿubūdīãtinā lam̊ yat̊ruk̊nā ại̹lahunā bal̊ basaṭa ʿalaẙnā raḥ̊maẗaⁿ ạảmāma mulūki fārisa, līuʿ̊ṭīanā ḥayāẗaⁿ linar̊faʿa baẙta ại̹lahinā wanuqīma kẖarāyỉbahu, wal̊yuʿ̊ṭīanā ḥāyỉṭaⁿạ fī yahūdẖā wafī ạủwrusẖalīma."],[9,10,"وَٱلْآنَ، فَمَاذَا نَقُولُ يَا إِلَهَنَا بَعْدَ هَذَا؟ لِأَنَّنَا قَدْ تَرَكْنَا وَصَايَاكَ","waٱl̊ậna, famādẖā naqūlu yā ại̹lahanā baʿ̊da hadẖā? liạảnãnā qad̊ tarak̊nā waṣāyāka"],[9,11,"ٱلَّتِي أَوْصَيْتَ بِهَا عَنْ يَدِ عَبِيدِكَ ٱلْأَنْبِيَاءِ قَائِلًا: إِنَّ ٱلْأَرْضَ ٱلَّتِي تَدْخُلُونَ لِتَمْتَلِكُوهَا هِيَ أَرْضٌ مُتَنَجِّسَةٌ بِنَجَاسَةِ شُعُوبِ ٱلْأَرَاضِي، بِرَجَاسَاتِهِمِ ٱلَّتِي مَلَأُوهَا بِهَا مِنْ جِهَةٍ إِلَى جِهَةٍ بِنَجَاسَتِهِمْ.","ٱlãtī ạảẘṣaẙta bihā ʿan̊ yadi ʿabīdika ٱl̊ạản̊bīāʾi qāyỉlaⁿạ: ại̹nã ٱl̊ạảr̊ḍa ٱlãtī tad̊kẖulūna litam̊talikūhā hīa ạảr̊ḍuⁿ mutanajĩsaẗuⁿ binajāsaẗi sẖuʿūbi ٱl̊ạảrāḍī, birajāsātihimi ٱlãtī malāủwhā bihā min̊ jihaẗiⁿ ại̹lay̱ jihaẗiⁿ binajāsatihim̊."],[9,12,"وَٱلْآنَ فَلَا تُعْطُوا بَنَاتِكُمْ لِبَنِيهِمْ وَلَا تَأْخُذُوا بَنَاتِهِمْ لِبَنِيكُمْ، وَلَا تَطْلُبُوا سَلَامَتَهُمْ وَخَيْرَهُمْ إِلَى ٱلْأَبَدِ لِكَيْ تَتَشَدَّدُوا وَتَأْكُلُوا خَيْرَ ٱلْأَرْضِ وَتُورِثُوا بَنِيكُمْ إِيَّاهَا إِلَى ٱلْأَبَدِ.","waٱl̊ậna falā tuʿ̊ṭūạ banātikum̊ libanīhim̊ walā tā̊̉kẖudẖūạ banātihim̊ libanīkum̊, walā taṭ̊lubūạ salāmatahum̊ wakẖaẙrahum̊ ại̹lay̱ ٱl̊ạảbadi likaẙ tatasẖadãdūạ watā̊̉kulūạ kẖaẙra ٱl̊ạảr̊ḍi watūritẖūạ banīkum̊ ại̹yãạhā ại̹lay̱ ٱl̊ạảbadi."],[9,13,"وَبَعْدَ كُلِّ مَا جَاءَ عَلَيْنَا لِأَجْلِ أَعْمَالِنَا ٱلرَّدِيئَةِ وَآثَامِنَا ٱلْعَظِيمَةِ، لِأَنَّكَ قَدْ جَازَيْتَنَا يَا إِلَهَنَا أَقَلَّ مِنْ آثَامِنَا وَأَعْطَيْتَنَا نَجَاةً كَهَذِهِ،","wabaʿ̊da kulĩ mā jāʾa ʿalaẙnā liạảj̊li ạảʿ̊mālinā ٱlrãdīyảẗi wā̂tẖāminā ٱl̊ʿaẓīmaẗi, liạảnãka qad̊ jāzaẙtanā yā ại̹lahanā ạảqalã min̊ ậtẖāminā wāảʿ̊ṭaẙtanā najāẗaⁿ kahadẖihi,"],[9,14,"أَفَنَعُودُ وَنَتَعَدَّى وَصَايَاكَ وَنُصَاهِرُ شُعُوبَ هَذِهِ ٱلرَّجَاسَاتِ؟ أَمَا تَسْخَطُ عَلَيْنَا حَتَّى تُفْنِيَنَا فَلَا تَكُونُ بَقِيَّةٌ وَلَا نَجَاةٌ؟","ạảfanaʿūdu wanataʿadãy̱ waṣāyāka wanuṣāhiru sẖuʿūba hadẖihi ٱlrãjāsāti? ạảmā tas̊kẖaṭu ʿalaẙnā ḥatãy̱ tuf̊nīanā falā takūnu baqīãẗuⁿ walā najāẗuⁿ?"],[9,15,"أَيُّهَا ٱلرَّبُّ إِلَهَ إِسْرَائِيلَ، أَنْتَ بَارٌّ لِأَنَّنَا بَقِينَا نَاجِينَ كَهَذَا ٱلْيَوْمِ. هَا نَحْنُ أَمَامَكَ فِي آثَامِنَا، لِأَنَّهُ لَيْسَ لَنَا أَنْ نَقِفَ أَمَامَكَ مِنْ أَجْلِ هَذَا».","ạảyũhā ٱlrãbũ ại̹laha ại̹s̊rāyỉyla, ạản̊ta bāruⁿ̃ liạảnãnā baqīnā nājīna kahadẖā ٱl̊yaẘmi. hā naḥ̊nu ạảmāmaka fī ậtẖāminā, liạảnãhu laẙsa lanā ạản̊ naqifa ạảmāmaka min̊ ạảj̊li hadẖā»."],[10,1,"فَلَمَّا صَلَّى عَزْرَا وَٱعْتَرَفَ وَهُوَ بَاكٍ وَسَاقِطٌ أَمَامَ بَيْتِ ٱللهِ، ٱجْتَمَعَ إِلَيْهِ مِنْ إِسْرَائِيلَ جَمَاعَةٌ كَثِيرَةٌ جِدًّا مِنَ ٱلرِّجَالِ وَٱلنِّسَاءِ وَٱلْأَوْلَادِ، لِأَنَّ ٱلشَّعْبَ بَكَى بُكَاءً عَظِيمًا.","falamãạ ṣalãy̱ ʿaz̊rā waٱʿ̊tarafa wahūa bākiⁿ wasāqiṭuⁿ ạảmāma baẙti ٱllhi, ٱj̊tamaʿa ại̹laẙhi min̊ ại̹s̊rāyỉyla jamāʿaẗuⁿ katẖīraẗuⁿ jidaⁿ̃ạ mina ٱlrĩjāli waٱlnĩsāʾi waٱl̊ạảẘlādi, liạảnã ٱlsẖãʿ̊ba bakay̱ bukāʾaⁿ ʿaẓīmaⁿạ."],[10,2,"وَأَجَابَ شَكَنْيَا بْنُ يَحِيئِيلَ مِنْ بَنِي عِيلَامَ وَقَالَ لِعَزْرَا: «إِنَّنَا قَدْ خُنَّا إِلَهَنَا وَٱتَّخَذْنَا نِسَاءً غَرِيبَةً مِنْ شُعُوبِ ٱلْأَرْضِ. وَلَكِنِ ٱلْآنَ يُوجَدُ رَجَاءٌ لِإِسْرَائِيلَ فِي هَذَا.","wāảjāba sẖakan̊yā b̊nu yaḥīyỉyla min̊ banī ʿīlāma waqāla liʿaz̊rā: «ại̹nãnā qad̊ kẖunãạ ại̹lahanā waٱtãkẖadẖ̊nā nisāʾaⁿ gẖarībaẗaⁿ min̊ sẖuʿūbi ٱl̊ạảr̊ḍi. walakini ٱl̊ậna yūjadu rajāʾuⁿ liại̹s̊rāyỉyla fī hadẖā."],[10,3,"فَلْنَقْطَعِ ٱلْآنَ عَهْدًا مَعَ إِلَهِنَا أَنْ نُخْرِجَ كُلَّ ٱلنِّسَاءِ وَٱلَّذِينَ وُلِدُوا مِنْهُنَّ، حَسَبَ مَشُورَةِ سَيِّدِي، وَٱلَّذِينَ يَخْشَوْنَ وَصِيَّةَ إِلَهِنَا، وَلْيُعْمَلْ حَسَبَ ٱلشَّرِيعَةِ.","fal̊naq̊ṭaʿi ٱl̊ậna ʿah̊daⁿạ maʿa ại̹lahinā ạản̊ nukẖ̊rija kulã ٱlnĩsāʾi waٱlãdẖīna wulidūạ min̊hunã, ḥasaba masẖūraẗi sayĩdī, waٱlãdẖīna yakẖ̊sẖaẘna waṣīãẗa ại̹lahinā, wal̊yuʿ̊mal̊ ḥasaba ٱlsẖãrīʿaẗi."],[10,4,"قُمْ فَإِنَّ عَلَيْكَ ٱلْأَمْرَ وَنَحْنُ مَعَكَ. تَشَجَّعْ وَٱفْعَلْ».","qum̊ fāi̹nã ʿalaẙka ٱl̊ạảm̊ra wanaḥ̊nu maʿaka. tasẖajãʿ̊ waٱf̊ʿal̊»."],[10,5,"فَقَامَ عَزْرَا وَٱسْتَحْلَفَ رُؤَسَاءَ ٱلْكَهَنَةِ وَٱللَّاوِيِّينَ وَكُلَّ إِسْرَائِيلَ أَنْ يَعْمَلُوا حَسَبَ هَذَا ٱلْأَمْرِ، فَحَلَفُوا.","faqāma ʿaz̊rā waٱs̊taḥ̊lafa rūảsāʾa ٱl̊kahanaẗi waٱllãạwīĩyna wakulã ại̹s̊rāyỉyla ạản̊ yaʿ̊malūạ ḥasaba hadẖā ٱl̊ạảm̊ri, faḥalafūạ."],[10,6,"ثُمَّ قَامَ عَزْرَا مِنْ أَمَامِ بَيْتِ ٱللهِ وَذَهَبَ إِلَى مُخْدَعِ يَهُوحَانَانَ بْنِ أَلْيَاشِيبَ. فَٱنْطَلَقَ إِلَى هُنَاكَ وَهُوَ لَمْ يَأْكُلْ خُبْزًا وَلَمْ يَشْرَبْ مَاءً، لِأَنَّهُ كَانَ يَنُوحُ بِسَبَبِ خِيَانَةِ أَهْلِ ٱلسَّبْيِ.","tẖumã qāma ʿaz̊rā min̊ ạảmāmi baẙti ٱllhi wadẖahaba ại̹lay̱ mukẖ̊daʿi yahūḥānāna b̊ni ạảl̊yāsẖība. faٱn̊ṭalaqa ại̹lay̱ hunāka wahūa lam̊ yā̊̉kul̊ kẖub̊zaⁿạ walam̊ yasẖ̊rab̊ māʾaⁿ, liạảnãhu kāna yanūḥu bisababi kẖīānaẗi ạảh̊li ٱlsãb̊yi."],[10,7,"وَأَطْلَقُوا نِدَاءً فِي يَهُوذَا وَأُورُشَلِيمَ إِلَى جَمِيعِ بَنِي ٱلسَّبْيِ لِكَيْ يَجْتَمِعُوا إِلَى أُورُشَلِيمَ.","wāảṭ̊laqūạ nidāʾaⁿ fī yahūdẖā wāủwrusẖalīma ại̹lay̱ jamīʿi banī ٱlsãb̊yi likaẙ yaj̊tamiʿūạ ại̹lay̱ ạủwrusẖalīma."],[10,8,"وَكُلُّ مَنْ لَا يَأْتِي فِي ثَلَاثَةِ أَيَّامٍ حَسَبَ مَشُورَةِ ٱلرُّؤَسَاءِ وَٱلشُّيُوخِ يُحَرَّمُ كُلُّ مَالِهِ، وَهُوَ يُفْرَزُ مِنْ جَمَاعَةِ أَهْلِ ٱلسَّبْيِ.","wakulũ man̊ lā yā̊̉tī fī tẖalātẖaẗi ạảyãạmiⁿ ḥasaba masẖūraẗi ٱlrũwảsāʾi waٱlsẖũyūkẖi yuḥarãmu kulũ mālihi, wahūa yuf̊razu min̊ jamāʿaẗi ạảh̊li ٱlsãb̊yi."],[10,9,"فَٱجْتَمَعَ كُلُّ رِجَالِ يَهُوذَا وَبَنْيَامِينَ إِلَى أُورُشَلِيمَ فِي ٱلثَّلَاثَةِ ٱلْأَيَّامِ، أَيْ فِي ٱلشَّهْرِ ٱلتَّاسِعِ، فِي ٱلْعِشْرِينَ مِنَ ٱلشَّهْرِ، وَجَلَسَ جَمِيعُ ٱلشَّعْبِ فِي سَاحَةِ بَيْتِ ٱللهِ مُرْتَعِدِينَ مِنَ ٱلْأَمْرِ وَمِنَ ٱلْأَمْطَارِ.","faٱj̊tamaʿa kulũ rijāli yahūdẖā waban̊yāmīna ại̹lay̱ ạủwrusẖalīma fī ٱltẖãlātẖaẗi ٱl̊ạảyãạmi, ạảẙ fī ٱlsẖãh̊ri ٱltãạsiʿi, fī ٱl̊ʿisẖ̊rīna mina ٱlsẖãh̊ri, wajalasa jamīʿu ٱlsẖãʿ̊bi fī sāḥaẗi baẙti ٱllhi mur̊taʿidīna mina ٱl̊ạảm̊ri wamina ٱl̊ạảm̊ṭāri."],[10,10,"فَقَامَ عَزْرَا ٱلْكَاهِنُ وَقَالَ لَهُمْ: «إِنَّكُمْ قَدْ خُنْتُمْ وَٱتَّخَذْتُمْ نِسَاءً غَرِيبَةً لِتَزِيدُوا عَلَى إِثْمِ إِسْرَائِيلَ.","faqāma ʿaz̊rā ٱl̊kāhinu waqāla lahum̊: «ại̹nãkum̊ qad̊ kẖun̊tum̊ waٱtãkẖadẖ̊tum̊ nisāʾaⁿ gẖarībaẗaⁿ litazīdūạ ʿalay̱ ại̹tẖ̊mi ại̹s̊rāyỉyla."],[10,11,"فَٱعْتَرِفُوا ٱلْآنَ لِلرَّبِّ إِلَهِ آبَائِكُمْ وَٱعْمَلُوا مَرْضَاتَهُ، وَٱنْفَصِلُوا عَنْ شُعُوبِ ٱلْأَرْضِ وَعَنِ ٱلنِّسَاءِ ٱلْغَرِيبَةِ».","faٱʿ̊tarifūạ ٱl̊ậna lilrãbĩ ại̹lahi ậbāyỉkum̊ waٱʿ̊malūạ mar̊ḍātahu, waٱn̊faṣilūạ ʿan̊ sẖuʿūbi ٱl̊ạảr̊ḍi waʿani ٱlnĩsāʾi ٱl̊gẖarībaẗi»."],[10,12,"فَأَجَابَ كُلُّ ٱلْجَمَاعَةِ وَقَالُوا بِصَوْتٍ عَظِيمٍ: «كَمَا كَلَّمْتَنَا كَذَلِكَ نَعْمَلُ.","fāảjāba kulũ ٱl̊jamāʿaẗi waqālūạ biṣaẘtiⁿ ʿaẓīmiⁿ: «kamā kalãm̊tanā kadẖalika naʿ̊malu."],[10,13,"إِلَا أَنَّ ٱلشَّعْبَ كَثِيرٌ، وَٱلْوَقْتَ وَقْتُ أَمْطَارٍ، وَلَا طَاقَةَ لَنَا عَلَى ٱلْوُقُوفِ فِي ٱلْخَارِجِ، وَٱلْعَمَلُ لَيْسَ لِيَوْمٍ وَاحِدٍ أَوْ لِٱثْنَيْنِ، لِأَنَّنَا قَدْ أَكْثَرْنَا ٱلذَّنْبَ فِي هَذَا ٱلْأَمْرِ.","ại̹lā ạảnã ٱlsẖãʿ̊ba katẖīruⁿ, waٱl̊waq̊ta waq̊tu ạảm̊ṭāriⁿ, walā ṭāqaẗa lanā ʿalay̱ ٱl̊wuqūfi fī ٱl̊kẖāriji, waٱl̊ʿamalu laẙsa līaẘmiⁿ wāḥidiⁿ ạảẘ liٱtẖ̊naẙni, liạảnãnā qad̊ ạảk̊tẖar̊nā ٱldẖãn̊ba fī hadẖā ٱl̊ạảm̊ri."],[10,14,"فَلْيَقِفْ رُؤَسَاؤُنَا لِكُلِّ ٱلْجَمَاعَةِ. وَكُلُّ ٱلَّذِينَ فِي مُدُنِنَا قَدِ ٱتَّخَذُوا نِسَاءً غَرِيبَةً، فَلْيَأْتُوا فِي أَوْقَاتٍ مُعَيَّنَةٍ وَمَعَهُمْ شُيُوخُ مَدِينَةٍ فَمَدِينَةٍ وَقُضَاتُهَا، حَتَّى يَرْتَدَّ عَنَّا حُمُوُّ غَضَبِ إِلَهِنَا مِنْ أَجْلِ هَذَا ٱلْأَمْرِ».","fal̊yaqif̊ rūảsāwủnā likulĩ ٱl̊jamāʿaẗi. wakulũ ٱlãdẖīna fī muduninā qadi ٱtãkẖadẖūạ nisāʾaⁿ gẖarībaẗaⁿ, fal̊yā̊̉tūạ fī ạảẘqātiⁿ muʿayãnaẗiⁿ wamaʿahum̊ sẖuyūkẖu madīnaẗiⁿ famadīnaẗiⁿ waquḍātuhā, ḥatãy̱ yar̊tadã ʿanãạ ḥumūũ gẖaḍabi ại̹lahinā min̊ ạảj̊li hadẖā ٱl̊ạảm̊ri»."],[10,15,"وَيُونَاثَانُ بْنُ عَسَائِيلَ وَيَحْزِيَا بْنُ تِقْوَةَ فَقَطْ قَامَا عَلَى هَذَا، وَمَشُلَّامُ وَشَبْتَايُ ٱللَّاوِيُّ سَاعَدَاهُمَا.","wayūnātẖānu b̊nu ʿasāyỉyla wayaḥ̊zīā b̊nu tiq̊waẗa faqaṭ̊ qāmā ʿalay̱ hadẖā, wamasẖulãạmu wasẖab̊tāyu ٱllãạwīũ sāʿadāhumā."],[10,16,"وَفَعَلَ هَكَذَا بَنُو ٱلسَّبْيِ. وَٱنْفَصَلَ عَزْرَا ٱلْكَاهِنُ وَرِجَالٌ رُؤُوسُ آبَاءٍ، حَسَبَ بُيُوتِ آبَائِهِمْ، وَجَمِيعُهُمْ بِأَسْمَائِهِمْ، وَجَلَسُوا فِي ٱلْيَوْمِ ٱلْأَوَّلِ مِنَ ٱلشَّهْرِ ٱلْعَاشِرِ لِلْفَحْصِ عَنِ ٱلْأَمْرِ.","wafaʿala hakadẖā banū ٱlsãb̊yi. waٱn̊faṣala ʿaz̊rā ٱl̊kāhinu warijāluⁿ rūủwsu ậbāʾiⁿ, ḥasaba buyūti ậbāyỉhim̊, wajamīʿuhum̊ biạảs̊māyỉhim̊, wajalasūạ fī ٱl̊yaẘmi ٱl̊ạảwãli mina ٱlsẖãh̊ri ٱl̊ʿāsẖiri lil̊faḥ̊ṣi ʿani ٱl̊ạảm̊ri."],[10,17,"وَٱنْتَهَوْا مِنْ كُلِّ ٱلرِّجَالِ ٱلَّذِينَ ٱتَّخَذُوا نِسَاءً غَرِيبَةً فِي ٱلْيَوْمِ ٱلْأَوَّلِ مِنَ ٱلشَّهْرِ ٱلْأَوَّلِ.","waٱn̊tahaẘạ min̊ kulĩ ٱlrĩjāli ٱlãdẖīna ٱtãkẖadẖūạ nisāʾaⁿ gẖarībaẗaⁿ fī ٱl̊yaẘmi ٱl̊ạảwãli mina ٱlsẖãh̊ri ٱl̊ạảwãli."],[10,18,"فَوُجِدَ بَيْنَ بَنِي ٱلْكَهَنَةِ مَنِ ٱتَّخَذَ نِسَاءً غَرِيبَةً: فَمِنْ بَنِي يَشُوعَ بْنِ يُوصَادَاقَ وَإِخْوَتِهِ: مَعْشِيَّا وَأَلِيعَزَرُ وَيَارِيبُ وَجَدَلْيَا.","fawujida baẙna banī ٱl̊kahanaẗi mani ٱtãkẖadẖa nisāʾaⁿ gẖarībaẗaⁿ: famin̊ banī yasẖūʿa b̊ni yūṣādāqa wāi̹kẖ̊watihi: maʿ̊sẖīãạ wāảlīʿazaru wayārību wajadal̊yā."],[10,19,"وَأَعْطَوْا أَيْدِيَهُمْ لِإِخْرَاجِ نِسَائِهِمْ مُقَرِّبِينَ كَبْشَ غَنَمٍ لِأَجْلِ إِثْمِهِمْ.","wāảʿ̊ṭaẘạ ạảẙdīahum̊ liại̹kẖ̊rāji nisāyỉhim̊ muqarĩbīna kab̊sẖa gẖanamiⁿ liạảj̊li ại̹tẖ̊mihim̊."],[10,20,"وَمِنْ بَنِي إِمِّيرَ: حَنَانِي وَزَبْدِيَا.","wamin̊ banī ại̹mĩyra: ḥanānī wazab̊dīā."],[10,21,"وَمِنْ بَنِي حَارِيمَ: مَعْسِيَّا وَإِيلِيَّا وَشَمْعِيَا وَيَحِيئِيلُ وَعُزِّيَّا.","wamin̊ banī ḥārīma: maʿ̊sīãạ wāi̹ylīãạ wasẖam̊ʿīā wayaḥīyỉylu waʿuzĩyãạ."],[10,22,"وَمِنْ بَنِي فَشْحُورَ: أَلْيُوعِينَايُ وَمَعْسِيَّا وَإِسْمَاعِيلُ وَنَثَنْئِيلُ وَيُوزَابَادُ وَأَلْعَاسَةُ.","wamin̊ banī fasẖ̊ḥūra: ạảl̊yūʿīnāyu wamaʿ̊sīãạ wāi̹s̊māʿīlu wanatẖan̊yỉylu wayūzābādu wāảl̊ʿāsaẗu."],[10,23,"وَمِنَ ٱللَّاوِيِّينَ: يُوزَابَادُ وَشِمْعِي وَقَلَايَا، هُوَ قَلِيطَا، وَفَتَحْيَا وَيَهُوذَا وَأَلِيعَزَرُ.","wamina ٱllãạwīĩyna: yūzābādu wasẖim̊ʿī waqalāyā, hūa qalīṭā, wafataḥ̊yā wayahūdẖā wāảlīʿazaru."],[10,24,"وَمِنَ ٱلْمُغَنِّينَ: أَلْيَاشِيبُ. وَمِنَ ٱلْبَوَّابِينَ: شَلُّومُ وَطَالَمُ وَأُورِي.","wamina ٱl̊mugẖanĩyna: ạảl̊yāsẖību. wamina ٱl̊bawãạbīna: sẖalũwmu waṭālamu wāủwrī."],[10,25,"وَمِنْ إِسْرَائِيلَ مِنْ بَنِي فَرْعُوشَ: رَمْيَا وَيِزِّيَّا وَمَلْكِيَّا وَمِيَّامِينُ وَأَلْعَازَارُ وَمَلْكِيَّا وَبَنَايَا.","wamin̊ ại̹s̊rāyỉyla min̊ banī far̊ʿūsẖa: ram̊yā wayizĩyãạ wamal̊kīãạ wamīãạmīnu wāảl̊ʿāzāru wamal̊kīãạ wabanāyā."],[10,26,"وَمِنْ بَنِي عِيلَامَ: مَتَّنْيَا وَزَكَرِيَّا وَيَحِيئِيلُ وَعَبْدِي وَيَرِيمُوثُ وَإِيلِيَّا.","wamin̊ banī ʿīlāma: matãn̊yā wazakarīãạ wayaḥīyỉylu waʿab̊dī wayarīmūtẖu wāi̹ylīãạ."],[10,27,"وَمِنْ بَنِي زَتُّو: أَلْيُوعِينَايُ وَأَلْيَاشِيبُ وَمَتَّنْيَا وَيَرِيمُوثُ وَزَابَادُ وَعَزِيزَا.","wamin̊ banī zatũw: ạảl̊yūʿīnāyu wāảl̊yāsẖību wamatãn̊yā wayarīmūtẖu wazābādu waʿazīzā."],[10,28,"وَمِنْ بَنِي بَابَايَ: يَهُوحَانَانُ وَحَنَنْيَا وَزَبَايُ وَعَثْلَايُ.","wamin̊ banī bābāya: yahūḥānānu waḥanan̊yā wazabāyu waʿatẖ̊lāyu."],[10,29,"وَمِنْ بَنِي بَانِي: مَشُلَّامُ وَمَلُّوخُ وَعَدَايَا وَيَاشُوبُ وَشَآلُ وَرَامُوثُ.","wamin̊ banī bānī: masẖulãạmu wamalũwkẖu waʿadāyā wayāsẖūbu wasẖā̂lu warāmūtẖu."],[10,30,"وَمِنْ بَنِي فَحَثَ مُوآبَ: عَدْنَا وَكَلَالُ وَبَنَايَا وَمَعْسِيَّا وَمَتَّنْيَا وَبَصَلْئِيلُ وَبَنُّويُ وَمَنَسَّى.","wamin̊ banī faḥatẖa mūậba: ʿad̊nā wakalālu wabanāyā wamaʿ̊sīãạ wamatãn̊yā wabaṣal̊yỉylu wabanũwyu wamanasãy̱."],[10,31,"وَبَنُو حَارِيمَ: أَلِيعَزَرُ وَيِشِّيَّا وَمَلْكِيَّا وَشِمْعِيَا وَشِمْعُونُ","wabanū ḥārīma: ạảlīʿazaru wayisẖĩyãạ wamal̊kīãạ wasẖim̊ʿīā wasẖim̊ʿūnu"],[10,32,"وَبَنْيَامِينُ وَمَلُّوخُ وَشَمَرْيَا.","waban̊yāmīnu wamalũwkẖu wasẖamar̊yā."],[10,33,"مِنْ بَنِي حَشُومَ: مَتَّنَايُ ومَتَّاثَا وزَابَادُ وَأَلِيفَلَطُ ويَرِيمَايُ وَمَنَسَّى وَشِمْعِي.","min̊ banī ḥasẖūma: matãnāyu wmatãạtẖā wzābādu wāảlīfalaṭu wyarīmāyu wamanasãy̱ wasẖim̊ʿī."],[10,34,"مِنْ بَنِي بَانِي: مَعَدَايُ وَعَمْرَامُ وَأُوئِيلُ","min̊ banī bānī: maʿadāyu waʿam̊rāmu wāủwyỉylu"],[10,35,"وَبَنَايَا وَبِيدْيَا وكَلُوهِي","wabanāyā wabīd̊yā wkalūhī"],[10,36,"وَوَنْيَا وَمَرِيمُوثُ وَأَلْيَاشِيبُ","wawan̊yā wamarīmūtẖu wāảl̊yāsẖību"],[10,37,"وَمَتَّنْيَا وَمَتَّنَايُ وَيَعْسُو","wamatãn̊yā wamatãnāyu wayaʿ̊sū"],[10,38,"وَبَانِي وَبِنُّويُ وَشِمْعِي","wabānī wabinũwyu wasẖim̊ʿī"],[10,39,"وَشَلَمْيَا وَنَاثَانُ وَعَدَايَا","wasẖalam̊yā wanātẖānu waʿadāyā"],[10,40,"وَمَكْنَدْبَايُ وَشَاشَايُ وَشَارَايُ","wamak̊nad̊bāyu wasẖāsẖāyu wasẖārāyu"],[10,41,"وَعَزَرْئِيلُ وَشَلْمِيَا وَشَمَرْيَا","waʿazar̊yỉylu wasẖal̊mīā wasẖamar̊yā"],[10,42,"وَشَلُّومُ وَأَمَرْيَا وَيُوسُفُ.","wasẖalũwmu wāảmar̊yā wayūsufu."],[10,43,"مِنْ بَنِي نَبُو: يَعِيئِيلُ وَمَتَّثْيَا وَزَابَادُ وَزَبِينَا وَيَدُّو وَيُوئِيلُ وَبَنَايَا.","min̊ banī nabū: yaʿīyỉylu wamatãtẖ̊yā wazābādu wazabīnā wayadũw wayūyỉylu wabanāyā."],[10,44,"كُلُّ هَؤُلَاءِ ٱتَّخَذُوا نِسَاءً غَرِيبَةً وَمِنْهُنَّ نِسَاءٌ قَدْ وَضَعْنَ بَنِينَ.","kulũ hawủlāʾi ٱtãkẖadẖūạ nisāʾaⁿ gẖarībaẗaⁿ wamin̊hunã nisāʾuⁿ qad̊ waḍaʿ̊na banīna."]],"bis-obbr":[[1,1,"Bifo, Hae God i bin givim tok blong hem long Profet Jeremaea blong i talemaot, mo long taem we King Sirus, man Pesia i rul long Babilonia, long fas yia blong hem, Hae God i mekem tok ya blong hem i kamtru. Hem i mekem we king ya i mekem wan tok, mo i raetemdaon, nao i givim long ol man blong hem blong oli go ridimaot long olgeta man long evri ples we hem i stap rul long hem. Long tok blong hem,","Bifo, Hae God i bin givim tok blong hem long Profet Jeremaea blong i talemaot, mo long taem we King Sirus, man Pesia i rul long Babilonia, long fas yia blong hem, Hae God i mekem tok ya blong hem i kamtru. Hem i mekem we king ya i mekem wan tok, mo i raetemdaon, nao i givim long ol man blong hem blong oli go ridimaot long olgeta man long evri ples we hem i stap rul long hem. Long tok blong hem,"],[1,2,"hem i talem se, “Mi King Sirus blong Pesia, mo tok blong mi i olsem. Hae God, hem i God blong heven, mo hem i putumap mi mi king long olgeta ples long wol ya. Bifo, haos* blong hem i stap long Juda,* long taon ya Jerusalem,* mo naoia wok blong wokem haos ya bakegen, hem i putum long han blong mi.","hem i talem se, “Mi King Sirus blong Pesia, mo tok blong mi i olsem. Hae God, hem i God blong heven, mo hem i putumap mi mi king long olgeta ples long wol ya. Bifo, haos* blong hem i stap long Juda,* long taon ya Jerusalem,* mo naoia wok blong wokem haos ya bakegen, hem i putum long han blong mi."],[1,3,"Hem i God blong yufala ol laen* blong Isrel,* mo yufala i man blong hem. Prea blong mi we hem bambae i stap wetem yufala evriwan. Jerusalem i ples blong mekem wosip long hem, mo naoia yufala i mas gobak long taon ya, yufala i mas stanemap haos ya blong hem bakegen long ples ya.","Hem i God blong yufala ol laen* blong Isrel,* mo yufala i man blong hem. Prea blong mi we hem bambae i stap wetem yufala evriwan. Jerusalem i ples blong mekem wosip long hem, mo naoia yufala i mas gobak long taon ya, yufala i mas stanemap haos ya blong hem bakegen long ples ya."],[1,4,"Mo yufala ol narafala man we i stap raonabaot long ol laen bong Isrel ya we oli stap wok slef* long ples ya, sipos sam long olgeta oli trabol blong gobak long ples blong olgeta, bambae yufala i mas givhan long olgeta. Bambae yufala i mas givim silva mo gol long olgeta, mo ol samting we oli nidim long rod, mo ol anamol blong karem ol samting ya. Mo bambae yufala i mas givim ol presen long olgeta tu blong oli givim i go long Hae God long haos blong hem long Jerusalem.”","Mo yufala ol narafala man we i stap raonabaot long ol laen bong Isrel ya we oli stap wok slef* long ples ya, sipos sam long olgeta oli trabol blong gobak long ples blong olgeta, bambae yufala i mas givhan long olgeta. Bambae yufala i mas givim silva mo gol long olgeta, mo ol samting we oli nidim long rod, mo ol anamol blong karem ol samting ya. Mo bambae yufala i mas givim ol presen long olgeta tu blong oli givim i go long Hae God long haos blong hem long Jerusalem.”"],[1,5,"Nao long taem ya, Hae God i wok long tingting blong plante man blong oli kambak. Long olgeta ya, i gat ol lida blong laen blong Juda, mo ol lida blong laen blong Benjamin,* mo ol pris* mo ol Livaet* mo sam narafala man tu. Nao olgeta ya evriwan oli stap mekemrere blong kam wokem haos blong hem bakegen long Jerusalem.","Nao long taem ya, Hae God i wok long tingting blong plante man blong oli kambak. Long olgeta ya, i gat ol lida blong laen blong Juda, mo ol lida blong laen blong Benjamin,* mo ol pris* mo ol Livaet* mo sam narafala man tu. Nao olgeta ya evriwan oli stap mekemrere blong kam wokem haos blong hem bakegen long Jerusalem."],[1,6,"Mo ol man we oli stap raonabaot long olgeta oli givhan long olgeta, oli givim plante samting long olgeta. Oli givim ol samting we oli wokem long silva mo long gol, mo ol samting we bambae oli nidim long rod, mo ol narafala gudgudfala samting, mo ol presen we bambae oli kam givim long Hae God, long haos blong hem. Mo oli givim ol anamol tu long olgeta, blong karem ol samting ya i kam.","Mo ol man we oli stap raonabaot long olgeta oli givhan long olgeta, oli givim plante samting long olgeta. Oli givim ol samting we oli wokem long silva mo long gol, mo ol samting we bambae oli nidim long rod, mo ol narafala gudgudfala samting, mo ol presen we bambae oli kam givim long Hae God, long haos blong hem. Mo oli givim ol anamol tu long olgeta, blong karem ol samting ya i kam."],[1,7,"Mo ol besin mo ol kap we King Nebukadnesa i bin tekemaot long haos blong Hae God long Jerusalem, i karem i go long Babilon, i putum long haos blong ol god blong hem, King Sirus i tekemaot ol samting ya bakegen blong givim i gobak long olgeta.","Mo ol besin mo ol kap we King Nebukadnesa i bin tekemaot long haos blong Hae God long Jerusalem, i karem i go long Babilon, i putum long haos blong ol god blong hem, King Sirus i tekemaot ol samting ya bakegen blong givim i gobak long olgeta."],[1,8,"Hem i putum ol samting ya long han blong Mitredat, man blong lukaot long mane blong hem, mo Mitredat i kaontem ol samting ya long fes blong Sesbajara, nao i givim olgeta i go long hem. Sesbajara ya, hem i wan lida blong ol man Juda, we biaen i kam distrikejen* blong distrik ya Juda.","Hem i putum ol samting ya long han blong Mitredat, man blong lukaot long mane blong hem, mo Mitredat i kaontem ol samting ya long fes blong Sesbajara, nao i givim olgeta i go long hem. Sesbajara ya, hem i wan lida blong ol man Juda, we biaen i kam distrikejen* blong distrik ya Juda."],[1,9,"Olgeta samting ya, i gat toti gol besin, mo wan taosen silva besin, mo twanti naen narafala besin,","Olgeta samting ya, i gat toti gol besin, mo wan taosen silva besin, mo twanti naen narafala besin,"],[1,10,"mo toti smol gol besin, mo fo handred ten smol silva besin, mo wan taosen narafala samting blong yusum long haos blong Hae God.","mo toti smol gol besin, mo fo handred ten smol silva besin, mo wan taosen narafala samting blong yusum long haos blong Hae God."],[1,11,"Namba blong ol samting ya, olgeta evriwan i kasem faef taosen fo handred. Nao taem Sesbajara wetem ol narafala laen blong Isrel ya oli aot long Babilon, oli kambak long Jerusalem, hem i karem ol samting ya i kam.","Namba blong ol samting ya, olgeta evriwan i kasem faef taosen fo handred. Nao taem Sesbajara wetem ol narafala laen blong Isrel ya oli aot long Babilon, oli kambak long Jerusalem, hem i karem ol samting ya i kam."],[2,1,"Nao long taem ya, i gat plante man we oli stap wok slef* long Babilonia oli aot, oli kambak long Juda,* nao oli kam stap long Jerusalem,* mo long ol narafala ples long Juda. Olgeta ya oli kambak, oli go stap long ol stret vilej blong olgeta bakegen. Olgeta oli bin go stap long Babilonia, i stat long taem ya we King Nebukadnesa bifo i holem ol olfala blong olgeta, i tekem olgeta oli go stap wok slef long ples ya.","Nao long taem ya, i gat plante man we oli stap wok slef* long Babilonia oli aot, oli kambak long Juda,* nao oli kam stap long Jerusalem,* mo long ol narafala ples long Juda. Olgeta ya oli kambak, oli go stap long ol stret vilej blong olgeta bakegen. Olgeta oli bin go stap long Babilonia, i stat long taem ya we King Nebukadnesa bifo i holem ol olfala blong olgeta, i tekem olgeta oli go stap wok slef long ples ya."],[2,2,"Ol man we oli lidim olgeta ya oli kambak, nem blong olgeta i olsem. I gat Serubabel, mo Josua we i hae pris,* mo Nehemaea, mo Seraea, mo Rehelaea, mo Modekae, mo Bilsan, mo Mispara, mo Bigvae, mo Rehum, mo Bahanaha. Mo ol laen* blong Isrel,* we oli aot long Babilonia oli kambak, lis blong olgeta wetem namba blong olgeta i olsem.","Ol man we oli lidim olgeta ya oli kambak, nem blong olgeta i olsem. I gat Serubabel, mo Josua we i hae pris,* mo Nehemaea, mo Seraea, mo Rehelaea, mo Modekae, mo Bilsan, mo Mispara, mo Bigvae, mo Rehum, mo Bahanaha. Mo ol laen* blong Isrel,* we oli aot long Babilonia oli kambak, lis blong olgeta wetem namba blong olgeta i olsem."],[2,3,"Ol laen blong Paros, i gat tu taosen wan handred seventi tu.","Ol laen blong Paros, i gat tu taosen wan handred seventi tu."],[2,4,"Mo ol laen blong Sefatia, i gat tri handred seventi tu.","Mo ol laen blong Sefatia, i gat tri handred seventi tu."],[2,5,"Mo ol laen blong Araha, i gat seven handred seventi faef.","Mo ol laen blong Araha, i gat seven handred seventi faef."],[2,6,"Mo ol laen blong Jesua wetem ol laen blong Joab, we tufala ya i kamaot biaen long Pahatmoab, i gat tu taosen eit handred twelef.","Mo ol laen blong Jesua wetem ol laen blong Joab, we tufala ya i kamaot biaen long Pahatmoab, i gat tu taosen eit handred twelef."],[2,7,"Mo ol laen blong Elam, i gat wan taosen tu handred fifti fo.","Mo ol laen blong Elam, i gat wan taosen tu handred fifti fo."],[2,8,"Mo ol laen blong Satu, i gat naen handred foti faef.","Mo ol laen blong Satu, i gat naen handred foti faef."],[2,9,"Mo ol laen blong Sakae, i gat seven handred sikisti.","Mo ol laen blong Sakae, i gat seven handred sikisti."],[2,10,"Mo ol laen blong Bani, i gat sikis handred foti tu.","Mo ol laen blong Bani, i gat sikis handred foti tu."],[2,11,"Mo ol laen blong Bebae, i gat sikis handred twanti tri.","Mo ol laen blong Bebae, i gat sikis handred twanti tri."],[2,12,"Mo ol laen blong Asgad, i gat wan taosen tu handred twanti tu.","Mo ol laen blong Asgad, i gat wan taosen tu handred twanti tu."],[2,13,"Mo ol laen blong Adonikam, i gat sikis handred sikisti sikis.","Mo ol laen blong Adonikam, i gat sikis handred sikisti sikis."],[2,14,"Mo ol laen blong Bigvae, i gat tu taosen fifti sikis.","Mo ol laen blong Bigvae, i gat tu taosen fifti sikis."],[2,15,"Mo ol laen blong Adin, i gat fo handred fifti fo.","Mo ol laen blong Adin, i gat fo handred fifti fo."],[2,16,"Mo ol laen blong Atere, we narafala nem blong hem Hesekia, i gat naenti eit.","Mo ol laen blong Atere, we narafala nem blong hem Hesekia, i gat naenti eit."],[2,17,"Mo ol laen blong Bejae, i gat tri handred twanti tri.","Mo ol laen blong Bejae, i gat tri handred twanti tri."],[2,18,"Mo ol laen blong Jora, i gat wan handred twelef.","Mo ol laen blong Jora, i gat wan handred twelef."],[2,19,"Mo ol laen blong Hasum, i gat tu handred twanti tri.","Mo ol laen blong Hasum, i gat tu handred twanti tri."],[2,20,"Mo ol laen blong Gibara, i gat naenti faef.","Mo ol laen blong Gibara, i gat naenti faef."],[2,21,"Mo i gat ol narafala tu oli kambak, we oli stap makem olgeta long vilej we ol olfala blong olgeta bifo oli stap long hem. Namba blong olgeta ya i olsem. Ol man Betlehem, i gat wan handred twanti tri.","Mo i gat ol narafala tu oli kambak, we oli stap makem olgeta long vilej we ol olfala blong olgeta bifo oli stap long hem. Namba blong olgeta ya i olsem. Ol man Betlehem, i gat wan handred twanti tri."],[2,22,"Mo ol man Netofa, i gat fifti sikis.","Mo ol man Netofa, i gat fifti sikis."],[2,23,"Mo ol man Anatot, i gat wan handred twanti eit.","Mo ol man Anatot, i gat wan handred twanti eit."],[2,24,"Mo ol man Asmavet, i gat foti tu.","Mo ol man Asmavet, i gat foti tu."],[2,25,"Mo ol man Kiriatsearim, mo ol man Kefira, mo ol man Beherot, i gat seven handred foti tri.","Mo ol man Kiriatsearim, mo ol man Kefira, mo ol man Beherot, i gat seven handred foti tri."],[2,26,"Mo ol man Rama mo ol man Geba, i gat sikis handred twanti wan.","Mo ol man Rama mo ol man Geba, i gat sikis handred twanti wan."],[2,27,"Mo ol man Mikmas, i gat wan handred twanti tu.","Mo ol man Mikmas, i gat wan handred twanti tu."],[2,28,"Mo ol man Betel mo ol man Eae, i gat tu handred twanti tri.","Mo ol man Betel mo ol man Eae, i gat tu handred twanti tri."],[2,29,"Mo ol man Neboho, i gat fifti tu.","Mo ol man Neboho, i gat fifti tu."],[2,30,"Mo ol man Magbis, i gat wan handred fifti sikis.","Mo ol man Magbis, i gat wan handred fifti sikis."],[2,31,"Mo ol man blong narafala Elam, i gat wan taosen tu handred fifti fo.","Mo ol man blong narafala Elam, i gat wan taosen tu handred fifti fo."],[2,32,"Mo ol man Harim, i gat tri handred twanti.","Mo ol man Harim, i gat tri handred twanti."],[2,33,"Mo ol man Lod, mo ol man Hadid, mo ol man Ono, i gat seven handred twanti faef.","Mo ol man Lod, mo ol man Hadid, mo ol man Ono, i gat seven handred twanti faef."],[2,34,"Mo ol man Jeriko, i gat tri handred foti faef.","Mo ol man Jeriko, i gat tri handred foti faef."],[2,35,"Mo ol man Senaha, i gat tri taosen sikis handred toti.","Mo ol man Senaha, i gat tri taosen sikis handred toti."],[2,36,"Mo ol pris* we oli aot long Babilonia oli kambak, lis blong olgeta wetem namba blong olgeta i olsem. Ol laen blong Jedaea we i kamaot biaen long Jesua, i gat naen handred seventi tri.","Mo ol pris* we oli aot long Babilonia oli kambak, lis blong olgeta wetem namba blong olgeta i olsem. Ol laen blong Jedaea we i kamaot biaen long Jesua, i gat naen handred seventi tri."],[2,37,"Mo ol laen blong Hime, i gat wan taosen fifti tu.","Mo ol laen blong Hime, i gat wan taosen fifti tu."],[2,38,"Mo ol laen blong Pasuru, i gat wan taosen tu handred foti seven.","Mo ol laen blong Pasuru, i gat wan taosen tu handred foti seven."],[2,39,"Mo ol laen blong Harim, i gat wan taosen seventin.","Mo ol laen blong Harim, i gat wan taosen seventin."],[2,40,"Mo ol Livaet* we oli aot long Babilonia oli kambak, lis blong olgeta wetem namba blong olgeta i olsem. Ol laen blong Jesua, mo ol laen blong Kadmiel, we tufala ya i kamaot biaen long Hodavia, i gat seventi fo.","Mo ol Livaet* we oli aot long Babilonia oli kambak, lis blong olgeta wetem namba blong olgeta i olsem. Ol laen blong Jesua, mo ol laen blong Kadmiel, we tufala ya i kamaot biaen long Hodavia, i gat seventi fo."],[2,41,"Mo i gat ol man blong mekem kwaea long haos* blong Hae God. Olgeta ya oli laen blong Asaf, mo namba blong olgeta, i gat wan handred twanti eit.","Mo i gat ol man blong mekem kwaea long haos* blong Hae God. Olgeta ya oli laen blong Asaf, mo namba blong olgeta, i gat wan handred twanti eit."],[2,42,"Mo i gat ol man blong gad long haos blong Hae God. Olgeta ya oli laen blong Salum, mo laen blong Atere, mo laen blong Talmon, mo laen blong Akub, mo laen blong Hatita, mo laen blong Sobae, mo olgeta evriwan, i gat wan handred toti naen.","Mo i gat ol man blong gad long haos blong Hae God. Olgeta ya oli laen blong Salum, mo laen blong Atere, mo laen blong Talmon, mo laen blong Akub, mo laen blong Hatita, mo laen blong Sobae, mo olgeta evriwan, i gat wan handred toti naen."],[2,43,"Mo olgeta we oli kamaot biaen long ol man blong wok long haos blong Hae God bifo, we oli aot long Babilonia oli kambak, lis blong olgeta i olsem. I gat ol laen blong Jiha, mo ol laen blong Hasufa, mo ol laen blong Tabaot,","Mo olgeta we oli kamaot biaen long ol man blong wok long haos blong Hae God bifo, we oli aot long Babilonia oli kambak, lis blong olgeta i olsem. I gat ol laen blong Jiha, mo ol laen blong Hasufa, mo ol laen blong Tabaot,"],[2,44,"mo ol laen blong Keros, mo ol laen blong Siaha, mo ol laen blong Padon,","mo ol laen blong Keros, mo ol laen blong Siaha, mo ol laen blong Padon,"],[2,45,"mo ol laen blong Lebana, mo ol laen blong Hagaba, mo ol laen blong Akub,","mo ol laen blong Lebana, mo ol laen blong Hagaba, mo ol laen blong Akub,"],[2,46,"mo ol laen blong Hagab, mo ol laen blong Samlae, mo ol laen blong Hanan,","mo ol laen blong Hagab, mo ol laen blong Samlae, mo ol laen blong Hanan,"],[2,47,"mo ol laen blong Gidel, mo ol laen blong Gaha, mo ol laen blong Rehaea,","mo ol laen blong Gidel, mo ol laen blong Gaha, mo ol laen blong Rehaea,"],[2,48,"mo ol laen blong Resin, mo ol laen blong Nekoda, mo ol laen blong Gasam,","mo ol laen blong Resin, mo ol laen blong Nekoda, mo ol laen blong Gasam,"],[2,49,"mo ol laen blong Usaha, mo ol laen blong Pasea, mo ol laen blong Besae,","mo ol laen blong Usaha, mo ol laen blong Pasea, mo ol laen blong Besae,"],[2,50,"mo ol laen blong Asna, mo ol laen blong Mehunim, mo ol laen blong Nefisim,","mo ol laen blong Asna, mo ol laen blong Mehunim, mo ol laen blong Nefisim,"],[2,51,"mo ol laen blong Bakbuk, mo ol laen blong Hakufa, mo ol laen blong Hahuru,","mo ol laen blong Bakbuk, mo ol laen blong Hakufa, mo ol laen blong Hahuru,"],[2,52,"mo ol laen blong Baslut, mo ol laen blong Mehida, mo ol laen blong Hasa,","mo ol laen blong Baslut, mo ol laen blong Mehida, mo ol laen blong Hasa,"],[2,53,"mo ol laen blong Bakos, mo ol laen blong Siseraha, mo ol laen blong Tema,","mo ol laen blong Bakos, mo ol laen blong Siseraha, mo ol laen blong Tema,"],[2,54,"mo ol laen blong Nejia, mo ol laen blong Hatifa.","mo ol laen blong Nejia, mo ol laen blong Hatifa."],[2,55,"Mo ol laen blong ol man blong wok blong King Solomon bifo, we oli aot long Babilonia oli kambak, lis blong olgeta i olsem. I gat ol laen blong Sotae, mo ol laen blong Hasoferet, mo ol laen blong Peruda","Mo ol laen blong ol man blong wok blong King Solomon bifo, we oli aot long Babilonia oli kambak, lis blong olgeta i olsem. I gat ol laen blong Sotae, mo ol laen blong Hasoferet, mo ol laen blong Peruda"],[2,56,"mo ol laen blong Jahala, mo ol laen blong Dakon, mo ol laen blong Gidel,","mo ol laen blong Jahala, mo ol laen blong Dakon, mo ol laen blong Gidel,"],[2,57,"mo ol laen blong Sefatia, mo ol laen blong Hatil, mo ol laen blong Pokeret Hajebaem, mo ol laen blong Ami.","mo ol laen blong Sefatia, mo ol laen blong Hatil, mo ol laen blong Pokeret Hajebaem, mo ol laen blong Ami."],[2,58,"Olgeta laen blong ol man blong wok long haos blong Hae God bifo wetem ol laen blong ol man blong wok blong King Solomon bifo, namba blong olgeta ya evriwan i kasem tri handred naenti tu.","Olgeta laen blong ol man blong wok long haos blong Hae God bifo wetem ol laen blong ol man blong wok blong King Solomon bifo, namba blong olgeta ya evriwan i kasem tri handred naenti tu."],[2,59,"Mo i gat ol narafala laen blong Isrel oli aot long Babilonia oli kambak, we oli no savegud stret stamba blong laen blong olgeta. Sam long olgeta ya oli laen blong Delaea, mo sam oli laen blong Tobia, mo sam oli laen blong Nekoda. Mo taem oli stap long Babilonia, oli stap long ol vilej we nem blong olgeta, Telmela, mo Telasaha, mo Kerub, mo Adan, mo Hime. Namba blong olgeta ya evriwan, i gat sikis handred fifti tu. Mo i gat ol pris* tu we oli aot long Babilonia oli kambak, we oli no savegud stret stamba blong laen blong olgeta. Sam long olgeta ya oli laen blong Habaea, mo sam oli laen blong Hakoj, mo sam oli laen blong Basilae.","Mo i gat ol narafala laen blong Isrel oli aot long Babilonia oli kambak, we oli no savegud stret stamba blong laen blong olgeta. Sam long olgeta ya oli laen blong Delaea, mo sam oli laen blong Tobia, mo sam oli laen blong Nekoda. Mo taem oli stap long Babilonia, oli stap long ol vilej we nem blong olgeta, Telmela, mo Telasaha, mo Kerub, mo Adan, mo Hime. Namba blong olgeta ya evriwan, i gat sikis handred fifti tu. Mo i gat ol pris* tu we oli aot long Babilonia oli kambak, we oli no savegud stret stamba blong laen blong olgeta. Sam long olgeta ya oli laen blong Habaea, mo sam oli laen blong Hakoj, mo sam oli laen blong Basilae.",60],[2,61,"Nao taem ol pris ya oli traem lukaot nem blong trifala bubu ya blong olgeta long lis blong ol pris, long buk ya we nem blong ol pris bifo i stap long hem, be oli no save faenem nem blong trifala. Nao long taem ya, distrikejen ya blong king we i stap lukaot long ol man Juda, hem i wan laen blong yumi, mo hem i putumaot olgeta olsem we oli no klin long fes blong Hae God, nao oli no moa save mekem wok blong pris. Mo hem i talem long olgeta, se bambae oli no moa save kakae ol kakae ya we ol man oli stap givim i go long Hae God blong mekem wosip long hem. Bambae oli mas stap olsem gogo kasem we i gat wan pris we i save yusum tufala samting ya Yurim* mo Tumim* blong faenemaot tingting blong Hae God long olgeta. Man ya Basilae, hem i wan man Gilead we dota blong hem i mared long wan pris, nao olgeta we oli kamaot biaen blong pris ya, oli stap makem olgeta se laen blong Basilae.","Nao taem ol pris ya oli traem lukaot nem blong trifala bubu ya blong olgeta long lis blong ol pris, long buk ya we nem blong ol pris bifo i stap long hem, be oli no save faenem nem blong trifala. Nao long taem ya, distrikejen ya blong king we i stap lukaot long ol man Juda, hem i wan laen blong yumi, mo hem i putumaot olgeta olsem we oli no klin long fes blong Hae God, nao oli no moa save mekem wok blong pris. Mo hem i talem long olgeta, se bambae oli no moa save kakae ol kakae ya we ol man oli stap givim i go long Hae God blong mekem wosip long hem. Bambae oli mas stap olsem gogo kasem we i gat wan pris we i save yusum tufala samting ya Yurim* mo Tumim* blong faenemaot tingting blong Hae God long olgeta. Man ya Basilae, hem i wan man Gilead we dota blong hem i mared long wan pris, nao olgeta we oli kamaot biaen blong pris ya, oli stap makem olgeta se laen blong Basilae.",63],[2,64,"Olgeta we oli aot long Babilonia, oli kambak long ples blong olgeta, namba blong olgeta evriwan i kasem foti tu taosen tri handred sikisti.","Olgeta we oli aot long Babilonia, oli kambak long ples blong olgeta, namba blong olgeta evriwan i kasem foti tu taosen tri handred sikisti."],[2,65,"Be oli no kaontem ol man blong wok blong olgeta, mo ol man blong mekem kwaea. Ol man blong wok blong olgeta, ol man wetem ol woman, namba blong olgeta evriwan i kasem seven taosen tri handred toti seven. Mo ol man blong mekem kwaea, ol man wetem ol woman, namba blong olgeta evriwan i kasem tu handred.","Be oli no kaontem ol man blong wok blong olgeta, mo ol man blong mekem kwaea. Ol man blong wok blong olgeta, ol man wetem ol woman, namba blong olgeta evriwan i kasem seven taosen tri handred toti seven. Mo ol man blong mekem kwaea, ol man wetem ol woman, namba blong olgeta evriwan i kasem tu handred."],[2,66,"Mo ol anamol blong olgeta, namba blong olgeta i olsem. I gat seven handred toti sikis hos, mo tu handred foti faef hafkas* dongki,","Mo ol anamol blong olgeta, namba blong olgeta i olsem. I gat seven handred toti sikis hos, mo tu handred foti faef hafkas* dongki,"],[2,67,"mo fo handred toti faef kamel, mo sikis taosen seven handred twanti dongki.","mo fo handred toti faef kamel, mo sikis taosen seven handred twanti dongki."],[2,68,"Nao taem olgeta ya oli kamtru long Jerusalem, oli kam kasem ples ya we haos blong Hae God i stap long hem bifo, nao sam long ol hed blong ol laen blong olgeta oli tekem ol presen blong olgeta, oli givim nomo long gladhat blong olgeta, blong givhan long wok blong wokem haos ya bakegen, stret long ples ya we olfala haos ya i stap long hem bifo.","Nao taem olgeta ya oli kamtru long Jerusalem, oli kam kasem ples ya we haos blong Hae God i stap long hem bifo, nao sam long ol hed blong ol laen blong olgeta oli tekem ol presen blong olgeta, oli givim nomo long gladhat blong olgeta, blong givhan long wok blong wokem haos ya bakegen, stret long ples ya we olfala haos ya i stap long hem bifo."],[2,69,"Olgeta oli givim plante samting olsem we oli save givim, nao namba blong olgeta samting ya we oli givim i olsem. I gat faef handred kilo gol, mo tu tan eit handred kilo silva, mo wan handred klos blong ol pris.","Olgeta oli givim plante samting olsem we oli save givim, nao namba blong olgeta samting ya we oli givim i olsem. I gat faef handred kilo gol, mo tu tan eit handred kilo silva, mo wan handred klos blong ol pris."],[2,70,"Nao ol pris wetem ol Livaet, mo sam long ol narafala man ya we oli kambak, oli mekem ples blong olgeta long Jerusalem, mo long ol vilej raonabaot long taon ya. Mo ol man blong mekem kwaea wetem ol man blong wok long haos blong Hae God, mo ol gad blong haos ya oli go stap long ol taon klosap long Jerusalem. Mo ol narafala man ya we oli kambak oli go stap long ol vilej blong ol bubu blong olgeta bifo.","Nao ol pris wetem ol Livaet, mo sam long ol narafala man ya we oli kambak, oli mekem ples blong olgeta long Jerusalem, mo long ol vilej raonabaot long taon ya. Mo ol man blong mekem kwaea wetem ol man blong wok long haos blong Hae God, mo ol gad blong haos ya oli go stap long ol taon klosap long Jerusalem. Mo ol narafala man ya we oli kambak oli go stap long ol vilej blong ol bubu blong olgeta bifo."],[3,1,"Nao ol laen* blong Isrel* oli kam stap gud long ol ples blong olgeta, mo long namba seven manis blong yia ya, olgeta evriwan oli kam wanples long Jerusalem.*","Nao ol laen* blong Isrel* oli kam stap gud long ol ples blong olgeta, mo long namba seven manis blong yia ya, olgeta evriwan oli kam wanples long Jerusalem.*"],[3,2,"Nao ya Josua we papa blong hem Jehosadak, wetem ol narafala pris, mo Serubabel we papa blong hem Sealtiel, wetem ol narafala famle blong hem, olgeta oli wokem Olta ya blong God blong yumi i gud bakegen. Oli wokem Olta ya blong oli save bonem ol sakrefaes long hem, stret olsem we oli raetem i stap long buk blong Loa* blong Moses, man ya blong God. Hae Pris*","Nao ya Josua we papa blong hem Jehosadak, wetem ol narafala pris, mo Serubabel we papa blong hem Sealtiel, wetem ol narafala famle blong hem, olgeta oli wokem Olta ya blong God blong yumi i gud bakegen. Oli wokem Olta ya blong oli save bonem ol sakrefaes long hem, stret olsem we oli raetem i stap long buk blong Loa* blong Moses, man ya blong God. Hae Pris*"],[3,3,"Nating we olgeta oli fraet long ol man we oli stap long ples ya, be oli girap, oli wokem Olta ya stret long ples we olfala Olta i bin stap long hem bifo. Mo evri dei, long moning mo long sapa, oli gohed, oli stap bonem ol sakrefaes long hem, olsem we Loa ya i talem.","Nating we olgeta oli fraet long ol man we oli stap long ples ya, be oli girap, oli wokem Olta ya stret long ples we olfala Olta i bin stap long hem bifo. Mo evri dei, long moning mo long sapa, oli gohed, oli stap bonem ol sakrefaes long hem, olsem we Loa ya i talem."],[3,4,"Nao olgeta oli mekem Lafet* blong Wokem ol Wansaed* Haos, mo evri dei, oli stap mekem ol sakrefaes stret olsem we Loa ya i talem.","Nao olgeta oli mekem Lafet* blong Wokem ol Wansaed* Haos, mo evri dei, oli stap mekem ol sakrefaes stret olsem we Loa ya i talem."],[3,5,"Mo biaen, evri dei, oli stap mekem ol sakrefaes long moning mo long sapa blong mekem wosip long Hae God. Mo oli stap mekem sakrefaes long ol Lafet blong Niumun,* mo long ol narafala dei we oli stap kam wanples blong mekem wosip long Hae God. Mo bakegen, olgeta oli stap givim ol presen i go long Hae God long gladhat blong olgeta.","Mo biaen, evri dei, oli stap mekem ol sakrefaes long moning mo long sapa blong mekem wosip long Hae God. Mo oli stap mekem sakrefaes long ol Lafet blong Niumun,* mo long ol narafala dei we oli stap kam wanples blong mekem wosip long Hae God. Mo bakegen, olgeta oli stap givim ol presen i go long Hae God long gladhat blong olgeta."],[3,6,"Nating we olgeta oli no stat yet blong wokem haos* ya blong Hae God, be long namba seven manis ya, long fas dei blong hem, olgeta oli stat blong bonem ol sakrefaes ya i go long Hae God, blong mekem wosip long hem.","Nating we olgeta oli no stat yet blong wokem haos* ya blong Hae God, be long namba seven manis ya, long fas dei blong hem, olgeta oli stat blong bonem ol sakrefaes ya i go long Hae God, blong mekem wosip long hem."],[3,7,"Nao long nekis yia, ol man oli givim mane blong pem ol kapenta wetem ol man blong katem ston, blong oli wokem haos* blong Hae God bakegen. Mo oli tekem ol kakae, mo ol samting blong dring, mo ol olifoel,* oli sanem i go long tufala taon ya, Taea mo Saedon, blong pem ol sida* long Lebanon blong wokem haos ya long hem, olsem we King Sirus blong Pesia i talem. Olgeta oli askem long ol man blong tufala taon ya blong oli katem ol sida ya, oli putum long solwota, oli karem i kamdaon long bigfala pasis ya long Jopa.","Nao long nekis yia, ol man oli givim mane blong pem ol kapenta wetem ol man blong katem ston, blong oli wokem haos* blong Hae God bakegen. Mo oli tekem ol kakae, mo ol samting blong dring, mo ol olifoel,* oli sanem i go long tufala taon ya, Taea mo Saedon, blong pem ol sida* long Lebanon blong wokem haos ya long hem, olsem we King Sirus blong Pesia i talem. Olgeta oli askem long ol man blong tufala taon ya blong oli katem ol sida ya, oli putum long solwota, oli karem i kamdaon long bigfala pasis ya long Jopa."],[3,8,"Nao long namba tu manis blong yia ya, olgeta oli stat blong wokem haos ya blong Hae God bakegen long ples ya we olfala haos i stap long hem bifo. Olgeta we oli joen wanples blong mekem wok ya, i gat Serubabel, mo Hae Pris* ya Josua, wetem ol narafala pris, mo ol Livaet* mo ol narafala man, gogo i finisim olgeta evriwan we oli aot long Babilonia oli kambak long Jerusalem.* Ol Livaet we yia blong olgeta i kasem twanti i go antap, ol lida oli putumap olgeta blong oli bos long wok ya.","Nao long namba tu manis blong yia ya, olgeta oli stat blong wokem haos ya blong Hae God bakegen long ples ya we olfala haos i stap long hem bifo. Olgeta we oli joen wanples blong mekem wok ya, i gat Serubabel, mo Hae Pris* ya Josua, wetem ol narafala pris, mo ol Livaet* mo ol narafala man, gogo i finisim olgeta evriwan we oli aot long Babilonia oli kambak long Jerusalem.* Ol Livaet we yia blong olgeta i kasem twanti i go antap, ol lida oli putumap olgeta blong oli bos long wok ya."],[3,9,"Long olgeta ya, Jesua wetem ol pikinini blong hem mo ol brata blong hem, mo Kadmiel wetem ol pikinini blong hem oli joen wanples blong lukaot long ol wok ya, mo ol laen blong Henadad tu oli stap givhan long olgeta. Kadmiel olgeta oli laen blong Hodavia, mo olgeta ya evriwan oli laen* blong Livae.*","Long olgeta ya, Jesua wetem ol pikinini blong hem mo ol brata blong hem, mo Kadmiel wetem ol pikinini blong hem oli joen wanples blong lukaot long ol wok ya, mo ol laen blong Henadad tu oli stap givhan long olgeta. Kadmiel olgeta oli laen blong Hodavia, mo olgeta ya evriwan oli laen* blong Livae.*"],[3,10,"Nao taem ol man ya oli stat blong putum fandesen blong haos ya, ol pris oli putum ol spesel klos blong olgeta, nao oli holem ol trampet, oli go stanap long ples blong olgeta. Mo ol Livaet we oli laen blong Asaf oli holem ol simbol,* oli go stanap long ples blong olgeta. Nao olgeta oli stap presem Hae God, folem fasin we King Deved i bin talem long ol man long taem blong hem.","Nao taem ol man ya oli stat blong putum fandesen blong haos ya, ol pris oli putum ol spesel klos blong olgeta, nao oli holem ol trampet, oli go stanap long ples blong olgeta. Mo ol Livaet we oli laen blong Asaf oli holem ol simbol,* oli go stanap long ples blong olgeta. Nao olgeta oli stap presem Hae God, folem fasin we King Deved i bin talem long ol man long taem blong hem."],[3,11,"Olgeta ya oli stap singsing, oli stap presem Hae God, mo ol narafala man oli stap joen blong talem se, “Hae God i God blong yumi, mo hem i gud tumas. Oltaem bambae hem i lavem yumi gogo i no save finis.” Olgeta evriwan oli stap singsingaot bigwan, oli stap presem Hae God, from we oli statem wok ya blong putum fandesen blong haos ya.","Olgeta ya oli stap singsing, oli stap presem Hae God, mo ol narafala man oli stap joen blong talem se, “Hae God i God blong yumi, mo hem i gud tumas. Oltaem bambae hem i lavem yumi gogo i no save finis.” Olgeta evriwan oli stap singsingaot bigwan, oli stap presem Hae God, from we oli statem wok ya blong putum fandesen blong haos ya."],[3,12,"Nao long taem ya, i gat ol olfala oli stap yet we oli bin luk haos blong Hae God we i stap long ples ya bifo. Sam long olgeta oli pris, mo sam oli Livaet, mo sam oli hed blong ol famle blong olgeta. Mo taem oli luk we ol man oli stap putum fandesen blong haos ya bakegen, oli stap krae we oli krae bigwan from olfala haos ya bifo we ol enemi oli bin spolem. Be plante man oli stap singsingaot bigwan from we oli glad tumas.","Nao long taem ya, i gat ol olfala oli stap yet we oli bin luk haos blong Hae God we i stap long ples ya bifo. Sam long olgeta oli pris, mo sam oli Livaet, mo sam oli hed blong ol famle blong olgeta. Mo taem oli luk we ol man oli stap putum fandesen blong haos ya bakegen, oli stap krae we oli krae bigwan from olfala haos ya bifo we ol enemi oli bin spolem. Be plante man oli stap singsingaot bigwan from we oli glad tumas."],[3,13,"Nao man i no save haremsave se oli stap krae from we oli harem nogud, no oli stap singsingaot from we oli glad, from we olgeta oli stap mekem bigfala noes, we man we i stap longwe i save harem.","Nao man i no save haremsave se oli stap krae from we oli harem nogud, no oli stap singsingaot from we oli glad, from we olgeta oli stap mekem bigfala noes, we man we i stap longwe i save harem."],[4,1,"Nao taem ol enemi blong ol laen* blong Juda* wetem ol laen blong Benjamin* oli harem we olgeta oli aot long Babilonia oli kambak, mo oli stap wokem bakegen haos* ya blong Hae God we i God blong olgeta,","Nao taem ol enemi blong ol laen* blong Juda* wetem ol laen blong Benjamin* oli harem we olgeta oli aot long Babilonia oli kambak, mo oli stap wokem bakegen haos* ya blong Hae God we i God blong olgeta,"],[4,2,"oli girap, oli kam luk Serubabel wetem ol hed blong ol famle blong olgeta, oli talem long olgeta se, “Bambae mifala i kam joen long yufala, blong yumi wokem haos ya blong Hae God we i God blong yufala, from we mifala tu i stap mekem wosip long hem. Mifala i stap mekem sakrefaes long hem, i stat long taem ya bifo we King Esaradon blong Asiria, i putum ol olfala blong mifala oli stap long ples ya.”","oli girap, oli kam luk Serubabel wetem ol hed blong ol famle blong olgeta, oli talem long olgeta se, “Bambae mifala i kam joen long yufala, blong yumi wokem haos ya blong Hae God we i God blong yufala, from we mifala tu i stap mekem wosip long hem. Mifala i stap mekem sakrefaes long hem, i stat long taem ya bifo we King Esaradon blong Asiria, i putum ol olfala blong mifala oli stap long ples ya.”"],[4,3,"Nao Serubabel mo Hae Pris* ya Josua mo ol hed blong ol famle ya oli talem long olgeta se, “Mifala i laen blong Isrel,* mo Hae God i God blong mifala. Yufala i no gat bisnes nating long wok ya blong wokem haos blong hem. Bambae mifala nomo i wokem haos ya, olsem we King Sirus blong Pesia i talem long mifala.”","Nao Serubabel mo Hae Pris* ya Josua mo ol hed blong ol famle ya oli talem long olgeta se, “Mifala i laen blong Isrel,* mo Hae God i God blong mifala. Yufala i no gat bisnes nating long wok ya blong wokem haos blong hem. Bambae mifala nomo i wokem haos ya, olsem we King Sirus blong Pesia i talem long mifala.”"],[4,4,"Nao ol enemi ya blong olgeta oli stap traem blong mekem tingting blong olgeta i foldaon, mo blong mekem olgeta oli fraet, blong oli no moa wokem haos ya.","Nao ol enemi ya blong olgeta oli stap traem blong mekem tingting blong olgeta i foldaon, mo blong mekem olgeta oli fraet, blong oli no moa wokem haos ya."],[4,5,"Mo oli stap pem ol haeman blong King Sirus blong Pesia we oli stap wok long ples ya, blong oli agensem olgeta ya from wok ya. Oltaem olgeta oli gohed, oli stap mekem fasin ya, i stat long taem blong king ya, gogo kasem taem we Darias i kam king.","Mo oli stap pem ol haeman blong King Sirus blong Pesia we oli stap wok long ples ya, blong oli agensem olgeta ya from wok ya. Oltaem olgeta oli gohed, oli stap mekem fasin ya, i stat long taem blong king ya, gogo kasem taem we Darias i kam king."],[4,6,"Biaen G,we plante yia i pas, long taem ya we King Sekses i rul long Pesia, ol enemi blong ol man Jerusalem* wetem ol narafala man Juda,* oli raetem wan leta blong agens long olgeta, nao oli sanem i go long hem.","Biaen G,we plante yia i pas, long taem ya we King Sekses i rul long Pesia, ol enemi blong ol man Jerusalem* wetem ol narafala man Juda,* oli raetem wan leta blong agens long olgeta, nao oli sanem i go long hem."],[4,7,"Mo bakegen, long taem we King Ataksekses i rul long Pesia, Bislam, mo Mitredat, mo Tabehel, wetem ol fren blong trifala oli raetem wan leta i go long king ya. Oli raetem leta ya long lanwis ya Arameik,* mo oli wantem se taem man blong king ya i ridim leta ya i go long hem, bambae i mas tanem i go long lanwis blong hem.","Mo bakegen, long taem we King Ataksekses i rul long Pesia, Bislam, mo Mitredat, mo Tabehel, wetem ol fren blong trifala oli raetem wan leta i go long king ya. Oli raetem leta ya long lanwis ya Arameik,* mo oli wantem se taem man blong king ya i ridim leta ya i go long hem, bambae i mas tanem i go long lanwis blong hem."],[4,8,"Mo Rehum we i haeman blong king long provins ya Narasaed Yufretes Reva long Wes, wetem Simsae we i sekretari blong provins ya, tufala tu i raetem wan leta i go long King Ataksekses, we long leta ya tufala i tok agens long ol man Jerusalem. Long leta ya, tufala i talem se,","Mo Rehum we i haeman blong king long provins ya Narasaed Yufretes Reva long Wes, wetem Simsae we i sekretari blong provins ya, tufala tu i raetem wan leta i go long King Ataksekses, we long leta ya tufala i tok agens long ol man Jerusalem. Long leta ya, tufala i talem se,"],[4,9,"“King Ataksekses, mi Rehum, mi haeman blong yu long provins ya Narasaed Yufretes Reva long Wes. Mi wetem Simsae we i sekretari blong provins ya, mo ol fren blong mitufala, mifala i raetem leta ya i kam long yu. Ol fren ya blong mitufala, i gat ol jaj, mo ol haeman we fastaem, sam oli man Erek, mo sam oli man Babilonia, mo sam oli man Susa long kantri ya Elam. Mo i gat ol narafala man tu, we King Asubanipal bifo i bin tekem olgeta i kam. King ya i wan hae king we i gat paoa, mo hem i bin tekemaot olgeta long ol ples blong olgeta, nao i kam putum olgeta oli stap long taon ya Sameria,* mo long ol ples olbaot long provins ya. “Mifala ol man blong wok blong yu long provins ya.","“King Ataksekses, mi Rehum, mi haeman blong yu long provins ya Narasaed Yufretes Reva long Wes. Mi wetem Simsae we i sekretari blong provins ya, mo ol fren blong mitufala, mifala i raetem leta ya i kam long yu. Ol fren ya blong mitufala, i gat ol jaj, mo ol haeman we fastaem, sam oli man Erek, mo sam oli man Babilonia, mo sam oli man Susa long kantri ya Elam. Mo i gat ol narafala man tu, we King Asubanipal bifo i bin tekem olgeta i kam. King ya i wan hae king we i gat paoa, mo hem i bin tekemaot olgeta long ol ples blong olgeta, nao i kam putum olgeta oli stap long taon ya Sameria,* mo long ol ples olbaot long provins ya. “Mifala ol man blong wok blong yu long provins ya.",11],[4,12,"Mifala i wantem blong yu yu save we ol man Juda ya we oli aot long ol narafala provins blong yu, naoia oli kam stap long Jerusalem, mo oli stap wokem taon ya bakegen we oltaem, ol man blong hem oli stap mekem ol rabis fasin, mo oli stap agensem ol king. Oli stap wokemgud ol fandesen blong bigfala stonwol blong taon ya, mo oli stap wokem stonwol ya blong hem bakegen, mo bambae i no longtaem oli finisim.","Mifala i wantem blong yu yu save we ol man Juda ya we oli aot long ol narafala provins blong yu, naoia oli kam stap long Jerusalem, mo oli stap wokem taon ya bakegen we oltaem, ol man blong hem oli stap mekem ol rabis fasin, mo oli stap agensem ol king. Oli stap wokemgud ol fandesen blong bigfala stonwol blong taon ya, mo oli stap wokem stonwol ya blong hem bakegen, mo bambae i no longtaem oli finisim."],[4,13,"“King, sipos oli wokem taon ya bakegen, mo oli finisim bigfala stonwol blong hem, bambae oli no moa save pem ol takis blong olgeta. Nao mane we i stap kam long yu, bambae i godaon.","“King, sipos oli wokem taon ya bakegen, mo oli finisim bigfala stonwol blong hem, bambae oli no moa save pem ol takis blong olgeta. Nao mane we i stap kam long yu, bambae i godaon."],[4,14,"Mo from we mifala i stap wok blong yu, mifala i no wantem luk samting olsem i kamtru. Taswe mifala i talemaot long yu,","Mo from we mifala i stap wok blong yu, mifala i no wantem luk samting olsem i kamtru. Taswe mifala i talemaot long yu,"],[4,15,"blong yu save talem long ol man blong yu, blong oli traem lukaot ol ripot blong taon ya long ol ololfala buk we ol bubu blong yu bifo oli bin raetemdaon. Sipos yu mekem olsem, bambae yu faenem we ol man blong taon ya, oltaem oli stap agens long ol king, mo we i stat bifo olgeta i kam kasem tede, oli stap mekem ol king mo ol lida blong provins ya oli trabol. Oltaem i strong tumas blong rulum olgeta. From ol samting ya nao, ol man bifo oli spolem taon ya.","blong yu save talem long ol man blong yu, blong oli traem lukaot ol ripot blong taon ya long ol ololfala buk we ol bubu blong yu bifo oli bin raetemdaon. Sipos yu mekem olsem, bambae yu faenem we ol man blong taon ya, oltaem oli stap agens long ol king, mo we i stat bifo olgeta i kam kasem tede, oli stap mekem ol king mo ol lida blong provins ya oli trabol. Oltaem i strong tumas blong rulum olgeta. From ol samting ya nao, ol man bifo oli spolem taon ya."],[4,16,"Taswe mifala i bilif strong se sipos oli wokem taon ya bakegen, mo oli finisim bigfala stonwol blong hem, bambae yu lusum olgeta ples long provins ya.”","Taswe mifala i bilif strong se sipos oli wokem taon ya bakegen, mo oli finisim bigfala stonwol blong hem, bambae yu lusum olgeta ples long provins ya.”"],[4,17,"Nao king i raetem ansa blong leta ya, i sanem i go long Rehum olgeta, i talem se, “Mi, King Ataksekses, mi talem halo long yu, Rehum, we yu haeman blong mi, mo long yu Simsae, we yu sekretari blong provins ya Narasaed Yufretes Reva long Wes, mo long ol fren blong yutufala we oli stap long Sameria, mo long ol narafala ples long provins ya.","Nao king i raetem ansa blong leta ya, i sanem i go long Rehum olgeta, i talem se, “Mi, King Ataksekses, mi talem halo long yu, Rehum, we yu haeman blong mi, mo long yu Simsae, we yu sekretari blong provins ya Narasaed Yufretes Reva long Wes, mo long ol fren blong yutufala we oli stap long Sameria, mo long ol narafala ples long provins ya."],[4,18,"“Leta ya we yufala i sanem i kam, oli bin tanem i kam long lanwis blong mi, nao oli ridim i kam long mi.","“Leta ya we yufala i sanem i kam, oli bin tanem i kam long lanwis blong mi, nao oli ridim i kam long mi."],[4,19,"Nao mi mi talem long ol man blong mi blong oli go faenemaot bisnes ya, mo olgeta oli faenem we ol tok we yufala i talem i tru nomo. I stat bifo olgeta, i kam kasem tede, oltaem ol man Jerusalem oli stap girap, oli stap agens long ol king blong ol narafala kantri. Mo long ples ya, oltaem i gat fulap man we oli stap agens long ol loa, mo oltaem oli stap mekem trabol.","Nao mi mi talem long ol man blong mi blong oli go faenemaot bisnes ya, mo olgeta oli faenem we ol tok we yufala i talem i tru nomo. I stat bifo olgeta, i kam kasem tede, oltaem ol man Jerusalem oli stap girap, oli stap agens long ol king blong ol narafala kantri. Mo long ples ya, oltaem i gat fulap man we oli stap agens long ol loa, mo oltaem oli stap mekem trabol."],[4,20,"Bifo, ol king blong ples ya oli gat paoa mo oli stap rul long olgeta ples long provins ya we yufala i stap long hem naoia, mo oli stap tekem takis long olgeta man blong provins ya.","Bifo, ol king blong ples ya oli gat paoa mo oli stap rul long olgeta ples long provins ya we yufala i stap long hem naoia, mo oli stap tekem takis long olgeta man blong provins ya."],[4,21,"Nao from samting ya, yufala i mas putum wan tok blong blokem olgeta, blong oli no moa gohed blong wokem taon ya bakegen, gogo kasem we mi mi givim wan tok long yufala bakegen.","Nao from samting ya, yufala i mas putum wan tok blong blokem olgeta, blong oli no moa gohed blong wokem taon ya bakegen, gogo kasem we mi mi givim wan tok long yufala bakegen."],[4,22,"Plis yufala i mekem samting ya kwiktaem, blong oli no moa spolem ol wok blong mi.”","Plis yufala i mekem samting ya kwiktaem, blong oli no moa spolem ol wok blong mi.”"],[4,23,"Nao taem man we i tekem leta ya i kam, i ridim i go long Rehum mo Simsae, mo ol fren blong tufala, kwiktaem nomo oli go long Jerusalem, oli fosem ol man Juda ya blong oli finis, oli no moa wokem taon ya bakegen.","Nao taem man we i tekem leta ya i kam, i ridim i go long Rehum mo Simsae, mo ol fren blong tufala, kwiktaem nomo oli go long Jerusalem, oli fosem ol man Juda ya blong oli finis, oli no moa wokem taon ya bakegen."],[4,24,"Nao from ol samting ya, ol laen* blong Juda* oli no moa wokem haos* blong Hae God bakegen, oli livim i stap, gogo kasem namba tu yia we King Darias i rul long Pesia.","Nao from ol samting ya, ol laen* blong Juda* oli no moa wokem haos* blong Hae God bakegen, oli livim i stap, gogo kasem namba tu yia we King Darias i rul long Pesia."],[5,1,"Nao long taem ya, Profet Hagae, mo Profet Sekaraea we olfala bubu blong hem Ido, tufala i stap talemaot tok we God blong yumi i givim long tufala, blong tufala i talemaot long ol laen blong Isrel* we oli stap long Jerusalem* mo long ol narafala ples long distrik ya.","Nao long taem ya, Profet Hagae, mo Profet Sekaraea we olfala bubu blong hem Ido, tufala i stap talemaot tok we God blong yumi i givim long tufala, blong tufala i talemaot long ol laen blong Isrel* we oli stap long Jerusalem* mo long ol narafala ples long distrik ya."],[5,2,"Nao taem Serubabel we papa blong hem Sealtiel, mo Hae Pris* ya Josua we papa blong hem Jehosadak, tufala i harem ol tok ya, tufala i girap, tufala i stat wokem haos ya blong Hae God bakegen, mo tufala profet ya i givhan long tufala.","Nao taem Serubabel we papa blong hem Sealtiel, mo Hae Pris* ya Josua we papa blong hem Jehosadak, tufala i harem ol tok ya, tufala i girap, tufala i stat wokem haos ya blong Hae God bakegen, mo tufala profet ya i givhan long tufala."],[5,3,"Nao long taem ya, Tatenae we i resedenkomisina blong provins ya Narasaed Yufretes Reva long Wes, mo Setara Bosenae wetem ol narafala haeman blong provins ya, olgeta oli kam long Jerusalem, oli askem long olgeta se, “?Yufala i stap wokem haos ya blong God bakegen, mo yufala i wantem blong putum evri samting blong mekem wosip i go insaed long hem bakegen, be hu i givim raet long yufala blong mekem wok ya?","Nao long taem ya, Tatenae we i resedenkomisina blong provins ya Narasaed Yufretes Reva long Wes, mo Setara Bosenae wetem ol narafala haeman blong provins ya, olgeta oli kam long Jerusalem, oli askem long olgeta se, “?Yufala i stap wokem haos ya blong God bakegen, mo yufala i wantem blong putum evri samting blong mekem wosip i go insaed long hem bakegen, be hu i givim raet long yufala blong mekem wok ya?"],[5,4,"?Hu olgeta oli stap wokem haos ya? Mifala i wantem save nem blong olgeta.”","?Hu olgeta oli stap wokem haos ya? Mifala i wantem save nem blong olgeta.”"],[5,5,"Be God i stap lukaot gud long ol lida ya blong ol laen blong Isrel, nao ol haeman ya blong Pesia oli no blokem olgeta. Be oli raetem leta i go long King Darias fastaem, nao oli stap wet long ansa blong leta ya blong olgeta.","Be God i stap lukaot gud long ol lida ya blong ol laen blong Isrel, nao ol haeman ya blong Pesia oli no blokem olgeta. Be oli raetem leta i go long King Darias fastaem, nao oli stap wet long ansa blong leta ya blong olgeta."],[5,6,"Leta ya we oli raetem i go long king, i talem se,","Leta ya we oli raetem i go long king, i talem se,"],[5,7,"“King Darias, mifala i wantem we oltaem bambae yu stap rul long pis.","“King Darias, mifala i wantem we oltaem bambae yu stap rul long pis."],[5,8,"“Mifala i wantem talemaot long yu, se mifala i bin go visitim distrik ya Juda, mo mifala i luk we ol man oli stap wokem wan niufala haos bakegen blong God ya we i gat olgeta paoa. Oli stap yusum ol bigbigfala ston blong wokem haos ya, mo oli stap putum ol bigbigfala timba insaed long ol wol blong hem. Olgeta oli stap hadwok tumas blong mekem olgeta samting blong haos ya i stret gud, mo wok blong hem i stap gohed gud nomo.","“Mifala i wantem talemaot long yu, se mifala i bin go visitim distrik ya Juda, mo mifala i luk we ol man oli stap wokem wan niufala haos bakegen blong God ya we i gat olgeta paoa. Oli stap yusum ol bigbigfala ston blong wokem haos ya, mo oli stap putum ol bigbigfala timba insaed long ol wol blong hem. Olgeta oli stap hadwok tumas blong mekem olgeta samting blong haos ya i stret gud, mo wok blong hem i stap gohed gud nomo."],[5,9,"“Mifala i askem long ol lida blong olgeta se, ‘?Yufala i stap wokem haos ya blong God bakegen, mo yufala i wantem blong putum evri samting blong mekem wosip i go insaed long hem bakegen, be hu i givim raet long yufala blong mekem wok ya?’","“Mifala i askem long ol lida blong olgeta se, ‘?Yufala i stap wokem haos ya blong God bakegen, mo yufala i wantem blong putum evri samting blong mekem wosip i go insaed long hem bakegen, be hu i givim raet long yufala blong mekem wok ya?’"],[5,10,"Mo mifala i askem nem blong olgeta, blong mifala i save talemaot long yu ol man ya we oli stap lidim olgeta long wok ya.","Mo mifala i askem nem blong olgeta, blong mifala i save talemaot long yu ol man ya we oli stap lidim olgeta long wok ya."],[5,11,"“Be oli talem se, ‘God blong mifala, hem i God blong heven mo wol, mo mifala i man blong wok blong hem. Mifala i stap wokem haos ya blong hem bakegen we bifo olgeta, wan king blong Isrel i bin wokem. King ya i gat paoa, mo hem i bin wokem haos ya bifo, mo i bin putum evri samting blong mekem wosip i go insaed long hem.","“Be oli talem se, ‘God blong mifala, hem i God blong heven mo wol, mo mifala i man blong wok blong hem. Mifala i stap wokem haos ya blong hem bakegen we bifo olgeta, wan king blong Isrel i bin wokem. King ya i gat paoa, mo hem i bin wokem haos ya bifo, mo i bin putum evri samting blong mekem wosip i go insaed long hem."],[5,12,"Be from we ol bubu blong mifala bifo oli mekem God ya i kros, hem i letem olgeta oli go long han blong King Nebukadnesa blong Babilonia, we hem i man Koldia. Hem i brekemdaon haos ya, mo i tekem ol olfala ya blong mifala oli go stap wok slef* long Babilonia.","Be from we ol bubu blong mifala bifo oli mekem God ya i kros, hem i letem olgeta oli go long han blong King Nebukadnesa blong Babilonia, we hem i man Koldia. Hem i brekemdaon haos ya, mo i tekem ol olfala ya blong mifala oli go stap wok slef* long Babilonia."],[5,13,"Be long fas yia we King Sirus i rul long Babilonia, hem i talem se mifala i mas kam wokem haos ya bakegen.","Be long fas yia we King Sirus i rul long Babilonia, hem i talem se mifala i mas kam wokem haos ya bakegen."],[5,14,"Olgeta samting we oli stap yusum blong mekem wosip insaed long haos ya bifo, we oli wokem olgeta long gol mo long silva, King Nebukadnesa i bin tekemaot olgeta, i go putum olgeta long haos blong god blong hem long Babilon. Be King Sirus i givimbak ol samting ya finis long mifala. Hem i tekemaot ol samting ya long haos blong god blong ol man Babilon, i givim olgeta i go long Sesbajara, we i distrikejen* long distrik ya Juda.","Olgeta samting we oli stap yusum blong mekem wosip insaed long haos ya bifo, we oli wokem olgeta long gol mo long silva, King Nebukadnesa i bin tekemaot olgeta, i go putum olgeta long haos blong god blong hem long Babilon. Be King Sirus i givimbak ol samting ya finis long mifala. Hem i tekemaot ol samting ya long haos blong god blong ol man Babilon, i givim olgeta i go long Sesbajara, we i distrikejen* long distrik ya Juda."],[5,15,"Mo king i talem long hem blong i karem ol samting ya i kambak long Jerusalem, mo i wokem haos blong Hae God bakegen long sem ples we haos ya i stap long hem bifo, mo i putum ol samting ya i stap insaed long hem.","Mo king i talem long hem blong i karem ol samting ya i kambak long Jerusalem, mo i wokem haos blong Hae God bakegen long sem ples we haos ya i stap long hem bifo, mo i putum ol samting ya i stap insaed long hem."],[5,16,"Nao Sesbajara i kam, i putum fandesen blong haos ya, mo i stat long taem ya, wok blong wokem haos ya i stap gohed kam kasem tede, be haos ya i no finis yet.’","Nao Sesbajara i kam, i putum fandesen blong haos ya, mo i stat long taem ya, wok blong wokem haos ya i stap gohed kam kasem tede, be haos ya i no finis yet.’"],[5,17,"“King, hemia nao tok blong olgeta. Mo sipos yu ting se i gud, bambae yu talem long ol man blong yu blong oli traem luklukgud long ol buk ya long Babilon, we ol king oli stap raetemdaon ol ripot blong olgeta long hem, blong faenemaot se King Sirus i talem long olgeta ya blong oli wokem haos ya bakegen long Jerusalem, no nogat. Nao bambae yu talemaot tingting blong yu long mifala from bisnes ya.”","“King, hemia nao tok blong olgeta. Mo sipos yu ting se i gud, bambae yu talem long ol man blong yu blong oli traem luklukgud long ol buk ya long Babilon, we ol king oli stap raetemdaon ol ripot blong olgeta long hem, blong faenemaot se King Sirus i talem long olgeta ya blong oli wokem haos ya bakegen long Jerusalem, no nogat. Nao bambae yu talemaot tingting blong yu long mifala from bisnes ya.”"],[6,1,"Nao King Darias i talem long ol man blong hem blong oli go lukaot tok ya blong King Sirus long ol buk ya long haos ya long Babilon, we ol king oli stap putumgud ol ripot blong olgeta long hem.","Nao King Darias i talem long ol man blong hem blong oli go lukaot tok ya blong King Sirus long ol buk ya long haos ya long Babilon, we ol king oli stap putumgud ol ripot blong olgeta long hem."],[6,2,"Be oli no faenem tok ya blong hem long Babilon, oli faenem long buk blong ol ripot we i stap long taon ya Ekbatana, we i kaptel blong provins ya Media. Tok ya i talem se,","Be oli no faenem tok ya blong hem long Babilon, oli faenem long buk blong ol ripot we i stap long taon ya Ekbatana, we i kaptel blong provins ya Media. Tok ya i talem se,"],[6,3,"“Long taem we King Sirus i stap rul, long fas yia blong hem, hem i talemaot se haos* blong God long Jerusalem,* ol man Juda* oli mas wokem bakegen, blong oli gat ples blong bonem ol sakrefaes, mo blong givim ol presen i go long God blong olgeta. Haos ya, hae blong hem bambae i kasem twanti seven meta, mo bigfala blong hem bambae i kasem twanti seven meta.","“Long taem we King Sirus i stap rul, long fas yia blong hem, hem i talemaot se haos* blong God long Jerusalem,* ol man Juda* oli mas wokem bakegen, blong oli gat ples blong bonem ol sakrefaes, mo blong givim ol presen i go long God blong olgeta. Haos ya, hae blong hem bambae i kasem twanti seven meta, mo bigfala blong hem bambae i kasem twanti seven meta."],[6,4,"Wol blong hem bambae oli mekem i go antap we bambae oli putum tri laen blong ston, wan laen blong timba, tri laen blong ston, wan laen blong timba, mo bambae oli mekem olsem, gogo oli finisim wol blong hem. Mo ol mane blong mekem wok ya bambae i kamaot long mane blong gavman.","Wol blong hem bambae oli mekem i go antap we bambae oli putum tri laen blong ston, wan laen blong timba, tri laen blong ston, wan laen blong timba, mo bambae oli mekem olsem, gogo oli finisim wol blong hem. Mo ol mane blong mekem wok ya bambae i kamaot long mane blong gavman."],[6,5,"Mo olgeta samting blong haos ya we oli wokem olgeta long gol mo long silva, we oli stap yusum bifo blong mekem wosip, we King Nebukadnesa i bin tekemaot olgeta long haos ya, i karem i kam long Babilon, be bambae oli mas gobak long prapa ples blong olgeta long niufala haos ya blong God we bambae oli wokem long Jerusalem.”","Mo olgeta samting blong haos ya we oli wokem olgeta long gol mo long silva, we oli stap yusum bifo blong mekem wosip, we King Nebukadnesa i bin tekemaot olgeta long haos ya, i karem i kam long Babilon, be bambae oli mas gobak long prapa ples blong olgeta long niufala haos ya blong God we bambae oli wokem long Jerusalem.”"],[6,6,"Nao King Darias i sanem ansa blong hem i go long olgeta, i talem se, “Tatenae. Yu yu resedenkomisina blong mi long provins ya Narasaed Yufretes Reva long Wes, mo mi mi raet i kam long yu mo long yu Setara Bosenae, mo long ol narafala haeman we oli stap wetem yutufala long provins ya. “Mi mi talem long yufala, se yufala i no go klosap long olgeta ya.","Nao King Darias i sanem ansa blong hem i go long olgeta, i talem se, “Tatenae. Yu yu resedenkomisina blong mi long provins ya Narasaed Yufretes Reva long Wes, mo mi mi raet i kam long yu mo long yu Setara Bosenae, mo long ol narafala haeman we oli stap wetem yutufala long provins ya. “Mi mi talem long yufala, se yufala i no go klosap long olgeta ya."],[6,7,"Yufala i no pusum nus blong yufala long wok ya blong haos* blong God. Yufala i letem distrikejen* ya blong mi long Juda* wetem ol lida blong olgeta oli gohed blong wokem haos ya bakegen long sem ples we haos ya i stap long hem bifo.","Yufala i no pusum nus blong yufala long wok ya blong haos* blong God. Yufala i letem distrikejen* ya blong mi long Juda* wetem ol lida blong olgeta oli gohed blong wokem haos ya bakegen long sem ples we haos ya i stap long hem bifo."],[6,8,"“Mo mi mi talem long yufala se, yufala tu i mas givhan long olgeta blong oli wokem haos ya bakegen. Olgeta mane we oli nidim long wok ya, yufala i mas tekemaot long ol mane blong takis, we yufala i stap tekem long nem blong mi long provins ya blong yufala, mo sipos oli askem, bambae yufala i mas givim kwiktaem long olgeta, blong wok i save gohed gud.","“Mo mi mi talem long yufala se, yufala tu i mas givhan long olgeta blong oli wokem haos ya bakegen. Olgeta mane we oli nidim long wok ya, yufala i mas tekemaot long ol mane blong takis, we yufala i stap tekem long nem blong mi long provins ya blong yufala, mo sipos oli askem, bambae yufala i mas givim kwiktaem long olgeta, blong wok i save gohed gud."],[6,9,"Mo evri dei, sipos ol pris* blong olgeta oli wantem ol yang bul, no ol man sipsip, no ol smol man sipsip, blong oli bonem blong mekem sakrefaes long God ya blong heven, no sipos oli wantem wit,* no sol, no waen, no olifoel,* bambae yufala i mas givim long olgeta.","Mo evri dei, sipos ol pris* blong olgeta oli wantem ol yang bul, no ol man sipsip, no ol smol man sipsip, blong oli bonem blong mekem sakrefaes long God ya blong heven, no sipos oli wantem wit,* no sol, no waen, no olifoel,* bambae yufala i mas givim long olgeta."],[6,10,"Yufala i mas mekem ol samting ya, blong olgeta oli save mekem ol sakrefaes we God ya blong heven i glad long hem, mo blong oli save prea long hem blong hem i blesem mi wetem ol pikinini blong mi.","Yufala i mas mekem ol samting ya, blong olgeta oli save mekem ol sakrefaes we God ya blong heven i glad long hem, mo blong oli save prea long hem blong hem i blesem mi wetem ol pikinini blong mi."],[6,11,"“Mo bakegen, mi mi talem long yufala, se sipos wan man i no obei long tok ya blong mi, ol man blong mi bambae oli mas go pulumaot wan wud blong haos blong hem, oli sapenem, oli planem i gotru long bodi blong hem, mo haos blong hem, oli mas mekem i kam ples blong sakem doti.","“Mo bakegen, mi mi talem long yufala, se sipos wan man i no obei long tok ya blong mi, ol man blong mi bambae oli mas go pulumaot wan wud blong haos blong hem, oli sapenem, oli planem i gotru long bodi blong hem, mo haos blong hem, oli mas mekem i kam ples blong sakem doti."],[6,12,"God ya i jusumaot ples ya Jerusalem* mo i talem se, ‘Ol man oli mas kam long ples ya blong mekem wosip long mi.’ Mo prea blong mi, we hem bambae i flatemgud king no neson we i no obei long tok ya blong mi, i traem kam spolem haos ya blong hem. “Mi mi King Darias, mo hemia tok blong mi. Olgeta man oli mas ona gud long tok ya.”","God ya i jusumaot ples ya Jerusalem* mo i talem se, ‘Ol man oli mas kam long ples ya blong mekem wosip long mi.’ Mo prea blong mi, we hem bambae i flatemgud king no neson we i no obei long tok ya blong mi, i traem kam spolem haos ya blong hem. “Mi mi King Darias, mo hemia tok blong mi. Olgeta man oli mas ona gud long tok ya.”"],[6,13,"Nao Tatenae we i resedenkomisina, mo Setara Bosenae wetem ol narafala haeman blong provins ya Narasaed Yufretes Reva long Wes oli mekem evri samting stret olsem we king i talem.","Nao Tatenae we i resedenkomisina, mo Setara Bosenae wetem ol narafala haeman blong provins ya Narasaed Yufretes Reva long Wes oli mekem evri samting stret olsem we king i talem."],[6,14,"Ol lida blong ol laen* blong Isrel* oli gohed gud long wok ya, mo Profet Hagae wetem Profet Sekaraea, tufala i stap leftemap tingting blong olgeta blong oli mekem wok ya. Nao oli finisimgud haos* ya, olsem we God blong yumi ol laen blong Isrel i bin talem, mo olsem we King Sirus, mo King Darias, mo King Ataksekses i bin talem long taem ya we trifala ya wanwan i king blong Pesia.","Ol lida blong ol laen* blong Isrel* oli gohed gud long wok ya, mo Profet Hagae wetem Profet Sekaraea, tufala i stap leftemap tingting blong olgeta blong oli mekem wok ya. Nao oli finisimgud haos* ya, olsem we God blong yumi ol laen blong Isrel i bin talem, mo olsem we King Sirus, mo King Darias, mo King Ataksekses i bin talem long taem ya we trifala ya wanwan i king blong Pesia."],[6,15,"Haos ya blong God, oli finisimgud long namba sikis yia blong King Darias, long manis ya Adara* we i namba twelef manis, long namba tri dei blong hem.","Haos ya blong God, oli finisimgud long namba sikis yia blong King Darias, long manis ya Adara* we i namba twelef manis, long namba tri dei blong hem."],[6,16,"Nao ol pris* wetem ol Livaet* mo ol narafala laen* blong Isrel* we oli aot long Babilonia oli kambak, olgeta oli glad tumas, mo oli mekem prea blong mekem haos* ya i tabu, i blong Hae God.","Nao ol pris* wetem ol Livaet* mo ol narafala laen* blong Isrel* we oli aot long Babilonia oli kambak, olgeta oli glad tumas, mo oli mekem prea blong mekem haos* ya i tabu, i blong Hae God."],[6,17,"Long dei ya we olgeta oli mekem haos ya i tabu, oli kilim wan handred bul, mo tu handred man sipsip, mo fo handred smol man sipsip blong mekem sakrefaes, mo oli kilim twelef man nani blong mekem sakrefaes blong tekemaot sin, we ol nani ya wanwan i blong makem ol twelef laen ya blong olgeta.","Long dei ya we olgeta oli mekem haos ya i tabu, oli kilim wan handred bul, mo tu handred man sipsip, mo fo handred smol man sipsip blong mekem sakrefaes, mo oli kilim twelef man nani blong mekem sakrefaes blong tekemaot sin, we ol nani ya wanwan i blong makem ol twelef laen ya blong olgeta."],[6,18,"Mo long taem ya, oli putum ol pris wetem ol Livaet long ol grup blong olgeta, blong bambae oli stap mekem ol wok blong olgeta evri dei long haos blong Hae God long Jerusalem,* olsem we tok long buk blong Moses i talem.","Mo long taem ya, oli putum ol pris wetem ol Livaet long ol grup blong olgeta, blong bambae oli stap mekem ol wok blong olgeta evri dei long haos blong Hae God long Jerusalem,* olsem we tok long buk blong Moses i talem."],[6,19,"Nao long nekis yia blong hem, long fas manis,* long namba fotin dei blong hem, olgeta oli mekem Lafet* blong Pasova.*","Nao long nekis yia blong hem, long fas manis,* long namba fotin dei blong hem, olgeta oli mekem Lafet* blong Pasova.*"],[6,20,"Be fastaem, ol pris wetem ol Livaet oli mekem olgeta oli klin long fes blong Hae God. Nao ol Livaet oli kilim ol anamol blong mekem ol sakrefaes blong Pasova. Ol sakrefaes ya oli blong olgeta, mo blong ol pris, mo blong ol narafala man ya we oli kambak.","Be fastaem, ol pris wetem ol Livaet oli mekem olgeta oli klin long fes blong Hae God. Nao ol Livaet oli kilim ol anamol blong mekem ol sakrefaes blong Pasova. Ol sakrefaes ya oli blong olgeta, mo blong ol pris, mo blong ol narafala man ya we oli kambak."],[6,21,"Olgeta we oli kam long lafet ya, i gat ol laen blong Isrel we oli aot long Babilonia oli kambak, wetem ol laen blong olgeta we oli stap nomo long Isrel mo long Juda,* be oli lego ol rabis fasin blong ol hiten man we oli stap long ples ya, oli kambak oli mekem wosip bakegen long Hae God, mo olgeta evriwan oli kakae ol mit blong sakrefaes ya.","Olgeta we oli kam long lafet ya, i gat ol laen blong Isrel we oli aot long Babilonia oli kambak, wetem ol laen blong olgeta we oli stap nomo long Isrel mo long Juda,* be oli lego ol rabis fasin blong ol hiten man we oli stap long ples ya, oli kambak oli mekem wosip bakegen long Hae God, mo olgeta evriwan oli kakae ol mit blong sakrefaes ya."],[6,22,"Mo long ol seven dei blong Lafet ya we oli Kakae Bred* we i No Gat Is long hem, olgeta oli glad tumas. Oli glad from we Hae God i mekem we king blong Pesia we narafala nem blong hem king blong Asiria, hem i glad long olgeta, i givhan long olgeta blong oli wokem haos ya blong God ya we i God blong yumi i gud bakegen.","Mo long ol seven dei blong Lafet ya we oli Kakae Bred* we i No Gat Is long hem, olgeta oli glad tumas. Oli glad from we Hae God i mekem we king blong Pesia we narafala nem blong hem king blong Asiria, hem i glad long olgeta, i givhan long olgeta blong oli wokem haos ya blong God ya we i God blong yumi i gud bakegen."],[7,1,"Nao plante yia i pas, mo long taem ya we King Ataksekses i rul long Pesia, i gat wan pris i stap we nem blong hem Esra. Hem i savegud ol olfala bubu blong hem, gogo kasem hae pris* ya Eron, we hem i fas hae pris, mo laen blong hem i olsem. Esra, papa blong hem Seraea, mo Seraea, papa blong hem Asaria, mo Asaria papa blong hem Hilkia,","Nao plante yia i pas, mo long taem ya we King Ataksekses i rul long Pesia, i gat wan pris i stap we nem blong hem Esra. Hem i savegud ol olfala bubu blong hem, gogo kasem hae pris* ya Eron, we hem i fas hae pris, mo laen blong hem i olsem. Esra, papa blong hem Seraea, mo Seraea, papa blong hem Asaria, mo Asaria papa blong hem Hilkia,"],[7,2,"mo Hilkia, papa blong hem Salum, mo Salum, papa blong hem Jadok, mo Jadok, papa blong hem Ahitub,","mo Hilkia, papa blong hem Salum, mo Salum, papa blong hem Jadok, mo Jadok, papa blong hem Ahitub,"],[7,3,"mo Ahitub, papa blong hem Amaria, mo Amaria, papa blong hem Asaria, mo Asaria, papa blong hem Meraeot,","mo Ahitub, papa blong hem Amaria, mo Amaria, papa blong hem Asaria, mo Asaria, papa blong hem Meraeot,"],[7,4,"mo Meraeot, papa blong hem Serahia, mo Serahia, papa blong hem Usi, mo Usi, papa blong hem Buki,","mo Meraeot, papa blong hem Serahia, mo Serahia, papa blong hem Usi, mo Usi, papa blong hem Buki,"],[7,5,"mo Buki, papa blong hem Abisua, mo Abisua, papa blong hem Finehas, mo Finehas, papa blong hem Eleasara, mo Eleasara, papa blong hem Eron ya we i fas hae pris, bifo olgeta.","mo Buki, papa blong hem Abisua, mo Abisua, papa blong hem Finehas, mo Finehas, papa blong hem Eleasara, mo Eleasara, papa blong hem Eron ya we i fas hae pris, bifo olgeta."],[7,6,"Pris ya Esra, hem i wan man we i skul gud, mo i savegud Loa* blong Hae God. Hae God ya, hem i God blong yumi ol laen* blong Isrel,* mo hem i bin givim Loa ya long Moses bifo. Nao long namba seven yia blong King Ataksekses, pris ya i mekemrere wan bigfala grup blong ol laen blong Isrel long Babilonia, blong i lidim olgeta oli kambak long Jerusalem.* Mo from we Hae God i stap blesem hem, olgeta samting we hem i askem long king, be king i givim long hem. Long grup ya, i gat ol pris, wetem ol Livaet* we sam oli man blong mekem kwaea long haos* blong Hae God, mo sam oli man blong gad long haos ya, mo sam oli man blong wok long haos ya.","Pris ya Esra, hem i wan man we i skul gud, mo i savegud Loa* blong Hae God. Hae God ya, hem i God blong yumi ol laen* blong Isrel,* mo hem i bin givim Loa ya long Moses bifo. Nao long namba seven yia blong King Ataksekses, pris ya i mekemrere wan bigfala grup blong ol laen blong Isrel long Babilonia, blong i lidim olgeta oli kambak long Jerusalem.* Mo from we Hae God i stap blesem hem, olgeta samting we hem i askem long king, be king i givim long hem. Long grup ya, i gat ol pris, wetem ol Livaet* we sam oli man blong mekem kwaea long haos* blong Hae God, mo sam oli man blong gad long haos ya, mo sam oli man blong wok long haos ya.",7],[7,8,"Olgeta ya oli aot long Babilonia long fas manis, long fas dei blong hem, mo Hae God i stap givhan gud long olgeta long rod, nao oli kamtru long Jerusalem long namba faef manis, long fas dei blong hem.","Olgeta ya oli aot long Babilonia long fas manis, long fas dei blong hem, mo Hae God i stap givhan gud long olgeta long rod, nao oli kamtru long Jerusalem long namba faef manis, long fas dei blong hem.",9],[7,10,"Pris ya Esra i laekem tumas ol tok blong Buk blong Loa blong Hae God, nao oltaem hem i stap stadi long hem, mo i stap mekem ol samting we buk ya i talem. Mo hem i stap tijim ol laen blong Isrel long ol loa mo ol rul we i stap long buk ya.","Pris ya Esra i laekem tumas ol tok blong Buk blong Loa blong Hae God, nao oltaem hem i stap stadi long hem, mo i stap mekem ol samting we buk ya i talem. Mo hem i stap tijim ol laen blong Isrel long ol loa mo ol rul we i stap long buk ya."],[7,11,"Pris* ya Esra, oltaem hem i stap stadi gud long ol loa mo long ol tok we Hae God i bin givim long ol laen* blong Isrel,* mo taem hem i stap yet long Babilonia, King Ataksekses i givim wan leta long hem. Leta ya i talem se,","Pris* ya Esra, oltaem hem i stap stadi gud long ol loa mo long ol tok we Hae God i bin givim long ol laen* blong Isrel,* mo taem hem i stap yet long Babilonia, King Ataksekses i givim wan leta long hem. Leta ya i talem se,"],[7,12,"“Mi, King Ataksekses we mi hae king blong Pesia, mi givim tok ya blong mi i go long yu Esra, we yu yu pris, mo oltaem yu stap stadi gud long Buk blong Loa* blong God blong heven.","“Mi, King Ataksekses we mi hae king blong Pesia, mi givim tok ya blong mi i go long yu Esra, we yu yu pris, mo oltaem yu stap stadi gud long Buk blong Loa* blong God blong heven."],[7,13,"“Naoia, mi mi talemaot se sipos eni man we i laen blong Isrel i wantem aot long eni ples long kingdom blong mi blong go wetem yu, hem i save go. Sipos hem i pris, no i Livaet,* no i wan man olbaot nomo, be bambae hem i fri blong gobak long Jerusalem.*","“Naoia, mi mi talemaot se sipos eni man we i laen blong Isrel i wantem aot long eni ples long kingdom blong mi blong go wetem yu, hem i save go. Sipos hem i pris, no i Livaet,* no i wan man olbaot nomo, be bambae hem i fri blong gobak long Jerusalem.*"],[7,14,"God blong yu i putum Buk blong Loa blong hem long han blong yu, mo mi wetem ol seven advaesa blong mi, mifala i sanem yu blong yu go long Jerusalem, mo long ol narafala ples long Juda,* blong yu faenemaot se ol man oli stap obei gud long Loa, no nogat.","God blong yu i putum Buk blong Loa blong hem long han blong yu, mo mi wetem ol seven advaesa blong mi, mifala i sanem yu blong yu go long Jerusalem, mo long ol narafala ples long Juda,* blong yu faenemaot se ol man oli stap obei gud long Loa, no nogat."],[7,15,"Bambae yu tekem ol presen blong mi mo blong ol advaesa ya blong mi, yu karem olgeta i go. Ol presen ya, i gat gol mo silva, we mifala i wantem givim long God blong yufala, we haos* blong hem i stap long Jerusalem.","Bambae yu tekem ol presen blong mi mo blong ol advaesa ya blong mi, yu karem olgeta i go. Ol presen ya, i gat gol mo silva, we mifala i wantem givim long God blong yufala, we haos* blong hem i stap long Jerusalem."],[7,16,"Mo olgeta mane we yufala i kasem long olgeta ples long provins ya Babilon, bambae yufala i putum wetem ol presen we yufala wetem ol pris blong yufala, yufala i givim se i blong haos ya blong God blong yufala, mo yufala i karem i go.","Mo olgeta mane we yufala i kasem long olgeta ples long provins ya Babilon, bambae yufala i putum wetem ol presen we yufala wetem ol pris blong yufala, yufala i givim se i blong haos ya blong God blong yufala, mo yufala i karem i go."],[7,17,"“Mane ya, yu mas yusumgud blong pem ol bul, mo ol man sipsip, mo ol smol man sipsip, mo ol kakae mo waen we i blong go wetem ol anamol ya, blong yufala i mekem ol sakrefaes long Olta blong haos blong God.","“Mane ya, yu mas yusumgud blong pem ol bul, mo ol man sipsip, mo ol smol man sipsip, mo ol kakae mo waen we i blong go wetem ol anamol ya, blong yufala i mekem ol sakrefaes long Olta blong haos blong God."],[7,18,"Mo sipos i gat ol silva mo gol we i stap yet, bambae yu wetem ol man ples blong yu, yufala i save yusum blong pem ol samting we yufala i luk se i gud mo i stret long tingting blong God blong yufala.","Mo sipos i gat ol silva mo gol we i stap yet, bambae yu wetem ol man ples blong yu, yufala i save yusum blong pem ol samting we yufala i luk se i gud mo i stret long tingting blong God blong yufala."],[7,19,"Olgeta samting ya blong mekem wosip we ol man oli bin givim long yu blong yu yusum long haos ya, bambae yu tekem olgeta, yu givim i go long God.","Olgeta samting ya blong mekem wosip we ol man oli bin givim long yu blong yu yusum long haos ya, bambae yu tekem olgeta, yu givim i go long God."],[7,20,"Mo sipos yu yu nidim sam samting bakegen blong haos ya, bambae yu save go tekem sam mane long mane blong gavman blong pem ol samting ya long hem.","Mo sipos yu yu nidim sam samting bakegen blong haos ya, bambae yu save go tekem sam mane long mane blong gavman blong pem ol samting ya long hem."],[7,21,"“Mo bakegen, mi mi talem long yufala olgeta haeman blong mi we yufala i stap lukaot long ol mane long provins ya Narasaed Yufretes Reva long Wes, se sipos pris ya Esra we i stap stadi gud long Buk blong Loa blong God blong heven, hem i kam askem sam samting long yufala, bambae yufala i mas givim long hem kwiktaem nomo.","“Mo bakegen, mi mi talem long yufala olgeta haeman blong mi we yufala i stap lukaot long ol mane long provins ya Narasaed Yufretes Reva long Wes, se sipos pris ya Esra we i stap stadi gud long Buk blong Loa blong God blong heven, hem i kam askem sam samting long yufala, bambae yufala i mas givim long hem kwiktaem nomo."],[7,22,"Mak blong ol samting we yufala i save givim long hem i olsem. Sipos hem i askem silva, yufala i save givim, go kasem tri tan fo handred kilo, mo sipos hem i askem wit,* yufala i save givim, go kasem ten tan. Sipos hem i askem waen, yufala i save givim, go kasem tu taosen lita, mo sipos hem i wantem olifoel,* yufala i save givim, go kasem tu taosen lita. Mo sol, yufala i save givim olsem we hem i wantem.","Mak blong ol samting we yufala i save givim long hem i olsem. Sipos hem i askem silva, yufala i save givim, go kasem tri tan fo handred kilo, mo sipos hem i askem wit,* yufala i save givim, go kasem ten tan. Sipos hem i askem waen, yufala i save givim, go kasem tu taosen lita, mo sipos hem i wantem olifoel,* yufala i save givim, go kasem tu taosen lita. Mo sol, yufala i save givim olsem we hem i wantem."],[7,23,"Yufala i mas lukaot gud blong givim evri samting we God blong heven i wantem blong ol man blong hem oli yusum long haos blong hem. Yufala i mas mekem olsem, blong bambae hem i no kros long mi, no long ol pikinini blong mi we bambae oli rul biaen long mi.","Yufala i mas lukaot gud blong givim evri samting we God blong heven i wantem blong ol man blong hem oli yusum long haos blong hem. Yufala i mas mekem olsem, blong bambae hem i no kros long mi, no long ol pikinini blong mi we bambae oli rul biaen long mi."],[7,24,"Mo ol pris ya wetem ol Livaet, we sam oli man blong mekem kwaea, mo sam oli man blong gad long haos ya, mo sam oli man blong wok long haos ya, mo ol narafala man ya tu we oli stap givhan long wok blong haos ya, mi mi blokem yufala se bambae yufala i no mas tekem takis long olgeta.","Mo ol pris ya wetem ol Livaet, we sam oli man blong mekem kwaea, mo sam oli man blong gad long haos ya, mo sam oli man blong wok long haos ya, mo ol narafala man ya tu we oli stap givhan long wok blong haos ya, mi mi blokem yufala se bambae yufala i no mas tekem takis long olgeta."],[7,25,"“Mo yu, Esra, yu yu gat waes we God ya blong yu i givim long yu. Long waes ya blong yu, bambae yu mas putumap ol jif mo ol jaj, blong oli lukaot long olgeta man we oli stap long provins ya Narasaed Yufretes Reva long Wes, we oli stap folem Loa blong God blong yu. Mo ol man we oli no save Loa ya, yu yu mas tijim olgeta long hem.","“Mo yu, Esra, yu yu gat waes we God ya blong yu i givim long yu. Long waes ya blong yu, bambae yu mas putumap ol jif mo ol jaj, blong oli lukaot long olgeta man we oli stap long provins ya Narasaed Yufretes Reva long Wes, we oli stap folem Loa blong God blong yu. Mo ol man we oli no save Loa ya, yu yu mas tijim olgeta long hem."],[7,26,"Mo sipos man i no obei long ol loa blong God blong yu, mo long ol loa blong kingdom ya blong mi, bambae hem i mas kasem panis kwiktaem nomo. Bambae ol man blong mi oli mas kilim hem i ded, no oli mas sanem hem i go wok slef* long narafala kantri, no oli mas tekemaot olting blong hem, no oli mas putum hem long kalabus.”","Mo sipos man i no obei long ol loa blong God blong yu, mo long ol loa blong kingdom ya blong mi, bambae hem i mas kasem panis kwiktaem nomo. Bambae ol man blong mi oli mas kilim hem i ded, no oli mas sanem hem i go wok slef* long narafala kantri, no oli mas tekemaot olting blong hem, no oli mas putum hem long kalabus.”"],[7,27,"Nao pris ya i talem se, “Olgeta. Hae God i God blong ol bubu blong yumi bifo. I gud yumi presem hem from we hem i givim gudfala tingting ya long king, nao king i ona long haos ya blong hem long Jerusalem.","Nao pris ya i talem se, “Olgeta. Hae God i God blong ol bubu blong yumi bifo. I gud yumi presem hem from we hem i givim gudfala tingting ya long king, nao king i ona long haos ya blong hem long Jerusalem."],[7,28,"Hae God i givhan long mi long gladhat blong hem, nao king ya wetem ol advaesa blong hem, mo ol haeman blong hem we oli gat paoa, olgeta oli stap glad long mi. Hae God i God blong mi, mo hem i stap leftemap tingting blong mi, nao mi mi save tekem plante man we oli hed blong ol naranarafala laen blong yumi, oli kambak wetem mi.”","Hae God i givhan long mi long gladhat blong hem, nao king ya wetem ol advaesa blong hem, mo ol haeman blong hem we oli gat paoa, olgeta oli stap glad long mi. Hae God i God blong mi, mo hem i stap leftemap tingting blong mi, nao mi mi save tekem plante man we oli hed blong ol naranarafala laen blong yumi, oli kambak wetem mi.”"],[8,1,"Nao long taem we King Ataksekses i stap rul, ol man we oli hed blong ol naranarafala laen we oli aot long Babilonia wetem pris* ya Esra, oli kambak long Jerusalem,* mo nem blong olgeta i olsem.","Nao long taem we King Ataksekses i stap rul, ol man we oli hed blong ol naranarafala laen we oli aot long Babilonia wetem pris* ya Esra, oli kambak long Jerusalem,* mo nem blong olgeta i olsem."],[8,2,"I gat Gesom, we i hed blong ol laen blong Finehas, mo Daniel, we i hed blong ol laen blong Itamara, mo Hatus, we papa blong hem Sekania. Hem i hed blong ol laen blong Deved. Mo i gat Sekaraea, we i hed blong ol laen blong Paros, mo olgeta we oli kam wetem hem, i gat wan handred fifti man. Olgeta ya, i gat nem blong ol bubu blong olgeta i stap long buk.","I gat Gesom, we i hed blong ol laen blong Finehas, mo Daniel, we i hed blong ol laen blong Itamara, mo Hatus, we papa blong hem Sekania. Hem i hed blong ol laen blong Deved. Mo i gat Sekaraea, we i hed blong ol laen blong Paros, mo olgeta we oli kam wetem hem, i gat wan handred fifti man. Olgeta ya, i gat nem blong ol bubu blong olgeta i stap long buk.",3],[8,4,"Mo i gat Eliehoenae, we papa blong hem Serahia. Hem i hed blong ol laen blong Pahatmoab, mo olgeta we oli kam wetem hem, i gat tu handred man.","Mo i gat Eliehoenae, we papa blong hem Serahia. Hem i hed blong ol laen blong Pahatmoab, mo olgeta we oli kam wetem hem, i gat tu handred man."],[8,5,"Mo i gat Sekania, we papa blong hem Jahasiel. Hem i hed blong ol laen blong Satu, mo olgeta we oli kam wetem hem, i gat tri handred man.","Mo i gat Sekania, we papa blong hem Jahasiel. Hem i hed blong ol laen blong Satu, mo olgeta we oli kam wetem hem, i gat tri handred man."],[8,6,"Mo i gat Ebed, we papa blong hem Jonatan. Hem i hed blong ol laen blong Adin, mo olgeta we oli kam wetem hem, i gat fifti man.","Mo i gat Ebed, we papa blong hem Jonatan. Hem i hed blong ol laen blong Adin, mo olgeta we oli kam wetem hem, i gat fifti man."],[8,7,"Mo i gat Jesaea, we papa blong hem Atalia. Hem i hed blong ol laen blong Elam, mo olgeta we oli kam wetem hem, i gat seventi man.","Mo i gat Jesaea, we papa blong hem Atalia. Hem i hed blong ol laen blong Elam, mo olgeta we oli kam wetem hem, i gat seventi man."],[8,8,"Mo i gat Sebadia, we papa blong hem Mikael. Hem i hed blong ol laen blong Sefatia, mo olgeta we oli kam wetem hem, i gat eiti man.","Mo i gat Sebadia, we papa blong hem Mikael. Hem i hed blong ol laen blong Sefatia, mo olgeta we oli kam wetem hem, i gat eiti man."],[8,9,"Mo i gat Obadaea, we papa blong hem Jehiel. Hem i hed blong ol laen blong Joab, mo olgeta we oli kam wetem hem, i gat tu handred eitin man.","Mo i gat Obadaea, we papa blong hem Jehiel. Hem i hed blong ol laen blong Joab, mo olgeta we oli kam wetem hem, i gat tu handred eitin man."],[8,10,"Mo i gat Selomit, we papa blong hem Josifia. Hem i hed blong ol laen blong Bani, mo olgeta we oli kam wetem hem, i gat wan handred sikisti man.","Mo i gat Selomit, we papa blong hem Josifia. Hem i hed blong ol laen blong Bani, mo olgeta we oli kam wetem hem, i gat wan handred sikisti man."],[8,11,"Mo i gat Sekaraea, we papa blong hem Bebae. Hem i hed blong ol laen blong Bebae, mo olgeta we oli kam wetem hem, i gat twanti eit man.","Mo i gat Sekaraea, we papa blong hem Bebae. Hem i hed blong ol laen blong Bebae, mo olgeta we oli kam wetem hem, i gat twanti eit man."],[8,12,"Mo i gat Johanan, we papa blong hem Hakatan. Hem i hed blong ol laen blong Asgad, mo olgeta we oli kam wetem hem, i gat wan handred ten man.","Mo i gat Johanan, we papa blong hem Hakatan. Hem i hed blong ol laen blong Asgad, mo olgeta we oli kam wetem hem, i gat wan handred ten man."],[8,13,"Mo i gat Elifelet mo Jehuel mo Semaea we trifala i hed blong ol laen blong Adonikam, mo olgeta we oli kam wetem trifala ya i gat sikisti man. Olgeta ya oli no kam wetem olgeta ya, oli jes kam biaen.","Mo i gat Elifelet mo Jehuel mo Semaea we trifala i hed blong ol laen blong Adonikam, mo olgeta we oli kam wetem trifala ya i gat sikisti man. Olgeta ya oli no kam wetem olgeta ya, oli jes kam biaen."],[8,14,"Mo i gat Utae mo Sakuru, we tufala i hed blong ol laen blong Bigvae, mo olgeta we oli kam wetem tufala, i gat seventi man.","Mo i gat Utae mo Sakuru, we tufala i hed blong ol laen blong Bigvae, mo olgeta we oli kam wetem tufala, i gat seventi man."],[8,15,"Nao taem pris* ya Esra i kamtru long Jerusalem,* hem i talemaot stori blong hem, i talem se, “Taem mifala i stap longwe yet, mi mi singaot olgeta man ya we oli wantem kam wetem mi oli kam wanples long Ahava Reva we i ron i go long taon ya Ahava, mo mifala i stap long ples ya tri dei. Nao mi luk we i gat ol pris oli stap wetem mifala, be ol Livaet,* i no gat.","Nao taem pris* ya Esra i kamtru long Jerusalem,* hem i talemaot stori blong hem, i talem se, “Taem mifala i stap longwe yet, mi mi singaot olgeta man ya we oli wantem kam wetem mi oli kam wanples long Ahava Reva we i ron i go long taon ya Ahava, mo mifala i stap long ples ya tri dei. Nao mi luk we i gat ol pris oli stap wetem mifala, be ol Livaet,* i no gat."],[8,16,"Nao mi singaot naen lida oli kam luk mi. Olgeta ya, i gat Eliesa, mo Ariel, mo Semaea, mo Elnatan, mo Jarib, mo narafala Elnatan, mo Natan, mo Sekaraea, mo Mesulam. Mo mi singaot tufala tija ya, Joearib, mo Elnatan, blong tufala tu i kam luk mi. Mo olgeta evriwan oli kam.","Nao mi singaot naen lida oli kam luk mi. Olgeta ya, i gat Eliesa, mo Ariel, mo Semaea, mo Elnatan, mo Jarib, mo narafala Elnatan, mo Natan, mo Sekaraea, mo Mesulam. Mo mi singaot tufala tija ya, Joearib, mo Elnatan, blong tufala tu i kam luk mi. Mo olgeta evriwan oli kam."],[8,17,"Ale, mi sanem olgeta oli go luk man ya Ido, we hem i hed blong ol man blong yumi we oli stap long Kasifia, blong oli askem long hem wetem ol fren blong hem we oli man blong wok long haos* blong God blong yumi, blong oli sanem sam long olgeta oli kam wetem mifala.","Ale, mi sanem olgeta oli go luk man ya Ido, we hem i hed blong ol man blong yumi we oli stap long Kasifia, blong oli askem long hem wetem ol fren blong hem we oli man blong wok long haos* blong God blong yumi, blong oli sanem sam long olgeta oli kam wetem mifala."],[8,18,"Nao from we God blong yumi i stap givhan long mifala long gladhat blong hem, olgeta oli sanem Serebia wetem eitin man, we sam oli pikinini blong hem mo sam oli brata blong hem, blong oli kam wetem mifala. Serebia ya, hem i wan man we i gat hed, mo hem i wan laen blong Mali, we bubu blong hem Livae.","Nao from we God blong yumi i stap givhan long mifala long gladhat blong hem, olgeta oli sanem Serebia wetem eitin man, we sam oli pikinini blong hem mo sam oli brata blong hem, blong oli kam wetem mifala. Serebia ya, hem i wan man we i gat hed, mo hem i wan laen blong Mali, we bubu blong hem Livae."],[8,19,"Mo oli sanem Hasabia mo Jesaea wetem twanti man long famle blong tufala, blong olgeta ya tu oli kam wetem mifala. Olgeta ya oli laen blong Merari, we papa blong hem Livae.","Mo oli sanem Hasabia mo Jesaea wetem twanti man long famle blong tufala, blong olgeta ya tu oli kam wetem mifala. Olgeta ya oli laen blong Merari, we papa blong hem Livae."],[8,20,"Mo bakegen, oli sanem tu handred twanti narafala man i kam. Olgeta ya, King Deved bifo wetem ol haeman blong hem oli bin makemaot ol bubu blong olgeta, blong oli wok wetem ol Livaet. Olgeta ya evriwan, nem blong ol bubu blong olgeta i stap long wan olfala lis.”","Mo bakegen, oli sanem tu handred twanti narafala man i kam. Olgeta ya, King Deved bifo wetem ol haeman blong hem oli bin makemaot ol bubu blong olgeta, blong oli wok wetem ol Livaet. Olgeta ya evriwan, nem blong ol bubu blong olgeta i stap long wan olfala lis.”"],[8,21,"Mo bakegen, pris* ya Esra i talem se, “Nao taem mifala i stap long ples ya, long saed blong reva ya Ahava, mi mi talem long olgeta man we oli kam wetem mi, se mifala evriwan i mas livim kakae blong kam long fes blong God we tingting blong mifala i stap daon. Mifala i askem long hem blong hem i lidim mifala long rod blong mifala, mo blong i lukaot gud long mifala, mo long ol pikinini blong mifala, mo long olting blong mifala.","Mo bakegen, pris* ya Esra i talem se, “Nao taem mifala i stap long ples ya, long saed blong reva ya Ahava, mi mi talem long olgeta man we oli kam wetem mi, se mifala evriwan i mas livim kakae blong kam long fes blong God we tingting blong mifala i stap daon. Mifala i askem long hem blong hem i lidim mifala long rod blong mifala, mo blong i lukaot gud long mifala, mo long ol pikinini blong mifala, mo long olting blong mifala."],[8,22,"Mi mekem olsem, from we mi sem blong askem long king, blong i givim ol soldia blong hem we sam oli wokbaot, mo sam oli ron long hos, blong oli gad long mifala long rod. Mi mi sem from we mi talem long hem finis se, ‘God blong mifala i stap blesem olgeta man we oli stap trastem hem, be i stap panisim olgeta we oli stap tanem baksaed long hem.’","Mi mekem olsem, from we mi sem blong askem long king, blong i givim ol soldia blong hem we sam oli wokbaot, mo sam oli ron long hos, blong oli gad long mifala long rod. Mi mi sem from we mi talem long hem finis se, ‘God blong mifala i stap blesem olgeta man we oli stap trastem hem, be i stap panisim olgeta we oli stap tanem baksaed long hem.’"],[8,23,"Nao mifala i livim kakae, mifala i prea blong God i lukaot long mifala. Mo hem i ansa long prea blong mifala.”","Nao mifala i livim kakae, mifala i prea blong God i lukaot long mifala. Mo hem i ansa long prea blong mifala.”"],[8,24,"Mo bakegen, pris* ya Esra i talem se, “Nao long ples ya, mi jusumaot twelef man long ol lida blong ol pris, mo mi jusumaot Serebia mo Hasabia wetem ten man we olgeta ya evriwan oli Livaet.*","Mo bakegen, pris* ya Esra i talem se, “Nao long ples ya, mi jusumaot twelef man long ol lida blong ol pris, mo mi jusumaot Serebia mo Hasabia wetem ten man we olgeta ya evriwan oli Livaet.*"],[8,25,"Nao mi skelem ol silva mo ol gol mo ol samting blong yusum long wosip, we king wetem ol advaesa blong hem, mo ol haeman blong hem, mo ol laen* blong Isrel* we oli stap longwe oli bin givim blong yusum long haos* blong God blong yumi. Nao mi givim ol samting ya i go long ol man ya, blong oli lukaot gud long olgeta long rod.","Nao mi skelem ol silva mo ol gol mo ol samting blong yusum long wosip, we king wetem ol advaesa blong hem, mo ol haeman blong hem, mo ol laen* blong Isrel* we oli stap longwe oli bin givim blong yusum long haos* blong God blong yumi. Nao mi givim ol samting ya i go long ol man ya, blong oli lukaot gud long olgeta long rod."],[8,26,"Ol samting we mi givim long olgeta i olsem. I gat silva, we hevi blong hem i kasem twanti tu tan, mo wan handred samting we oli wokem long silva blong yusum long wosip, we hevi blong olgeta i kasem seventi kilo, mo gol, we hevi blong hem i kasem tri tan fo handred kilo, mo twanti besin we oli wokem long gol, we hevi blong olgeta i kasem eit kilo, mo tu besin we oli wokem long bras we i beswan, we praes blong tufala wanwan i sem mak long praes blong besin we oli wokem long gol.","Ol samting we mi givim long olgeta i olsem. I gat silva, we hevi blong hem i kasem twanti tu tan, mo wan handred samting we oli wokem long silva blong yusum long wosip, we hevi blong olgeta i kasem seventi kilo, mo gol, we hevi blong hem i kasem tri tan fo handred kilo, mo twanti besin we oli wokem long gol, we hevi blong olgeta i kasem eit kilo, mo tu besin we oli wokem long bras we i beswan, we praes blong tufala wanwan i sem mak long praes blong besin we oli wokem long gol.",27],[8,28,"“Mo mi talem long olgeta se, ‘Olgeta. Hae God, hem i God blong ol bubu blong yumi bifo, mo yufala i tabu, yufala i man blong hem. Mo ol samting ya blong yusum long wosip, we oli wokem long silva mo long gol, we ol man oli givim long gladhat blong olgeta, ol samting ya tu oli tabu, oli blong hem.","“Mo mi talem long olgeta se, ‘Olgeta. Hae God, hem i God blong ol bubu blong yumi bifo, mo yufala i tabu, yufala i man blong hem. Mo ol samting ya blong yusum long wosip, we oli wokem long silva mo long gol, we ol man oli givim long gladhat blong olgeta, ol samting ya tu oli tabu, oli blong hem."],[8,29,"Yufala i mas lukaot gud long olgeta, gogo yufala i kasem haos blong hem long Jerusalem.* Mo long ples ya, long rum blong ol pris, long fes blong ol lida blong ol pris ya, wetem ol lida blong ol Livaet, wetem ol narafala lida blong yumi longwe, bambae yufala i mas skelem olgeta bakegen, nao yufala i mas givim i go long olgeta.’","Yufala i mas lukaot gud long olgeta, gogo yufala i kasem haos blong hem long Jerusalem.* Mo long ples ya, long rum blong ol pris, long fes blong ol lida blong ol pris ya, wetem ol lida blong ol Livaet, wetem ol narafala lida blong yumi longwe, bambae yufala i mas skelem olgeta bakegen, nao yufala i mas givim i go long olgeta.’"],[8,30,"Nao olgeta oli tekem ol samting ya, oli lukaot long olgeta, mo oli karem olgeta i kam long haos ya blong God blong yumi long ples ya.”","Nao olgeta oli tekem ol samting ya, oli lukaot long olgeta, mo oli karem olgeta i kam long haos ya blong God blong yumi long ples ya.”"],[8,31,"Mo bakegen, pris* ya Esra i talem se, “Nao long fas manis,* long namba twelef dei blong hem, mifala i aot long reva ya blong kam long Jerusalem.* Mo taem mifala i stap wokbaot, God blong yumi i stap wetem mifala, i stap lukaot gud long mifala, nao ol enemi blong mifala mo ol man we oli stap haed blong kilim man oli no kam mekem faet long mifala.","Mo bakegen, pris* ya Esra i talem se, “Nao long fas manis,* long namba twelef dei blong hem, mifala i aot long reva ya blong kam long Jerusalem.* Mo taem mifala i stap wokbaot, God blong yumi i stap wetem mifala, i stap lukaot gud long mifala, nao ol enemi blong mifala mo ol man we oli stap haed blong kilim man oli no kam mekem faet long mifala."],[8,32,"Nao mifala i wokbaot gogo, mifala i kamtru long Jerusalem, mo mifala i spel tri dei.","Nao mifala i wokbaot gogo, mifala i kamtru long Jerusalem, mo mifala i spel tri dei."],[8,33,"Nao long namba fo dei blong hem, mifala i go long haos* blong God, mifala i skelem ol silva, mo ol gol, mo ol narafala samting ya, nao mifala i putum olgeta samting ya long han blong pris ya Meremot, we papa blong hem Uria, mo tri narafala man blong haos ya. Trifala ya, i gat pris ya Eleasara, we papa blong hem Finehas, mo tu Livaet,* we nem blong tufala, Josabad, we papa blong hem Jesua, mo Noadia, we papa blong hem Binui.","Nao long namba fo dei blong hem, mifala i go long haos* blong God, mifala i skelem ol silva, mo ol gol, mo ol narafala samting ya, nao mifala i putum olgeta samting ya long han blong pris ya Meremot, we papa blong hem Uria, mo tri narafala man blong haos ya. Trifala ya, i gat pris ya Eleasara, we papa blong hem Finehas, mo tu Livaet,* we nem blong tufala, Josabad, we papa blong hem Jesua, mo Noadia, we papa blong hem Binui."],[8,34,"Mo olgeta samting ya evriwan we mifala i kaontem, mo mifala i skelem, olgeta oli raetemdaon nem blong olgeta wetem wet blong olgeta.","Mo olgeta samting ya evriwan we mifala i kaontem, mo mifala i skelem, olgeta oli raetemdaon nem blong olgeta wetem wet blong olgeta."],[8,35,"“Nao mifala evriwan we i kambak, mifala i tekem ol anamol blong mifala i kam blong mekem sakrefaes long God blong yumi. Mifala i tekem twelef bul blong makem ol twelef laen* blong yumi, mo naenti sikis man sipsip, mo seventi seven smol man sipsip, mo twelef man nani blong mekem sakrefaes blong tekemaot ol sin blong mifala, nao mifala i bonem olgeta blong mekem sakrefaes long hem.","“Nao mifala evriwan we i kambak, mifala i tekem ol anamol blong mifala i kam blong mekem sakrefaes long God blong yumi. Mifala i tekem twelef bul blong makem ol twelef laen* blong yumi, mo naenti sikis man sipsip, mo seventi seven smol man sipsip, mo twelef man nani blong mekem sakrefaes blong tekemaot ol sin blong mifala, nao mifala i bonem olgeta blong mekem sakrefaes long hem."],[8,36,"Mo mifala i tekem leta ya we king i givim long mifala, mifala i go givim long resedenkomisina mo ol distrikejen* mo ol haeman blong king long provins ya Narasaed Yufretes Reva long Wes, mo ol bigman ya oli stap mekem i gud long yumi, mo long haos ya blong God.”","Mo mifala i tekem leta ya we king i givim long mifala, mifala i go givim long resedenkomisina mo ol distrikejen* mo ol haeman blong king long provins ya Narasaed Yufretes Reva long Wes, mo ol bigman ya oli stap mekem i gud long yumi, mo long haos ya blong God.”"],[9,1,"Nao pris* ya Esra i gohed bakegen long stori blong hem, i talem se, “Nao biaen, taem mifala i mekem ol samting ya finis, ol lida blong yumi oli kam luk mi, mo oli talemaot long mi se, ‘Esra. Ol pris, mo ol Livaet,* mo ol narafala laen* ya blong Isrel* oli stap miks wetem ol man blong ol kantri ya raonabaot long yumi. Hemia ol man Amon, mo ol man Moab, mo ol man Ijip, mo long saed blong ol man Kenan,* hemia ol laen blong Het, mo ol laen blong Perij, mo ol laen blong Jebus, mo ol laen blong Amoro.* Ol man ya blong yumi oli stap joen wetem olgeta ya, mo oli stap mekem ol fasin we i nogud we i nogud we olgeta ya oli stap mekem.","Nao pris* ya Esra i gohed bakegen long stori blong hem, i talem se, “Nao biaen, taem mifala i mekem ol samting ya finis, ol lida blong yumi oli kam luk mi, mo oli talemaot long mi se, ‘Esra. Ol pris, mo ol Livaet,* mo ol narafala laen* ya blong Isrel* oli stap miks wetem ol man blong ol kantri ya raonabaot long yumi. Hemia ol man Amon, mo ol man Moab, mo ol man Ijip, mo long saed blong ol man Kenan,* hemia ol laen blong Het, mo ol laen blong Perij, mo ol laen blong Jebus, mo ol laen blong Amoro.* Ol man ya blong yumi oli stap joen wetem olgeta ya, mo oli stap mekem ol fasin we i nogud we i nogud we olgeta ya oli stap mekem."],[9,2,"Ol man blong yumi oli stap tekem ol dota blong ol narafala man ya i kam, blong oli mared long ol pikinini blong olgeta. Yumi ol man blong God, be sin ya i mekem we yumi no moa tabu, yumi kam doti long fes blong hem. Mo ol lida blong yumi wetem ol narafala haeman ya, olgeta ya nao oli stamba blong fasin nogud ya.’","Ol man blong yumi oli stap tekem ol dota blong ol narafala man ya i kam, blong oli mared long ol pikinini blong olgeta. Yumi ol man blong God, be sin ya i mekem we yumi no moa tabu, yumi kam doti long fes blong hem. Mo ol lida blong yumi wetem ol narafala haeman ya, olgeta ya nao oli stamba blong fasin nogud ya.’"],[9,3,"“Nao taem mi harem samting ya, tingting blong mi i foldaon olgeta, nao mi terem* klos blong mi, mi pulpulumaot hea blong mi, mo mustas blong mi, mo mi go sidaon we mi harem nogud tumas.","“Nao taem mi harem samting ya, tingting blong mi i foldaon olgeta, nao mi terem* klos blong mi, mi pulpulumaot hea blong mi, mo mustas blong mi, mo mi go sidaon we mi harem nogud tumas."],[9,4,"Mi sidaon, mi stap harem nogud gogo kasem taem blong mekem sakrefaes long sapa, mo ol man blong yumi we oli fraet from ol strong tok ya we God blong yumi i talem finis from ol sin ya we ol man ya oli mekem, oli kam hivap raon long mi.","Mi sidaon, mi stap harem nogud gogo kasem taem blong mekem sakrefaes long sapa, mo ol man blong yumi we oli fraet from ol strong tok ya we God blong yumi i talem finis from ol sin ya we ol man ya oli mekem, oli kam hivap raon long mi."],[9,5,"Nao long taem ya, mi mi stap harem nogud yet, mo mi stap werem klos ya we mi terem, be mi girap long ples ya we mi stap sidaon long hem, mi nildaon, mi leftemap han blong mi blong mi prea long God,","Nao long taem ya, mi mi stap harem nogud yet, mo mi stap werem klos ya we mi terem, be mi girap long ples ya we mi stap sidaon long hem, mi nildaon, mi leftemap han blong mi blong mi prea long God,"],[9,6,"nao mi talem se, ‘Hae God. Yu yu God blong mi. Mi mi sem tumas, mi no save kam leftemap hed blong mi long fes blong yu. Ol sin blong mifala oli plante we plante, nao mifala i harem nogud tumas from. I olsem we oli hivimap i go antap we i bitim hed blong mifala, i go kasem skae.","nao mi talem se, ‘Hae God. Yu yu God blong mi. Mi mi sem tumas, mi no save kam leftemap hed blong mi long fes blong yu. Ol sin blong mifala oli plante we plante, nao mifala i harem nogud tumas from. I olsem we oli hivimap i go antap we i bitim hed blong mifala, i go kasem skae."],[9,7,"Mifala i man blong yu, be oltaem, i stat long taem blong ol bubu blong mifala bifo, kam kasem tede, mifala i stap mekem sin tumas. Mo from ol sin blong ol bubu blong mifala bifo, yu bin letem ol bubu blong mifala wetem ol king blong olgeta, mo ol pris blong olgeta i go long han blong ol king blong ol narafala kantri. Nao olgeta ya oli kam kilim sam long olgeta oli ded, oli stilim olting blong olgeta, mo oli tekemaot olgeta i go stap wok slef* long ples blong olgeta. Yu yu mekem we ol man oli no moa ona long olgeta, oltaem oli stap lukluk nogud tumas long olgeta, mo oli stap mekem sem fasin yet long mifala, kam kasem tede.","Mifala i man blong yu, be oltaem, i stat long taem blong ol bubu blong mifala bifo, kam kasem tede, mifala i stap mekem sin tumas. Mo from ol sin blong ol bubu blong mifala bifo, yu bin letem ol bubu blong mifala wetem ol king blong olgeta, mo ol pris blong olgeta i go long han blong ol king blong ol narafala kantri. Nao olgeta ya oli kam kilim sam long olgeta oli ded, oli stilim olting blong olgeta, mo oli tekemaot olgeta i go stap wok slef* long ples blong olgeta. Yu yu mekem we ol man oli no moa ona long olgeta, oltaem oli stap lukluk nogud tumas long olgeta, mo oli stap mekem sem fasin yet long mifala, kam kasem tede."],[9,8,"“ ‘Hae God. Yu yu God blong mifala, mo naoia long smol taem ya, yu yu glad long mifala, yu letem sam long mifala i aot long laef ya we mifala i stap wok slef long hem, mifala i kam stap gud bakegen long ples ya we i tabu, i blong yu. Nating we mifala i stap wok slef yet, be yu yu givim niu laef long mifala.","“ ‘Hae God. Yu yu God blong mifala, mo naoia long smol taem ya, yu yu glad long mifala, yu letem sam long mifala i aot long laef ya we mifala i stap wok slef long hem, mifala i kam stap gud bakegen long ples ya we i tabu, i blong yu. Nating we mifala i stap wok slef yet, be yu yu givim niu laef long mifala."],[9,9,"Mifala i stap wok slef, be yu yu no lego mifala. Mo from we yu yu lavem mifala, yu mekem we ol king blong Pesia oli givhan long mifala, oli letem mifala i stap laef, blong mifala i save wokem haos* blong yu bakegen, we ol enemi blong mifala oli bin spolem. Mo yu letem mifala i stap gud long ples blong mifala long Jerusalem,* mo long ol narafala ples long Juda.*","Mifala i stap wok slef, be yu yu no lego mifala. Mo from we yu yu lavem mifala, yu mekem we ol king blong Pesia oli givhan long mifala, oli letem mifala i stap laef, blong mifala i save wokem haos* blong yu bakegen, we ol enemi blong mifala oli bin spolem. Mo yu letem mifala i stap gud long ples blong mifala long Jerusalem,* mo long ol narafala ples long Juda.*"],[9,10,"“ ‘God blong mi. Yu yu mekem i gud tumas long mifala. ?Be naoia, bambae mifala i save talem wanem? Ol profet blong yu bifo, oli man blong wok blong yu, be ol tok blong yu we yu givim long olgeta blong oli talemaot long ol bubu blong mifala, mifala i no obei long hem, mifala i brekem finis. Olgeta oli talem long ol bubu blong mifala bifo se, “Kantri ya we bambae yufala i go stap long hem, hem i no klin long fes blong God. I stat long wan en blong kantri ya, i go kasem narafala en blong hem, ol man blong hem oli mekem i fulap gud long ol rabis fasin blong olgeta we oli nogud we i nogud tumas.”","“ ‘God blong mi. Yu yu mekem i gud tumas long mifala. ?Be naoia, bambae mifala i save talem wanem? Ol profet blong yu bifo, oli man blong wok blong yu, be ol tok blong yu we yu givim long olgeta blong oli talemaot long ol bubu blong mifala, mifala i no obei long hem, mifala i brekem finis. Olgeta oli talem long ol bubu blong mifala bifo se, “Kantri ya we bambae yufala i go stap long hem, hem i no klin long fes blong God. I stat long wan en blong kantri ya, i go kasem narafala en blong hem, ol man blong hem oli mekem i fulap gud long ol rabis fasin blong olgeta we oli nogud we i nogud tumas.”",11],[9,12,"Mo ol profet ya oli talem se, “From samting ya, bambae yufala i no mas letem ol dota blong yufala oli go mared long ol pikinini blong olgeta, mo yufala i no mas tekem ol dota blong olgeta oli kam mared long ol pikinini blong yufala. Mo bambae yufala i no mas traem givhan long olgeta blong oli kam strong, we laef blong olgeta i gohed gud. Nao sipos yufala i obei long ol tok ya, bambae yufala i save kam strong, mo yufala i save harem gud long ol gudgudfala kakae blong kantri ya, mo yufala i save givim kantri ya long olgeta we bambae oli kamaot biaen long yufala, blong oli holem i blong olgeta olwe.”","Mo ol profet ya oli talem se, “From samting ya, bambae yufala i no mas letem ol dota blong yufala oli go mared long ol pikinini blong olgeta, mo yufala i no mas tekem ol dota blong olgeta oli kam mared long ol pikinini blong yufala. Mo bambae yufala i no mas traem givhan long olgeta blong oli kam strong, we laef blong olgeta i gohed gud. Nao sipos yufala i obei long ol tok ya, bambae yufala i save kam strong, mo yufala i save harem gud long ol gudgudfala kakae blong kantri ya, mo yufala i save givim kantri ya long olgeta we bambae oli kamaot biaen long yufala, blong oli holem i blong olgeta olwe.”"],[9,13,"“ ‘God blong mifala, yu yu panisim ol bubu blong mifala from ol sin blong olgeta, mo from ol fasin nogud blong olgeta, mo mifala i luksave se panis ya i smol nomo, i no kasem mak blong ol sin blong olgeta, mo yu letem olgeta oli stap laef.","“ ‘God blong mifala, yu yu panisim ol bubu blong mifala from ol sin blong olgeta, mo from ol fasin nogud blong olgeta, mo mifala i luksave se panis ya i smol nomo, i no kasem mak blong ol sin blong olgeta, mo yu letem olgeta oli stap laef."],[9,14,"From samting ya, bambae mifala i no save tanem baksaed long ol tok blong yu bakegen, blong go mared long ol man ya we oli stap mekem ol fasin we i nogud we i nogud. Sipos mifala i mekem olsem, bambae yu kros tumas long mifala, nao bambae yu kilim mifala evriwan i ded we bambae i no gat wan i stap laef.","From samting ya, bambae mifala i no save tanem baksaed long ol tok blong yu bakegen, blong go mared long ol man ya we oli stap mekem ol fasin we i nogud we i nogud. Sipos mifala i mekem olsem, bambae yu kros tumas long mifala, nao bambae yu kilim mifala evriwan i ded we bambae i no gat wan i stap laef."],[9,15,"Hae God, yu yu God blong mifala ol laen blong Isrel, mo mifala i man blong yu. Mifala i talemaot ol sin blong mifala long yu, mo from ol sin ya, i no stret nating blong mifala i kam stanap long fes blong yu, from we fasin blong yu i stret olgeta, be plis yu letem mifala i stap laef.’ ”","Hae God, yu yu God blong mifala ol laen blong Isrel, mo mifala i man blong yu. Mifala i talemaot ol sin blong mifala long yu, mo from ol sin ya, i no stret nating blong mifala i kam stanap long fes blong yu, from we fasin blong yu i stret olgeta, be plis yu letem mifala i stap laef.’ ”"],[10,1,"Nao pris* ya Esra i stap bodaon afsaed long doa blong haos* blong God, i stap prea, mo i stap krae, mo i stap talemaot ol sin blong ol laen* blong Isrel,* mo long taem ya, ol man, mo ol woman, mo ol pikinini oli kam hivap plante raon long hem, mo oli harem nogud, oli stap krae tumas.","Nao pris* ya Esra i stap bodaon afsaed long doa blong haos* blong God, i stap prea, mo i stap krae, mo i stap talemaot ol sin blong ol laen* blong Isrel,* mo long taem ya, ol man, mo ol woman, mo ol pikinini oli kam hivap plante raon long hem, mo oli harem nogud, oli stap krae tumas."],[10,2,"Nao Sekania we papa blong hem Jehiel, we i laen blong Elam, hem i talem long pris ya se, “Ol man ya blong yumi oli mekem i nogud long God blong yumi. Long fasin ya we oli tekem ol woman blong ol narafala kantri, oli tanem baksaed long hem. Be yumi ol laen blong Isrel, mo yumi bilif yet se hem bambae i save fogivim yumi, i tekemaot ol sin blong yumi.","Nao Sekania we papa blong hem Jehiel, we i laen blong Elam, hem i talem long pris ya se, “Ol man ya blong yumi oli mekem i nogud long God blong yumi. Long fasin ya we oli tekem ol woman blong ol narafala kantri, oli tanem baksaed long hem. Be yumi ol laen blong Isrel, mo yumi bilif yet se hem bambae i save fogivim yumi, i tekemaot ol sin blong yumi."],[10,3,"Naoia yumi mas mekem wan strong promes wetem hem, se ol man we oli tekem ol woman ya oli mas lego olgeta, wetem ol pikinini blong olgeta, oli mas sanem olgeta oli gobak long ples blong olgeta. Bambae mifala i mekem ol samting we yu wetem ol narafala man we i stap tinghevi long ol tok blong God, yufala i talem long mifala. Bambae yumi mas mekem ol samting we Loa* blong God i talem.","Naoia yumi mas mekem wan strong promes wetem hem, se ol man we oli tekem ol woman ya oli mas lego olgeta, wetem ol pikinini blong olgeta, oli mas sanem olgeta oli gobak long ples blong olgeta. Bambae mifala i mekem ol samting we yu wetem ol narafala man we i stap tinghevi long ol tok blong God, yufala i talem long mifala. Bambae yumi mas mekem ol samting we Loa* blong God i talem."],[10,4,"Wok blong stretem trabol ya i stap long han blong yu. Yu gohed, yu stretem. Bambae mifala i sapotem yu.”","Wok blong stretem trabol ya i stap long han blong yu. Yu gohed, yu stretem. Bambae mifala i sapotem yu.”"],[10,5,"Nao, pris ya Esra i girap, i mekem we ol lida blong ol pris, mo ol lida blong ol Livaet,* mo ol narafala lida blong olgeta oli mekem promes blong mekem olsem we man ya i talem.","Nao, pris ya Esra i girap, i mekem we ol lida blong ol pris, mo ol lida blong ol Livaet,* mo ol narafala lida blong olgeta oli mekem promes blong mekem olsem we man ya i talem."],[10,6,"Nao pris ya i aot long ples ya afsaed long doa blong haos blong God, i go long rum blong Jehohanan, we papa blong hem Eliasib. Nao long naet ya, hem i stap long ples ya, i stap harem nogud from we God i tekem ol man ya oli kambak, be olgeta oli tanem baksaed long hem. Nao long naet ya, hem i no kakae mo i no dring wan samting.","Nao pris ya i aot long ples ya afsaed long doa blong haos blong God, i go long rum blong Jehohanan, we papa blong hem Eliasib. Nao long naet ya, hem i stap long ples ya, i stap harem nogud from we God i tekem ol man ya oli kambak, be olgeta oli tanem baksaed long hem. Nao long naet ya, hem i no kakae mo i no dring wan samting."],[10,7,"Nao ol lida ya oli sanem tok i go long olgeta ples long Jerusalem* mo long ol narafala ples long Juda,* se olgeta man we oli aot long Babilonia oli kambak, oli mas kam long wan miting long Jerusalem.","Nao ol lida ya oli sanem tok i go long olgeta ples long Jerusalem* mo long ol narafala ples long Juda,* se olgeta man we oli aot long Babilonia oli kambak, oli mas kam long wan miting long Jerusalem."],[10,8,"Olgeta oli putum tri dei blong ol man oli save wokbaot blong kam long miting ya, mo oli talem se sipos man i no kam long taem ya, bambae ol lida oli tekemaot olting we hem i gat, mo bambae oli no moa save kaontem hem se i wan laen blong Isrel.","Olgeta oli putum tri dei blong ol man oli save wokbaot blong kam long miting ya, mo oli talem se sipos man i no kam long taem ya, bambae ol lida oli tekemaot olting we hem i gat, mo bambae oli no moa save kaontem hem se i wan laen blong Isrel."],[10,9,"Nao long tri dei ya, olgeta man we oli stap long tufala distrik ya Juda mo Benjamin* oli stap kamkamtru long Jerusalem. Mo long namba tri dei blong hem, we hemia namba naen manis, long namba twanti dei blong hem, oli kam wanples blong holem miting long bigfala open ples long yad blong haos blong God. Long taem ya i gat bigfala ren, mo ol man oli stap seksek from ren ya, mo from bigfala miting ya.","Nao long tri dei ya, olgeta man we oli stap long tufala distrik ya Juda mo Benjamin* oli stap kamkamtru long Jerusalem. Mo long namba tri dei blong hem, we hemia namba naen manis, long namba twanti dei blong hem, oli kam wanples blong holem miting long bigfala open ples long yad blong haos blong God. Long taem ya i gat bigfala ren, mo ol man oli stap seksek from ren ya, mo from bigfala miting ya."],[10,10,"Nao pris ya Esra i stanap, i tok long olgeta, i talem se, “!Olgeta! Yufala we i tekem ol woman blong ol narafala kantri, yufala i brekem tok blong Hae God ya. Fasin ya i mekem we laef blong yumi i no stret nating long fes blong hem.","Nao pris ya Esra i stanap, i tok long olgeta, i talem se, “!Olgeta! Yufala we i tekem ol woman blong ol narafala kantri, yufala i brekem tok blong Hae God ya. Fasin ya i mekem we laef blong yumi i no stret nating long fes blong hem."],[10,11,"From samting ya, yufala i mas talemaot ol sin blong yufala long hem. Hem i God blong ol bubu blong yumi bifo, mo yufala i mas mekem ol samting we hem i wantem. Bambae yufala i no moa go joen wetem ol man blong ol narafala kantri we oli stap long ples blong yumi, yufala i mas lego olgeta. Mo yufala we i mared long ol hiten woman ya, yufala i mas lego olgeta.”","From samting ya, yufala i mas talemaot ol sin blong yufala long hem. Hem i God blong ol bubu blong yumi bifo, mo yufala i mas mekem ol samting we hem i wantem. Bambae yufala i no moa go joen wetem ol man blong ol narafala kantri we oli stap long ples blong yumi, yufala i mas lego olgeta. Mo yufala we i mared long ol hiten woman ya, yufala i mas lego olgeta.”"],[10,12,"Nao olgeta man ya oli singsingaot bigwan, oli talem se, “!I gud nomo! !Ol samting ya we yu yu talem, bambae mifala i mekem!”","Nao olgeta man ya oli singsingaot bigwan, oli talem se, “!I gud nomo! !Ol samting ya we yu yu talem, bambae mifala i mekem!”"],[10,13,"Mo oli gohed, oli talem se, “Be naoia bigfala ren ya, mo i gat plante man tumas long ples ya. Mifala i no save gohed blong stanap long open ples ya long bigfala ren olsem. Mo trabol ya, yumi no save stretem long wan dei no tu dei nomo, from we mifala plante i mekem sin ya.","Mo oli gohed, oli talem se, “Be naoia bigfala ren ya, mo i gat plante man tumas long ples ya. Mifala i no save gohed blong stanap long open ples ya long bigfala ren olsem. Mo trabol ya, yumi no save stretem long wan dei no tu dei nomo, from we mifala plante i mekem sin ya."],[10,14,"I gud ol haeman blong yumi nomo oli stap long Jerusalem, oli lukluk long trabol ya. Mo man we i tekem woman blong narafala kantri, bambae i tekem ol lida mo ol jaj blong taon blong hem oli kam long taem we yufala i putum, nao bambae oli fiksimap trabol blong hem. Long fasin ya, bambae God i no moa save kros long yumi from trabol ya, nao bambae i no panisim yumi.”","I gud ol haeman blong yumi nomo oli stap long Jerusalem, oli lukluk long trabol ya. Mo man we i tekem woman blong narafala kantri, bambae i tekem ol lida mo ol jaj blong taon blong hem oli kam long taem we yufala i putum, nao bambae oli fiksimap trabol blong hem. Long fasin ya, bambae God i no moa save kros long yumi from trabol ya, nao bambae i no panisim yumi.”"],[10,15,"Nao olgeta oli agri long tok ya. Be Jonatan we papa blong hem Asahel, mo Jasea we papa blong hem Tikvaha, tufala nomo i no agri long hem. Mo Mesulam wetem Sabetae we i wan Livaet, tufala ya tu i sapotem tufala ya.","Nao olgeta oli agri long tok ya. Be Jonatan we papa blong hem Asahel, mo Jasea we papa blong hem Tikvaha, tufala nomo i no agri long hem. Mo Mesulam wetem Sabetae we i wan Livaet, tufala ya tu i sapotem tufala ya."],[10,16,"Nao olgeta man ya oli agri blong mekem olsem we ol lida ya oli talem, mo pris ya Esra i jusumaot ol hed blong ol famle blong olgeta, mo i raetemdaon nem blong olgeta. Nao long namba ten manis, long fas dei blong hem, oli mekem miting, mo oli stat blong lukluk long problem blong ol mared ya.","Nao olgeta man ya oli agri blong mekem olsem we ol lida ya oli talem, mo pris ya Esra i jusumaot ol hed blong ol famle blong olgeta, mo i raetemdaon nem blong olgeta. Nao long namba ten manis, long fas dei blong hem, oli mekem miting, mo oli stat blong lukluk long problem blong ol mared ya."],[10,17,"Mo long tri manis nomo, long niuyia, long fas manis, long fas dei blong hem, oli finisim wok ya. Olgeta oli luklukgud long ol problem blong ol mared blong ol man ya we oli tekem woman blong narafala kantri.","Mo long tri manis nomo, long niuyia, long fas manis, long fas dei blong hem, oli finisim wok ya. Olgeta oli luklukgud long ol problem blong ol mared blong ol man ya we oli tekem woman blong narafala kantri."],[10,18,"Nao ol man we oli tekem ol woman blong narafala kantri, nem blong olgeta i olsem. Long ol pris, i gat Mahasea, mo Eliesa, mo Jarib, mo Gedalia. Olgeta ya oli laen* blong Hae Pris* ya Josua we papa blong hem Jehosadak.","Nao ol man we oli tekem ol woman blong narafala kantri, nem blong olgeta i olsem. Long ol pris, i gat Mahasea, mo Eliesa, mo Jarib, mo Gedalia. Olgeta ya oli laen* blong Hae Pris* ya Josua we papa blong hem Jehosadak."],[10,19,"Olgeta oli promes blong lego ol woman ya blong olgeta, mo from ol sin ya blong olgeta, oli tekem wan man sipsip, oli mekem sakrefaes long God.","Olgeta oli promes blong lego ol woman ya blong olgeta, mo from ol sin ya blong olgeta, oli tekem wan man sipsip, oli mekem sakrefaes long God."],[10,20,"Mo i gat Hanani mo Sebadia we tufala i laen blong Hime.","Mo i gat Hanani mo Sebadia we tufala i laen blong Hime."],[10,21,"Mo i gat Mahasea, mo Elaeja, mo Semaea, mo Jehiel, mo Usia, we oli laen blong Harim.","Mo i gat Mahasea, mo Elaeja, mo Semaea, mo Jehiel, mo Usia, we oli laen blong Harim."],[10,22,"Mo i gat Elioenae, mo Mahasea, mo Ismael, mo Netanel, mo Josabad, mo Elasa, we oli laen blong Pasuru.","Mo i gat Elioenae, mo Mahasea, mo Ismael, mo Netanel, mo Josabad, mo Elasa, we oli laen blong Pasuru."],[10,23,"Long ol Livaet,* i gat Josabad, mo Simei, mo Petahia, mo Juda, mo Eliesa, mo Kelaea we narafala nem blong hem Kelita.","Long ol Livaet,* i gat Josabad, mo Simei, mo Petahia, mo Juda, mo Eliesa, mo Kelaea we narafala nem blong hem Kelita."],[10,24,"Mo i gat Eliasib we i man blong mekem kwaea long haos* blong God. Mo i gat Salum, mo Telem, mo Uri, we oli man blong gad long haos blong God.","Mo i gat Eliasib we i man blong mekem kwaea long haos* blong God. Mo i gat Salum, mo Telem, mo Uri, we oli man blong gad long haos blong God."],[10,25,"Mo long ol narafala laen blong Isrel,* i gat Ramia, mo Jisia, mo Malkia, mo Miamin, mo Eleasara, mo Malkia, mo Benaea, we oli laen blong Paros.","Mo long ol narafala laen blong Isrel,* i gat Ramia, mo Jisia, mo Malkia, mo Miamin, mo Eleasara, mo Malkia, mo Benaea, we oli laen blong Paros."],[10,26,"Mo i gat Matania, mo Sekaraea, mo Jehiel, mo Abdi, mo Jeremot, mo Elaeja, we oli laen blong Elam.","Mo i gat Matania, mo Sekaraea, mo Jehiel, mo Abdi, mo Jeremot, mo Elaeja, we oli laen blong Elam."],[10,27,"Mo i gat Elioenae, mo Eliasib, mo Matania, mo Jeremot, mo Sabad, mo Asisa, we oli laen blong Satu.","Mo i gat Elioenae, mo Eliasib, mo Matania, mo Jeremot, mo Sabad, mo Asisa, we oli laen blong Satu."],[10,28,"Mo i gat Jehohanan, mo Hanania, mo Sabae, mo Atlae, we oli laen blong Bebae.","Mo i gat Jehohanan, mo Hanania, mo Sabae, mo Atlae, we oli laen blong Bebae."],[10,29,"Mo i gat Mesulam, mo Maluk, mo Adaea, mo Jasub, mo Seal, mo Jeremot, we oli laen blong Bani.","Mo i gat Mesulam, mo Maluk, mo Adaea, mo Jasub, mo Seal, mo Jeremot, we oli laen blong Bani."],[10,30,"Mo i gat Adnaha, mo Kelal, mo Benaea, mo Mahasea, mo Matania, mo Bejalehel, mo Binui, mo Manase, we oli laen blong Pahatmoab.","Mo i gat Adnaha, mo Kelal, mo Benaea, mo Mahasea, mo Matania, mo Bejalehel, mo Binui, mo Manase, we oli laen blong Pahatmoab."],[10,31,"Mo i gat Eliesa, mo Jisia, mo Malkia, mo Semaea, mo Simeon, mo Benjamin, mo Maluk, mo Semaria, we oli laen blong Harim.","Mo i gat Eliesa, mo Jisia, mo Malkia, mo Semaea, mo Simeon, mo Benjamin, mo Maluk, mo Semaria, we oli laen blong Harim.",32],[10,33,"Mo i gat Matenae, mo Matataha, mo Sabad, mo Elifelet, mo Jeremae, mo Manase, mo Simei, we oli laen blong Hasum.","Mo i gat Matenae, mo Matataha, mo Sabad, mo Elifelet, mo Jeremae, mo Manase, mo Simei, we oli laen blong Hasum."],[10,34,"Mo i gat Mahadae, mo Amram, mo Huel, mo Benaea, mo Bedea, mo Keluhi, mo Vania, mo Meremot, mo Eliasib, mo Matania, mo Matenae, mo Jahasao, we oli laen blong Bani.","Mo i gat Mahadae, mo Amram, mo Huel, mo Benaea, mo Bedea, mo Keluhi, mo Vania, mo Meremot, mo Eliasib, mo Matania, mo Matenae, mo Jahasao, we oli laen blong Bani.",37],[10,38,"Mo i gat Simei, mo Selemia, mo Natan, mo Adaea, mo Maknadebae, mo Sasae, mo Sarae, mo Asarel, mo Selemia, mo Semaria, mo Salum, mo Amaria, mo Josef, we oli laen blong Binui.","Mo i gat Simei, mo Selemia, mo Natan, mo Adaea, mo Maknadebae, mo Sasae, mo Sarae, mo Asarel, mo Selemia, mo Semaria, mo Salum, mo Amaria, mo Josef, we oli laen blong Binui.",42],[10,43,"Mo i gat Jehiel, mo Matitia, mo Sabad, mo Sebinaha, mo Jadae, mo Joel, mo Benaea, we oli laen blong Neboho.","Mo i gat Jehiel, mo Matitia, mo Sabad, mo Sebinaha, mo Jadae, mo Joel, mo Benaea, we oli laen blong Neboho."],[10,44,"Olgeta man ya evriwan oli mared long woman blong narafala kantri, mo oli lego ol woman ya, oli sanem olgeta wetem ol pikinini blong olgeta oli gobak long ples blong olgeta.","Olgeta man ya evriwan oli mared long woman blong narafala kantri, mo oli lego ol woman ya, oli sanem olgeta wetem ol pikinini blong olgeta oli gobak long ples blong olgeta."]]}};